    {
        key = "a_fairy_tale_i_growing_pains", name = "A Fairy Tale I - Growing Pains", wiki = "A Fairy Tale I - Growing Pains/Quick guide",
        required = { "Dramen or lunar staff", "Secateurs (tool belt will not work, can be obtained during the quest from Vanessa near Dantaera)", "Three or four random items assigned individually for each player" },
        recommended = { "Activated Ardougne, Catherby, Canifis, Draynor, Falador, Varrock and Yanille lodestone", "Explorer's ring 3 or 4", "Cosmic altar teleports", "Druid pouches (to avoid getting hurt by the ghasts in the Mort Myre Swamp)", "Skills necklace (faster teleport to Dark Wizards' Tower and Malignius Mortifer)" },
        sections = {
            {
                title = "G.A.G", needed = {},
                steps = {
                    {
                        text = "Talk to Martin the Master Gardener in Draynor Village.",
                        chat = "2 General Chat / 1 Anything I can help with? / Accept / 1 Now that I think about it, you're right!",
                        npcs = { "Martin the Master Gardener", "Draynor Village" },
                    },
                    {
                        text = "Talk to 5 different gardeners near farming patches around RuneScape. Easy options include:",
                        npcs = { "Group of Advanced Gardeners" },
                        subs = {
                            { text = "Frizzy, on the other side of the wall, just west of Martin.", chat = "2 Are you a member of the Group of Advanced Gardeners?" },
                            { text = "Elstan, to the north of Frizzy.", chat = "2 Are you a member of the Group of Advanced Gardeners?" },
                            { text = "If Garden of Tranquillity has been started.", chat = "1 Fairy Tale Part I - Growing Pains" },
                            { text = "Alain, north of Taverley lodestone.", chat = "2 Are you a member of the Group of Advanced Gardeners?" },
                            { text = "Dantaera, north-west of Catherby lodestone.", chat = "2 Are you a member of the Group of Advanced Gardeners?" },
                            { text = "If Garden of Tranquillity has been started.", chat = "1 Fairy Tale Part I - Growing Pains" },
                            { text = "If you do not have secateurs yet, buy them from Vanessa's Farming Shop just to the south." },
                            { text = "Ellena, east of the Catherby lodestone, beside the fruit tree patch on the beach.", chat = "2 Are you a member of the Group of Advanced Gardeners?" },
                        },
                    },
                    {
                        text = "Note that:",
                        npcs = {},
                        subs = {
                            { text = "Spirit Tree Patch gardeners all count as the same gardener." },
                            { text = "The gardeners in Prifddinas won't work." },
                            { text = "The zombie farmer does not work." },
                            { text = "Head Farmer Jones in Taverley won't work." },
                            { text = "Wyson the gardener in Falador won't work." },
                            { text = "Demetrius in Wendlewick won't work." },
                        },
                    },
                    {
                        text = "The fifth gardener you talk to will mention fairies.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Martin again.",
                        chat = "2 Talk about farming problems.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finding a cure", needed = { "Dramen staff, secateurs" },
                steps = {
                    {
                        text = "Equip your dramen staff or lunar staff and head to the Lumbridge Swamp to enter the Lost City shed.",
                        npcs = { "dramen staff", "lunar staff", "Lumbridge Swamp", "Lost City" },
                    },
                    {
                        text = "Run south and talk to the Fairy Godfather (near Chaeldar, the Slayer master) about the Queen. Make sure to finish the whole dialogue.",
                        chat = "2 Where's the Fairy Queen?",
                        npcs = { "Fairy Godfather", "Chaeldar" },
                    },
                    {
                        text = "Run west to the bank, then go north a few steps and talk to Fairy Nuff.",
                        npcs = { "Fairy Nuff" },
                    },
                    {
                        text = "Travel to the Dark Wizards' Tower, west of Falador (use the skills necklace teleport to Crafting Guild or teleport to Port Sarim lodestone, and then run north-west).",
                        npcs = { "Dark Wizards' Tower", "Falador", "skills necklace", "Crafting Guild", "Port Sarim lodestone" },
                    },
                    {
                        text = "Climb to the top, talk to Zandar Horfyre.",
                        npcs = { "Zandar Horfyre" },
                        subs = {
                            { text = "Player with low combat level should be aware of the aggressive dark wizards inside the tower." },
                        },
                    },
                    {
                        text = "Teleport to Port Sarim and talk to Malignius Mortifer about a Tanglefoot. or if Swan Song has been completed.",
                        chat = "2 I need help with fighting a Tanglefoot. / 1 I need help with fighting a Tanglefoot.",
                        npcs = { "Port Sarim", "Malignius Mortifer", "Swan Song" },
                        tile = { x = 3001, y = 3267, plane = 0 },
                        subs = {
                            { text = "Talking to Malignius at the Um ritual site will not work." },
                        },
                    },
                    {
                        text = "Head back to Draynor Village and enter the gates of Draynor Manor.",
                        npcs = {},
                    },
                    {
                        text = "Dig the gravestone inside the fence, north of the manor, west of the gallows. It resembles a celtic cross.",
                        npcs = { "Gravestone (A Fairy Tale I - Growing Pains)" },
                    },
                    {
                        text = "Return to Malignius. or if Swan Song has been started.",
                        chat = "2 I was asking you about fighting a Tanglefoot... / 1 I was asking you about fighting a Tanglefoot...",
                        npcs = { "Swan Song" },
                    },
                    {
                        text = "Fetch the items that Malignius requested (they will be listed in your quest journal), then make your way to the Nature Spirit.",
                        npcs = {},
                        subs = {
                            { text = "Make sure to bring extra of any requested food items or bring a filled druid pouch to ward off ghasts." },
                            { text = "Make sure to clean any requested herbs." },
                        },
                    },
                },
            },
            {
                title = "Magic secateurs", needed = { "Secateurs, and requested items." },
                steps = {
                    {
                        text = "Talk to the Nature Spirit in Mort Myre Swamp to receive magic secateurs.",
                        npcs = { "Filliman Tarlock", "Mort Myre Swamp", "magic secateurs" },
                    },
                },
            },
            {
                title = "The final fight", needed = { "Dramen staff, Magic secateurs" },
                steps = {
                    {
                        text = "Return to Zanaris, then enter the shady grove (dungeon icon) west of the cosmic altar.",
                        npcs = { "Zanaris", "shady grove", "cosmic altar" },
                        subs = {
                            { text = "You can use a cosmic altar teleport to teleport to the cosmic altar." },
                        },
                    },
                    {
                        text = "Run south around the bend then north to the opening with the Tanglefoot.",
                        npcs = {},
                    },
                    {
                        text = "Equip your magic secateurs and kill Tanglefoot.",
                        npcs = { "magic secateurs", "Tanglefoot" },
                        subs = {
                            { text = "Off-hand weaponry will work here, but will only deal as much as the secateurs would." },
                        },
                    },
                    {
                        text = "Take the Queen's secateurs (area loot will not work).",
                        npcs = { "Queen's secateurs" },
                    },
                    {
                        text = "Talk to the Fairy Godfather, Next to the Slayer Master icon.",
                        npcs = { "Fairy Godfather" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "A Fairy Tale I - Growing Pains",
                        npcs = { "A Fairy Tale I - Growing Pains (achievement)" },
                    },
                },
            },
        },
    },
    {
        key = "a_fairy_tale_ii_cure_a_queen", name = "A Fairy Tale II - Cure a Queen", wiki = "A Fairy Tale II - Cure a Queen/Quick guide",
        required = { "Dramen staff/Lunar staff", "A vial of water" },
        recommended = { "Combat gear and good food", "Cosmic altar teleport" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to Martin the Master Gardener in the Draynor Market.",
                        chat = "2 Talk about farming problems and fairies. / Accept",
                        npcs = { "Martin the Master Gardener", "Draynor Market" },
                    },
                    {
                        text = "After around 5-6 minutes have elapsed, talk to him again.",
                        chat = "2 I suppose I'd better go and see what the problem is, then.",
                        npcs = {},
                    },
                    {
                        text = "Go to Fairy Nuff's house, north of the Zanaris bank, and wait for a cutscene to play.",
                        npcs = { "Fairy Nuff", "Zanaris bank" },
                    },
                    {
                        text = "Enter the house and take Nuff's healing certificate from the floor in the south-east corner. Keep this in your inventory throughout the quest.",
                        npcs = { "healing certificate" },
                    },
                    {
                        text = "Right-click Study Nuff's certificate (using Read will not allow you to reach the Fairy Resistance HQ).",
                        npcs = { "Nuff's certificate" },
                    },
                    {
                        text = "Head south and read the rune temple sign, on the ground south of the cosmic altar.",
                        npcs = { "cosmic altar" },
                    },
                    {
                        text = "Talk to the Fairy Godfather (located in the Throne Room) about the Queen's disappearance.",
                        chat = "1 Where is the Fairy Queen? / 1 Do you have any idea who could have done this? / 1 Yes, okay.",
                        npcs = { "Fairy Godfather" },
                    },
                },
            },
            {
                title = "Resistance hideout", needed = { "Dramen staff or lunar staff, Nuff's certificate" },
                steps = {
                    {
                        text = "Make sure you have Nuff's certificate in your inventory. It can be retrieved from her house by searching on the western potion shelves if lost.",
                        npcs = {},
                    },
                    {
                        text = "Equip your dramen or lunar staff, click on the fairy ring, and teleport to the following codes (in this order):",
                        npcs = {},
                        subs = {
                            { text = "AIR" },
                            { text = "DLR" },
                            { text = "DJQ (Dialling this will appear to fail and take you back to Zanaris; continue regardless.)" },
                            { text = "AJS" },
                        },
                    },
                    {
                        text = "In the Fairy Resistance Hideout, talk to Fairy Nuff in the northeastern clearing.",
                        npcs = { "Fairy Resistance Hideout" },
                    },
                    {
                        text = "Return to Zanaris and pickpocket the Fairy Godfather for the queen's secateurs (may take several attempts). The Fairy Godfather, Fat Rocco and Slim Louie need to be looking away from you when you pickpocket.",
                        npcs = { "Queen's secateurs (A Fairy Tale II)", "Fat Rocco", "Slim Louie" },
                    },
                    {
                        text = "Return to the Resistance Hideout by selecting the \"Fairy Resistance HQ\" option in the Fairy Ring. Nuff's certificate must be in your inventory.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Fairy Nuff.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Magic essence", needed = { "Vial of water, Nuff's certificate" },
                steps = {
                    {
                        text = "Travel to the Cosmic Entity plane using CKP.",
                        npcs = { "Cosmic Entity plane" },
                    },
                    {
                        text = "Wait for a starflower to spawn (may take 1-2 minutes).",
                        npcs = { "Starflower (scenery)" },
                    },
                    {
                        text = "Pick the star flower and use it on a vial of water.",
                        npcs = {},
                    },
                    {
                        text = "Ensure you have equipment required to fight at least one gorak, then travel to the Gorak Plane using DIR.",
                        npcs = { "gorak", "Gorak Plane" },
                    },
                    {
                        text = "Kill Goraks until you receive gorak claws.",
                        npcs = { "gorak claws" },
                    },
                    {
                        text = "Grind the Gorak claws, then use the resulting gorak claw powder on the magic essence (unfinished).",
                        npcs = { "gorak claw powder", "magic essence (unfinished)" },
                    },
                    {
                        text = "Return to the Resistance Hideout by first teleporting back to Zanaris by choosing \"Use Fairy ring\" and then clicking the Fairy Resistance HQ as a teleport destination.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Fairy Nuff.",
                        npcs = {},
                    },
                    {
                        text = "Right-click use the magic essence (3) on the Fairy Queen. She is laying on the stretcher near Fairy Nuff, not as an interactable NPC.",
                        npcs = { "magic essence (3)" },
                    },
                    {
                        text = "Finish dialogue with the Fairy Queen.",
                        npcs = { "Fairy Queen" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
