    {
        key = "a_fairy_tale_iii_battle_at_ork_s_rift", name = "A Fairy Tale III - Battle at Ork's Rift", wiki = "A Fairy Tale III - Battle at Ork's Rift/Quick guide",
        required = { "Nuff's certificate (if dropped, another can be found in Fairy Nuff's grotto)", "Bucket of milk (in Zanaris a bucket spawns just west of the mill and there is a dairy cow just east of the wheat field)", "Dramen staff or Lunar staff", "Secateurs (can be obtained during the quest; Magic secateurs will not work; tool belt will not work)", "Hammer (can be obtained during the quest; tool belt will not work)" },
        recommended = { "Level 37 Prayer for Protect from Magic", "1-3 Prayer potions", "Potions that improve your combat abilities", "Good weapon and armour (Dragon equipment or better)", "Some food, beltfish or better", "8 Willow logs (Level 85 Firemaking required for this optional step)", "4 regular planks and 8 nails of any kind to repair one side of the bridge to Mos Le'Harmless via K'Chunk's island" },
        sections = {
            {
                title = "Starting out", needed = { "Nuff's certificate, Dramen staff or the Lunar staff" },
                steps = {
                    {
                        text = "Use any fairy ring to travel to Zanaris. If you can start the quest, you will be redirected to the Sparse Plane.",
                        npcs = { "fairy ring", "Zanaris" },
                        subs = {
                            { text = "If you cannot start the quest, enter and leave Zanaris via fairy rings repeatedly until Fairy Very Wise appears and talks to you. It may require up to 30 minutes after completing A Fairy Tale II - Cure a Queen. If you've declined her before, you have to travel by fairy ring BIR to reach her." },
                        },
                    },
                    {
                        text = "Talk to Fairy Very Wise and accept her offer. After accepting her offer, Nuff's certificate is no longer needed to reach the Fairy Resistance headquarters.",
                        chat = "4 Of course I'll help. What do I need to do?",
                        npcs = {},
                    },
                    {
                        text = "Accept the teleport from her, or use the fairy ring to get to the Fairy Resistance headquarters (AIR, DLR, DJQ, AJS).",
                        chat = "1 Please teleport me there right away!",
                        npcs = { "Fairy Resistance Hideout" },
                    },
                    {
                        text = "Talk to the Fairy Queen south-east in the headquarters and then finish talking to the Tooth Fairy (she automatically speaks to you after you speak with the queen).",
                        chat = "2 Yes, I'll help. / Accept",
                        npcs = { "Fairy Queen", "Tooth Fairy" },
                    },
                    {
                        text = "Be wary of cutscenes that may trigger epilepsy. Talk to the Tooth Fairy, then turn on the projector to watch the first briefing.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Tooth Fairy again after the briefing.",
                        chat = "5 Right, I understand about fairy tooth magic now. / 1 Yes, I'm ready.",
                        npcs = {},
                    },
                    {
                        text = "Turn on the projector to watch the second briefing.",
                        npcs = {},
                    },
                    {
                        text = "End of cutscenes.",
                        npcs = {},
                    },
                    {
                        text = "After both briefings, agree to collect her wand.",
                        chat = "3 Yes, I'll go and collect your wand.",
                        npcs = {},
                    },
                    {
                        text = "Run north-west and take a hammer and secateurs from on top of the crates. You may use area loot. Use them on each other to create a tooth extractor.",
                        npcs = { "hammer", "secateurs" },
                    },
                    {
                        text = "Leave through the fairy ring.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Gnarly", needed = { "Bucket of milk and tooth extractor" },
                steps = {
                    {
                        text = "Go to the house north-west of Zanaris bank. Use your tooth extractor on the door to pick the lock on it.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Gnarly.",
                        chat = "4 Can I do something for you...in return for the wand?",
                        npcs = { "Gnarly" },
                    },
                    {
                        text = "In no particular order, compliment him with the following responses (Only 3 compliments may be needed to continue to the next part):",
                        npcs = {},
                        subs = {
                            { text = "\"Your enamel shimmers like a river of silver in the moonlight.\"" },
                            { text = "\"I've never seen such amazing, inspired and dream-like toothiness.\"" },
                            { text = "\"I can see your bicuspid ancestry is an example to all molar-kind.\"" },
                            { text = "\"You're a wonderful guard tooth with lovely cusps.\"" },
                        },
                    },
                    {
                        text = "Use the bucket of milk on him. Gnarly should jump into your inventory.",
                        chat = "2 Okay, I'll close my eyes. / 2 Okay, okay! Keep your enamel on, I'll pick you up.",
                        npcs = { "Gnarly (item)" },
                    },
                    {
                        text = "Use the fairy rings to go back to the Fairy Resistance HQ.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Tooth Fairy in the south-east room, then turn on the projector.",
                        npcs = {},
                    },
                    {
                        text = "After the briefing, agree to the tooth extraction.",
                        chat = "2 Yes, I understand all of that. / 2 Yes, I accept. / 3 Pain? Bring it on! Replace my tooth. / 4 Okay, thanks.",
                        npcs = {},
                    },
                    {
                        text = "Step onto the yellow flowers and use the wave emote. There will be a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Leave through the fairy ring.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Bre'egth's Tooth", needed = { "Dramen staff or Lunar staff" },
                steps = {
                    {
                        text = "Talk to General Bre'egth outside of the Zanaris mill, northwest of the fairy ring.",
                        chat = "3 What's wrong with your mouth?",
                        npcs = { "General Bre'egth" },
                    },
                    {
                        text = "Talk to any other Ork about K'Chunk.",
                        chat = "4 Do you know anything about K'Chunk?",
                        npcs = { "K'Chunk" },
                    },
                    {
                        text = "Run to the fairy ring, talk to Fairy Fixit about K'Chunk.",
                        chat = "2 What do you know about K'Chunk?",
                        npcs = { "Fairy Fixit" },
                    },
                    {
                        text = "Teleport to DIP and talk to K'Chunk.",
                        chat = "4 You knocked out Bre'egth's tooth, didn't you?",
                        npcs = {},
                        subs = {
                            { text = "Recommended: Bring 4 regular planks and 8 nails of any kind to fix the bridge by using a plank on the broken bridge." },
                            { text = "Recommended: Bring 8 willow logs if you have level 85 Firemaking, light the campfire for K'Chunk and receive 10,000 Firemaking experience." },
                        },
                    },
                    {
                        text = "Pickpocket him for the tooth.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Gromblod's Tooth", needed = { "Dramen staff or Lunar staff and tooth extractor" },
                steps = {
                    {
                        text = "Teleport to BKQ.",
                        npcs = {},
                    },
                    {
                        text = "Head down the waterfall to talk to the Wood Dryad to the west.",
                        chat = "2 Have you seen Gromblod?",
                        npcs = { "Wood Dryad" },
                    },
                    {
                        text = "Talk to General Gromblod.",
                        npcs = { "General Gromblod" },
                    },
                    {
                        text = "Talk to the Wood Dryad again.",
                        npcs = {},
                    },
                    {
                        text = "Teleport to CLR.",
                        npcs = {},
                    },
                    {
                        text = "Pick a mango from the mango tree.",
                        npcs = { "Mango (A Fairy Tale III)", "Mango tree (A Fairy Tale III)" },
                        subs = {
                            { text = "Optional: unblock this end of the hollow log if you haven't yet." },
                        },
                    },
                    {
                        text = "Return to BKQ.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Gromblod, giving him the mango, he will spit it out about 15 tiles south of where he is standing. It does not appear as a red dot on the minimap.",
                        npcs = {},
                    },
                    {
                        text = "Pick up the mango with tooth and use the tooth extractor on it.",
                        npcs = { "mango with tooth" },
                    },
                },
            },
            {
                title = "Shredflesh's Tooth", needed = { "Dramen staff or Lunar staff, and tooth extractor" },
                steps = {
                    {
                        text = "Teleport to ALP and talk to General Shredflesh.",
                        chat = "4 Can I help with something? / 1 So your tooth is really hurting, is it? / 2 Which tooth is it that's so terribly painful and hurting? / 3 And the pain is very high is it? / 4 I'm a dentist; I can extract it for you!",
                        npcs = { "General Shredflesh" },
                    },
                    {
                        text = "In no particular order, calm him with the following responses:",
                        npcs = {},
                        subs = {
                            { text = "\"What's a bit of pain for a huge ork hero like you?\"" },
                            { text = "\"If the tooth isn't pulled out, all your teeth will hurt much worse!\"" },
                            { text = "\"Let me pull it out! What are you, an ork or a goblin?\"" },
                            { text = "\"I'll make sure it doesn't hurt a bit; I'm a professional.\"" },
                        },
                    },
                    {
                        text = "Use the extractor on him.",
                        npcs = {},
                    },
                    {
                        text = "Clear the pile of rock behind him if you haven't yet already.",
                        npcs = {},
                    },
                    {
                        text = "Go back and talk to the Tooth Fairy in the hideout.",
                        npcs = {},
                    },
                    {
                        text = "Turn-on the projector to watch another briefing.",
                        chat = "5 Okay, thanks.",
                        npcs = {},
                    },
                    {
                        text = "She gives you the fairy wand.",
                        npcs = { "fairy wand" },
                    },
                },
            },
            {
                title = "The final battle", needed = { "The fairy wand, the 3 teeth and combat equipment. You will not use the fairy wand to fight, but you will need it during the fight to heal the farming patches and the friendly generals. You can also use the fairy wand to access the fairy ring system, so you can bank your Dramen or Lunar staff at this point." },
                steps = {
                    {
                        text = "Prepare for the final battle, with the above listed items.",
                        npcs = {},
                    },
                    {
                        text = "Teleport to BIR, DIP, CLR, ALP. (If the fairy ring at BIR does not appear, lobby and start over.)",
                        npcs = {},
                    },
                    {
                        text = "Look-through the fairy tree where you'll encounter a cutscene.",
                        npcs = { "fairy tree" },
                    },
                    {
                        text = "After the cutscene talk to the Tooth Fairy.",
                        npcs = {},
                    },
                    {
                        text = "How to kill the Fairy Godfather:",
                        npcs = { "Fairy Godfather" },
                        subs = {
                            { text = "Use all 3 teeth on the farming patches." },
                            { text = "Stand by the patches and kill the generals and ork warriors; Prioritise any general using the drum near the rift, to stop new orks from spawning." },
                            { text = "Once the teeth have grown, instruct them to fight." },
                            { text = "Focus on ork warriors while the teeth focus on killing the generals." },
                            { text = "After you and the teeth kill the generals, kill the godfather." },
                            { text = "You must let the teeth attack the godfather to reduce the shields. Ensure all 3 teeth are attacking the godfather at once, as each one removes a layer of his 3-layer shield." },
                            { text = "If all 3 teeth are not attacking the godfather, you will not land hits as his shield will still be active. The melee tooth will not path around the player if you are in the way." },
