    {
        key = "a_guild_of_our_own_miniquest", name = "A Guild of Our Own (miniquest)", wiki = "A Guild of Our Own (miniquest)/Quick guide",
        required = { "Any blackjack (not including the rubber blackjack)", "Lockpick (or hair clip)", "Irit potion (unfinished) (or clean irit and a vial of water)", "Chopped onion (or bowl, onion)" },
        recommended = { "Ardougne teleport runes, tablet (recommended) or Ardougne lodestone." },
        sections = {
            {
                title = "Guild registry", needed = { "Lockpick, blackjack, vial of stench (a)" },
                steps = {
                    {
                        text = "In a building south-east of Ardougne market, pickpocket the Registrar for a cuckoo clock key.",
                        npcs = { "Registrar", "cuckoo clock key" },
                    },
                    {
                        text = "Get ready, the next steps are time sensitive. You can try again if you fail with no consequence. Make sure to equip a blackjack first.",
                        npcs = {},
                        subs = {
                            { text = "In the north room, wind the clock on the wall." },
                            { text = "Go in the south room, wait for the Registrar to get to the clock room." },
                            { text = "Lure, knock out, then steal-from the guard." },
                            { text = "Pull the vault lever behind the desk." },
                            { text = "Go down the trapdoor that opens, the following steps are no longer time sensitive." },
                        },
                    },
                    {
                        text = "Right-click pick-lock on the vault door.",
                        npcs = {},
                    },
                    {
                        text = "Right-click check the chest for traps, then open it. You should receive some bonds.",
                        npcs = { "Bonds (A Guild of Our Own)" },
                    },
                    {
                        text = "Inspect the boxes under the square hole in the wall to exit.",
                        chat = "1 Leave the vault.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing up", needed = { "Bonds (A Guild of Our Own)" },
                steps = {
                    {
                        text = "Bank (recommended) or destroy your vial of stench (a).",
                        npcs = { "vial of stench (a)" },
                    },
                    {
                        text = "Re-enter the building and talk to the Registrar.",
                        npcs = {},
                    },
                    {
                        text = "Return to Darren Lightfinger.",
                        chat = "3 I'd like to talk about the caper I'm doing for you.",
                        npcs = {},
                    },
                    {
                        text = "Miniquest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "a_shadow_over_ashdale", name = "A Shadow over Ashdale", wiki = "A Shadow over Ashdale/Quick guide",
        required = {},
        recommended = { "Decent armour, some food and a gem bag.", "Ranged or Magic weapons to deal damage from a distance." },
        sections = {
            {
                title = "Return to Ashdale", needed = { "Decent armour, some food, a gem bag, weapons to deal damage from a distance." },
                steps = {
                    {
                        text = "To start, talk to Gudrik, east of Gerrant's Fishy Business in Port Sarim.",
                        chat = "1 Ask about A Shadow over Ashdale. / Accept",
                        npcs = { "Gudrik" },
                    },
                    {
                        text = "Talk to him again.",
                        chat = "1 Can you take me to the island of Ashdale? / 1 Ashdale by night (A Shadow over Ashdale).",
                        npcs = {},
                    },
                    {
                        text = "Once you arrive at Ashdale, head north into Lucy's house to speak with her.",
                        chat = "1 I'm here to help. / 3 Why haven't you tried to leave?",
                        npcs = { "Lucy (A Shadow over Ashdale)" },
                    },
                    {
                        text = "Enter the storm drain just west of the house.",
                        npcs = { "storm drain" },
                    },
                },
            },
            {
                title = "Sewer raider", needed = {},
                steps = {
                    {
                        text = "Go through in the sewer, killing or running past crassians.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the ladder at the end of the sewer.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Run west, then south up the stairs. Continue south through Ashdale, through the gate and into the house.",
                        npcs = {},
                    },
                    {
                        text = "Inspect the bust by the fireplace.",
                        npcs = { "bust" },
                    },
                    {
                        text = "Climb down the staircase.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Smuggler's cavern", needed = {},
                steps = {
                    {
                        text = "Ignore the crassians and enter the eastern room.",
                        npcs = {},
                    },
                    {
                        text = "Pick up the valve outer wheel, valve inner wheel and pitch.",
                        npcs = { "valve outer wheel", "valve inner wheel", "pitch" },
                    },
                    {
                        text = "Repair the pipe on the ground.",
                        npcs = { "Pipe (A Shadow over Ashdale)" },
                    },
                    {
                        text = "Combine the valve parts to create a valve wheel.",
                        npcs = { "Valve wheel (A Shadow over Ashdale)" },
                    },
                    {
                        text = "Repair the socket on the central barrel.",
                        npcs = { "socket", "Barrel (A Shadow over Ashdale)" },
                    },
                    {
                        text = "Turn the valve wheel on the filled barrel, repeating this process on each of the barrels to move the water through the pipes to open the door.",
                        npcs = {},
                    },
                    {
                        text = "Continue through and kill the crassian scouts in the next room to open the barrier.",
                        npcs = {},
                    },
                    {
                        text = "Pull the lever to the south when the crassian warrior isn't looking.",
                        npcs = { "Lever (A Shadow over Ashdale)", "crassian warrior" },
                        subs = {
                            { text = "If seen, simply try again." },
                        },
                    },
                    {
                        text = "Do the same with each crassian warrior guarding a lever to kill them.",
                        npcs = {},
                    },
                    {
                        text = "Optionally loot the chests along the path for some coins and uncut gems.",
                        npcs = { "Chest (A Shadow over Ashdale)", "coins" },
                    },
                    {
                        text = "Run past the scouts.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Release the Kraken", needed = {},
                steps = {
                    {
                        text = "Climb on the ship.",
                        npcs = {},
                    },
                    {
                        text = "Kill the 4 tentacles, moving to avoid their attacks.",
                        npcs = {},
                    },
                    {
                        text = "Kill Agoroth, ideally from a distance.",
                        npcs = {},
                    },
                    {
                        text = "Continue dialogue with Lucy and agree to return to Port Sarim.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Continue dialogue with Gudrik and ask for a reward.",
                        chat = "1 Ask about A Shadow over Ashdale. / 1 Is there a reward?",
                        npcs = {},
                        subs = {
                            { text = "The reward requires seven free backpack spaces." },
                        },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "a_soul_s_bane", name = "A Soul's Bane", wiki = "A Soul's Bane/Quick guide",
        required = {},
        recommended = { "Food", "Melee Armour and a weapon", "Antipoison is helpful for low-levelled players", "Archaeology journal for a close teleport" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to Launa who is east of Varrock and south of the path leading to Silvarea.",
                        chat = "Accept",
                        npcs = { "Launa", "Varrock", "Silvarea" },
                        tile = { x = 3309, y = 3453, plane = 0 },
                    },
                    {
                        text = "Enter the rift.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Room of Rage", needed = {},
                steps = {
                    {
                        text = "Near the entrance is a set of weapons.",
                        npcs = {},
                    },
                    {
                        text = "Only these weapons will defeat the monsters in this room. Different weapons kill different monsters. Kill monsters until the rage meter at the top of the screen is full. Certain equipment will not allow progress. To be safe, un-equip all gear except the anger weapons.",
                        npcs = {},
                        subs = {
                            { text = "Anger sword - kills Angry unicorn" },
                            { text = "Anger spear - kills Angry bear" },
                            { text = "Anger maul - kills Angry giant rat" },
                            { text = "Anger battleaxe - kills Angry goblin" },
                        },
                    },
                    {
                        text = "Watch the short cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Enter the exit to the east to proceed.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Room of Fear", needed = {},
                steps = {
                    {
                        text = "'Look-inside' a dark hole, if the fear reaper does not show up right away move onto the next hole that has the 'look-inside' option. Move around the room in a clock-wise rotation until the fear reaper has been killed 5 times.",
                        npcs = { "fear reaper" },
                    },
                    {
                        text = "Continue the process until you receive a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene, Enter the black hole on the west wall to proceed.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Room of Confusion", needed = {},
                steps = {
                    {
                        text = "Start attacking a confusion beast, if you do not deal any damage immediately move onto another beast until you find the one that takes damage.",
                        npcs = { "confusion beast" },
                        subs = {
                            { text = "Any confusion beast that you hit will continue to attack you, if you are low combat it is advised to continue hitting a beast until it goes away." },
                        },
                    },
                    {
                        text = "Find and kill the confusion beast 5 times in total in order to proceed.",
                        npcs = { "confusion beast" },
                    },
                    {
                        text = "After all beasts have been killed enter the remaining confusing door for a cutscene.",
                        npcs = { "confusing door" },
                    },
                },
            },
            {
                title = "Room of Hopelessness", needed = {},
                steps = {
                    {
                        text = "Kill each of the hopeless creatures 3 times.",
                        npcs = { "hopeless creature" },
                        subs = {
                            { text = "Eating food will cause the hopeless creature to restore 75% of their life points." },
                        },
                    },
                    {
                        text = "Cross the bridge and 'Use' the exit to proceed.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Tolna", needed = {},
                steps = {
                    {
                        text = "Kill all three of Tolna's heads.",
                        npcs = { "Tolna (monster)" },
                    },
                    {
                        text = "Talk to Tolna.",
                        npcs = { "Tolna" },
                        subs = {
                            { text = "If he doesn't spawn, exit the room and re-enter." },
                        },
                    },
                    {
                        text = "On the surface, talk to Tolna again.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "a_tail_of_two_cats", name = "A Tail of Two Cats", wiki = "A Tail of Two Cats/Quick guide",
        required = { "Cat, hellcat, wily cat, or kitten (if a kitten, advised to bring food for it)", "Catspeak amulet (a cramulet cannot be used as a substitute, you can separate the catspeak amulet from the cramulet with the Interact dismantle option)", "Five death runes", "Chocolate cake", "Bucket of milk", "Logs (can be obtained south of Unferth's house)", "Four potato seeds (can be obtained south-west of Unferth's house from Head Farmer Jones)", "Vial of water (as it will dry up in the desert, it is recommended to take this after you are finished with that part of the quest.)", "A vial is more reliable. There is a sink right where you need the vial of water.", "White desert robe outfit, druid's robe outfit, or other white-coloured robes" },
        recommended = { "An enchanted water tiara or waterskins or completion of Crocodile tears", "Varrock Teleport or a combat bracelet", "A pharaoh's sceptre, sceptre of the gods, or Sophanem Slayer Dungeon teleport for quick teleport to Sophanem.", "A desert amulet 2 or a player-owned house in Pollnivneach also gives close access to a magic carpet.", "Completion of Contact! also allows one-way travel across the bridge from Menaphos to Sophanem, which is only a short distance from the Menaphos lodestone.", "Active lodestones or teleportation across the free-to-play map in order to find Bob the Cat." },
        sections = {
            {
                title = "Starting the quest", needed = { "catspeak amulet" },
                steps = {
                    {
                        text = "Equip your catspeak amulet, have your pet cat with you, and talk to Unferth. His house is in eastern Burthorpe, south of Dunstan and east of Tam McGrubor.",
                        chat = "Accept",
                        npcs = { "Unferth", "Burthorpe" },
                    },
                },
            },
            {
                title = "Cathunt", needed = { "5 death runes" },
                steps = {
                    {
                        text = "Speak to Hild in the building north of the Heroes' Guild. She will enchant the catspeak amulet for 5 death runes.",
                        npcs = { "Hild", "Heroes' Guild" },
                    },
                    {
                        text = "Locate Bob the Cat using the catspeak amulet.",
                        npcs = { "Bob the Cat" },
                        subs = {
                            { text = "Right-click and \"open\" the amulet." },
                            { text = "Click on the whiskers until the arrow and the eyes glow white." },
                            { text = "Run in the direction of the arrow, occasionally re-checking the amulet, until you find Bob." },
                            { text = "The easiest way to find Bob is to keep hopping worlds in the Carwen Essencebinder Magical Runes Shop in Burthorpe." },
                        },
                    },
                    {
                        text = "Talk to Bob.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Strong lineage", needed = {},
                steps = {
                    {
                        text = "Ask Gertrude about Bob's parents in her house west of Varrock.",
                        chat = "4 Ask about Bob's parents.",
                        npcs = { "Gertrude", "Varrock" },
                        subs = {
                            { text = "If Rat Catchers hasn't been started.", chat = "5 Ask about Bob's parents." },
                        },
                    },
                    {
                        text = "Speak to Reldo in the Varrock library.",
                        chat = "3 Ask about Robert the Strong.",
                        npcs = { "Reldo", "Varrock Palace" },
                    },
                    {
                        text = "Go back and talk to Bob the cat again, in the same spot you found him.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Memories and Bob's list", needed = { "4 potato seeds, logs, chocolate cake, bucket of milk" },
                steps = {
                    {
                        text = "Go to Sophanem and talk to the Sphinx.",
                        chat = "1 Ask the Sphinx for help. / 2 Skip the cutscene and view summary.",
                        npcs = { "Sophanem", "Sphinx" },
                        subs = {
                            { text = "Talk to Raetul and buy a full desert robe set, if you don't have them already." },
                        },
                    },
                    {
                        text = "Return to Unferth's house in Burthorpe and do the following:",
                        npcs = {},
                        subs = {
                            { text = "Rake the patch behind his house and plant potato seeds in it. Your cat will notify you when they are done (typically 25–35 minutes to grow). A supreme growth potion from player-owned farm cannot be used to accelerate growth. It will not get disease, and it does not need composting or watering." },
                            { text = "If you don't have your cat out, chatbox will tell \"Perhaps I should have a look and see if Unferth's potatoes have grown...\"." },
                            { text = "Use the logs on fireplace, then light the fireplace." },
                            { text = "Use the chocolate cake and bucket of milk on the table." },
                            { text = "Make his bed upstairs." },
                            { text = "Give Unferth a haircut.", chat = "2 Cut Unferth's hair" },
                        },
                    },
                    {
                        text = "Talk to Unferth once all the chores are done.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Down with the \"sickness\"", needed = { "vial of water, desert robe outfit, druid's robe outfit or other white robes" },
                steps = {
                    {
                        text = "Talk to the Apothecary in south-west Varrock.",
                        chat = "1 Tell the Apothecary that Unferth is ill. / Any",
                        npcs = { "Apothecary" },
                        tile = { x = 3195, y = 3404, plane = 0 },
                    },
                    {
                        text = "Unequip your weapons and equip the doctors hat/nurse hat and your white robes.",
                        npcs = { "doctors hat", "nurse hat" },
                    },
                    {
                        text = "Return to Unferth with a vial of water.",
                        npcs = { "vial of water" },
                    },
                    {
                        text = "Talk to Bob the cat. If he's not at his previous location, locate him again using the catspeak amulet (e).",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene, talk to Unferth again.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
