    {
        key = "another_slice_of_h_a_m", name = "Another Slice of H.A.M.", wiki = "Another Slice of H.A.M./Quick guide",
        required = { "At least 3 free backpack spaces, however 8 is preferable", "Magic, Ranged, or Necromancy gear to fight a level 28 H.A.M. ranger and a level 28 H.A.M. mage.", "They cannot be killed using Melee weapons. A crossbow and 50 bronze bolts can be found at their location.", "A light source (A bug lantern does not work)", "A rope (only if you have never entered the Lumbridge Swamp Caves from the surface before)" },
        recommended = { "Food for lower levelled players", "Water altar teleport or an enlightened amulet", "Molten glass and law runes in the bank to make Dorgesh-kaan spheres post-quest" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to either NPC in the north eastern most building on the 2nd floor of Dorgesh-Kaan.",
                        npcs = { "Dorgesh-Kaan" },
                        subs = {
                            { text = "Ambassador Alvijar", chat = "Accept" },
                            { text = "If Ambassador Alvijar says you might be a human spy, you haven't completed The Giant Dwarf yet." },
                            { text = "If you have just completed Death to the Dorgeshuun, you may need to exit to the lobby and re-enter the game for him to appear." },
                            { text = "Ur-Tag", chat = "1 What are you arguing about? / Accept" },
                        },
                    },
                },
            },
            {
                title = "Artefacts", needed = {},
                steps = {
                    {
                        text = "While on the same floor, head west then south until you find a transportation map icon.",
                        npcs = {},
                        tile = { x = 103, y = 93, plane = 0 },
                    },
                    {
                        text = "Enter the doorway, head south down the tracks and talk to Tegdak (you need 2 free spaces for the specimen brush and trowel).",
                        npcs = { "Tegdak" },
                    },
                    {
                        text = "Use the trowel on the 6 artefacts on the ground to dig them up. They have the same sparkles as time sprite.",
                        npcs = { "Artefact (Another Slice of H.A.M.)", "time sprite" },
                        subs = {
                            { text = "If you need more backpack space, you can talk to Tegdak per restored artefact, you don't need to give all in at once." },
                        },
                    },
                    {
                        text = "Use each of them on the specimen table.",
                        npcs = { "specimen table (Another Slice of H.A.M.)" },
                    },
                    {
                        text = "Talk to Tegdak and Zanik will be following you after the dialogue.",
                        npcs = {},
                    },
                    {
                        text = "If Zanik isn't following you, dismiss any pets/familiars and talk to Zanik.",
                        chat = "1 Yes",
                        npcs = { "Zanik" },
                        subs = {
                            { text = "Zanik will now be following you." },
                            { text = "If you lose Zanik you will need to return here to retrieve her. (Teleporting will leave Zanik behind)" },
                        },
                    },
                    {
                        text = "With Zanik following, exit the train tunnel using the doorway to the north.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Goblin scribe, in the building directly west of the quest start point.",
                        npcs = { "Goblin scribe" },
                    },
                    {
                        text = "In the house just west of the Goblin scribe, climb down the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Oldak.",
                        npcs = { "Oldak" },
                        subs = {
                            { text = "If you have Invention unlocked.", chat = "2 No - talk about quest or other things." },
                        },
                    },
                    {
                        text = "You will be teleported to Goblin Village with Zanik, receiving a Dorgesh-kaan sphere in your inventory.",
                        npcs = { "Goblin Village", "Dorgesh-kaan sphere" },
                    },
                },
            },
            {
                title = "The Goblin Village", needed = { "A ranged, magic or necromancy weapon and its ammunition to defeat 2 H.A.M. members behind object." },
                steps = {
                    {
                        text = "In Goblin Village, in the northernmost building, talk to either General Bentnoze or Wartface.",
                        npcs = { "General Bentnoze", "General Wartface" },
                    },
                    {
                        text = "After the cutscene, go behind the buildings to the west, go south, then climb up the ladder to the east.",
                        npcs = {},
                        subs = {
                            { text = "If you attempt to walk around the front of the buildings, you will be stopped by falling arrows." },
                        },
                    },
                    {
                        text = "Kill the H.A.M. Mage and H.A.M. Archer.",
                        npcs = { "H.A.M. Mage", "H.A.M. Archer" },
                        subs = {
                            { text = "A crossbow and 50 bronze bolts can be found on the ground here." },
                        },
                    },
                    {
                        text = "Talk to generals.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Infiltrating H.A.M.", needed = { "A light source (and a rope if you have never entered the caves from the surface before)" },
                steps = {
                    {
                        text = "With a light source, head to the Lumbridge Swamp Caves entrance north-west of the Water altar.",
                        npcs = { "Lumbridge Swamp Caves", "Water altar" },
                        subs = {
                            { text = "If you brought a water altar teleport or Enlightened amulet to teleport to Lumbridge Swamp, use them now for quicker travel." },
                        },
                    },
                    {
                        text = "Talk to Sergeant Slimetoes or Mossfists outside the entrance to the Lumbridge Swamp Caves.",
                        npcs = { "Sergeant Slimetoes", "Sergeant Mossfists" },
                    },
                    {
                        text = "Climb down the dark hole under the tree entering the Lumbridge Swamp Caves.",
                        npcs = {},
                        subs = {
                            { text = "If you haven't already placed rope in the entrance you will need rope." },
                        },
                    },
                    {
                        text = "Go down the ladder, directly south east of the Climbing Rope.",
                        npcs = {},
                    },
                    {
                        text = "For the next part, you need to distract the guards by luring them to Slimetoes and Mossfists.",
                        npcs = {},
                        subs = {
                            { text = "If a guard catches you by getting too close, you will be thrown out to the Lumbridge Swamp Caves." },
                            { text = "Finishing the dialogue and waiting allows the first guard to return with the second guard and they should begin fighting the goblins." },
                            { text = "Once the 2 guards are fighting the goblins, carefully go towards the south end of the tunnel. (A guard will begin patrolling the tunnel once you get close)" },
                            { text = "Let the patrolling guard spot you from a distance, then lure the guard to the goblins." },
                            { text = "For the final guard blocking the exit, step next to the pillar in his view and he will spot you. Lure him to the goblins." },
                        },
                    },
                    {
                        text = "With the guards engaging the goblins, it is safe to run south to the ladder.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Sigmund Reloaded", needed = {},
                steps = {
                    {
                        text = "Enabling legacy combat for this section can make your fight with Sigmund significantly quicker.",
                        npcs = {},
                    },
                    {
                        text = "Equip the ancient mace and climb down the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Initiate combat with Sigmund.",
                        npcs = {},
                        subs = {
                            { text = "If you have legacy combat enabled, simply use the Ancient Mace's special attack at the start of the fight and finish him however you choose." },
                            { text = "If you have do not have legacy combat enabled, use the Ancient Mace's special attack to disable Sigmund's prayers once you reach 100% adrenaline." },
                            { text = "The special attack ability can be found in the Constitution ability book or you can click on your adrenaline bar on your main ability bar to use the special attack once at 100% adrenaline." },
                            { text = "You can use any combat style you choose once Sigmund's prayer is down." },
                        },
                    },
                    {
                        text = "After defeating Sigmund, untie Zanik.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "as_a_first_resort", name = "As a First Resort", wiki = "As a First Resort/Quick guide",
        required = { "Box trap", "Bird snare", "Teasing stick (Unless you are buying the 8 larupia furs from the grand exchange)", "Four spears of the same type (bone spears work; poisoned spears and leaf-bladed spears do not work)", "Available just outside Oo'glog:", "8 achey tree logs", "15-30 eucalyptus logs (If you don't make any mistakes in the logic section, 20 is more than enough)", "2 raw chompy", "Available to be caught in the ogre chompy hunting area, which requires partial completion of Big Chompy Bird Hunting. If hunting, remember to bring an ogre comp or a plain ogre bow, ogre arrows and ogre bellows", "8 stripy feathers (available from the tropical wagtails in the hunting area to the north of Oo'glog)", "4 wolf bones (available from killing the wolves outside Oo'glog)", "8 larupia furs (tatty or perfect, available from pit-fall hunting Larupia in the hunting area to the north of Oo'glog)", "Each of the following plants found near Oo'glog:", "11-14 fever grass", "7-11 lavender", "6 primweed", "6 stinkbloom", "8-12 tansymum", "Some logs of any kind for traps" },
        recommended = { "Activated the Oo'glog lodestone (Fastest method of travel)", "Master archaeologist's outfit or Archaeology teleport to Chief Tess", "Runes for the South Feldip Hills Teleport (1 air rune, 1 water rune and 1 law rune)", "A ring of duelling to teleport to the Warforge Dig Site, a short distance west from Oo'glog", "The Fairy ring AKS is north of Oo'glog", "The Spirit Tree at South Feldip Hills Teleport" },
        sections = {
