                    },
                    {
                        text = "Use two raw chompies on Chargurr.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Chargurr.",
                        npcs = {},
                    },
                    {
                        text = "Light the fire pit.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Chargurr.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The beds", needed = { "8 stripy feathers (or a bird snare)" },
                steps = {
                    {
                        text = "Talk to Balnea located in the bank.",
                        chat = "1 Right-ho. I'll go and see Snurgh at the hotel and 'transition' away.",
