            {
                title = "The pools", needed = { "at least 6 eucalyptus logs, 2 tansymum, 1 fever grass, 1 primweed, 1 stinkbloom, and 1 lavender" },
                steps = {
                },
            },
            {
                title = "First trial", needed = {},
                steps = {
                    {
                        text = "Talk to Balnea.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Seegud in the building north-east of the bank.",
                        npcs = { "Seegud" },
                    },
                    {
                        text = "Head north-east of Seegud to the thermal spring.",
                        npcs = {},
                    },
                    {
                        text = "Use a pile of eucalyptus logs and a tansymum, on the fire pit nearby.",
                        npcs = {},
