    {
        key = "back_to_my_roots", name = "Back to my Roots", wiki = "Back to my Roots/Quick guide",
        required = { "Any hatchet on your tool belt or otherwise to fight with; a rune hatchet or better (including Inferno adze) is recommended.", "A plant pot with soil", "Soft clay (to make the pot lid during the quest after talking to Wizard Cromperty; a bought pot lid or one that was made before the quest will not work).", "An empty pot (not a plant pot)", "A Melee weapon if your hatchet is on your tool belt" },
        recommended = { "Food", "Antipoison, anti-poison totem, or prayer book (for in the maze only)" },
        sections = {
