            {
                title = "Karamja vine maze", needed = { "pot lid, filled plant pot, empty pot" },
                steps = {
                    {
                        text = "South-east of the nature altar, enter the maze by climbing the vine (north side). Do not leave the maze until you have followed all steps in this section.",
                        npcs = {},
