        key = "back_to_the_freezer", name = "Back to the Freezer", wiki = "Back to the Freezer/Quick guide",
        required = { "Combat equipment", "Clockwork suit (given to you if you do not have one)", "Insulated boots", "Ice cooler (needed as an item, ice shaker will not work)", "50 flickering energy", "50 bright energy", "50 sparkling energy", "50 gleaming energy", "8-12 backpack spaces" },
        recommended = { "Protection against desert heat", "Food", "Pollnivneach teleportation methods (e.g. Chipped Teleport to house tablets, ring of slaying teleport to Sumona, or a Pollnivneach Teleport), or an activated Bandit Camp lodestone", "Easy Ardougne achievements for quick teleports to Chuck using the Kandarin monastery Teleport, or Clocktower Teleport, or Dramen/Lunar staff for access to the fairy ring code DJP", "A charged Enchanted lyre, for immediate access to the market in Rellekka" },
        sections = {
            {
                title = "Start", needed = {},
                steps = {
                    {
                        text = "Talk to Chuck in the Ardougne Zoo",
                        chat = "1 Back to the Freezer Quest / Accept",
                        npcs = { "Chuck", "Ardougne Zoo" },
                    },
                    {
                        text = "Note down the blue text.",
                        npcs = {},
                        subs = {
                            { text = "Alternatively, the Passphrase may also be found in your quest journal." },
                        },
                    },
                    {
                        text = "North-east of the Rellekka marketplace, talk to Skot or Mundsen.",
                        npcs = { "Rellekka", "Skot", "Mundsen" },
                    },
                    {
                        text = "When prompted, tell them the passphrase from Chuck.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Desert", needed = {},
                steps = {
                    {
                        text = "After telling the passphrase, finish the dialogue and cutscene.",
                        npcs = {},
                    },
                    {
                        text = "South-west of Pollnivneach, talk to Dundee (gnome next to the tent), who will give you a crocspeak amulet.",
                        chat = "1 Ask about the penguins.",
                        npcs = { "Pollnivneach", "Dundee", "crocspeak amulet" },
                    },
                    {
                        text = "Equip the crocspeak amulet.",
                        npcs = {},
                    },
                    {
                        text = "Just west, talk to Croc.",
                        chat = "4 Bye",
                        npcs = { "Croc" },
                    },
                    {
                        text = "South-west, investigate the T.A.R.D.I.S..",
                        npcs = { "T.A.R.D.I.S." },
                    },
                },
            },
            {
                title = "The secret-secret agent", needed = {},
                steps = {
                    {
                        text = "Return to Chuck in Ardougne.",
                        chat = "1 Back to the Freezer Quest",
                        npcs = { "Ardougne" },
                    },
                    {
                        text = "Note down the agent's favourite food Chuck tells you. Favourite food may be found in your quest journal.",
                        npcs = {},
                    },
                    {
                        text = "Return to the T.A.R.D.I.S.",
                        npcs = {},
                    },
                    {
                        text = "Unequip any item in your cape, main-hand and off-hand slot.",
                        npcs = {},
                    },
                    {
                        text = "With your clockwork suit in your backpack talk to any named penguin and you will automatically equip your clockwork suit.",
                        npcs = { "clockwork suit" },
                        subs = {
                            { text = "If you don't have a clockwork suit with you return to the zoo and speak with Chuck. Chuck will give you a clockwork suit." },
                        },
                    },
                    {
                        text = "In order, talk to the following penguins:",
                        npcs = {},
                        subs = {
                            { text = "Emperor Wing", chat = "1 Remind me what happened. / 2 What happened to you at the party?" },
                            { text = "Elon", chat = "2 What happened to you at the party?" },
                            { text = "Hugh", chat = "2 What happened to you at the party?" },
                            { text = "Gordon", chat = "2 What happened to you at the party? / 3 Are you a spy?" },
                        },
                    },
                    {
                        text = "Gordon will give you a G.P.S.. If he does not, simply talk to him again.",
                        npcs = { "G.P.S." },
                    },
                    {
                        text = "Walk to the edge of the icy patch to get out of the clockwork suit.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The secret bunker", needed = { "Ice cooler" },
                steps = {
                    {
                        text = "Head to the pier north of Fremennik Province lodestone and north-east of Rellekka, travel to the Iceberg via the smaller boat.",
                        npcs = { "Fremennik Province lodestone", "Iceberg" },
                    },
                    {
                        text = "Locate with the G.P.S., follow the directions until you find the Mysterious Hatch.",
                        npcs = { "Mysterious Hatch" },
                    },
                    {
                        text = "To the north-east, right click Jim the polar bear and choose \"Tuxedo-Time\".",
                        npcs = { "Jim" },
                    },
                    {
                        text = "Interact with the hatch and type in \"1234\" to enter.",
                        npcs = {},
                    },
                    {
                        text = "Enter the north-east room and search the interactable cupboard on the north wall for a hat.",
                        npcs = { "Hat (Back to the Freezer)" },
                    },
                    {
                        text = "Exit the room and then follow the corridor south.",
                        npcs = {},
                    },
                    {
                        text = "Head west and take the first turn north. Enter the large door leading to the large room in the centre of the bunker.",
                        npcs = {},
                    },
                    {
                        text = "Enter the locker room to your west and search Gordon's locker on the west side for the de-lore-ing device parts list and de-lore-ing device (incomplete).",
                        npcs = { "de-lore-ing device parts list", "de-lore-ing device (incomplete)" },
                    },
                    {
                        text = "Exit the large door to go back to the main corridor (make sure you interact with your side of the door).",
                        npcs = {},
                    },
                    {
                        text = "Enter the southwest room full of crates and search or look in them until you find both a hammer and flax.",
                        npcs = { "Hammer (Back to the Freezer)", "Flax (Back to the Freezer)" },
                    },
                    {
                        text = "In the north-western most room, Peruse the ice shelf (looks like a normal shelf) for The Penguin Book of Gielinor.",
                        npcs = { "The Penguin Book of Gielinor" },
                    },
                    {
                        text = "Behind you, Get Ice from the Ice Maker by the door to take ice cubes.",
                        npcs = { "Ice Maker", "ice cubes" },
                    },
                    {
                        text = "Use the hammer on the ice cubes to create the flax cap-ice-i-tor.",
                        npcs = { "flax cap-ice-i-tor" },
                    },
                    {
                        text = "Use the flax cap-ice-i-tor on the de-lore-ing device (incomplete) for the de-lore-ing device.",
                        npcs = { "de-lore-ing device" },
                    },
                    {
                        text = "Operate the de-lore-ing device.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Time travelling!", needed = {},
                steps = {
                    {
                        text = "Take the monkey wrench (north & slightly east), use it on the de-lore-ing device then operate the device again.",
                        npcs = { "monkey wrench" },
                    },
                    {
                        text = "Take the penguin bongos and cowbells in the north-west corner, use either on the device, operate the device again.",
                        npcs = { "Penguin bongos (Back to the Freezer)", "Cowbells (Back to the Freezer)" },
                    },
                    {
                        text = "Pick cabbage, use it on the device, operate the device again.",
                        npcs = { "Cabbage (Back to the Freezer)" },
                    },
                    {
                        text = "Speak to the man with a dragon pickaxe, use worthless old boots on the device, operate the device one last time.",
                        npcs = { "worthless old boots" },
                    },
                },
            },
            {
                title = "Back in the bunker", needed = {},
                steps = {
                    {
                        text = "Talk to Gordon in the south-western room.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Elon in the centre of the bunker.",
                        npcs = {},
                    },
                    {
                        text = "Get the fishing rod from the corner of the War room south of the big door.",
                        npcs = { "fishing rod" },
                    },
                    {
                        text = "Go to the 'cold storage' crate room in the southwest and search until you have both the cog and coolant holder.",
                        npcs = { "Cog (Back to the Freezer)", "coolant holder" },
                    },
                    {
                        text = "Use the cog on the fishing rod to create the 'fishvention' rod.",
                        npcs = { "'fishvention' rod" },
                    },
                    {
                        text = "Go to the western room with the snowmaker and gather Pure S-now from the pure snow piles - wait until you have gathered all 2,000. (Process takes about a minute)",
                        npcs = { "Pure S-now", "pure snow" },
                    },
                    {
                        text = "Search the crate north of the Mysterious Ice Block in the same room for a lemon.",
                        npcs = { "Lemon (Back to the Freezer)" },
                    },
                    {
                        text = "Use the Mysterious ice block in the room to craft 2000 lemon sole runes.",
                        npcs = { "lemon sole rune" },
                    },
                    {
                        text = "Go to the north-western room and use the ice cooler and the coolant holder from your inventory on the Ice Maker to create cool-ant and an ice box.",
                        npcs = { "ice cooler", "coolant holder", "cool-ant", "ice box" },
                    },
                    {
                        text = "Talk to Buzz who is in the prison in the eastern room for 21 killerwatt energy.",
                        npcs = { "Buzz", "killerwatt energy" },
                    },
                    {
                        text = "Leave the bunker via the door to the north.",
                        npcs = {},
                    },
                    {
                        text = "Walk east, talk to Jim the polar bear to exit your disguise.",
                        chat = "1 Yes",
                        npcs = {},
                    },
                },
            },
            {
                title = "Getting Energy", needed = { "Insulated boots" },
                steps = {
                    {
                        text = "Equip your insulated boots and prepare for combat.",
                        npcs = { "insulated boots" },
                    },
                    {
                        text = "Make your way to the top floor of Draynor Manor (staircase then ladder).",
                        npcs = { "Draynor Manor" },
                    },
                    {
                        text = "Enter the eastern room, then the Interdimensional Rift.",
                        npcs = { "Interdimensional Rift" },
                    },
                    {
                        text = "Kill 10 Killerwatts until you have 121 killerwatt energy.",
                        npcs = { "Killerwatt" },
                    },
                },
            },
            {
                title = "Returning to the iceberg", needed = { "50 of each: bright, flickering, gleaming, and sparkling energy" },
                steps = {
                    {
                        text = "Return to the iceberg.",
                        npcs = {},
                        subs = {
                            { text = "Head to a pier north of Fremennik Province lodestone and north-east of Rellekka, travel to the Iceberg via the smaller boat." },
                        },
                    },
                    {
                        text = "Head north-east of the iceberg to Jim and right click \"Tuxedo-Time\".",
                        npcs = {},
                    },
                    {
                        text = "Re-enter the bunker via the Mysterious Hatch.",
                        npcs = {},
                    },
                    {
                        text = "In the centre of the bunker, talk to Elon to give him all the items.",
                        npcs = {},
                    },
                    {
                        text = "Fill the energy container to the north-west with your divination energy.",
                        npcs = {},
                    },
                    {
                        text = "Configure the battery control station, north-west.",
                        npcs = {},
                    },
                    {
                        text = "Solve the puzzle. See the full guide for advice on solving the puzzle.",
                        npcs = { "Back to the Freezer" },
                    },
                    {
                        text = "Once complete, speak to the following penguins, in order:",
                        npcs = {},
                        subs = {
                            { text = "Elon, in the same (central) room, roaming around T.A.R.D.I.S." },
                            { text = "Gordon, in the south-west room (northern part)." },
                            { text = "Hugh roaming around the north-west room." },
                            { text = "Emperor Wing, in the central room again, easy to recognise due to his size." },
                        },
                    },
                    {
                        text = "Click the T.A.R.D.I.S. in the centre for a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Return to Chuck.",
                        chat = "1 Back to the Freezer Quest",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "bar_crawl_miniquest", name = "Bar Crawl (miniquest)", wiki = "Bar Crawl (miniquest)/Quick guide",
        required = { "208 coins to buy all the required liquor" },
        recommended = { "Food to recover from beer that inflicts damage.", "Unlocked Lodestone Network or teleportation runes", "Restore potions to restore skills that are lowered", "Games necklace", "Grand seed pod" },
        sections = {
            {
                title = "Getting started", needed = { "Games necklace for quick travel to the Barbarian Outpost" },
                steps = {
                    {
                        text = "Talk to barbarian guard located east of Barbarian assault.",
                        chat = "1 I want to come through this gate. / 2 Looks can be deceiving, I am in fact a barbarian. / Accept",
                        npcs = { "barbarian guard", "Barbarian assault" },
                    },
                    {
                        text = "Bars are marked with on the world map. It may be helpful to turn off other map icons so that it is easier to locate the bars during the miniquest.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Visiting the bars", needed = { "208 gold coins, barcrawl card" },
                steps = {
                    {
                        text = "Go to the 2nd floor of the Grand Tree and talk to Blurberry. You can use Home Teleport to Al Kharid and then take the Gnome Glider to the Tree Gnome Stronghold, Ardougne lodestone and run north-west, or Eagles' Peak lodestone with 61 Agility and head east.",
                        chat = "Any",
                        npcs = { "Grand Tree", "Blurberry", "Home Teleport", "Ardougne lodestone", "Eagles' Peak lodestone" },
                    },
                    {
                        text = "Home Teleport to, and then visit the Forester's Arms. Talk to the Bartender.",
                        chat = "3 I'm doing Alfred Grimhand's Barcrawl.",
                        npcs = { "Forester's Arms" },
                    },
                    {
                        text = "Home Teleport to, then proceed to the Flying Horse Inn, located directly north of Ardougne castle. Talk to the Bartender.",
                        chat = "3 I'm doing Alfred Grimhand's Barcrawl.",
                        npcs = { "Flying Horse Inn" },
                    },
                    {
                        text = "Home Teleport to, and then visit the Dragon Inn. Talk to the Bartender.",
                        chat = "4 I'm doing Alfred Grimhand's Barcrawl.",
                        npcs = { "Dragon Inn" },
                    },
                    {
                        text = "Home Teleport to. Run north and then east until you reach the Dead Man's Chest. Talk to the Bartender.",
                        chat = "4 I'm doing Alfred Grimhand's Barcrawl.",
                        npcs = { "Dead Man's Chest" },
                    },
                    {
                        text = "Home Teleport to. Run north-east to the Rusty Anchor. Talk to the Bartender.",
                        chat = "1 I'm doing Alfred Grimhand's Barcrawl.",
                        npcs = { "Rusty Anchor" },
                        subs = {
                            { text = "If you do not have Visions of Havenhythe started then", chat = "2 Talk about something else. / 1 I'm doing Alfred Grimhand's Barcrawl." },
                        },
                    },
                    {
                        text = "Run south and 'Travel Karamja' on Captain Tobias just east of the lodestone. Run west to the pub and talk to Zembo.",
                        chat = "3 I'm doing Alfred Grimhand's Barcrawl.",
                        npcs = { "Captain Tobias", "Zembo" },
                    },
                    {
                        text = "Home Teleport to and run north to the Blue Moon Inn. Talk to the Bartender.",
                        chat = "4 I'm doing Alfred Grimhand's Barcrawl.",
                        npcs = { "Blue Moon Inn" },
                    },
                    {
                        text = "Home Teleport to and head south-west to the Jolly Boar Inn. Talk to the Bartender.",
                        chat = "4 I'm doing Alfred Grimhand's Barcrawl.",
                        npcs = { "Jolly Boar Inn" },
                    },
                    {
                        text = "Home Teleport to and go to the Rising Sun Inn. Talk to Emily or Kaylee.",
                        chat = "2 I'm doing Alfred Grimhand's Barcrawl.",
                        npcs = { "Rising Sun Inn", "Emily", "Kaylee" },
                    },
                    {
                        text = "Return to the Barbarian Outpost, ideally by using a games necklace, and talk to the Barbarian guard.",
                        npcs = { "Barbarian Outpost" },
                    },
                    {
                        text = "Miniquest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = { "Bar Crawl (miniquest)" },
                steps = {
                },
            },
        },
    },
