    {
        key = "battle_of_the_monolith", name = "Battle of the Monolith", wiki = "Battle of the Monolith/Quick guide",
        required = {},
        recommended = { "Archaeology journal (For easy teleport to the start & replays of the quest)", "TokKul-Zo (For quick teleport to the TzHaar City during the third battle of the quest)", "Combat gear and food" },
        sections = {
