    {
        key = "big_chompy_bird_hunting", name = "Big Chompy Bird Hunting", wiki = "Big Chompy Bird Hunting/Quick guide",
        required = { "Feathers (100+ to be safe, 25 can be bought during quest for )", "4-6 wolf bones (can be obtained during the quest)", "4-6 achey tree logs (can be obtained during the quest)" },
        recommended = { "Ring of duelling", "Gnome glider network", "Dramen staff or A Fairy Tale III - Battle at Ork's Rift completed (fairy ring AKS – fastest way to start)", "Armour and weapons (recommended if you're a low level as there are level 11 Wolves to be encountered)", "Ranged armour otherwise accuracy of shot damage will be considerably reduced" },
        sections = {
