                    {
                        text = "Use 6 ogre arrows on Rantz.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Bloated toads", needed = {},
                steps = {
                    {
                        text = "Ask Rantz all possible questions.",
                        chat = "1 How do we make the chompys come? / 2 What are 'fatsy toadies'? / 3 Where do we put the fatsy toadies? / 4 What do you mean 'sneaky..sneaky, stick da chompy?' / 5 Ok, thanks.",
                        npcs = {},
                    },
                    {
                        text = "Enter the cave north of Rantz.",
                        npcs = {},
                    },
                    {
                        text = "Unlock the Locked Ogre chest in the north-west corner, then search it to receive ogre bellows.",
                        npcs = { "Locked Ogre chest", "ogre bellows" },
                    },
                    {
                        text = "Exit the cave and run a short distance south-west to the swamp.",
                        npcs = {},
                    },
                    {
                        text = "At the swamp, fill bellows via the swamp bubbles, then bloat 3 nearby swamp toads for 3 bloated toads.",
                        npcs = { "swamp bubbles", "Swamp toad (creature)", "bloated toad" },
                    },
                },
            },
            {
                title = "Hunting", needed = {},
                steps = {
                    {
                        text = "Remove any Armour/Augmented Armour this will stop you from killing Chompy",
                        npcs = {},
                    },
                    {
                        text = "Talk to Rantz.",
                        npcs = {},
                    },
                    {
                        text = "Drop a bloated toad where the arrow points and wait for a chompy to appear.",
                        npcs = {},
                        subs = {
