                    },
                    {
                        text = "Talk to Klaas.",
                        chat = "1 I spoke to Meike. She vouched for you. / Any",
                        npcs = { "Klaas" },
                    },
                    {
                        text = "Don't forget to judge all the dwarves and make sure they are gone. Otherwise you won't find Veldaban in the cave later on.",
                        npcs = {},
                    },
                    {
                        text = "Return to King Veldaban.",
                        chat = "1 I've dealt with the suspected spies. / 1 Vigr said the Red Axe broke off contact with him. / 2 Goodbye.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Taverley chaos dwarves", needed = { "Combat equipment" },
                steps = {
                    {
                        text = "Go to the Taverley Dungeon and kill chaos dwarves (south of the Lesser demons) until Ikadia the Exile appears.",
                        npcs = { "Taverley Dungeon", "Chaos dwarf", "Lesser demon", "Ikadia the Exile" },
                    },
                    {
                        text = "After she talks to you and teleports away, go to the chaos druid circle in the north-eastern corner of the dungeon and talk to her.",
                        chat = "2 I am ready.",
                        npcs = {},
                    },
                    {
                        text = "Defeat her and talk to her again.",
                        chat = "Any / Any",
                        npcs = {},
                    },
                },
            },
            {
                title = "Yanille's Watchtower Wizard", needed = { "No Summoning familiar, 5 backpack spaces" },
                steps = {
                    {
                        text = "Go to the Yanille's Watchtower",
                        npcs = { "Watchtower (building)" },
                        subs = {
                            { text = "Use Watchtower Teleport or Watchtower teleport tablet" },
                            { text = "Alternatively, teleport to Yanille lodestone to Yanille and use the northern shortcuts to go under the north wall (requires 16 Agility) then west outside the northern wall" },
                            { text = "If you do not have the Watchtower quest completed, Climb-up the Trellis on the northern side of the Watchtower." },
                        },
                    },
                    {
                        text = "Dismiss any Summoning familiar you have, and talk to the Watchtower Wizard on the top floor.",
                        chat = "3 King Veldaban sent me... / Any / 1 I'm ready.",
                        npcs = { "Watchtower Wizard" },
                        subs = {
                            { text = "You'll be given a memory wand. Keep the wand for the rest of the quest, do not destroy it." },
                        },
                    },
                    {
                        text = "Use the wand on the 4 floating objects.",
                        npcs = {},
                    },
                    {
                        text = "Catch all the loose memory fragments. There will be 16 fragments total, 4 of each type.",
                        npcs = {},
                    },
                    {
                        text = "Investigate each memory void. Based on the text that appears, use the corresponding memory fragment on the memory void following the table below:",
                        npcs = {},
                        subs = {
                            { text = "Kebab — Walking stick, spiky hair, twirly moustache." },
                            { text = "Beer — What would a Gnome be doing here?" },
                            { text = "Beer — I wonder where he got that scar." },
                            { text = "Kebab — It's not natural for a dwarf to look like that." },
                        },
                    },
                    {
                        text = "After the cutscene, return to King Veldaban.",
                        chat = "1 I investigated Taverley dungeon. / Any / 1 I got a wand from the Watchtower Wizard. / 2 I'll keep hold of it. / 2 I'll meet you in the Barendir caves.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The assault on the Red Axe", needed = { "Food, sign of life, run enhancing items, 1 backpack space" },
                steps = {
                    {
                        text = "Enter the Barendir caves southeast of west Keldagrim. The caves can be accessed by selecting \"Travel\" on the Dwarven Boatman on the eastern side of Keldagrim near the northern bridge, or selecting \"Cross-river\" on the Dwarven Ferryman to the south of western Keldagrim.",
                        npcs = { "Barendir", "Dwarven Boatman", "Dwarven Ferryman" },
                        tile = { x = 2877, y = 10119, plane = 0 },
                    },
                    {
                        text = "Proceed to the north end of the tunnel and enter the cave at the end.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Veldaban. If Veldaban isn't there, make sure the cave with suspects is empty.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Nulodion. He'll give you explosive gears.",
                        npcs = { "Nulodion", "explosive gear" },
                    },
                    {
                        text = "Fire the cannon. This part is not a safe death. Should you die, your gravestone will be a short walk inside the Barendir caves.",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene, stand behind the pillars to get the cannons to shoot them down, and sabotage the cannons as you progress. The first one is to the west. Do not stand near a cannon if it is about to explode, as it will hit for 5,000+ damage. Praying against range is strongly recommended.",
                        npcs = {},
                    },
                    {
                        text = "After destroying all 5 cannons, walk up onto the platform with Colonel Grimsson.",
                        npcs = { "Colonel Grimsson" },
                    },
                    {
                        text = "Pull the lever that's on top of the platform above the minecart, then get into the mine cart.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Repairing the memories", needed = { "3 backpack spaces, memory wand" },
                steps = {
                    {
                        text = "After getting in the cart, there will be a cutscene and you will end up in another memory.",
                        npcs = {},
                    },
                    {
                        text = "Use the Memory wand on the royal Red Axe standard (flag, west of Veldaban), the Zamorakian Chaplain, and the chaos dwarf standing next to him.",
                        npcs = {},
                    },
                    {
                        text = "Catch all the loose memory fragments. There will be 9 fragments total, 3 of each type.",
                        npcs = {},
                    },
                    {
                        text = "Investigate each memory void. Based on the text that appears, use the corresponding memory fragment on the memory void following the table below:",
                        npcs = {},
                        subs = {
                            { text = "Chaos dwarf — He doesn't want to be here. — Conscript" },
                            { text = "Zamorakian chaplain — Guthix won't help us now. — Guthixian chaplain" },
                            { text = "Red Axe Standard — Eight coloured segments on a flag. — Consortium Standard" },
                        },
                    },
                    {
                        text = "Talk to Veldaban. You will then be put into the next memory.",
                        npcs = {},
                    },
                    {
                        text = "In the next memory, use the wand on the two trolls directly next to Grimsson (each provide 6 memory fragments) and repeat the memory fragment process following the table below:",
                        npcs = {},
                        subs = {
                            { text = "Dwarf Bone — Broken rocks. — Dwarf Bone" },
                            { text = "Small troll — He doesn't want to be here. — Conscript" },
                        },
                    },
                    {
                        text = "Talk to Grimsson (his dialogue won't appear while he's busy fending the trolls).",
                        npcs = {},
                    },
                    {
                        text = "In the next memory, use the wand on Zamorak and repeat the memory fragment process.",
                        npcs = { "Zamorak" },
                    },
                    {
                        text = "In the next memory, use the wand on the 3 dwarves, catch the memory fragments only when they're not labelled \"dangerous\", and repeat the process following the table below:",
                        npcs = {},
                        subs = {
                            { text = "Old Dwarf — Walking stick, spiky hair, twirly moustache." },
                            { text = "Grumpy Dwarf — I wonder where he got that scar." },
                            { text = "Beardless dwarf — What would a gnome be doing here?" },
                        },
                    },
                },
            },
            {
                title = "Veldaban of the Red Axe", needed = { "Combat equipment" },
                steps = {
                    {
                        text = "Kill Grunsh or let him go.",
                        npcs = {},
                    },
                    {
                        text = "Enter the eastern doorway behind King Veldaban, then enter the palace and go up to the 2nd floor.",
                        npcs = {},
                    },
                    {
                        text = "Try to open the door with the chaos dwarf behind it.",
                        npcs = {},
                    },
                    {
                        text = "Right click and talk to one of the directors.",
                        chat = "4 My friend here would like to join the Red Axe.",
                        npcs = {},
                    },
                    {
                        text = "Kill 7 of the 8 directors.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the remaining director.",
                        npcs = {},
                    },
                    {
                        text = "Go upstairs to the top floor of the palace.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The final confrontation", needed = { "No follower" },
                steps = {
                    {
                        text = "Talk to Grimsson and begin the fight.",
                        chat = "3 All right, Grimsson - bring it on.",
                        npcs = {},
                    },
                    {
                        text = "Kill Grimsson. If Veldaban dies, you will respawn outside the cave and need to re-enter and try again from the start.",
                        npcs = {},
                    },
                    {
                        text = "Kill Chaos Grimsson. Try to lure and isolate him on the side with the stairs, just outside the main room. When his adrenaline bar fills up and he's about to charge you, go down the stairs and wait for 10 seconds before coming back up.",
                        npcs = { "Colonel Grimsson" },
                    },
                    {
                        text = "Kill Chaos Hreidmar.",
                        npcs = { "Hreidmar" },
                    },
                    {
                        text = "Either kill or save Veldaban.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Speak with any director.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "blood_runs_deep", name = "Blood Runs Deep", wiki = "Blood Runs Deep/Quick guide",
        required = { "Rope (obtained during the quest)", "Weapons for the Melee, Ranged and Magic combat styles", "All four elemental spells: Blast, Wave, or Surge spells recommended" },
        recommended = { "Food", "Prayer potions", "Armour that provides minimal penalties to Ranged or Magic but still has good defensive properties. Hybrid armour is recommended because style switching is required", "Dwarf multicannon" },
        sections = {
            {
                title = "The sick man's dream world", needed = { "One free inventory space, combat gear" },
                steps = {
                    {
                        text = "Talk to Baba Yaga on Lunar Isle about the man in the bed.",
                        chat = "1 Talk about the man in the bed. / Accept / 1 Is there anything we can do? / 1 Yes? / 1 An excellent idea!",
                        npcs = { "Baba Yaga", "Lunar Isle" },
                    },
                    {
                        text = "Talk to Baba Yaga again to go to the Dream World.",
                        chat = "1 Talk about the man in the bed. / 1 I am ready. / 1 I've no idea. / 1 I think I've got it.",
                        npcs = {},
                    },
                    {
                        text = "Listen Silas.",
                        chat = "1 He's crazy.",
                        npcs = { "Silas" },
                    },
                    {
                        text = "Search the bookcase to obtain a prophecy tablet.",
                        npcs = { "Prophecy tablet (lighthouse)" },
                    },
                    {
                        text = "Climb the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Eavesdrop-on Silas and continue through the tunnel.",
                        chat = "1 She didn't count on us finding out.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Silas.",
                        chat = "1 I'm a friend of your nephew.",
                        npcs = {},
                    },
                    {
                        text = "Read Our Lives.",
                        chat = "1 What do you mean, 'not working'?",
                        npcs = { "Our Lives" },
                        subs = {
                            { text = "Prepare to face multiple (4-7) Dagannoth and Wallasalki at a time. This will go on for a few minutes." },
                            { text = "Do not use your dwarf multicannon in this area or you will lose it." },
                        },
                    },
                },
            },
            {
                title = "The Dagannoth attack", needed = {},
                steps = {
                    {
                        text = "Talk to Baba Yaga to be teleported to Rellekka.",
                        chat = "1 Talk about the man in the bed. / 1 What is? / 2 I'm ready. What's your trick?",
                        npcs = {},
                        subs = {
                            { text = "Prepare to face many Dagannoth." },
                        },
                    },
                    {
                        text = "After killing sufficient Dagannoth, Brundt the Chieftain will command you to get onto his boat.",
                        npcs = { "Brundt the Chieftain" },
                    },
                    {
                        text = "Talk to Queen Sigrid.",
                        chat = "1 What is the matter, Your Majesty? / 1 I'll set out right away.",
                        npcs = { "Queen Sigrid" },
                    },
                    {
                        text = "Talk to Brundt to get another seal of passage.",
                        chat = "2 I'll go with you.",
                        npcs = { "seal of passage" },
                    },
                },
            },
            {
                title = "Saving King Vargas", needed = {},
                steps = {
                    {
                        text = "Bank before teleporting to Waterbirth. Bring prayer potions and a full load of food. Leave 1 space empty.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Jarvald (on the western pier) and select the option Travel-Waterbirth to head to Waterbirth Island. If he says he's not taking you, you will have to talk to him first and get to the option where you ask \"Can I come?\"",
                        npcs = { "Jarvald", "Waterbirth Island" },
                    },
                    {
                        text = "Talk to Bardur near the cave entrance for a rope.",
                        chat = "1 What kind of voices? / 1 Could it be an old man echoing from underground?",
                        npcs = { "Bardur" },
                    },
                    {
                        text = "Make your way to the southwestern tip of the island and tie the rope on the hole.",
                        npcs = {},
                    },
                    {
                        text = "Climb-down the hole.",
                        npcs = {},
                    },
                    {
                        text = "Talk to King Vargas.",
                        chat = "1 We aren't out yet. / 1 Come on, this isn't the King Vargas I'm used to. / 1 No, I can imagine. / 1 Certainly, I've got some here.",
                        npcs = { "King Vargas" },
                    },
                    {
                        text = "Lead King Vargas down the path to the north-east and go down the ladder.",
                        npcs = {},
                        subs = {
                            { text = "Don't get too far ahead of King Vargas in the tunnels, or the dagannoth will get him and return him to the first chamber meaning you will have to start over. Staying close to King Vargas also ensures he will not be attacked so you won't have to feed him any food. It's recommended to turn off run while escorting King Vargas." },
                        },
                    },
                    {
                        text = "Continue to the far-east side of the next tunnel, past the small obelisk, and climb up the ladder.",
                        npcs = { "small obelisk" },
                    },
                    {
                        text = "The next ladder to climb up is to the west, in this short tunnel dagannoth will spawn that prioritise attacking King Vargas, make sure you attack them so they will focus their attacks on you instead.",
                        npcs = {},
                    },
                    {
                        text = "Make your way through the last two short tunnels with rock lobsters and climb up the ladder.",
                        chat = "1 Well, as quickly as you can, please. / 1 Don't touch anything!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Fremennik spiritual realm", needed = {},
                steps = {
                    {
                        text = "Talk to Eir.",
                        chat = "1 Pardon? / 1 I'm not supposed to be here? / 1 Can you at least explain where I am? / 1 How do I get back then?",
                        npcs = { "Eir" },
                    },
                    {
                        text = "Talk to Nial Swiftfling.",
                        chat = "1 [Say nothing] / 1 The dagannoths are mounting a massive attack on nearby settlements. / 1 It's nothing I can't handle.",
                        npcs = { "Nial Swiftfling" },
                    },
                    {
                        text = "Talk to Asleif Hamalsdotter.",
                        chat = "1 Just passing through. / 1 You realise they're waiting for a huge battle? / 1 I don't recall that working out so well last time.",
                        npcs = { "Asleif Hamalsdotter" },
                    },
                    {
                        text = "Talk to Eir.",
                        chat = "1 Yes, please.",
                        npcs = {},
                        subs = {
                            { text = "If the spiritual realm sequence is interrupted, speak with Brundt in the long hall in Rellekka to obtain a letter. Read the letter to return." },
                        },
                    },
                    {
                        text = "Speak to Brundt the Chieftain.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Talk to King Vargas.",
                        chat = "Any / Any / Any / Any / Any / Any / Any / Any / 2 [Cut to the chase]",
                        npcs = {},
                    },
                    {
                        text = "Talk to Princess Astrid or Prince Brand.",
                        chat = "Any",
                        npcs = { "Princess Astrid", "Prince Brand" },
                    },
                    {
                        text = "Talk to Brundt to continue and bank.",
                        chat = "2 Actually, could you drop me off at the bank on Etceteria?",
                        npcs = {},
                        subs = {
                            { text = "Prepare for a fight with Dagannoth sentinels and the Dagannoth Mother (Blood Runs Deep)" },
                        },
                    },
                },
            },
            {
                title = "Waterbirth", needed = { "Balmung" },
                steps = {
                    {
                        text = "Talk to Brundt in the long hall in Rellekka when you are ready.",
                        chat = "2 Ask about the war against the daggermouths. / 1 Yes, let's go now.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Baba Yaga on the boat.",
                        chat = "1 [Say nothing] / 2 What do you think? / 1 Yes, I have. / 1 No, of course not! / 1 I'm ready.",
                        npcs = {},
                    },
                    {
                        text = "Climb down the hole on the southwestern tip of the island.",
                        npcs = {},
                    },
                    {
                        text = "Enter the southern tunnel.",
                        chat = "1 That sounds reasonable.",
                        npcs = {},
                    },
                    {
                        text = "Enter the next tunnel to fight the Dagannoth sentinels.",
                        chat = "1 Good luck.",
                        npcs = {},
                        subs = {
                            { text = "After defeating the sentinels, you can go to bank to get more food. You don't need to fight the sentinels again. Also you don't need the tablets or the seal of passage for the fights (saves you a few slots for food)." },
                        },
                    },
                    {
                        text = "Alternate attacks between the dagannoth, keeping their health within approximately 500 life points to prevent them from healing each other.",
                        npcs = {},
                        subs = {
                            { text = "High level players with good equipment can just kill one then the other, it is easy to deal more damage than the amount that they are healed." },
                            { text = "There is a common glitch that prevents you from attacking the second sentinel. In this case stand on top of the sentinel you cannot attack. This will prevent it from attacking or healing the first sentinel." },
                        },
                    },
                    {
                        text = "Continue to the next tunnel.",
                        npcs = {},
                    },
                    {
                        text = "Go to the south-east intersection and enter the tunnel entrance.",
                        npcs = {},
                        subs = {
                            { text = "Use the picture on the right for reference." },
                        },
                    },
                    {
                        text = "Proceed south and enter the tunnel.",
                        npcs = {},
                    },
                    {
                        text = "Go through the next tunnel and select either chat option.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Start the battle with Balmung (the special weapon you received from Brundt) and kill the Dagannoth Mother, switching styles according to her colour.",
                        npcs = {},
                        subs = {
                            { text = "If you have trouble telling between the colours (specially red/orange/yellow), you can use the chatbox. It will say \"The dagannoth changes to red...\" etc." },
                            { text = "White — Air spells, including Smoke spells" },
                            { text = "Blue — Water spells, including Ice spells" },
                            { text = "Brown — Earth spells, including Shadow spells" },
                            { text = "Red — Fire spells, including Blood spells" },
                            { text = "Orange — Melee attacks with Balmung or any slashing weapon" },
                            { text = "Green — Ranged attacks (officially weak to thrown)" },
                        },
                    },
                    {
                        text = "After the Dagannoth Mother has been defeated, go back to the previous room, collect the pickaxe, plank, and tinderbox and use them to collapse one of the pillars.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Eir.",
                        chat = "1 I seem to have died again. / 1 Yes, I am.",
                        npcs = {},
                    },
                    {
                        text = "Check the bodies and finish chat.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Talk with Baba Yaga and Koschei.",
                        npcs = { "Koschei" },
                    },
                    {
                        text = "Attempt to climb up the rope.",
                        chat = "Any / Any",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                    {
                        text = "Speak to Brundt to receive your reward.",
                        chat = "2 Ask about the war against the daggermouths.",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
