    {
        key = "bringing_home_the_bacon", name = "Bringing Home the Bacon", wiki = "Bringing Home the Bacon/Quick guide",
        required = { "5 wheat (can be obtained during the quest)", "10 backpack spaces" },
        recommended = { "Methods to get to East Ardougne, Draynor Village, Falador, Lumbridge, and Varrock.", "Lodestone Network activation", "Explorer's ring 3 or 4 (Falador cabbage patch), or skills necklace (Mining Guild)", "Dave's spellbook to create 'Chipped' Falador teleports", "Amulet of glory (Draynor)", "1 earth rune, 1 fire rune, 3 water runes, 9 air runes and 5 law runes for fast teleportation to Varrock, Ardougne, Falador and Lumbridge", "Construction materials to upgrade the machine after the quest", "Tier two: 3 oak planks, 2 steel bars and at least 3 nails. Requires 44 in each of Summoning, Crafting, and Construction.", "Tier three: 3 teak planks, 2 mithril bars, and at least 3 nails. Requires 84 in each of Summoning, Crafting, and Construction." },
        sections = {
            {
                title = "Protecting the pork", needed = {},
                steps = {
                    {
                        text = "Speak to Eli in Falador Farm north of Port Sarim.",
                        chat = "Accept",
                        npcs = { "Eli" },
                    },
                    {
                        text = "Eat the piece of bacon he gives you.",
                        chat = "~",
                        npcs = {},
                    },
                    {
                        text = "Make sure you have at least 3 (better 6) free inventory spaces or Eli won't be able to give you planks",
                        npcs = {},
                    },
                    {
                        text = "Speak to Eli again.",
                        npcs = {},
                    },
                    {
                        text = "During the cutscene, avoid clicking too fast through the dialogue or you will have to restart the cutscene.",
                        npcs = {},
