                    {
                        text = "Go through the world window",
                        npcs = { "world window" },
                    },
                    {
                        text = "Go slightly to the north then east to Kanatah.",
                        npcs = { "Kanatah" },
                    },
                    {
                        text = "Talk to Acca Kanatah.",
                        chat = "2 I've simply come to help. / 1 Talk about Call of the Ancestors. / 2 The airut are gathering to completely wipe out Kanatah. / 2 Ok, I'm done talking. What do I need to do?",
                        npcs = { "Acca Kanatah" },
                    },
                    {
                        text = "If you have a pet, dismiss it and go east to the beach and talk to Tunks for a cutscene.",
                        chat = "1 No problem.",
                        npcs = {},
                    },
                },
            },
