                    },
                    {
                        text = "Control Tunks and stand on the pressure plate on the centre platform.",
                        npcs = {},
                    },
                    {
                        text = "Control Lunch and pull the heavy block onto the south-eastern pressure plate. Stand on the north-eastern pressure plate to release Tunks.",
                        npcs = {},
                    },
                    {
                        text = "Control Tunks, jump the gap to the north.",
                        npcs = {},
                    },
                    {
                        text = "Control Lunch and walk around to stand on the north-eastern pressure plate.",
                        npcs = {},
                    },
                    {
                        text = "Control Tunks and stand on one of the north-western pressure plates.",
                        npcs = {},
                    },
                    {
                        text = "Control Peck and squeeze through the north-western gap.",
