        key = "catapult_construction", name = "Catapult Construction", wiki = "Catapult Construction/Quick guide",
        required = { "90 mithril nails (or better)", "10 mahogany planks (protean planks will not work)" },
        recommended = { "Level 56 Agility if entering forest from Port Tyras", "Access to the Tirannwn lodestone", "A charged amulet of glory or combat bracelet", "An arc journal for teleport outside the pub in Port Sarim and Thaki the delivery dwarf", "Some food and antipoison" },
        sections = {
