    {
        key = "children_of_mah", name = "Children of Mah", wiki = "Children of Mah/Quick guide",
        required = {},
        recommended = { "Level 110 Combat", "Combat equipment, food and potions are highly recommended", "TokKul-Zo or Portable fairy ring for quick access to fairy rings", "Sixth-Age circuit for quick access to World Gate", "Dig Site pendant or Archaeology journal", "Shard of Zaros", "Sign or Portent of life", "Be on the Ancient Magicks spellbook, for increased damage against the various Muspah encountered during the quest" },
