                    {
                        text = "Talk to Zamorak once more.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Pilgrimage to the ritual site", needed = { "Sixth-Age circuit, combat equipment, food, Shard of Zaros, sign of life or portent of life, 1-2 free inventory spaces to remove weapon and shield" },
                steps = {
                    {
                        text = "Go to the World Gate, dial Freneskae, and enter it (left click, select \"Children of Mah\").",
                        chat = "1 Children of Mah.",
                        npcs = { "World Gate", "Freneskae" },
                    },
                    {
                        text = "Optionally inspect the four Mahjarrat deathstones along the route for a master quest cape requirement.",
                        npcs = { "Mahjarrat deathstone", "master quest cape" },
                    },
                    {
                        text = "Talk to Kharshai.",
                        npcs = {},
                    },
                    {
                        text = "Unequip weapon(s) and jump on the rock. The first deathstone is before the first lava ride.",
                        chat = "1 Yes.",
                        npcs = {},
                        subs = {
                            { text = "Avoid taking damage using the keyboard or on-screen arrows." },
                            { text = "The mini-map can help you predict upcoming obstacles." },
                            { text = "The off-hand Enhanced Excalibur can be activated prior to departure, and will heal you during the ride." },
                        },
                    },
                    {
                        text = "Equip weapon(s) and attack muspahs until a grand force muspah appears.",
                        npcs = { "muspah", "grand force muspah" },
                    },
                    {
                        text = "Stand next to the interactable wall and attack it until its adrenaline bar fills and it destroys the wall with its special attack.",
                        npcs = {},
                    },
                    {
                        text = "Repeat in next area. (Note: There is a checkpoint right before the second river of lava)",
                        npcs = {},
                    },
                    {
                        text = "Heal up, un-equip weapon(s), and jump on the rock. The second deathstone is before the second lava ride.",
                        chat = "1 Yes.",
                        npcs = {},
                        subs = {
                            { text = "Avoid taking damage using the keyboard or on-screen arrows as before." },
                        },
                    },
                    {
                        text = "Talk to Seren. The third deathstone is to the east of Seren.",
                        chat = "Any / 2 [Continue...]",
                        npcs = { "Seren" },
                    },
                    {
                        text = "Enter the cave. The final deathstone is right before meeting with the mahjarrat.",
                        npcs = {},
                    },
                    {
                        text = "Go west and talk to Zemouregal.",
                        chat = "Any / 2 [Continue...] / 2 [Continue...] / 2 Stay silent.",
                        npcs = { "Zemouregal" },
                    },
                    {
                        text = "Watch or skip the cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Speak with Zaros.",
                        npcs = { "Zaros" },
                    },
                },
            },
            {
                title = "Mah's nightmares", needed = { "3 empty inventory spaces. Bank all your equipment and bring food. If you want to speed up this part, whenever you need to go up or down the northern path, teleport to the world gate and re-enter the quest instance." },
                steps = {
                    {
                        text = "Go up the northern path and talk to Seren at the end.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Investigate the core of Mah.",
                        npcs = { "core of Mah" },
                    },
                    {
                        text = "Intercept the shadows heading towards the core from the muspahs.",
                        npcs = {},
                        subs = {
                            { text = "Insert the glowing orb into the light shard between the core and the shadow heading towards it. The orb must be retrieved from the light shard it's in before it can be inserted into another." },
                        },
                    },
                    {
                        text = "Navigate the area by going from one circle of light to another.",
                        npcs = {},
                        subs = {
                            { text = "Touch the light shard at the end of the path." },
                            { text = "Go back half way and exit on Zemouregal." },
                        },
                    },
                    {
                        text = "Investigate the core and intercept the shadows as before. Two orbs will be given this time. Failing three times will result in the option to toggle an easier mode.",
                        npcs = {},
                    },
                    {
                        text = "Navigate the area using the circles of light as before.",
                        npcs = {},
                        subs = {
                            { text = "Touch the western light shard." },
                            { text = "Touch the eastern light shard." },
                            { text = "Touch the central light shard." },
                            { text = "Go south and exit on Seren." },
                        },
                    },
                    {
                        text = "Investigate the core and intercept the shadows as before. Three orbs will be given this time. If you're having issues completing this round, after three failed attempts, there will be an option for easy mode.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Talk to Seren.",
                        chat = "2 [Continue...]",
                        npcs = {},
                    },
                    {
                        text = "Go down the path and talk to Seren at the ritual site.",
                        chat = "2 [Continue...]",
                        npcs = {},
                    },
                    {
                        text = "Go back up the path and talk to Zaros.",
                        chat = "2 [Continue...]",
                        npcs = { "Zaros" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
