    {
        key = "city_of_senntisten", name = "City of Senntisten", wiki = "City of Senntisten/Quick guide",
        required = { "A cut dragonstone", "Combat gear", "A rock hammer (tool belt works)", "Ways to heal yourself (such as food and enhanced Excalibur)" },
        recommended = { "Archaeology journal to teleport to the Archaeology Guild", "Invitation box or Skeletal horror Teleport to teleport to Paterdomus", "Signs of the porter or a grace of the elves for banking Archaeology materials", "Powerburst of acceleration to reset Surge and Dive/Bladed Dive abilities", "The Heart teleport to teleport quickly to the Heart of Gielinor", "Skills necklace to the Crafting Guild near Armadyl's Tower", "Ring of respawn to teleport to White Knights' Castle" },
        sections = {
            {
                title = "Starting out", needed = {},
                steps = {
                    {
                        text = "Talk to Ariane at the entrance to the Heart of Gielinor and enter the Elder Halls.",
                        chat = "Accept / 1 Yes",
                        npcs = { "Ariane", "Heart of Gielinor" },
                    },
                    {
                        text = "Talk to Charos. Go through all chat options about what to do with the eggs.",
                        chat = "1 Could we destroy them? / 2 Could we drain them? / 3 Could we hide them? / 4 Could we fight the elder gods? / 5 Could we move them? / 4 I'm stumped.",
                        npcs = { "Charos" },
                    },
                    {
                        text = "Talk to Azzanadra, after which a cutscene will play.",
                        chat = "~",
                        npcs = { "Azzanadra" },
                    },
                    {
                        text = "Talk to Charos and Ariane.",
                        chat = "~",
                        npcs = {},
                    },
                    {
                        text = "Go to the Archaeology Guild, upstairs onto the balcony. Talk to Dr Nabanik.",
                        chat = "~",
                        npcs = { "Archaeology Guild", "Dr Nabanik" },
                    },
                    {
                        text = "Head to Armadyl's Tower. Climb to the top and talk to Armadyl.",
                        npcs = { "Armadyl's Tower", "Armadyl" },
                        subs = {
                            { text = "Teleport to Port Sarim lodestone and go north-west to the Armadyl's tower teleporter to teleport up to Armadyl's Tower." },
                            { text = "Alternatively, use an Archaeology teleport and choose Lowse from Collectors." },
                        },
                    },
                    {
                        text = "Go to Burthorpe Castle and climb up the stone staircase.",
                        chat = "1 Yes",
                        npcs = { "Burthorpe Castle" },
                    },
                    {
                        text = "Talk to Icthlarin south-east of the table.",
                        npcs = { "Icthlarin" },
                    },
                    {
                        text = "Talk to Seren west of the table.",
                        npcs = { "Seren" },
                    },
                    {
                        text = "Talk to Moia south of the table.",
                        chat = "1 Yes.",
                        npcs = { "Moia" },
                    },
                    {
                        text = "Talk to Zamorak.",
                        chat = "2 Er, help?",
                        npcs = { "Zamorak" },
                    },
                    {
                        text = "Go to the throne room on the 3rd floor (east side) of the White Knights' Castle and talk to Saradomin.",
                        chat = "1 City of Senntisten",
                        npcs = { "White Knights' Castle", "Saradomin" },
                    },
                    {
                        text = "Return to Dr Nabanik on the balcony of the main building at the Archaeology Guild.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Senntisten", needed = { "A mattock (tool belt works), a dragonstone, and 4 free inventory slots." },
                steps = {
                    {
                        text = "Enter the City of Senntisten through the ancient door to the north of the Archaeology Guild.",
                        chat = "1 Yes.",
                        npcs = { "Senntisten", "Ancient door (Senntisten)" },
                    },
                    {
                        text = "Excavate the forum entrance. (Use your grace of the elves charges to move the materials to the material storage container if you have it. Porters also work.)",
                        npcs = { "forum entrance", "grace of the elves", "material storage container", "Sign of the porter" },
                    },
                    {
                        text = "Interact with the pedestal to obtain Pontifex Maximus figurine (damaged).",
                        npcs = { "Pedestal (figurine)", "Pontifex Maximus figurine (damaged)" },
                    },
                    {
                        text = "Exit via the pulley.",
                        chat = "1 Yes.",
                        npcs = { "Pulley (City of Senntisten)" },
