        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to Brother Kojo at the Clock Tower located south-west on the path going south from Ardougne Zoo.",
                        chat = "Accept",
                        npcs = { "Clock Tower (building)", "Ardougne Zoo" },
                    },
                    {
                        text = "Go into the central room and down the ladder.",
