                    {
                        text = "Use the heather on the tea.",
                        npcs = {},
                    },
                    {
                        text = "Talk to 'The Guns'.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Fish Finding", needed = {},
