    {
        key = "dealing_with_scabaras", name = "Dealing with Scabaras", wiki = "Dealing with Scabaras/Quick guide",
        required = { "Equipment and high-healing food", "Ugthanki dung (requires a bucket, this is not consumed)", "10 unnoted gold artefacts from the Pyramid Plunder, including gold seals, golden scarabs, and golden statuettes", "1 pyramid top from the Agility Pyramid", "Up to 36 bronze gear or bronze bars (See distressing bronze gear)" },
        recommended = { "Level 60 Crafting", "Level 43 Prayer", "The higher your Agility, Thieving, Strength and combat levels are above the required levels, the easier and shorter the quest becomes", "Some waterskins", "Rope (for use on an optional agility shortcut)", "Coins for carpet rides", "Ring of charos for cheaper carpet rides", "Desert amulet 2 for unlimited teleports to Nardah", "Salve amulet to help damage the undead monsters", "3-6 logs lightable at your Firemaking level minus 20", "Keris to help damage scabarites and the giant scarab", "Antipoison or super antipoison", "Prayer potions", "Emergency teleport (such as ectophial)", "Summer pie or agility potion, super strength (See room settings)" },
        sections = {
            {
                title = "Running errands", needed = { "Rope" },
                steps = {
                    {
                        text = "Talk to the High Priest in Sophanem.",
                        chat = "1 What news? / Accept",
                        npcs = { "High Priest (Sophanem)", "Sophanem" },
                    },
                    {
                        text = "Climb the ladder behind the altar.",
                        npcs = { "Altar (Sophanem)" },
                    },
                    {
                        text = "After the cutscene, talk to Maisa.",
                        chat = "1 Why are you here?",
                        npcs = { "Maisa" },
                    },
                    {
                        text = "Talk to the High Priest.",
                        npcs = {},
                    },
                    {
                        text = "Go to the south-east of the Agility Pyramid, take the rope shortcut just to the east.",
                        npcs = { "Agility Pyramid", "Rope (Agility Pyramid)" },
                        subs = {
                            { text = "If you haven't unlocked this shortcut, enter to the swamp south-east of Sophanem and go north, then climb the fallen pillar and the low wall. Last, use the rope on the rock." },
                        },
                    },
                    {
                        text = "Climb over the low wall and talk to Lead archaeologist Abigail and Assistant archaeologist Kerner by the tents. Read their questions carefully and always round down the answer.",
                        chat = "1 I've had dealings with his sort before; feel free to test me.",
                        npcs = { "Lead archaeologist Abigail", "Assistant archaeologist Kerner" },
                    },
                    {
                        text = "Talk to them again for an empty crate.",
                        npcs = { "empty crate" },
                    },
                },
            },
            {
                title = "Distressing bronze gear", needed = { "Ugthanki dung, bronze gear, bucket (if you do not have Ugthanki dung)" },
                steps = {
                    {
                        text = "Fetch the bronze gear that are written in your quest journal.",
                        npcs = {},
                    },
                    {
                        text = "At this point, if you have 60 Crafting, continue with the section #Distressing by players|Distressing by players.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Distressing by archaeologists", needed = {},
                steps = {
                    {
                        text = "Use the bronze gear on the crate.",
                        npcs = {},
                    },
                    {
                        text = "Return to the archaeologists. This will take 3 hours so if 60 Crafting is achievable by any boosts within that time frame it is highly recommended to do that instead.",
                        chat = "1 Indeed, I am. / 1 Indeed, I would.",
                        npcs = {},
                    },
                    {
                        text = "Continue with the section #Collecting scabarite notes|Collecting scabarite notes.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Distressing by players", needed = {},
                steps = {
                    {
                        text = "While standing in the desert, use Ugthanki dung on the bronze items.",
                        npcs = { "Ugthanki dung" },
                    },
                    {
                        text = "Use the oxidized bronze items on the crate.",
                        npcs = {},
                    },
                    {
                        text = "Travel to Pollnivneach (Pollnivneach Teleport or Magic carpet network are easiest).",
                        npcs = { "Pollnivneach", "Pollnivneach Teleport", "Magic carpet" },
                    },
                    {
                        text = "Enter the kebab shop North-West of the well in the center of the town.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Isma'il the Kebab seller and purchase Red hot sauce",
                        chat = "3 Would you sell me that bottle of special kebab sauce?",
                        npcs = { "Isma'il the Kebab seller", "Red hot sauce" },
                    },
                    {
                        text = "Head to the building South-West.",
                        npcs = {},
                    },
                    {
                        text = "Go inside the fenced area with two Jasim the Camels.",
                        npcs = { "Jasim the Camel" },
                    },
                    {
                        text = "Use the Red hot sauce on the trough to the South.",
                        npcs = { "Red hot sauce" },
                    },
                    {
                        text = "Use a bucket on the dung produced by Jasim the Camel to get Ugthanki dung.",
                        npcs = { "Jasim the Camel", "Ugthanki dung" },
                    },
                    {
                        text = "While standing in the desert, use Ugthanki dung on the bronze items.",
                        npcs = { "Ugthanki dung" },
