            {
                title = "Collecting scabarite notes", needed = { "pyramid top, 10 Gold artefact, smelly crate" },
                steps = {
                    {
                        text = "Talk to Simon Templeton at the Agility Pyramid.",
                        chat = "1 Some archaeologists asked me to deliver some artefacts to you. / 1 I'd like to supply some gold objects from Pyramid Plunder. / 1 I'd like to supply a golden Agility Pyramid artefact. / 1 I'd like to supply a crate of bronze antiquities.",
                        npcs = { "Simon Templeton", "Agility Pyramid" },
                    },
                    {
                        text = "Talk to the archaeologists (back at the campfire along the shortcut to the east) for a book scabaras research.",
                        npcs = { "scabaras research" },
                    },
                    {
                        text = "Kill undead creatures nearby until you get 4 different scabarite notes. They should have different examine texts.",
                        npcs = { "scabarite notes" },
                        subs = {
                            { text = "Dried zombies and skeletons to the north." },
                            { text = "Mummies to the west." },
                            { text = "Locust lancers, rangers, scabaras lancers, and rangers in the swamp to the south-east." },
