            {
                title = "Dungeon puzzles", needed = { "logs according to your Firemaking level, antipoison, food" },
                steps = {
                },
            },
            {
                title = "Preparation", needed = {},
                steps = {
                    {
                        text = "This section is a race against time. Read it fully before continuing. You need to pass all challenges successfully in one go, otherwise you need to tell the clay golem to reset the levers so you can try again.",
                        npcs = { "Clay golem (Ullek)" },
                    },
                    {
                        text = "It is possible to empty the storage box of logs so you might need to bring your own in case you fail at first attempt. If you have a lower Firemaking level, you might not be able to stoke the furnace. For example, the storage box may give you magic logs, but if your Firemaking level is below 95, you won't be able to continue, unless you bring your own logs.",
                        npcs = { "storage box" },
                    },
                },
            },
            {
                title = "Challenges", needed = {},
                steps = {
                    {
                        text = "Use the logs on the furnace to stoke the furnace.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the golem.",
                        chat = "3 I am ready for you to operate the levers. / 4 Set the mysterious box room to the highest power. / 1 Set the empty room to the second highest power. / 2 Set the narrow walkway room to the second lowest power.",
                        npcs = {},
                    },
                    {
                        text = "Relight the furnace.",
                        npcs = {},
                    },
                    {
                        text = "Enter the narrow walkway room.",
                        npcs = {},
                        subs = {
                            { text = "Cross the pipe and pull the lever." },
                        },
                    },
                    {
                        text = "Enter the empty room.",
                        npcs = {},
                        subs = {
                            { text = "Pull the lever." },
                        },
                    },
                    {
                        text = "Enter the scarab room.",
                        npcs = {},
                        subs = {
                            { text = "Kill the level 92 giant scarab." },
                            { text = "Pull the lever." },
                        },
                    },
                    {
                        text = "Enter the mysterious box room.",
                        npcs = {},
                        subs = {
                            { text = "Investigate the mysterious mechanism to start the puzzle. Clicking outside of the interface will fail the attempt and you'll have to start the whole process over." },
                            { text = "Starting from the upper left corner, note the runes shown, flipping three runes in a row. Do this for all rows until all runes are noted. You should finish with 8 attempts left." },
                            { text = "Click on the cog, mechanical screw parts and dial (three areas) on the right side of the interface to receive an extra 15 attempts giving 23 in total. You only need a minimum of 12 attempts, if you don't make any mistakes." },
                            { text = "Flip the rune in the upper left corner. Use your notes to identify the locations of other matching runes and flip them over (You are matching groups of 3 runes). Continue until all runes have been flipped." },
                        },
                    },
                    {
                        text = "Once you have completed all 4 challenges in a row, it is possible to teleport out and restock without having to do them again.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Vault area", needed = { "antipoison, food" },
                steps = {
                    {
                        text = "Run to the High Priest of Scabaras in the north-west room in the dungeon. Disarm the traps along the way.",
                        npcs = { "High Priest of Scabaras" },
                    },
                    {
                        text = "Talk to the High Priest.",
                        chat = "2 Conversion, eh? / 2 I do not fear your pathetic beetle-brained magics.",
                        npcs = {},
                    },
                    {
                        text = "Defeat him.",
                        npcs = {},
                    },
                    {
                        text = "Talk to him again.",
                        chat = "4 By all the deities, what is going on here? / 1 I sense the hand of the Devourer in this. Am I correct?",
                        npcs = {},
                    },
                    {
                        text = "Defeat him.",
                        npcs = {},
                    },
                    {
                        text = "Talk to him once more.",
                        chat = "4 By all the deities, what is going on here? / 2 Sounds like the Devourer dragged you into heresy for her own ends.",
                        npcs = {},
                    },
                    {
                        text = "Defeat him.",
                        npcs = {},
                    },
                    {
                        text = "Talk to him once more.",
                        chat = "2 Conversion, eh? / 1 I sense the hand of the Devourer in this. Am I correct?",
                        npcs = {},
                    },
                    {
                        text = "Return to the High Priest in Sophanem.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
