        required = { "2 full sets of H.A.M. robes (hood, shirt, robe, gloves, boots, cloak, and logo). If obtaining them yourself, the chance to pickpocket outfit pieces is increased during the quest.", "A light source (such as a bullseye lantern)", "A melee, magic, or necromancy weapon or ability" },
        recommended = { "Non-Ranged armour and weapons, and food", "Lockpick", "Spiny helmet or a Slayer helmet. If you use this method, a rope may be needed if you have never ventured into the Lumbridge swamp caves before.", "Games necklace (only if Tears of Guthix has been completed)" },
        sections = {
