                    {
                        text = "Talk to the Lumbridge Sage right in front of the castle gate.",
                        npcs = { "Lumbridge Sage" },
                    },
                    {
                        text = "Take Zanik to a level 2 goblin across the east bridge.",
                        npcs = { "goblin" },
