                        npcs = {},
                    },
                    {
                        text = "If you have finished the Tears of Guthix quest, you can teleport there with her using a games necklace.",
                        npcs = { "Tears of Guthix (quest)", "games necklace" },
                    },
                    {
                        text = "Climb down the trapdoor in the Lumbridge castle, and squeeze through the hole in the cellar wall.",
                        npcs = {},
                    },
                    {
                        text = "Squeeze through the hole to the south, run south then jump across the stepping stones.",
                        npcs = {},
                    },
                    {
                        text = "Enter the tunnel to reach the Tears of Guthix cavern.",
                        npcs = { "Tears of Guthix cavern" },
                    },
                    {
                        text = "With Zanik in your inventory and both hands free, talk to Juna.",
                        npcs = { "Juna" },
                    },
                    {
                        text = "Collect 20 blue tears from the walls to trigger a cutscene.",
                        npcs = {},
                        subs = {
                            { text = "Green tears empty your bowl." },
                        },
                    },
                    {
                        text = "Talk to Zanik.",
                        npcs = {},
                    },
                },
            },
            {
                title = "To be continued...", needed = {},
                steps = {
                    {
                        text = "Prepare for the fight against Sigmund and his guards (but keep the H.A.M robes with you). Zanik is considered a follower. Pets and familiars cannot be used during the battle.",
                        npcs = {},
                    },
                    {
                        text = "Teleport to Lumbridge then enter the castle cellar.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Zanik and have her follow you.",
                        chat = "1 Let's go!",
                        npcs = {},
                    },
                    {
                        text = "Go to Seth Groats's farm on the east side of the river near the cow paddock, walk into the fenced area through the gap on the south side.",
                        npcs = { "Seth Groats" },
                    },
                    {
                        text = "Unequip any weapons or shields.",
                        npcs = {},
                    },
                    {
                        text = "Equip full H.A.M. set.",
                        npcs = {},
                    },
                    {
                        text = "Search one of the empty crates by the tree.",
                        chat = "1 I don't know, what are you thinking? / 1 Good idea.",
                        npcs = {},
                    },
                    {
                        text = "After Zanik climbs in the crate, carry it down into the trapdoor just north of the empty crates.",
                        npcs = {},
                    },
                    {
                        text = "Go west and walk up to Sigmund, instead of immediately clicking to attack him. You must trigger the dialogue with Sigmund in order to have Zanik attack him, which is needed to complete the quest.",
                        npcs = {},
                        subs = {
                            { text = "Kill the guards first. This allows Zanik to attack Sigmund who will then switch to Protect from Missiles." },
                            { text = "Kill Sigmund, who uses the Protect from Missiles prayer. If he's protecting against your attack style, avoid him so he switches back to Protect from Missile." },
                        },
                    },
                    {
                        text = "Smash the drilling machine at the centre of the room.",
                        npcs = {},
                    },
                    {
                        text = "Go east then south and unblock the tunnel for a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "defender_of_varrock", name = "Defender of Varrock", wiki = "Defender of Varrock/Quick guide",
        required = { "A light source", "Blurite ore (can be obtained during the quest from the ice cave near Thurgo)", "A spade", "Armour, weapons, and supplies to survive in the Wilderness" },
        recommended = { "Activated Edgeville, Falador, Port Sarim and Varrock lodestones", "Emergency teleport such as an ectophial, crystal teleport seed or a teleport tablet", "Salve amulet (e)", "A redberry pie, if you wish to gain an additional" },
        sections = {
            {
                title = "Tracking", needed = {},
                steps = {
                    {
                        text = "Dismiss any followers now.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Captain Rovin in Varrock Palace, on the floor of north-west tower.",
                        chat = "1 Ooh, good, sounds like a quest. / Accept / 1 Okay, let's get going.",
                        npcs = { "Captain Rovin", "Varrock Palace" },
                        subs = {
                            { text = "If he will not give you the quest, make sure you have claimed kudos from Historian Minas at Varrock Museum." },
                        },
                    },
                    {
                        text = "Enter the Graveyard of Shadows, then talk to Hartwin.",
                        chat = "1 I want to talk about the mission.",
                        npcs = { "Graveyard of Shadows", "Hartwin" },
                        subs = {
                            { text = "Make sure Hartwin is following you in this section." },
                            { text = "If you lose Hartwin for any reason, he can be found back at the Varrock Palace." },
                        },
                    },
                    {
                        text = "Inspect the tree stump just south of the west graveyard entrance (just south of the arch) to uncover more footprints.",
                        npcs = {},
                    },
                    {
                        text = "Follow the footprints and continue searching bushes, trees, stumps, mushrooms, and bones to uncover more footprints.",
                        npcs = {},
                        subs = {
                            { text = "Search the small forest of dead trees south of the Graveyard of Shadows, northwest of the Chaos Temple for a grubby key." },
                        },
                    },
                    {
                        text = "The trail eventually leads to Simon near the Chaos Temple.",
                        npcs = { "Simon" },
                    },
                    {
                        text = "Run south to the trapdoor, unlock it using the grubby key and climb down.",
                        npcs = { "Trapdoor (Chaos Temple Dungeon)" },
                    },
                },
            },
            {
                title = "Undead army", needed = { "combat equipment to kill six or more armoured zombies" },
                steps = {
                    {
                        text = "Run north and look over the balcony.",
                        npcs = {},
                    },
                    {
                        text = "Run west and take 3 bottles.",
                        npcs = {},
                    },
                    {
                        text = "Kill 3 armoured zombies, using the bottles on red mist to fill them.",
                        npcs = {},
                    },
                    {
                        text = "Proceed deeper into the cave through the door.",
                        npcs = {},
                    },
                    {
                        text = "Run north and kill 3 armoured zombies again, using the bottles on red mist to fill them.",
                        npcs = {},
                    },
                    {
                        text = "Go through the next door and look over another balcony.",
                        npcs = {},
                    },
                    {
                        text = "Hartwin will give you a Varrock teleport tablet to return to Varrock quickly.",
                        npcs = { "Varrock teleport (item)" },
                    },
                    {
                        text = "Return to Captain Rovin in Varrock.",
                        npcs = { "Captain Rovin" },
                    },
                },
            },
            {
                title = "The Sacred Forge", needed = { "blurite ore, light source, and a spade (tool belt does not work)" },
                steps = {
                    {
                        text = "Talk to Thurgo in Thurgo's Peninsula, south of Port Sarim lodestone, north of fairy ring AIQ. or if you have 99 Smithing.",
                        chat = "3 I'd like to ask about the Shield of Arrav. / 4 I'd like to ask about the Shield of Arrav.",
                        npcs = { "Thurgo", "Thurgo's Peninsula", "Port Sarim lodestone", "Smithing" },
                        subs = {
                            { text = "If you don't have a blurite ore, now is the opportune time to mine one in the snowy area of the dungeon nearby." },
                        },
                    },
                    {
                        text = "Climb Ice Mountain, west of Edgeville.",
                        npcs = { "Ice Mountain", "Edgeville" },
                    },
                    {
                        text = "Dig with your spade 2 steps on east of the white tree, next to the material caches, near the dungeon icon.",
                        npcs = {},
                        tile = { x = 3010, y = 3498, plane = 0 },
                    },
                    {
                        text = "Dig the churned-up snow then enter the hole.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Ramarno.",
                        npcs = { "Ramarno" },
                        subs = {
                            { text = "If you have a redberry pie, give it to Ramarno for 1,000 Smithing experience.", chat = "1 Okay, here you go. / 4 I wish to use the Sacred Forge." },
                        },
                    },
                    {
                        text = "Use blurite ore on the forge.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Ramarno for a cutscene (note that pressing escape during the cutscene will reset it).",
                        npcs = {},
                    },
                },
            },
            {
                title = "Zombie invasion", needed = {},
                steps = {
                    {
                        text = "Return to Captain Rovin, ignoring the zombies. He gives you a restored shield.",
                        npcs = { "Captain Rovin", "restored shield" },
                    },
                    {
                        text = "Talk to Reldo in the library on the 1st floor.",
                        chat = "# I'd like to talk about the invading zombies.",
                        npcs = { "Reldo" },
                    },
                    {
                        text = "Read the Varrock Census on the lectern.",
                        npcs = { "Varrock Census" },
                    },
                    {
                        text = "Search the scrolls on the floor a few steps south after talking to Reldo about the situation.",
                        npcs = { "Scrolls (Defender of Varrock)" },
                    },
                    {
                        text = "Read the list of elders.",
                        npcs = { "list of elders" },
                    },
                },
            },
            {
                title = "Shield of Arrav", needed = {},
                steps = {
                    {
                        text = "Talk to the following NPCs until one mentions they are not a blood descendant:",
                        npcs = {},
                        subs = {
                            { text = "King Roald, southeast corner of the 1st floor or if the quest Lord of Vampyrium has been completed.", chat = "1 Talk about Zombies. / 2 Talk about Zombies." },
                            { text = "Aeonisig Raispher, next to King Roald.", chat = "1 Defender of Varrock. / 1 Talk about the zombie invasion." },
                            { text = "Sir Prysin, west of the king." },
                            { text = "Curator Haig Halen, in the Varrock Museum.", chat = "1 Talk about the zombie invasion." },
                            { text = "Horvik the smith north-east of Varrock Square.", chat = "2 Talk about the zombie invasion." },
