    {
        key = "desert_slayer_dungeon_miniquest", name = "Desert Slayer Dungeon (miniquest)", wiki = "Desert Slayer Dungeon (miniquest)/Quick guide",
        required = { "Full slayer helmet, slayer helmet, masked earmuffs or face mask. Having a slayer helmet stored on the slayer helmet stand also works.", "Leaf-bladed sword, spear or slayer staff with runes for slayer dart spell", "Mirror shield" },
        recommended = { "Level 43 Prayer", "Level 50 Magic", "Antipoison", "Restore potion", "Anti-poison totem" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Enter the well in Pollnivneach.",
                        npcs = { "Pollnivneach" },
                    },
                    {
                        text = "In the room with mighty banshees, pass the mystic barrier to the southwest and climb down the stairs. The quest is just about killing 4 bosses in their specific locations. Below is a recommended order.",
                        npcs = { "mighty banshee" },
                    },
                    {
                        text = "Mightiest turoth (SW - bottom left barrier)",
                        npcs = { "Mightiest turoth" },
                        subs = {
                            { text = "Use Slayer Dart and Protect from Melee prayer. If you stand far away from the Mightiest turoth, it will use Ranged-based attacks on you. Ignore the minions." },
                            { text = "If you choose to use melee, do not forget to bring a leaf-bladed spear or sword." },
                        },
                    },
                    {
                        text = "Kurask overlord (NW - top left barrier)",
                        npcs = { "Kurask overlord" },
                        subs = {
                            { text = "Use same strategies as above." },
                        },
                    },
                    {
                        text = "Basilisk boss (SE - bottom right barrier)",
                        npcs = { "Basilisk boss" },
                        subs = {
                            { text = "Use melee and wield the mirror shield." },
                            { text = "Use Protect from Magic prayer. Also watch your stats as they will be drained with each attack. Bring a restore potion." },
                            { text = "Take a dose of Super strength potion and Super attack potion, a Combat potion, or Super warmaster's potion to help." },
                        },
                    },
                    {
                        text = "Monstrous cave crawler (NE - top right barrier)",
                        npcs = { "Monstrous cave crawler" },
                        subs = {
                            { text = "Use melee and Protect from Ranged prayer. The poison from its ranged attack severely reduces the duration of any antipoison potions, including super antipoison. Every second or third hit poisons the player even with potions. An anti-poison totem will not work." },
                        },
                    },
                },
            },
        },
    },
    {
        key = "desert_treasure", name = "Desert Treasure", wiki = "Desert Treasure/Quick guide",
        required = { "Ashes", "Blood rune", "Bones", "Charcoal", "650 coins", "6 molten glass (can be noted)", "12 magic logs (can be noted)", "6 steel bars (can be noted)", "Cake (a slice, or full)", "Alternatively, chocolate cake, chocolate bar, cooking apple, or pineapple pizza", "Face mask (can be replaced by masked earmuffs, a slayer helmet, a full slayer helmet, or a gas mask)", "Garlic", "Up to 100 lockpicks (the lower your Thieving level, the more lockpicks you may require), hair clips, or a master thief's lockpick (which has no chance of breaking)", "Ice gloves or another method to defeat Fareed", "Silver bar (metal bank will not work)", "Spice", "Climbing boots for the Death Plateau Troll shortcut (or Trollheim Teleport or Trollheim tablet)", "Spiked boots for the Ice Path segment (made by bringing Dunstan an iron bar and climbing boots; rock climbing boots will not work)" },
        recommended = { "Level 47 Agility (to be able to pass certain obstacles on the way to Trollheim)", "Level 50 Mining (to obtain the ice gloves for the smoke diamond)", "A higher Thieving level is recommended for a higher chance of success", "Combat equipment (Magic or Necromancy recommended)", "Runes for casting your best fire and water spells if using Magic", "A few antipoisons", "Activated Burthorpe, Canifis, Draynor and Port Sarim lodestone", "Skills necklace for fast teleport to Rasolo.", "Finished In Search of the Myreque and Eadgar's Ruse for faster transportation", "Finished As a First Resort or have unlocked the tier 1 Spa in the Anachronia base camp for access to the salt-water spring, which can be useful for obtaining the Ice and Smoke diamonds", "About 1,500 coins for carpet rides", "Desert heat protection", "Single-click teleports (e.g. ectophial, or a teleport tablet) for escaping fights that turn for the worse", "A charged druid pouch or an ouroboros pouch", "Several energy/super energy potions or explorer's ring, prayer potions and restore potions", "An enchanted broomstick, Bandit Camp Teleports, Archaeology journal and/or a Dig Site pendant for quicker teleports to the desert and the Exam Centre" },
        sections = {
            {
                title = "Asgarnia Smith", needed = { "One backpack space" },
                steps = {
