                        subs = {
                            { text = "If he offers you a Codex Ultimatus, refuse it or talk to him again." },
                        },
                    },
                    {
                        text = "Talk to him again for the Translation.",
                        chat = "1 Ask about the Desert Treasure quest.",
                        npcs = { "Translation" },
