                },
            },
            {
                title = "Bandit Camp", needed = { "650 coins, 1 charcoal, 1 ashes, 1 bones, 1 blood rune, 6 steel bars (can be noted), 12 magic logs (can be noted), 6 molten glass (can be noted), translation, and one backpack space." },
                steps = {
                    {
                        text = "Return to Asgarnia Smith with the book.",
                        chat = "2 Don't read book",
                        npcs = {},
