                    {
                        text = "Talk to Asgarnia again and offer to help him.",
                        chat = "1 Help him",
                        npcs = {},
                    },
                    {
                        text = "Run south to the Bandit Camp.",
                        npcs = { "Bandit Camp (Kharidian Desert)" },
                        subs = {
                            { text = "If you're wearing any Zamorak or Saradomin equipment, bandits become aggressive." },
                        },
