            {
                title = "Blood diamond", needed = { "Garlic, silver bar, spice, food, air spells if using magic" },
                steps = {
                    {
                        text = "Enter the pub in Canifis. After a short cutscene, talk to Malak.",
                        chat = "5 I am looking for a special Diamond... / 1 Yes / 3 How can I kill Dessous? / 3 Actually, I don't need to know anything.",
                        npcs = { "Canifis", "Malak" },
                    },
                    {
                        text = "Take a silver bar and talk to Ruantun in the Draynor Sewers for a Silver pot.",
                        npcs = { "Ruantun", "Draynor Sewers", "Silver pot (empty)" },
                    },
                    {
                        text = "Take the pot to the High Priest on Entrana for a Blessed pot.",
                        npcs = { "High Priest (Entrana)", "Entrana", "Blessed pot (empty)" },
