            {
                title = "Ice diamond", needed = { "A sweet (cake, chocolate cake (partial cakes work), chocolate bar, cooking apple, or pineapple pizza), spiked boots, and climbing boots (or Trollheim Teleport or Trollheim tablet)." },
                steps = {
