                    {
                        text = "Take the path that leads to the snow area north-west of Troll Stronghold.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the troll child a few squares west of the ice gate.",
                        npcs = { "troll child" },
                        tile = { x = 2835, y = 3740, plane = 0 },
                    },
                    {
                        text = "Use a cake or a chocolate bar on him. Talk again to help him.",
                        chat = "1 Yes",
                        npcs = {},
                    },
                    {
                        text = "Enable Protect from Melee, and head east through the ice gate.",
                        npcs = { "Protect from Melee" },
                    },
                    {
                        text = "Kill 5 trolls, then travel through the cave entrance to your east and keep running.",
                        npcs = {},
                    },
                    {
                        text = "Kill Kamil when he appears.",
                        npcs = { "Kamil" },
                    },
                    {
                        text = "After you kill Kamil once, continue the path to the north and walk to the ice ledge. You can use Surge and Dive.",
                        npcs = { "Surge", "Dive" },
                    },
                    {
                        text = "Equip your spiked boots and climb the path to the top.",
                        npcs = {},
                    },
                    {
                        text = "Pass through the ice gate and across the bridge.",
                        npcs = {},
                    },
                    {
                        text = "Break the two ice blocks at the top (by casting a fire spell or choosing the \"smash-ice\" option).",
                        npcs = { "Ice block (Desert Treasure)" },
                    },
                    {
                        text = "Talk to the trolls, the child will give you the Ice diamond.",
                        npcs = { "Ice diamond" },
                    },
                    {
                        text = "Bank the ice diamond immediately. While holding the ice diamond, a stranger capable of dealing over 5,000 damage per attack can spawn at any time.",
                        npcs = { "ice diamond", "stranger" },
                    },
                },
            },
            {
                title = "Smoke diamond", needed = { "Face mask, masked earmuffs or slayer helmet, ice gloves" },
                steps = {
                    {
                        text = "Prepare for combat by bringing plenty of food, few super energy potions, melee gear, or water spells if using magic, or ice arrows if using ranged.",
                        npcs = { "super energy", "water spells", "ice arrows", "ranged" },
                        tile = { x = 3310, y = 2961, plane = 0 },
                    },
                    {
                        text = "Travel to Pollnivneach.",
                        npcs = { "Pollnivneach" },
                    },
                    {
                        text = "With your face mask and ice gloves equipped enter the Smoke Dungeon.",
                        npcs = { "face mask", "ice gloves", "Smoke Dungeon" },
                        subs = {
                            { text = "If Smoking Kills is complete the dungeon can be entered from the Pollnivneach well and through the dark stairs to the west." },
                            { text = "Otherwise the player can enter the smokey well which is located west of Pollnivneach." },
                            { text = "Killing a dust devil completes the achievement Drafty in Here." },
                        },
                    },
                    {
                        text = "Light the four standing torches, 1 in each corner of the dungeon. This part is timed and torches will go out if you are not fast enough.",
                        npcs = {},
                    },
                    {
                        text = "Consider using the Endurance relic power in place of energy potions to keep your run energy up.",
                        npcs = { "Endurance" },
                    },
                    {
                        text = "Open the burnt chest in the middle of the dungeon to receive a Warm key.",
                        npcs = { "Warm key" },
                        subs = {
                            { text = "Each torch will remain lit for exactly 5 minutes, and you will receive a game message when each one dies out. You will be unable to open the chest if any of the torches have gone out, even if you have lit all 4 torches before attempting." },
                        },
                    },
                    {
                        text = "With the warm key, open the gate on the eastern side of the dungeon.",
                        npcs = { "warm key" },
                    },
                    {
                        text = "Defeat Fareed for the Smoke diamond.",
                        npcs = { "Fareed", "Smoke diamond" },
                        subs = {
                            { text = "You must use melee, ranged, necromancy, or water spells." },
                            { text = "You must wear ice gloves to wield a main-hand weapon while fighting him, including staves and bows. Off-hand weapons are not restricted." },
                            { text = "While ranged weapons are effective on Fareed, any ammunition used by auto-attacks besides ice arrows will drop beneath him as ashes, bypassing the ammo-saving effect of Ava's accumulator." },
                        },
                    },
                    {
                        text = "Bank the smoke diamond immediately. While holding the smoke diamond, a stranger capable of dealing over 5,000 damage per attack can spawn at any time.",
                        npcs = { "smoke diamond", "stranger" },
                    },
                },
            },
            {
                title = "Shadow diamond", needed = { "Lots of lockpicks, hair clips, or a master thief's lockpick, earth spells if using magic. See each section for more info." },
                steps = {
                },
            },
            {
                title = "Ring of visibility", needed = {},
                steps = {
                    {
                        text = "Travel to Rasolo.",
                        chat = "3 Ask about the Diamonds of Azzanadra / 1 Yes",
                        npcs = { "Rasolo", "Ardougne lodestone" },
                    },
                },
            },
            {
                title = "Stealing the cross", needed = { "Waterskins, lots of lockpicks, hair clips, or a master thief's lockpick" },
                steps = {
                    {
                        text = "Return to the desert Bandit Camp.",
                        npcs = { "Bandit Camp (Kharidian Desert)" },
                    },
                    {
                        text = "Unlock the secure chest in the southern-most tent. You might consume between 10 to 100 lockpicks.",
                        npcs = {},
                        subs = {
                            { text = "Hair clips are very useful here, as you can reclaim them from Merlin for free." },
                            { text = "You can steal from the level 54 Bandits around the camp to get lock picks and antipoison." },
                            { text = "Master thief's lockpick also works and will never break." },
                            { text = "Five finger discount upgrades help." },
                        },
                    },
                },
            },
            {
                title = "Getting the diamond", needed = { "Gilded cross, combat equipment, earth spells if using magic" },
                steps = {
                    {
                        text = "Prepare for combat before returning the cross to Rasolo who will give you a ring of visibility.",
                        npcs = { "ring of visibility" },
                    },
                    {
                        text = "Equip the ring, run into the nearby triangular fenced area and climb down the ladder. You may equip any other ring now as this was only required to see the invisible ladder.",
                        npcs = {},
                    },
                    {
                        text = "Run east to Damis and kill him in both phases for the Shadow diamond.",
                        npcs = { "Damis", "Shadow diamond" },
                        subs = {
                            { text = "If Damis despawns, run a small distance back from where you came, then run back." },
                        },
                    },
                    {
                        text = "Bank the shadow diamond immediately. While holding the shadow diamond, a stranger capable of dealing over 5,000 damage per attack can spawn at any time.",
                        npcs = { "shadow diamond", "stranger" },
                    },
                },
            },
            {
                title = "Jaldraocht Pyramid", needed = { "All 4 diamonds" },
                steps = {
                    {
                        text = "Make sure your weight is less than 5 or you'll keep failing traps.",
                        npcs = {},
                        subs = {
                            { text = "Boots of lightness and any other weight reducing equipment helps." },
                        },
                    },
                    {
                        text = "Return to the Bandit Camp, and head directly south of Eblis to the pyramid.",
                        npcs = { "Jaldraocht Pyramid" },
                    },
                    {
                        text = "Use the diamonds on the obelisks surrounding the pyramid.",
                        npcs = { "Obelisk (Jaldraocht Pyramid)" },
                        subs = {
                            { text = "Blood diamond in the north-west obelisk." },
                            { text = "Shadow diamond in the south-west obelisk." },
                            { text = "Ice diamond in the south-east obelisk." },
                            { text = "Smoke diamond in the north-east obelisk." },
                        },
                    },
                    {
                        text = "Climb down the ladder at the top of the pyramid.",
                        npcs = {},
                    },
                    {
                        text = "Run through the pyramid using the map. Don't stand still, or you may be transported back to the start.",
                        npcs = {},
                        subs = {
                            { text = "There's a possibility that scarabs spawn in Azzanadra's room so bring a weapon, antipoison, and some more food just in case." },
                        },
                    },
                    {
                        text = "Talk to Azzanadra.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "Bandit Camp",
                        npcs = { "Bandit Camp (achievement)" },
                    },
                    {
                        text = "Desert Treasure",
                        npcs = { "Desert Treasure (achievement)" },
                    },
                    {
                        text = "Buying Up Ancient Artefacts",
                        npcs = { "Buying Up Ancient Artefacts" },
                        subs = {
                            { text = "You can buy an ancient staff from Eblis for coins, once. If you lose the staff, you will have to kill mummies inside the pyramid or in the Chaos Tunnels to get another one, or purchase a new one at the Grand Exchange for coins." },
                        },
                    },
                    {
                        text = "Varrock achievements",
                        npcs = { "Varrock achievements" },
                        subs = {
                            { text = "Hard - Living on the Edge" },
                        },
                    },
                    {
                        text = "Morytania achievements",
                        npcs = { "Morytania achievements" },
                        subs = {
                            { text = "Hard - Huge Success" },
                        },
                    },
                    {
                        text = "Desert achievements",
                        npcs = { "Desert achievements" },
                        subs = {
                            { text = "Hard - Ice-Cold Killer" },
                            { text = "Elite" },
                            { text = "Staff on Stryke" },
                            { text = "A, B, Cithara" },
                            { text = "Sun Shade" },
                            { text = "Damis, Fareed, Kamil and Dessous need to be killed in the Dominion Tower." },
                        },
                    },
                    {
                        text = "Tirannwn achievements",
                        npcs = { "Tirannwn achievements" },
                        subs = {
                            { text = "Easy - Casting Shadows" },
                            { text = "Hard - Cadarn Tootin'" },
                        },
                    },
                },
            },
        },
    },
