    {
        key = "desperate_measures", name = "Desperate Measures", wiki = "Desperate Measures/Quick guide",
        required = { "100 orthenglass (Can be stored in material storage container. Can also be obtained during quest from Anachronia north excavation site.)", "The Measure (Obtained during quest if not in bank or inventory. Fate of the Gods not required.)" },
        recommended = { "Level 95 Combat", "Archaeology journal for quick access to an archaeologist's workbench", "Teleports for Burthorpe, e.g. Slayer cape to Turael/Spria, combat bracelet, ring of respawn, Burthorpe lodestone", "Phoenix Lair Teleport or memory strand teleport for quick access to the Piscatoris Fishing Colony", "The Heart teleport tablet or desert amulet 2 for quick access to the Heart of Gielinor", "Grace of the elves necklace for quick access to Anachronia Dinosaur Farm if a skill portal in the Max Guild is attuned (or any other means to travel to Manor Farm)", "Around 10 empty inventory spaces for orthenglass and artefacts discovered while excavating" },
        sections = {
            {
                title = "Finding the dragonkin artefacts", needed = { "2 backpack spaces, 100 orthenglass in material storage (can be obtained from Anachronia north excavation site during quest, recommended to bring multiple sign of the porters if collecting there)" },
                steps = {
                    {
                        text = "Speak to Seren on the 2nd floor of Burthorpe Castle (north of the lodestone).",
                        chat = "Any / Accept / Any",
                        npcs = { "Seren", "Burthorpe Castle", "Burthorpe lodestone" },
                    },
                    {
                        text = "Head to Anachronia to speak with Mr Mordaut in the base camp.",
                        chat = "1 Anachronia. / 1 Ask about Desperate Measures.",
                        npcs = { "Anachronia", "Mr Mordaut", "Anachronia base camp" },
                    },
                    {
                        text = "Go north of the base camp, and down the two flights of stairs to the dragonkin gate. Do not begin the Agility course.",
                        npcs = {},
                    },
                    {
                        text = "Dismiss any pets or followers and then speak with Thok or Charos.",
                        chat = "1 Yes.",
                        npcs = { "Thok of Daemonheim", "Charos" },
                    },
                    {
                        text = "Inside the flashback, go to Charos. Finish all dialogue before continuing else you will exit the flashback and have to start over.",
                        npcs = {},
                    },
                    {
                        text = "Smash the feral dinosaurs.",
                        npcs = {},
                    },
                    {
                        text = "Continue east along the path, attacking more dinosaurs as you go.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Laniakea and then follow her across the bridge. After Kerapac leaves, finish the conversation with Charos.",
                        chat = "1 Not much. / 3 [Leave]",
                        npcs = { "Laniakea", "Kerapac" },
                    },
                    {
                        text = "Uncover and excavate the Dragonkin remains (Desperate Measures)",
                        npcs = {},
                    },
                    {
                        text = "Restore the dragonkin device at an archaeologist's workbench.",
                        npcs = { "dragonkin device" },
                    },
                    {
                        text = "Talk to Charos.",
                        chat = "4 [Leave]",
                        npcs = {},
                    },
                    {
                        text = "Excavate the orthen rubble spot, which appears about three paces north of him, to obtain a dragonkin tablet (damaged).",
                        npcs = { "Orthen rubble (Desperate Measures)", "dragonkin tablet (damaged)" },
                        subs = {
                            { text = "If you do not have enough orthenglass, you can destroy the tablet and excavate again." },
                        },
                    },
                    {
                        text = "Restore the dragonkin tablet at an archaeologist's workbench.",
                        npcs = { "dragonkin tablet" },
                    },
                    {
                        text = "Talk to Charos.",
                        chat = "5 [Leave]",
                        npcs = {},
                    },
                },
            },
            {
                title = "Nodon hibernatorium shared memory", needed = { "Dragonkin device, Dragonkin tablet" },
                steps = {
                    {
                        text = "Head to the Anachronia Dinosaur Farm (from the Manor Farm, go to the top floor of the manor and teleport using the mystical tree).",
                        npcs = { "Anachronia Dinosaur Farm", "Manor Farm", "mystical tree" },
                    },
                    {
                        text = "Speak to Hannibus next to Prehistoric Potterington.",
                        chat = "5 [Leave]",
                        npcs = { "Hannibus", "Prehistoric Potterington" },
                    },
                    {
                        text = "Travel to the Nodon Hibernatorium on the north-eastern coast of Anachronia, east of the Herby Werby entrance and south-east of the Observation outpost.",
                        npcs = { "Nodon Hibernatorium", "Herby Werby", "Observation outpost" },
                    },
                    {
                        text = "Enter the southern door next to Hannibus using the dragonkin device you restored earlier.",
                        npcs = {},
                    },
                    {
                        text = "Talk with Hannibus inside.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Speak with Hannibus again to start a memory.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Eventually, one of the Nodon caretakers will walk to the south-eastern corner of the room. Wait for the Nodon caretaker to finish putting in the passcode on the pylon, and you will be able to cycle the symbols.",
                        npcs = {},
                        subs = {
                            { text = "You must first click on the pylon in the shared memory." },
                            { text = "Talk with Hannibus to exit the dream.", chat = "2 No. / 1 Yes." },
                        },
                    },
                    {
                        text = "Cycle each of the three symbols outside of the dream until they match what you saw in the dream. Your character will interrupt when a symbol is input correctly. Continue that dialogue instead of exiting the chat box, otherwise, Hannibus won't recognise the correct sequence.",
                        npcs = {},
                    },
                    {
                        text = "Re-enter the dream and start the shared dream again. This time, follow the other dragonkin outside.",
                        npcs = {},
                    },
                    {
                        text = "Follow him until he walks to the door at the front of the ruins and speak a passphrase. Not being close enough to the door will cause you to miss the passphrase.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Hannibus again and exit the dream (you can lobby and log back to go faster). Return to the front of the ruins and enter the door with the passphrase you heard earlier (should be in the chat box).",
                        npcs = {},
                    },
                },
            },
            {
                title = "The Kindra council memory", needed = {},
                steps = {
                    {
                        text = "Inside the front door, speak with Hannibus again to enter another shared dream. If the room is empty it means you actually do not have the right code, even if you cannot change it.",
                        chat = "1 Yes.",
                        npcs = {},
                        subs = {
                            { text = "Ensure you rotated three characters on the pylon; one on the left, one on the right, and one in the centre. May need to zoom in to see. Hannibus should also be now standing in front of the door, he wasn't before. Each character will confirm a prompt once it is in the correct position. There will be 3 dialogue confirmations total." },
                        },
                    },
                    {
                        text = "Speak with Hannibus, next to a water pool, inside the dream to start a shared memory.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Skip the cutscene on Kerapac's device.",
                        npcs = {},
                    },
                    {
                        text = "Attack Kerapac until he flies off or watch your party of NPCs try to fight him. It may take about 1 minute. No damage will be done to or by you in the fight.",
                        npcs = {},
                    },
                    {
                        text = "Return and talk to Seren in Burthorpe.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Primrose located in the house by the Needle (far west of the Piscatoris Fishing Colony).",
                        npcs = { "Primrose", "the Needle", "Piscatoris Fishing Colony" },
                        subs = {
                            { text = "The nearest fairy ring is AKQ." },
                            { text = "Memory strand can also be used to teleport to Memorial to Guthix, which is south of the house." },
                        },
                    },
                    {
                        text = "Talk to Primrose and exhaust all chat options (focus on finding the needles weakness). Your quest log should update to speak to Seren.",
                        chat = "1 Ask about Desperate Measures. / 1 Ask how she's doing. / 1 Ask about the Needle / 1 Can the Needle be destroyed? / 1 Can the Needle be counteracted? / 2 Does the Needle have any weaknesses? / 4 Ask about Gail. / 1 Was she vulnerable to anything? / 1 What was it like being her? / 4 [Leave]",
                        npcs = {},
                    },
                    {
                        text = "Return to Seren.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Meeting Jas", needed = { "1 backpack space" },
                steps = {
                    {
                        text = "Make your way to Heart of Gielinor in the Kharidian Desert. (The Heart teleports can be used, or travel to Nardah using the magic carpet network and run south-west). Alternatively, the nearest fairy ring is DLQ, then run south.",
                        npcs = { "Heart of Gielinor", "Kharidian Desert", "The Heart teleport", "Nardah", "magic carpet" },
                    },
                    {
                        text = "Speak with Seren outside the Heart.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Jas about Kerapac.",
                        chat = "1 [Ask about Kerapac.] / 2 Can you intervene? / 1 Why not? / 1 Point out her power.",
                        npcs = { "Jas" },
                    },
                    {
                        text = "Speak to Jas about the Needle.",
                        chat = "5 [Ask about something else.] / 2 [Ask about the Needle.] / 2 Can it be stopped?",
                        npcs = {},
                    },
                    {
                        text = "Ask for Jas' help then exit the dialogue. The Eye of Jas should be in your inventory.",
                        chat = "4 [Ask about something else.] / 1 Can you help?",
                        npcs = { "Eye of Jas" },
                    },
                    {
                        text = "Talk to Seren.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Dinosaur invasion", needed = { "Eye of Jas, nothing equipped in your main-hand and off-hand, or enough backpack space to unequip." },
                steps = {
                    {
                        text = "Return to the Anachronia base camp and speak with Charos near the lodestone.",
                        npcs = {},
                    },
                    {
                        text = "After Kerapac turns up, speak with Thok to start the fight. You can't be wielding anything in your hands.",
                        chat = "1 I'm ready.",
                        npcs = {},
                    },
                    {
                        text = "Follow the instructions set out when starting the fight with your team members (Hannibus, Thok, Charos, and Laniakea).",
                        npcs = {},
                        subs = {
                            { text = "If you get the message \"you need to finish speaking with Charos before you can start the encounter\", you also have to change Charos attack type (just choose closest), then you need to move Hannibus one square away and move him back to his original place." },
                            { text = "Keep them in their default positions, and stand two squares west of Charos. You should win without moving, but if you struggle then move your character around to get early hits on the bigger dinosaurs." },
                            { text = "If you exit dialogue with Charos too early you may need to reset the instance by right clicking Thok and clicking Leave." },
                        },
                    },
                },
            },
            {
                title = "Kerapac's laboratory", needed = { "The Measure (received in first step by speaking to Charos, if Fate of the Gods is not completed), Eye of Jas, 1 backpack space (2 if you didn't already have the Measure)" },
                steps = {
                    {
                        text = "After the fight is complete, speak with Charos next to the lodestone. Go north past the Anachronia Agility Course and speak with Charos once more. The Measure should be in your inventory after speaking to him—if not, it may be in your bank; you will need to speak with Charos again before proceeding.",
                        chat = "Any",
                        npcs = { "Anachronia Agility Course" },
                    },
                    {
                        text = "You have to use The Measure near Charos a total of four times in the ruined areas surrounding the volcano. He will speak to you automatically if done correctly. If anytime during this Charos disappears or you are unable to interact properly with him, log out and back in or try hopping worlds. Charos will be standing right at the spot you need to use The Measure at. When you arrive at one of the spots where Charos is at, place The Measure. After placing The Measure, it's unnecessary to fully finish speaking to Charos. Players may proceed to the next location.",
                        npcs = {},
                        subs = {
                            { text = "The first location is a bit north of the entrance where you talk to him." },
                            { text = "The second location is north of the lodestone. Start the Agility course, enter through the cave, cross the roots, and walk north till you reach the camouflaged jadinkos." },
                            { text = "The third location can be reached by teleporting to the Anachronia lodestone, then head west past the bridge and north-west past the arcane apoterrasaur until you reach the dragonkin ruins. Alternatively, players that have unlocked the Orthen teleportation device can teleport to the third location." },
                            { text = "The last location is directly east of the previous location, up a flight of stairs." },
                        },
                    },
                    {
                        text = "Prepare for combat.",
                        npcs = {},
                    },
                    {
                        text = "Speak with Charos again (north of the base camp). (If he is not there, step into the room north of Thok and step out again. He might appear in the northern room, if so, place a measure in front of him.)",
                        npcs = {},
                    },
                    {
                        text = "Enter Kerapac's laboratory. (An entrance will have spawned where you met Thok and Charos north of the base camp.)",
                        npcs = { "Kerapac's laboratory" },
                    },
                    {
                        text = "Enter the correct codes into the pylons on the four corners of the area, as given in the image on the right. The codes are the same for all players.",
                        npcs = {},
                        subs = {
                            { text = "The south-western room's solution is 2-1-4." },
                            { text = "The north-western room's solution is 7-1-5." },
                            { text = "The north-eastern room's solution is 4-1-6." },
                            { text = "The south-eastern room's solution is 3-1-4." },
                        },
                    },
                },
            },
            {
                title = "Black stone dragon", needed = { "A weapon to kill a level 91 version of the black stone dragon" },
                steps = {
                    {
                        text = "Enter the room to the north that has now opened up and prepare for a battle with the black stone dragon. (If you die while fighting the dragon, it is a safe death.)",
                        npcs = {},
                    },
                    {
                        text = "After defeating the dragon, talk to Kerapac when he appears.",
                        npcs = {},
                    },
                    {
                        text = "Choose any chat option, and after the cutscene, the lab will start to collapse and you will get a timer on your screen and have to escape. When you hit a dead end, turn around or interact with a nearby character to continue. Failing restarts the escape.",
                        npcs = {},
                        subs = {
                            { text = "If you get sent back out before talking to Kerapac or the escape sequence by logging out or being interrupted (such as conjures), you may re-enter Kerapac's lab to trigger the sequence again." },
                        },
                    },
                    {
                        text = "After escaping the lab and the following cutscenes, return to Seren in Burthorpe (requires 4 backpack spaces to collect reward).",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Post-quest rewards", needed = {},
                steps = {
                    {
                        text = "Players can upgrade their cosmic focus to the cosmic accumulator which provides 20% Sprite Focus instead of 10%.",
                        npcs = { "cosmic focus", "cosmic accumulator" },
                    },
                },
            },
        },
    },
    {
