    {
        key = "dimension_of_disaster", name = "Dimension of Disaster", wiki = "Dimension of Disaster/Quick guide",
        required = { "1 coin", "652 zemomarks beforehand to purchase items listed below for all subquests", "Must be on the standard spellbook and prayerbook", "Obtained during quest:", "2 zemomarks", "Cabbage", "Rotten tomato", "Beer glass", "90 Zemomarks or", "Black hood", "Black robe top", "Black robe bottom", "Black mushroom", "Vial", "Dog hair", "500 zemomarks or", "Zombie mask", "Zombie shirt", "Zombie trousers", "Zombie gloves", "Zombie boots", "Vial", "3 tin ore or 60 zemomarks", "4 fire runes (or a fire staff)", "1 nature rune or 372 zemomarks", "2 vials of water", "Raw onion", "Ring of life or 582 zemomarks" },
        recommended = {},
        sections = {
            {
                title = "Coin of the Realm", needed = { "Coin of the Realm is a starter quest needed to complete in order to access all of the subquests." },
