            {
                title = "Subquests", needed = {},
                steps = {
                    {
                        text = "Locations:",
                        npcs = {},
                        subs = {
                            { text = "Shield of Arrav — Orlando Smith, in the Varrock Museum — Shield of Arrav and Coin of the Realm — * 2 Zemomarks (optional)" },
                            { text = "Demon Slayer — Aris, in her tent — Shadow of the Storm, Demon Slayer, and Coin of the Realm — * Cabbage * Rotten tomato * Beer glass * Black hood * Black robe (top) * Black robe (bottom) * Black mushroom * Vial * Dog hair" },
                            { text = "Defender of Varrock — Reldo, in Varrock Castle — Defender of Varrock and Coin of the Realm — * Zombie mask * Zombie shirt * Zombie trousers * Zombie gloves * Zombie boots * Vial * 3 tin ore * 4 fire runes * 1 nature rune" },
                            { text = "Curse of Arrav — Arrav, in the Varrock Castle garden — The Curse of Arrav and all previous subquests — * Must be on the standard spellbook and prayer book. * Zombie mask * Zombie shirt * Zombie trousers * Zombie gloves * Zombie boots * Lockpick * Mith crossbow * Mith grapple * Darklight * Vial of purple mist (or Vial, Vial of water, Delphinium flower) * Vial of orange mist (or Vial, Vial of water, Raw onion) * Ring of life (or gold ore, diamond, 10 earth runes and 1 cosmic rune) * 11 Raw undead beef" },
                        },
                    },
                },
            },
