                        subs = {
                            { text = "Run off the platform when teleported to the centre and move out of the path of the smoke. It travels straight down the stairs." },
                            { text = "Stand near the boss when he summons darkness or you will take massive damage." },
                            { text = "Click rapidly to escape cocoons." },
