    {
        key = "do_no_evil", name = "Do No Evil", wiki = "Do No Evil/Quick guide",
        required = { "10 bananas", "6 teak planks", "10 bolts of cloth", "A spade (can be obtained during the quest)", "3 ropes", "3 knives", "1 uncut Sapphire (can be obtained during the quest)", "1 uncut Emerald (can be obtained during the quest)", "1 uncut Ruby (can be obtained during the quest)", "1 uncut Diamond (can be obtained during the quest)", "3 waterskin (4) (can be obtained during the quest)", "Any type of cat, kitten, or hellcat", "A desert shirt, desert robe, and desert boots", "Masked earmuffs or a slayer helmet for the first battle (a slayer helmet mounted on the slayer helmet stand works)", "Gorilla greegree", "Ring of charos (a)", "Ava's accumulator", "Monkeyspeak amulet", "Monkeyspeak amulet mould (can be purchased during the quest)", "Ghostspeak amulet (the hard Morytania achievements permanent ghostspeak effect will not work)", "Enough runes for 20+ casts of Ice Spells (excluding Ice Rush)", "At least 1,000 coins (11,000+ recommended)" },
        recommended = { "Desert amulet 2 for unlimited teleports to Nardah", "Pollnivneach Tablet, master constructor's outfit teleport to Pollnivneach house portal, or Slayer master cape teleport to Sumona for transportation to Pollnivneach", "Enlightened Amulet for Desert Bandit Camp Teleport allowing quick access to the Monkey Colony", "Pharaoh's Sceptre or Sceptre of the Gods for quick access to Sophanem by Jalsavrah teleport", "Portable fairy ring or access to fairy ring Network (Requires A Fairy Tale II - Cure a Queen or A Fairy Tale III - Battle at Ork's Rift for use without a lunar staff or dramen staff)", "TokKul-Zo and a ninja monkey greegree (small) for transportation to Ape Atoll or Ape Atoll Teleport (Level 64 Magic)", "Explorer's ring to restore Energy or Endurance relic power for unlimited Energy while delivering chimp ice", "Waterskins or an enchanted water tiara to survive the desert heat. Completing the Crocodile Tears quest grants immunity against desert heat.", "Completing the Eagles' Peak quest unlocks the eagle transport system which is a viable method of travelling.", "Level 100 Combat", "Armour and food", "Antipoisons" },
        sections = {
            {
                title = "Before starting the quest", needed = {},
                steps = {
                    {
                        text = "If you did not bring Leela to Senliten's tomb, speak to Leela in Draynor Village, who is just north of the northern fence line of the jail; she will teleport the player to Senliten. Leela can only be found there afterwards.",
                        npcs = { "Leela", "Senliten", "Draynor Village" },
                        subs = {
                            { text = "If you need to return later, you can pick the option to return to the Pharaoh Queen directly (without having to go through the pyramid)." },
                        },
                    },
                },
            },
            {
                title = "Senliten's concern", needed = { "Any kind of cat, kitten, or hellcat, 1,000 coins and desert survival equipment" },
                steps = {
                    {
                        text = "Talk to Senliten in Uzer Mastaba.",
                        chat = "2 Talk about Do No Evil. / 3 Where are you going with this? / Accept",
                        npcs = { "Senliten", "Uzer Mastaba" },
                        subs = {
                            { text = "Inside the pyramid east of fairy ring code DLQ or north-east of Nardah which is easily reached by using Desert amulet 2 or above." },
                        },
                    },
                    {
                        text = "Head to Sophanem and talk to Jex north of the Sphinx.",
                        chat = "2 Could you tell me more about the minor gods? / 4 Could you tell me more about Apmeken? / 1 Could you tell me more about Apmeken's connection with monkeys? / 2 Could you tell me more about Apmeken's followers? / 3 Could you tell me more about Apmeken's influence over the desert?",
                        npcs = { "Sophanem", "Jex", "Sphinx" },
                        subs = {
                            { text = "Players can right click on Coenus by the bridge (near the Menaphos lodestone) to pass through to Sophanem." },
                            { text = "To quickly enter the magic carpet network, use a charged amulet of glory and teleport to Al Kharid, or use a Desert amulet 2 to teleport to Nardah." },
                        },
                    },
                    {
                        text = "Drop your cat and talk to the Sphinx",
                        chat = "2 Can you tell me about the gods of the Menaphites? / 3 Tell me about the minor gods. / 4 Tell me about Apmeken.",
                        npcs = { "Sphinx" },
                    },
                    {
                        text = "Go back and talk to Senliten..",
                        chat = "2 Talk about Do No Evil.",
                        npcs = { "Senliten" },
                    },
                },
            },
            {
                title = "Three Wise Monkeys", needed = { "Any monkey greegree, a monkeyspeak amulet, at least 10 coins, and a lot of backpack space (20+ to make it easy in one try)." },
                steps = {
                    {
                        text = "Head to Ape Atoll and equip the monkey greegree and monkeyspeak amulet, then speak to three wise monkeys in the Temple of Marimbo (north-easternmost temple).",
                        chat = "1 I'm trying to take some of our kind back to the desert. / 1 Admit to being a human.",
                        npcs = { "Ape Atoll", "three wise monkeys", "Temple of Marimbo" },
                    },
                    {
                        text = "Fill your entire backpack with Green bananas by using take banana from the pile of bananas crate to the east and lay a trail to lure the guard to the crate (you can place bananas every few squares to ensure the guard does not give up. Key-binding the Green banana will make this step easier). You will have to go counter-clockwise around the building due to the large gorilla posted on the north side. See the full guide for advice on luring the guard efficiently.",
                        npcs = { "Green banana", "pile of bananas", "Do No Evil" },
                    },
                    {
                        text = "Return to the three wise monkeys and talk to them.",
                        npcs = { "three wise monkeys" },
                    },
                    {
                        text = "Remove your greegree and speak to them in human form.",
                        npcs = {},
                    },
                    {
                        text = "Equip your greegree and speak to them again.",
                        chat = "2 The baboon head. / 4 On the monkey's shoulder.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Awowogei, who is in the building south of the temple.",
                        chat = "1 To build the greatest monkey colony ever! / 5 Next. / 3 Choc ices from Nardah.",
                        npcs = { "Awowogei" },
                    },
                    {
                        text = "If you don't have a monkeyspeak amulet mould, Hamab's crafting stall sells one, which is needed for the next step.",
                        npcs = { "monkeyspeak amulet mould", "Hamab" },
                    },
                },
            },
            {
                title = "Chimp ice", needed = { "1,000 coins, Monkey greegree, rope, Monkeyspeak amulet, Monkeyspeak amulet mould, Ancient Magicks spellbook, runes for either Ice Burst, Ice Blitz, or Ice Barrage." },
                steps = {
                    {
                        text = "Talk to Rokuh in Nardah next to the fountain.",
                        chat = "1 Commission Awowogei's choc ice. / 1 Deal! / 2 So, if I don't teleport it won't melt?",
                        npcs = { "Rokuh", "Nardah" },
                        tile = { x = 3423, y = 3142, plane = 0 },
                    },
                    {
                        text = "You should receive one chimp ice. If it melts, right click on Rokuh to buy another. Click to stop it from melting. Higher level spells, like Ice Barrage, will last longer.",
                        npcs = { "chimp ice", "Rokuh" },
                        subs = {
                            { text = "Unlike standard ancient spell casting, you do not need a staff/wand and orb/book for this. Only the runes are enough." },
                        },
                    },
                    {
                        text = "Helpful things to keep in mind:",
                        npcs = {},
                        subs = {
                            { text = "Looking at the world map prevents the chimp ice from melting." },
                            { text = "If you are out of run energy, rest and pull up the world map." },
                            { text = "Talking to NPC's prevents the chimp ice from melting." },
                            { text = "Using transportation such as magic carpets and eagles prevents the chimp ice from melting." },
                        },
                    },
                    {
                        text = "Take the chimp ice to King Awowogei without teleporting (this route requires completion of Eagles' Peak. For a full list of routes, see the in-depth quest guide):",
                        npcs = { "Awowogei", "Eagles' Peak", "Do No Evil" },
                        subs = {
                            { text = "From Nardah, use the magic carpet to Uzer." },
                            { text = "Run north-west to the desert eagle lair located north of the Uzer Hunter area and north-east of the Dominion Tower. Enter the tunnel, and use the rope that spawns nearby on an eagle to be transported." },
                            { text = "Exit the cave via the north-west entrance and climb down the mountain." },
                            { text = "Run east into Tree Gnome Stronghold, up 2nd floor of the Grand Tree and find Daero to the east to travel to the Secret Hangar." },
                            { text = "Talk to Waydar to travel to Crash Island." },
                            { text = "Talk to Lumdo to travel to Ape Atoll. You get a checkpoint here where you can restart if the chimp ice melts." },
                            { text = "Run to King Awowogei. The chimp ice can't be frozen while transformed as a monkey, so choose your moments carefully. An easy method is to freeze it at the mahogany tree before the main gate, turn into a monkey, and enter the gate. Run east to the small obelisk across from the agility course and hide in the grass to freeze it again. Then turn back into a monkey, and run to King Awowogei." },
                        },
                    },
                    {
                        text = "Go to the wise monkeys and add them to the barrel.",
                        npcs = { "Three wise monkeys" },
                    },
                },
            },
            {
                title = "The colony", needed = { "ring of charos (a), Ava's accumulator, monkeyspeak amulet, monkey greegree, a spade, barrel of monkeys, a weapon to kill low-level enemies -- if you have a gem bag and wear the desert clothing set below you can bring the items from the next section to avoid bank travel." },
                steps = {
                    {
                        text = "Teleport to Bandit Camp in the Kharidian Desert",
                        npcs = { "Bandit Camp (Kharidian Desert)" },
                        tile = { x = 3226, y = 2984, plane = 0 },
                    },
                    {
                        text = "Head north-east around the cliff to the area shown here on the map (you need to be below the cliff) and release the monkeys (open the barrel).",
                        npcs = {},
                    },
                    {
                        text = "Equip Monkey Speak Amulet and talk to one of the Wise Monkeys.",
                        npcs = { "Three wise monkeys" },
