                    {
                        text = "Take the crate to and talk to Ava in Draynor Manor until you get Ava's alerter.",
                        chat = "5 Talk about making a metal detector.",
                        npcs = { "Ava", "Ava's alerter" },
                    },
                    {
                        text = "Pick up the spade in the easternmost room if you do not already have one.",
                        npcs = {},
                    },
                    {
                        text = "Go to the fountain in the south-western corner of the manor's grounds.",
                        npcs = {},
                    },
                    {
                        text = "Wear your Ava's alerter and walk two steps east from the dead tree that can be converted to a hidey-hole, just north-east of the fountain. Dig when it says Bwuk! Bwuk! Bwuk! Bwuk!",
                        npcs = { "Ava's alerter" },
                    },
                    {
                        text = "Return to Ava.",
                        chat = "5 Talk about Ava's alerter.",
                        npcs = { "Ava" },
                    },
                    {
                        text = "Teleport to Bandit Camp and in the area north-east of the monkey camp search for crates using the map. You should dig up 5 crates, repeat this until you receive bundle of carpets.",
                        npcs = { "Bandit Camp (Kharidian Desert)", "bundle of carpets" },
                        subs = {
                            { text = "If you obtain any uncut gems or noted waterskins, save them for the next step." },
                            { text = "If you discover a scarab, kill it and then dig again." },
