                    {
                        text = "Talk to the three wise monkeys twice for a book.",
                        npcs = { "three wise monkeys" },
                    },
                    {
                        text = "Read the book or at least open it.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Building the colony", needed = { "1 hammer & 1 saw (toolbelt works for both), 6 teak planks (protean planks and planks stored in the plank box will not work), 10 bolts of cloth, 1 rope, 1 uncut sapphire, 1 uncut emerald, 1 uncut ruby, 1 uncut diamond (gems are obtained during quest), 1 pair of desert boots, 1 desert robe, 1 desert shirt and 1 Monkeyspeak amulet, 10 noted bananas, 3 noted knives, 3 noted waterskins (4), and a spade. The desert equipment, knives and waterskins can be bought at the Bandit Camp general store nearby." },
                steps = {
                    {
                        text = "Clear Rubble from the four building spots in the colony.",
                        npcs = {},
