                        npcs = { "cramulet" },
                    },
                    {
                        text = "Talk to the ghost monkey.",
                        chat = "3 I must try to rescue them.",
                        npcs = { "dead monkey" },
                    },
                },
            },
            {
                title = "Leeuni", needed = { "masked earmuffs or a slayer helmet, a cramulet and combat gear." },
                steps = {
