        required = { "48 adamant bars or a set of", "Adamant full helm +2", "Adamant platelegs +2", "Adamant platebody +2", "Adamant armoured boots +2", "Adamant gauntlets +2" },
        recommended = { "Activated Falador lodestone" },
        sections = {
            {
                title = "Burial armour", needed = {},
                steps = {
                    {
                        text = "Speak to Doric in his hut north of Falador.",
                        chat = "1 Do you have any more Smithing tasks for me? / Accept",
                        npcs = { "Doric", "Doric's hut", "Falador" },
                    },
                    {
                        text = "Make an adamant burial set in the Artisans' Workshop located in southeast Falador.",
                        npcs = { "adamant burial set", "Artisans' Workshop" },
                        subs = {
                            { text = "You must make the \"burial set\" and not make the burial items individually." },
                            { text = "If the player has never made burial armour before they must first talk to Suak.. To make a burial set the player first needs to acquire:", chat = "2 How can I make burial armour?" },
                            { text = "Adamant full helm +2." },
                            { text = "Adamant platelegs +2." },
                            { text = "Adamant platebody +2." },
                            { text = "Adamant armoured boots +2." },
                            { text = "Adamant gauntlets +2." },
                            { text = "It is possible to buy all five armour pieces on the Grand Exchange to complete this task." },
                        },
                    },
                    {
                        text = "Talk to Suak.",
                        npcs = {},
                    },
                },
            },
        },
    },
