        required = {},
        recommended = { "Falador Teleport or activated Falador lodestone", "Luck of the Dwarves, ring of slaying, or access to fairy rings (code DKR or DKS). Alternatively, take the mining cart from the Dwarven Mine or the Grand Exchange trapdoor." },
        sections = {
