                        npcs = { "black guard warhammer (crushed)" },
                    },
                    {
                        text = "Talk to Santiri.",
                        chat = "1 I have your warhammer.",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "doric_s_task_viii_miniquest", name = "Doric's Task VIII (miniquest)", wiki = "Doric's Task VIII (miniquest)/Quick guide",
        required = { "Two backpack spaces", "20 necronium bars" },
        recommended = { "Falador Teleport or activated Falador lodestone" },
        sections = {
            {
                title = "The mysterious client", needed = {},
                steps = {
                    {
                        text = "Speak to Doric in his hut north of Falador.",
                        chat = "1 Do you have any more Smithing tasks for me? / Accept / 1 I'm sure it will be fine.",
