    {
        key = "dragon_slayer", name = "Dragon Slayer", wiki = "Dragon Slayer/Quick guide",
        required = { "An unfired bowl", "A Wizard's mind bomb", "A crayfish cage or lobster pot (tool belt does not work)", "A piece of silk", "To obtain one of the map parts, specifically map part (Lozar), you need to do one of the following:", "Bring 10,000 coins to buy it", "A weapon to kill Wormbrain. You can either use Telekinetic Grab or utilise area loot to obtain it.", "2,000 coins to purchase a boat", "3 regular planks", "90 steel nails (other metal nails will not work)", "An anti-dragon shield (will be obtained during quest) or super antifire potion" },
        recommended = { "Level 50 Combat", "Level 37 Prayer for Protect from Magic", "Activated Draynor, Edgeville, Port Sarim, and Varrock lodestones", "Food for the final battle", "Antifire to minimise damage", "Members may bring a combat bracelet to quickly teleport inside the Champions' Guild" },
        sections = {
            {
                title = "Starting out", needed = {},
                steps = {
                    {
                        text = "Talk to the Guildmaster in the Champions' Guild.",
                        chat = "2 Can I have a quest? / Accept",
                        npcs = { "Guildmaster", "Champions' Guild" },
                    },
                    {
                        text = "Talk to Oziach in the house directly north of the Edgeville lodestone.",
                        chat = "1 Can you sell me a rune platebody? / 1 The Guildmaster of the Champions' Guild told me. / 1 I thought you were going to give me a quest. / 1 A dragon, that sounds like fun.",
                        npcs = { "Oziach", "Edgeville" },
                    },
                    {
                        text = "Go back to the Guildmaster and talk about the map pieces to get the key, about protection against dragon breath, and about buying a boat.",
                        chat = "2 I talked to Oziach... / 1 How can I find the route to Crandor? / 1 Where is Melzar's Map piece? / 1 Where is Thalzar's Map piece? / 2 Where is Lozar's Map piece? / 3 Where can I find the right ship? / 2 How can I protect myself from the dragon's breath? / 3 Okay, I'll get going!",
                        npcs = {},
                    },
                },
            },
            {
                title = "First map part", needed = { "Maze key" },
                steps = {
                    {
                        text = "Go to Melzar's Maze by entering the tower entrance north-west of Rimmington.",
                        npcs = { "Melzar's Maze", "Tower entrance (Melzar's Maze)", "Rimmington" },
                    },
                    {
                        text = "Enter the door with the maze key.",
                        npcs = {},
                    },
                    {
                        text = "Kill the small zombie rat with the long tail, pick up the red key and use it on the north-west door, then go up the ladder.",
                        npcs = { "zombie rat", "Key (red)" },
                    },
                    {
                        text = "Kill the thin hooded ghost with the patterned robe to receive the orange key, go through the door second from the north on the eastern wall and climb the ladder.",
                        npcs = { "Ghost (Melzar's Maze)", "Key (orange)" },
                    },
                    {
                        text = "Kill the skeleton with the small round shield and pick up the yellow key. Use the key on the south-western most door and climb down until you get to the zombies.",
                        npcs = { "skeleton", "Key (yellow)" },
                    },
                    {
                        text = "Kill the zombies. One of them will drop a blue key. Pass through the blue door.",
                        npcs = { "Zombie (24)", "Key (blue)" },
                    },
                    {
                        text = "Kill Melzar the Mad, pick up the magenta key and pass through the magenta coloured door.",
                        npcs = { "Melzar the Mad", "Key (magenta)" },
                    },
                    {
                        text = "Kill the lesser demon, pick up the green key, and go through the green door.",
                        npcs = { "Key (green)" },
                    },
                    {
                        text = "Open the chest and search it for the map part.",
                        npcs = { "Chest (Melzar's Maze)", "Map part (Melzar)" },
                        subs = {
                            { text = "Note: Make sure you finish the dialogue, or you will not receive the map part." },
                        },
                    },
                },
            },
            {
                title = "Second map part", needed = { "Unfired bowl, wizard's mind bomb, lobster pot or a crayfish cage, and silk" },
                steps = {
                    {
                        text = "Talk to the Oracle on Ice Mountain.",
                        chat = "1 I seek a piece of the map to the island of Crandor.",
                        npcs = { "Oracle", "Ice Mountain" },
                    },
                    {
                        text = "Travel south into the dwarven mines. Find the room with a sealed door in the north-eastern area of the mine and use all the items on the \"Magic door\". (Unfired bowl, wizard's mind bomb, lobster pot or a crayfish cage, and silk)",
                        npcs = { "dwarven mines", "Bowl (unfired)", "wizard's mind bomb", "lobster pot", "crayfish cage", "silk" },
                    },
                    {
                        text = "Open the chest in the room and search for the second map part after opening. You need to click again to search after the dialogue, it does not automatically loot or search.",
                        npcs = { "Chest (Dragon Slayer, dwarven mines)", "Map part (Thalzar)" },
                    },
                },
            },
            {
                title = "Third map part", needed = { "Either 10,000 coins, or a halberd, Ranged, Magic or Necromancy weapon" },
                steps = {
                    {
                        text = "Head to Port Sarim Jail and talk to Wormbrain in the cell.",
                        npcs = { "Port Sarim Jail", "Wormbrain" },
                        subs = {
                            { text = "You may need to speak with the Guild Master at this point before you can attack Wormbrain." },
                        },
                    },
                    {
                        text = "There are two ways to obtain the third map part:",
                        npcs = { "Map part (Lozar)" },
                        subs = {
                            { text = "Talk to Wormbrain and pay him 10,000 coins for the map part.", chat = "1 I believe you've got a piece of map that I need. / 3 I suppose I could pay you for the map piece... / 2 Alright then, 10,000 it is." },
                            { text = "Attack Wormbrain and use the loot interface or Telekinetic Grab to get the map part that he drops. You may need to drop an item in order for the loot interface to open." },
                        },
                    },
                    {
                        text = "Use a map part on any one of the other parts to form the complete Crandor map.",
                        npcs = { "Crandor map" },
                    },
                },
            },
            {
                title = "Obtaining an anti-dragon shield", needed = {},
                steps = {
                    {
                        text = "Talk to Duke Horacio on the 2nd floor of Lumbridge Castle.",
                        chat = "1 I seek a shield that will protect me from dragonbreath. / 1 Elvarg, the dragon of Crandor island! / 1 Yes. / 2 So, are you going to give me the shield or not?",
                        npcs = { "Duke Horacio", "Lumbridge Castle" },
                        subs = {
                            { text = "You can also buy an anti-dragon shield from the Grand Exchange to skip this step entirely." },
                            { text = "If the dialogue option for the anti-dragon shield doesn't appear, you need to talk to the Guildmaster about protection from dragon fire" },
                        },
                    },
                },
            },
            {
                title = "Obtaining a ship", needed = { "Crandor map, 2,000 coins, 90 steel nails, 3 planks, and a hammer (tool belt works)" },
                steps = {
                    {
                        text = "If you haven't already, ask the Guildmaster in the Champions' Guild about the boat and the captain of the ship.",
                        npcs = {},
                    },
                    {
                        text = "In Port Sarim, buy the ship Lady Lumbridge from Klarense, by the Void knight Squire.",
                        chat = "4 I'd like to buy her. / 1 Yep, sounds good.",
                        npcs = { "Lady Lumbridge", "Klarense" },
                    },
                    {
                        text = "Repair the damaged deck of the ship.",
                        npcs = { "damaged deck" },
                    },
                    {
                        text = "Go to Draynor Village. In the house north-east of the bank talk to Ned.",
                        chat = "2 Talk about something else. / 1 You're a sailor? Could you take me to Crandor?",
                        npcs = { "Ned" },
                    },
                },
            },
            {
                title = "The fight", needed = { "Food, potions, combat equipment, anti-dragon shield" },
                steps = {
                    {
                        text = "Prepare the battle against Elvarg.",
                        npcs = { "Elvarg" },
                        subs = {
                            { text = "Melee is recommended due to how hit chances are calculated." },
                            { text = "Players with level 37 Prayer can use Protect from Magic." },
                        },
                    },
                    {
                        text = "Board your ship and talk to Ned. Tell him you're ready to sail to Crandor Isle.",
                        chat = "1 Yes, let's go!",
                        npcs = {},
                    },
                    {
                        text = "After crashing on the island, follow the light grey path around and up to the top of the mountain. Climb down the hole.",
                        npcs = {},
                    },
                    {
                        text = "Move past the skeletons until you see Elvarg behind a short wall of spikes protruding from the ground on the east.",
                        npcs = {},
                    },
                    {
                        text = "Before you climb over to Elvarg its advisable to open the shortcut in the wall south of the short wall.",
                        npcs = {},
                    },
                    {
                        text = "Climb over it and kill Elvarg.",
                        npcs = {},
                        subs = {
                            { text = "Wear your dragonfire protection before hopping over, or your stats will get drained resulting most likely in a failed kill." },
                            { text = "If you leave Crandor before killing Elvarg or opening the shortcut, you will need 3 planks and 90 steel nails to repair the ship to get back." },
                        },
                    },
                },
            },
            {
                title = "Conclusion", needed = {},
                steps = {
                    {
                        text = "Take Elvarg's head to Oziach in Edgeville.",
                        npcs = { "Elvarg's head", "Oziach" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "dream_mentor", name = "Dream Mentor", wiki = "Dream Mentor/Quick guide",
        required = { "3 different kinds of food: 6 of 1 type and 7 of 2 others for a total of 20 pieces.", "Purple sweets, roast potatoes, mince pies, yule logs, and mint cakes cannot be used; stackable foods, such as holy biscuits, will be counted as a single piece of food; cake can be used in all 3 pieces.", "An easy way to acquire the food items is to use the lodestone teleport to Port Sarim, which brings you right next to the Wydin's Food Store, and then lodestone teleport right back to Lunar Isle.", "Cabbages, onions, and raw potatoes can be found within Rellekka. To use fewer backpack space, you can fill the vegetables into empty sacks, or alternatively bring uncut pineapples.", "1 astral rune" },
        recommended = { "A good weapon and armour", "Food (bring the highest-healing food for your level)", "A ring of recoil can be useful, especially for players low on food", "Being on the Lunar spellbook and having runes for the NPC Contact spell" },
        sections = {
            {
                title = "A helping hand", needed = {},
                steps = {
                    {
                        text = "Enter the mine in the north-east area of Lunar Isle.",
                        npcs = { "Lunar Isle" },
                    },
                    {
                        text = "Crawl-through the cave entrance (quest minimap icon).",
                        npcs = {},
                    },
                    {
                        text = "Talk to the fallen man (close the interface when it appears).",
                        chat = "Accept",
                        npcs = {},
                    },
                    {
                        text = "Starting with one of your 7 item foods, feed him 4 food while cycling through your different foods.",
                        npcs = {},
                        subs = {
                            { text = "Starting with a food item of which you brought 7 items will ensure you do not run out of variety." },
                        },
                    },
                    {
                        text = "Talk to him again.",
                        chat = "1 Just don't worry. / 1 Of course.",
                        npcs = {},
                    },
                    {
                        text = "Feed him 4 more food as before.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Raising his spirit", needed = {},
                steps = {
                    {
                        text = "Talk to repeatedly to raise his spirits:",
                        npcs = {},
                        subs = {
                            { text = "Of the four chat options, choose the one that appears on the table below." },
                            { text = "Select the response according to the table." },
                            { text = "Repeat until a short cutscene plays and he sits up." },
                            { text = "You seem like a nice guy. — Just being honest." },
                            { text = "When we get out of here I'll buy you a drink! — Whatever and wherever you want - my treat." },
                            { text = "I'm very impressed you managed to get into this cave. — I would have given up personally." },
                            { text = "You'll survive this easily. — Think of all the places you can visit when you get out!" },
                            { text = "What are you going to do when you get out of here? — That's up to you. You could travel with me!" },
                            { text = "It's a good thing you have me to look after you. — Not that I'm bragging or anything." },
                            { text = "Not long now and you'll be back on your feet! — On whether you mind me helping you further." },
                            { text = "You're sounding much better. — If you need anything, just let me know." },
                            { text = "It's quite cosy in here. — The perfect environment for getting back on your feet!" },
                            { text = "You're very safe in this little cave. — The suqah will never fit through that tunnel." },
                            { text = "Just don't worry. — Of course." },
                            { text = "You're looking better now. — Well, you look and sound more lively." },
                            { text = "Are you looking forward to getting out? — That's the spirit!" },
                            { text = "Tell me a bit about yourself. — Fishing!" },
                        },
                    },
                    {
                        text = "Feed him 6 more food.",
                        npcs = {},
                    },
                    {
                        text = "Talk to him and raise his spirit as before until he stands up.",
                        npcs = {},
                    },
                    {
                        text = "Exit the cave and climb up the ladder.",
                        npcs = {},
                        subs = {
                            { text = "Or just use the Lunar Isle lodestone" },
                        },
                    },
                    {
                        text = "Talk to 'Bird's-Eye' Jack in the bank. You will need 1 free inventory space for Cyrisus's chest.",
                        npcs = { "'Bird's-Eye' Jack", "Cyrisus's chest" },
                    },
                    {
                        text = "Select the equipment he needs. The equipment is usually, but not always, dependent on your highest combat stats (Magic, Ranged, Melee):",
                        npcs = {},
                        subs = {
                            { text = "Melee: Dragon helm, Abyssal whip, Ahrim's robe top, Ahrim's robe skirt, Ranger boots" },
                            { text = "Ranged: Splitbark Helm, Karil's top, Torag's platelegs, Adamant boots, Magic shortbow" },
                            { text = "Magic: Robin Hood hat, Dragon Chainbody, Black dragonhide chaps, Infinity boots, Ancient staff" },
                        },
                    },
                    {
                        text = "You can use the NPC Contact spell to ensure you have the right equipment.",
                        npcs = {},
                    },
                    {
                        text = "Return and talk to Cyrisus (Fallen Man) for a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Right-click \"inspect\" and fill the remaining stats until he tells you that he is ok (if not already).",
                        npcs = {},
                    },
                },
            },
            {
                title = "Dream potion", needed = {},
                steps = {
                    {
                        text = "Talk to the Oneiromancer at the astral altar (most south-eastern part of the Lunar Isle) for a dream vial (herb).",
                        npcs = { "Oneiromancer", "astral altar", "dream vial (herb)" },
                    },
                    {
                        text = "Change your spellbook as necessary if you wish to use magic in the final fight.",
                        npcs = {},
                    },
                    {
                        text = "Use an astral rune on an anvil (there's one on Lunar Isle in a small building to the south), then grind the shards. Add it to the potion.",
                        npcs = {},
                    },
                    {
                        text = "Prepare for 4 fights (below level 100). Prayers and emergency teleports won't work. Neither will familiars.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Dreamland", needed = {},
                steps = {
                    {
                        text = "Light the Ceremonial Brazier in the long hall building, near the lodestone.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Cyrisus (dismiss any followers before).",
                        npcs = {},
                        subs = {
                            { text = "Do not click away of the chat or you will be teleported out" },
                        },
                    },
                    {
                        text = "During the fight, you can leave at any time by using the pedestal.",
                        npcs = {},
                        subs = {
                            { text = "Kill The Inadequacy" },
                            { text = "Kill The Everlasting (can safespot by the pedestal)" },
                            { text = "Kill The Untouchable (can safespot by the pedestal)" },
                            { text = "Kill The Illusive" },
                        },
                    },
                    {
                        text = "Return to the Oneiromancer.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "druidic_ritual", name = "Druidic Ritual", wiki = "Druidic Ritual/Quick guide",
        required = { "1 coin", "Vial (given by Sanfew if none are in your backpack)" },
        recommended = {},
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to Kaqemeex south of the Heroes' Guild.",
                        chat = "1 Talk about Druidic Ritual. / 1 What do you need help with? / 1 I'm pretty sure I've heard that before. / Accept",
                        npcs = { "Kaqemeex", "Heroes' Guild" },
                        tile = { x = 2924, y = 3484, plane = 0 },
                    },
                    {
                        text = "Run directly south and enter the last house on the west near the Herblore icon.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Sanfew.",
                        chat = "1 I've been sent to help make an ointment of imbalance for Kaqemeex. / 4 Ok, I'll do that then.",
                        npcs = { "Sanfew" },
                    },
                },
            },
            {
                title = "Untainted living water", needed = { "Vial" },
                steps = {
                    {
                        text = "Go north and enter the Burthorpe Slayer Cave directly east of the crayfish pond.",
                        npcs = { "Burthorpe Slayer Cave" },
                    },
                    {
                        text = "Head south and fill your vial at the subterranean spring for a vial of living water.",
                        npcs = { "subterranean spring", "living water" },
                    },
                    {
                        text = "Exit the cave.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Wandering wyrmwood", needed = {},
                steps = {
                    {
                        text = "Head south until you find wandering wyrmwood, then take-from one of them for wandering wyrmwood.",
                        npcs = { "wandering wyrmwood", "Wandering wyrmwood (item)" },
                    },
                },
            },
            {
                title = "Stone scales", needed = { "One coin" },
                steps = {
                    {
                        text = "At the west part of the lake, bait the Sparkling Fishing Spot.",
