                    {
                        text = "Have the owner make you two eagle capes and two fake beaks.",
                        chat = "2 I've got the feathers and the materials you requested. / 1 Okay, here are the materials. Eagle me up.",
                        npcs = { "eagle cape", "fake beak" },
