    {
        key = "eclipse_of_the_heart", name = "Eclipse of the Heart", wiki = "Eclipse of the Heart/Quick guide",
        required = { "A cat or kitten", "A monkeyspeak amulet or cramulet", "Ink and candles for two level 90 Necromancy rituals", "20 powerful ghostly ink", "31 greater ghostly ink", "18 regular ghostly ink", "16 ritual candles" },
        recommended = { "Level 130 Combat", "Level 43 Prayer to pray Protect from Melee", "A catspeak amulet or cramulet", "Food and combat equipment", "Bandit Camp lodestone activated", "Ring of duelling for teleports to Het's Oasis or fire altar teleport for teleports to fire altar", "Underworld Grimoire 2 or better, or runes for the Ungael Teleport necromancy incantation", "Activated Menaphos lodestone or Pharaoh's sceptre or Sceptre of the Gods or Leela's favour", "Coins for the magic carpet or:", "Pollnivneach Teleport scroll or ring of slaying", "Desert amulet 2 or better for teleports to Nardah", "Ingredients for 4 Speed III glyphs", "8 powerful ghostly ink", "8 greater ghostly ink", "8 ectoplasm", "Leela's favour for getting around Menaphos" },
        sections = {
            {
                title = "Gathering desert demigods", needed = { "pet cat or kitten, monkeyspeak amulet or cramulet." },
                steps = {
                    {
                        text = "Enter the Golden Palace in Menaphos.",
                        chat = "1 Yes.",
                        npcs = { "Golden Palace", "Menaphos" },
                    },
                    {
                        text = "Speak with Leela inside the pyramid.",
                        chat = "Accept",
                        npcs = {},
                    },
                    {
                        text = "Speak with Leela outside the pyramid.",
                        npcs = {},
                    },
                    {
                        text = "Cross the bridge to Sophanem and speak with Ozan.",
                        chat = "1 Yes. / ~",
                        npcs = {},
                    },
                    {
                        text = "Speak with the following citizens (if you need to leave the area to visit a bank, you will need to talk to Ozan again to proceed):",
                        npcs = {},
                        subs = {
                            { text = "The Sphinx (west of larger pyramid, cat is required but catspeak amulet is not required for quest progression. Your cat must be following you in order to progress dialogue.)" },
                            { text = "Jex (inside the north-east temple)" },
                            { text = "Raetul (north-east of larger pyramid; by silk stall)" },
                            { text = "Urbi (south of the larger pyramid)" },
                            { text = "Nathifa, south of the Sophanem Slayer Dungeon (must speak to the other 4 before Nathifa dialogue progresses)", chat = "3 What proposition? (Continue quest) / ~" },
                        },
                    },
                    {
                        text = "Speak to Ozan and prepare well for an intense battle which includes four waves of multiple heavy hitting enemies and stuns. Death is unsafe here.",
                        npcs = {},
                    },
                    {
                        text = "Go to the Sophanem Slayer Dungeon and inspect the dungeon entrance.",
                        npcs = { "Sophanem Slayer Dungeon" },
                        subs = {
                            { text = "If this option does not appear, speak to Ozan again." },
                        },
                    },
                    {
                        text = "Defeat four waves of soul devourers. You may need to speak to Het or Apmeken to continue receiving waves. If you die, you will have to restart all waves.",
                        npcs = { "Het", "Apmeken" },
                    },
                    {
                        text = "Talk to Het or Apmeken and finish the dialogue.",
                        npcs = { "Het", "Apmeken" },
                    },
                    {
                        text = "Return to Ozan and finish the dialogue.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Scabaras in the Temple of Isolation with at least 1 backpack space.",
                        chat = "3 (Continue quest)",
                        npcs = { "Temple of Isolation" },
                        subs = {
                            { text = "The entrance to the temple is north of Pollnivneach in the Scabarite Cavern, where you can use the old boat." },
                        },
                    },
                    {
                        text = "Head to Het's Oasis and speak to Het (outside west entrance) to continue the quest and be transported to the agility course.",
                        npcs = {},
                        subs = {
                            { text = "There is a possible graphical bug. After talking to Het to continue the quest, your screen will remain black. Re-log and talk to Het again to fix." },
                        },
                    },
                    {
                        text = "Talk to Het to be tasked with doing the agility course.",
                        npcs = { "Het" },
                    },
                    {
                        text = "Complete 1 lap of the agility course (from your current location) by climbing the rope ladder.",
                        npcs = { "Het's Oasis Agility Course" },
                    },
                    {
                        text = "Start a new lap on the course until you get back to Crondis and Het.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Het by the rope ladder.",
                        npcs = {},
                    },
                    {
                        text = "Gather 1 of each flower from the perfect flower bushes in each corner of Het's Oasis, do not teleport as you will need to speak with Het again. Each one will be marked with a light beam.",
                        npcs = {},
                        subs = {
                            { text = "Perfect iris bush (north-east)" },
                            { text = "Perfect rose bush (north)" },
                            { text = "Perfect hollyhock bush (south)" },
                            { text = "Perfect hydrangea bush (south-east)" },
                        },
                    },
                    {
                        text = "Speak to Crondis by the rope ladder.",
                        npcs = {},
                    },
                    {
                        text = "Go to the monkey colony north-east of the Bandit Camp and talk to Apmeken with a monkeyspeak amulet or cramulet equipped.",
                        npcs = { "monkey colony", "Bandit Camp", "Apmeken", "monkeyspeak amulet", "cramulet" },
                    },
                    {
                        text = "Run slightly north (somewhere quieter) and talk to Apmeken again.",
                        chat = "3 We could go get a chimp ice? (Continue quest)",
                        npcs = {},
                    },
                    {
                        text = "Head to choc ice stall in Nardah and speak to Rokuh.",
                        npcs = { "Choc Ice Stall", "Rokuh" },
                        subs = {
                            { text = "You may teleport to Nardah using a desert amulet 2 or higher." },
                            { text = "Buying choc Ice without speaking to him will not progress the quest." },
                            { text = "If Apmeken is not following you, he will not give you the Ice. Return to the monkey colony and speak to Apmeken." },
                        },
                    },
                    {
                        text = "Head back to the monkey colony and continue quest (unlike other instances, players may teleport without the item melting, and ice spells are not required).",
                        npcs = {},
                    },
                    {
                        text = "Kill Mizaru, Kikazaru and Iwazaru.",
                        npcs = {},
                        subs = {
                            { text = "Remember to kill the demons for Kikazaru; beware Iwazaru can unequip your helmet to the backpack." },
                        },
                    },
                    {
                        text = "Speak to Apmeken in the Monkey Colony to receive Apmeken's Favour.",
                        npcs = { "Apmeken's Favour" },
                    },
                    {
                        text = "Speak to Scabaras in the Temple of Isolation.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Tumeken puzzles", needed = { "Move symbol plinths next to their matching symbol. For the puzzles, you must click the desired plinth then \"move here tile\" on the lighter grey/beige spots. Puzzles may be reset by lobbying or teleporting away and re-entering. Players will continue from the puzzle they started prior to leaving. The plinths can only move 1 tile at a time." },
