            {
                title = "Performing rituals", needed = { "18 regular ghostly ink, 31 greater ghostly ink, 20 powerful ghostly ink, 16 basic ritual candle" },
                steps = {
                    {
                        text = "Speak to Icthlarin.",
                        chat = "5 Continue Quest.",
                        npcs = {},
                    },
                    {
                        text = "Go to the Ungael ritual site.",
                        npcs = { "Ungael ritual site" },
                    },
                    {
                        text = "Take beacon from the soul beacon north of the Archivist.",
                        chat = "1 Yes.",
                        npcs = { "Soul beacon (scenery)", "Archivist (Ungael)" },
                    },
                    {
                        text = "Place the soul beacon (corrupted) on the pedestal of the ritual site and draw the corresponding glyphs for the ensoul beacon ritual.",
                        npcs = { "soul beacon (corrupted)", "ensoul beacon" },
                    },
                    {
                        text = "Perform ritual, closing shadow rifts as they appear.",
                        npcs = {},
                        subs = {
                            { text = "If you're unable to start the ritual, attempt to take the soul beacon again." },
                        },
                    },
                    {
                        text = "Interact with the soul beacon west of the ritual site.",
                        npcs = {},
                    },
                    {
                        text = "Go to the Um Ritual Site and continue the quest via the portal.",
                        chat = "1 Yes.",
                        npcs = { "Um Ritual Site" },
                    },
                    {
                        text = "Talk with Vorkath, then to Icthlarin.",
                        npcs = {},
                    },
                    {
                        text = "Place the soul beacon on the pedestal and perform the powerful ritual of severance. Simply ignore the creatures that appear - Vorkath and Icthlarin will deal with them.",
                        npcs = { "Soul beacon (Eclipse of the Heart)", "powerful ritual of severance" },
                    },
                },
            },
            {
                title = "Confronting Amascut", needed = { "Food and combat equipment" },
                steps = {
                    {
                        text = "Prepare for the encounter of Amascut, the Devourer.",
                        npcs = { "Amascut, the Devourer" },
                    },
                    {
                        text = "When you're ready, return to the Um Ritual Site and speak to Icthlarin to continue.",
                        npcs = {},
                    },
                    {
                        text = "Run through the city to the Great Pyramid and speak to any of the lesser gods for a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Tumeken, click through all the chat options to continue.",
                        chat = "1 What are you? / 2 Why is everyone frozen? / 3 Why are you speaking to me? / 4 Continue.",
                        npcs = {},
                    },
                    {
                        text = "The fight then begins with Amascut. Attack the soul obelisks, she switches between magic, ranged, and melee attacks. During the last phase, you will be teleported onto a platform.",
