                    },
                    {
                        text = "After the fight, go through the dialogue.",
                        chat = "~",
                        npcs = {},
                    },
                    {
                        text = "Speak to Icthlarin to leave the instance.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Finish the remaining dialogue.",
                        chat = "~",
                        npcs = {},
                    },
                },
            },
