    {
        key = "elemental_workshop_i", name = "Elemental Workshop I", wiki = "Elemental Workshop I/Quick guide",
        required = { "1 thread", "Soft leather (obtainable during the quest)", "4 coal" },
        recommended = {},
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "In Seers' Village, go to the house immediately south of the anvil.",
                        npcs = { "Seers' Village" },
                    },
                    {
                        text = "Search the bookcase on the eastern wall to find a battered book.",
                        npcs = { "battered book" },
                    },
                    {
                        text = "Read the book, then right-click on the book and click \"Cut-open\" to get a battered key. Do not drop the book.",
                        chat = "Accept",
                        npcs = { "battered key" },
                    },
                    {
                        text = "Go to the building with the anvil and click on the northern wall to open the odd-looking wall.",
                        npcs = { "odd-looking wall" },
                    },
                    {
                        text = "Go down the stairs.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Repairing a workshop", needed = {},
                steps = {
                    {
                        text = "Go into the room to the north.",
                        npcs = {},
                    },
                    {
                        text = "(Red Indicator) Turn the water controls east of the water wheel to turn it green.",
                        npcs = {},
                    },
                    {
                        text = "(Red Indicator) Turn the water controls west of the water wheel to turn it green",
                        npcs = {},
                    },
                    {
                        text = "Pull the lever by the water wheel.",
                        npcs = {},
                    },
                    {
                        text = "(Optional) To obtain leather, search the singular crate north-west of the hatch in the middle room.",
                        npcs = { "leather", "Crate (Elemental Workshop I)" },
                    },
                    {
                        text = "Go to the eastern room.",
                        npcs = {},
                    },
                    {
                        text = "With thread and leather, fix the bellows.",
                        npcs = { "thread" },
                    },
                    {
                        text = "Pull the lever by the bellows.",
                        npcs = {},
                    },
                    {
                        text = "Go to the western room and mine an elemental rock.",
                        npcs = { "elemental rock" },
                    },
                    {
                        text = "Kill the earth elemental and pick up the elemental ore it drops.",
                        npcs = { "earth elemental", "elemental ore" },
                    },
                    {
                        text = "Go back to the middle room and search the small boxes north-east of the hatch to obtain a stone bowl.",
                        npcs = { "Boxes (Elemental Workshop I)", "a stone bowl" },
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Go to the south room.",
                        npcs = {},
                    },
                    {
                        text = "Use the stone bowl on the lava trough to the south.",
                        npcs = { "lava trough" },
                    },
                    {
                        text = "Use the bowl of lava on the furnace in the room.",
                        npcs = { "furnace" },
                    },
                    {
                        text = "Use the elemental ore and four coal on the furnace.",
                        npcs = { "coal" },
                    },
                    {
                        text = "With the slashed book, go to the middle room and smith an elemental shield on an anvil workbench.",
                        npcs = { "slashed book", "elemental shield" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "elemental_workshop_ii", name = "Elemental Workshop II", wiki = "Elemental Workshop II/Quick guide",
        required = { "8 coal (12 if you wish to also make a mind shield)", "Battered key (May be in steel key ring; can be obtained during quest)" },
        recommended = { "Activated Seers' Village lodestone, runes for Camelot Teleport, or a Camelot teleport tablet", "The Archaeology journal, Master archaeologist's outfit, or Dig Site pendant for quick access to the Exam Centre" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Go to the Exam Centre in the south of the Archaeology Campus and search the bookshelf on the eastern wall in the Exam Centre.",
                        chat = "Accept",
                        npcs = { "Exam Centre", "Archaeology Campus", "Bookshelf (Elemental Workshop II)" },
                        subs = {
                            { text = "Use Archaeology journal to teleport to the Archaeology Campus just north of the Exam Centre." },
                            { text = "If you end up with Varmen's notes, you searched the wrong bookshelf." },
                        },
                    },
                    {
                        text = "Read the scroll inside the beaten book and keep the book.",
                        npcs = { "beaten book" },
                    },
                },
            },
            {
                title = "The second key", needed = {},
                steps = {
                    {
                        text = "Head to the building with an anvil west of the Seers' Village bank.",
                        npcs = { "anvil", "Seers' Village bank" },
                    },
                    {
                        text = "Click on the odd-looking wall to enter it.",
                        npcs = { "odd-looking wall" },
                        subs = {
                            { text = "If it says \"You see a small hole in the wall but no way to open it\", go to the building directly south and search the bookcase on the east wall for a battered key." },
                        },
                    },
                    {
                        text = "Go down the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Go north to the water elemental room and search the machinery in the southwest of the room to get a key.",
                        npcs = { "Machinery (Elemental Workshop)", "Key (Elemental Workshop II)" },
                    },
                },
            },
            {
                title = "Elemental bars", needed = {},
                steps = {
                    {
                        text = "Obtain 2 elemental ores from the west room by attempting to mine the elemental rocks, and defeating the earth elementals that spawn.",
                        npcs = { "elemental ore", "elemental rock", "earth elemental" },
                    },
                    {
                        text = "Go back to the north room (where you got the key) and pull the lever to start the water wheel (if the wheel is already turning, this step can be skipped).",
                        npcs = {},
                    },
                    {
                        text = "Go to the east room and pull the lever to start the bellows (if the bellows are already working, this step can be skipped).",
                        npcs = {},
                    },
                    {
                        text = "Smelt two elemental bars in the south room. ('Use' the ore on the furnace.)",
