                    {
                        text = "Pull the east lever.",
                        npcs = {},
                    },
                    {
                        text = "Pull the west lever twice.",
                        npcs = {},
                    },
                    {
                        text = "Pull the east lever.",
                        npcs = {},
                    },
                    {
                        text = "Pull the west lever twice.",
                        npcs = {},
                    },
                    {
                        text = "Pull the lever behind you, by the mine cart sign.",
