                        text = "Move to the west side by the steam press.",
                        npcs = {},
                    },
                    {
                        text = "Open the junction box and connect the pipes by clicking on a pair of pipe holes. Refer to the solution on the right.",
                        npcs = {},
                        subs = {
                            { text = "Top left and bottom right." },
                            { text = "Top middle and top right." },
                            { text = "Bottom left and bottom middle." },
