    {
        key = "family_crest", name = "Family Crest", wiki = "Family Crest/Quick guide",
        required = { "Cooked shrimps", "Cooked salmon", "Cooked tuna", "Cooked bass", "Cooked swordfish", "2 cut rubies", "Antipoison or super antipoison, any number of doses", "Either one to defeat Chronozon:", "Runes, magic weapon and standard spellbook to cast Air, Water, Earth, and Fire Blast which require Level 59 Magic", "A deathtouched dart can be used instead of Magic to kill Chronozon" },
        recommended = { "Activated Al Kharid, Ardougne, Edgeville, Falador and Varrock lodestones", "A charged amulet of glory", "A charged combat bracelet", "Activated Fort Forinthry lodestone, Fort Forinthry Teleport scrolls, earth altar teleport, or an archaeology journal to teleport to the Infernal Source Dig Site for easy access to Johnathon" },
        sections = {
            {
                title = "Patriarch", needed = {},
                steps = {
                    {
                        text = "Talk to Dimintheis in the house next to the Fancy Clothes Store in south-eastern Varrock.",
                        chat = "3 Hi, I am a bold adventurer. / 2 So where is this crest? / Accept",
                        npcs = { "Dimintheis", "Fancy Clothes Store", "Varrock" },
                        tile = { x = 3279, y = 3404, plane = 0 },
                    },
                },
            },
            {
                title = "Caleb's piece", needed = { "Swordfish, bass, tuna, salmon, and shrimp" },
                steps = {
                    {
                        text = "Go to Gertrude's house west of Varrock and talk to Caleb, who is inside the house (although he can sometimes wander outside).",
                        chat = "1 Are you Caleb Fitzharmon? / 2 So can I have your bit? / 1 Ok, I will get those.",
                        npcs = { "Gertrude", "Varrock", "Caleb" },
                    },
                    {
                        text = "Talk to him again with swordfish, bass, tuna, salmon, and shrimp in the backpack to get a crest part.",
                        npcs = { "crest part" },
                    },
                    {
                        text = "Then ask Caleb where the rest of the crest is..",
                        chat = "1 Uh... what happened to the rest of it?",
                        npcs = {},
                    },
                },
            },
            {
                title = "Avan's request", needed = {},
                steps = {
                    {
                        text = "Talk to Avan just south of the Al Kharid mine.",
                        chat = "2 I'm looking for a man named Avan Fitzharmon.",
                        npcs = { "Avan", "Al Kharid mine" },
                    },
                    {
                        text = "Enter the Dwarven mines north-east of Falador.",
                        npcs = { "Dwarven mines", "Falador" },
                    },
                    {
                        text = "Head south-west of the general store and talk to Boot.",
                        chat = "1 Hello. I'm in search of very high quality gold.",
                        npcs = { "Boot" },
                    },
                },
            },
            {
                title = "Creating the necklace", needed = { "Two rubies and two backpack spaces, combat equipment and food to survive under hellhound attacks" },
                steps = {
                    {
                        text = "Travel to Witchaven, south-east of the Ardougne lodestone. Climb down the ruins just to the west of the town. Run past the hobgoblins towards the elongated room with the Ogres.",
                        npcs = { "Witchaven", "Ardougne lodestone" },
                        tile = { x = 2697, y = 3283, plane = 0 },
                    },
                    {
                        text = "Solve the puzzle:",
                        npcs = {},
                        subs = {
                            { text = "Logging out will reset this puzzle." },
                            { text = "Head to the northern lever located outside the room and pull it up." },
                            { text = "Head to the southern lever, located inside the room, and pull it up." },
                            { text = "Return to the northern room and pull the lever outside the room down." },
                            { text = "Enter the northern room and push the lever in there up." },
                            { text = "Leave the room and pull the one outside the northern room up." },
                            { text = "Go back to the southern room and pull the inside lever down." },
                            { text = "Now enter the room with the hellhounds." },
                        },
                    },
                    {
                        text = "Mine two 'Perfect' gold ore in the hellhound room. You will continue to mine gold while being attacked by hellhounds if you turn auto-retaliate off.",
                        npcs = { "'Perfect' gold ore", "hellhound" },
                    },
                    {
                        text = "Smelt the ores into bars and then craft a 'Perfect' ring and a 'Perfect' necklace with two rubies at any furnace. There is a furnace just northwest of the Al Kharid lodestone.",
                        chat = "1 Yes smelt 'perfect' golden ring. / 2 Yes smelt 'perfect' golden necklace.",
                        npcs = { "'Perfect' gold bar", "'Perfect' ring", "'Perfect' necklace", "ruby", "Al Kharid lodestone" },
                    },
                    {
                        text = "Go back to south of the Al Kharid mine and give them to Avan.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Helping Johnathon", needed = { "Antipoison" },
                steps = {
                    {
                        text = "Talk to Johnathon on the 2nd floor of the Jolly Boar Inn south-west of the Fort Forinthry lodestone.",
                        npcs = { "Johnathon", "Jolly Boar Inn", "Fort Forinthry lodestone" },
                        tile = { x = 3097, y = 3468, plane = 0 },
                    },
                    {
                        text = "Use an antipoison on him.",
                        chat = "2 Where can I find Chronozon?",
                        npcs = { "antipoison" },
                    },
                },
            },
            {
                title = "Defeating Chronozon", needed = { "Runes, magic weapon and standard spellbook to cast Air, Water, Earth, and Fire Blast, alternatively a deathtouched dart" },
                steps = {
                    {
                        text = "Teleport to Edgeville and prepare for the final fight which will use multiple casts of the four blast spells. The other elemental spells do not work.",
                        npcs = { "Edgeville" },
                    },
                    {
                        text = "Enter Edgeville Dungeon and run north and then west.",
                        npcs = { "Edgeville Dungeon" },
                    },
                    {
                        text = "Kill Chronozon when it appears.",
                        npcs = { "Chronozon" },
                        subs = {
                            { text = "Chronozon must be hit with all four elemental blast spells or deathtouched dart in order to be killed, or otherwise it will return to full health when it is nearly dead. Once it has been hit with all four elemental blast spells, other types of damage can be used to kill it." },
                            { text = "Only the following elemental spells will work: Air Blast, Water Blast, Earth Blast, Fire Blast." },
                            { text = "If you use a high tier magic weapon (tier 70+), it will be very hard as you will kill him before being able to deal all 4 types of damage, therefore use a low-tier weapon (tier 30 or 40)." },
                        },
                    },
                    {
                        text = "Kill him and take the crest piece.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Talk to Dimintheis.",
                        npcs = { "Dimintheis" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                    {
                        text = "Talk to Dimintheis again for cooking and smelting gauntlets.",
                        chat = "1 Ask about gauntlets. / 1 Reclaim lost gauntlets / 1 Yes please.",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "fate_of_the_gods", name = "Fate of the Gods", wiki = "Fate of the Gods/Quick guide",
        required = {},
        recommended = { "A face mask or any item that acts as one, such as masked earmuffs or a Slayer helmet (not on slayer helmet stand)", "Combat equipment and food", "Switch to the Ancient Magicks spell book and Ancient Curses prayer book before the quest", "Restore potions or overloads for dealing with nihils' stat-reducing magic", "Traveller's necklace, or activated Eagles' Peak lodestone to get to the World Gate", "The fully charged engrammeter (if Mahjarrat Memories (miniquest) is completed)", "8 backpack spaces for collecting the memoriam crystals in the opening area of Freneskae", "Ring of visibility for dialogue" },
        sections = {
            {
                title = "Powering the World Gate", needed = { "combat gear and a face mask (alternatively, a masked earmuffs, or a slayer helmet not on slayer helmet stand)" },
                steps = {
                    {
                        text = "Optional: Equip a ring of visibility to skip some dialogue.",
                        npcs = { "ring of visibility" },
                    },
                    {
                        text = "Find the World Gate, south of the Eagles' Peak lodestone.",
                        npcs = { "World Gate", "Eagles' Peak lodestone" },
                    },
                    {
                        text = "Talk to Azzanadra.",
                        chat = "Accept / 2 I'll help if I can. / Any / 4 Okay, let's hear your proposal. / Any / Any",
                        npcs = { "Azzanadra" },
                    },
                },
            },
            {
                title = "Combination lock", needed = {},
                steps = {
                    {
                        text = "Rotate the right controls near the gate until you reach.",
                        npcs = {},
                    },
                    {
                        text = "Rotate left until you reach.",
                        npcs = {},
                    },
                    {
                        text = "Rotate right until you reach.",
                        npcs = {},
                    },
                    {
                        text = "Step away from the controls, and speak to Sliske.",
                        npcs = { "Sliske" },
                    },
                },
            },
            {
                title = "Preparing for Freneskae", needed = {},
                steps = {
                    {
                        text = "Put on a face mask or equivalent protection to avoid taking 50 damage every 15 seconds while in Freneskae.",
                        npcs = { "face mask", "Freneskae" },
                    },
                    {
                        text = "If you have completed Mahjarrat Memories (miniquest), you should also bring the fully charged engrammeter. Operating the engrammeter on Freneskae will cause it to become a distorted engrammeter, which provides a 15% reduction to lightning damage on Freneskae and a one-time reward of 25,000 Divination experience.",
                        npcs = { "Mahjarrat Memories (miniquest)", "engrammeter", "distorted engrammeter", "Divination" },
                    },
                    {
                        text = "Enter the World Gate to enter Freneskae.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Freneskae", needed = {},
                steps = {
                    {
                        text = "Run through Freneskae to reach the Sanctum. Move fast and avoid the hazards. There are healing points along the way if needed.",
                        npcs = { "the Sanctum" },
                    },
                    {
                        text = "Optional: collect the memoriam crystals along the way. They are numbered on the map below; for efficiency, start with collecting number 9, then 2, 1, 4, 5, 6, 7, 8.",
                        npcs = { "memoriam crystals" },
                    },
                },
            },
            {
                title = "The Sanctum", needed = {},
                steps = {
                    {
                        text = "Optional: Deposit collected Memoriam crystals in the middle to see memories.",
                        npcs = {},
                    },
                    {
                        text = "Go to the north side of the room to the door puzzle.",
                        npcs = {},
                    },
                    {
                        text = "Match the symbols up together to light up the lines in between them three times to open the door, then enter.",
                        npcs = {},
                    },
                    {
                        text = "Kill the four nihils then enter the next area to the north. All nihils use a special attack after hissing. Each nihil always runs in the same direction. Therefore, a pair of nihil (ice and shadow or smoke and blood) can be killed first, leaving areas between the tracks unused and safe. Don't stand in the middle, as you might be dashed by multiple nihils at once.",
                        npcs = {},
                        subs = {
                            { text = "Killing the nihils while all 4 are attacking you will unlock the title and the achievement Annihilator." },
                            { text = "The smoke nihil attacks with Magic. Its special attack will decrease Attack, Strength, Magic, Ranged, and Defence by 15. Its charge will decrease these stats by 5." },
                            { text = "The shadow nihil attacks with Ranged, and its special attack creates Nex-like shadow bomb at the position of player that deals rapid damage. Players should move away as soon as the floor below them is darkened by a circular spot. Shadow nihil darkens the whole screen whenever it approaches the player, both when charging or fighting the player, but this causes no gameplay difference." },
                            { text = "The blood nihil attacks with melee. Its special attack causes all incoming damage to heal it, indicated when the creature lowers its head and begin to glow. It also will passively heal other nihil if it is damaged. Its charge inflicts a bleed similar to Slaughter that begins at 100 damage." },
                            { text = "The ice nihil attacks with Magic, and its special attack applies a six second stun and drains player's Prayer points by 50% of its maximum. Its charge drains the player's Prayer points by 25% of its maximum." },
                        },
                    },
                },
            },
            {
                title = "Meeting Zaros", needed = { "good equipment and a lot of food" },
                steps = {
                    {
                        text = "Attempt to descend the ledge to the north then speak to Zaros.",
                        chat = "Any / 5 I've heard all I need to. / 2 No, just tell me the crucial info. / 2 Yes, allow him in for now.",
                        npcs = {},
                        subs = {
                            { text = "If you accept Zaros' help against Mah, he will provide you with full prayer for use with Ancient Curses along the fight and less damage from Mah." },
                        },
                    },
                    {
                        text = "Defend against monsters while Mah has her nightmare (progress displayed at the top of the screen).",
                        npcs = { "Mah" },
                        subs = {
                            { text = "Use Freedom or Anticipate after Mah clenches her hands to avoid being stunned when she screams in agony (though you will still take damage)." },
                        },
                    },
                    {
                        text = "When the progress is 0%, climb down the ledge next to Mah's hand.",
                        npcs = {},
                    },
                    {
                        text = "Collect The Measure and place it on the ground near faint wisps to activate them for harvesting (wisps can be found on the centre and edges of the cave. After revealing one, it will be a yellow dot on minimap).",
                        npcs = { "The Measure" },
                    },
                    {
                        text = "Convert Mah memories into Mah Energy using the Energy rift. When you gather 250 energy, weave it into a simulacrum (dark to help Zaros, light to hinder Zaros). Hop worlds if you are having trouble finding wisps. You will be outside of the World Gate, enter again using the checkpoint option.",
                        npcs = {},
                    },
                    {
                        text = "Return and speak to Zaros by exiting the rock face on the wall between two hallways (west of the energy rift). Speak to Zaros again after the cutscene.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Talk to Azzanadra through the world gate.",
                        chat = "1 I'm ready. / Any",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
