            {
                title = "The white tree", needed = { "Ring of charos (a), secateurs or magic secateurs, a filled plant pot, and watering can or magic watering can" },
                steps = {
                    {
                        text = "Talk to Dantaera at the Catherby allotment farming patch with the ring equipped. Select all the options beginning with [Charm].",
                        chat = "1 Do you know how I could grow a White Tree? / 2 [Charm] I think that there is something that you are not telling me. / 2 [Charm] A secret is a dreadful burden to have to keep to yourself. / 2 [Charm] Unless you allow me to do this she will die anyway.",
                        npcs = { "Dantaera", "Catherby" },
                    },
                    {
                        text = "Interact with the white tree on Ice Mountain west of Edgeville, select secateurs.",
                        npcs = { "white tree", "Ice Mountain", "Edgeville" },
                    },
                    {
                        text = "Use the white tree shoot on a plant pot and water it.",
                        npcs = { "white tree shoot" },
                    },
                    {
                        text = "It will take 3 minutes for the shoot to turn into a White tree sapling. It is recommended to plant the tree in the Queen's Garden as soon as possible, as this will take about 6 minutes longer to grow than the other plants.",
                        npcs = { "White tree sapling" },
                    },
                },
            },
            {
                title = "Vines from Taverley", needed = { "Ring of charos (a), 2 plant cure, and rune essence or pure essence" },
                steps = {
                    {
                        text = "Charm Bernald who is south of the Taverley pub.",
                        chat = "2 [Charm] But it is the only way that these vines will be cured. / 1 I accept the deal.",
