            {
                title = "Falador Statue", needed = { "Trolley" },
                steps = {
                    {
                        text = "Teleport to Falador, and use the trolley on the statue of Saradomin south of the Falador lodestone.",
                        npcs = { "Falador", "statue of Saradomin (Falador)" },
