                    {
                        text = "Push it into the Queen's garden and use the \"place\" option when statue is close to the plinth. If you are not fast enough to push it and place it, it will disappear and respawn in Falador.",
                        npcs = {},
                        subs = {
                            { text = "Big-push the trolley east three times." },
                            { text = "Big-push the trolley south twice." },
                            { text = "Big-push the trolley east." },
                            { text = "Big-push the trolley south twice." },
