                            { text = "Big-push the trolley south." },
                            { text = "\"Place\" the trolley." },
                        },
                    },
                },
            },
            {
                title = "Finishing the garden", needed = { "4 white rose seed, 4 pink rose seed, 4 red rose seed, 4 snowdrop seed, 1 white tree sapling, 4 vine seed, 3 orchid seed (pink), 3 orchid seed (yellow), 4 delphinium seed, 2 compost or supercompost, and ring of charos (a)" },
                steps = {
                    {
