    {
        key = "ghosts_ahoy", name = "Ghosts Ahoy", wiki = "Ghosts Ahoy/Quick guide",
        required = { "A way to get into Port Phasmatys three times (either charter ships or the 2 ecto-token toll)", "Around 1,000 coins (more or less, depending on your luck)", "Thread", "Silk", "Spade (tool belt will not work)", "Oak longbow", "Nettle tea (a bowl of water and any pair of gloves will be required if you brew the nettle tea during the quest)", "Bucket of milk", "Ghostspeak amulet", "3 randomly chosen standard dyes (to save time, bring three of each primary colour to mix as needed):", "3 red dye", "3 blue dye", "3 yellow dye" },
        recommended = { "Bucket of slime (can be obtained during the quest)" },
        sections = {
            {
                title = "Ghostly trouble", needed = { "Ghostspeak amulet" },
                steps = {
                    {
                        text = "To enter Port Phasmatys, either pay two ecto-tokens as an entrance fee to pass the energy barrier or charter a ship to reach the town. Each entry through the barrier, until the end of the quest, will cost two ecto-tokens.",
                        npcs = { "Port Phasmatys", "ecto-token", "Energy Barrier (Port Phasmatys)", "Charter ship" },
                    },
                    {
                        text = "Equip the ghostspeak amulet. You need to equip the amulet when you talk to the ghost residents in the town.",
                        npcs = { "ghostspeak amulet" },
                    },
                    {
                        text = "Talk to Velorina at Port Phasmatys, in the northernmost building just east of the entrance.",
                        chat = "1 Why, what is the matter? / 1 Yes, I do. It is a very sad story. / Accept",
                        npcs = { "Velorina" },
                    },
                    {
                        text = "Talk to Necrovarus at the Ectofuntus just outside the town, to the north.",
                        npcs = { "Necrovarus", "Ectofuntus" },
                    },
                    {
                        text = "If you do not already have a bucket of slime, obtain it now for later use in the quest.",
                        npcs = { "bucket of slime" },
                        subs = {
                            { text = "Open and climb down the trapdoor on the west side of the Ectofuntus to enter the basement. You do not need a bucket to obtain one." },
                            { text = "If you intend to proceed with the quest Vessel of the Harbinger after this quest, obtain the second one." },
                        },
                    },
                    {
                        text = "Talk to Velorina.",
                        chat = "1 Do you know where this woman can be found?",
                        npcs = {},
                    },
                },
            },
            {
                title = "Getting help", needed = { "nettle tea, silk, thread, bucket of milk" },
                steps = {
                    {
                        text = "Teleport to Canifis lodestone.",
                        npcs = { "Canifis lodestone" },
                    },
                    {
                        text = "If you haven't already made nettle tea, pick some nettles just east. Use the nettles on the bowl of water to get nettle-water.",
                        npcs = { "Nettles (scenery)", "nettles", "bowl of water", "nettle-water" },
                    },
                    {
                        text = "Head north-west to Netty's house which is on the east side of the Slayer Tower, talk to Netty in her house.",
                        chat = "1 You are doing so much for me - is there anything I can do for you?",
                        npcs = { "Slayer Tower", "Netty" },
                    },
                    {
                        text = "If you haven't already made nettle tea, run south of Netty's house and cut down a swamp tree for logs. Light a fire and use the nettle-water on it to get nettle tea. It is possible to accidentally boil your tea over.",
                        npcs = { "swamp tree", "logs", "fire" },
                    },
                    {
                        text = "Talk to Netty to get her porcelain cup.",
                        chat = "1 I'm here about Necrovarus.",
                        npcs = { "porcelain cup" },
                    },
                    {
                        text = "Use your nettle tea on her cup, and use your bucket of milk on it.",
                        npcs = { "nettle tea", "bucket of milk" },
                    },
                    {
                        text = "Talk to Netty again.",
                        chat = "1 I'm here about Necrovarus. / 1 You are doing so much for me - is there anything I can do for you?",
                        npcs = {},
                    },
                    {
                        text = "Repair the model ship with the silk. Bring thread just in case.",
                        npcs = { "model ship", "thread" },
                    },
                },
            },
            {
                title = "The map", needed = { "3 red dye, 3 blue dye, 3 yellow dye, combat equipment" },
                steps = {
                    {
                        text = "Go inside the shipwreck just north of Alice's farm, east of the Canifis lodestone.",
                        npcs = { "Alice's farm", "Canifis lodestone" },
                    },
                    {
                        text = "Climb the ladders to reach the top deck (there is a ladder on the outer cabin wall).",
                        npcs = {},
                    },
                },
            },
            {
                title = "Dyeing the ship", needed = {},
                steps = {
                    {
                        text = "Wait for the \"wind speed\" to become \"low\", which is shown on the top of the screen. Search the mast to determine the colours and their positions. You need to search for 3 different results, take note if needed.",
                        npcs = {},
                    },
                    {
                        text = "Dye the model ship with the same colours and position as the mast. Orange dye is made from red and yellow; green dye is made from blue and yellow; purple dye is made from red and blue dye. If you make a mistake when painting, simply paint over the piece again.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Collecting the map scraps", needed = {},
                steps = {
                    {
                        text = "Climb down a ladder and enter the captain's cabin.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the old man.",
                        chat = "3 Is this your toy boat?",
                        npcs = { "old man" },
                    },
                    {
                        text = "Use the key on the chest by the Captain and open it for a map scrap.",
                        npcs = { "Map scrap (1)" },
                    },
                    {
                        text = "On the 1st floor of the ship, open and search all unlocked chest in the eastern end of the ship until a giant lobster spawns.",
                        npcs = { "Giant lobster (Ghosts Ahoy)" },
                    },
                    {
                        text = "Kill the giant lobster.",
                        npcs = {},
                        subs = {
                            { text = "You can safespot the lobster by moving all the way east." },
                        },
                    },
                    {
                        text = "Search the chest again for a map scrap.",
                        npcs = { "Map scrap (3)" },
                    },
                    {
                        text = "On the 2nd floor of the ship, go to the northwest part of the ship's deck.",
                        npcs = {},
                    },
                    {
                        text = "Cross the gangplank to the rocks.",
                        npcs = {},
                    },
                    {
                        text = "Jump to the rocks on your side until you find a chest. Open it for another map scrap.",
                        npcs = { "Map scrap (2)" },
                    },
                    {
                        text = "Put the pieces together to get the map.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Dragontooth Island", needed = { "spade in the backpack, treasure map" },
                steps = {
                    {
                        text = "Go back to Port Phasmatys.",
                        npcs = {},
                    },
                    {
                        text = "Right-click and choose \"Travel (Dragontooth Island)\" on the ghost captain on the south-east docks (the one with the smaller boat, not the one directly east of Velorina) to get a ride to Dragontooth Island.",
                        npcs = { "ghost captain", "Dragontooth Island" },
                    },
                    {
                        text = "Dig with a spade at the location shown to the right to obtain the book of haricanto.",
                        npcs = { "spade", "book of haricanto" },
                        tile = { x = 3803, y = 3530, plane = 0 },
                    },
                    {
                        text = "Right-click and choose \"Travel\" on the ghost captain to go back Port Phasmatys.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Translation", needed = { "oak longbow" },
                steps = {
                    {
                        text = "Talk to Ak-Haranu (who is not a ghost) around the docks.",
                        chat = "1 Okay, wait here - I'll get you your bow.",
                        npcs = { "Ak-Haranu" },
                    },
                    {
                        text = "Go to the inn and talk to Robin.",
                        chat = "2 Talk about something else. / 1 Yes, I'll give you a game.",
                        npcs = { "Robin" },
                    },
                    {
                        text = "Win 4 games of Rune-Draw against him to get a signed oak longbow. The easiest method is to choose \"draw\" until one player loses by drawing a death rune and repeating this until you have four wins total.",
                        npcs = { "Rune-Draw", "signed oak longbow" },
                        subs = {
                            { text = "Talk to Robin every time you finish a game.", chat = "2 Talk about something else. / 1 Yes, I'll give you a game." },
                        },
                    },
                    {
                        text = "Talk to Ak-Haranu to get the translation manual.",
                        npcs = { "translation manual" },
                    },
                },
            },
            {
                title = "Revolution", needed = { "bucket of slime" },
                steps = {
                    {
                        text = "Ask the ghost innkeeper, who is located in the pub, for a job to get a bedsheet.",
                        chat = "4 Do you have any jobs I can do? / 1 Yes, I'd be delighted.",
                        npcs = { "ghost innkeeper", "bedsheet" },
                        subs = {
                            { text = "Don't give it to Robin like he asks." },
                        },
                    },
                    {
                        text = "Use your bucket of slime on the bedsheet or dip it into the Pool of Slime. You cannot re-enter Port Phasmatys via charter ship if you have dipped bedsheet in the backpack.",
                        npcs = { "bucket of slime", "Pool of Slime", "Bedsheet (ectoplasm)" },
                    },
                    {
                        text = "Talk to Gravingas west of the inn to get a petition form.",
                        chat = "1 After hearing Velorina's story I will be happy to help out.",
                        npcs = { "Gravingas", "petition form" },
                    },
                    {
                        text = "Wear your bedsheet.",
                        npcs = {},
                    },
                    {
                        text = "Ask the ghost villager for signatures until you have 10.",
                        npcs = { "ghost villager" },
                        subs = {
                            { text = "You can get multiple signatures from the same ghost if you ask another ghost first." },
                            { text = "Some will resist. Just ask others." },
                            { text = "If a ghost ask for ecto-tokens, simply leave the conversation and ask the same ghost again." },
                        },
                    },
                    {
                        text = "After you collected 10 signatures, remove your bedsheet.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Necrovarus at the Ectofuntus. Take the bone key he drops on the floor.",
                        npcs = { "Necrovarus", "Ectofuntus", "Bone key (Ghosts Ahoy)" },
                    },
                    {
                        text = "Head upstairs, and use the key on the door on the south-west side. Then open the door.",
                        npcs = {},
                    },
                    {
                        text = "Open and search the coffin for Necrovarus' mystical robes.",
                        npcs = { "Coffin (Necrovarus)", "mystical robes" },
                    },
                },
            },
            {
                title = "Persuasion techniques", needed = {},
                steps = {
                    {
                        text = "Head north-west of the Canifis lodestone and talk to Netty in her shack (east of the Slayer Tower).",
                        npcs = { "Canifis lodestone", "Netty" },
                    },
                    {
                        text = "Equip the enchanted ghostspeak amulet.",
                        npcs = { "Ghostspeak amulet (enchanted)" },
                    },
                    {
                        text = "Talk to Necrovarus near the Ectofuntus. Once you have talked to Necrovarus, you will be able to enter Port Phasmatys freely. You can pass the energy barrier without needing to pay ecto-tokens.",
                        chat = "1 Let any ghost who so wishes pass on into the next world.",
                        npcs = {},
                    },
