            {
                title = "The king's cure", needed = { "An empty vial, 10 earth runes and 1 cosmic rune to cast Lvl-4 Enchant, a plank, a staff or pole, a clean irit, herb pouch, and yeti hair." },
                steps = {
                    {
                        text = "Ensure you have the standard spellbook enabled.",
                        npcs = {},
