                    {
                        text = "After the cutscene, talk to Manni the Reveller in the longhall and watch another cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                    {
                        text = "Optionally after the quest:",
                        npcs = {},
                        subs = {
                            { text = "Take the unfinished astral rune to Baba Yaga on Lunar Isle.", chat = "2 Talk about astral runes." },
                            { text = "Take the prophecy tablet to Historian Minas on the 2nd floor of the Varrock Museum.", chat = "2 I have some information that might be of use in your displays." },
