    {
        key = "helping_laniakea_miniquest", name = "Helping Laniakea (miniquest)", wiki = "Helping Laniakea (miniquest)/Quick guide",
        required = { "Raw arcane apoterrasaur meat (can be bought from the Grand Exchange or another player)", "Ironmen: 1-3 Raw sharks" },
        recommended = { "Archaeology journal to get to The Stormbreaker faster", "Ways to keep up run energy such as super energy potions, especially at low Agility levels" },
        sections = {
            {
                title = "Embarking on an adventure", needed = {},
                steps = {
                    {
                        text = "Talk to Laniakea at either base camp on Anachronia or the south-eastern part of the island (using Slayer cape).",
                        chat = "3 Let's talk about you. / 4 Tell me about your poisons. / 1 I'll help you out. / Accept",
                        npcs = { "Laniakea", "Anachronia base camp", "Anachronia", "Slayer cape" },
                    },
                    {
                        text = "Collect the following items:",
                        npcs = { "Anachronia Agility Course" },
                        subs = {
                            { text = "Old spring by searching crates next to The Stormbreaker." },
                            { text = "Use archaeology journal to teleport to the Archaeology Campus and run north-east to The Stormbreaker and board it" },
                            { text = "A shimmering feather from the strange bird that can be found on the southern (middle) peninsula of the island." },
                            { text = "This is also a short run from the Moksha ritual site" },
                            { text = "Collect a block of stone by investigating a rock south of Laniakea's second location, at the south-eastern part of the island." },
                            { text = "Use the Grouping System to teleport to Raksha under the \"Boss Fights\" tab and exit the stairway to the west" },
                            { text = "Teleport to Xolo City archaeology site from base camp" },
                            { text = "Use the Slayer cape to teleport to Laniakea" },
                            { text = "A jungle vine, found by investigating the dense jungle vines north-west and across the river from the eastern most overgrown idol in the north-eastern corner of the island. It cannot be obtained from the nearby overgrown idols." },
                            { text = "Ancient arbuck, found by investigating the strange foliage east of the entrance to the Herby Werby D&D." },
                            { text = "Combine it with raw arcane apoterrasaur meat to obtain herby meat." },
                        },
                    },
                    {
                        text = "Collect an immaculate jungle stick by doing the following:",
                        npcs = { "immaculate jungle stick" },
                        subs = {
                            { text = "Bring the block of stone (collected above) talk to either Eliza or Alpheus in order to get a dirty stick." },
                            { text = "Wash the dirty stick in the mucky water next to Eliza and Alpheus to get the immaculate jungle stick." },
                        },
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Create a custom jungle fishing rod by combining the immaculate jungle stick with the jungle vine.",
                        npcs = { "custom jungle fishing rod", "immaculate jungle stick", "jungle vine" },
                    },
                    {
                        text = "Create a custom fishing lure by combining herby meat, the shimmering feather, and the old spring.",
                        npcs = { "custom fishing lure", "herby meat", "shimmering feather", "old spring" },
                    },
                    {
                        text = "Go to the strange fishing spot found on the west side of the island and fish for fugu. The pathway that leads to the fishing spot is by the cannibal jadinkos. The exact fishing spot is north of the luminous snaggler area. The fishing spot can be reached from the luminous snaggler area.",
                        npcs = { "strange fishing spot", "fugu", "cannibal jadinko", "luminous snaggler" },
                    },
                    {
                        text = "Return to Laniakea and give her the fugu.",
                        npcs = { "Laniakea" },
                    },
                },
            },
        },
    },
