                    {
                        text = "Travel to Amberfell, climb over the barricade and go east, then go south before reaching Berylbrook.",
                        npcs = {},
                    },
                    {
                        text = "Enter Moonsylvar Wood south-west of Berylbrook and follow the following paths:",
                        npcs = { "Moonsylvar Wood", "Berylbrook" },
                        subs = {
