                    {
                        text = "Enter the Crimson Gate in the eastern-most part of Shuruk-Ba.",
                        chat = "1 Yes.",
                        npcs = { "Crimson Gate" },
                    },
                    {
                        text = "Talk to Anya or Inanna to begin the fight (this is not a safe fight)..",
