    {
        key = "hermit_permits", name = "Hermit Permits", wiki = "Hermit Permits/Quick guide",
        required = { "Ball of wool", "6 seaweed (obtainable during quest)", "3 ropes" },
        recommended = { "Runes for multiple casts of Wendlewick Teleport" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
