                        npcs = { "Noticeboard (Wendlewick)", "Wendlewick" },
                    },
                    {
                        text = "Talk to Grocer Hannah in the Wendlewick food shop, east of the bank.",
                        chat = "1 Talk about 'Hermit Permits'. / Any / 1 I could try herding them out? / 2 What if I threatened them? / 3 I could just kill them all.",
                        npcs = { "Grocer Hannah", "The Village Grocery" },
                    },
                    {
                        text = "Talk to Shelly, the crab, located in the same store and on the floor.",
                        npcs = { "Shelly" },
