                    {
                        text = "Follow the crab, talking to it every time it stops.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Obtaining the crabulet", needed = {},
                steps = {
                    {
                        text = "Enter the cave to the east and talk to Hermit inside to the north-west.",
                        npcs = { "Hermit" },
                    },
                    {
                        text = "Kill one of the crabs for a fresh crab claw, craft it into an crab amulet (unstrung), and use it on a ball of wool to make a crab amulet.",
                        npcs = { "fresh crab claw", "crab amulet (unstrung)", "crab amulet" },
                    },
                    {
                        text = "Talk to Hermit again.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Equip the crabulet and talk to Shelly.",
                        npcs = { "crabulet" },
                    },
                    {
                        text = "Return to Wendlewick, go back to the food shop, and talk to Shelly.",
                        npcs = {},
                    },
                    {
                        text = "South of the Shrine of Inanna, go to the beach and talk to any of the crabs (Finn, Sandy, or Kai).",
                        npcs = { "Shrine of Inanna", "Finn (Havenhythe)", "Sandy (Havenhythe)", "Kai (Havenhythe)" },
                        subs = {
                            { text = "(Optional) Travel via the canoe station on the dock next to the Burnt Lobster Tavern and then go south-west.", chat = "3 Wendlewick (Grotto)" },
                        },
                    },
                },
            },
            {
                title = "Getting permission", needed = {},
                steps = {
                    {
                        text = "Return to Wendlewick and talk to Adam (in the northern building).",
                        chat = "? Talk about 'Hermit Permits'.",
                        npcs = { "Adam" },
                    },
                    {
                        text = "Talk to Zeke in the building to the east.",
                        chat = "1 Talk about 'Hermit Permits'.",
                        npcs = { "Zeke (Wendlewick)" },
                    },
                    {
                        text = "Talk to Esther upstairs in the lighthouse.",
                        chat = "1 Talk about 'Hermit Permits'.",
                        npcs = { "Esther" },
                    },
                    {
                        text = "Talk to 5 different villagers around Wendlewick to get them to sign the planning permission form. The shop and stall owners work for this.",
                        chat = "1 Talk about 'Hermit Permits'.",
                        npcs = { "Villager (Wendlewick)", "planning permission form" },
                    },
                    {
                        text = "Talk to either Adam, Esther, or Zeke again.",
                        chat = "# Talk about 'Hermit Permits'.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Building the huts", needed = {},
                steps = {
                    {
                        text = "Go back to the southern beach and talk to one of the crab leaders.",
                        npcs = {},
                        subs = {
                            { text = "6 seaweed can be collected to the west on the same beach." },
                            { text = "You also need to bring 3 ropes. If you have the Lorehound pet quest supplies track unlocked you can obtain from there." },
                        },
                    },
                    {
                        text = "Build the three piles of driftwood on the beach into their huts.",
                        npcs = { "pile of driftwood", "driftwood hut" },
                    },
                    {
                        text = "Talk to Finn, Sandy, or Kai.",
                        npcs = {},
