    {
        key = "hero_s_welcome", name = "Hero's Welcome", wiki = "Hero's Welcome/Quick guide",
        required = { "Soft clay", "Mithril bar", "Protection from dragonfire", "to enter the Brimhaven Dungeon, unless Karamja gloves 3 or Dungeoneering cape are owned" },
        recommended = { "Level 100 Combat or more is strongly recommended.", "An enchanted lyre to take you near the quest start point in Rellekka (or Fremennik sea boots 4)", "Either a charged ferocious ring, games necklace, fairy ring BJQ (after being repaired with 5 bittercap mushrooms) or a Slayer cape (to reach the Ancient Cavern)", "Remora's necklace to teleport to the Grotworm Lair", "A hoardstalker ring or Dungeoneering cape to teleport to the Brimhaven Dungeon resource dungeon near the Abomination Cave", "A Beast of Burden to store food for the final fight" },
        sections = {
            {
                title = "Welcoming V", needed = { "An enchanted lyre or Fremennik sea boots 4" },
                steps = {
                    {
                        text = "Talk to Freya Lune or Alfrick the Planner near Rellekka docks.",
                        chat = "Any / Any / Accept",
                        npcs = { "Freya Lune", "Alfrick the Planner", "Rellekka" },
                    },
                    {
                        text = "Talk to the following people about \"V\":",
                        npcs = { "V" },
                        subs = {
                            { text = "Yrsa in the clothes shop nearby.", chat = "1 Can I ask you about V?" },
                            { text = "Peer the Seer who is south-west of the marketplace.", chat = "1 Can I ask you about V?" },
                            { text = "Swensen the Navigator who is in the house south of the marketplace." },
                            { text = "Sigmund The Merchant in the middle of the marketplace.", chat = "1 Can I ask you about V?" },
                            { text = "Brundt the Chieftain in the main hall.", chat = "1 Can I ask you about V?" },
                            { text = "Manni the Reveller, also in the hall.", chat = "1 Can I ask you about V?" },
                            { text = "Olaf the Bard, east of the hall.", chat = "1 Can I ask you about V?" },
                        },
                    },
                    {
                        text = "Return to Alfrick or Freya, right-click celebrate with them.",
                        npcs = {},
                        subs = {
                            { text = "What ballad should be played on V's arrival? — The ballad of the giant basilisk." },
                            { text = "What flowers should be used to decorate the stage? — Winter's Eye." },
                            { text = "Should magic be used in the ceremony? — Yes - Simple air and water magic." },
                            { text = "What sort of feast did V have before he left? — A victory feast." },
                            { text = "How should V be welcomed? — As a returning hero." },
                            { text = "When did V leave the world? — At the end of the Third Age." },
                            { text = "Why did V leave the world? — Out of respect for Guthix." },
                        },
                    },
                    {
                        text = "Watch the cutscene.",
                        chat = "any",
                        npcs = {},
                    },
                },
            },
            {
                title = "Scavenging for energy", needed = { "2 backpack spaces" },
                steps = {
                    {
                        text = "Return to Alfrick at the docks.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Enter cave entrance and talk to V.",
                        chat = "any / 1 Why can't you do it yourself? / 4 I need to get moving.",
                        npcs = { "V" },
                    },
                    {
                        text = "Exit the cave.",
                        npcs = {},
                    },
                    {
                        text = "Investigate 5 locations on the island. There are 2 of each location that you must pair up:",
                        npcs = {},
                        subs = {
                            { text = "2 old docks. (One to the south of the island and one to the east)" },
                            { text = "2 fishing boats. (One to the east of the island and one to the west; the western boat is located on land not in the water)" },
                            { text = "2 gnarled trees. (One to the south-west of the island and one to the north-west)" },
                            { text = "2 cave entrances. (The trapdoors, not the cave you went in earlier) (One in the middle of the island and one to the south-east)" },
                            { text = "2 rock formations. (One to the north of the island and one to the north-west)" },
                        },
                    },
                    {
                        text = "Return to V in the cave.",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene, pass the door into the north room.",
                        npcs = {},
                    },
                    {
                        text = "Search the belongings to the east of the door (south-east corner of the room) and read the journal.",
                        npcs = { "belongings" },
                    },
                    {
                        text = "Solve the map fragments.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Ancient Cavern", needed = { "Soft clay and a mithril bar." },
                steps = {
                    {
                        text = "Travel to the Ancient Cavern.",
                        npcs = { "Ancient Cavern" },
                        subs = {
                            { text = "If using a games necklace, travel to the barbarian outpost and run south to dive into the whirl pool. Then climb-down the rough hewn steps to the north-east." },
                        },
                    },
                    {
                        text = "Go to the south-west corner of the cavern and climb-up the rough hewn steps.",
                        npcs = {},
                    },
                    {
                        text = "South of Kuradal in the Ancient Cavern is an ancient door along the western wall. Try to open the door, then use your soft clay on it.",
                        npcs = { "Kuradal", "Ancient Cavern", "Ancient door (Ancient Cavern)" },
                    },
                    {
                        text = "Go to the mithril dragons. (Head north, go down the rough hewn steps, then up the stairs to the north-east.) Attack a mithril dragon, then use your key mould on the dragon.",
                        npcs = { "mithril dragon", "Key mould (Hero's Welcome)" },
                    },
                    {
                        text = "Go back south west up the rough hewn steps.",
                        npcs = {},
                    },
                    {
                        text = "Open the ancient door with the key.",
                        chat = "1 Yes, I am ready.",
                        npcs = {},
                    },
                    {
                        text = "Kill the dragon.",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene, run west to the stepping stones.",
                        npcs = { "Stepping stone (Dragonkin Lair)" },
                    },
                    {
                        text = "Jump diagonally to the chest and open it, then continue north.",
                        npcs = { "Chest (Dragonkin Lair)" },
                    },
                    {
                        text = "Don't step on any pressure plates. Push the crates out of your way (you are able to push the 2 crates in a line).",
                        npcs = {},
                        subs = {
                            { text = "Push the first eastern crate north twice." },
                            { text = "Walk around to the middle and push the two crates north twice." },
                            { text = "Push the eastern crate to the east twice, then push the northern-most crate to the west once." },
                            { text = "Push the crate to your south once, and walk to the door." },
                        },
                    },
                    {
                        text = "Open the eastern door and search the chest.",
                        npcs = {},
                    },
                    {
                        text = "Read the notes and equip the dragonkin protection charm.",
                        npcs = { "Notes (Hero's Welcome)", "dragonkin protection charm" },
                    },
                    {
                        text = "Enter the bottom floor of the Grotworm Lair near Port Sarim. (There's an agility shortcut from the entrance requiring level 50 Agility.)",
                        npcs = { "Grotworm Lair", "Port Sarim" },
                    },
                    {
                        text = "Climb the stairs in the centre of the open area, west of the Queen Black Dragon entrance.",
                        npcs = { "Queen Black Dragon" },
                    },
                    {
                        text = "Defeat Tarshak, avoiding his charge attack by moving out of the way.",
                        npcs = { "Tarshak" },
                    },
                    {
                        text = "Talk to Phalaks.",
                        chat = "5 I'm done here.",
                        npcs = { "Phalaks" },
                    },
                },
            },
            {
                title = "Final fight", needed = {},
                steps = {
                    {
                        text = "Take lots of high-healing food, including a full BoB if possible. Wear the Dragonkin protective charm at all times, and pray against melee during stage 2.",
                        npcs = { "BoB" },
                    },
                    {
                        text = "Defeat Abomination in the Brimhaven Dungeon in the tunnel found in the south-west corner where steel dragons are.",
                        npcs = { "Abomination", "Brimhaven Dungeon", "steel dragon" },
                    },
                },
            },
            {
                title = "Stage 1", needed = {},
                steps = {
                    {
                        text = "Focus on mining the 4 pillars in the room while avoiding his attacks. Surge, double surge, and bladed dive can be useful in avoiding damage from the Abomination's rotating beam of fire.",
                        npcs = { "Surge", "double surge", "bladed dive" },
                        subs = {
                            { text = "His charge attacks are often not aimed at the player, meaning you don't always need to move." },
                        },
                    },
                    {
                        text = "When a pillar cannot be mined any more, lure a fireball attack into the pillar. Click the water pool if you get hit to cool off.",
                        npcs = {},
                    },
                    {
                        text = "Repeat until all 4 pillars are broken.",
                        npcs = {},
                    },
                    {
                        text = "A good strategy is to stand near the pillar and take the fireball damage, this guarantees the destruction of the pillar as long as it is no longer minable.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Stage 2", needed = {},
                steps = {
                    {
                        text = "Lure Tarshak into the falling rocks, don't stand too close yourself.",
                        npcs = {},
                    },
                    {
                        text = "You may also attack with a regular weapon at the same time.",
                        npcs = {},
                    },
                    {
                        text = "Once Tarshak reaches 458 life points, he will no longer take damage from falling rocks, and you must deal the final blow yourself.",
                        npcs = {},
                    },
                },
            },
            {
                title = "V's Island", needed = {},
                steps = {
                    {
                        text = "Watch the cutscene.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Return to Freya and Alfrick in Rellekka.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Enter the cave and pass the door.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Freya or Alfrick.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "heroes_quest", name = "Heroes' Quest", wiki = "Heroes' Quest/Quick guide",
        required = { "Ice gloves (can be obtained during the quest)", "Harralander potion (unfinished)", "Fishing rod (can be obtained during the quest)", "Fishing bait if baitless fishing is not unlocked (can be obtained during the quest)", "For completing the quest solo:", "Multiple lockpicks in case of failure, or a hair clip, or master thief's lockpick (tool belt works)", "Either one (you may switch your gang):", "Black Arm Gang members: black full helm, platebody and platelegs (plateskirt will not work; trimmed armour versions also do not work)", "Phoenix Gang members: or ring of charos (a)", "For completing the quest with a partner:", "Black Arm Gang members: black full helm, platebody and platelegs (plateskirt will not work)", "Phoenix Gang members: ranged or magic weapons" },
        recommended = { "Activated Burthorpe, Karamja, Taverley (or Catherby) and Varrock lodestones", "Law altar teleport for faster access to Entrana", "Dusty key (or level Level 70 Agility; can be obtained during quest; not required if fishing for lava eels in the Lava Maze) or a Mask of the Black Demon to teleport to Taverley Dungeon" },
        sections = {
