    {
        key = "horror_from_the_deep", name = "Horror from the Deep", wiki = "Horror from the Deep/Quick guide",
        required = { "For fixing the bridge:", "60 steel nails", "2 normal planks (can be obtained during the quest, just north of the fenced-in area of the Barbarian Outpost)", "For fixing the lighthouse mechanism:", "Molten glass", "1 swamp tar", "For activating the wall:", "1 Fire rune", "1 Water rune", "1 Earth rune", "1 Air rune", "A sword of any type that you are willing to lose", "An arrow of any type (except ogre and training) that you are willing to lose" },
        recommended = { "Level 43 Prayer", "A melee weapon (ideally a slash weapon), a ranged weapon (ideally thrown weapons), and magic weapon plus runes for all four elemental spells to switch amongst in combat. Necromancy does not work against the Dagannoth mother.", "Games necklace and quick teleport tabs are very helpful to reach the Lighthouse during the quest.", "Houses by Rellekka are also helpful transportation methods.", "Lighthouse Teleport for quick teleportation to Larrissa" },
        sections = {
            {
                title = "Getting started", needed = { "Lighthouse Teleport or games necklace" },
                steps = {
                    {
                        text = "Head to the lighthouse north of the Barbarian Outpost and talk to Larrissa.",
                        chat = "1 With what? / 1 But how can I help? / Accept / 3 I'll see what I can do",
                        npcs = { "lighthouse", "Barbarian Outpost", "Larrissa" },
                    },
                },
            },
            {
                title = "Preparations", needed = { "60 steel nails, 2 planks, molten glass, swamp tar, 1 free inventory slot" },
