                        npcs = { "Barbarian Outpost Agility Course" },
                    },
                    {
                        text = "Enter through the gate, then go through the Obstacle pipe.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Gunnjorn. (Make sure to have 1 free inventory slot)",
                        chat = "1 Talk about Horror from the Deep.",
                        npcs = { "Gunnjorn" },
                    },
                    {
                        text = "Far east of Larrissa, go to a broken bridge, just past the crystal tree.",
                        npcs = { "crystal tree" },
                    },
                    {
                        text = "Fix the bridge from both sides (you can cross the bridge after the first side is repaired and right-click fix the other side).",
                        npcs = {},
                    },
                    {
                        text = "Return to the lighthouse and go to the 3rd floor and Repair the lighting mechanism three times.",
                        npcs = { "lighting mechanism" },
                    },
                },
            },
            {
                title = "The battle", needed = { "fire rune, air rune, water rune, earth rune (a staff will not work for any of these), any smithable sword, an arrow, combat equipment" },
                steps = {
                    {
                        text = "Climb the iron ladder on the 1st floor to go to the lighthouse basement.",
                        npcs = {},
                    },
                    {
                        text = "To open the strange wall, use a fire rune, air rune, water rune, earth rune, a sword, and an arrow on it.",
                        chat = "1 Yes / 1 Yes / 1 Yes / 1 Yes / 1 Yes / 1 Yes",
                        npcs = { "strange wall", "fire rune", "air rune", "water rune", "earth rune", "Swords", "arrow" },
