                    },
                    {
                        text = "Kill the dagannoth that appears.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Jossik again, and then kill the Dagannoth mother when it appears.",
                        npcs = { "Dagannoth mother" },
                        subs = {
                            { text = "Strategies can be found here; note that Necromancy does not have any effect on the dagannoth mother. The below table shows her weaknesses in different forms:" },
                        },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "The God Books", needed = {},
                steps = {
                    {
                        text = "Go to the 2nd floor of the lighthouse.",
                        npcs = {},
                    },
                    {
                        text = "Show the rusty casket to Jossik.",
                        npcs = { "rusty casket" },
                        subs = {
                            { text = "If you had a full inventory when defeating the Dagannoth mother, you will not receive a rusty casket. Instead, you must talk to Jossik, who will have picked it up for you." },
