                    {
                        text = "You may now choose a book affiliated with three gods: Saradomin's Book of Wisdom, Guthix's Book of Balance or Zamorak's Book of Chaos.",
                        npcs = { "Saradomin's Book of Wisdom", "Guthix's Book of Balance", "Zamorak's Book of Chaos" },
                        subs = {
                            { text = "Be sure to choose the same book twice in a row when he asks if you are sure about your selection." },
                        },
                    },
