    {
        key = "impressing_the_locals", name = "Impressing the Locals", wiki = "Impressing the Locals/Quick guide",
        required = {},
        recommended = { "Activated Port Sarim and Draynor lodestones" },
        sections = {
            {
                title = "Walkthrough", needed = {},
                steps = {
                    {
                        text = "Right click to talk to Trader Stan located at the south-eastern dock of Port Sarim. Finish all dialogue.",
                        chat = "2 Talk about the Skulls pirate, Jed. / Accept / 1 About a quartermaster. / 2 About a navigator. / 3 About a bosun. / 4 Never mind.",
                        npcs = { "Trader Stan" },
                        tile = { x = 3033, y = 3190, plane = 0 },
                    },
                    {
                        text = "Talk to Guard Captain Roarkwin in the Port Sarim jail located to the west. Finish all dialogue.",
                        npcs = { "Guard Captain Roarkwin", "Port Sarim jail" },
                    },
                    {
                        text = "Enter the port portal near the northern dock.",
                        npcs = { "port portal" },
                        subs = {
                            { text = "Ignore the dialogue about Meg which triggers after you enter the portal." },
                        },
                    },
                    {
                        text = "Talk to Seasinger Umi to the southeast of the portal. Finish all dialogue.",
                        npcs = { "Seasinger Umi" },
                    },
                    {
                        text = "Talk to the Barmaid in a building to the northwest of the portal.",
                        chat = "1 Yes.",
                        npcs = { "the Barmaid" },
                    },
                    {
                        text = "Climb up the stairs and talk to Mister Gully.",
                        npcs = { "Mister Gully" },
                    },
                    {
                        text = "Head to the pottery house in Draynor Village and climb up the stairs.",
                        npcs = { "Draynor Village" },
                    },
                    {
                        text = "Talk to the Black Knight sergeant.",
                        npcs = { "Bosun Higgs" },
                        subs = {
                            { text = "If your character does not talk about Jacob, make sure you finish all dialogue with Guard Captain Roarkwin." },
                        },
                    },
                    {
                        text = "Head to Rimmington and talk to Seasinger Jemi near the well.",
                        npcs = { "Rimmington", "Seasinger Jemi" },
                    },
                    {
                        text = "Back at the Port Sarim docks, talk to Trader Stan.",
                        chat = "2 Talk about the Skulls pirate, Jed.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "Impressing the Locals",
                        npcs = { "Impressing the Locals (achievement)" },
                    },
                },
            },
        },
    },
    {
        key = "in_aid_of_the_myreque", name = "In Aid of the Myreque", wiki = "In Aid of the Myreque/Quick guide",
        required = { "Items marked with † can be easily acquired during the quest by either obtaining them from the surrounding area or by purchasing them from Razmire's store, if you have completed Shades of Mort'ton.", "At least 1 piece of food †", "A silver weapon (silver bolts do not work, havensilver weapons will not work against the juvinates in the Burgh de Rott general store), and armour to beat several enemies up to level 68", "For building the pub, general store and bank:", "1–5 buckets † (can be picked up by the well in Burgh de Rott)", "11 regular planks † (protean planks do not work)", "Swamp paste (not tar) †", "36–45 nails of any metal (you might get enough of them from mining the rubble)", "10 bronze hatchets", "Either 10 raw mackerel † or 10 raw snails † (depending on the store-owner's choice; any size or combination works), or a weapon and big fishing net to gather them yourself. Mackerel can be obtained at the boat dock south-east of the pub, and snails can be obtained in Morytania.", "3 tinderboxes †", "For building the furnace (these items can be kept in the bank but do not keep in the metal bank):", "2 steel bars", "1 piece of coal", "For making the rod of Ivandis (these items can be kept in the bank or metal bank):", "A piece of soft clay", "Silver bar", "Mithril bar", "A cut sapphire", "1 cosmic and water rune, or a Lvl-1 enchant tablet.", "Rope" },
        recommended = { "Completion of Shades of Mort'ton for access to Razmire Builders' Merchants.", "A charged druid pouch", "or a ring of charos (a)", "A second silver weapon to provide to Ivan (not recoverable)", "Steel equipment (med helm, chainbody, and platelegs) and food for Ivan (up to 15 pieces of cooked snails, salmon, slimy eel or stew). This is only needed for lower level players, as the enemies you have to protect Ivan from mainly focus their attacks on the player. (not recoverable)", "1–2 Guthix balance potions for the journey.", "Attuning the boss portal from War's Retreat to the Barrows Brothers provides an easy teleport to a bank chest and a way past Mort Myre Swamp." },
        sections = {
            {
                title = "Burgh de Rott", needed = { "1 food, 1-5 buckets and 9 free spaces, preferably charged druid pouch so your food won't rot" },
                steps = {
                    {
                        text = "In the hideout behind the Canifis pub, go through the secret wall and squeeze past the stalagmite on the east side of the cave",
                        npcs = {},
                    },
                    {
                        text = "Talk to Veliaf Hurtz.",
                        chat = "1 I want to join your organisation. / 3 Can you tell me about the job? / Accept / 1 Ok, I'll do the job.",
                        npcs = { "Veliaf Hurtz" },
                    },
                    {
                        text = "Travel to Mort'ton. The fastest way is by heading south of the cave, exiting through the doors, climbing the same tree from In Search of the Myreque and using the swamp boat south, or using a portal to the Barrows in War's Retreat.",
                        npcs = { "Mort'ton", "In Search of the Myreque", "swamp boat", "Barrows", "War's Retreat" },
                        subs = {
                            { text = "If you need a piece of food, there are snails to the west of Mort'ton that can be cooked with level 12 Cooking." },
                        },
                    },
                    {
                        text = "Speak to Florin, south of the bridge to Burgh de Rott, who won't let you pass yet. (Make sure to finish dialogue options)",
                        npcs = { "Florin", "Burgh de Rott" },
                    },
                    {
                        text = "Search the chest.",
                        npcs = {},
                    },
                    {
                        text = "Use food on the chest.",
                        npcs = {},
                    },
                    {
                        text = "Jump the gate.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Florin.",
                        chat = "4 Are there any 'out of the way' places in here? / 5 Ok, thanks!",
                        npcs = {},
                    },
                    {
                        text = "Climb over the broken down wall in the building just south-east of the well. It'll be near an unreachable pile of rubble that you can mine.",
                        npcs = {},
                    },
                    {
                        text = "Mine the rubble to clear the trap door, then open the trapdoor and climb down.",
                        npcs = {},
                    },
                    {
                        text = "Mine and use spade to remove all the rubble piles (15). Your bucket can be emptied on the pile outside the pub.",
                        npcs = {},
                        subs = {
                            { text = "1 bucket will allow you to mine 3 piles before it needs to be emptied in the pile outside. There is a bucket next to the well if you need one." },
                            { text = "Bucket(s) of rubble may be disassembled or alchemized to avoid the need to empty them outside." },
                            { text = "Any items left on the ground when you climb back up the ladder will be lost." },
                        },
                    },
                    {
                        text = "Go up and talk to any villager.",
                        chat = "3 I'd like to help fix up the town. / 4 Ok, thanks.",
                        npcs = {},
                    },
                },
            },
            {
                title = "General store and bank", needed = { "11 planks, 10 bronze hatchets, 3 tinderboxes, 44 nails, 2 steel bars, 1 swamp paste, 1 coal and 10 raw mackerel or snails (all un-noted). A beast of burden familiar may also help out in holding all the needed supplies. A plank box may help with inventory space as well." },
                steps = {
                    {
                        text = "Talk to Aurel in the general store.",
                        chat = "3 I'd like to help fix up the town. / 4 What should I do now? / 5 Ok, thanks.",
                        npcs = { "Aurel" },
                    },
                    {
                        text = "Climb the ladder outside and use a plank on the Broken Roof (3 planks, 12 nails required).",
                        npcs = { "Broken Roof" },
                    },
                    {
                        text = "Climb down and use a plank on the damaged wall (3 planks, 12 nails required).",
                        npcs = {},
                    },
                    {
                        text = "Talk to Aurel.",
                        chat = "4 What should I do now? / 5 Ok, thanks.",
                        npcs = {},
                    },
                    {
                        text = "Fill the box with supplies: 10 bronze hatchet, 3 tinderbox and 10 raw mackerel or snails. The snails can be cooked or raw (depending on what Aurel asked for, check the in-game quest journal if you forget).",
                        npcs = { "raw mackerel", "quest journal" },
                    },
                    {
                        text = "Return the crate to Aurel.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Cornelius in the bank.",
                        chat = "4 What should I do now? / 5 Ok, thanks.",
                        npcs = { "Cornelius" },
                    },
                    {
