    {
        key = "in_search_of_the_myreque", name = "In Search of the Myreque", wiki = "In Search of the Myreque/Quick guide",
        required = { "Six steel weapons (cannot be +1 or off-hand versions):", "Steel dagger", "Steel mace", "2 steel swords", "Steel longsword", "Steel warhammer", "75 steel nails", "Druid pouch containing at least 5 charges (You can bring the items without filling the pouch until needed, to ensure you have enough charges)", "6 normal planks (Protean planks do not work)" },
        recommended = { "Silver sickle (b) to fill the druid pouch (You will need some prayer points to cast bloom with the sickle)", "Activated Canifis lodestone" },
        sections = {
            {
                title = "Getting started", needed = { "Steel weapons, 75 steel nails, druid pouch, normal planks, combat equipment" },
                steps = {
                    {
                        text = "Talk to Vanstrom Klause in the Hair of the Dog tavern in Canifis.",
                        chat = "2 Why do they need help? Are they in trouble? / 4 Perhaps I could help you out here. / 4 Yes, I'll do it! / Accept",
                        npcs = { "Vanstrom Klause", "Hair of the Dog", "Canifis" },
                    },
                    {
                        text = "Make sure you finish the dialogue or the quest won't start.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Swamp trekking", needed = {},
                steps = {
                    {
                        text = "Obtain a Druid pouch with at least six items in it. It is required for the section below. The Ouroboros pouch will not work.",
                        npcs = { "Druid pouch", "Ouroboros pouch" },
                        subs = {
                            { text = "It is required to have six as Ghasts will rot the items within the pouch." },
                            { text = "If you do not have charges in your druid pouch, make sure you have prayer points to cast bless to obtain more in the swamp." },
                            { text = "You will need a Silver sickle (b) to cast bloom." },
                        },
                    },
                    {
                        text = "Go to Mort'ton by either running through the swamp or using the fairy ring BKR and taking the boat south-east of the fairy ring. Alternatively, use a portal at War's Retreat tuned to the Barrows Brothers for fast access.",
                        npcs = { "fairy ring" },
                    },
                },
            },
            {
                title = "The hideout", needed = {},
                steps = {
                    {
                        text = "Talk to Cyreg Paddlehorn, before the bridge east of Mort'ton.",
                        chat = "2 Well, I guess they'll just die without weapons. / 2 Resourceful enough to get their own steel weapons? / 3 If you don't tell me, their deaths are on your head! / 3 What kind of a man are you to say that you don't care? / 1 Give wooden planks to Cyreg.",
                        npcs = { "Cyreg Paddlehorn" },
                    },
                    {
                        text = "Use the boat to get to the Hollows.",
                        npcs = {},
                    },
                    {
                        text = "Go north and climb up the strange tree. Look for a bridge on the map.",
                        npcs = {},
                    },
                    {
                        text = "Left click the bridge one step north, the bridge will break. Click it again to repair it. You can also right click and select Repair option. Repeat until the bridge is fully repaired (requires 75 steel nails and three planks).",
                        npcs = {},
                    },
                    {
                        text = "Climb down, go just north-east to the hollow tree, and talk to Curpile Fyod. The questions are random. The answers to his question are as follows:",
                        chat = "1 I've come to help the Myreque. I've brought weapons.",
                        npcs = { "Curpile Fyod" },
                    },
                    {
                        text = "Open the doors on the rock behind the tree and follow the tunnel.",
                        npcs = {},
                    },
                    {
                        text = "Squeeze-past the stalagmite at the east wall, next to the stone brazier.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Veliaf Hurtz.",
                        npcs = { "Veliaf Hurtz" },
                    },
                    {
                        text = "Talk to all the other members, first dialogue will be enough.",
                        chat = "5 Ok, thanks.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Veliaf again. Cutscene follows.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Kill the Skeleton Hellhound.",
                        npcs = { "Skeleton Hellhound" },
                    },
                    {
                        text = "Talk to Veliaf.",
                        chat = "3 How do I get out of here? / 5 Ok, thanks.",
                        npcs = {},
                    },
                    {
                        text = "Go back into the tunnel and search the wall to the north. This unlocks the achievement I Wonder How Far It Ghost?",
                        npcs = { "I Wonder How Far It Ghost?" },
                    },
                    {
                        text = "Climb up the ladder. (Do not Teleport to Canifis)",
                        npcs = {},
                    },
                    {
                        text = "Talk to the stranger next to the stairs where Vanstrom was located.",
                        npcs = { "Stranger (In Search of the Myreque)" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "In Search of the Myreque",
                        npcs = { "In Search of the Myreque (achievement)" },
                    },
                    {
                        text = "Morytania achievements",
                        npcs = { "Morytania achievements" },
                        subs = {
                            { text = "Medium - I Wonder How Far It Ghost?" },
                        },
                    },
                },
            },
        },
