                            { text = "South-west: Snothead", chat = "1 Where is Yu'biusk? / 1 What was your predecessor's name? / 4 Goodbye." },
                            { text = "South-east: Snailfeet", chat = "2 Snailfeet / 2 What was your predecessor's name?" },
                            { text = "North-west: Mosschin", chat = "3 Mosschin / 2 What was your predecessor's name?" },
                            { text = "North-east: Redeyes", chat = "4 Redeyes / 2 What was your predecessor's name?" },
                            { text = "North: Strongbones (ignore his skeleton minions)", chat = "5 Strongbones" },
                        },
                    },
                    {
                        text = "Talk to Strongbones after defeating him.",
                        chat = "1 Where is Yu'biusk? / 4 Goodbye.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Home portal", needed = {},
                steps = {
                    {
                        text = "Return to Dorgesh-Kaan and speak with Zanik in the north-west (Oldak's lab).",
                        npcs = {},
                    },
                    {
                        text = "With a light source, head to the south end of Dorgesh-Kaan using fairy code AJQ. Alternatively, without using fairy rings:",
                        npcs = {},
                        subs = {
                            { text = "Go up the stairs to the agility course." },
                            { text = "At the start of the agility course, climb down the ladder west of the agility cable." },
                            { text = "Follow the cave path east then south to the Fairy ring." },
                        },
                    },
                    {
                        text = "Adjust the machines next to Oldak, use combination 9-4-1, activate the machine.",
                        npcs = {},
                    },
                    {
                        text = "Open the strange box in the north-western part of Yu'biusk for a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Continue dialogue with Oldak.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "learning_the_ropes", name = "Learning the Ropes", wiki = "Learning the Ropes/Quick guide",
        required = {},
        recommended = {},
        sections = {
            {
                title = "Walkthrough", needed = {},
                steps = {
                    {
                        text = "Skip the tutorial by clicking the button on the options menu.",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "legacy_of_seergaze", name = "Legacy of Seergaze", wiki = "Legacy of Seergaze/Quick guide",
        required = { "Teak or higher-level pyre logs", "Combat gear (Necromancy or two different combat styles recommended for lower-level players)", "10 nails (obtained during quest from Flaygian)", "1 coal (can be obtained during the quest)", "Items to use Lvl-2 Enchant:", "Lvl-2 enchant tablet (if not on the standard spellbook) or;", "1 cosmic rune and 3 air runes (can be obtained during the quest)", "1 mithril bar (can be obtained during the quest, metal bank works)", "1 silver bar (can be obtained during the quest, metal bank works)", "1 silver sickle (b) (can be obtained during the quest)", "1 emerald (can be obtained during the quest)", "1 saw (cannot use the default one on the tool belt, one can be obtained during the quest)" },
        recommended = { "Teleport to Canifis (Kharyrll Teleport or teleport tablets/runes for Canifis portal in a player-owned house) or an activated Canifis lodestone", "Invitation box for fast transportation to Paterdomus", "Shortcut key (can be stored on a steel key ring, if not planning on using the mines method to return to the Myreque Hideout in Meiyerditch)", "Druid pouches or ouroboros pouch (if carrying food through the swamp)", "Food (monkfish or higher recommended if you are a low level)", "Rod of Ivandis (in case you need to defeat juvinate during the Burgh de Rott Ramble)" },
        sections = {
            {
                title = "An evil conspiracy", needed = { "Rod of Ivandis, or another silver weapon, and 2 backpack space" },
                steps = {
                    {
                        text = "Talk to the Mercenary Adventurer at the Temple Trekking ending point (west of Canifis). CKS or the Canifis lodestone are good options to reach the area quickly.",
                        chat = "Accept / 3 Okay, thanks.",
                        npcs = { "Mercenary Adventurer", "Temple Trekking", "Canifis", "Canifis lodestone" },
                    },
                    {
                        text = "Enter the Mausoleum west of the Adventurer.",
                        npcs = { "Paterdomus" },
                    },
                    {
                        text = "Talk to Drezel.",
                        chat = "2 Who do you think these suspicious people are? / 4 Okay, thanks.",
                        npcs = { "Drezel" },
                    },
                    {
                        text = "Go through the gate west of Drezel and climb down the stairs north of the well.",
                        npcs = {},
                    },
                    {
                        text = "Search the sparkling wall storage unit a few steps east of the stairs, then go back up the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Exit the Mausoleum via the west entrance ladder, enter the Paterdomus temple and head to the top floor.",
                        npcs = { "Paterdomus" },
                    },
                    {
                        text = "After the cutscene, kill Fistandantilus and Zaromark Sliver (or wait until they time out and teleport away).",
                        npcs = { "Fistandantilus", "Zaromark Sliver" },
                        subs = {
                            { text = "Both enemies have 2,750 life points, a combat level of 77, and a max hit of 220 in magic and ranged. These enemies will use prayer to become immune to your combat style, but do not protect against necromancy. Necromancy or multiple combat styles are recommended for this fight." },
                        },
                    },
                    {
                        text = "Search the crude table in the north-west corner of the room.",
                        npcs = {},
                    },
                    {
                        text = "Return to Drezel.",
                        chat = "2 Do you think this has anything to do with the Guthixian Edicts?",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Mercenary Adventurer and escort him the same way as any Burgh de Rott Ramble.",
                        npcs = { "Temple Trekking" },
                        subs = {
                            { text = "Easy path recommended for least time and effort. Be sure to remove any melee-reducing equipment like ranged and magic armour. If you encounter juvinates, you will require your Rod of Ivandis or another silver weapon." },
                        },
                    },
                    {
                        text = "Once in Burgh de Rott, if the dialogue does not automatically start, talk to the Mercenary Adventurer.",
                        npcs = { "Burgh de Rott" },
                        subs = {
                            { text = "If no one with that name is present in Burgh de Rott, skip to the next step." },
                        },
                    },
                },
            },
            {
                title = "The Myreque's task", needed = {},
                steps = {
                    {
                        text = "Climb over the wall inside the Pub and then climb down the trapdoor to the cellar.",
                        npcs = { "Trapdoor (Burgh de Rott cellar)" },
                    },
                    {
                        text = "Talk to Veliaf Hurtz until he gives you a crate.",
                        chat = "2 Do you have a job for me? / 3 Okay, thanks.",
                        npcs = { "Veliaf Hurtz" },
                    },
                    {
                        text = "Climb up the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Go south of Burgh de Rott and take the boat to Meiyerditch.",
                        npcs = { "Meiyerditch" },
                    },
                    {
                        text = "Go to the Meiyerditch Myreque base. Refer to the Meiyerditch shortcut guide for help. Being caught by the vyrewatch and sent to mines provides a fast and reliable route.",
                        npcs = { "Meiyerditch shortcut guide", "vyrewatch" },
                    },
                    {
                        text = "Talk to Flaygian Screwte, in the north room, and offer him your help.",
                        chat = "3 How's the research going? / 4 Can I help in some way? / 5 Okay, thanks.",
                        npcs = { "Flaygian Screwte" },
                    },
                },
            },
            {
                title = "In search of the weapon", needed = {},
                steps = {
                    {
                        text = "Ask Andiess Juip or Kael Forshaw in the same room about weapons.",
                        chat = "2 Hi there, I was wondering if I could ask some questions?",
                        npcs = { "Andiess Juip", "Kael Forshaw" },
                        tile = { x = 3635, y = 3320, plane = 0 },
                    },
                    {
                        text = "Go to the next room south (near Mekritus A'hara) and search the middle bunk bed on the eastern half of the north wall for a book.",
                        npcs = {},
                    },
                    {
                        text = "Read it and remember which page mentioned flails.",
                        npcs = {},
                    },
                    {
                        text = "Give the book to Flaygian, giving him the proper page number. He will give you 10 nails and a hammer. (You can drop the hammer)",
                        npcs = {},
                    },
                    {
                        text = "Head to the northernmost part of Meiyerditch and enter the house south of the house with the furnace (\"mass of debris\").",
                        npcs = { "Meiyerditch" },
                    },
                    {
                        text = "Use the Make-ladder option on the centre post.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the post.",
                        npcs = {},
                    },
                    {
                        text = "Jump across the floorboards to the east, then to the north.",
                        npcs = {},
                    },
                    {
                        text = "Jump west through the damaged wall.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the ladder and search the trough.",
                        npcs = {},
                    },
                    {
                        text = "Take a piece of coal from the coal barrel.",
                        npcs = { "coal" },
                    },
                    {
                        text = "Go to the bottom floor and select \"dig\" on the mass of debris (right click).",
                        npcs = {},
                        subs = {
                            { text = "If the \"dig\" option doesn't appear, you must go back to the top floor and search the trough" },
                        },
                    },
                    {
                        text = "Use the coal on the furnace, then light the furnace.",
                        npcs = {},
                    },
                    {
                        text = "Return and talk to Flaygian, then in the same room;",
                        npcs = {},
                        subs = {
                            { text = "Take 2 silver and 2 mithril bars from the barrel on the northern wall." },
                            { text = "Take a blessed sickle from the shelf on the south-western wall." },
                        },
                    },
                    {
                        text = "Go to the room to the east of the entrance ladder.",
                        npcs = {},
                    },
                    {
                        text = "Search the crate for a chain link mould and add it to your tool belt.",
                        npcs = { "chain link mould", "tool belt" },
                    },
                    {
                        text = "Return to the furnace and make the Silvthril chain. It can be found by clicking on the silver bar in the smithing interface (scroll with down arrow next to \"Casting Metals & Glass\").",
                        npcs = { "Silvthril chain", "silver bar" },
                        subs = {
                            { text = "You do not need to make 2, you will have 1 bar of each type left. These are not used at any point in the quest so you can safely deposit them into your metal bank." },
                        },
                    },
                    {
                        text = "Talk to Flaygian, then use the blessed sickle on him.",
                        chat = "2 How about using this as the head for the flail?",
                        npcs = {},
                    },
                    {
                        text = "Talk to Safalaan.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Back to the lab", needed = {},
                steps = {
                    {
                        text = "Proceed to the laboratory; the building south-east of the furnace, third from the top on the east wall and through the slashed tapestry.",
                        npcs = {},
                    },
                    {
                        text = "Dismiss any followers and climb down the stairs.",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene, Look at one of the bodies in the north-west corner.",
                        chat = "2 Is there anything I can do? / 3 Okay, thanks.",
                        npcs = {},
                    },
                    {
                        text = "Search the door to the south and use the saw in your tool belt.",
                        npcs = {},
                    },
                    {
                        text = "Climb-through the door, then after the cutscene continue down the long and winding tunnel.",
                        npcs = {},
                    },
                    {
                        text = "Continue north on the path to the large chamber where the strange stones are.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Vyrewatch and the Ivandis flail", needed = {},
                steps = {
                    {
                        text = "If you need runes for the Lvl-2 Enchant spell, search the corpse next to the rocks before continuing.",
                        npcs = { "Lvl-2 Enchant" },
                        subs = {
                            { text = "Searching the corpse will complete the Bloodstained Treasure achievement, if not already completed." },
                        },
                    },
                    {
                        text = "Search the strange stones in the northern part of the cavern.",
                        npcs = { "strange stones" },
                    },
                    {
                        text = "Talk to Safalaan. There will be a cutscene and a fight against vyrewatches in which you cannot deal any damage, but the fight will end in another cutscene with Safalaan being attacked.",
                        npcs = { "vyrewatch" },
                    },
                    {
                        text = "Make sure you have 4 free backpack spaces, then talk to Safalaan.",
                        npcs = {},
                    },
                    {
                        text = "Use the emerald on the sickle (right click, don't accidentally make bolt tips).",
                        npcs = {},
                    },
                    {
                        text = "Use the Lvl-2 Enchant spell on it.",
                        npcs = { "Lvl-2 Enchant" },
                    },
                    {
                        text = "Use the chain on it.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Safalaan.",
                        npcs = {},
                    },
                    {
                        text = "Go to the surface, equip the Ivandis flail, kill a vyrewatch, and pick up its corpse.",
                        npcs = { "Ivandis flail" },
                    },
                    {
                        text = "Return to Safalaan.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Back to the Columbarium", needed = { "Teak pyre logs or better" },
                steps = {
                    {
                        text = "Return to the basement of the pub in Burgh de Rott and talk to Veliaf. Ask him what to do. Ensure your quest log updates to say to speak to Drezel.",
                        chat = "1 The Flail of Ivandis kills Vyrewatch! / 4 What should I do now? / 5 Okay, thanks.",
                        npcs = { "Burgh de Rott", "Veliaf" },
                    },
                    {
                        text = "Return to and talk to Drezel at the Mausoleum.",
                        chat = "2 Veliaf asked me to bring this Vyrewatch corpse to you. / 4 Okay, thanks.",
                        npcs = { "Drezel" },
                    },
                    {
                        text = "Go through the west gate, then down the stairs north of the well.",
                        npcs = {},
                    },
                    {
                        text = "Use the pyre logs on a funeral pyre, then the vyre corpse. Light it.",
                        npcs = {},
                    },
                    {
                        text = "Take the ornate tomb key from the pedestal.",
                        npcs = { "ornate tomb key" },
                    },
                    {
                        text = "Use it on the wall storage unit from the beginning of the quest on the north-eastern side of the room (the same one that is still sparkling) to acquire a blood talisman.",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene, go upstairs and ask Drezel what to do. If you still have the library key:. Otherwise, to bypass getting a new key.",
                        chat = "2 What should I do now? / 3 Okay, thanks. / 1 Talk about items. / 2 What should I do now? / 3 Okay, thanks.",
                        npcs = {},
                    },
                    {
                        text = "Report to Veliaf in the Burgh de Rott pub basement.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "Legacy of Seergaze",
                        npcs = { "Legacy of Seergaze (achievement)" },
                    },
                    {
                        text = "Bloodstained Treasure",
                        npcs = { "Bloodstained Treasure" },
                    },
                    {
                        text = "Ivan is Flailing",
                        npcs = { "Ivan is Flailing" },
                    },
                    {
                        text = "Morytania achievements",
                        npcs = { "Morytania achievements" },
                        subs = {
                            { text = "Hard" },
                            { text = "Runecraft Carrier" },
                            { text = "Shade-Shattering Ka-Bloom" },
                            { text = "Just One More Key..." },
                            { text = "Elite - As You Might Expect" },
                        },
                    },
                    {
                        text = "Tirannwn achievements",
                        npcs = { "Tirannwn achievements" },
                        subs = {
                            { text = "Hard - What a Rush" },
                        },
                    },
                },
            },
        },
    },
    {
        key = "legends_quest", name = "Legends' Quest", wiki = "Legends' Quest/Quick guide",
        required = { "A rope", "An empty vial", "A vial of water", "3 papyrus (can be obtained during the quest)", "1 charcoal", "An unpowered orb (two if taking the easy way)", "2 gold bars (more recommended in case of smithing failure, metal bank does not work)", "Clean ardrigal and clean snake weed (can be obtained during the quest)", "A cut opal, jade, red topaz, sapphire, emerald, ruby, and diamond", "Runes for two casts of any Charge Orb spell (bring more to be safe)", "Lockpick, hair clip or a master thief's lockpick (tool belt works)", "Unaugmented rune hatchet or better (tool belt works; the hatchet might have to be used on the item)", "Runes, depending on your version of RuneScape:", "English: 1 soul, mind, earth, and 2 law runes", "German: 1 air, blood, nature, and 2 earth runes", "French: 1 law, air, death, mind, and blood rune", "Portuguese: 1 fire, water, earth, air, and law rune" },
        recommended = { "Level 43 Prayer (highly recommended for Protect from Melee)", "Level 50 Ranged (if wielding holy water against Nezikchened)", "Level 100 Combat", "5 bittercap mushrooms to activate fairy ring CJS in the Kharazi Jungle", "Portable fairy ring for quick access to the jungle if you repair the fairy ring", "Weapon, armour, food and several prayer potions", "1-10 empty vials to be enchanted during the quest.", "Silverlight or Darklight to weaken the demon", "A Beast of Burden to carry more items and save trips" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to a Legends' guard at the Legends' Guild north-east of East Ardougne (fairy ring BLR).",
                        chat = "3 Can I speak to someone in charge? / 1 Can I go on the quest? / 2 Yes, I'd like to talk to Grand Vizier Erkle.",
                        npcs = { "Legends' guard", "Legends' Guild", "East Ardougne" },
                    },
                    {
                        text = "Talk to Radimus Erkle.",
                        chat = "1 Yes actually, what's involved? / Accept",
                        npcs = { "Radimus Erkle" },
                    },
                    {
                        text = "If required, take 3 papyrus from Radimus' table. Alternatively, Obli's General Store in the Shilo Village sells 10 papyrus as well.",
                        npcs = { "papyrus", "Obli's General Store", "Shilo Village (location)" },
                    },
                },
            },
            {
                title = "Kharazi Jungle", needed = { "Radimus notes, 3 papyrus, 1 charcoal" },
                steps = {
                    {
                        text = "Chop-down the Jungle Trees/Bushes south of Shilo Village (fairy ring CKR) to access the Kharazi Jungle.",
                        npcs = { "Jungle Tree", "Jungle Bush", "Shilo Village (location)" },
                    },
                    {
                        text = "Walk to the western edge of the jungle.",
                        npcs = {},
                    },
                    {
                        text = "Use the Complete option on the Radimus notes in your backpack.",
                        npcs = { "Radimus notes (partially complete)" },
                    },
                    {
                        text = "Repeat in the centre of the jungle.",
                        npcs = {},
                        subs = {
                            { text = "If you have completed A Fairy Tale II - Cure a Queen, repair fairy ring CJS with five bittercap mushrooms to make returning to the jungle easier." },
                        },
                    },
                    {
                        text = "Repeat again on the eastern edge of the jungle.",
                        npcs = {},
                    },
                    {
                        text = "Return north of the Jungle Trees using fairy ring CKR, or by chopping them down again.",
                        npcs = {},
                    },
                    {
                        text = "Use the notes on a jungle forester, south of Shilo Village.",
                        chat = "1 Yes, go ahead make a copy!",
                        npcs = { "jungle forester" },
                    },
                },
            },
            {
                title = "Viyeldi caves", needed = { "Radimus notes, bull roarer, lockpicks, the runes for your version of RuneScape (see the item requirements table above), opal, jade, red topaz, sapphire, emerald, ruby, diamond, and at least 4 backpack spaces." },
                steps = {
                    {
                        text = "Return to Kharazi Jungle (fairy ring CJS).",
                        npcs = {},
                    },
                    {
                        text = "Swing the bull roarer to summon Gujuo, this may take several attempts.",
                        npcs = { "Gujuo" },
                    },
                    {
                        text = "Talk to him.",
                        chat = "1 I was hoping to attract the attention of a native. / 1 I want to develop friendly relationships with your people. / 1 Can you get your people together? / 1 What can we do instead then? / 1 How do we make the totem pole? / 1 I will release Ungadulu...",
                        npcs = {},
                    },
                    {
                        text = "Search the mossy rocks in the north-west of the jungle to enter the Viyeldi caves, this may take several attempts.",
                        chat = "1 Yes, I'll crawl through, I'm very athletic.",
                        npcs = { "Viyeldi caves" },
                    },
                    {
                        text = "Investigate the firewall.",
                        chat = "1 How can I extinguish the flames? / 1 Where do I get pure water from?",
                        npcs = {},
                    },
                    {
                        text = "Exit the cave via the Cave Exit.",
                        npcs = {},
                    },
                    {
                        text = "Swing the Bull roarer to summon Gujuo.",
                        npcs = {},
                    },
                    {
                        text = "Talk to him to get the sketch.",
                        chat = "3/4 I need some pure water to douse some magic flames. / 5 Where is the pool of sacred water? / 5 What kind of vessel? / 2 Ok thanks for your help.",
                        npcs = { "sketch" },
                    },
                    {
                        text = "Re-enter the cave.",
                        npcs = {},
                    },
                    {
                        text = "Search the eastern bookcase.",
                        chat = "1 Yes please!",
                        npcs = {},
                    },
                    {
                        text = "Search the Ancient Gate.",
                        npcs = { "Ancient Gate" },
                    },
                    {
                        text = "Smash-to-bits the three boulders. You do not need to keep the rocks that these gives you.",
                        npcs = { "Boulder (Viyeldi caves)", "Rock_(ore)" },
                    },
                    {
                        text = "Open the Ancient Gate.",
                        chat = "1 Yes, I'm very strong, I'll force them open.",
                        npcs = {},
                    },
                    {
                        text = "Move past the death wings.",
                        npcs = { "death wing" },
                        subs = {
                            { text = "If you want to complete one of the hard Karamja achievements, you can kill a death wing here." },
                        },
                    },
                    {
                        text = "Choose the Jump-over option on the jagged wall.",
                        npcs = { "jagged wall" },
                    },
                    {
                        text = "Search the marked wall.",
                        chat = "1 Yes, I'll read it.",
                        npcs = { "marked wall" },
                    },
                    {
                        text = "Use your runes on it in order according to your version:",
                        npcs = {},
                        subs = {
                            { text = "English: Soul, Mind, Earth, Law, Law.", chat = "1 Yes, I'll go through!" },
                            { text = "German: Air, Earth, Blood, Earth, Nature." },
                            { text = "French: Law, Air, Death, Mind, Blood." },
                            { text = "Portuguese: Fire, Water, Earth, Air, Law." },
                        },
                    },
                    {
                        text = "If the chat option is not already offered, search the marked wall.",
                        chat = "1 Yes, I'll go through!",
                        npcs = {},
                    },
                    {
                        text = "Use (right click so you don't craft them) the cut gems on the carved rocks. Use the map to see which gem goes where.",
                        npcs = { "carved rock" },
                    },
                    {
                        text = "Take the Binding book.",
                        npcs = { "Binding book" },
                    },
                },
            },
            {
                title = "Sacred pool", needed = { "Radimus notes, empty vial, at least 2 gold bars, at least 100 prayer points, binding book, sketch, and bull roarer" },
                steps = {
                    {
                        text = "Make sure you received a sketch from Gujuo, and use 2 gold bars on any anvil for a gold bowl. This may fail.",
                        npcs = { "sketch", "gold bowl" },
                    },
                    {
                        text = "Return to Kharazi Jungle (fairy ring CJS) and swing the bull roarer.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Gujuo.",
                        chat = "1 Yes, I'd like you to bless my gold bowl.",
                        npcs = {},
                    },
                    {
                        text = "Travel to the Water Pool (look for the tree icon on minimap).",
                        npcs = { "Water Pool (Kharazi Jungle)" },
                    },
                    {
                        text = "\"Cut-Reed\" the Tall Reeds next to it.",
                        npcs = {},
                    },
                    {
                        text = "Use the acquired hollow reed on the Water Pool.",
                        npcs = { "hollow reed" },
                    },
                    {
                        text = "If you need holy water for the fight against the demon: Choose the Enchant-Vials option on the binding book and create an enchanted vial.",
                        npcs = { "holy water", "binding book", "enchanted vial" },
                    },
                    {
                        text = "If you need holy water for the fight against the demon: Use the hollow reed on the Water Pool again to fill the vial.",
                        npcs = { "holy water" },
                    },
                    {
                        text = "Optional: Take a vanilla pod from one of the five Vanilla plants to the southwest if you intend to do Recipe for Disaster: Freeing Sir Amik Varze",
                        npcs = { "vanilla pod", "Vanilla plant", "Recipe for Disaster: Freeing Sir Amik Varze" },
                    },
                    {
                        text = "Return to the Viyeldi caves.",
                        npcs = { "Viyeldi caves" },
                    },
                    {
                        text = "Use the golden bowl on the fire wall.",
                        npcs = { "golden bowl" },
                    },
                    {
                        text = "Use the binding book on Ungadulu.",
                        npcs = {},
                    },
                    {
                        text = "Kill Nezikchened. He will blast the player sometimes exceeding 2500 typeless damage when he dies.",
                        npcs = { "Nezikchened" },
                    },
                    {
                        text = "Talk-to Ungadulu.",
                        chat = "1 I need to collect some Yommi tree seeds for Gujuo. / 1 How do I grow the Yommi tree? / 1 What will you do now? / 3 Okay, thanks...",
                        npcs = {},
                    },
                    {
                        text = "Touch the Fire Wall.",
                        npcs = {},
                    },
                    {
                        text = "Exit the cave.",
                        npcs = {},
                    },
                    {
                        text = "Use the Golden bowl on the seeds.",
                        npcs = {},
                    },
                    {
                        text = "Use the seeds on a patch of fertile soil. There is some just a few tiles north-west of the pool, indicated by a brown patch without grass. You will fail to plant the seeds; this is intended.",
                        npcs = {},
                    },
                    {
                        text = "Return to the pool and Use the Hollow reed on it. The water will be dried up.",
                        npcs = { "Hollow reed" },
                    },
                    {
                        text = "Swing the Bull roarer and Talk to Gujuo.",
                        chat = "1 The water pool has dried up and I need more water. / 2 Where is the source of the spring of pure water? / 2 If I went, could you help me? / 5 Ok thanks for your help.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Restoring the pool", needed = { "Radimus notes, clean ardrigal and clean snake weed (or two free inventory slots to obtain during quest), vial of water, runes and unpowered orb for any Charge Orb spell, an unpowered orb, blessed gold bowl, hollow reed, yommi tree seeds, a lockpick, a rope, and a non-augmented rune hatchet (alternatively, dragon hatchet or better) in the backpack (not tool belt)." },
                steps = {
                },
            },
            {
                title = "Picking the herbs", needed = {},
                steps = {
                    {
                        text = "Switch to the standard spellbook if you are not already on it.",
                        npcs = { "standard spells" },
                    },
                    {
                        text = "Collect the herbs using the maps below.",
                        npcs = {},
                        subs = {
                            { text = "Search palm trees for grimy ardrigal." },
                            { text = "Search marshy jungle vines for grimy snake weed." },
                        },
                    },
                    {
                        text = "Clean the herbs.",
                        npcs = {},
                    },
                    {
                        text = "Use the clean ardrigal and clean snake weed on a vial of water for a bravery potion.",
                        npcs = { "clean ardrigal", "clean snake weed", "bravery potion" },
                    },
                },
            },
            {
                title = "Preparation in the caves", needed = {},
                steps = {
                    {
                        text = "Return to the Viyeldi caves.",
                        npcs = { "Viyeldi caves" },
                    },
                    {
                        text = "Traverse the dungeon as before to where you found the Binding book:",
                        npcs = {},
                        subs = {
                            { text = "Search the eastern Bookcase." },
                            { text = "Search the Ancient Gate." },
                            { text = "Smash-to-bits the three Boulders." },
                            { text = "Open the Ancient Gate.", chat = "1 Yes, I'm very strong, I'll force them open." },
                            { text = "Move past the Death wings." },
                            { text = "Jump-over option on Jagged wall." },
                            { text = "Use the Marked wall." },
                        },
                    },
                    {
                        text = "Cast a Charge Orb spell on the north Ancient Gate.",
                        npcs = { "Charge Orb" },
                    },
                    {
                        text = "Use the Rope on the Winch.",
                        npcs = {},
                        subs = {
                            { text = "If you forgot your rope, you can smash the barrels in the room for one." },
                        },
                    },
                    {
                        text = "Drink the bravery potion.",
                        chat = "1 Yes, I'll bravely drink the bravery potion.",
                        npcs = {},
                    },
                    {
                        text = "Search and then climb-down the Winch.",
                        chat = "1 Yes, I'll shimmy down the rope into possible doom.",
                        npcs = {},
                    },
                    {
                        text = "Climb-over the rocky ledges and rocks to reach the bottom. You can potentially fall and take upward of 5000 typeless damage during this.",
                        chat = "1 Yes, I can think of nothing more exciting! / 1 Yes, I can think of nothing more exciting! / 1 Yes, I can think of nothing more exciting! / 1 Yes, I want to climb over the rocks. / 1 Yes, I want to climb over the rocks. / 1 Yes, I want to climb over the rocks.",
                        npcs = {},
                    },
                    {
                        text = "Kill the 3 different skeletons until you get 3 crystal pieces (Hunk, Chunk, and Lump):",
                        npcs = { "Hunk of crystal", "Chunk of crystal", "Lump of crystal" },
                        subs = {
                            { text = "San Tojalon" },
                            { text = "Irvig Senay" },
                            { text = "Ranalph Devere" },
                        },
                    },
                    {
                        text = "Use each crystal on the north-east furnace.",
                        npcs = {},
                    },
                    {
                        text = "Use the heart crystal on the searchable mossy rock in the middle of the room.",
                        npcs = { "heart crystal", "Mossy rock (Viyeldi caves)" },
                    },
                    {
                        text = "Run south and use the heart crystal on the recess next to the shimmering field.",
                        npcs = { "Heart crystal (activated)" },
                    },
                    {
                        text = "Walk-through the shimmering field.",
                        npcs = {},
                    },
                    {
                        text = "West past the lesser demons, push any of the boulders.",
                        chat = "any / 1 What can I do about that? / 1 I'll do what I must to get the water. / 1 Ok, I'll do it.",
                        npcs = { "lesser demon" },
                    },
                    {
                        text = "Return to the start of the cavern, back past the shimmering field and Rocks.",
                        npcs = {},
                    },
                    {
                        text = "Equip the dark dagger.",
                        npcs = { "dark dagger" },
                    },
                    {
                        text = "Take the blue hat.",
                        npcs = { "blue hat" },
                    },
                    {
                        text = "Kill Viyeldi.",
                        npcs = { "Viyeldi" },
                        subs = {
                            { text = "You will need to Attack him during the dialogue as he will disappear after completing the dialogue." },
                        },
                    },
                    {
                        text = "Re-equip your preferred weapon.",
                        npcs = {},
                    },
                    {
                        text = "Return to the boulders and push one.",
                        npcs = {},
                    },
                    {
                        text = "Kill Nezikchened.",
                        npcs = { "Nezikchened" },
                    },
                    {
                        text = "Push all three boulders.",
                        npcs = {},
                        subs = {
                            { text = "All three must be pushed while standing on the east side of them." },
                            { text = "If one does not move, push it from a different angle." },
                            { text = "Quickly use the golden bowl on sacred water that appears under the boulder." },
                        },
                    },
                },
            },
            {
                title = "Planting yommi", needed = {},
                steps = {
                    {
                        text = "Return to Kharazi Jungle (fairy ring CJS).",
                        npcs = {},
                    },
                    {
                        text = "Use the hollow reed on the water pool.",
                        npcs = { "hollow reed" },
                    },
                    {
                        text = "Use the yommi tree seeds on the dark brown soil just north-west of the pool, it will appear as Fertile Soil.",
                        npcs = { "yommi tree seeds", "Fertile Soil (scenery)" },
                    },
                    {
                        text = "Use the golden bowl on it once it stops growing.",
                        npcs = { "golden bowl" },
                    },
                    {
                        text = "Chop the adult yommi tree.",
                        npcs = {},
                    },
                    {
                        text = "Trim the felled yommi tree.",
                        npcs = {},
                    },
                    {
                        text = "Carve the trimmed yommi.",
                        npcs = {},
                    },
                    {
                        text = "Lift the totem pole.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The final fight", needed = { "Yommi totem, Radimus notes, bull roarer" },
                steps = {
                    {
                        text = "Use your Yommi totem on the Totem Pole east of the pool.",
                        npcs = {},
                    },
                    {
                        text = "Defeat Nezikchened and the three skeletons.",
                        npcs = { "Nezikchened" },
                        subs = {
                            { text = "He will appear four times, with a skeleton spawning between each kill." },
                        },
                    },
                    {
                        text = "Use the Yommi totem on the Totem Pole again.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Gujuo to receive the gilded totem.",
                        npcs = { "gilded totem" },
                    },
                    {
                        text = "Return to the Legends' Guild (fairy ring BLR).",
                        npcs = {},
                    },
                    {
                        text = "Talk to Radimus.",
                        npcs = {},
                    },
                    {
                        text = "Talk to him again inside the guild.",
                        chat = "1 Yes, I'll train now.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "let_them_eat_pie", name = "Let Them Eat Pie", wiki = "Let Them Eat Pie/Quick guide",
        required = { "All of these can be obtained for free during the quest.", "Raw potato", "Raw crayfish", "Wheat", "Fishing bait" },
        recommended = {},
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to Nails Newton a few steps east of the Taverley lodestone.",
                        chat = "Accept",
                        npcs = { "Nails Newton", "Taverley lodestone" },
                    },
                },
            },
            {
                title = "The pie shell", needed = {},
                steps = {
                    {
                        text = "(Optional) Gather wheat and fishing bait.",
                        npcs = {},
                        subs = {
                            { text = "Go south and then east across the bridge and take some fishing bait from the ground near the bait barrel and hanging fish." },
                            { text = "Go south and pick some wheat." },
                        },
                    },
                    {
                        text = "Go to the watermill in the north-east of the bank and south of the pub.",
                        npcs = { "Taverley bank", "The Pick and Lute" },
                    },
                    {
                        text = "Climb the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Investigate the hopper with fishing bait and wheat in the backpack.",
                        npcs = {},
                    },
                    {
                        text = "Operate hopper controls.",
                        npcs = {},
                    },
                    {
                        text = "Go down the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Take an empty pot and take-flour from flour bin to obtain maggoty flour.",
                        npcs = { "maggoty flour" },
                    },
                    {
                        text = "Talk to Nails Newton. He will give you a maggoty pie shell.",
                        npcs = { "maggoty pie shell" },
                    },
                },
            },
            {
                title = "The filling", needed = {},
                steps = {
                    {
                        text = "(Optional) Go north and trade with Head Farmer Jones outside of the flax field to receive a free raw potato.",
                        npcs = { "Head Farmer Jones", "raw potato" },
                    },
                    {
                        text = "(Optional) Go east and cage on a fishing spot to catch a raw crayfish.",
                        npcs = { "Fishing spot (crayfish)", "raw crayfish" },
                    },
                    {
                        text = "Go inside the flax field or animal pen and watch the cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Nails Newton.",
                        npcs = {},
                    },
                    {
                        text = "Go north-west into the snowy Hunter area near the animal pens.",
                        npcs = {},
                    },
                    {
                        text = "Inspect a hole with a raw potato in the backpack to receive a stinking potato.",
                        npcs = { "Hole (Hunter)", "stinking potato" },
                    },
                    {
                        text = "Use the stinking potato or manky crayfish on the maggoty pie shell to create a terrible pie (uncooked).",
                        npcs = { "terrible pie (uncooked)" },
