                    {
                        text = "Cook the pie at an oven in The Pick and Lute pub which is right next to Nails Newton.",
                        npcs = { "The Pick and Lute", "Nails Newton" },
                    },
                    {
                        text = "Talk to Nails Newton.",
                        npcs = {},
                    },
                },
