            {
                title = "The final battle", needed = {},
                steps = {
                    {
                        text = "Talk to Zenevivia to start the battle. If you fail your first attempts, return to the Wise Old Man at the house in Rimmington. Right click on the house teleport tabs to modify them for another teleport to the fight.",
                        npcs = { "Zenevivia" },
                        subs = {
                            { text = "Avoid the flames on the floor, they deal low damage." },
                            { text = "Zenevivia uses magic spells and flames on the floor that can quickly deal around 600 damage." },
                            { text = "She will sometimes use protection prayers so prepare to switch attack styles or just use Necromancy." },
                            { text = "She can be knocked off pillars using abilities that knock back enemies, such as Kick." },
                        },
                    },
                    {
                        text = "After she is defeated, talk to her.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Robbing the Wizards' Tower", needed = {},
                steps = {
                    {
                        text = "You will return to Draynor Village.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Zenevivia in the Wise Old Man's house.",
                        chat = "4 Have you still got Mabel's ring? / 2 When will you give me Mabel's ring? / 1 Stealing is wrong. / 1 When are you going to attack?",
                        npcs = {},
                    },
                    {
                        text = "Go upstairs and look through the telescope and watch the Wizards' Tower Robbery.",
                        npcs = { "Wizards' Tower Robbery" },
                    },
                    {
                        text = "Head downstairs, talk to Zenevivia again.",
                        chat = "1 Are you going to try any more robberies? / 1 Can I have Mabel's ring back now?",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Required for completing", needed = { "It is however required to start the court case Miss Schism v. Draynor Village." },
                steps = {
                },
            },
        },
