    {
        key = "lunar_diplomacy", name = "Lunar Diplomacy", wiki = "Lunar Diplomacy/Quick guide",
        required = { "Coins (1,000 should be enough, there is a bank on the island)", "Runes for combat spells (preferably fire spells, elemental staff not equippable)", "Dramen staff", "Spade (tool belt will not work)", "Air, earth, fire, and water talismans, or alternate methods of accessing the respective runecrafting altars (e.g. a wicked hood consumed the aforementioned talisman)", "Two spools of thread (can be obtained during the quest - Crafting cape perk works as well)", "Clean guam (may be obtained from dropped grimy guam during the quest, common drop)", "Clean marrentill (may be obtained from dropped grimy marrentill during the quest, common drop)" },
        recommended = { "Armour, weapons and food", "Extra dramen staves (if interested in making more lunar staves)", "Agility boost, e.g. Summer pie" },
        sections = {
            {
                title = "Starting out", needed = {},
                steps = {
                    {
                        text = "Choose the 'talk to' option on Lokar Searunner on Rellekka's westernmost dock.",
                        chat = "2 You've been away from these parts for a while? / 1 Why did you leave? / Accept",
                        npcs = { "Lokar Searunner" },
                    },
                    {
                        text = "Speak to Brundt the Chieftain in the Longhall for a seal of passage.",
                        chat = "1 Ask about a seal of passage.",
                        npcs = { "Brundt the Chieftain", "seal of passage" },
                        subs = {
                            { text = "You will need to keep the seal on you while on the island. Talking to anyone without it will teleport you back to Rellekka." },
                        },
                    },
                    {
                        text = "Return and talk to Lokar.",
                        chat = "1 Arrr! Yar! Let's be on our way, yar!",
                        npcs = {},
                    },
                    {
                        text = "Climb the ladder and board the pirate ship. Talk to Captain Bentley about sailing to Lunar Isle.",
                        chat = "4 Can we sail to Lunar Isle now?",
                        npcs = { "Captain Bentley", "Lunar Isle" },
                        subs = {
                            { text = "Make sure to be sufficiently on the pirate ship, otherwise the quest will not progress." },
                        },
                    },
                    {
                        text = "Climb down the central ladder.",
                        npcs = {},
                    },
                    {
                        text = "Below deck, talk to 'Bird's-Eye' Jack to the south-west.",
                        npcs = { "'Bird's-Eye' Jack" },
                    },
                    {
                        text = "Talk to Captain Bentley again.",
                        chat = "2 Perhaps it's the Navigator's fault?",
                        npcs = {},
                    },
                    {
                        text = "Return to 'Birds-Eye' Jack again.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Talking to the crew", needed = {},
                steps = {
                    {
                        text = "Must talk to them in this order.",
                        npcs = {},
                        subs = {
                            { text = "Talk to 'Eagle-eye' Shultz at the very front of the ship (back upstairs)." },
                            { text = "Talk to 'Beefy' Burns on the lowest level of the ship." },
                            { text = "Talk to 'Lecherous' Lee on the very top level, at the south end of the ship." },
                            { text = "Talk to First mate 'Davey-boy' on the southern end of the deck near the stairs." },
                            { text = "Climb up to the top level at the south end of the ship and talk to the cabin boy (2 inventory spaces required). He is next to Lecherous Lee." },
                        },
                    },
                },
            },
            {
                title = "Searching for clues", needed = {},
                steps = {
                    {
                        text = "Use the lens on the lantern. Light it.",
                        npcs = {},
                    },
                    {
                        text = "Use the lantern on the following objects and rub away the symbols:",
                        npcs = {},
                        subs = {
                            { text = "Barrel: Return to the lowest level of the ship. It is the southernmost stack of three barrels.", chat = "1 Rub away!" },
                            { text = "Support: On the same level, it is the big support column in the middle of the ship.", chat = "1 Rub away!" },
                            { text = "Chest: Same level still, before going back up, it is the chest on the ground just northwest of the ladder.", chat = "1 Rub away!" },
                            { text = "Cannon: Climb the ladder up one level. It is the long cannon at the very south end of the ship, directly behind 'Bird's-Eye' Jack.", chat = "1 Rub away!" },
                            { text = "Wallchart: Finally, climb up to the main deck and enter the southernmost room. It is the wallchart on the northwestern wall.", chat = "1 Rub away!" },
                        },
                    },
                    {
                        text = "Talk to Captain Bentley.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Lunar Isle", needed = { "clean guam, clean marrentill, and ground suqah tooth" },
                steps = {
                    {
                        text = "Climb down the ladders and walk into the city (there will be a small cutscene).",
                        npcs = {},
                    },
                    {
                        text = "Go north-east outside the city and kill suqah until these items are obtained:",
                        npcs = { "suqah" },
                        subs = {
                            { text = "One suqah tooth." },
                            { text = "4 suqah hides." },
                            { text = "If not already in the backpack, one grimy guam and one grimy marrentill. Clean the herbs." },
                        },
                    },
                    {
                        text = "Mine a lunar ore at the mine north-east of the city. Climb down the ladder and mine a stalagmite to the West of the rune essence rock. It looks like a rock jutting out of the ground.",
                        npcs = { "lunar ore", "Lunar Isle mine", "stalagmite" },
                        subs = {
                            { text = "Optional: Mine Rune Essence to complete Runes on the Moon, which is a Hard Fremennik achievement." },
                        },
                    },
                    {
                        text = "Run to the south-east part of the island. Talk to the Oneiromancer near the astral altar.",
                        npcs = { "Oneiromancer", "astral altar" },
                    },
                    {
                        text = "Return to the city and enter the walking house in the northern section. Talk to Baba Yaga (1 inventory space required).",
                        chat = "2 The Oneiromancer told me you may be able to help...",
                        npcs = { "Baba Yaga" },
                    },
                    {
                        text = "Use the vial on the sink.",
                        npcs = {},
                        subs = {
                            { text = "Add a guam and a marrentill to the vial of water." },
                            { text = "Grind the suqah tooth and use it on the vial to complete the potion." },
                        },
                    },
                    {
                        text = "Return to the Oneiromancer with the potion.",
                        npcs = { "Oneiromancer", "Waking sleep vial" },
                    },
                },
            },
            {
                title = "Lunar staff", needed = { "Dramen staff" },
                steps = {
                },
            },
            {
                title = "Travelling options", needed = {},
                steps = {
                    {
                        text = "Skull sceptre or Edgeville lodestone for the air altar",
                        npcs = { "Skull sceptre", "Edgeville lodestone", "air altar" },
                    },
                    {
                        text = "Ring of duelling or Al Kharid lodestone for the fire altar",
                        npcs = { "Ring of duelling", "Al Kharid lodestone", "fire altar" },
                    },
                    {
                        text = "Enlightened amulet or Lumbridge lodestone for the water altar",
                        npcs = { "Enlightened amulet", "Lumbridge lodestone", "water altar" },
                    },
                    {
                        text = "Fort Forinthry lodestone, Invitation box, or Archaeology journal for the earth altar",
                        npcs = { "Fort Forinthry lodestone", "Invitation box", "Archaeology journal", "earth altar" },
                    },
                },
            },
            {
                title = "Elemental runecrafting altars", needed = {},
                steps = {
                    {
                        text = "Use your dramen staff/staves on the following altars in the listed order (you may need talismans to access if you do not have alternate teleports):",
                        npcs = { "dramen staff" },
                        subs = {
                            { text = "Air (west of Varrock)" },
                            { text = "Fire (north of Al Kharid)" },
                            { text = "Water (Lumbridge Swamp)" },
                            { text = "Earth (south of Fort Forinthry)" },
                        },
                    },
                    {
                        text = "Before returning to the isle, smelt the lunar ore at any regular furnace and make a lunar helmet at a regular anvil.",
                        npcs = {},
                    },
                    {
                        text = "Travel back to Lunar Isle by selecting \"travel\" from Lokar Searunner in Rellekka at the westernmost dock.",
                        npcs = {},
                    },
                    {
                        text = "Travel with Captain Bentley to Lunar Isle.",
                        npcs = {},
                    },
                    {
                        text = "Give a lunar staff to the Oneiromancer.",
                        npcs = { "Oneiromancer" },
                    },
                },
            },
            {
                title = "Smithing lunar helm", needed = { "1 backpack space" },
                steps = {
                    {
                        text = "If you have already made the lunar helm, you can skip the next 4 steps.",
                        npcs = {},
                        subs = {
                            { text = "Climb down ladder north-eastern part of the isle." },
                            { text = "Mine a stalagmite for a lunar ore." },
                            { text = "You have to use a furnace to smith the ore (the forge in the southern building will not work)." },
                            { text = "Use an anvil to make the helm, such as the one in the southern building." },
                        },
                    },
                },
            },
            {
                title = "Crafting lunar gear", needed = { "400 coins, thread or Crafting cape, four suqah hides, 1 backpack space" },
                steps = {
                    {
                        text = "Talk to Pauline Polaris in the north-western-most building in the city. Choose the correct answer \"Jane Blud-Hagic-Maid\". The answers are randomly ordered.",
                        chat = "2 Pauline.",
                        npcs = { "Pauline Polaris" },
                    },
                    {
                        text = "Talk to Meteora south in the city.",
                        npcs = { "Meteora" },
                    },
                    {
                        text = "Kill Suqahs until one drops a special tiara. If you haven't already, pick up their hide as well as you'll need four hides later on.",
                        npcs = { "Suqah", "a special tiara" },
                    },
                    {
                        text = "Give Meteora the tiara.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Rimae Sirsalis in the clothing store south of the bank about ceremonial clothes.",
                        chat = "2 You know the ceremonial clothes?",
                        npcs = { "Rimae Sirsalis" },
                    },
                    {
                        text = "Talk to Rimae Sirsalis again, she will tan your hides.",
                        chat = "2 You know the ceremonial clothes? / 1 That seems like a fair deal.",
                        npcs = {},
                        subs = {
                            { text = "If you didn't bring thread, Rimae's shop sells some." },
                        },
                    },
                    {
                        text = "Craft a lunar torso, trousers, gloves, and boots from your hides.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Looking for lunar ring", needed = { "1 backpack space, and a spade" },
                steps = {
                    {
                        text = "Go to the biggest building in the city (west of the lodestone) and talk to Selene (she might be outside).",
                        chat = "2 I'm looking for a ring.",
                        npcs = { "Selene (Lunar Isle)" },
                    },
                    {
                        text = "Exit the city and run south. Dig up near blue flowers with a spade (tool belt doesn't work), they are the flowers to the furthest south west across the bridge. Make sure to finish the dialogue.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Giving lunar gear", needed = {},
                steps = {
                    {
                        text = "Give the Oneiromancer all your lunar gear.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Oneiromancer again with 11 free inventory slots.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Dreamland", needed = { "Runes for combat spells (preferably fire spells, elemental staff not equippable)." },
                steps = {
                    {
                        text = "Use the vial on the kindling Oneiromancer just gave you to create soaked kindling.",
                        npcs = { "soaked kindling" },
                    },
                    {
                        text = "Get your combat runes and supplies, dismiss your follower, and wear all your lunar items. Four backpack spaces are required.",
                        npcs = {},
                    },
                    {
                        text = "Do not carry an augmented crystal hatchet in the backpack to avoid a bug later in the quest.",
                        npcs = {},
                    },
                    {
                        text = "Run to the biggest building in the city (west of the lodestone).",
                        npcs = {},
                    },
                    {
                        text = "Make sure you're wearing all 8 pieces of lunar equipment and wielding the lunar staff; if you exit to lobby or logout, or are not wearing them all when you add the soaked kindling, you'll have to return to the Oneiromancer to get a new kindling.",
                        npcs = {},
                    },
                    {
                        text = "Light the ceremonial brazier then use the Soaked kindling on it to enter Dreamland.",
                        npcs = {},
                    },
                },
            },
