    {
        key = "mahjarrat_memories_miniquest", name = "Mahjarrat Memories (miniquest)", wiki = "Mahjarrat Memories (miniquest)/Quick guide",
        required = { "7,500 vibrant memories (or memories of a higher tier); enriched memories count for double (collected during miniquest)", "Invitation box (for Sliske's memory)", "Insulated boots (for Zemouregal's memory)", "Macaw pouch or Ravenous locust pouch (for Zemouregal's memory)" },
        recommended = { "Nightmare muspah familiar (makes the process more AFK and provides an increased chance for enriched memories as well as a chance to gather more energy, at least 2 needed for the duration of the quest)", "Elder divination outfit or its equivalents (if owned)", "Prism of Dowsing", "Fading memory (if owned)", "Ethereal Connection (World Gate engram) buff from Memorial to Guthix", "Enchanted lyre, Fremennik sea boots 4 or activated Fremennik Province lodestone for quick Rellekka teleport", "Divine-o-matic vacuum (works for filling charges instead of gathering energy, might be profitable or not depending on type of energy–will take longer because divine-o-matic destroys memories)", "Divination cape (if owned, makes the process more afk)" },
        sections = {
            {
                title = "Beginning", needed = { "Rellekka tablet or enchanted lyre" },
                steps = {
                    {
                        text = "Speak to Kharshai, located under the helmet shop in Rellekka. Agree to help him.",
                        chat = "3 I want to talk about the Mahjarrat memories. / 1 Tell me more. / Accept / 1 Sign the contract.",
                        npcs = { "Kharshai", "Rellekka" },
                    },
                    {
                        text = "With the engrammeter, head to any divination colony of vibrant wisps or higher. Fill it with 500 divine memories.",
                        npcs = { "engrammeter", "vibrant wisp" },
                        subs = {
                            { text = "You may utilise World 79 (Community Divination World) for more frequent enriched springs." },
                        },
                    },
                    {
                        text = "Visit the locations below, use the charged engrameter to collect the memory.",
                        npcs = {},
                    },
                    {
                        text = "Return to Kharshai. Talk to him to give him the memory.",
                        chat = "3 I want to talk about the Mahjarrat memories.",
                        npcs = {},
                    },
                    {
                        text = "Recharge the engrammeter with another 500 divine memories, and repeat for the remaining 14 memories.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finding the memories", needed = { "Macaw, insulated boots, and the invitation box." },
                steps = {
                    {
                        text = "Locations:",
                        npcs = {},
                        subs = {
                            { text = "Wahisietel — Go to Nardah. Go to the Ali the Wise's house, the northern-most one from the Elidinis Statuette, and use the charged engrammeter there." },
                            { text = "Azzanadra — Go to the Jaldraocht Pyramid. Use the engrammeter in the altar room." },
                            { text = "Enakhra — Travel to Enakhra's Temple. Use the engrammeter in the central room." },
                            { text = "Akthanakos — Travel to Enakhra's Temple. Use the ladder in the central room, go through the magic barrier and up the ladder. Use the engrammeter in the first chamber." },
                            { text = "Bilrach — Go to Daemonheim. Use the engrammeter next to the banker." },
                            { text = "Hazeel — Go south of Ardougne Zoo. Enter the cave entrance east of the Clock Tower. Take the raft, and enter the Hazeel Cultist headquarters. Use the engrammeter. See Hazeel Cult quest guide if you failed to do so." },
                            { text = "Lucien — Go to Lucien's house, just west of the Grand Exchange, quickest using fairy ring DKR. Use the engrammeter inside." },
                            { text = "Zemouregal — This next section will take you into the Wilderness. Make sure you have a summoned macaw and are wearing insulated boots. Go to Hartwin in Varrock Palace, on the 3rd floor of the north-west tower. Ask him to lead you to the Chaos Temple. * Go down the trapdoor, and follow the corridors full of armoured zombies. * Ignore the human detector corridor; squeeze through the pipe in the next room. Follow the passage around to another pipe. * Try to go through it. Then right-click on the summoned macaw and remote view. * Go into the south room in the corridor, use the engrammeter." },
                            { text = "Sliske — In the throne room (octagon-shaped room) of the Empyrean Citadel. Use the invitation box to teleport there quickly." },
                            { text = "Mizzarch — Go to the Varrock Dig Site. Go down into the Senntisten Temple (north-east winch). Use the engrammeter in the altar room." },
                            { text = "Jhallan — Go to the Erjolf's cave (east of Olaf Hradson, above the entrance to Keldagrim). Cross the river and enter the cave opening to the west. Use the engrammeter near the floating bridge to the centre island. Fairy code DKS will place you just a few steps from the cave." },
                            { text = "Palkeera — Go to the Mahjarrat Ritual Site. Use the engrammeter next to the ritual marker." },
                            { text = "Lamistard — Go to Zemouregal's fort, west of the Mahjarrat Ritual Site. Go inside using the left side of the large front door. Use the engrammeter." },
                            { text = "Ralvash — Go to Ghorrock. Go into the fortress courtyard, and use the engrammeter." },
                            { text = "Kharshai — Go to Kharshai's cave, where you begin the miniquest. Use the engrammeter inside. (Skip this if you already completed this earlier.)" },
                        },
                    },
                    {
                        text = "Take the final memory to Kharshai, receive your reward.",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "making_history", name = "Making History", wiki = "Making History/Quick guide",
        required = { "Spade (or the meerkats familiar; the spade can be purchased from Richard's Farming Shop during the quest)", "2,600 coins (1,300 coins after Cabin Fever) to charter ships from Port Sarim to Port Phasmatys, or 2 ecto-tokens (or completion of Ghosts Ahoy)", "A strung, un-enchanted sapphire amulet", "A ghostspeak amulet or cramulet (not required if you have completed the hard Morytania achievements)" },
        recommended = { "A traveller's necklace", "An ectophial (requires Ghosts Ahoy) or 2 ecto-tokens", "Energy or super energy potions", "Activated Ardougne and Fremennik Province lodestones", "A ring of duelling", "A dramen or lunar staff for the use of fairy rings, unless you've completed A Fairy Tale III - Battle at Ork's Rift" },
        sections = {
            {
                title = "Starting the quest", needed = {},
                steps = {
                    {
                        text = "Go to the Outpost; an old, now-derelict tower to the north of West Ardougne.",
                        npcs = { "Outpost", "West Ardougne" },
                        tile = { x = 2436, y = 3346, plane = 0 },
                        subs = {
                            { text = "Traveller's necklace teleports directly to the Outpost." },
                            { text = "Eagles' Peak lodestone and run south, then south east." },
                        },
                    },
                    {
                        text = "Speak with Jorral for a cutscene.",
                        chat = "1 Tell me more.",
                        npcs = { "Jorral" },
                    },
                    {
                        text = "After the cutscene, agree to help.",
                        chat = "Accept",
                        npcs = {},
                    },
                },
            },
            {
                title = "Erin", needed = { "A spade (the one in your tool belt will not work)" },
                steps = {
                    {
                        text = "Talk to the silver merchant in the East Ardougne marketplace.",
                        chat = "3 Ask about the outpost.",
                        npcs = { "silver merchant", "East Ardougne" },
                        tile = { x = 2442, y = 3139, plane = 0 },
                        subs = {
                            { text = "Do not steal from the stall otherwise the merchant will not talk with you." },
                        },
                    },
                    {
                        text = "Ring of dueling to Castle Wars, run north and cross the bridge south of the Observatory.",
                        npcs = { "Castle Wars", "Observatory" },
                        subs = {
                            { text = "West of fairy ring CIQ and north-west of Yanille lodestone." },
                        },
                    },
                    {
                        text = "When you're just north of the bridge, play hot-and-cold by feeling the key and walking around until it feels steaming hot, and use the spade to dig. (Between the two trees)",
                        npcs = {},
                    },
                    {
                        text = "Use the key on the chest to unlock it.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Droalak", needed = { "Ghostspeak amulet, sapphire amulet, and two ecto tokens or enough money to buy a charter boat to Port Phasmatys if Ghosts Ahoy has not been completed" },
                steps = {
                    {
                        text = "Speak to Droalak south of the General Store in Port Phasmatys.",
                        npcs = { "Droalak", "Port Phasmatys" },
                        subs = {
                            { text = "Ectophial or Port Sarim lodestone and charter ship to Port Phasmatys." },
                            { text = "Wear the ghostspeak amulet." },
                        },
                    },
                    {
                        text = "Talk to Melina in the building east of the General Store with a sapphire amulet in your inventory.",
                        npcs = { "Melina", "sapphire amulet" },
                    },
                    {
                        text = "Talk to Droalak again for the scroll.",
                        npcs = { "Droalak" },
                    },
                },
            },
            {
                title = "Dron", needed = {},
                steps = {
                    {
                        text = "Talk to Blanin, west of the cow pen in Rellekka.",
                        npcs = { "Blanin", "Rellekka" },
                    },
                    {
                        text = "Talk to Dron, west of the helmet shop.",
                        chat = "3 I'm after important answers. / 2 Why you're the famous warrior Dron!",
                        npcs = { "Dron" },
                    },
                    {
                        text = "Answer his quiz.",
                        chat = "2 An iron mace. / 1 Breakfast. / 2 Lunch. / 1 Bunnies. / 2 Red. / 2 36. / 1 8. / 3 Fifth and Fourth. / 3 Northeast side of town. / 1 Blanin. / 1 Fluffy. / 1 12, but what does that have to do with anything?",
                        npcs = {},
                    },
                },
            },
            {
                title = "Jorral", needed = { "Journal, scroll" },
                steps = {
                    {
                        text = "Return to Jorral at the outpost, talk to him until he gives you a Letter.",
                        npcs = { "Jorral" },
                    },
                    {
                        text = "Talk to King Lathas on the 2nd floor of Ardougne Castle. (Remove Mourner Outfit if equipped)",
                        npcs = { "King Lathas", "Ardougne Castle" },
                    },
                    {
                        text = "Return to Jorral.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
