    {
        key = "merlin_s_crystal", name = "Merlin's Crystal", wiki = "Merlin's Crystal/Quick guide",
        required = { "Bread (can be obtained during the quest with 24 coins)", "Bat bones (can be obtained during the quest)", "If getting the black candle from Wendle's Wicks:", "Black candle", "If getting the black candle from Catherby:", "Bucket (can be obtained during the quest)", "Insect repellent (can be obtained during the quest)", "Can be used from the tool belt" },
        recommended = { "Activated Falador, Seers' Village and Varrock lodestone" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to King Arthur at Camelot.",
                        chat = "1 I'm looking for a quest. / Accept",
                        npcs = { "King Arthur", "Camelot" },
                    },
                    {
                        text = "Talk to Sir Gawain nearby. Ask him how Merlin got stuck in the crystal.",
                        chat = "3 Do you know how Merlin got trapped? / 2 Thank you for the information!",
                        npcs = { "Sir Gawain", "Merlin" },
                    },
                    {
                        text = "Go upstairs, and talk to Sir Lancelot. Ask if he has any ideas on getting into Keep Le Faye.",
                        chat = "3 Any ideas on how to get into Morgan Le Faye's stronghold?",
                        npcs = { "Sir Lancelot", "Keep Le Faye" },
                    },
                    {
                        text = "Hide in the crate just west of the candle-maker in Catherby.",
                        chat = "1 Yes. / 1 Yes.",
                        npcs = { "candle-maker", "Catherby" },
                    },
                },
            },
            {
                title = "Inside Keep Le Faye", needed = {},
                steps = {
                    {
                        text = "Climb to the top floor.",
                        npcs = {},
                    },
                    {
                        text = "Attack Sir Mordred until his health drops to 0. If you use bleeds/poisons/conjures, future dialogue will be interrupted until the bleed/poison effect ends. Aggressive familiars would continue to attack when Sir Mordred goes back to full health after reaching 0 health, thus restarting the fight.",
                        npcs = { "Sir Mordred" },
                    },
                    {
                        text = "Talk to Morgan Le Faye. Spare Mordred's life to discover how to save Merlin.",
                        chat = "1 Tell me how to untrap Merlin and I might. / 2 Okay, I will do that.",
                        npcs = { "Morgan Le Faye", "Merlin" },
                    },
                    {
                        text = "If you do not have bat bones, exit the keep to the west and kill a Giant bat.",
                        npcs = { "bat bones", "Giant bat" },
                    },
                },
            },
            {
                title = "Getting a black candle", needed = { "Bucket, Insect repellent" },
                steps = {
                    {
                        text = "Talk to the candle-maker in Catherby.",
                        chat = "1 Have you got any black candles?",
                        npcs = { "candle-maker", "Catherby" },
                    },
                    {
                        text = "Gather a bucket of wax from the beehives to the north-west. A bucket can be found at the beehives.",
                        npcs = { "beehive" },
                        subs = {
                            { text = "If you do not have insect repellent then speak to the beekeeper for some. You can also add it to your tool belt." },
                        },
                    },
                    {
                        text = "Left click the hive to use insect repellent on it and then use an empty bucket on a beehive to fill the bucket.",
                        npcs = { "insect repellent" },
                    },
                    {
                        text = "Talk to the candle-maker again to get the black candle from him.",
                        npcs = { "black candle" },
                    },
                },
            },
            {
                title = "Getting Excalibur", needed = { "Bread" },
                steps = {
                    {
                        text = "Talk to the Lady of the Lake in southern Taverley. Ask about the sword Excalibur.",
                        chat = "2 I seek the sword Excalibur.",
                        npcs = { "the Lady of the Lake", "Taverley" },
                        tile = { x = 2924, y = 3405, plane = 0 },
                    },
                    {
                        text = "Go to Port Sarim.",
                        npcs = { "Port Sarim" },
                        subs = {
                            { text = "If you don't have bread, buy a loaf from Wydin's Food Store, just south of the Port Sarim lodestone." },
                        },
                    },
                    {
                        text = "Enter Grum's Gold Exchange to the north of Port Sarim lodestone.",
                        npcs = { "Grum's Gold Exchange" },
                    },
                    {
                        text = "Give the beggar your bread.",
                        chat = "1 Yes certainly.",
                        npcs = {},
                    },
                    {
                        text = "The beggar will turn into the Lady of the Lake and give you Excalibur for your good deed.",
                        npcs = { "the Lady of the Lake" },
                    },
                },
            },
            {
                title = "Ritual", needed = { "Bat bones, Black candle" },
                steps = {
                    {
                        text = "Go to the Temple of Zamorak south of the Varrock east bank.",
                        npcs = { "Temple of Zamorak", "Varrock east bank" },
                    },
                    {
                        text = "Check the chaos altar's inscription.",
                        npcs = { "Chaos altar (Varrock)" },
                    },
                    {
                        text = "Return to Camelot and enter the gates.",
                        npcs = { "Camelot" },
                    },
                    {
                        text = "Run north-east outside of the castle to the ritual site (the gazebo outside the castle).",
                        npcs = {},
                    },
                    {
                        text = "Stand on the star and light the black candle.",
                        npcs = {},
                    },
                    {
                        text = "Drop the bat bones on the star.",
                        npcs = {},
                    },
                    {
                        text = "The magic words are \"Snarthon Candtrick Termanto\". If you get this wrong, you will have to get the black candle remade; or click away before proceeding with the dialogue and re-drop the bat bones to try again.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing up", needed = { "Excalibur" },
                steps = {
                    {
                        text = "Enter the castle and climb the top of the south-east tower.",
                        npcs = {},
                    },
                    {
                        text = "Smash the giant crystal to free Merlin.",
                        npcs = { "Merlin" },
                    },
                    {
                        text = "Talk to King Arthur.",
                        npcs = { "King Arthur" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "missing_my_mummy", name = "Missing My Mummy", wiki = "Missing My Mummy/Quick guide",
        required = { "1 willow log", "20 fire runes (cannot be substituted by a staff that provides fire runes)", "Jug of wine", "Spice", "Wheat", "Empty pot" },
        recommended = { "The explorer's ring 3 and above to teleport to Draynor, access to the Draynor lodestone, War's Retreat Teleport, or a charged amulet of glory", "Access to fairy rings to reach Uzer Mastaba (code DLQ)", "A charged ring of duelling, broomstick, or access to the Al Kharid lodestone", "Desert robes, an enchanted water tiara or waterskins", "Some food and prayer potions (have your prayer points full before entering the pyramid the second time)" },
        sections = {
            {
                title = "Pharaoh's pyramid", needed = { "3 backpack spaces" },
                steps = {
                    {
                        text = "Talk to Leela, north of the Draynor Village jail.",
                        npcs = { "Leela", "Draynor Village" },
                        tile = { x = 3122, y = 3259, plane = 0 },
                        subs = {
                            { text = "If Leela does not show up in Draynor Village, you need to complete the Stolen Hearts and Diamond in the Rough quests first, even if Icthlarin's Little Helper is already completed." },
                        },
                    },
                    {
                        text = "Enter the flat-topped pyramid Uzer Mastaba from the west side, south of Uzer.",
                        npcs = { "Uzer Mastaba", "Uzer" },
                        subs = {
                            { text = "Teleport to the fairy ring DLQ and then run east." },
                            { text = "Teleport to Al Kharid and go south to Shantay's Pass (Or use amulet of glory's teleport to Al Kharid)." },
                            { text = "Use the magic carpet network to get to Uzer." },
                            { text = "Teleport with the traveller's necklace to desert eagles' eyrie." },
                        },
                    },
                    {
                        text = "In the initial east chamber, rummage and kill the skeleton for a canopic jar.",
                        npcs = { "Canopic jar (Missing My Mummy)" },
                    },
                    {
                        text = "Head north-west and through the imposing doors to the south.",
                        npcs = {},
                    },
                    {
                        text = "Kill the four skeletons in the room for a mummy hand and the scroll of the dead. The mummy hand and scroll of the dead don't appear in area loot, you need to right click to take them.",
                        npcs = { "mummy hand", "scroll of the dead" },
                    },
                    {
                        text = "Return to Leela in Draynor Village.",
                        chat = "5 I think I can deal with this myself.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Reclaiming the papyri", needed = { "Al Kharid flyer, Sq'irkjuice, ring of charos (a)" },
                steps = {
                    {
                        text = "The scroll of praise:",
                        npcs = { "scroll of praise" },
                        subs = {
                            { text = "Get an Al Kharid flyer from Waseem the Leaflet Dropper north of the Al Kharid mine (at the entrance to the desert)." },
                            { text = "Varrock Lodestone or Archeology Journal Teleport." },
                            { text = "With your Al Kharid flyer, talk to Reldo in the Varrock palace library (most northern room of the ground floor) about the pyramid. or He will give you a scroll of praise.", chat = "3 I'd like to talk about a pyramid. / 4 I'd like to talk about a pyramid." },
                        },
                    },
                    {
                        text = "The copied name papyrus and mummy's name papyrus:",
                        npcs = { "copied name papyrus", "mummy's name papyrus" },
                        subs = {
                            { text = "Play the Sorceress's Garden minigame and obtain a mug of any sq'irkjuice." },
                            { text = "You need to use the sq'irkjuice on Ali Morrisane at his stall. Then talk with him..", chat = "3 I have some questions about a tomb. / 1 I'm after ways to reunite the mummy in the pyramid. / 4 I can't think of anything sensible to ask." },
                            { text = "Talk to him again with a ring of charos (a) equipped..", chat = "3 I have some questions about a tomb. / 1 I'm after ways to reunite the mummy in the pyramid. / 4 I can't think of anything sensible to ask." },
                            { text = "This step will only work after talking to the Wise Old Man during the Garden of Tranquillity, as the ring does not allow you to persuade people before this step." },
                            { text = "You should have received both a copied name papyrus and a mummy's name papyrus." },
                            { text = "Do not destroy the copied name papyrus or you will have to re-obtain a sq'irkjuice for another copy." },
                        },
                    },
                },
            },
            {
                title = "Collecting canopic jars", needed = {},
                steps = {
                    {
                        text = "Return to the pyramid with prayer points.",
                        npcs = {},
                    },
                    {
                        text = "Again, open the imposing door in the north-west corner.",
                        npcs = {},
                    },
                    {
                        text = "Kill the golem and descend the stairs (You may be placed in the mummy's tomb after descending the stairs, past the puzzle. If so, you will need to cross the puzzle to do the next 4 steps).",
                        npcs = {},
                    },
                    {
                        text = "Find a path of blue and green blocks or of red and yellow blocks all the way through.",
                        npcs = {},
                    },
                    {
                        text = "Go across the tiled room and collect the first canopic jar to the west of the northern staircase.",
                        npcs = {},
                        subs = {
                            { text = "If you spawn at the bottom of the northern staircase simply pick up the canopic jar to the west." },
                        },
                    },
                    {
                        text = "Collect the two remaining canopic jars and mummy with no hand in the tunnels. If you did not collect the fourth earlier, it can be found on one of the skeleton bodies upstairs. \"Rummage\" them and defeat them.",
                        npcs = { "mummy with no hand" },
                    },
                    {
                        text = "Use the mummy hand on the mummy with no hand.",
                        npcs = { "mummy hand", "mummy with no hand" },
                    },
                    {
                        text = "Return to the tiled room and cross back towards the empty sarcophagus.",
                        npcs = {},
                        subs = {
                            { text = "You may go upstairs and back downstairs to teleport to the tomb room to skip the tile puzzle." },
                        },
                    },
                },
            },
            {
                title = "Restoring the tomb", needed = { "20 fire rune, 1 willow log, jug of wine, spice, empty pot, and wheat" },
                steps = {
                    {
                        text = "Place jar on the shelves 4 times.",
                        npcs = {},
                    },
                    {
                        text = "Fill the empty sarcophagus.",
                        npcs = {},
                    },
                    {
                        text = "Pray at the 5 broken statues.",
                        npcs = {},
                        subs = {
                            { text = "This requires 150 prayer points." },
                        },
                    },
                    {
                        text = "Repair the chair and table.",
                        npcs = {},
                    },
                    {
                        text = "Use spice on your jug of wine.",
                        npcs = {},
                    },
                    {
                        text = "Use wheat on your empty pot.",
                        npcs = {},
                    },
                    {
                        text = "Replace the pot and jug.",
                        npcs = {},
                    },
                    {
                        text = "Run east and kill the shadow. Then light the enchanted sconces in the following order: south, north, west, east. Shadows will spawn and must be killed between each sconce lighting.",
                        npcs = {},
                    },
                    {
                        text = "Return to the Queen's chamber and create the statue on the empty base, then carve it 2 times.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Pharaoh Queen who has appeared in front of the table to give her the 2 papyri and the Scroll of Praise. (Not required for quest completion, only for 100% rebuild)",
                        npcs = { "Pharaoh Queen" },
                    },
                    {
                        text = "Right-click check-progress on your scroll of the dead or pyramid journal to verify you've rebuilt the mummy 75%. Otherwise, check any parts missed. (Or 100% if you want to finish the mummy)",
                        npcs = {},
                    },
                    {
                        text = "Talk to Leela in Draynor Village.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
