    {
        key = "monkey_madness", name = "Monkey Madness", wiki = "Monkey Madness/Quick guide",
        required = { "Gold bar", "Ball of wool", "Monkey bones from Karamja (or a monkey corpse or monkey skull)", "5 bananas (can be obtained in Ape Atoll)" },
        recommended = { "Level 43 Prayer or higher (for the protection prayers)", "Level 10 Thieving or higher (for increased success chance in lock-picking)", "Antipoison potions (Antipoison++ recommended), anti-poison totem, or a dip in the thermal bath to reduce poison damage", "Prayer potions for prayer restoration", "Super energy potions, a charged explorer's ring, mint cakes or a dip in the Salt-water spring for run energy boosts", "Ring of duelling", "Amulet of glory", "Ardougne cloak to quickly reach the Ardougne Zoo (Monastery teleport)", "200,000 coins if you want Glough to do the puzzle for you", "Food and/or Enhanced Excalibur for surviving the dangers of the island and cave", "A one-click teleport item (Ectophial)", "Spirit tree re-rooter for quicker access to the Tree Gnome Stronghold" },
        sections = {
            {
                title = "Missing 10th squad", needed = {},
                steps = {
                    {
                        text = "Speak to King Narnode Shareen in the Grand Tree. He will give you a gnome royal seal.",
                        chat = "Accept",
                        npcs = { "King Narnode Shareen", "gnome royal seal" },
                    },
                    {
                        text = "Right-click the ladder, select Top Floor, and take the glider from Captain Errdo to Karamja - 'Gandius'.",
                        chat = "5",
                        npcs = { "Captain Errdo" },
                    },
                    {
                        text = "Head north along the coast to reach the shipyard and try to enter through the gate.",
                        npcs = {},
                    },
                    {
                        text = "Speak with G.L.O. Caranock in the hut southeast of the gate.",
                        npcs = { "G.L.O. Caranock" },
                    },
                    {
                        text = "Return to King Narnode. He gives you Narnode's orders.",
                        npcs = { "Narnode's orders" },
                        subs = {
                            { text = "You can return to Captain Klemfoodle to take the glider to The Grand Tree - 'Ta Quir Priw'" },
                        },
                    },
                    {
                        text = "Talk to Daero, found on the east side of the 2nd floor of the Grand Tree. He is at the Blurberry bar platform.",
                        chat = "1 Talk about the journey / 4 Return to previous menu / 2 Talk about the 10th squad / 4 Return to previous menu / 3 Talk about Caranock / 4 Return to previous menu / 4 Leave... / 1 Who is it?",
                        npcs = { "Daero" },
                    },
                },
            },
            {
                title = "Solving puzzle before crashing", needed = {},
                steps = {
                    {
                        text = "Talk to Daero.",
                        npcs = { "Daero" },
                    },
                    {
                        text = "Begin the puzzle by clicking on the Reinitialisation Panel to the south-east in front of the long pipe.",
                        npcs = { "Reinitialisation Panel" },
                    },
                    {
                        text = "Unscramble the puzzle. Caution: The A3 and A5 pieces look near identical and can make the solving the puzzle difficult (A3 should have a straight cloud bottom on the tile and A5 should have a small curve at the bottom right corner of the tile).",
                        npcs = {},
                        subs = {
                            { text = "You can use this sliding puzzle solver." },
                            { text = "Or pay Glough 200,000 coins. He's located in the tree house south-east of the Grand Tree. Speak to Daero at the Blurberry bar platform to return to the hangar; you will only have to complete the last move in the puzzle if you pay.", chat = "1 / 1 / 1" },
                        },
                    },
                    {
                        text = "There is a cutscene when the puzzle is correct. Speak to Daero and then to Waydar to fly to Crash Island.",
                        chat = "1 Yes.",
                        npcs = { "Waydar" },
                    },
                    {
                        text = "Speak to Lumdo.",
                        npcs = { "Lumdo" },
                    },
                    {
                        text = "Speak to Waydar who will convince Lumdo to follow orders.",
                        chat = "4 I cannot convince Lumdo to take us to the island…",
                        npcs = {},
                    },
                },
            },
            {
                title = "Ape Atoll", needed = {},
                steps = {
                    {
                        text = "Recommended: turn off auto-retaliate and leave it off until the final battle (Can be toggled on/off by clicking the button left of the adrenaline gauge on the Action Bar).",
                        npcs = { "auto-retaliate" },
                    },
                    {
                        text = "On the island, travel west then north to a bamboo gate. Stand there getting pelted by poisoned arrows until you are brought to a prison. You will take some damage and be poisoned.",
                        npcs = {},
                    },
                    {
                        text = "Picklock the cell when there is no guard outside and escape the prison.",
                        npcs = {},
                        subs = {
                            { text = "Stay at least 2 squares away from the guards (even while in the cell) otherwise they will attack and damage you." },
                        },
                    },
                    {
                        text = "Stay in the grass to hide from archer monkeys and travel south against the western wall of the Temple of Marimbo.",
                        npcs = { "Temple of Marimbo" },
                    },
                    {
                        text = "Go east along the wall of the temple and around the monkey palace. Speak to Garkor.",
                        npcs = { "Garkor" },
                        tile = { x = 2805, y = 2762, plane = 0 },
                    },
                },
            },
            {
                title = "Zooknock", needed = { "gold bar, ball of wool, monkey bones" },
                steps = {
                    {
                        text = "Head to the U-shaped building in the southern side of the monkey village. Enter through the southern door otherwise you will be knocked out.",
                        npcs = {},
                        subs = {
                            { text = "Stay on the dark brown ground at the perimeter of the room." },
                        },
                    },
                    {
                        text = "Search the stacked crates two tiles east of the trapdoor for monkey dentures (you can grab another for making a tooth creature).",
                        npcs = { "monkey dentures", "tooth creature" },
                    },
                    {
                        text = "Search the south-easternmost crate (which is a different style and slightly darker brown) to crawl down into the basement - you may fall and take up to 50% of your life points in damage.",
                        chat = "1 Yes, I’m sure",
                        npcs = {},
                    },
                    {
                        text = "In the northwest corner there's a cluster of crates around a stalagmite; search the crate directly south of the stalagmite for a monkeyspeak amulet mould.",
                        npcs = { "monkeyspeak amulet mould" },
                    },
                    {
                        text = "If you needed to leave to obtain items, teleport to Al Kharid, go north, talk to Captain Dalbur to glide to the Tree Gnome Stronghold, then talk to Daero at Blurberry's Bar to return to the hangar, Waydar to return to Crash Island, and then Lumdo to return to Ape Atoll.",
                        npcs = { "Captain Dalbur", "Daero", "Waydar", "Lumdo" },
                    },
                    {
                        text = "If you didn't need to leave to obtain items, go to the area where you first landed on Ape Atoll. There is a one-way shortcut south of Garkor.",
                        npcs = {},
                    },
                    {
                        text = "Travel west until you see a dungeon on your mini-map. Climb down.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Ape Atoll Dungeon", needed = {},
                steps = {
                    {
                        text = "Run through the long dungeon.",
                        npcs = {},
                        subs = {
                            { text = "Protect from Melee is highly recommended here, as are antipoison and energy potions. Make sure to have several pieces of food (and/or Enhanced Excalibur) for healing from the traps and mobs." },
                        },
                    },
                    {
                        text = "At the end of the dungeon (the most north-eastern part), speak to Zooknock first.",
                        npcs = { "Zooknock" },
                    },
                    {
                        text = "Use the gold bar on Zooknock.",
                        npcs = {},
                    },
                    {
                        text = "Use the monkey dentures on Zooknock.",
                        npcs = {},
                    },
                    {
                        text = "Use the monkeyspeak amulet mould on Zooknock. He will give you an enchanted bar and your mould back.",
                        npcs = { "enchanted bar" },
                    },
                    {
                        text = "Use the bones on Zooknock if you already have them.",
                        npcs = {},
                        subs = {
