        recommended = { "Activated lodestone or other methods of getting to the following locations:", "Taverley", "Isafdar", "West Ardougne", "Feldip Hills", "Tree Gnome Stronghold", "Rimmington", "More toad crunchies for extra dialogue", "Something to cure poison", "Ring of Duelling For fast access to Castle Wars", "Food" },
        sections = {
