                            { text = "Heading to the entrance on the Kandarin side." },
                            { text = "Exiting Lletya and heading north on the Tirannwn side." },
                            { text = "Using a Traveller's necklace to the Outpost and running west." },
                            { text = "Using Home Teleport to Eagles' Peak lodestone and running south." },
                        },
                    },
                    {
                        text = "Kill a mourner. Pick up all pieces of the mourner outfit including the gas mask and mourner letter.",
                        npcs = { "mourner", "mourner outfit", "gas mask", "mourner letter" },
                        subs = {
                            { text = "You may now want to unequip and bank any combat equipment (unless you want to gather bear fur later) as you will not need it to progress the quest any longer." },
