                    {
                        text = "Go to Taverley and talk to Tegid at the southern lake, south of Jatix.",
                        npcs = { "Taverley", "Tegid", "Jatix" },
                    },
                    {
                        text = "Search the laundry basket near him to steal the soap.",
                        chat = "1",
                        npcs = {},
