    {
        key = "murder_mystery", name = "Murder Mystery", wiki = "Murder Mystery/Quick guide",
        required = { "An empty pot to fill during the quest, or 7 pots of flour if you prefer", "11–16 empty backpack spaces" },
        recommended = {},
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to a guard on the Sinclair Mansion property which is located north of Camelot Castle.",
                        chat = "Accept",
                        npcs = { "Guard (Sinclair Mansion)", "Sinclair Mansion", "Camelot Castle" },
                        subs = {
                            { text = "You can use fairy ring CJR, then walk south-east to the mansion entrance." },
                        },
                    },
                },
            },
            {
                title = "House of crime", needed = {},
                steps = {
                    {
                        text = "Inside the mansion, go to the crime scene in the room on the east side with the criminal's dagger and pungent pot on the floor.",
                        npcs = { "criminal's dagger", "pungent pot" },
                    },
                    {
                        text = "Take the pungent pot and criminal's dagger and investigate the window to find a criminal's thread.",
                        npcs = { "pungent pot", "criminal's dagger", "criminal's thread" },
                    },
                    {
                        text = "Search the barrels in the bedrooms owned by the following two suspects for two silver items.",
                        npcs = {},
                        subs = {
                            { text = "If the thread is red, search the barrels belonging to Bob to the west and Carol upstairs for a silver cup and silver bottle." },
                            { text = "If the thread is green, search the barrels belonging to Anna downstairs and David upstairs for a silver necklace and silver book." },
                            { text = "If the thread is blue, search the barrels belonging to Elizabeth and Frank upstairs for a silver needle and silver pot." },
                        },
                    },
                },
            },
            {
                title = "The evidence", needed = {},
                steps = {
                    {
                        text = "Fill the empty pots from the barrel of flour from the kitchen.",
                        npcs = { "empty pot", "barrel of flour" },
                    },
                    {
                        text = "Go to the gardener's shed in the very north-west of the mansion and take three flypapers from the sack.",
                        chat = "1 Yes, it might be useful.",
                        npcs = { "flypaper" },
                        subs = {
                            { text = "You must click the sack 3 times." },
                        },
                    },
                    {
                        text = "Use the pot of flour on the dagger.",
                        npcs = { "pot of flour" },
                    },
                    {
                        text = "Use the flypaper on the dagger to lift the fingerprint.",
                        npcs = {},
                    },
                    {
                        text = "Repeat with the two silver objects.",
                        npcs = {},
                    },
                    {
                        text = "Compare each fingerprint by using each suspect's print with the unknown print. The unknown print will then turn to the killer's print.",
                        npcs = { "unknown print", "killer's print" },
                    },
                    {
                        text = "Go to the mansion's gate and talk to Gossip.",
                        chat = "2 Who do you think was responsible?",
                        npcs = { "Gossip" },
                    },
                    {
                        text = "Go to the Forester's Arms in Seers' Village and talk to the Poison Salesman (to get there quickly, teleport to the Seers' Village lodestone).",
                        chat = "2 Who did you sell Poison to at the house?",
                        npcs = { "Forester's Arms", "Poison Salesman" },
                        subs = {
                            { text = "Or if \"The Fremennik Trials\" is started or finished.", chat = "1 Talk about the Murder Mystery Quest. / 2 Who did you sell Poison to at the house?" },
                        },
                    },
                },
            },
            {
                title = "A criminal revealed", needed = {},
                steps = {
                    {
                        text = "Return to the mansion and talk to the suspect with the matching fingerprint.",
                        chat = "3 Why'd you buy poison the other day?",
                        npcs = {},
                        subs = {
                            { text = "Or if the player still has the criminal's thread with them", chat = "4 Why'd you buy poison the other day?" },
                        },
                    },
                    {
                        text = "Find evidence. If your quest log says you have conclusive evidence and to talk to a guard, you may skip this step.",
                        npcs = {},
                        subs = {
                            { text = "If the prints match Bob, search the beehive in the cow pen." },
                            { text = "If the prints match Carol, search the drain on the wall directly north of the row of potatoes." },
                            { text = "If the prints match Anna, search the compost heap." },
                            { text = "If the prints match David, search the spider web upstairs between the two south rooms." },
                            { text = "If the prints match Elizabeth, search the fountain." },
                            { text = "If the prints match Frank, search the family crest on the outside of the manor building to the east of the entrance." },
                        },
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Talk to a guard.",
                        chat = "3 I know who did it!",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
