            {
                title = "Part 1", needed = {},
                steps = {
                    {
                        text = "(1/8) Go to the Kitchen and investigate the nut roast located on a table in the southeast corner of the room.",
                        npcs = { "Kitchen", "nut roast" },
                    },
                    {
                        text = "(2/8) At the north-west part of the Fort, by the northern gates, investigate the strange satchel beside the rock (southeast of the guards).",
                        chat = "~",
                        npcs = { "Gates (Fort Forinthry)", "strange satchel" },
                    },
                    {
                        text = "(3/8) Talk to Simon outside of the Town Hall and Link \"How to Poison Dummies for Dummies\".",
                        chat = "2 Link a clue to Simon.",
                        npcs = { "Simon (Murder on the Border)", "Town Hall (Fort Forinthry)" },
                    },
                    {
                        text = "(4/8) Investigate the half-buried box in the northeastern corner of the fort.",
                        npcs = { "half-buried box" },
                    },
                    {
                        text = "Detect the poison:",
                        npcs = {},
                        subs = {
                            { text = "Investigate the strange satchel again and take a poison detection potion (base).", chat = "1 Take a vial. / 2 Leave." },
                            { text = "Search the supply cupboard in the Kitchen and take a hollyhock.", chat = "1 Take hollyhock. / 4 Leave." },
                            { text = "Use the hollyhock on the vial to create an unheated poison detection potion (hollyhock)." },
                            { text = "Heat the vial on the range." },
                            { text = "(5/8) Use the poison detection potion (hollyhock) on the duke's meal (meat pâté) on the dining table.", chat = "2 Use it on the duke's meat pâté." },
                        },
                    },
                    {
                        text = "(6/8) Talk to King Roald in the Chapel.",
