    {
        key = "my_arm_s_big_adventure", name = "My Arm's Big Adventure", wiki = "My Arm's Big Adventure/Quick guide",
        required = { "3 buckets of ugthanki dung (camel dung)", "Some coins", "Bucket (may be obtained during the quest)", "Climbing Boots or rock climbing boots or Trollheim teleport", "7 supercompost", "There is a Tool leprechaun available when and where the below items will be needed, and he sells them, so players will not need to carry these items with them for the duration of the quest.", "Rake (can't be on the tool belt, may be obtained during the quest)", "Seed dibber (can't be on the tool belt, may be obtained during the quest)", "Spade (can't be on the tool belt, may be obtained during the quest)", "Plant cure (or an additional supercompost; Cure Plant from the Lunar Spellbook will not work, may be obtained during the quest)" },
        recommended = { "Level 61 Magic and runes for Trollheim Teleport", "Food", "Armour", "Weapon", "A bucket of compost or an additional supercompost", "Tai bwo wannai teleport" },
        sections = {
            {
                title = "The adventurer", needed = { "Bring all items required for the next step" },
                steps = {
                    {
                        text = "Go to the Troll Stronghold, head south then downstairs into the kitchen.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Burntmeat.",
                        chat = "Accept / 2 Alright, I'll lend him a hand.",
                        npcs = { "Burntmeat" },
