                    {
                        text = "Talk to My Arm, east of Burntmeat.",
                        npcs = { "My Arm" },
                    },
                },
            },
            {
                title = "Getting the goutweed", needed = { "Climbing boots, 3 buckets of Ugthanki dung, 7 buckets of supercompost, 1 empty bucket" },
                steps = {
                    {
                        text = "Travel to Burthorpe and head north-west past Troll Invasion.",
                        npcs = {},
                    },
                    {
                        text = "Climb the rocks and head east past the thrower trolls to reach the Death Plateau.",
                        npcs = { "thrower trolls", "Death Plateau (location)" },
                    },
                    {
                        text = "Search the cooking pot to obtain a.",
                        npcs = { "Cooking pot (Death Plateau)" },
                        subs = {
                            { text = "If you receive the message \"... but you can't reach very far into it.\", use an empty bucket on the cooking pot." },
                        },
                    },
                    {
                        text = "Return to the Troll Stronghold kitchen and speak to My Arm.",
                        npcs = { "Troll Stronghold (area)" },
                    },
                    {
                        text = "Once on the surface, talk to him near the farming patch.",
                        npcs = {},
                    },
                    {
                        text = "Read the he gives you, then talk to him again.",
                        npcs = {},
                    },
                    {
                        text = "Use the 3 buckets of and 7 buckets of on the soil patch.",
                        npcs = { "New farming patch" },
                    },
                    {
                        text = "Talk to My Arm for a cutscene.",
                        chat = "1 This is My Arm. We'd like to go to Karamja.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Getting the tubers", needed = { "At least 1 free inventory space to receive the gout tubers" },
                steps = {
                    {
                        text = "Talk to Captain Barnaby if you find yourself in Ardougne.",
                        npcs = { "Captain Barnaby", "Ardougne" },
                    },
                    {
                        text = "Talk to My Arm south-east of the Karamja lodestone. He is east of Jiminua's Jungle Store.",
                        npcs = { "Karamja lodestone", "Jiminua's Jungle Store" },
                    },
                    {
                        text = "Talk to Murcaily, guarding the tree grove north-east of Tai Bwo Wannai.",
                        chat = "1 A troll called My Arm wants a favour...",
                        npcs = { "Murcaily" },
                    },
                    {
                        text = "A cutscene will play. Go through the dialogue.",
                        npcs = {},
                    },
                    {
                        text = "Talk to My Arm south-east of the Karamja lodestone. Continue through the dialogue while on the boat.",
                        npcs = { "Karamja lodestone" },
                    },
                },
            },
            {
                title = "Teaching a troll to farm", needed = { "Spade, rake, hardy gout tubers, seed dibber, plant cure, combat equipment to fight a level 56 and 77" },
                steps = {
                    {
                        text = "Return to the roof of the Troll Stronghold where the soil patch was.",
                        npcs = { "Troll Stronghold" },
                    },
                    {
                        text = "If you don't already have the farming tools, right-click talk to the Tool Leprechaun to buy some.",
                        chat = "4 Would you like to trade?",
                        npcs = { "Tool Leprechaun" },
                    },
                    {
                        text = "Talk to My Arm.",
                        npcs = {},
                    },
                    {
                        text = "Use the following items on him in order:",
                        npcs = {},
                        subs = {
                            { text = "(twice as he breaks it)" },
                            { text = "Pick up and use the on the, give him the assembled rake again." },
                            { text = "(optional but recommended). Without supercompost, the patch may become diseased and require curing. Regular compost and ultracompost have no effect." },
                            { text = "If the patch becomes diseased, a" },
