        key = "nadir_saga", name = "Nadir (saga)", wiki = "Nadir (saga)/Quick guide",
        required = { "Ring of kinship to find the damaged device", "Standard spells must be used for completing this saga" },
        recommended = { "Persistent Rage relic power may trivialise some of this content", "To play the unabridged version:", "Level 60 Attack", "Level 55 Dungeoneering", "Level 45 Thieving" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Start by finding a damaged device on Daemonheim floors 18-22.",
                        npcs = { "damaged device" },
                        subs = {
                            { text = "You might need to talk to Skaldrun to check whether the Nadir saga is already unlocked." },
                        },
                    },
                    {
                        text = "Then start saga with Skaldrun south-west of the Daemonheim entrance.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The Ritual Site", needed = {},
                steps = {
                    {
                        text = "Wait approximately one minute for Zemouregal and Lucien to finish their conversation.",
                        npcs = {},
                    },
                    {
                        text = "Finish the dialogue and cutscene then continue north to interrogate the merchant.",
                        npcs = {},
                    },
                    {
                        text = "Hunt for 3 memories (having sound turned on helps a lot here).",
                        npcs = {},
                        subs = {
                            { text = "Move your mouse around until the orange circle rapidly pulses THREE times per second on a location, and click, as this is a correct spot. There are three speeds--you want to click at the fastest, highest-pitched ping. Repeat until all three memories are recovered." },
                            { text = "If only half the memory is recovered, you did not do this step correctly and as a result an unabridged tome will not be awarded, you can lobby to restart the saga." },
                            { text = "A pinging sound will play if game sounds are turned on: a slow hum (level 1), a moderately fast ping (level 2, indicating you are close to the correct position), and a fast, high-frequency ping that plays ~2 times a second. This is the correct location for full memory retrieval." },
                            { text = "The correct location does not always correspond to the centre of a memory you can see. It can also be an empty space." },
                            { text = "Note: On mobile, there is a bug, read the full article to find out how to deal with this." },
                        },
                    },
                    {
                        text = "Continue north and climb down the dungeon entrance.",
                        npcs = {},
                    },
                },
            },
