    {
        key = "nature_spirit", name = "Nature Spirit", wiki = "Nature Spirit/Quick guide",
        required = { "Silver sickle (Can be made from a silver bar and a sickle mould or bought from the Grand Exchange. Not able to make unless part of the Nature Spirit quest has been completed. Talk to Filliman to obtain the ability to craft this.)", "Ghostspeak amulet" },
        recommended = { "Level 18 Crafting (For making the silver sickle if not bought)", "Level 10 Prayer (Or a couple of prayer potions to restore Prayer Points)", "Food, if you are a low-levelled player, to absorb attacks from ghasts.", "Combat equipment to kill the ghasts if you are a low-levelled player.", "A prayer potion in case you use up all of your druid pouches and you have to re-harvest fungus.", "Canifis home teleport", "The Invitation Box for teleports to Paterdomus" },
        sections = {
            {
                title = "Getting started", needed = { "Ghostspeak amulet" },
                steps = {
                    {
                        text = "Make sure you have prayer points before starting.",
                        npcs = {},
                        tile = { x = 3404, y = 3507, plane = 0 },
                    },
                    {
                        text = "Talk to Drezel, who is located underground near Paterdomus. The entrance is north from the temple's door. You should have six empty backpack space; otherwise the food he gives you will appear on the floor.",
                        npcs = { "Drezel", "Paterdomus" },
                        subs = {
                            { text = "If you have lost Wolfbane:", chat = "2 Talk about something else. / 2 Is there anything else interesting to do around here? / Accept / 4 Yes, I'll go and look for him. / 1 Yes, I'm sure." },
                            { text = "If you have Wolfbane in your bank or backpack:", chat = "2 Is there anything else interesting to do around here? / Accept / 4 Yes, I'll go and look for him. / 1 Yes, I'm sure." },
                            { text = "If you have just completed Priest in Peril, then you might need to exit and reenter the Mausoleum before the quest dialogue will appear. Drezel should be standing in the last chamber before the holy barrier." },
                        },
                    },
                    {
                        text = "Exit into Morytania and travel south to a fence.",
                        npcs = {},
                    },
                    {
                        text = "Look along the fence for a gate and go through it.",
                        npcs = {},
                    },
                    {
                        text = "Go south until a round island is found with a grotto tree.",
                        npcs = {},
                    },
                    {
                        text = "Jump across the broken bridge and onto the island.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The ghost of the grotto", needed = {},
                steps = {
                    {
                        text = "Search the bench nearby for a small mirror.",
                        npcs = { "mirror" },
                    },
                    {
                        text = "Search the grotto tree for Filliman's journal.",
                        npcs = { "grotto tree", "Journal (Nature Spirit)" },
                    },
                    {
                        text = "Equip your ghostspeak amulet and talk to Filliman Tarlock.",
                        chat = "2 How long have you been a ghost?",
                        npcs = { "ghostspeak amulet", "Filliman Tarlock" },
                    },
                    {
                        text = "Use the mirror on Filliman to prove he's a ghost.",
                        chat = "2 So, what's your plan? / 4 How can I help?",
                        npcs = {},
                        subs = {
                            { text = "He'll give you a druidic spell." },
                        },
                    },
                },
            },
            {
                title = "Becoming a nature spirit", needed = {},
                steps = {
                    {
                        text = "Return to Drezel to be blessed and teleported back to Filliman.",
                        npcs = { "Drezel" },
                        subs = {
                            { text = "If you have lost the wolfbane:", chat = "2 Talk about something else. / 1 Yes, please" },
                            { text = "If you have the wolfbane in your backpack or bank:", chat = "1 Yes, please" },
                        },
                    },
                    {
                        text = "Jump the bridge and find a nearby rotting log in the swamp.",
                        npcs = { "rotting log" },
                        subs = {
                            { text = "There is some directly West of the Grotto tree island." },
                        },
                    },
                    {
                        text = "Cast the druidic spell in your backpack, then pick the fungus from the log.",
                        npcs = {},
                    },
                    {
                        text = "Take the Mort myre fungus mushroom from the log and talk to Filliman.",
                        npcs = { "Mort myre fungus" },
                    },
                    {
                        text = "Use the Mort myre fungus on the western, yellow stone.",
                        npcs = {},
                    },
                    {
                        text = "Use a used spell on the eastern, grey stone.",
                        npcs = { "a used spell" },
                    },
                    {
                        text = "Stand on top of the southern, orange stone in the centre by right-click selecting \"Walk here\".",
                        npcs = {},
                    },
                    {
                        text = "Tell Filliman the puzzle is solved.",
                        chat = "3 I think I've solved the puzzle!",
                        npcs = {},
                    },
                    {
                        text = "Enter the Grotto tree.",
                        npcs = {},
                    },
                    {
                        text = "Search the Grotto in the centre.",
                        npcs = { "Grotto" },
                    },
                    {
                        text = "Continue speaking with Nature Spirit and he will ask you for a silver sickle.",
                        chat = "4 Ok, thanks.",
                        npcs = { "Nature Spirit (NPC)", "silver sickle" },
                    },
                },
            },
            {
                title = "Killing the ghasts", needed = { "Silver sickle, at least 1 prayer point" },
                steps = {
                    {
                        text = "Obtain a silver sickle via:",
                        npcs = { "silver sickle" },
                        subs = {
                            { text = "Purchasing it from the Grand Exchange." },
                            { text = "Crafting one yourself:" },
                            { text = "Obtain a sickle mould from a Crafting shop or the Grand Exchange. You may add it to the tool belt." },
                            { text = "Smelt at a furnace with a silver bar. Select \"silver bar\" under \"Casting Metals & Glass\" section on the interface, and then select the \"silver sickle\" option in the \"Silver Casting\" section." },
                        },
                    },
                    {
                        text = "Return to the grotto either by speaking to Drezel, or by navigating via the Morytania Swamp.",
                        chat = "1 Yes, please",
                        npcs = {},
                    },
                    {
                        text = "Enter the grotto tree.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Nature Spirit with a silver sickle in your backpack. He will bless it for a silver sickle (b).",
                        npcs = { "silver sickle (b)" },
                    },
                    {
                        text = "Exit the grotto, jump the bridge into the swamp and stand next to the nearby rotting log.",
                        npcs = {},
                    },
                    {
                        text = "Right-click Bloom the silver sickle (b) in your backpack. Blooming requires at least 1 prayer point.",
                        npcs = {},
                    },
                    {
                        text = "Pick the fungi from the log. You will need at least 3 total fungi (ghasts can rot the contents of the pouch).",
                        npcs = {},
                    },
                    {
                        text = "Fill the druid pouch in your backpack to add the fungi into it.",
                        npcs = {},
                    },
                    {
                        text = "Invoke and kill 3 nearby ghasts, consuming 1 fungus per invocation.",
                        npcs = { "ghast" },
                    },
                },
            },
            {
                title = "Finishing up", needed = { "3 backpack spaces" },
                steps = {
                    {
                        text = "If you drop anything to receive the rewards, it will be lost.",
                        npcs = {},
                    },
                    {
                        text = "Return to the Nature Spirit in the grotto.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                    {
                        text = "(Optional) Pray at the altar to complete one of the easy Morytania achievements, Fortified Spirit.",
                        npcs = { "easy Morytania achievements", "Fortified Spirit" },
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "Nature Spirit",
                        npcs = { "Nature Spirit (achievement)" },
                    },
                    {
                        text = "Morytania achievements",
                        npcs = { "Morytania achievements" },
                        subs = {
                            { text = "Easy" },
                            { text = "Fortified Spirit" },
                            { text = "Struck A-Ghast" },
                            { text = "Blooming Marvellous" },
                        },
                    },
                },
            },
        },
    },
