        key = "nomad_s_elegy", name = "Nomad's Elegy", wiki = "Nomad's Elegy/Quick guide",
        required = { "2 free inventory spaces" },
        recommended = { "Level 105 Combat or more is strongly recommended", "Dreadnips", "Any shield (to use Resonance) for Nomad's charged blast in second phase", "High-healing food and combat equipment", "Magic style is preferred for the use of Guthix staff's affinity debuff when fighting Nomad", "Vulnerability or Smoke Cloud is helpful as well", "Stat-boosting combat potions (such as overloads)", "The Dominion marker does not work in the fight against Nomad", "A beast of Burden for the fight against Nomad", "Aggression potions for the Bandosian afterlife and protecting the battering ram" },
        sections = {
            {
                title = "Beginning", needed = {},
                steps = {
                    {
                        text = "Make sure you have combat equipment (but not your familiar yet) from this point. If you die, you will be returned to Death's office and will have to leave and re-enter via Death's Hourglass (i.e. not War's Retreat) to resume progress with the quest.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Zimberfizz in the Soul Wars area.",
                        chat = "2 Talk about Nomad's Elegy / Accept",
                        npcs = { "Zimberfizz", "Soul Wars" },
                    },
                    {
                        text = "Investigate Nomad's tent to the east.",
                        npcs = {},
                    },
                    {
                        text = "Investigate the throne, some crystals to the west, and sticky goo south of that.",
                        npcs = {},
                    },
                    {
                        text = "Investigate the strange emissions to the southwest. You will be sent to Death's Realm.",
                        npcs = {},
                    },
                    {
                        text = "Go through the dialogue and travel through Death's door to the north (the mosaic of Death behind his desk).",
                        npcs = {},
                    },
                },
            },
            {
                title = "Freeing Zanik", needed = {},
                steps = {
                    {
                        text = "Speak to Death again.",
                        chat = "1 What do we need to do now? / 5 I have to go.",
                        npcs = {},
                    },
                    {
                        text = "Embark on the Bloodstained Jetty to the north-east. (You cannot bring a familiar here.)",
                        chat = "1 Yes",
                        npcs = {},
                    },
                    {
                        text = "If you leave the Underworld, you can return by entering Death's Office from Draynor. Do not enter from War's Retreat.",
                        npcs = {},
                    },
                    {
                        text = "Defeat oncoming waves of Bandosians to protect the cave goblins. There are three waves, and progress is saved after each wave. Aggression potions can help, though some of the Bandosians can slip past.",
                        npcs = { "Bandosian", "Aggression potion" },
                    },
                },
            },
            {
                title = "Gathering your allies", needed = { "2 free inventory spaces" },
                steps = {
                    {
                        text = "Embark on the Dusty Jetty to the north-west.",
                        chat = "1 Yes",
                        npcs = {},
                    },
                    {
                        text = "Speak to Astrid/Brand.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Jessika/Korasi", needed = {},
                steps = {
                    {
                        text = "Speak to Korasi/Jessika in the house north of Bob's Brilliant Axes.",
                        npcs = { "Bob's Brilliant Axes" },
                    },
                    {
                        text = "Travel to the south-west of Lumbridge Castle grounds. Speak to Wizard Grayzag for half of Korasi's/Jessika's memories.",
                        chat = "1 I'm not Korasi/Jessika. / 3 My name is Korasi/Jessika. / 2 Wizard Grayzag? / 2 You represent danger. / 4 I am not afraid of you! / 1 Then I won't fail.",
                        npcs = {},
                    },
                    {
                        text = "Travel to the of the Lumbridge Castle wall using the southern gate ladder (not within the main castle keep), and speak to the person you saved in The Void Stares Back to recover the other half of Korasi's/Jessika's memory.",
                        npcs = { "The Void Stares Back" },
                    },
                    {
                        text = "Combine the memory halves.",
                        npcs = {},
                    },
                    {
                        text = "Return Korasi's/Jessika's completed memory to her north of Bob's Axes.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Hazelmere", needed = {},
                steps = {
                    {
                        text = "Talk to Hazelmere on the of Lumbridge castle.",
                        npcs = {},
                    },
                    {
                        text = "Find and talk to him again on the and above on the above where the bank normally is by using the ladder on the north side of the building.",
                        npcs = {},
                    },
                    {
                        text = "Climb either of the two tower ladders of the castle gate (not within the main castle keep); he will be on the.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Hazelmere in what would normally be Bob's Axes.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Hazelmere west of Lumbridge Castle.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Hazelmere next to Astrid/Brand.",
                        chat = "1 I need you to help me fight Nomad.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Xenia", needed = {},
                steps = {
                    {
                        text = "Speak to Xenia in the Lumbridge Castle.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Attempt to open the chest in the northern room on the.",
                        npcs = {},
                        subs = {
                            { text = "Kill Guilt, pick up the guilt ridden key, then open and search the chest for a Xenia memory half. The key will not drop if you are in a group." },
                        },
                    },
                    {
                        text = "Climb to the and attempt to open the chest in the room.",
                        npcs = {},
                        subs = {
                            { text = "Kill Shame, pick up the shame filled key, then open and search the chest for a other Xenia memory half." },
                        },
                    },
                    {
                        text = "Combine the memory halves and return the completed memory to Xenia.",
                        npcs = { "Xenia memory" },
                    },
                    {
                        text = "Talk to Astrid/Brand.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Enter the portal to leave.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Interrogation", needed = {},
                steps = {
                    {
                        text = "Plan the war table in the centre area.",
                        npcs = {},
                    },
                    {
                        text = "Begin interrogating Legio Septimus. The player has the option to kill him outright by repeated torture which will end this section quickly, or to make his willpower low and restore his sanity high, so he answers your questions truthfully which unlocks a shortcut in the battering ram battle later.",
                        npcs = { "Legio Septimus" },
                        subs = {
                            { text = "To kill him outright, select Threaten him, then 'remove' crystals until Legio dies." },
                            { text = "To fully interrogate him instead, threaten him until it is no longer effective. Then use Zanik's Good Cop option and Xenia's Bad Cop option until his sanity is about 50%. Then use Charm to lower his willpower to about 50% as well. Finally raise his sanity back up to about 80% using Zanik's Bad Cop option and Xenia's Good Cop Option. Ask the questions, and his answers should be sane and cooperative. Once answered, choose whether to kill or release him (choice currently has no effect on future events)" },
                        },
                    },
                },
            },
            {
                title = "Battering ram", needed = {},
                steps = {
                    {
                        text = "Click the war table and select any two companions.",
                        npcs = {},
                    },
                    {
                        text = "Collect 25 wood and 25 metal. You can put both companions on the same material; by the time you complete the other, they will be finished.",
                        npcs = {},
                    },
                    {
                        text = "Leave through the exit once complete.",
                        npcs = {},
                    },
                    {
                        text = "Build the battering ram to the north (takes a few minutes while dialogue plays).",
                        npcs = {},
                    },
                    {
                        text = "Return to the war table.",
                        npcs = {},
                    },
                    {
                        text = "Slowly walk the battering ram across the bridge and through the doors.",
                        npcs = {},
                    },
                    {
                        text = "Suggestion 1: Put Zanik north-west by battering ram, Death north-east and the remaining four block off the start of the bridge while fighting.",
                        npcs = {},
                    },
                    {
                        text = "Suggestion 2: Place your companions three on each side of the ram, and stand on the bridge's edge blocking off all the monsters while using an aggression potion which requires level 82 Herblore. Fight or withstand the attacks until the ram is done.",
                        npcs = {},
                    },
                    {
                        text = "Choose to either head north and assault the fortress head-on, or if you unlocked the information in the earlier interrogation, detour through the east door and enter the secret passage in the north wall of the cave, which will bypass the second half of the assault.",
                        npcs = {},
                    },
                    {
                        text = "Once inside, you'll have to fight Nomad.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Fighting Nomad and Gielinor", needed = { "Combat equipment and high-healing food", "If the Persistent Rage relic power is unlocked, it can be used to allow Regenerate to heal Xenia and Death during the following encounters without draining your character's adrenaline. If at any point you leave, you can enter Death's hourglass in Draynor." },
                steps = {
                },
            },
            {
                title = "First combat phase", needed = {},
                steps = {
                    {
                        text = "Dwindle away Nomad's health, and move away from the centre of the bridge to avoid Gielinor's hand. Also move away from shadows that appear on the ground to avoid rapid powerful magic attacks. Use Surge if you can.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Xenia", needed = {},
                steps = {
                    {
                        text = "Stand in the middle of each of the three sections in the area and constantly use the 3 abilities made available. Move to the next one when one side is finished.",
                        npcs = {},
                        subs = {
                            { text = "Use Fire Blast when Rorarii are present." },
                            { text = "Use Shield Dome when Gladii are present." },
                            { text = "Use Shadow Stalk when Scutarii are present." },
                            { text = "Every time you attack a Capsarii, it will heal Xenia for a small amount." },
                        },
                    },
                },
            },
            {
                title = "Second combat phase", needed = {},
                steps = {
                    {
                        text = "In addition to the previous phase's attacks, when Nomad teleports you near him and orders you to 'face his wrath', switch to your shield to use Resonance to negate any and all damage from the attack.",
                        npcs = { "Resonance" },
                    },
                },
            },
            {
                title = "Death", needed = {},
                steps = {
                    {
                        text = "Go directly north, south, east and west of Gielinor. Each time provoking him and quickly getting out of the way, to then use Scythe on the hand, and finally claim the released spirit.",
                        npcs = { "Provoke" },
                    },
                },
            },
            {
                title = "Third combat phase", needed = {},
                steps = {
                    {
                        text = "In addition to the previous phases' attacks, Nomad will create a clone of himself when he reaches half health. Kill them both (you might kill Nomad first, in which case you will move on).",
                        npcs = {},
                    },
                },
            },
            {
                title = "Icthlarin", needed = {},
                steps = {
                    {
                        text = "Quickly and without stopping, run around the area anti-clockwise, releasing the souls as you get in the middle of a group of them. Make sure to get over half of the initial total number of spirits.",
                        npcs = {},
                    },
                    {
                        text = "The more souls you release, the more powerful the attack reflected onto Gielinor will be.",
                        npcs = {},
                    },
                    {
                        text = "Once all souls have been released, continue circling until Gielinor stops firing the beam, then shield yourself from Gielinor's attack with the ability, in order to reflect the damage onto Gielinor.",
                        npcs = {},
                    },
                    {
                        text = "You will have to repeat this process a few times.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Final combat phase", needed = {},
                steps = {
                    {
                        text = "In this phase, Nomad will only be using rapid melee attacks. Kill him by any means. If using Ranged, Magic or Necromancy, then you can run around the room to avoid damage from Nomad, using Surge to gain distance. Watch out for Gielinor's attacks. Protect from Melee or Deflect Melee, especially combined with Devotion, can reduce or negate much of Nomad's damage in this phase, though the speed of his attacks can still be problematic.",
                        npcs = { "Surge", "Protect from Melee", "Deflect Melee", "Devotion" },
                    },
                },
            },
            {
                title = "Aftermath", needed = {},
                steps = {
                    {
                        text = "Choose who ends Gielinor.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Decide Nomad's fate.",
                        chat = "Any / Any / Any",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene, speak with Death.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Choose Zanik's fate.",
                        chat = "Any / Any / Any",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "nomad_s_requiem", name = "Nomad's Requiem", wiki = "Nomad's Requiem/Quick guide",
        required = { "A magic weapon to cast a fire spell", "Air runes and fire runes for the fire spell or runes to cast a fire-aligned Ancient Magicks spell. A staff alone will not work" },
        recommended = { "Level 76 Constitution highly recommended, Nomad uses an attack that deals exactly 7,500 damage. If you have Level 71 Constitution, the Font of Life relic power can be harnessed to boost the max life points by 500.", "Level 75 Combat or higher, unless you're particularly good at combat", "Combat equipment, food, and potions", "Beast of Burden or healing summoning familiar", "Standard prayer book active, or restore potions or super restores" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Teleport to Edgeville and run south-east into the Soul Wars portal.",
                        npcs = { "Edgeville", "Soul Wars portal" },
                    },
                    {
                        text = "Talk to Zimberfizz the imp in the lobby.",
                        chat = "Accept",
                        npcs = { "Zimberfizz" },
                        subs = {
                            { text = "Note: if you haven't done the Soul Wars tutorial you won't be able to accept the quest." },
                        },
                    },
                    {
                        text = "Investigate Nomad's tent and watch the cutscene.",
                        npcs = { "Nomad" },
                    },
                },
            },
            {
                title = "The hidden temple", needed = {},
                steps = {
                    {
                        text = "Talk to Nomad.",
                        chat = "2 Zimberfizz sent me here to see where you went.",
                        npcs = {},
                    },
                    {
                        text = "Go up the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Zimberfizz.",
                        chat = "1 Talk about Nomad's Requiem.",
                        npcs = {},
                    },
                    {
                        text = "Investigate the tent.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Water", needed = {},
                steps = {
                    {
                        text = "Enter the south-western doorway.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the south-eastern ladder and pull the north lever.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the north-eastern ladder and move both pillars over the drains.",
                        npcs = {},
                    },
                    {
                        text = "Climb down the ladder and make sure that water is flowing through the southern channel. If it is not, operate the levers until it is. The symbol at the top of a pillar represents the direction of water flow through the pillar.",
                        npcs = {},
                    },
                    {
                        text = "Climb down the south-eastern ladder and complete the puzzle. A solution is pictured to the right and another solution is right below. Click on the statues in the following order:",
                        npcs = {},
                        subs = {
                            { text = "Centre, west statue" },
                            { text = "North, west statue" },
                            { text = "North, centre statue" },
                            { text = "North, east statue" },
                            { text = "Centre, east statue" },
                            { text = "South, east statue" },
                            { text = "South, centre statue" },
                            { text = "Centre, centre statue" },
                            { text = "North, centre statue" },
                            { text = "North, east statue" },
                            { text = "Centre, east statue" },
                            { text = "South, east statue" },
                            { text = "South, centre statue" },
                            { text = "South, west statue" },
                            { text = "Centre, west statue" },
                            { text = "North, west statue" },
                            { text = "North, centre statue" },
                            { text = "North, east statue" },
                            { text = "Centre, east statue" },
                            { text = "South, east statue" },
                        },
                    },
                },
            },
            {
                title = "Elementals", needed = {},
                steps = {
                    {
                        text = "Climb up the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Mine the rubble at the tunnel at the end of the eastern channel",
                        npcs = {},
                    },
                    {
                        text = "Pull the southern lever until water flows to the new tunnel.",
                        npcs = {},
                    },
                    {
                        text = "Climb down the ladder to the bottom floor.",
                        npcs = {},
                    },
                    {
                        text = "Enter the northern doorway,",
                        npcs = {},
                    },
                    {
                        text = "Enter the south-eastern doorway.",
                        npcs = {},
                    },
                    {
                        text = "There should be a waterfall in this room. If water is only dripping, the levers were not operated properly.",
                        npcs = {},
                    },
                    {
                        text = "Take some Elemental fuel out of the Fuel hopper located at the north-eastern or south-eastern corner of the room.",
                        npcs = { "Elemental fuel", "Fuel hopper" },
                    },
                    {
                        text = "Lure an Elemental creature out of the strange device and into the waterfall by placing the fuel on the floor.",
                        npcs = { "Elemental creature" },
                    },
                    {
                        text = "Do the above step a total of three times.",
                        npcs = {},
                    },
                    {
                        text = "Exit the room through the northern doorway.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Vines", needed = { "Combat gear, weapons, food" },
                steps = {
                    {
                        text = "Enter the arcane doorway and then enter the western doorway.",
                        npcs = {},
                    },
                    {
                        text = "Attempt to destroy a root surrounding the strange device.",
                        npcs = {},
                    },
                    {
                        text = "Follow the vines on the floor and destroy four lone roots to which the vines lead.",
                        npcs = {},
                    },
                    {
                        text = "Go back to the strange device.",
                        npcs = {},
                    },
                    {
                        text = "Kill the Decaying avatar. Destroy the roots when they appear at the corners of the room. Strategies can be found here.",
                        npcs = { "Decaying avatar" },
                    },
                    {
                        text = "Exit the room through the eastern doorway.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Smoke", needed = { "Magic weapon, fire runes, air runes, 5 free inventory spaces, Restore potions or standard prayers" },
                steps = {
                    {
                        text = "Talk to the knight near the eastern doorway.",
                        npcs = {},
                    },
                    {
                        text = "Before entering the next room, consider turning on Piety to avoid constant damage and stat reduction or bringing a super restore potion to keep your magic level high enough to cast a fire spell. The Corruption beasts inside restore prayer upon death.",
                        npcs = { "Piety", "super restore", "Corruption beast" },
                    },
                    {
                        text = "Enter the eastern doorway.",
                        npcs = {},
                    },
                    {
                        text = "Pick up five stone slabs (Take-slab from the rubble piles all around the room).",
                        npcs = { "Stone slab (Nomad's Requiem)" },
                    },
                    {
                        text = "Place the stone slabs to complete and cross the bridge across the central body of water.",
                        npcs = {},
                    },
                    {
                        text = "Ignite the barrels with a magic weapon equipped and a fire spell active (75 Magic required to ignite the barrels).",
                        npcs = {},
                    },
                    {
                        text = "Cross the bridge and exit the room through the western doorway.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Nomad", needed = {},
                steps = {
                    {
                        text = "Make any necessary preparations to fight Nomad. You can teleport out, and bank to prepare for the fight.",
                        npcs = {},
                    },
                    {
                        text = "To return to the area, teleport to Edgeville, enter into the Soul Wars portal, and investigate the tent again.",
                        npcs = {},
                    },
                    {
                        text = "Enter the arcane doorway at the northern wall then the arcane doorway on the inner southern wall.",
                        chat = "1 Yes. / Any",
                        npcs = {},
                    },
                    {
                        text = "Kill Nomad. (Deathtouched darts work)",
                        npcs = {},
                    },
                    {
                        text = "Strategies can be found here. Recommended if you haven't fought him before.",
                        npcs = { "Nomad/Strategies" },
                        subs = {
                            { text = "If you are a high combat level (130+) and have tier 80 gear or higher, you will likely kill him easily without worrying about his final stun ability. Bring high-healing food like shark or sea turtle and just keep attacking him and healing while standing directly beside him." },
                            { text = "In short; bombs laid on the floor deal 4,000 damage when stepped on." },
                            { text = "Avoid them by walking DIRECTLY south, he does not place one there." },
                            { text = "\"You cannot hide from my wrath\" deals 7,500 damage. Either eat above that or hide behind a pillar." },
                            { text = "If he summons clones, the real one attacks you last, otherwise kill them all." },
                            { text = "An alternative is hide from them, after about 90 seconds the three fake ones will despawn. Make sure to re-attack him quickly after this so he does not reset, he does not use \"Face me!\" while clones are present." },
                            { text = "\"Face me!\" if he doesn't hit you in time, he restores his life points and teleports you. For example, if you were hiding behind a pillar." },
                            { text = "Towards the end of the fight he teleports you to the centre and stuns you. The next attack deals all your maximum life points, minus 1. So eat to full." },
                            { text = "If you bring a shield, swap to it and use resonance. This blocks the attack 100% but does not heal you." },
                            { text = "\"This. Ends. Now\" starts attacking you rapidly. It's important to finish him off at this point and not hide, otherwise he will restore his life points and you'll have to restart the fight." },
                        },
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Talk to Zimberfizz.",
                        chat = "1 Talk about Nomad's Requiem. / Any",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "observatory_quest", name = "Observatory Quest", wiki = "Observatory Quest/Quick guide",
        required = { "3 normal planks", "Bronze bar", "Molten glass" },
        recommended = { "Antipoison potions (a super antipoison (1) can be found in the southeast building of the goblin camp) or a piece of augmented equipment with the Venomblood Invention perk.", "A ring of duelling", "An energy potion or any explorer's ring to boost run energy" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to the Observatory professor in the house near the Observatory which is located north of Castle Wars.",
                        chat = "1 Talk about the Observatory Quest. / 2 An Observatory? / Accept",
                        npcs = { "Observatory professor", "Observatory", "Castle Wars" },
                    },
                    {
                        text = "Obtain a bronze bar, 3 planks, and molten glass.",
                        npcs = { "bronze bar", "plank", "molten glass" },
                    },
                    {
                        text = "Talk to the professor three times (until he takes all of the above items).",
                        chat = "1 Talk about the Observatory Quest.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Obtaining a lens", needed = {},
                steps = {
                    {
                        text = "Leave the house and go east to the abandoned buildings.",
                        npcs = {},
                    },
                    {
                        text = "Climb down the stairs in the western building.",
                        npcs = {},
                    },
                    {
                        text = "Open and then search specific chests for a goblin kitchen key.",
                        npcs = { "goblin kitchen key" },
                        subs = {
                            { text = "Be sure to finish the dialogue after searching to receive the key." },
                            { text = "Every dead end will have a searchable chest. Head south (and slightly east) first and if the key is not found in the two chests directly south from the stairs, it is guaranteed to be in the far south-east chest in the dungeon." },
                        },
                    },
                    {
                        text = "Go back to the staircase at the entrance, but do not exit the dungeon.",
                        npcs = {},
                    },
                    {
                        text = "Go east, then north, and then head west until a guard is seen guarding a kitchen.",
                        npcs = {},
                    },
                    {
                        text = "Kill him or lure him away from the kitchen.",
                        npcs = {},
                    },
                    {
                        text = "Inspect the stove in the kitchen to receive lens mould.",
                        npcs = {},
                    },
                    {
                        text = "Return to the surface and talk to the professor.",
                        chat = "1 Talk about the Observatory Quest.",
                        npcs = {},
                    },
                    {
                        text = "Use the lens mould on the molten glass.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the professor.",
                        chat = "1 Talk about the Observatory Quest.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Go back to the abandoned building and climb down the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Head to the southern section and climb the stairs to the observatory.",
                        npcs = {},
                    },
                    {
                        text = "Watch the cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Go upstairs. Look through the telescope and identify which constellation is seen.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the professor and tell him which constellation was seen.",
                        chat = "1 Talk about the Observatory Quest. / ?",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
