                        npcs = {},
                    },
                    {
                        text = "Question 5 people around the abbey.",
                        npcs = {},
                        subs = {
                            { text = "Valerio - Musician outside the abbey (3 clues).", chat = "1 What were you singing about? / 1 You were singing about Sister Anna, weren't you? / 2 Where were you between Vespers and Compline yesterday? / 2 I can't tell you, sorry." },
                            { text = "Sister Elena, north of the cabbages, in the kitchen (3 clues).", chat = "2 Where were you between Vespers and Compline yesterday? / 2 What did you think of Sister Anna? / 4 Goodbye." },
                            { text = "Sister Cecilia, in the east-central room, the chapel (3 clues).", chat = "1 What are you rehearsing? / 1 No - could you tell me? / 2 Go on. / 3 Back to my other questions... / 2 Where were you between Vespers and Compline yesterday? / 4 Goodbye." },
                            { text = "Sister Catherina, in the chapel (2 clues).", chat = "1 Where were you between Vespers and Compline yesterday? / 1 I'd like that. / 1 What did you think of Sister Anna? / 1 What other applicant? / 2 I can't tell you, sorry. / 3 Goodbye." },
                            { text = "Feet (Sister Debora, once she stands up), on the 3rd floor of the clock tower on the northeast side, sticking out under the clock mechanism. Talk to her, then, operate the clock mechanism to show 12 o'clock. Afterwards, talk to her again (2 clues).", chat = "2 Where were you between Vespers and Compline yesterday? / 1 Where were you between Vespers and Compline yesterday? / 2 Tell me about the troubadour outside. / 2 What did you think of Sister Anna? / 3 Goodbye." },
                        },
                    },
                    {
                        text = "Return to Abbess Benita, select any suspect.",
                        chat = "1 I've finished investigating for now. / Any",
                        npcs = {},
