                        npcs = { "Wizard Cromperty" },
                    },
                    {
                        text = "Pick up five full pigeon cages from the back yard of the first house south of the north-western bank in Ardougne. There are three cages that will respawn immediately.",
                        npcs = { "Pigeon_cage_(full)" },
                    },
                    {
                        text = "Go to Port Khazard (teleport to Catherby and use a charter to Port Khazard or teleport to the Yanille lodestone, run east through town then north) and talk to Tindel Marchant on the southern pier.",
                        chat = "2 Ask about iron oxide. / 1 Ok, I'll do it!",
                        npcs = { "Port Khazard", "Tindel Marchant" },
