                        npcs = { "Gnormadium Avlafrim" },
                    },
                    {
                        text = "For each of the 8 gnome landing lights immediately east:",
                        npcs = { "gnome landing light" },
                        subs = {
                            { text = "Select the \"Search\" option on the gnome landing light to receive an uncut gem." },
                            { text = "Cut the gem. If you crush one talk to the gnome to buy a replacement..", chat = "4 I need new gem to fix the lights. / 1 Ok, here's 500 gold, I'll buy one." },
