    {
        key = "our_man_in_the_north", name = "Our Man in the North", wiki = "Our Man in the North/Quick guide",
        required = {},
        recommended = { "Level 100 Combat", "Combat gear and food", "Desert amulet 2 or above for teleport to Nardah, then run north east to Uzer Mastaba", "Pollnivneach Teleport scroll, Ring of slaying, or Slayer cape teleport to Sumona" },
        sections = {
