                },
            },
            {
                title = "The bloodline", needed = { "Combat gear and food, Pollnivneach Teleport, 1 free backpack space" },
                steps = {
                    {
                        text = "Go to the Grand Library of Menaphos in the Imperial district. The entrance is next to the deposit box (bank chest).",
                        npcs = { "Grand Library of Menaphos", "Menaphos Imperial district" },
                    },
                    {
                        text = "Talk to Kohnen the librarian, who is just north of the entrance.",
                        chat = "1 *whisper* I'm looking for a book.",
                        npcs = { "Kohnen the librarian" },
                    },
                    {
                        text = "Exit the Grand Library.",
                        npcs = {},
                    },
                    {
                        text = "Head north to talk to Commander Akhomet.",
                        chat = "1 Talk about Our Man in the North. / 2 Historical text and bloodlines.",
                        npcs = { "Commander Akhomet (Imperial)" },
                    },
                    {
                        text = "Head to Pollnivneach.",
                        npcs = { "Pollnivneach" },
                    },
                    {
                        text = "Speak to Aristarchus, who is north-west of the south magic carpet station.",
                        chat = "1 Talk about Our Man in the North",
                        npcs = { "Aristarchus" },
                    },
                    {
                        text = "You will have to fight four Menaphite Thugs.",
                        npcs = { "Menaphite thug (Our Man in the North)" },
                        subs = {
                            { text = "They are level 122 and fight using melee." },
                            { text = "You can hide behind Aristarchus if you need a safe spot and are using ranged/magic/necromancy." },
                        },
                    },
                    {
                        text = "Speak to Aristarchus again who will agree to meet you in the library.",
                        chat = "1 Talk about Our Man in the North",
                        npcs = {},
                    },
                    {
                        text = "Return to the Grand Library and speak to Aristarchus, who is south of the entrance inside the library.",
                        npcs = {},
                    },
                    {
                        text = "Go to Uzer Mastaba and enter the pyramid to trigger a cutscene. (fairy code DLQ)",
                        npcs = { "Uzer Mastaba" },
                    },
                    {
                        text = "After the cutscene, enter the pyramid once more and speak to Senliten.",
                        chat = "4 Talk about Our Man in the North. / 4 Ozan is Senliten's descendant? / 2 Where are you going with this?",
                        npcs = { "Senliten" },
                    },
                    {
                        text = "Go to Al Kharid and speak to Osman, who is in the throne room, south of the lodestone.",
                        npcs = { "Al Kharid", "Osman" },
                    },
                    {
                        text = "Speak to Emir Ali Mirza in front of the throne.",
                        chat = "1 Talk about Our Man in the North.",
                        npcs = { "Ali Mirza" },
                    },
                },
            },
            {
                title = "Tracking down Jabari", needed = { "Have the 'remove roofs' setting set to 'selectively' in your graphics settings" },
                steps = {
                    {
                        text = "Leave the Palace and head north-east to Dommik's Crafting Store.",
                        npcs = { "Dommik's Crafting Store" },
                        subs = {
                            { text = "Ignore the quest active area marked on the minimap." },
                        },
                    },
                    {
                        text = "Climb the stairs on the inside of the crafting store.",
                        npcs = {},
                    },
                    {
                        text = "Climb the ladder south of the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Follow these steps across the rooftops:",
                        npcs = {},
                        subs = {
                            { text = "Walk across the plank to the south." },
                            { text = "Slide down the awning to the south." },
                            { text = "Go through the building." },
                            { text = "Walk across the washing line (north-west from where you started)." },
                            { text = "Climb the ladder to the west." },
                            { text = "Talk to Jabari." },
                            { text = "Cross the planks to the west." },
                            { text = "Climb the ladder to the southwest." },
                            { text = "Jump from the scaffold to the west." },
                            { text = "Climb down the rug to the south." },
                            { text = "Swing across the wooden frame immediately west." },
                            { text = "Jump from the scaffold (west) to the next building." },
                            { text = "Bounce on the awning (south) to the bank." },
                            { text = "Climb up the brickwork to the west on the wall." },
                            { text = "Talk to Jabari." },
                            { text = "Parrot drop on the rug to the south." },
                            { text = "Do not shimmy across the rope." },
                            { text = "Run north of the bank, west of the furnace, and talk to Jabari." },
                            { text = "Run north-east of the Al Kharid lodestone into a tent, and talk to Jabari." },
                            { text = "Run north to the house near the north-east exit of Al Kharid, and talk to Jabari." },
                            { text = "You can get a free heal from the Surgeon General west of this house." },
                        },
                    },
                    {
                        text = "Go to Het's Oasis.",
                        npcs = { "Het's Oasis" },
                    },
                },
            },
            {
                title = "Fighting Jabari", needed = { "Combat equipment and food" },
                steps = {
                    {
                        text = "Prepare to battle Jabari four times. He is level 112 and uses magic. He has a weakness to slash.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Jabari.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Jabari will teleport you into the centre of the arena, surrounding you with his clones.",
                        npcs = {},
                        subs = {
                            { text = "Choosing the wrong Jabari will cause an explosion that damages the player and scales with level." },
                            { text = "Find the real Jabari by attacking the odd one out. As it is random for each player, it could be any of these:" },
                            { text = "The only one facing backwards." },
                            { text = "The only one in attack position." },
                            { text = "The one with the smallest sceptre." },
                            { text = "The largest one of them." },
                            { text = "The one targeted by the audience." },
                            { text = "The one with the correctly spelled name." },
                            { text = "The one with a different robe colour." },
                            { text = "The one without prayer renewal particles." },
                            { text = "The one who is not translucent." },
                        },
                    },
                    {
                        text = "Talk to Het.",
                        npcs = { "Het" },
                    },
                    {
                        text = "Talk to Emir Ali Mirza, in the Al Kharid throne room.",
                        chat = "1 Talk about Our Man in the North.",
                        npcs = { "Ali Mirza" },
                    },
                    {
                        text = "After the cutscene, talk to Emir Ali Mirza again.",
                        chat = "1 Talk about Our Man in the North.",
                        npcs = { "Ali Mirza" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
