    {
        key = "perils_of_ice_mountain", name = "Perils of Ice Mountain", wiki = "Perils of Ice Mountain/Quick guide",
        required = { "1 watering can (with water, magic watering can from tool belt works as well)", "1 Bucket of compost (or supercompost)", "2 Wooden planks (protean planks won't work)", "2 nails of any metal (Non-members must use steel nails or lower)" },
        recommended = { "Activated Falador and Edgeville lodestones", "Combat bracelet for faster teleport to Edgeville Monastery", "Skills necklace for teleports to Invention Guild near the dwarven mines" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to Lakki the delivery dwarf, who can be found to the east of the Invention Guild, north of Falador.",
                        chat = "1 What's the matter? / 1 I could help you find the crate. / Accept",
                        npcs = { "Lakki the delivery dwarf", "Falador" },
                    },
                },
            },
            {
                title = "Delivery", needed = {},
                steps = {
                    {
                        text = "Along the path west towards Falador are eight bushes you can search. Search each of them until a crate is found.",
                        npcs = {},
                        tile = { x = 2977, y = 3417, plane = 0 },
                    },
                    {
                        text = "Give the crate to Drorkar, who is in the Power Station west of the Dwarven Mines.",
                        chat = "1 Yes. / 2 Okay.",
                        npcs = { "Crate (Perils of Ice Mountain)", "Drorkar", "Power Station", "Dwarven Mine" },
                    },
                    {
                        text = "Head to the Edgeville Monastery (use the Edgeville lodestone to save time).",
                        npcs = { "Edgeville Monastery", "Edgeville lodestone" },
                    },
                    {
                        text = "Give the letter to Brother Bordiss in the garden.",
                        chat = "1 I have a letter for you.",
                        npcs = { "Letter (Perils of Ice Mountain)", "Brother Bordiss" },
                    },
                    {
                        text = "Talk to Brother Althric.",
                        chat = "2 Can I help? / 1 I'll go and get some compost.",
                        npcs = { "Brother Althric" },
                    },
                    {
                        text = "Use compost on the dying roses, then water them. If your watering can is empty, you may use the fountains in the monastery to fill it.",
                        npcs = { "compost" },
                    },
                },
            },
            {
                title = "Ice Mountain", needed = {},
                steps = {
                    {
                        text = "Talk to Professor Arblenap (the gnome) half way up to the top of Ice Mountain.",
                        chat = "1 What are you doing? / 2 Can I help?",
                        npcs = { "Professor Arblenap", "Ice Mountain" },
                    },
                    {
                        text = "Wield the icefiend net and catch the four baby icefiends.",
                        npcs = { "icefiend net", "baby icefiend" },
                    },
                    {
                        text = "Talk to Professor Arblenap.",
                        npcs = { "Professor Arblenap" },
                    },
                    {
                        text = "Talk to the Oracle, who is just north on the mountain.",
                        chat = "1 What happened to your tent? / 1 I could fix your tent for you.",
                        npcs = { "Oracle" },
                    },
                    {
                        text = "Take the wrecked tent from the base of the mountain, south of the Black Knights' Fortress entrance and east of the Oracle. It does not appear as a red dot on the minimap.",
                        npcs = { "Black Knights' Fortress", "Oracle" },
                    },
                    {
                        text = "With the tent, two planks, and two nails, use the tent on the remains atop the mountain, next to the Oracle.",
                        npcs = { "tent", "planks", "nails" },
                    },
                    {
                        text = "Continue dialogue with the Oracle.",
                        chat = "5 I'm going to go and do something.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing Up", needed = {},
                steps = {
                    {
                        text = "Talk to Drorkar at the Power Station.",
                        chat = "1 You've got to shut down this power station. / 4 The Oracle predicted it would cause the end of civilisation! / 4 I'll go and talk to Nurmof, then.",
                        npcs = { "Drorkar", "Power Station" },
                    },
                    {
                        text = "Pickpocket Drorkar for a Dwarven key.",
                        npcs = { "Dwarven key" },
                    },
                    {
                        text = "Go in the Dwarven Mines and talk to Nurmof in the north-western corner of the mines, at the pickaxe shop.",
                        chat = "4 You've got to shut down the power station! / 1 What was this other power source? / 3 Goodbye.",
                        npcs = { "Nurmof" },
                    },
                    {
                        text = "Talk to Brother Bordiss at the Edgeville Monastery.",
                        chat = "1 Nurmof says you made plans for an alternative power station.",
                        npcs = { "Brother Bordiss", "Edgeville Monastery" },
                    },
                    {
                        text = "Head back down into the Dwarven Mines, then immediately east into a small alcove.",
                        npcs = { "Map:Dwarven Mine" },
                    },
                    {
                        text = "Open the small, bright chest against the north wall.",
                        npcs = { "Chest (Perils of Ice Mountain)" },
                    },
                    {
                        text = "Return to the pickaxe shop and talk to Nurmof.",
                        chat = "4 You've got to shut down the power station. / 1 I have the plans to the alternative power station here.",
                        npcs = { "Nurmof" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
