                    {
                        text = "After the cutscene, dive off the pier.",
                        npcs = {},
                    },
                    {
                        text = "Speak to anyone. This is the first point where you can leave the quest and save progress.",
                        chat = "Any / 1 Yes.",
                        npcs = {},
                    },
                },
