            {
                title = "Finding a friend", needed = { "2 pieces of leather, 1 gold bar, 1 free inventory space" },
                steps = {
                    {
                        text = "Sit in the chair in the north-east corner of Harpoon Joe's House of 'Rum'.",
                        chat = "1 A Long Drop.",
                        npcs = { "Harpoon Joe's House of 'Rum'" },
                    },
                    {
                        text = "Speak to the Zombie pirate head.",
                        chat = "Any / 2 [Kind interrogation.] / 3 Maybe we can come to an arrangement. / Any / 1 Deal.",
                        npcs = { "Zombie pirate head" },
                    },
                    {
                        text = "Go to the west of Varrock and speak to Gertrude in her house. (or if completed Rat Catchers)",
