                    {
                        text = "Talk to Philop or Kanel inside Gertrude's house.",
                        npcs = { "Philop", "Kanel" },
                    },
                    {
                        text = "Go to the abandoned house northwest of the apothecary in south-west Varrock and search the jiggling crate to find Wilson.",
                        chat = "1 Yes - I fear nothing. / 1 Yes - it's probably fine.",
                        npcs = { "apothecary" },
                    },
                },
            },
            {
                title = "Seeing the sunset", needed = { "Blurberry special, Drunk dragon, Chocolate saturday" },
                steps = {
                    {
                        text = "Travel to the Karamja lodestone and head south to the beach just north of Jiminua's Jungle Store; the head will tell you to stop.",
