            {
                title = "Zogoth", needed = { "Combat gear" },
                steps = {
                    {
                        text = "Prepare for combat. Return to Harpoon Joe's House of 'Rum' and return to the Interrogation Room by sitting in the north-east chair.",
                        chat = "1 A Long Drop.",
                        npcs = { "Harpoon Joe's House of 'Rum'" },
                    },
                    {
                        text = "When ready for the fight, head south-west of Harpoon Joe's House of 'Rum' and row the rowboat.",
                        chat = "1 Yes!",
                        npcs = {},
                    },
                    {
                        text = "Enter the door to the south.",
                        npcs = {},
                    },
                    {
                        text = "Kill all four tentacles; a cutscene follows.",
                        npcs = {},
                    },
                    {
                        text = "Kill Zogoth; a cutscene follows.",
                        npcs = { "Zogoth" },
                        subs = {
                            { text = "Stay within melee range to avoid a typeless damage attack from the tentacles." },
                            { text = "Move away from the water jet attack to avoid being pushed to the back of the boat." },
                            { text = "Move away from shadows when Zogoth shields itself to avoid acid spray attacks (occurs at 50% and 25% health). The acid will follow you around until the attack ends." },
                        },
                    },
                },
            },
            {
                title = "Rabid Jack's invasion", needed = { "Combat gear" },
                steps = {
                    {
                        text = "Once on Mos Le'Harmless, during Rabid Jack's Invasion, the player must clear two waves of enemies.",
                        npcs = {},
                    },
                    {
                        text = "Wave 1 (initial attack):",
                        npcs = {},
                        subs = {
                            { text = "Kill the barrelchest and zombie captains at the main gate to the north and repair the barricades." },
                            { text = "Kill the zombie captains up the ramp (on the western wall), then help up the pirate on the wall." },
                            { text = "Kill the zombie captains at the south-east coast of the town, then repair the cannons and sink the zomboats." },
                            { text = "Kill the zombie captains at the south-west coast of the town, then repair the cannons and sink the zomboats." },
                        },
                    },
                    {
                        text = "Wave 2 (next attack):",
                        npcs = {},
                        subs = {
                            { text = "Kill the DKS and the zombie captains at the main gate and repair the barricades." },
                            { text = "Kill the zombie captains up the ramp (on the western wall), then help up the pirate on the wall." },
                            { text = "Kill the zombie captains at the south-east coast of the town, then repair the cannons and sink the zomboats." },
                            { text = "Kill the zombie captains at the south-west coast of the town, then repair the cannons and sink the zomboats." },
                            { text = "Kill the zombie captains at river east of the town, then destroy the makeshift bridges." },
                            { text = "Kill the DKS and the zombie captains at the wheat field north of the town, then destroy the cannon." },
                            { text = "Kill the DKS and the zombie captains at the coast north-west of the town, then destroy the grounded ship. This should be done last." },
                        },
                    },
                    {
                        text = "Finish the conversation with the pirates in the invasion. You will not be able to progress without doing so.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Braindeath Island", needed = { "Four free backpack spaces" },
                steps = {
                    {
                        text = "Head to Braindeath Island via Pirate Pete north of Port Phasmatys. You can also use the pirate spell sheet or Dungeoneering cape.",
                        chat = "1 Travel to Braindeath Island (Pieces of Hate). / 1 Braindeath Island / 1 Travel to Braindeath Island (Pieces of Hate). / 8 Braindeath Island / 1 Travel to Braindeath Island (Pieces of Hate).",
                        npcs = { "Braindeath Island", "Pirate Pete", "Port Phasmatys", "Dungeoneering cape" },
                    },
                    {
                        text = "Head south, and down the wooden stairs. Run west along the building and up the wooden stairs on the west of the bunkroom.",
                        npcs = {},
                    },
                    {
                        text = "Head through the bunkroom to the east side, then north-east. Listen at the window to the room with Captain Braindeath.",
                        npcs = {},
                    },
                    {
                        text = "After the dialogue, head back to the bunkroom, and talk to Davey.",
                        npcs = { "Davey" },
                    },
                    {
                        text = "Head down the wooden stairs, put on the barrelchest disguise then talk to Captain Donnie south-east.",
                        chat = "3 Mi-Gor is in need of some witchwood.",
                        npcs = { "Barrelchest disguise (Pieces of Hate)", "Captain Donnie" },
                    },
                    {
                        text = "Head up the nearby wooden stairs, and talk to the Barrelchest Mk I.",
                        npcs = { "Barrelchest Mk I" },
                    },
                    {
                        text = "Return to Captain Donnie again to learn the passphrase",
                        chat = "2 Mi-Gor wants to see you right now!",
                        npcs = {},
                    },
                    {
                        text = "Head back up the wooden stairs, and once again talk with the Barrelchest Mk I.",
                        chat = "5 'How appropriate. You fight like a zombie sea cow.'",
                        npcs = {},
                    },
                    {
                        text = "Remove the disguise, for speed.",
                        npcs = {},
                    },
                    {
                        text = "Climb the ladder in the south-east corner of the building.",
                        npcs = {},
                    },
                    {
                        text = "Head west, and take the Barrels of 'rum' from on top of the crate, head north and do the same again.",
                        npcs = { "Barrels of 'rum'" },
                    },
                    {
                        text = "Block the pressure barrel (just south-east of the second of the barrels of 'rum'), then overload the pressure lever beside it.",
                        npcs = {},
                    },
                    {
                        text = "Return down the ladder, and then the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Head north-west and pass through the gate by 66.6...% Luke.",
                        npcs = { "66.6...% Luke" },
                        subs = {
                            { text = "You cannot use the dungeoneering cape teleport here to get to the north of the island." },
                        },
                    },
                    {
                        text = "Head north, up the mountain to the pool (marked with on the minimap) and investigate the perch rock.",
                        npcs = {},
                    },
                    {
                        text = "Baron von Hattenkrapper will appear. Complete the dialogue, then select Unleash!",
                        chat = "1 Unleash!",
                        npcs = { "Baron von Hattenkrapper" },
                    },
                    {
                        text = "Guide Baron von Hattenkrapper and hit the mysterious entrance to the south-west 3 times; a cutscene follows.",
                        npcs = {},
                    },
                    {
                        text = "Talk with Mi-Gor, and set sail.",
                        npcs = { "Mi-Gor" },
                    },
                },
            },
            {
                title = "Underwater", needed = { "Combat gear" },
                steps = {
                    {
                        text = "Head south and equip gear from the crate of diving gear, then head north and dive into the cracked hull.",
                        npcs = {},
                    },
                    {
                        text = "Head south-west, and jump off the edge.",
                        npcs = {},
                    },
                    {
                        text = "Head south, then west, then north to the shimmering barrier.",
                        npcs = {},
                        subs = {
                            { text = "EPILEPSY WARNING: If you suffer from epilepsy, talk to the shimmering kitten to prevent aggravating symptoms." },
                            { text = "You need to prepare for combat for the next part." },
                        },
                    },
                    {
                        text = "If well-prepared for combat, pass through the shimmering barrier; a cutscene follows.",
                        npcs = {},
                        subs = {
                            { text = "Note: If you choose to re-gear use the rowboat in the south-west of Mos Le'Harmless to get back to the temple." },
                        },
                    },
                },
            },
            {
                title = "Rabid Jack fight", needed = {},
                steps = {
                    {
                        text = "Reduce Jack's health to 0.",
                        npcs = {},
                        subs = {
                            { text = "Stand at the north, south, west, east walls or doorway to avoid being damaged and stunned by the black hand in the centre of the room." },
                            { text = "Use Freedom or Anticipation if stunned by Jack's stun attack. Avoid running from Jack to reduce the frequency of this attack." },
                            { text = "Drink 'rum' from barrels in the room to reduce \"insanity\". Insanity is indicated by the black cat debuff icon and will cause Jack hallucinations to spawn and the camera to spin if it becomes too high. Drink as soon as the debuff icon appears." },
                            { text = "If you die you can return to fight Rabid Jack by travelling back to Mos Le'Harmless and taking the small rowboat." },
                        },
                    },
                    {
                        text = "Loosen an ancient chain.",
