    {
        key = "player_owned_farm_tutorial", name = "Player-owned farm tutorial", wiki = "Player-owned farm tutorial/Quick guide",
        required = {},
        recommended = {},
        sections = {
            {
                title = "Walkthrough", needed = {},
                steps = {
                    {
                        text = "Start the tutorial by talking with Granny Potterington in front of her house at the centre of the farm.",
                        npcs = { "Granny Potterington" },
                    },
                    {
                        text = "Pick up Jack the yak from behind the farmhouse and talk to Granny.",
                        npcs = { "Jack the yak" },
                    },
                    {
                        text = "Sell Jack to Prezleek (yak trader), located beside the well in front of the house (gain 500 beans).",
                        npcs = { "Jack the yak (item)", "Prezleek (yak trader)", "beans" },
                    },
                    {
                        text = "Add the beans to the currency pouch.",
                        npcs = {},
                    },
                    {
                        text = "Buy a small animal pen kit (tutorial) from the Farmers' Market (right-click \"Farmers' Market\" on Granny; costs 100 beans).",
                        npcs = { "small animal pen kit (tutorial)", "Farmers' Market" },
                    },
                    {
                        text = "Buy two rabbits from the market and check each of them in the inventory (cost 10 beans each).",
                        npcs = { "common brown rabbit (tutorial)" },
                    },
                    {
                        text = "Build the small pen (click \"build\" on the broken paddock (small)) and place the two rabbits inside (click \"check animals\" or use the common brown rabbit on small paddock).",
                        npcs = {},
                    },
                    {
                        text = "Check the rabbits by clicking on them in the pen and click \"cure disease\". Then investigate all options and choose \"administer treatment\". Click flu.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Granny to get fruity mush and return to pen to 'fill trough' and head back to Granny.",
                        npcs = { "fruity mush" },
                    },
                    {
                        text = "Pass the time with her until the rabbits have matured; talk until option to advance time or wait 22 minutes.",
                        npcs = {},
                    },
                    {
                        text = "Take the two rabbits out of the pen. (Optionally \"gather produce\" for 275 Farming experience (137.5 each))",
                        npcs = {},
                    },
                    {
                        text = "Talk to Granny to get more fruity mush.",
                        npcs = {},
                    },
                    {
                        text = "Bring the rabbits to the breeding pen behind the main farmhouse. Click \"check animals\" on the breeding paddock or use the rabbit on it.",
                        npcs = {},
                    },
                    {
                        text = "Fill trough. Soon a child bunny will appear (or talk to Granny to advance time until this happens).",
                        npcs = {},
                    },
                    {
                        text = "Talk to Granny to complete the tutorial.",
                        npcs = {},
                    },
                },
            },
        },
    },
