    {
        key = "quiet_before_the_swarm", name = "Quiet Before the Swarm", wiki = "Quiet Before the Swarm/Quick guide",
        required = {},
        recommended = { "Quick method of travelling to Void Knights' Outpost, e.g. Void familiar (with Void scrolls (Call to Arms)), or to Port Sarim via the Captain's log, or Explorer's ring 3 or 4.", "Falador teleport runes (1 law rune, 1 water rune, 3 air runes) or tablet or teleport to the Falador lodestone", "Have no items equipped or in your inventory (You will be required to bank everything during the quest.)" },
        sections = {
            {
                title = "Starting", needed = {},
                steps = {
                    {
                        text = "Speak to Sir Tiffy Cashien in the Falador Park about the void knights.",
                        chat = "1 Void Knights. / Accept",
                        npcs = { "Sir Tiffy Cashien", "Falador Park" },
                        subs = {
                            { text = "Or, if Slug Menace isn't complete", chat = "2 Void Knights. / Accept" },
                        },
                    },
                    {
                        text = "Go to the Void Knights' Outpost.",
                        npcs = { "Void Knights' Outpost" },
                        subs = {
                            { text = "To get there, speak to the Squire on the pier at Port Sarim to travel to the island by ship free of charge.", chat = "3 I'd like to go to your outpost." },
                        },
                    },
                    {
                        text = "Speak to Commodore Matthias in the north-east building.",
                        npcs = { "Commodore Matthias" },
                    },
                    {
                        text = "Talk to Captain Tyr just south of the building.",
                        npcs = { "Captain Tyr" },
                    },
                    {
                        text = "Talk to the following people about escaping pests:",
                        npcs = {},
                        subs = {
                            { text = "Knight Ami", chat = "4 That's all, thanks." },
                            { text = "Knight Bernard", chat = "3 Have you heard anything about pests escaping? / 4 That's all, thanks." },
                            { text = "Knight Diana", chat = "3 Have you heard anything about pests escaping? / 4 That's all, thanks." },
                            { text = "Knight Mikhal", chat = "3 Have you heard anything about pests escaping? / 4 That's all, thanks." },
                            { text = "Jessika", chat = "4 Have you heard anything about pests escaping? / 5 That's all, thanks." },
                            { text = "Mariah", chat = "4 That's all, thanks." },
                            { text = "Mrs Gord", chat = "3 Have you heard anything about pests escaping? / 4 That's all, thanks." },
                            { text = "Squire Sam", chat = "1 Ask about escaped pest. / 2 That's all, thanks." },
                            { text = "Terry Gord", chat = "3 Have you heard anything about pests escaping? / 4 That's all, thanks." },
                        },
                    },
                },
            },
            {
                title = "The accused", needed = {},
                steps = {
                    {
                        text = "Talk to Captain Tyr.",
                        npcs = { "Captain Tyr" },
                    },
                    {
                        text = "Talk to Jessika about the crimes she has committed.",
                        chat = "5 Confront about a crime. / 3 You let a pest escape to the mainland.",
                        npcs = { "Jessika" },
                    },
                    {
                        text = "Talk to Captain Tyr.",
                        npcs = { "Captain Tyr" },
                    },
                    {
                        text = "Talk to Commodore Matthias.",
                        npcs = { "Commodore Matthias" },
                    },
                    {
                        text = "Agree during the cutscene.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Inside Jessika's mind", needed = {},
                steps = {
                    {
                        text = "Solve the 3x3 slider puzzle. The border helps you find their correct positions.",
                        npcs = {},
                        subs = {
                            { text = "The centre piece will appear when you have placed the border pieces." },
                        },
                    },
                    {
                        text = "Watch the cutscene and continue the dialogue with Commodore Mathias.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Arresting Jessika", needed = {},
                steps = {
                    {
                        text = "Bank all your items, both equipped and in your inventory. Dismiss any pets or familiars.",
                        npcs = {},
                    },
                    {
                        text = "Return to Sir Tiffy and talk about Void Knights.",
                        chat = "1 Void Knights.",
                        npcs = { "Sir Tiffy" },
                        subs = {
                            { text = "Or, if Slug Menace isn't complete", chat = "2 Void Knights." },
                        },
                    },
                },
            },
            {
                title = "Bridge and the sword", needed = {},
                steps = {
                    {
                        text = "Talk to Commander Korasi.",
                        chat = "1 Yes.",
                        npcs = { "Commander Korasi" },
                    },
                    {
                        text = "Talk to the toll booth to start the puzzle.",
                        chat = "2 What do I need to do?",
                        npcs = {},
                    },
                    {
                        text = "Complete the puzzle:",
                        npcs = {},
                        subs = {
                            { text = "Talk to Bernard and cross with him.", chat = "1 I'll cross with you." },
                            { text = "Talk to the toll booth to send yourself over.", chat = "1 Send someone over the bridge. / 1 Yourself" },
                            { text = "Talk to Ami or Diana and have them cross together.", chat = "2 You cross with [Diana/Ami]." },
                            { text = "Talk to the toll booth to send Bernard over.", chat = "1 Send someone over the bridge. / 1 Bernard" },
                            { text = "Talk to Bernard and cross with him.", chat = "1 I'll cross with you." },
                        },
                    },
                },
            },
            {
                title = "Ship positions", needed = {},
                steps = {
                    {
                        text = "Right-click assign the people to the following:",
                        npcs = {},
                    },
                    {
                        text = "Completing the puzzle correctly triggers a cutscene.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The Pests' attack", needed = {},
                steps = {
                    {
                        text = "Ensure that \"Auto Attack\" is enabled in the \"Combat Mode\" settings, or use Revolution or Classic combat mode. Otherwise, this section cannot be completed. If you become stuck, close your client and wait for your character to log out.",
                        npcs = {},
                    },
                    {
                        text = "Kill the torcher.",
                        npcs = { "torcher" },
                    },
                    {
                        text = "Go up the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Kill the shifter and wait for another cutscene.",
                        npcs = { "shifter" },
                    },
                    {
                        text = "Once teleported, talk to Sir Tiffy.",
                        npcs = { "Sir Tiffy" },
                    },
                    {
                        text = "Speak with Captain Tyr at the Void Knights' Outpost.",
                        npcs = { "Captain Tyr", "Void Knights' Outpost" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "rag_and_bone_man", name = "Rag and Bone Man", wiki = "Rag and Bone Man/Quick guide",
        required = { "About 40 coins", "8 empty pots (pots can be reused)", "8 core logs of any type (can be collected during quest, eternal magic logs does not work)", "Any light source", "A rope (needed to get into Lumbridge Swamp Cave if you haven't placed a rope there before, unless you have started The Lost Tribe)" },
        recommended = { "Spiny helmet or slayer helmet", "Candle lantern or bullseye lantern", "Energy-enhancing items", "Teleport methods to Varrock, and Falador", "Explorer's ring 3 or 4 for quick access to Draynor Village (Cabbage-port)", "Invitation box for quick access to the Odd Old Man", "If not owned, use the Fort Forinthry lodestone or the earth altar teleport.", "Yanille lodestone activated if not Spirit tree (in order to go to Yanille)", "1 law rune and 1 air rune for Telekinetic Grab if killing a monkey in Ardougne Zoo." },
        sections = {
            {
                title = "Getting started", needed = { "one or more empty pots (can be reused)" },
                steps = {
                    {
                        text = "Talk to the Odd Old Man in Silvarea.",
                        chat = "1 Anything I can do to help? / Accept",
                        npcs = { "Odd Old Man", "Silvarea" },
                    },
                    {
                        text = "Go to Draynor Village market and talk to Fortunato about the quest (do not steal from the stalls before talking to him, as you won't be able to initiate the conversation for a couple of minutes).",
                        npcs = { "Draynor Village", "Fortunato" },
                    },
                    {
                        text = "Buy 8 jugs of vinegar.",
                        npcs = { "jug of vinegar" },
                    },
                    {
                        text = "Use the jugs of vinegar on your empty pots.",
                        npcs = { "empty pot" },
                    },
                    {
                        text = "Gather and use each bone listed below on the pots of vinegar.",
                        npcs = { "Pot of vinegar" },
                    },
                },
            },
            {
                title = "Obtaining the Bones", needed = {},
                steps = {
                    {
                        text = "Obtain the bones. Use the table below as a reference.",
                        npcs = {},
                        subs = {
                            { text = "Goblin — * East of the River Lum in Lumbridge * Near the Draynor lodestone and the Wizard's Tower * East of Barbarian Village and south-west of the Grand Exchange * Stronghold of Security * Goblin Village * Port Sarim * By the Coal truck mine and Hemenster * Goblin Cave * Around the Varrock Dig Site * God Wars Dungeon" },
                            { text = "Bear and Black bear — * Directly east of the Captured Temple * South of the Mind altar * Legends' Guild south-west mine (Fairy ring code BLR) * South of the fruit tree patch by the Tree Gnome Village * East of Rellekka" },
                            { text = "Big Frog — * Inside of the Lumbridge Swamp Caves in the area in the south-east corner * Dorgesh-Kaan South Dungeon (fairy ring code AJQ)" },
                            { text = "Ram — * Fred the Farmer's pen, north of Lumbridge * Near the Wilderness wall, north of the Edgeville Monastery * South-west of Falador * In the Fisher Realm (Fairy ring code BJR)" },
                            { text = "Unicorn and black unicorn — * South of Seers' Village * South of Yanille * Ardougne Zoo (fairy ring code BIS) * East of Rellekka * Varrock south-east mine * South of Wilderness Crater" },
                            { text = "Monkey — * North of Karamja lodestone * East of Karamja Volcano * Ardougne Zoo (must have level 33 Magic for Telekinetic Grab) * Mos Le'Harmless" },
                            { text = "Giant rat — * Stronghold of Security * Behind the Dancing Donkey Inn in south-east Varrock * Varrock sewers * South-west of Port Sarim * Behind Lumbridge Castle and Lumbridge swamp * In the pen south of Varrock * Edgeville dungeon" },
                            { text = "Giant bat — * Yanille Dungeon * Legends' Guild basement * Heroes' Guild basement * Coal truck mine * Temple of Ikov * Goblin Cave * Taverley Dungeon * Chaos Druid Tower dungeon" },
                        },
                    },
                },
            },
            {
                title = "Finishing up", needed = { "8 core logs of any type (eternal magic logs does not work)" },
                steps = {
                    {
                        text = "Go back to the Odd Old Man's hut.",
                        npcs = {},
                    },
                    {
                        text = "Add logs, then a pot of bones to the pot boiler, and light it. Collect the bone when it finishes boiling after 12 seconds (hopping worlds will skip the boiling).",
                        npcs = { "pot boiler", "worlds" },
                    },
                    {
                        text = "Repeat for the remaining bones.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Odd Old Man.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "raksha_the_shadow_colossus_quest", name = "Raksha, the Shadow Colossus (quest)", wiki = "Raksha, the Shadow Colossus (quest)/Quick guide",
        required = {},
        recommended = { "Slayer cape or Slayer master cape (to teleport to Laniakea)", "Some food (if you have less than 1000 life points)" },
        sections = {
            {
                title = "Walkthrough", needed = {},
                steps = {
                    {
                        text = "Talk to Laniakea, south-east in the ruins on Anachronia.",
                        chat = "2 The doorway at the top of the ruins. / Accept / 1 Zaros? / 3 Can we open the door somehow?",
                        npcs = { "Laniakea", "Anachronia" },
                        subs = {
                            { text = "She is also at the ruins around the lodestone but she tells you to go to the south-east and talk to her there." },
                            { text = "You can use option 2 on the Slayer cape to get to her quickly or teleport to Xolo City via the Orthen teleportation device, then run south-east." },
                        },
                    },
                    {
                        text = "Run west, up to the top of the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Siphon the shadow anima pools until you reach 100%.",
                        npcs = {},
                        subs = {
                            { text = "Completing each pool will damage you 200 points. Be aware of that in case you are on low life points." },
                        },
                    },
                    {
                        text = "Unlock the door.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Zaros.",
                        npcs = {},
                    },
                    {
                        text = "Talk to The Keeper",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "Raksha, the Shadow Colossus (quest achievement)",
                        npcs = { "Raksha, the Shadow Colossus (quest achievement)" },
                    },
                },
            },
        },
    },
    {
        key = "rat_catchers", name = "Rat Catchers", wiki = "Rat Catchers/Quick guide",
        required = { "Cat or hellcat", "A kitten works, but it catches rats very slowly and needs to be fed. An overgrown cat does not work.", "Your cat may die on this quest.", "1 rat poison (can be found in the Clock Tower Dungeon)", "Alternatively the ingredients to make it during the quest are:", "1 vial (must be empty)", "1 clean kwuarm (if needed, Zahur in Nardah cleans grimy herbs for 200 coins)", "1 red spiders' eggs", "4 cheese", "1 unicorn horn dust", "1 clean marrentill (if needed, Zahur in Nardah cleans grimy herbs for 200 coins)", "1 bucket of milk", "1 catspeak amulet (or cramulet containing a catspeak amulet)", "1 pot of weeds (use an empty pot with weeds)", "About 600 coins (about 300 with ring of charos (a))", "Snake charm (can be obtained during quest if not already in bank)" },
        recommended = { "About 2-10 raw or cooked fish or buckets of milk for your cat or kitten during the fight.", "Your cat may die without this", "Raw is preferred to avoid accidentally eating cooked ones", "The type of fish does not matter. All completely heal your cat or kitten the same amount.", "When talking to the NPCs, you may want to wear your catspeak amulet and have your cat out, as this results in more interesting conversations.", "Pollnivneach Teleport or coins for magic carpet", "A desert amulet 2 or having a player-owned house in Pollnivneach (with House Teleport) can also help." },
        sections = {
            {
                title = "Starting out", needed = { "a cat, hellcat or kitten, 1 backpack space" },
                steps = {
                    {
                        text = "Talk to Gertrude, in her house west of Varrock.",
                        chat = "3 Talk about the 'Ratcatchers' quest. / Accept",
                        npcs = { "Gertrude" },
                        subs = {
                            { text = "If you have a Hellcat out", chat = "4 Talk about the 'Ratcatchers' quest. / Accept" },
                        },
                    },
                    {
                        text = "Take out your cat or kitten.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Phingspet or Grimesquit in the Varrock Sewers right next to the eastern entrance of Varrock Palace (down the manhole).",
                        npcs = { "Phingspet", "Grimesquit", "Varrock Sewers", "Varrock Palace", "manhole" },
                    },
                    {
                        text = "Catch 8 rats with your cat or kitten by choosing the \"interact-with\" option.",
                        chat = "2 Chase-Vermin.",
                        npcs = {},
                        subs = {
                            { text = "The \"Hide familiar options\" setting must be off in the Gameplay settings." },
                        },
                    },
                    {
                        text = "Talk to them again to obtain a rat pole.",
                        npcs = { "rat pole" },
                    },
                },
            },
            {
                title = "Just the ticket", needed = { "1 free inventory space" },
                steps = {
                    {
                        text = "Talk to Jimmy Dazzler in the house in East Ardougne, directly west of the Flying Horse Inn, north-west of the Ardougne Castle. Ensure you finish the dialogue, or you will not be able to follow the next step.",
                        npcs = { "Jimmy Dazzler", "East Ardougne", "Flying Horse Inn", "Ardougne Castle" },
                    },
                    {
                        text = "Read the \"directions\" scroll he gives you.",
                        chat = "1 Follow the directions to the house.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Breaking in", needed = { "cat, rat pole" },
                steps = {
                },
            },
            {
                title = "Going through the garden", needed = {},
                steps = {
                    {
                        text = "Avoid guards whilst traversing throughout. You can use Surge or Dive to navigate quickly.",
                        npcs = { "Surge", "Dive" },
                    },
                    {
                        text = "Hide behind the hedges directly west of the mansion when the southwest guard walks toward the bridge.",
                        npcs = {},
                    },
                    {
                        text = "Run to the north-west corner when the guard is behind the hedges.",
                        npcs = {},
                    },
                    {
                        text = "Run to the hedges directly north of the mansion.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the nearby trellis on the northern of the mansion.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Catching the rats", needed = {},
                steps = {
                    {
                        text = "Once inside continue to avoid guards. You can hide by the potted flower on the balcony first.",
                        npcs = {},
                    },
                    {
                        text = "Wield your rat pole.",
                        npcs = {},
                    },
                    {
                        text = "Catch 1 rat with your cat in the north-west room. You may pick up your cat to prevent stuck outside.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Find your way into the opposite bedroom across the hall and wait (or wait for one guard to be on the balcony and the second have his back appropriately turned to dash to the next room).",
                        npcs = {},
                    },
                    {
                        text = "Catch 2 rats with your cat in the south-east room.",
                        chat = "1 Yes. / 1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Go down the ladder in the north-east of this room.",
                        npcs = {},
                    },
                    {
                        text = "Catch 3 rats with your cat in this room and the room to the north.",
                        chat = "1 Yes. / 1 Yes. / 1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Leave the area by using Home Teleport to Ardougne lodestone.",
                        npcs = { "Home Teleport", "Ardougne lodestone" },
                        subs = {
                            { text = "You can also return to the trellis and climb down it to return directly to Jimmy." },
                        },
                    },
                    {
                        text = "Talk to Jimmy Dazzler.",
                        npcs = {},
                        subs = {
                            { text = "You can destroy your directions scroll now." },
                        },
                    },
                },
            },
            {
                title = "Hooknosed Jack", needed = { "a cat, 4 pieces of cheese, a bucket of milk, clean marrentill, unicorn horn dust, rat poison (alternatively, clean kwuarm, red spiders eggs and an empty vial), 5-10 raw or cooked fish for your cat (even if you're using a fully grown cat)" },
                steps = {
                    {
                        text = "Talk to Hooknosed Jack in south-east Varrock, inside the fenced area past the guard.",
                        npcs = { "Hooknosed Jack" },
                    },
                    {
                        text = "If you need to make the rat poison and do not have the ingredients (clean kwuarm, red spiders eggs and an empty vial) in the backpack on the first talk, talk to him again.",
                        chat = "1 Can you make me some rat poison?",
                        npcs = { "rat poison" },
                    },
                    {
                        text = "Climb up the ladder in the warehouse directly south of the Dancing Donkey Inn.",
                        npcs = { "Dancing Donkey Inn" },
                    },
                    {
                        text = "Use rat poison on all 4 pieces of cheese.",
                        npcs = {},
                    },
                    {
                        text = "Use poisoned cheese on all of the rat holes.",
                        npcs = { "poisoned cheese", "rat hole" },
                    },
                    {
                        text = "Talk to Hooknosed Jack.",
                        chat = "2 Can I help?",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Apothecary in south-western Varrock for cat antipoison.",
                        chat = "5 I need to talk to you about cats.",
                        npcs = { "Apothecary", "cat antipoison" },
                        subs = {
                            { text = "If the first option is not 'Can you make a strength potion?',", chat = "# Talk about something else. / 5 I need to talk to you about cats." },
                        },
                    },
                    {
                        text = "Talk to Hooknosed Jack. Finish the dialogue or you will not be able to progress.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the ladder in the warehouse.",
                        npcs = {},
                    },
                    {
                        text = "Pick up your cat and use it on the hole in wall (not the rat holes). Make sure you finish the dialogue to start the fight, life points bars appear.",
                        chat = "1 Yes / 1 Be careful in there, cat!",
                        npcs = { "hole in wall" },
                    },
                    {
                        text = "Keep using fish on the hole in wall (not on the cat) to restore the cat's life points until the king rat dies.",
                        npcs = {},
                        subs = {
                            { text = "If you lose your cat by going down the ladder, exit to lobby out and join the world should return it to you." },
                            { text = "If you are in a group or have lootshare active, then the kill will not register and you will need to go down the ladder to reset the king rat." },
                        },
                    },
                    {
                        text = "You may retrieve your cat by calling your follower or by climbing down the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Jack to tell him the king rat is dead.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Smokin' Joe", needed = { "a cat, a catspeak amulet, an empty pot, weeds" },
                steps = {
                    {
                        text = "Talk to Smokin' Joe in east Keldagrim, just east of the mining shop.",
                        chat = "1 I could help you.",
                        npcs = { "Smokin' Joe", "Keldagrim", "Pickaxe-Is-Mine" },
                    },
                    {
                        text = ": If this is your first time entering Keldagrim proceed with the following route:",
                        npcs = {},
                        subs = {
                            { text = "Enter the tunnel north-east of Rellekka and Fremennik Province lodestone." },
                            { text = "Go-through the cave entrance between the two dwarven statues." },
                            { text = "Talk to the Dwarven Boatman and get him to take you into Keldagrim, this may cause you to automatically start the quest The Giant Dwarf." },
                            { text = "Proceed to the east part of Keldagrim and talk with Smokin' Joe." },
                        },
                    },
                    {
                        text = "Use some weeds on an empty pot and light the pot of weeds.",
                        npcs = { "pot of weeds" },
                    },
                    {
                        text = "Use the smouldering pot on the rat hole near the crates on the southern wall.",
                        npcs = { "smouldering pot" },
                    },
                    {
                        text = "Use the pot on the same hole again with your cat out and your catspeak amulet on, your cat will offer to help.",
                        npcs = {},
                        subs = {
                            { text = "If your cat doesn't automatically initiate a conversation with you, you may have to attempt this a third time." },
                        },
                    },
                    {
                        text = "Talk to Joe again.",
                        npcs = {},
                        subs = {
                            { text = "You can drop the smouldering pot now." },
                        },
                    },
                },
            },
            {
                title = "The Face and the Felkrash", needed = { "101 coins (51 coins with the ring of charos(a)), and one free inventory space." },
                steps = {
                    {
                        text = "Talk to Felkrash, north of Port Sarim lodestone.",
                        npcs = { "Felkrash", "Port Sarim lodestone" },
                    },
                    {
                        text = "Talk to The Face nearby.",
                        npcs = { "The Face" },
                    },
                    {
                        text = "Head south of the bar in Pollnivneach.",
                        npcs = { "Pollnivneach" },
                    },
                    {
                        text = "Throw a coin into the money pot next to Badir the Snake Charmer and then complete the conversation. (unless wearing a ring of charos).",
                        chat = "1 Yes. / 2 I want to talk to you about animal charming. / 3 What if I offered you some money? / 2 Forget about it. I don't care. / 2 Walk away slowly / 1 Stop",
                        npcs = { "Badir the Snake Charmer", "ring of charos" },
                        subs = {
                            { text = "He will give you a music scroll." },
                        },
                    },
                    {
                        text = "If you have a snake charm in bank, retrieve it.",
                        npcs = { "snake charm" },
                    },
                    {
                        text = "Return to Port Sarim.",
                        npcs = {},
                    },
                    {
                        text = "Play the snake charm. Only 1 note can be set per page.",
                        npcs = {},
                        subs = {
                            { text = "Go through the pages and click the correct notes (one note per page). The red dots in the music scroll correspond to the black dots on the flutes." },
                            { text = "On page 5, click the <) icon in the top left before you play the note. You can go back and make corrections to the pages if needed." },
                            { text = "Click play once all the notes are correctly selected." },
                            { text = "There will be short cutscene upon completing correctly." },
                        },
                    },
                    {
                        text = "Talk to Felkrash.",
                        npcs = {},
                        subs = {
                            { text = "You can destroy your music scroll now." },
                        },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "rebuilding_edgeville_miniquest", name = "Rebuilding Edgeville (miniquest)", wiki = "Rebuilding Edgeville (miniquest)/Quick guide",
        required = { "5 bittercap mushrooms", "20 planks (protean planks don't work)", "10 oak planks (protean planks don't work)", "10 mahogany planks (protean planks don't work)", "Molten glass", "Marble block", "100 water runes", "Magic watering can (tool belt works)" },
        recommended = { "Amulet of glory for quick transport to Draynor Village and Edgeville" },
        sections = {
            {
                title = "Checklist", needed = {},
                steps = {
                    {
                        text = "Start by talking to Vannaka near the lever teleport from Edgeville, for a To-Do list..",
                        chat = "3 Did you see what attacked Edgeville? / Accept",
                        npcs = { "Vannaka", "Edgeville", "To-Do list (Rebuilding Edgeville)" },
                    },
                    {
                        text = "Head to Aggie's house which is north-west of the Draynor Village bank and take the broom when Aggie is not looking at you to obtain Aggie's broom (uncharged).",
                        npcs = { "Draynor Village", "Broom (scenery)", "Aggie's broom (uncharged)" },
                    },
                    {
                        text = "Charge the uncharged broom with 100 water runes to obtain Aggie's broom.",
                        npcs = { "Aggie's broom" },
                    },
                    {
                        text = "Head back to Edgeville and sweep four scorch marks.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Jeffery, who is east of the bank and near a furnace, for Jeffery's hammer.",
                        chat = "2 Have you seen the damage done to Edgeville?",
                        npcs = { "Jeffery", "Jeffery's hammer" },
                    },
                    {
                        text = "Fix the following buildings by getting close to the locations and selecting the first option of the hammer in your backpack. You will need to remove them from your plank box if using that to carry them.",
                        npcs = { "backpack", "plank box" },
                        subs = {
                            { text = "The house north of the bank, requiring ten mahogany planks." },
                            { text = "The market stall north of the bank, requiring ten planks." },
                            { text = "The broken window on the north side of the bank, requiring five planks and a unit of molten glass." },
                            { text = "Jeffery's Armoury, east of the bank, requiring five planks." },
                            { text = "The guard house, north-east of the bank, requiring a marble block." },
                            { text = "The house across River Lum, between the river and Grand Exchange, requiring ten oak planks." },
                        },
                    },
                    {
                        text = "Use five bittercap mushrooms on the fairy ring south of Quercus.",
                        npcs = { "bittercap mushroom", "fairy ring", "Quercus" },
                    },
                    {
                        text = "Clear the Destroyed Roof and Destroyed Wall just west of the fairy ring.",
                        npcs = { "Destroyed Roof", "Destroyed Wall" },
                    },
                    {
                        text = "Consecrate or desecrate the burnt skeleton north of the bank.",
                        npcs = { "burnt skeleton" },
                    },
                    {
                        text = "Nurture four burnt trees. Any four around Edgeville work.",
                        npcs = { "burnt tree" },
                    },
                    {
                        text = "Go back to Vannaka for your reward.",
                        chat = "3 Rebuilding Edgeville",
                        npcs = {},
                    },
                },
            },
        },
    },
