    {
        key = "recipe_for_disaster_another_cook_s_quest", name = "Recipe for Disaster: Another Cook's Quest", wiki = "Recipe for Disaster: Another Cook's Quest/Quick guide",
        required = { "1 Eye of newt", "1 Greenman's ale", "1 Rotten tomato", "1 Ashes", "1 Fruit Blast (premade does not work). The fruit blast can also be made with the following items:", "1 Cocktail shaker", "1 Cocktail glass", "2 Lemons, 1 pineapple, 1 orange" },
        recommended = {},
        sections = {
            {
                title = "Before starting the quest", needed = { "It is recommended that players grow a pet kitten before they start the quest. If they don't already have an adult cat, it will take 2.5 hours for the pet kitten to grow into a cat. If done at the start of the quest, it should be fully grown and Recipe for Disaster: Freeing Evil Dave can be completed last." },
                steps = {
