                    {
                        text = "Use the ashes on the fruit blast.",
                        npcs = {},
                    },
                    {
                        text = "Give the items to the cook.",
                        npcs = {},
                    },
                    {
                        text = "Subquest complete!",
                        npcs = {},
                    },
                    {
                        text = "Go through the dining hall door and complete the dialogue to unlock the rest of subquests.",
                        npcs = {},
                        subs = {
                            { text = "It is recommended to inspect each character first, complete every subquest outside this instanced area and then finish all of them at once." },
                        },
                    },
                },
            },
        },
