    {
        key = "recipe_for_disaster_freeing_evil_dave", name = "Recipe for Disaster: Freeing Evil Dave", wiki = "Recipe for Disaster: Freeing Evil Dave/Quick guide",
        required = { "Wily cat, cat, kitten, or lazy cat", "Overgrown cats won't work as they do not hunt rats", "A kitten is not recommended as the chance of them catching a rat is a low 15% compared to 50% for a normal cat, and will take longer to complete", "Up to 10 bowls of stew (If you make no mistakes, you will not need more than 10 bowls. The Forester's Arms sells stew for 20 coins)." },
        recommended = { "Charged amulet of glory or the Wilderness sword for quick teleport to Edgeville. Alternatively, Edgeville lodestone can be used." },
        sections = {
            {
                title = "Freeing Evil Dave", needed = {},
                steps = {
                    {
                        text = "Inspect Evil Dave inside Lumbridge Castle Banquet Hall.",
                        npcs = { "Evil Dave", "Lumbridge Castle" },
                    },
                    {
                        text = "Optional: West of Edgeville's bank, talk to Doris.",
                        chat = "1 Is Dave in? / 1 Yes, I'm evil!",
                        npcs = { "Edgeville", "Doris" },
                    },
                    {
                        text = "Head into the house's basement.",
                        npcs = { "Evil Dave's Basement of Doom" },
                    },
                    {
                        text = "Talk to Evil Dave.",
                        chat = "2 General chat / 3 What did you eat at the secret council meeting? / 4 You've got to tell me because the magic requires it!",
                        npcs = {},
                    },
                    {
                        text = "Speak to Doris, upstairs in the house. If you miss this step, the hellrats will only drop ashes.",
                        npcs = {},
                    },
                    {
                        text = "Head back in the basement, interact with your cat and select \"Chase-Vermin\". (Switch off 'Hide Familiar Options' in Gameplay->Combat & Action Bar-> 'Choose Option' Menu)",
                        npcs = {},
                    },
                    {
                        text = "As your cat catches the rats, pick up the spices that drop.",
                        npcs = {},
                    },
                    {
                        text = "Do so until at least six doses of each of the four spices are collected.",
                        npcs = {},
                    },
                    {
                        text = "Make Dave's Evil stew by combining doses of each spice on the stews.",
                        npcs = { "Evil stew", "stews" },
                    },
                    {
                        text = "Start with 1 dose of any spice on the stew, then use the spicy stew on Evil Dave (right click and use).",
                        npcs = {},
                    },
                    {
                        text = "If he says one spice is right, note the number of dose using Spice type below.",
                        npcs = {},
                    },
                    {
                        text = "(Skip if 1 dose is correct) Use 2 dose of spice on the stew, then use on Evil Dave, repeat step 2. Do not try for three spices, if 2 doses is wrong then it is 3 doses.",
                        npcs = {},
                    },
                    {
                        text = "Repeat for each spice.",
                        npcs = {},
                    },
                    {
                        text = "Once all 4 types of spice dosage are confirmed, use it on another stew with corresponding doses, then use on Evil Dave one last time.",
                        npcs = {},
                    },
                    {
                        text = "After determining the right combination, have Evil Dave taste it and finish the dialogue. This won't consume the stew.",
                        npcs = {},
                    },
                    {
                        text = "Head to Lumbridge and give Evil Dave the stew.",
                        npcs = { "Lumbridge" },
                    },
                    {
                        text = "Subquest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "recipe_for_disaster_freeing_king_awowogei", name = "Recipe for Disaster: Freeing King Awowogei", wiki = "Recipe for Disaster: Freeing King Awowogei/Quick guide",
        required = { "Monkeyspeak amulet (if you've lost your amulet, all the materials to remake it, except for the gold bar, can be bought from shops in Ape Atoll)", "Gorilla greegree or gorilla greegree (bearded) or gorilla greegree (ancient)", "Ninja monkey greegree or small variant", "Zombie monkey greegree", "Banana (can be picked or bought in Ape Atoll)", "Monkey nuts (can be bought in Ape Atoll)", "Rope (can be bought in Ape Atoll)", "Few coins (10 coins should be enough)" },
        recommended = { "Antipoison", "A regular monkey greegree", "A ninja monkey greegree (small) and fairy ring access", "Combat gear to fight against a few big snakes (level 64)", "Several pieces of food (lobsters or higher)", "Cooking cape (no chance to burn food)", "Chef's delight (m) or Chef's delight or Cooking potion if your Cooking is lower than 70", "Spirit tree re-rooter to get to the Grand Tree/Daero quicker (for travel to Ape Atoll)" },
        sections = {
            {
                title = "Forenote", needed = {},
                steps = {
                    {
                        text = "The completion of this subquest will require players to have a ninja monkey greegree, zombie monkey greegree, and gorilla greegree as well as a monkeyspeak amulet.",
                        npcs = { "ninja monkey greegree", "zombie monkey greegree", "gorilla greegree", "monkeyspeak amulet" },
                    },
                },
            },
            {
                title = "King Awowogei", needed = {},
                steps = {
                    {
