    {
        key = "recipe_for_disaster_freeing_pirate_pete", name = "Recipe for Disaster: Freeing Pirate Pete", wiki = "Recipe for Disaster: Freeing Pirate Pete/Quick guide",
        required = { "Raw cod", "Bread", "An empty fishbowl", "Needle (Only a normal needle will work. Tool belt will not work.)", "3 bronze wires" },
        recommended = {},
        sections = {
