                title = "Pirate Pete", needed = {},
                steps = {
                    {
                        text = "Inspect Pirate Pete in the banquet hall in Lumbridge Castle.",
                        npcs = { "Pirate Pete" },
                    },
                    {
                        text = "Talk to the Cook in the Lumbridge Castle.",
                        chat = "3 Protecting the Pirate / 1 Where do I get Ground Cod? / 2 Where do I get Ground Giant Crab Meat? / 3 Where do I get Breadcrumbs? / 5 Thanks!",
                        npcs = { "Cook (Lumbridge)", "Lumbridge Castle" },
                    },
                },
            },
            {
                title = "Diving", needed = { "1 fishbowl, 1 needle, 3 bronze wire, any weapon unequipped in the backpack, at least 8 backpack space" },
                steps = {
                    {
                        text = "Bank any Summoning pouches or Pets.",
