        },
    },
    {
        key = "recipe_for_disaster_freeing_sir_amik_varze", name = "Recipe for Disaster: Freeing Sir Amik Varze", wiki = "Recipe for Disaster: Freeing Sir Amik Varze/Quick guide",
        required = { "Bucket of milk (buy from chest)", "Pot of cream (buy from chest)", "Sweetcorn", "Empty pot (can be obtained during quest, bought from chest or picked from the table in the kitchen)", "Radimus notes if you haven't completed Legends' Quest", "Dramen staff or Lunar staff if you haven't completed A Fairy Tale III - Battle at Ork's Rift", "Raw chicken (can be obtained during the quest at the Chicken Shrine)", "Dramen branch (or cinnamon, made from a Dramen branch)" },
        recommended = { "Anti-dragon shield or super antifire", "Ice gloves" },
        sections = {
            {
                title = "Sir Amik", needed = {},
                steps = {
                    {
                        text = "Inspect Sir Amik Varze.",
                        npcs = { "Sir Amik Varze" },
                    },
                    {
                        text = "Talk to the Cook in the Lumbridge Castle kitchen.",
                        chat = "4 More... / 5 More... / 2 Protecting Sir Amik Varze",
                        npcs = { "Cook (Lumbridge)", "Lumbridge Castle" },
                    },
                },
            },
            {
                title = "The Brulee", needed = { "Pot of cream, bucket of milk, and sweetcorn" },
                steps = {
                    {
                        text = "Use a bucket of milk with a pot of cream.",
                        npcs = { "bucket of milk", "pot of cream" },
                    },
                    {
                        text = "Locate a windmill (Taverley windmill doesn't work) and pick up an empty pot on the 1st floor.",
                        npcs = { "windmill", "empty pot" },
                    },
                    {
                        text = "Put sweetcorn into the hopper on the 3rd floor.",
                        npcs = { "sweetcorn", "hopper" },
                    },
                    {
                        text = "Operate the hopper controls, then take from the flour bin on the 1st floor.",
                        npcs = { "hopper controls" },
                    },
                    {
                        text = "Use the milky mixture with the pot of cornflour.",
                        npcs = { "milky mixture", "pot of cornflour" },
                    },
                },
            },
            {
                title = "Vanilla Pod", needed = {},
                steps = {
                    {
                        text = "Go to the Kharazi Jungle.",
                        npcs = { "Kharazi Jungle" },
                        subs = {
                            { text = "Have Radimus notes with you, if Legends' Quest isn't completed." },
                            { text = "Fairy ring CJS if unlocked." },
                        },
                    },
                    {
                        text = "Head southwest of the pool to the beach to find five vanilla plants.",
                        npcs = { "vanilla plant" },
                    },
                    {
                        text = "Search a Vanilla plant and add the vanilla pod to the cornflour mixture for brulee.",
                        npcs = { "vanilla pod", "cornflour mixture", "brulee" },
                    },
                },
            },
            {
                title = "Evil Chicken's Egg and Dragon Token", needed = { "Dragonfire protection" },
                steps = {
                    {
                        text = "Go to Draynor Village and talk to the Wise Old Man.",
                        chat = "3/4 I'd just like to ask you something. / 2 Strange beasts / 4 The Evil Chicken / 2 Thanks, maybe some other time.",
                        npcs = { "Draynor Village", "Wise Old Man" },
                    },
                    {
                        text = "Head to Zanaris. Use a raw chicken on the Chicken shrine. (Kill a chicken near the shrine for a raw chicken if you need one).",
                        npcs = { "Zanaris", "raw chicken", "Chicken shrine" },
                    },
                    {
                        text = "Head north and kill the Evil Chicken.",
                        npcs = {},
                        subs = {
                            { text = "If the chicken is not in the shrine, talk to the Cook and attempt to fight it again." },
                        },
                    },
                    {
                        text = "Take the evil chicken's egg (right-click the loot pile, as area loot won't show it).",
                        npcs = { "evil chicken's egg" },
                    },
                    {
                        text = "Head south and kill a black dragon.",
                        npcs = { "black dragon" },
                    },
                    {
                        text = "Take the dragon token it drops (right-click the loot pile, as area loot won't show it).",
                        npcs = { "dragon token" },
                    },
                    {
                        text = "Use the egg on the brulee.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Cinnamon", needed = { "1 dramen branch" },
                steps = {
                    {
                        text = "Craft your dramen branches branch, selecting pestle and mortar.",
                        npcs = { "dramen branch", "pestle and mortar" },
                        subs = {
                            { text = "If you do not have Dramen branches, cut one from the dramen tree in the Entrana Dungeon." },
                        },
                    },
                    {
                        text = "Add the cinnamon to the brulee.",
                        npcs = { "cinnamon" },
                    },
                },
            },
            {
                title = "Freeing Sir Amik", needed = { "Ice gloves or dragonfire protection" },
                steps = {
                    {
                        text = "Wear the ice gloves or dragonfire protection, otherwise you can take up to 500 damage if you don't have them on for the next few steps.",
                        npcs = {},
                    },
                    {
                        text = "Rub the dragon token in either Lumbridge or Zanaris.",
                        npcs = { "Lumbridge" },
                    },
                    {
                        text = "Ask the Fairy Dragon to flambé the brulee.",
                        chat = "1 Please flambe this creme brulee for me.",
                        npcs = { "Fairy Dragon" },
                    },
                    {
                        text = "Head back to Lumbridge Castle then use brulee supreme on Sir Amik.",
                        npcs = { "brulee supreme" },
                    },
                    {
                        text = "Subquest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "recipe_for_disaster_freeing_skrach_uglogwee", name = "Recipe for Disaster: Freeing Skrach Uglogwee", wiki = "Recipe for Disaster: Freeing Skrach Uglogwee/Quick guide",
        required = { "1 Raw chompy (if you don't burn the food, only one is needed)", "Ball of wool", "Iron spit", "Logs", "Ogre bellows", "Ogre bow or Comp ogre bow", "Ogre arrows or brutal arrows (bring extras or make more just in case you lose some)" },
        recommended = { "Feathers (to make the arrows if you don't have enough)", "Dramen Staff/Lunar Staff or completion of A Fairy Tale III - Battle at Ork's Rift (recommended for quick teleportation)", "Having the Karamja lodestone activated is a quick way to get to Karamja", "The gnome glider system is also a fast transportation method (glide to Lemantolly Undri)", "Access to Yanille lodestone for easier transportation to Feldip Hills", "Ardougne teleport (since you will need to travel to Karamja)", "Amulet of glory (alternative teleportation to Karamja)", "Ring of duelling (easier teleport to Feldip Hills if unable to use fairy rings)" },
        sections = {
            {
                title = "Skrach", needed = {},
                steps = {
                    {
                        text = "Inspect Skrach Uglogwee.",
                        chat = "1 Yes, I'm sure I can get some Jubbly Chompy. / 2 Oh Ok then, I guess I'll talk to Rantz.",
                        npcs = { "Skrach Uglogwee" },
                        tile = { x = 2769, y = 3092, plane = 0 },
                    },
                    {
                        text = "Head to Feldip Hills AKS and talk to Rantz to the north-east.",
                        chat = "1 I'm trying to free Skrach. Can you help? / 3 Ok, I'll do it.",
                        npcs = { "Feldip Hills", "Rantz" },
                    },
                    {
                        text = "Follow the coast south and talk to Rantz.",
                        chat = "1 I guess this is the watery place. What now?",
                        npcs = {},
                    },
                    {
                        text = "Cut the roots of the old tree, carve it",
                        npcs = {},
                    },
                    {
                        text = "Talk to Rantz.",
                        chat = "1 Okay, the boat's ready; now tell me how to get a jubbly.",
                        npcs = {},
                    },
                    {
                        text = "With a raw chompy, iron spit, and logs, teleport to the Karamja lodestone.",
                        npcs = { "raw chompy", "iron spit", "logs", "Lodestone Network" },
                    },
                    {
                        text = "Head south until a row boat is seen along the western coast. Just south-east of the boat is a small tree with Rantz's arrow stuck in it.",
                        npcs = {},
                    },
                    {
                        text = "Use the iron spit on the raw chompy and light a fire just west of the small tree.",
                        npcs = {},
                    },
                    {
                        text = "Cook the chompy on the fire.",
                        npcs = {},
                    },
                    {
                        text = "Board the nearby ogre boat.",
                        chat = "1 Yes please, I'll get a lift back with you.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Rantz.",
                        chat = "1 Okay, now tell me how to get jubbly.",
                        npcs = {},
                    },
                    {
                        text = "Make a balloon toad by using the following steps (it is advised to make a few in the event you burn the raw jubbly).",
                        npcs = { "balloon toad" },
                        subs = {
                            { text = "Just west, fill your ogre bellows with swamp bubbles from the swamp, then use the bellows on a swamp toad." },
                            { text = "Directly west or north-west of the swamp pool, mine a feldip swamp rock (near AKS)." },
                            { text = "With the rock, toad, and a ball of wool in your inventory, use the bellows on the bloated toad again to make a balloon toad (the bellows must be filled)." },
                        },
                    },
                    {
                        text = "Drop the balloon toad in the area where Rantz is.",
                        npcs = {},
                    },
                    {
                        text = "When a jubbly bird appears, kill it with an ogre bow and pluck it.",
                        npcs = { "jubbly bird", "ogre bow" },
                        subs = {
                            { text = "If a jubbly bird does not spawn by the time the balloon toad disappears, you will need to make another one." },
                        },
                    },
                    {
                        text = "Head north to the ogre spit-roast fire and cook the raw jubbly. If you burn it, you must repeat the hunting process.",
                        npcs = { "raw jubbly" },
                    },
                    {
                        text = "Return to Lumbridge Castle and Use cooked jubbly on Skrach.",
                        npcs = { "Lumbridge Castle", "cooked jubbly" },
                    },
                    {
                        text = "Subquest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "recipe_for_disaster_freeing_the_goblin_generals", name = "Recipe for Disaster: Freeing the Goblin Generals", wiki = "Recipe for Disaster: Freeing the Goblin Generals/Quick guide",
        required = { "Charcoal", "Spice or gnome spice", "Fishing bait", "Bucket of water or bowl of water or jug of water", "Bread", "Orange", "Green, blue, or purple dye" },
        recommended = { "Goblin village sphere for quick transportation" },
        sections = {
            {
                title = "Freeing the Generals", needed = {},
                steps = {
                    {
                        text = "Inspect either General Bentnoze or General Wartface. They are located in the Lumbridge Castle banquet room.",
                        npcs = { "General Bentnoze", "General Wartface" },
                    },
                    {
                        text = "Head to Goblin Village and climb down the ladder in the eastern building.",
                        npcs = { "Goblin Village" },
                    },
                    {
                        text = "Talk to Goblin Cook.",
                        chat = "2 I need your help... / 1 What do you need? Maybe I can get it for you.",
                        npcs = { "Goblin Cook" },
                    },
                    {
                        text = "Give him charcoal.",
                        chat = "1 I've got the charcoal you were after.",
                        npcs = { "charcoal" },
                    },
                    {
                        text = "After the cutscene, talk to him again.",
                        chat = "3 I need your help...",
                        npcs = {},
                    },
                    {
                        text = "Slice an orange into orange slices (not chunks) and use any colour of dye except orange, yellow, red, or pink on the slices to create dyed orange.",
                        npcs = { "orange", "orange slices", "Orange chunks", "dye", "Orange dye", "Yellow dye", "Red dye", "Pink dye", "dyed orange" },
                    },
                    {
                        text = "Use spice on fishing bait to create spicy maggots.",
                        npcs = { "spice", "fishing bait", "spicy maggots" },
                    },
                    {
                        text = "Right click Use bread on bucket, bowl, or jug of water to create soggy bread.",
                        npcs = { "bread", "Bucket of water", "Bowl of water", "Jug of water", "soggy bread" },
                    },
                    {
                        text = "Talk to Goblin Cook.",
                        chat = "3 I've got the ingredients we need...",
                        npcs = {},
                    },
                    {
                        text = "Head back to the dining room in Lumbridge Castle, use the slop of compromise on either of the Generals.",
                        npcs = { "Lumbridge Castle", "slop of compromise" },
                    },
                    {
                        text = "Subquest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
