    {
        key = "regicide", name = "Regicide", wiki = "Regicide/Quick guide",
        required = { "Items to get through the Underground Pass (other items can be banked until the lodestone is active):", "A bow (excluding all chargebows)", "A few of bronze, iron, steel, mithril, adamant, rune, dragon, or dark arrows", "A plank (can be obtained in the underground pass)", "1-5 ropes (you won't necessarily use all of them)", "Limestone (limestone bricks will not work)", "6-30 pieces of coal (coal in an orebox will not work)", "An empty pot (can be obtained in the elf camp)", "A strip of cloth (made by using 2 balls of wool on a loom)", "A cooked rabbit (can be obtained from charter traders or in Tirannwn after killing a rabbit and cooking the meat)" },
        recommended = { "Level 60 Agility or higher (to decrease the chance of failing obstacles in the Underground Pass).", "6,400 coins (to activate a charter ship route between Port Tyras and Port Sarim; less cost with discounts)", "Remora's necklace or an active lodestone in Port Sarim for quicker travels to Rimmington", "Any emergency teleport (Ectophial, teleport tablets, etc.)", "Weight-reducing clothing", "Antipoisons for the elf traps", "Summer Pies for lower agility levels" },
        sections = {
            {
                title = "Starting out", needed = { "Any bow, arrows, 1-5 ropes, plank" },
                steps = {
                    {
                        text = "Talk to King Lathas on the 2nd floor of Ardougne Castle.",
                        npcs = { "King Lathas", "Ardougne Castle" },
                    },
                    {
                        text = "Travel through the Underground Pass which can be found on the far west side of West Ardougne. You do not need to find another Iban's doll or complete any of the steps from Underground Pass quest. You only need to reach Iban's temple.",
                        npcs = { "Underground Pass (dungeon)", "West Ardougne" },
                    },
                    {
                        text = "Refer to this guide for instructions navigating the Underground Pass.",
                        npcs = { "Underground Pass (dungeon)" },
                    },
                    {
                        text = "Enter the well in Iban's Temple.",
                        npcs = { "Iban's Temple" },
                    },
                    {
                        text = "Exit the cave to the west.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Tirannwn", needed = { "Limestone" },
                steps = {
                    {
                        text = "Run through the forest, talk to Idris. Watch him die then continue.",
                        npcs = { "Idris" },
                        subs = {
                            { text = "If Idris does not spawn, log out and back in to trigger the scene." },
                        },
                    },
                    {
                        text = "Go west to jump the leaves trap (a dark green patch on the ground).",
                        npcs = {},
                    },
                    {
                        text = "Proceed southwest of the musician. Between some trees find a trap of sticks on the ground, click the sticks (choose the \"pass\" option, clicking beyond the sticks has a 100% failure rate).",
                        npcs = { "sticks" },
                        subs = {
                            { text = "This may take a few tries (if you spam click the trap, it will let you pass - make sure you're clicking the trap itself, as it has a small hitbox. If you're running low on health, return to the musician to recuperate before trying again." },
                        },
                    },
                    {
                        text = "Continue south towards the lodestone.",
                        npcs = {},
                    },
                    {
                        text = "Activate the Tirannwn lodestone once you find it.",
                        npcs = {},
                    },
                    {
                        text = "Run back north-west towards the elf camp.",
                        npcs = {},
                    },
                    {
                        text = "Jump another leaves trap, run past the bears and cross the log into the elf camp.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Lord Iorwerth.",
                        npcs = { "Lord Iorwerth" },
                    },
                    {
                        text = "Teleport to the Tirannwn lodestone, talk to the elf tracker.",
                        npcs = { "elf tracker" },
                    },
                    {
                        text = "Talk to Lord Iorwerth again which requires at least one free inventory space.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the elf tracker back at the Tirannwn lodestone.",
                        npcs = { "elf tracker" },
                    },
                    {
                        text = "Follow the tracks just west of the lodestone in front of the dense forest entrance.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the elf tracker.",
                        npcs = {},
                    },
                    {
                        text = "Enter the dense forest and kill the guard that appears.",
                        npcs = {},
                    },
                    {
                        text = "Go north, step-over the tripwire.",
                        npcs = {},
                        subs = {
                            { text = "Stepping over avoids taking damage as opposed to walking through." },
                        },
                    },
                    {
                        text = "Continue north through the dense forest and west, then once again through dense forest to enter Tyras Camp.",
                        npcs = { "Tyras Camp" },
                    },
                    {
                        text = "Talk to General Hining in the camp.",
                        npcs = { "General Hining" },
                    },
                    {
                        text = "Take two barrels behind the largest rectangular tent.",
                        npcs = { "barrel" },
                        subs = {
                            { text = "The second is required for completing Mourning's End Part I." },
                        },
                    },
                    {
                        text = "Teleport to the Tirannwn lodestone again and head south to reach the shoreline of the swamp.",
                        npcs = {},
                    },
                    {
                        text = "Use the barrels on the tar to fill them into barrels of tar.",
                        npcs = { "tar", "Barrel of tar" },
                        subs = {
                            { text = "There are only two clickable tiles near the corpse and trees. Mouse over along the shoreline until you find the clickable area." },
                        },
                    },
                    {
                        text = "Take some sulphur from the floor, then grind it into ground sulphur.",
                        npcs = { "sulphur", "ground sulphur" },
                    },
                    {
                        text = "Head north-west into the elf camp and talk to Lord Iorwerth.",
                        npcs = {},
                    },
                    {
                        text = "Read the Big Book of Bangs he gives you and pick up the empty pot north of him if you need one.",
                        npcs = { "the Big Book of Bangs" },
                    },
                    {
                        text = "Go to a furnace and use the limestone on it to obtain some quicklime.",
                        chat = "1 Yes",
                        npcs = { "furnace", "quicklime" },
                        subs = {
                            { text = "You need a pot if you wish to grind the quicklime now, otherwise it will be destroyed." },
                        },
                    },
                },
            },
            {
                title = "Sabotage", needed = { "The Big Book of Bangs, empty pot, quicklime, strip of cloth, cooked rabbit, barrel of coal-tar, ground sulphur and at least 10 pieces of coal (cannot be in an ore box, noted or Furnace - more may be required as you fail to operate the still)" },
                steps = {
                    {
                        text = "Talk to the Chemist in Rimmington.",
                        chat = "3 Ask about Regicide. / 1 What is naphtha and how do I make it? / 2 What's quicklime? / 3 What's brimstone?",
                        npcs = { "Chemist", "Rimmington" },
                        subs = {
                            { text = "The book must be in your inventory, otherwise your Quest Journal will not update." },
                        },
                    },
                    {
                        text = "Use your barrel of tar on the fractionation still outside.",
                        npcs = { "fractionation still" },
                    },
                },
            },
            {
                title = "Operating the still", needed = {},
                steps = {
                    {
                        text = "Click the tar regulator side twice.",
                        npcs = {},
                    },
                    {
                        text = "Wait until the arrow gauge is within the green on the pressure valve side, then click the pressure valve once. This should keep the pressure indicator in the green without fluctuating.",
                        npcs = {},
                    },
                    {
                        text = "Now add coal in 2x increments using the middle \"Add coal\" button to get the tar regulator indicator in the green.",
                        npcs = {},
                    },
                    {
                        text = "Now that the pressure valve and tar regulator are both in the green, the distillation bar at the bottom of the interface will begin to fill up.",
                        npcs = {},
                    },
                    {
                        text = "When the distillation bar is full, you may exit out of the interface, You should now have a barrel of naptha in the backpack.",
                        npcs = {},
                        subs = {
                            { text = "If you plan on completing Mourning's End I a barrel of naphtha is required for that quest, repeat this process for a second barrel." },
                        },
                    },
                },
            },
            {
                title = "Preparing barrel bomb", needed = {},
                steps = {
                    {
                        text = "Make the bomb:",
                        npcs = {},
                        subs = {
                            { text = "Use ground sulphur on the barrel of naphtha for naphtha mix." },
                            { text = "Grind the quicklime with an empty pot in your backpack." },
                            { text = "Use the pot of quicklime on the naptha mix." },
                            { text = "Use a strip of cloth on the barrel bomb." },
                        },
                    },
                    {
                        text = "Teleport back to the Tirannwn lodestone.",
                        npcs = {},
                        subs = {
                            { text = "Kill and cook a rabbit just north if you didn't bring a cooked rabbit." },
                        },
                    },
                    {
                        text = "Head to the catapult north of Tyras Camp (west through the dense forest and tripwires if you used the lodestone).",
                        npcs = {},
                    },
                    {
                        text = "Right-click use the cooked rabbit on the Tyras guard standing next to the catapult.",
                        npcs = { "Tyras guard (catapult)" },
                    },
                    {
                        text = "Use the barrel bomb on the catapult.",
                        npcs = { "barrel bomb" },
                    },
                    {
                        text = "Talk to Lord Iorwerth at the Elf Camp.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The lord's message", needed = {},
                steps = {
                    {
                        text = "Attempt to enter Ardougne Castle. Arianwyn will talk to you.",
                        npcs = { "Arianwyn" },
                    },
                    {
                        text = "Talk to King Lathas.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
