    {
        key = "requiem_for_a_dragon", name = "Requiem for a Dragon", wiki = "Requiem for a Dragon/Quick guide",
        required = { "30 white marble (material storage works)", "30 white oak (material storage works)", "5 greater ensouled bars", "Ink and candles for two level 75 Necromancy rituals (assuming no glyphs or light sources are present at the Um ritual site):", "4 basic ghostly ink", "10 regular ghostly ink", "16 greater ghostly ink", "12 basic ritual candle or better" },
        recommended = { "Level 80 Necromancy (to make greater ensouled bars)", "Archaeology journal", "Archaeology equipment", "Sixth-Age circuit", "Combat equipment", "Super restore" },
        sections = {
            {
                title = "Starting out", needed = {},
                steps = {
                    {
                        text = "Talk to Aster in the Fort Forinthry Town Hall.",
                        chat = "1 Talk about quests... / 1 Talk about 'Requiem for a Dragon'. / Accept",
                        npcs = { "Aster", "Town Hall (Fort Forinthry)" },
                    },
                },
            },
            {
                title = "Approaching Vorkath", needed = { "5 free backpack spaces" },
                steps = {
                    {
                        text = "Head east to the rowboat docked next to the Grove cabin.",
                        npcs = { "Rowboat (Fort Forinthry)", "Grove" },
                    },
                    {
                        text = "Interact with the rowboat to travel to Ungael.",
                        chat = "1 Yes.",
                        npcs = { "Ungael" },
                        subs = {
                            { text = "You will spawn next to hostile Zamorakian scouts; praying against Ranged can be helpful. This is a safe encounter, and you will respawn outside of the rowboat upon death." },
                        },
                    },
                    {
                        text = "Run north-west past the scouts and enter the colossal cave.",
                        npcs = { "colossal cave" },
                    },
                    {
                        text = "Head north-west and approach Vorkath.",
                        chat = "2 Reach out your hand. (friendly) / 2 Keep your hand extended. (friendly) / 2 Encourage Vorkath. (friendly) / 2 Try not to shiver. (friendly) / 1 Study the creature. (neutral) / 2 Lay the dragon's soul to rest. (Necromancy)",
                        npcs = { "Vorkath" },
                    },
                    {
                        text = "Inspect the crystal shard in the backpack.",
                        npcs = { "crystal shard" },
                    },
                    {
                        text = "Return to the Ungael beach, this time travel up the north-east path, up the hill and interact with the Ruins Entrance to enter.",
                        npcs = { "Ruins Entrance" },
                    },
                    {
                        text = "Head north, just in front of the Imposing Statue, and interact with the doorway to the south.",
                        npcs = { "Imposing Statue", "Doorway (Ungael)" },
                    },
                    {
                        text = "Follow the path south-west and kill the translator.",
                        npcs = { "translator" },
                    },
                    {
                        text = "Pick up the dropped Zamorakian translator's notes and read them.",
                        npcs = { "Zamorakian translator's notes" },
                    },
                    {
                        text = "Search the bookcase on the northern wall for Zorgoth's Journal.",
                        npcs = { "Bookcase (Ungael)", "Zorgoth's Journal" },
                    },
                    {
                        text = "Search the shelves immediately southeast for a broken focus.",
                        npcs = { "Shelves (Requiem for a Dragon)", "broken focus" },
                    },
                    {
                        text = "Inspect the dragonkin mural on the western wall.",
                        npcs = { "Dragonkin mural (Requiem for a Dragon)" },
                    },
                    {
                        text = "Pick up the congealed potion in the south-eastern corner.",
                        npcs = { "congealed potion" },
                    },
                    {
                        text = "Listen to the Archivist about all findings.",
                        chat = "1 The wall mural. / 2 The congealed potion. / 3 The broken focus. / 4 The crystal shard.",
                        npcs = { "Archivist (Ungael)" },
                    },
                },
            },
            {
                title = "Fort Forinthry", needed = {},
                steps = {
                    {
                        text = "Return to Fort Forinthry and enter the floor hatch east of the Command Centre (south-east).",
                        npcs = { "Fort Forinthry", "floor hatch", "Command Centre" },
                    },
                    {
                        text = "Talk to Zemouregal.",
                        npcs = { "Zemouregal" },
                        subs = {
                            { text = "If your Necromancy level is 120, you can skip most of the conversation", chat = "1 Show off your mastery of necromancy. / 3 What did you do to Vorkath? / 4 I've heard enough." },
                            { text = "Otherwise, you must follow further dialogue options", chat = "3 Mock his skeletal form. / 1 Remind him of the other times you've defeated him. / 1 I have a soul and you don't. / 3 What did you do to Vorkath? / 4 I've heard enough." },
                        },
                    },
                },
            },
            {
                title = "City of Um", needed = {},
                steps = {
                    {
                        text = "Head to the City of Um and talk to Death.",
                        chat = "1 Yes. / 3 Just tell me what the lead is.",
                        npcs = { "City of Um", "Death" },
                    },
                },
            },
            {
                title = "Tree of Balance", needed = {},
                steps = {
                    {
                        text = "Talk to the Tree of Balance, south of the Archaeology Guild.",
                        chat = "1 Continue Requiem for a Dragon. / 3 Let's get straight to the point.",
                        npcs = { "Tree of Balance", "Archaeology Guild" },
                    },
                },
            },
            {
                title = "Memorial to Guthix", needed = { "Backpack space to excavate two artefacts" },
                steps = {
                    {
                        text = "Head to Memorial to Guthix (do not enter the Hall of Memories)",
                        npcs = { "Memorial to Guthix", "Hall of Memories" },
                        subs = {
                            { text = "You can teleport directly there using memory strand or Sixth-Age circuit, otherwise teleport to Eagles' Peak lodestone and run north-west" },
                        },
                    },
                    {
                        text = "South-east outside the memorial, uncover both fertile soil spots",
                        npcs = { "Fertile soil (Requiem for a Dragon)" },
                    },
                    {
                        text = "Excavate both halves of the soul beacon from the uncovered standing stone debris and runic debris. There is a material storage container just north of the spots.",
                        npcs = { "standing stone debris", "runic debris", "material storage container" },
                        subs = {
                            { text = "Damaged soul beacon (base)" },
                            { text = "Damaged soul beacon (core)" },
                        },
                    },
                },
            },
            {
                title = "Restoring the beacon", needed = { "Damaged soul beacon (base), damaged soul beacon (core), 30 white marble (material storage works), 30 white oak (material storage works), and 5 greater ensouled bars" },
                steps = {
                    {
                        text = "Return to the Tree of Balance with the two damaged parts.",
                        chat = "1 Continue Requiem for a Dragon.",
                        npcs = { "Tree of Balance" },
                    },
