    {
        key = "ritual_of_the_mahjarrat", name = "Ritual of the Mahjarrat", wiki = "Ritual of the Mahjarrat/Quick guide",
        required = { "Ring of visibility", "Rope", "Spade (Can be acquired during the quest; the one on your tool belt will not work)", "Catspeak amulet (e) or cramulet" },
        recommended = { "Anti-dragon shield or an equivalent protection against dragonfire", "Activated Falador lodestone", "A Dig Site pendant, Varrock Teleport or the Archaeology journal to get to the digsite easily.", "Rock climbing boots", "Combat gear and food", "Super energy potions or Endurance relic power", "Agility cape" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to Sir Tiffy Cashien in Falador Park about the Ritual of the Mahjarrat.",
                        chat = "# Ritual of the Mahjarrat. / Accept",
                        npcs = { "Sir Tiffy Cashien", "Falador Park" },
                    },
                    {
                        text = "Accept the teleport.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Mos Le'Harmless", needed = {},
                steps = {
                    {
                        text = "Talk to Sir Tendeth in the southern pub on Mos Le'Harmless.",
                        chat = "1 Yes.",
                        npcs = { "Sir Tendeth", "Mos Le'Harmless" },
                    },
                    {
                        text = "Talk to Sir Tendeth again after the cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the injured pirates outside and other pirates outside.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The mighty jungle", needed = { "Food and armour as well as protection against dragonfire" },
                steps = {
                    {
                        text = "Go north past the walls, to the blue area marked on the mini-map.",
                        npcs = {},
                    },
                    {
                        text = "Using the western side of the trees as cover and following the burnt areas, head to the east side of the island.",
                        npcs = {},
                        subs = {
                            { text = "Hide west of tropical trees and jungle grass with the examine Looks good for hiding in.... Once north of Trouble Brewing, you must keep hiding on the west side of the trees or grass. Do not move too quickly. Count at least 1 or 2 seconds before moving to next square." },
                            { text = "Surge, the Magic ability may be used." },
                            { text = "The music will change when you are not behind cover." },
                            { text = "If hit by a fireball, heal by entering the nearby bank." },
                            { text = "Remaining in the open for too long will cause a fireball to do damage and reset the player to the town gates." },
                            { text = "If you misclick while going through the dialogue during the cutscene, you will exit it. Take one step to the west then step back behind the tree to re-trigger the cutscene." },
                        },
                    },
                    {
                        text = "After the cutscene, report back to Sir Tiffy.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The archives", needed = { "Catspeak amulet (e) or Cramulet" },
                steps = {
                    {
                        text = "Talk to Sir Tiffy and explain the situation to him. If you haven't completed Quiet Before the Swarm then",
                        chat = "2 Ritual of the Mahjarrat. / 3 I think they were dragonkin. / 1 Ritual of the Mahjarrat. / 3 I think they were dragonkin.",
                        npcs = { "Quiet Before the Swarm" },
                    },
                    {
                        text = "Talk to Lady Table or Sir Tiffy.",
                        chat = "1 I think I understand the reincarnation bit. / 2 He's reincarnated as a cat. / 1 I think I understand the stonetoucher part. / 3 I think it's me.",
                        npcs = { "Lady Table" },
                    },
                    {
                        text = "Use the Catspeak Amulet to find Bob back on the surface, who will be roaming anywhere in Asgarnia or Misthalin. Or can be easily found in Apprentice Clara's Shop in Burthorpe.",
                        npcs = { "Bob (cat)", "Asgarnia", "Misthalin" },
                    },
                    {
                        text = "Once found, ask him for his collar.",
                        npcs = {},
                    },
                    {
                        text = "Study Bob's collar — the back, too!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Traversing Isle of Sann", needed = { "Bob's collar, a spade (tool belt does not work), eight empty inventory spaces" },
                steps = {
                    {
                        text = "Go through any fairy ring, dial DIR and teleport to the Gorak Plane.",
                        npcs = { "Gorak Plane" },
                    },
                    {
                        text = "Click \"Configure\", dial AKS and teleport to Kethsi.",
                        npcs = { "Kethsi" },
                    },
                    {
                        text = "Head north-west and search the rubble west of the mural to get tetrahedron 4. (If you do not receive the tetrahedron 4, check the bank for it.)",
                        npcs = { "tetrahedron 4" },
                    },
                    {
                        text = "Go south-east and climb up the ramp.",
                        npcs = {},
                    },
                    {
                        text = "Use Bob's collar on the wall design and solve the puzzle by positioning Bob's collar.",
                        npcs = { "wall design" },
                    },
                    {
                        text = "Press the up arrow once to submit your puzzle solution.",
                        npcs = {},
                    },
                    {
                        text = "Investigate the wall design to get tetrahedron 1, statue arm, note to you, note to Robert and Robert's necklace. Robert's necklace has no purpose in the quest and may be destroyed or banked.",
                        npcs = { "tetrahedron 1", "statue arm", "note to you", "note to Robert", "Robert's necklace" },
                    },
                    {
                        text = "Go south-west and jump across the ledge.",
                        npcs = {},
                    },
                    {
                        text = "Use the Statue arm on the statue.",
                        npcs = { "Statue arm" },
                    },
                    {
                        text = "Cross the fallen spire that appears and go down the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Go east and up the wall jump.",
                        npcs = {},
                    },
                    {
                        text = "Climb the wall to the west.",
                        npcs = {},
                    },
                    {
                        text = "Use the swing pole to the north.",
                        npcs = {},
                    },
                    {
                        text = "Walk across the beam.",
                        npcs = {},
                    },
                    {
                        text = "Jump east over the gap.",
                        npcs = {},
                    },
                    {
                        text = "Jump from the floor to the south.",
                        npcs = {},
                    },
                    {
                        text = "Go down the southern ladder twice.",
                        npcs = {},
                    },
                    {
                        text = "Squeeze through the pipe to the northeast of the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Use a pickaxe to mine the rocks or right-click and choose mine if using the pickaxe on your tool belt.",
                        npcs = {},
                    },
                    {
                        text = "Climb the nearby wall and run across both walls to the west. If you fail either wall run or the handholds, go back to the pipe.",
                        npcs = {},
                    },
                    {
                        text = "Climb across the handholds then go down the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Go east (along the northern coast) and search the rubble to find tetrahedron 3 and a strange device.",
                        npcs = { "tetrahedron 3", "strange device (Ritual of the Mahjarrat)" },
                    },
                    {
                        text = "Go back up the ladder twice and jump from the floor to the south. If you fail this jump, go back to the pipe.",
                        npcs = {},
                    },
                    {
                        text = "Slide down the roof to the south",
                        npcs = {},
                        subs = {
                            { text = "Grab the nearby spade if you didn't have one with you." },
                        },
                    },
                    {
                        text = "Walk across the plank to the south.",
                        npcs = {},
                    },
                    {
                        text = "Search the rubble to find tetrahedron 2.",
                        npcs = { "tetrahedron 2" },
                    },
                },
            },
            {
                title = "The lost library", needed = {},
                steps = {
                    {
                        text = "Once all four tetrahedrons are collected, go down the stairs north of the area where tetrahedron 2 was located.",
                        npcs = {},
                    },
                    {
                        text = "Use each tetrahedron on an indentation (on the walls close to the entrance, also a second spade spawns by the stairs)",
                        npcs = {},
                    },
                    {
                        text = "Check the quest journal for the code that must be found.",
                        npcs = {},
                    },
                    {
                        text = "Find the coordinates received and dig there with a spade to receive a Kethsian key. The strange device tells you your current location. The coordinates are arranged in a grid.",
                        npcs = { "Kethsian key", "strange device (Ritual of the Mahjarrat)" },
                    },
                    {
                        text = "Go back to the dungeon and through the door to the south.",
                        npcs = {},
                    },
                    {
                        text = "Search the southern bookcase for Dathana's message.",
                        npcs = { "Dathana's message" },
                        subs = {
                            { text = "Optional: Search the south-east bookcase for the tune bane scroll." },
                        },
                    },
                },
            },
            {
                title = "Planning", needed = {},
                steps = {
                    {
                        text = "Read the message, then take it to Sir Tiffy. If you haven't completed Quiet Before the Swarm then",
                        chat = "2 Ritual of the Mahjarrat. / 1 Ritual of the Mahjarrat.",
                        npcs = { "Quiet Before the Swarm" },
                    },
                    {
                        text = "Go to the White Knights' Castle and talk to either Idria, Thaerisk Cemphier, or Akrisae.",
                        chat = "3 So, instead, you'd risk all our lives? / 1 I can't think of another way. / 2 Yes, we'll have to be careful. / 3 I will risk my own life to negotiate.",
                        npcs = { "White Knights' Castle", "Idria", "Thaerisk Cemphier", "Akrisae" },
                    },
                    {
                        text = "Make sure to get Arrav's heart before going to speak to Azzanadra or he will not talk to you about this quest.",
                        npcs = {},
                    },
                    {
                        text = "Go to the north-eastern Varrock Dig Site winch, climb down and talk to Azzanadra. Ask him about the quest.",
                        chat = "1 Ritual of the Mahjarrat.",
                        npcs = { "Varrock Dig Site", "Azzanadra" },
                    },
                },
            },
            {
                title = "Setting up the site", needed = { "Ring of visibility, rope, all items from the previous step, and at least one free inventory space" },
                steps = {
                    {
                        text = "From the Rellekka Hunter area (fairy ring code: DKS) take the canoe (north-west from fairy ring code: DKS, north of Larry and past the hunter area) to the Mahjarrat Ritual Site Cavern, then squeeze-past the ice block to the east (do not enter the cavern itself). This allows one to skip the Wilderness.",
                        npcs = { "Rellekka Hunter area", "Mahjarrat Ritual Site Cavern", "Wilderness" },
                        subs = {
                            { text = "If there is no heat globe on the pedestal, you may reclaim it from Azzanadra and place on it." },
                        },
                    },
                    {
                        text = "At the Ghorrock Fort, jump over the pillar to the south (it is outside of the walls of the fort, there is no red line to indicate it, the obstacle is to the south along a line of trees and pillars.) then go through the tunnel.",
                        npcs = {},
                        subs = {
                            { text = "Avoid the undead Broavs or the player will get thrown into Zemouregal's dungeon. To escape, search the bed and lift up the tiles to the east of the cell. Enter the tunnel to escape." },
                        },
                    },
                    {
                        text = "Several items will need to be placed around the ritual site:",
                        npcs = {},
                        subs = {
                            { text = "Northern Beacon: Run west from the ice entrance at the north of the plateau. Place the beacon on the closest tree." },
                            { text = "Southern Beacon: Run directly south, and place the second beacon in the tree south-south-west of the ritual stone. If this is done correctly, you should have a message saying the south beacon is opposite the northern beacon." },
                            { text = "Arrav's Heart: Place Arrav's heart in the rocks south of the ritual marker. The site is several paces south of the marker and just a pace or two east. If you cannot place the heart in a pile of rocks, you are at the wrong place." },
                            { text = "Western Beacon: Run up the west side of the plateau until you find a tree just north of a central line. Place the beacon here. Using the tree just south of the central line will not work." },
                            { text = "Eastern Beacon: Run straight east and place the beacon on the tree directly opposite the western tree. You should have a message saying the east beacon is directly opposite the west beacon." },
                            { text = "Go to the north-west corner of the plateau and look for an Overhanging Tree above the Cavern entrance. Use a rope on it to create a rope climb from the beach to the plateau, turning it into a Snow-covered Tree with an attached rope. This will be used for your allies to climb to the ritual. (From now on, you can also use the rope yourself to get between the canoe landing site and the plateau without having to go past the dragons around Ghorrock.)" },
                        },
                    },
                },
            },
            {
                title = "Zemouregal's fort", needed = {},
                steps = {
                    {
                        text = "Head to Zemouregal's fort which is south-west of the ritual site.",
                        npcs = { "Zemouregal's fort" },
                    },
                    {
                        text = "Kill the Armoured zombie outside of the main entrance and pick up the Code key and Decoder strips.",
                        npcs = { "Armoured zombie", "Code key (main entrance)", "Decoder strips" },
                    },
                    {
                        text = "Read the code key and open the main entrance by obtaining the code from the key and strips.",
                        npcs = {},
                        subs = {
                            { text = "Drag the red strip number 1 to the first letter of the code key (example: \"E\")." },
                            { text = "A single number will be revealed by the code strip (example: \"E\" row). Enter that number in the code box using the controls." },
                            { text = "Drag the red strip number 2 to the second letter of the code key (example: \"I\")." },
                            { text = "A single number will be revealed by the code strip (example: \"I\" row). Enter that number in the code box using the controls." },
                            { text = "Drag the red strip number 3 to the third letter of the code key (example: \"H\")." },
                            { text = "A single number will be revealed by the code strip (example: \"H\" row). Enter that number in the code box using the controls." },
                            { text = "Drag the red strip number 4 to the fourth letter of the code key (example: \"C\")." },
                            { text = "A single number will be revealed by the code strip (example: \"C\" row). Enter that number in the code box using the controls." },
                        },
                    },
                    {
                        text = "Go through the front door and search the crate by the north-eastern weapon rack for the storeroom's Code key.",
                        npcs = { "Code key (storeroom)" },
                    },
                    {
                        text = "Read it and use it to open the storeroom door to the west in the same manner as the front entrance.",
                        npcs = {},
                    },
                    {
                        text = "In the northern part of the storeroom, search the crates (2 empty spaces required).",
                        npcs = {},
                    },
                    {
                        text = "Read the Heart magic notes.",
                        npcs = { "Heart magic notes" },
                    },
                    {
                        text = "Exit the room, head up the western stairs, and stand next to the southern door to listen to Zemouregal and Sharathteerk (you may have to move to the tile east of the door to allow the dialogue to play).",
                        npcs = { "Zemouregal", "Sharathteerk" },
                    },
                    {
                        text = "Head back downstairs, then go up the eastern stairs. Use the previously acquired Code key to enter the reliquary.",
                        npcs = { "Code key (reliquary)" },
                    },
                    {
                        text = "Smash the black stone in the southern half of the room.",
                        npcs = { "black stone (Ritual of the Mahjarrat)" },
                    },
                },
            },
            {
                title = "Searching for the Stone of Jas", needed = {},
                steps = {
                    {
                        text = "Exit the fortress and head to the south-eastern part of the ritual site.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Movario.",
                        chat = "1 So, you're still working for Lucien? / 1 What are you doing up here?",
                        npcs = { "Movario" },
                    },
                    {
                        text = "With the ring of visibility equipped, run west from Movario along southern wall of the site to find a shadow pedestal (almost directly south-east from the ritual marker).",
                        npcs = {},
                    },
                    {
                        text = "Go back inside the centre of the Ghorrock Castle courtyard (past the dragons), and climb the western stairs next to the statue of Khazard.",
                        npcs = { "Khazard" },
                    },
                    {
                        text = "Go east and climb down the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Scale the Damaged Wall next to the door.",
                        npcs = {},
                    },
                    {
                        text = "Run past the smashed pedestal, and climb down the smashed rampart on west side of the trapdoor in the courtyard.",
                        npcs = {},
                    },
                    {
                        text = "Enter the trapdoor. The icefiends encountered here will hit hard and there will be a good number of them. Bring high level food (sharks or swordfish) just in case for comfortable exploration.",
                        npcs = {},
                    },
                    {
                        text = "Enter the room to the west and then head south.",
                        npcs = {},
                    },
                    {
                        text = "Take the Heat globe and exit the same way you came.",
                        npcs = { "Heat globe" },
                    },
                    {
                        text = "Return to the shadow pedestal, south east of the ritual marker.",
                        npcs = {},
                    },
                    {
                        text = "Put the globe on the pedestal.",
                        npcs = {},
                        subs = {
                            { text = "If you try to put heat globe on the shadow pedestal and it says \"That could be a good idea, but you've got other things to do first.\", it means either that the beacons are not aligned properly, you have not placed Arrav's heart in the rocks to the south of the Ritual marker, you haven't placed the rope to the north-west of the tunnel or you have not talked to Movario after having done so. If you are completely sure you have done all of these things, talk to Movario to the east of the shadow pedestal, and he will place the heat globe in the pedestal. A few players have removed a beacon from a tree and put in back in the tree—this also has worked. Some report that reading the notes/Dathana's message also fixes this." },
                        },
                    },
                },
            },
            {
                title = "The ritual", needed = { "Food and Prayer Potions (Certain sections of this battle will call for no Prayer, and others will work with prayer just fine. Read ahead to understand the fight and allocate resources as necessary.)" },
                steps = {
                    {
                        text = "Enter the newly opened entrance, south of the shadowy pedestal.",
                        npcs = {},
                    },
                    {
                        text = "Follow the open passageway and touch the Stone of Jas.",
                        npcs = { "Stone of Jas" },
                    },
                },
            },
            {
                title = "The battle", needed = { "Using an overload or any damage curses or normal damage prayers will cause you not to be able to hit, as it interferes with the Stone of Jas buff." },
                steps = {
                },
            },
            {
                title = "Khazard", needed = {},
                steps = {
                    {
                        text = "After the cutscenes, defeat Khazard.",
                        npcs = { "General Khazard (monster)" },
                    },
                    {
                        text = "It helps to pray against magic and when Bouncer is summoned, lure him to Wahisietel so that he dies.",
                        npcs = { "Bouncer (ghost)", "Wahisietel" },
                    },
                },
            },
            {
                title = "Ice titans", needed = {},
                steps = {
                    {
                        text = "Defeat the Enhanced ice titans.",
                        npcs = { "Enhanced ice titan" },
                        subs = {
                            { text = "Lucien will be casting spells at the player whilst fighting the ice titans. If a smoking black skull is flying towards you, move at least two squares away from your current position. Also, praying melee completely negates damage from the titans' normal attacks. If ice starts encasing the player, they should click rapidly on the ground around them to escape." },
                            { text = "You will only be able to damage the two enhanced ice titans that run at you; your teammates must kill the rest." },
                            { text = "Avoid attacking Lucien, as doing so causes Lucien to hit you with a high damage attack." },
                        },
                    },
                },
            },
            {
                title = "Ice demons", needed = {},
                steps = {
                    {
                        text = "Defeat the Ice Demons",
                        npcs = { "Ice demon (Ritual of the Mahjarrat)" },
                        subs = {
                            { text = "Praying against magic helps limit the damage the demons can cause. They will also summon icicles which will fall around the player. When this happens, run out of the icicles to avoid being trapped due to Lucien still casting the skull spell at the player." },
                            { text = "You will only be able to damage the two ice demons that run at you; your teammates must kill the rest." },
                            { text = "You are able to use Split Soul on the two that your teammates are meant to kill to speed up the process." },
                        },
                    },
                },
            },
            {
                title = "Arrav", needed = {},
                steps = {
                    {
                        text = "Attack the armoured zombies until Arrav is summoned.",
                        npcs = { "Arrav" },
                    },
                    {
                        text = "Attack Arrav until he follows you. You may have to attack the zombies before Arrav will follow you.",
                        npcs = { "Arrav" },
                    },
                    {
                        text = "Lure him over to where his heart is placed and wait for Arrav to fight Zemouregal before proceeding.",
                        npcs = {},
                        subs = {
                            { text = "If you have a combat follower out, it is best to dismiss it when Arrav starts following you. Otherwise, it is possible that the combat familiar and Arrav will fight. If this occurs when Arrav gets his heart back, the familiar's attack may distract Arrav from attacking Zemouregal. Instead, Arrav will stand near the rockpile where his heart was hidden and will not move. This is a glitch, and the only way to overcome it is to leave the battle, return, and fight the fourth battle again from its start." },
                        },
                    },
                },
            },
            {
                title = "The broken beacon", needed = {},
                steps = {
                    {
                        text = "Head to where the southern beacon was.",
                        npcs = {},
                    },
                    {
                        text = "Turn on a prayer against ranged or magic attacks and pick up the beacon pieces.",
                        npcs = {},
                    },
                    {
                        text = "Click on a piece to assemble all of them and then place the beacon back into the tree.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Watch the cutscenes and pick a number for the new hiding spot for the Stone of Jas.",
                        npcs = {},
                    },
                    {
                        text = "Go to the stalls area of the town (north-west of where the bank would be in Draynor Village) in the destroyed version of Draynor Village.",
                        npcs = { "Draynor Village" },
                    },
                    {
                        text = "Watch the last cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Sir Tiffy. If Quiet Before the Swarm isn't completed.",
                        chat = "1 Ritual of the Mahjarrat. / 2 Ritual of the Mahjarrat.",
                        npcs = { "Quiet Before the Swarm" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
