                    {
                        text = "Swim around until you find a Karamthulhu and catch it. (It is the only fish that appears on the mini map.)",
                        npcs = { "Karamthulhu" },
                    },
                    {
                        text = "Head over to the ship and climb-up the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Open and search the chest to get a crowbar.",
                        npcs = { "crowbar" },
                        subs = {
                            { text = "An aggressive giant lobster may attack you. You can open and search the chest while being attacked." },
                        },
                    },
                    {
                        text = "Return down the stairs and climb down the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Go west on the bottom floor of the ship and dig the mess a several times to uncover the idol of many heads buried in the pile of planks and sand. Pick it up.",
                        npcs = { "Idol (Rocking Out)", "idol of many heads" },
                        subs = {
                            { text = "You can wield weapons while down there digging, so you can kill any aggressive giant crabs or lobsters that may be hindering you from digging successfully." },
                        },
                    },
                    {
                        text = "Bring the idol back to Bill Teach to receive Bill Teach's mark.",
                        chat = "1 Speak about Rocking Out.",
                        npcs = { "Bill Teach", "Bill Teach's mark" },
                    },
                },
            },
            {
                title = "Cap'n Izzy No-Beard", needed = {},
                steps = {
                    {
                        text = "Travel to Brimhaven and go to the Brimhaven Agility Arena entrance, located south-east of the docks.",
                        npcs = { "Brimhaven", "Brimhaven Agility Arena" },
                    },
                    {
                        text = "Speak to Cap'n Izzy No-Beard.",
                        chat = "1 Talk about Rocking Out.",
                        npcs = { "Cap'n Izzy No-Beard" },
                    },
                    {
                        text = "Return to the Rimmington Customs Office. Deposit all of your items in the locker and get arrested by talking to the Customs Sergeant.",
                        npcs = { "Rimmington", "Customs Sergeant" },
                    },
                    {
                        text = "Search the bed for a crude lockpick and use it on your cell door.",
                        npcs = { "crude lockpick" },
                    },
                    {
                        text = "Kill one of the customs officers, loot the uniform and equip it to disguise yourself.",
                        npcs = { "Customs Officer (Rocking Out)", "Customs Officer's outfit" },
                        subs = {
                            { text = "You can withdraw your pickaxe from your tool belt to use as a weapon." },
                            { text = "Make sure you do not have lootshare enabled, as this can prevent the uniform from being dropped. If you do not get the loot, try relogging." },
                        },
                    },
                    {
                        text = "Climb the stairs twice to the top floor.",
                        npcs = {},
                    },
                    {
                        text = "Open the door to the room with the cabinets.",
                        npcs = {},
                    },
                    {
                        text = "Search the northern-most cabinet on the second column from the west for \"Wanda the Fish\".",
                        chat = "1 Yes. Wanda the Fish",
                        npcs = { "File (Wanda the Fish)" },
                    },
                    {
                        text = "Talk to the Locker Officer and receive the brooch.",
                        npcs = { "Locker Officer", "Brooch (Rocking Out)" },
                    },
                    {
                        text = "Return to Cap'n Izzy No-Beard in Brimhaven to receive Izzy's mark.",
                        chat = "1 Talk about Rocking Out.",
                        npcs = { "Cap'n Izzy No-Beard", "Izzy's mark" },
                    },
                },
            },
            {
                title = "Back to prison and quest completion", needed = { "Izzy's mark, Bill Teach's mark, Frank's mark, Braindeath's mark, and Brass Hand Harry's mark" },
                steps = {
                    {
                        text = "Talk to the Customs Sergeant in Rimmington with the five marks. He will give you a file.",
                        npcs = { "File (empty)" },
                    },
                    {
                        text = "Use one of the marks on the file.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Customs Sergeant to give him the filled file.",
                        npcs = { "File (marks)" },
                    },
                    {
                        text = "Talk to him again to get sent back to prison.",
                        npcs = {},
                    },
                    {
                        text = "Search the bed for the crude lockpick and break out of your cell. Kill the Customs Officer(s) for another uniform, equip it, then head to the top floor.",
                        npcs = {},
                        subs = {
                            { text = "You may get a message saying that the lock is rusty, and the lockpick does not work. Continue trying until it works." },
                        },
                    },
                    {
                        text = "Go to the top floor and talk to the Locker Officer to get back the filled file.",
                        npcs = { "File (marks)" },
                    },
                    {
                        text = "Return to your cell and right-click open the door.",
                        npcs = {},
                        subs = {
                            { text = "If you do not have the option to open the cell door, hop to a different world." },
                        },
                    },
                    {
                        text = "Shout-through the barred window to Young Ralph. A cutscene will follow.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "roving_elves", name = "Roving Elves", wiki = "Roving Elves/Quick guide",
        required = { "A rope (not necessary if you have built a rope rack)", "A key to the Waterfall Dungeon (can be acquired during the quest)", "Glarial's pebble", "Glarial's amulet (can be acquired during the quest)" },
        recommended = { "Food, restore potions and combat stat-boosting potions", "Two summer pies or agility potions/flasks if your Agility level is below 56", "Means of getting to Ardougne (e.g. Ardougne Teleport, spirit trees, Ardougne cloak)", "Means of getting to Camelot (e.g. Camelot Teleport, Seers' Village Teleport)", "Means of getting to Tirannwn (e.g. money for charter ships)", "A few antipoison potions in case you trip the traps", "Amulet of glory", "Games necklace", "Regen bracelet", "Ring of recoil", "Enhanced excalibur" },
        sections = {
