                    {
                        text = "If needed, reclaim a key from the discoloured crates in the eastern room with skeletons.",
                        npcs = { "A key (Waterfall Dungeon)" },
                    },
                    {
                        text = "Go inside the north-west room with the statues.",
                        npcs = {},
                    },
                    {
                        text = "Plant the enchanted consecration seed anywhere inside.",
                        npcs = { "Consecration seed (enchanted)" },
                    },
                    {
                        text = "Return to Islwyn to choose your reward.",
                        chat = "Any",
                        npcs = {},
