    {
        key = "rune_mechanics", name = "Rune Mechanics", wiki = "Rune Mechanics/Quick guide",
        required = { "5 steam runes (you must craft one during the quest; the rest can be bought)", "1 fire rune or water rune (needed to craft the steam rune; 5 if crafting all 5 steam runes during the quest)", "Item to access fire altar if bringing water rune, or water altar if bringing fire rune (a fire talisman and water talisman are given to you in the quest)", "5 mind runes", "5 body runes", "2 emeralds", "21 pure essence (cannot be noted)", "Progress hat (and 5 or more pizazz points at the Mage Training Arena)" },
        recommended = { "Transportation to Mage Training Arena such as a ring of duelling or mystical sand seed" },
        sections = {
