                        npcs = { "binding necklace" },
                    },
                    {
                        text = "Craft at least one steam rune. The remaining runes (4 steam runes, 5 mind runes, 5 body runes) can be obtained or bought ahead of time.",
                        npcs = { "steam rune", "mind rune", "body rune" },
                        subs = {
                            { text = "Steam runes can be crafted by using fire runes on the water altar (consuming a fire talisman)." },
                            { text = "Alternatively, use water runes on the fire altar (consuming a water talisman)." },
