    {
        key = "secrets_of_amberfell", name = "Secrets of Amberfell", wiki = "Secrets of Amberfell/Quick guide",
        required = { "2 ropes", "10 logs (of same kind, core logs only)", "20 nails (of same kind)", "A butterfly net (including magic butterfly net and Tellervo's net)", "A teasing stick or ferret", "An empty vial", "5 cooked fish (not for combat use)", "Food (for combat use)", "3- or 4-dose antisanguine potion (optionally more for combat use)", "Combat gear, recommended to include a havensilver weapon" },
        recommended = { "Dramen/lunar staff (not necessary if A Fairy Tale III - Battle at Ork's Rift quest is completed)", "Portable fairy ring, Cape of legends, or TokKul-Zo for quick access to fairy rings", "Repair the Amberfell canoe station with 6 maple planks and 20 steel nails and Level 40 Construction", "War's retreat boss portal set to Ivar, King of Bones for fast access to the bridge" },
        sections = {
