                    },
                    {
                        text = "South-east of Anya's camp, talk to Mossbrain at the goblin camp.",
                        chat = "1 Talk about 'Secrets of Amberfell'.",
                        npcs = { "Mossbrain" },
                    },
                    {
                        text = "Talk to him again with 5 cooked fish to receive the offering bowl. If you have different types of fish, he will take the first 5 fish in your backpack.",
                        chat = "1 Talk about 'Secrets of Amberfell'.",
                        npcs = { "offering bowl" },
                    },
                    {
                        text = "Go to Highweald Forest, north of Wendlewick, and search a hollow tree (found at the Hunting resource icon on the minimap) to spawn spirit moths.",
                        npcs = { "Highweald Forest", "Hollow tree (Hollow Hill)", "spirit moths" },
