                        npcs = { "Shrine Tender Joanna" },
                    },
                    {
                        text = "Pray at the Altar of Inanna to enter Inanna's Den.",
                        chat = "1 Yes",
                        npcs = { "Altar of Inanna", "Inanna's Den" },
                    },
                    {
                        text = "Talk to Inanna.",
                        chat = "2 Move on. (Continue quest) / 3 Let's do it.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Anya to receive a vial of blood.",
                        npcs = { "Vial of blood (Secrets of Amberfell)" },
                    },
                    {
                        text = "Go to the floor of the Wendlewick lighthouse and talk to Esther.",
                        chat = "1 Talk about 'Secrets of Amberfell'. / Any / 2 I'll get going on that, then. (Continue quest)",
                        npcs = { "Lighthouse (Wendlewick)", "Esther" },
                    },
                    {
                        text = "Combine your antisanguine (3) potion with the vial of blood.",
                        npcs = { "antisanguine (3)" },
                    },
                    {
                        text = "Return to Inanna's Den and use the empowered antisanguine on Inanna.",
                        npcs = { "empowered antisanguine" },
                    },
                    {
                        text = "Talk to Inanna.",
                        chat = "Any / 1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Head to Amberfell and talk to Sorrel. (fairy ring DLP)",
                        chat = "Any / Any",
                        npcs = {},
                        subs = {
                            { text = "Make sure to have 6 backpack spaces, or you will have to go grab Anya and Inanna again and walk back. (If Inanna vanishes, using the Wendlewick lodestone may respawn her.)" },
                        },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
