    {
        key = "shades_of_mort_ton", name = "Shades of Mort'ton", wiki = "Shades of Mort'ton/Quick guide",
        required = { "2 or more vial of water (can be obtained during quest)", "2 or more ashes (can be obtained during quest)", "2 or more clean tarromin (obtained during quest but this is a rather uncommon drop, so bringing extra tarromin is recommended.)", "A pile of logs (can be gathered during quest)", "1,000 or more coins to buy resources" },
        recommended = { "Flamtaer bracelet", "Some food for lower-levelled players", "Some druid pouches, to stop the Ghasts from rotting your food as you pass through the Mort Myre Swamp or the ouroboros pouch", "An additional 13,000 coins will buy a flamtaer hammer, which speeds up the quest", "5 or more additional clean tarromin (herbs obtained during quest are usually not enough)", "A weapon to kill Loar Shades", "Doing this quest in world 88 as it has many benefits and is dedicated to the Shades of Mort'ton minigame" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Enter the south-western ruined house in Mort'ton.",
                        npcs = { "Mort'ton" },
                        tile = { x = 3491, y = 3287, plane = 0 },
                        subs = {
                            { text = "Teleport to Canifis and run south-west to the gate of the swamp (must have Nature Spirit quest started), and then head to Mort'ton." },
                            { text = "Teleport to fairy ring BKR and then run south by south-east to where the map says the Hollows, to find a rowboat that takes you there." },
                            { text = "Alternatively use Drakan's medallion to teleport to the Barrows and run west." },
                        },
                    },
                    {
                        text = "Search the shelf on the wall and read the diary.",
                        chat = "Accept",
                        npcs = { "Shelf (Shades of Mort'ton)", "Diary (Shades of Mort'ton)" },
                        subs = {
                            { text = "If you do not find it, it's probably already in your bank." },
                        },
                    },
                    {
                        text = "(Optional) Chop three swamp trees nearby and burn two logs to get the ashes.",
                        npcs = {},
                        subs = {
                            { text = "If you have an Underworld Grimoire equipped make sure to disable the auto-storage function, otherwise your ashes will be sent to the bank." },
                        },
                    },
                    {
                        text = "(Optional) Pick up the vials (on the ground near the shelf) and search the smashed table for extra tarromin and one grimy rogue's purse.",
                        npcs = { "vial", "smashed table", "grimy rogue's purse" },
                    },
                },
            },
            {
                title = "Serum 207", needed = {},
                steps = {
                    {
                        text = "Make vials of water by using the empty vials on the sink nearby.",
                        npcs = {},
                    },
                    {
                        text = "Make Serum 207 by adding clean tarromin and ashes to a vial of water.",
                        npcs = { "Serum 207" },
                    },
                    {
                        text = "Use it on Razmire (afflicted) in the general store.",
                        chat = "4 What are all these shadowy creatures? / 1 Yes, I'll dispatch those dark and evil creatures.",
                        npcs = { "Razmire" },
                    },
                    {
                        text = "Kill five Loar Shades and pick up their remains. Be sure to talk to Razmire first. They can be safespotted using the rocks south west of the waypost in the middle of town.",
                        npcs = { "Loar Shade" },
                    },
                    {
                        text = "Give him the remains. He may require more Serum 207.",
                        npcs = {},
                    },
                    {
                        text = "Use the serum on Ulsquire Shauncy, located in the house east of the general store.",
                        npcs = { "Ulsquire Shauncy" },
                    },
                    {
                        text = "Wait a minute and ask him about the remains and the temple.",
                        chat = "1 What did you find out about the remains? / 2 What can you tell me about that temple? / 5 Ok, thanks.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Razmire.",
                        chat = "3 I have another question. / 2 What can you tell me about that temple? / 4 Can you open a store for me? / 1 Can I see the general store please?",
                        npcs = {},
                    },
                    {
                        text = "Buy at least one olive oil from his general store and optionally a Flamtaer hammer.",
                        npcs = { "Flamtaer hammer" },
                    },
                    {
                        text = "Open his builders' store.",
                        npcs = {},
                    },
                    {
                        text = "Buy 5 timber beams, 5 limestone bricks, 25 swamp paste.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Repairing the temple", needed = {},
                steps = {
                    {
                        text = "Hop to World 88 which is the official world for this minigame.",
                        npcs = {},
                    },
                    {
                        text = "Head north-east and kill shades or repair the temple to increase your sanctity.",
                        npcs = {},
                    },
                    {
                        text = "Repair the temple until you reach 100% and at least 20 sanctity.",
                        npcs = {},
                    },
                    {
                        text = "Light the sacred altar in the centre of the temple.",
                        npcs = {},
                    },
                    {
                        text = "For solo questers: Shade luring dummies can be used to distract the Loar Shades when repairing the temple. Using the Flamtaer bracelet, the solo player can instantly create the temple walls section by section, until at 100%.",
                        npcs = { "Shade luring dummy", "Loar Shade", "Flamtaer bracelet" },
                    },
                    {
                        text = "Use your olive oil on the flame to make sacred oil.",
                        npcs = { "sacred oil" },
                    },
                    {
                        text = "(Optional) Use Serum 207 on the flame to make Serum 208, which permanently cures NPCs.",
                        npcs = { "Serum 208" },
                    },
                    {
                        text = "(Optional) Use the Serum 208 on Razmire and Ulsquire in the houses nearby to permanently cure them.",
                        npcs = { "Serum 208", "Razmire Keelgan", "Ulsquire Shauncy" },
                    },
                },
            },
            {
                title = "Burning a shade", needed = {},
                steps = {
                    {
                        text = "Use the sacred oil on a log to create a pyre log.",
                        npcs = { "pyre log" },
                    },
                    {
