    {
        key = "shadow_of_the_storm", name = "Shadow of the Storm", wiki = "Shadow of the Storm/Quick guide",
        required = { "Silverlight (If you do not have the sword, it can be re-obtained during the quest)", "Silver bar (metal bank works)", "Empty vial (To dye Silverlight/clothing black if you have not done so already)", "3 pieces of a black outfit (see Blending into the dark; you can also dye the desert robe and desert shirt during the quest for two of the pieces)", "The strange implement (If lost, it can be re-obtained during the quest)" },
        recommended = { "About 1,000 coins to cover expenses", "Waterskins (approximately 5 full waterskins) or an enchanted water tiara.", "Food and potions for lower levelled players", "Desert clothing", "Energy potions", "A charged amulet of glory, ring of duelling, a broomstick for teleporting to Al Kharid or an activated Al Kharid lodestone could be useful", "A traveller's necklace for faster travel to Uzer" },
        sections = {
            {
                title = "Starting out", needed = {},
                steps = {
                    {
                        text = "Talk to Father Reen south of Al Kharid bank.",
                        chat = "Accept",
                        npcs = { "Father Reen" },
                        tile = { x = 3271, y = 3158, plane = 0 },
                        subs = {
                            { text = "He will give you Silverlight if you've dyed or destroyed it." },
                        },
                    },
                    {
                        text = "Talk to Father Badden at Uzer, east of Shantay Pass. (Optional: take the magic carpet to Uzer)",
                        chat = "1 Reen sent me. / 3 So what do you want me to do? / 1 How can I do that?",
                        npcs = { "Father Badden", "Uzer" },
                    },
                    {
                        text = "Pick and grind a black mushroom (the closest is just south-east of the stairs east of Father Badden). Use it to dye Silverlight black. You can find some beside the staircase, downstairs east of the stairwell, or in the north east corner of the room, east of Evil Dave.",
                        npcs = { "black mushroom", "Father Badden", "Evil Dave" },
                    },
                    {
                        text = "Go down the stairs.",
                        npcs = {},
                        subs = {
                            { text = "If you do not have the strange implement from The Golem quest, you can pick it up from the ground in the northwest room." },
                        },
                    },
                    {
                        text = "Talk to Evil Dave wearing your three black items and your dyed Silverlight. He is standing at the entrance to Agrith Naar's demonic temple in the underground Uzer ruins.",
                        chat = "2 I want to join your group. / 1 I'm evil!",
                        npcs = { "Evil Dave" },
                    },
                },
            },
            {
                title = "Ritual", needed = {},
                steps = {
                    {
                        text = "Talk to Denath.",
                        chat = "4 What do I have to do?",
                        npcs = { "Denath" },
                    },
                    {
                        text = "Talk to Jennifer to get a demonic sigil mould.",
                        chat = "2 Do you have the demonic sigil mould?",
                        npcs = { "Jennifer", "demonic sigil mould" },
                    },
                    {
                        text = "Talk to Matthew.",
                        chat = "3 Do you know what happened to Josef?",
                        npcs = { "Matthew" },
                    },
                    {
                        text = "Go to any furnace and smelt a demonic sigil.",
                        chat = "1 Make Demonic sigil",
                        npcs = { "demonic sigil" },
                        subs = {
                            { text = "Your black outfit can be discarded at this point and replaced with combat gear. Keep Silverlight for the duration of the quest." },
                        },
                    },
                    {
                        text = "Talk to the clay golem outside the ruins about last night.",
                        chat = "3 Did you see anything happen last night?",
                        npcs = { "clay golem" },
                    },
                    {
                        text = "Look in the nearby Broken kilns for a book until you have found the Demonic tome (there's a broken kiln north of the Rug Merchant and one behind the walls east of the staircase that are easy to miss).",
                        npcs = { "Demonic tome" },
                    },
                    {
                        text = "Talk to Matthew back in the lair.",
                        npcs = {},
                    },
                    {
                        text = "Go north to talk to Denath and write down the incantation he tells you.",
                        chat = "4",
                        npcs = {},
                    },
                    {
                        text = "Complete the circle and click the sigil to chant the incantation. Be sure to remember it, as you’ll need it again later in the quest.",
                        npcs = {},
                    },
                    {
                        text = "Be sure to take the sigil from the floor, or you will have to make a new one at a furnace.",
                        npcs = {},
                    },
                    {
                        text = "Enter the portal and take Tanya's sigil.",
                        npcs = {},
                    },
                    {
                        text = "Tell Evil Dave to return to the lair - you should have 4 sigils now.",
                        chat = "2 You've got to get back to the throne room!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Rallying the troops", needed = {},
                steps = {
                    {
                        text = "Go up the stairs, talk to Father Badden and Father Reen.",
                        chat = "3 Oh, don't be so simple-minded!",
                        npcs = { "Father Badden", "Father Reen" },
                    },
                    {
                        text = "Talk to the golem.",
                        chat = "4 [use strange implement]",
                        npcs = {},
                    },
                },
            },
            {
                title = "The final fight", needed = {},
                steps = {
                    {
                        text = "Return to the throne room downstairs.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Matthew to start the incantation.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Form the circle and Chant demonic sigil and say the incantation in reverse. (If you have forgotten the incantation, it can be found on page 6 of the demonic tome.)",
                        npcs = { "demonic tome" },
                    },
                    {
                        text = "Kill the demon with the Silverlight (dyed). After defeating it, you will have the Darklight equipped.",
                        npcs = { "Silverlight (dyed)" },
                        subs = {
                            { text = "You can damage the demon with any combat style, but you must equip the Silverlight (dyed) as it dies." },
                        },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "sheep_herder", name = "Sheep Herder", wiki = "Sheep Herder/Quick guide",
        required = { "100 coins" },
        recommended = {},
        sections = {
            {
                title = "Starting out", needed = {},
                steps = {
                    {
                        text = "Talk to Councillor Halgrive south of the Ardougne church and north of the zoo.",
                        chat = "1 What's wrong? / Accept",
                        npcs = { "Councillor Halgrive", "Ardougne", "Ardougne Zoo" },
                    },
                    {
                        text = "Talk to Doctor Orbon inside the church and buy a pair of clothes for 100 coins.",
                        chat = "2 Talk about something else. / 2 Ok, I'll take it.",
                        npcs = { "Doctor Orbon" },
                    },
                },
            },
            {
                title = "Herding the sheep", needed = {},
                steps = {
                    {
                        text = "Return to the lodestone and go west until you reach the fenced enclosure with a stone building and incinerator (looks like a furnace). It is south of the fishing guild.",
                        npcs = {},
                    },
                    {
                        text = "Equip the plague jacket and trousers and enter the gate.",
                        npcs = { "plague jacket", "Plague trousers" },
                    },
                    {
                        text = "Pick up the cattleprod inside the stone enclosure, equip it.",
                        npcs = { "cattleprod" },
                    },
                    {
                        text = "Prod 1 of each colour sheep in and through the incinerator pen's gate. If the sheep are stuck, simply switch worlds.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Euthanising the sheep", needed = {},
                steps = {
                    {
                        text = "Enter the pen and use the sheep feed on each of them.",
                        npcs = { "sheep feed" },
                    },
                    {
                        text = "Take all 4 bones, then use them on the incinerator.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Return to Councillor Halgrive.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "sheep_shearer_miniquest", name = "Sheep Shearer (miniquest)", wiki = "Sheep Shearer (miniquest)/Quick guide",
        required = { "20 balls of wool (unnoted, can be obtained during the miniquest)" },
        recommended = {},
        sections = {
            {
                title = "If you already have the 20 unnoted balls of wool", needed = {},
                steps = {
                    {
                        text = "Talk to Fred the Farmer north of Lumbridge.",
                        chat = "3 I'm looking for work. / 1 It takes all sorts, I suppose. / Accept / 1 Of course! / 1 I'm something of an expert, actually.",
                        npcs = { "Fred the Farmer", "Lumbridge" },
                    },
                    {
                        text = "Fred takes the 20 balls of wool.",
                        npcs = { "balls of wool" },
