                    {
                        text = "Talk to Fred and hand them in.",
                        chat = "1 I have some balls of wool for you.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "Sheep Shearer (miniquest)",
                        npcs = { "Sheep Shearer (miniquest) (achievement)" },
