    {
        key = "shield_of_arrav", name = "Shield of Arrav", wiki = "Shield of Arrav/Quick guide",
        required = { "20 coins" },
        recommended = {},
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to Reldo in the Varrock Palace library.",
                        chat = "1 I'm in search of a quest. / Accept",
                        npcs = { "Reldo", "Varrock Palace" },
                    },
                    {
                        text = "Search the east side of the centre bookcases (with the navy blue book) for The Shield of Arrav book, then read it.",
                        npcs = { "The Shield of Arrav book" },
                    },
                },
            },
            {
                title = "The Phoenix Gang", needed = {},
                steps = {
                    {
                        text = "Talk to Reldo and ask about the Phoenix Gang.",
                        chat = "1 Do you know where I can find the Phoenix Gang?",
                        npcs = { "Phoenix Gang" },
                        tile = { x = 3244, y = 3386, plane = 0 },
                    },
                    {
                        text = "Talk to Baraek who is located in the north-east of Varrock square, and give him 10 coins. Ask him every question available.",
                        chat = "1 Can you tell me where I can find the Phoenix Gang? / 1 Alright. Have 10 gold coins. / 2 Thanks!",
                        npcs = { "Baraek", "coins" },
                    },
                    {
                        text = "Travel to the Phoenix Gang Hideout which is located south of Aubury's Rune Shop. It will be marked by a dungeon link to the Misthalin Underground on the map.",
                        npcs = { "Phoenix Gang Hideout", "Aubury's Rune Shop" },
                    },
                    {
                        text = "Climb down the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Straven and ask to join. Tell him you know who he is.",
                        chat = "1 I know who you are! / 1 I'd like to offer you my services.",
                        npcs = { "Straven" },
                    },
                    {
                        text = "Go to the Blue Moon Inn which is just north of Varrock's southern entrance.",
                        npcs = { "Blue Moon Inn", "Varrock" },
                    },
                    {
                        text = "Kill Jonny the beard.",
                        npcs = { "Jonny the beard" },
                    },
                    {
                        text = "Grab the Intel report that he drops.",
                        npcs = { "Intel report" },
                    },
                    {
                        text = "Return to the hideout and talk to Straven.",
                        npcs = { "Straven" },
                    },
                    {
                        text = "Search the chest in the south-west corner of the hideout for a broken shield.",
                        npcs = { "Broken shield (right)" },
                    },
                    {
                        text = "After climbing back up the ladder, enter the house east of the Phoenix Gang Hideout and go up the ladder there.",
                        npcs = {},
                    },
                    {
                        text = "Pick up the two Phoenix crossbows on the floor, you will need these for the next gang.",
                        npcs = { "Phoenix crossbow" },
                    },
                },
            },
            {
                title = "The Black Arm Gang", needed = {},
                steps = {
                    {
                        text = "Talk to Charlie the Tramp located just north of Varrock's southern entrance. Ask him what's down the alley.",
                        chat = "3 Do you know where I can find the Black Arm Gang hideout? / 1 That sounds fair. (Pay 10 gold.)",
                        npcs = { "Charlie the Tramp", "Varrock" },
                    },
                    {
                        text = "Follow the alley to the west and enter the building.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Katrine.",
                        chat = "1 I've heard you're the Black Arm Gang. / Any / 1 I want to become a member of your gang. / 1 Well, you can give me a try, can't you? / 1 No problem. I'll get you two phoenix crossbows.",
                        npcs = { "Katrine" },
                    },
                    {
                        text = "Talk to Katrine again to give her the crossbows.",
                        npcs = { "Katrine" },
                    },
                    {
                        text = "Head north through the door and climb up the staircase.",
                        npcs = {},
                    },
                    {
                        text = "Open and search the cupboard on the south-eastern wall for the other broken shield piece.",
                        npcs = { "Broken shield (left)" },
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Use one half of the shield on the other for a restored shield.",
                        npcs = { "restored shield" },
                    },
                    {
                        text = "Talk to King Roald located in the immediate east room of the Varrock Palace.",
                        chat = "1 Talk about the Shield of Arrav.",
                        npcs = { "King Roald", "Varrock Palace" },
                        subs = {
                            { text = "If you have completed Priest in Peril", chat = "2 Talk about the Shield of Arrav." },
                        },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "Shield of Arrav",
                        npcs = { "Shield of Arrav (achievement)" },
                    },
                },
            },
        },
    },
    {
        key = "shilo_village", name = "Shilo Village", wiki = "Shilo Village/Quick guide",
        required = { "A spool of bronze wire", "3 regular bones (can be obtained during quest by killing level 44–46 skeletal undead ones)", "Can be bought from Jiminua's Jungle Store (the general store north-west of Tai Bwo Wannai):", "A rope", "A chisel (the tool belt will not work for certain parts)", "A torch (or any other light source, such as a lantern can be used, but be aware that you WILL lose this item)" },
        recommended = { "Level 43 Prayer for Protect from Melee", "An active Karamja lodestone, juju teleport spiritbags, dramen staff, spirit graahks, and Tai Bwo Wannai Teleport for teleportation around Karamja.", "A salve amulet or salve amulet (e)", "An antipoison (in case you are poisoned by a wandering warrior)", "Some food", "Some energy potions" },
        sections = {
            {
                title = "Starting out", needed = {},
                steps = {
                    {
                        text = "Teleport to Karamja (shortest teleport is CKR) and run far south/southeast to the southeast corner of Shilo Village.",
                        npcs = { "Karamja", "Shilo Village (location)" },
                    },
                    {
                        text = "Speak to Mosol Rei near the Broken cart. He will give you a wampum belt.",
                        chat = "1 Why do I need to run? / 1 Rashiliyia? Who is she? / 1 What can we do? / 4 I'll go see the Shaman. / Accept",
                        npcs = { "Mosol Rei", "wampum belt" },
                    },
                    {
                        text = "Teleport to the Karamja lodestone and run southeast to Trufitus, northeast of Tai Bwo Wannai Village, west of the hardwood grove.",
                        npcs = { "Karamja lodestone", "Trufitus", "hardwood grove" },
                    },
                    {
                        text = "Use the belt on Trufitus. Tell him you're going to search for \"Ah Za Rhoon\".",
                        chat = "2 Mosol Rei said something about a legend? / 1 Why was it called Ah Za Rhoon? / 3 I am going to search for Ah Za Rhoon! / 1 Yes, I will seriously look for Ah Za Rhoon and I'd appreciate your help.",
                        npcs = { "Trufitus" },
                        subs = {
                            { text = "If you don't yet have a chisel, a rope and torch, you should get those now from Jiminua's Jungle Store. You may also craft bronze wire at the nearby anvil." },
                        },
                    },
                },
            },
            {
                title = "The mound", needed = { "Torch and rope" },
                steps = {
                    {
                        text = "Travel east of Trufitus' hut, cross a wooden log and then head south to the mound of earth surrounded by three dead trees, Ah Za Rhoon.",
                        npcs = { "a wooden log", "Mound of earth (Karamja)", "Ah Za Rhoon" },
                    },
                    {
                        text = "Search the mound of earth and select excavate.",
                        chat = "1 Try to excavate the mound.",
                        npcs = { "Mound of earth (Karamja)" },
                    },
                    {
                        text = "Use a lit torch on the fissure.",
                        npcs = { "lit torch", "fissure" },
                        subs = {
                            { text = "To obtain a lit torch, light the torch in the backpack." },
                        },
                    },
                    {
                        text = "Use a rope on the fissure.",
                        npcs = { "rope" },
                    },
                    {
                        text = "Search the fissure, climb down.",
                        chat = "1 Yes, I'll give it a go!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Ah Za Rhoon", needed = {},
                steps = {
                    {
                        text = "Search the cave in and wiggle through the rocks to proceed to the second area.",
                        chat = "1 Yes, I'll wriggle through.",
                        npcs = { "Cave in (Ah Za Rhoon)" },
                    },
                    {
                        text = "After wiggling through, follow along the west side of the wall and search the loose rocks against the northwestern wall for a tattered scroll.",
                        chat = "1 Yes, I'll carefully move the rocks to see what's behind them.",
                        npcs = { "loose rocks", "tattered scroll" },
                        subs = {
                            { text = "You might fail and take damage, retry until you succeed." },
                        },
                    },
                    {
                        text = "Search the old sacks in the far southeast corner for a crumpled scroll.",
                        npcs = { "old sacks", "crumpled scroll" },
                    },
                    {
                        text = "Search the ancient gallows to the north for the Zadimus corpse.",
                        chat = "2 Yes, I may find something else on the corpse.",
                        npcs = { "ancient gallows", "Zadimus corpse" },
                    },
                    {
                        text = "Read the scroll.",
                        chat = "1 Yes please.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Burial", needed = {},
                steps = {
                    {
                        text = "Use the Karamja lodestone/Tai Bwo Wannai teleport to get back to Trufitus.",
                        npcs = {},
                    },
                    {
                        text = "Use the tattered scroll and crumpled scroll on Trufitus.",
                        npcs = { "tattered scroll", "crumpled scroll" },
                    },
                    {
                        text = "Use the Zadimus corpse on Trufitus.",
                        npcs = { "Zadimus corpse" },
                    },
                    {
                        text = "Ask about the sacred ground.",
                        chat = "1 Is there any sacred ground around here?",
                        npcs = {},
                    },
                    {
                        text = "Walk west to the nearby Tribal Statue. Bury the corpse then talk to the Spirit of Zadimus for the bone shard.",
                        npcs = { "Tribal Statue", "bone shard" },
                    },
                    {
                        text = "Use the bone shard on Trufitus.",
                        chat = "1 It appeared when I buried Zadimus' corpse. / 1 He said something after he gave it to me. / 1 The spirit said something about keys and kin?",
                        npcs = {},
                    },
                    {
                        text = "Talk to Trufitus. Ensure Trufitus mentions the need to find the Tomb of Bervirius.",
                        chat = "2 I need help with Bervirius.",
                        npcs = { "Tomb of Bervirius" },
                    },
                },
            },
            {
                title = "Cairn Island", needed = { "Chisel, bronze wire (or a bronze bar to make the wire), and three backpack spaces" },
                steps = {
                    {
                        text = "Head southwest to Cairn Isle by climbing the rocks and going across the bridge. Be careful, you can sometimes fall - use the Surge ability to bypass this.",
                        npcs = { "Cairn Isle", "Surge" },
                        tile = { x = 2765, y = 2976, plane = 0 },
                    },
                    {
                        text = "Search the well stacked rocks to the north to enter the Tomb of Bervirius. If you fail search again until you are able to enter.",
                        chat = "1 Yes please, I can think of nothing nicer!",
                        npcs = { "well stacked rocks", "Tomb of Bervirius" },
                    },
                    {
                        text = "Inside, run south and search the tomb dolmen to receive three items: sword pommel, locating crystal, and Bervirius notes.",
                        npcs = { "tomb dolmen", "sword pommel", "locating crystal", "Bervirius notes" },
                        subs = {
                            { text = "If you do not have enough space the notes will drop on the ground." },
                        },
                    },
                    {
                        text = "Read all 3 options on the Bervirius notes.",
                        npcs = {},
                    },
                    {
                        text = "Use the chisel on the sword pommel to create bone beads (the chisel on the tool belt will not work).",
                        npcs = { "chisel", "bone beads", "tool belt" },
                    },
                    {
                        text = "Use the bone beads on the bronze wire to create beads of the dead.",
                        npcs = { "bronze wire", "beads of the dead" },
                        subs = {
                            { text = "You can make the bronze wire from a bronze bar at an anvil near Trufitus." },
                        },
                    },
                },
            },
            {
                title = "Rashiliyia's Tomb", needed = { "Chisel, bone shard, beads of the dead, and 3 regular bones (can be obtained from monsters in cave)" },
                steps = {
                    {
                        text = "Travel east of Trufitus' hut, over the agility log and run north, to the general area of The Shaikahan. (Fairy ring: DKP)",
                        npcs = { "Trufitus", "The Shaikahan" },
                    },
                    {
                        text = "Search the foliage, then attempt to open the Ancient Door.",
                        npcs = { "foliage", "Ancient Door (Rashiliyia's Tomb)" },
                    },
                    {
                        text = "Use a chisel on the bone shard.",
                        npcs = { "bone shard" },
                    },
                    {
                        text = "Equip the beads of the dead.",
                        npcs = {},
                    },
                    {
                        text = "Use the bone key on the door to open it.",
                        npcs = { "Bone key (Shilo Village)" },
                    },
                    {
                        text = "Open the ancient metal gate.",
                        npcs = { "ancient metal gate" },
                    },
                    {
                        text = "Climb down the rock.",
                        npcs = { "Rock (Rashiliyia's Tomb)" },
                    },
                    {
                        text = "Run to the south west corner and use 3 bones on the tomb doors. Be careful not to bury them instead.",
                        npcs = { "bones" },
                    },
                    {
                        text = "Open the doors and search the tomb dolmen.",
                        npcs = { "tomb dolmen" },
                    },
                    {
                        text = "Kill all 3 forms of Nazastarool. The stalagmites to the east of the tomb dolmen can be used as a safe spot.",
                        npcs = { "Nazastarool" },
                    },
                    {
                        text = "Search the tomb dolmen again for a Rashiliyia corpse.",
                        npcs = { "Rashiliyia corpse" },
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Travel back to the Tomb of Bervirius on Cairn Isle.",
                        npcs = { "Tomb of Bervirius", "Cairn Isle" },
                    },
                    {
                        text = "Use the Rashiliyia corpse on the tomb dolmen.",
                        npcs = { "Rashiliyia corpse", "tomb dolmen" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
