    {
        key = "sliske_s_endgame", name = "Sliske's Endgame", wiki = "Sliske's Endgame/Quick guide",
        required = { "A disguise with which to enter the Black Knights' Fortress", "Alternatively, the Dulcin armour cosmetic override or the teleport option on the Skull of Remembrance can be used", "Alternatively, the Communication device from Dishonour among Thieves may be used to teleport to Zamorak" },
        recommended = { "Combat equipment and food", "Heart of Gielinor quick access; such as The Heart teleport or a desert amulet 2 or above", "Armadyl's Tower quick access; an Armadylean token, skills necklace or activated Port Sarim lodestone", "Black Knights' Fortress quick access; mind altar teleport or a Skull of Remembrance" },
        sections = {
            {
                title = "Gathering the party", needed = { "an Armadylean token or skills necklace to the Crafting Guild for quick access to Armadyl's Tower, mind altar teleport for quick access to the Black Knight's Fortress" },
                steps = {
                    {
                        text = "Talk to Relomia in Draynor Village.",
                        chat = "1 Sliske's Endgame. / 1 Where are the gods? / Accept",
                        npcs = { "Relomia", "Draynor Village" },
                    },
                    {
                        text = "Talk to each of the gods.",
                        npcs = {},
                        subs = {
                            { text = "Talk to Seren and Zaros up in the Tower of Voices by using the stairs north-east of the Prifddinas lodestone.", chat = "1 Speak with Seren about Sliske's Endgame." },
                            { text = "Talk to Saradomin in the throne room on the east side of the 3rd floor of White Knights' Castle." },
                            { text = "He may not speak to you if you have the title active. Lobbying may be necessary if he only insults you." },
                            { text = "Talk to Armadyl on the roof of his tower north-west of Port Sarim." },
                            { text = "Go up the tower by the teleporter." },
                            { text = "Climb up the stairs on the west side to the roof." },
                            { text = "Talk to Zamorak on the 2nd floor of Black Knights' Fortress or at Zamorak's hideout." },
                            { text = "You may get there by using the mind altar teleport to mind altar, a communication device, or a Skull of Remembrance." },
                            { text = "Talk to Icthlarin in Death's office by entering through portal in the north of Draynor Village.", chat = "2 Speak to Death about Sliske's Endgame" },
                            { text = "You cannot go from War's Retreat directly." },
                        },
                    },
                    {
                        text = "Talk to Relomia in Draynor Village.",
                        chat = "1 Sliske's Endgame.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The final member", needed = { "Weapon to defeat Nomad" },
                steps = {
                    {
                        text = "Dismiss any familiar or follower you may have following you.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Relomia in the Heart of Gielinor campsite (west of the entrance, outside of the Heart of Gielinor).",
                        chat = "1 Yes, I am prepared. / Any / Any",
                        npcs = { "Heart of Gielinor" },
                    },
                    {
                        text = "Defeat Nomad. He uses melee/mage and doesn't use special attacks.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Maze and puzzles", needed = {},
                steps = {
                    {
                        text = "Run through both the mazes to the exit on the north-east. The solutions are given below.",
                        npcs = {},
                    },
                    {
                        text = "The green lines show the main path to follow, and the blue lines lead to puzzle rooms off the main map that must be completed.",
                        npcs = {},
                        subs = {
                            { text = "See the puzzles section below with help solving the puzzles." },
                            { text = "Return to the green paths after completing the puzzles." },
                        },
                    },
                    {
                        text = "The orange lines lead to optional cutscenes.",
                        npcs = {},
                    },
                    {
                        text = "These maps and your minimap may not line up exactly until the puzzle rooms have been completed as completing puzzle rooms rotates parts of the labyrinth.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Routes of the maze", needed = { "An accessible colour palette for the map solution can be found at Sliske's Labyrinth." },
                steps = {
                },
            },
            {
                title = "Puzzles", needed = { "The location of the puzzle rooms are constant, but the puzzles themselves are different for each player." },
                steps = {
                },
            },
            {
                title = "Rotation puzzles", needed = {},
                steps = {
                    {
                        text = "Click the Solution panel to view the Clue",
                        npcs = {},
                    },
                    {
                        text = "Use the table below to find the Solution",
                        npcs = {},
                    },
                    {
                        text = "Rotate the Shadow casters till they match the solution.",
                        npcs = {},
                        subs = {
                            { text = "Misery loves company. — All four casters need sad faces" },
                            { text = "You and I are beautifully broken. The others resent our superiority — Sad faces on the south casters and broken faces on the north casters." },
                            { text = "When the sun rises, we are happy. When the sun sets, we are sad. — Happy faces on both of the east casters, sad faces on the west casters." },
                            { text = "I'm bored of helping you, you can figure this one out on your own — North-west: Neutral - north-east: Happy - south-east: Sad - south-west: Broken" },
                            { text = "I'm not a morning person; nor am I a mourning person — Sad faces on the eastern wall, leave the western two without masks." },
                            { text = "Never let anyone see how you truly feel, they will use it against you — All neutral expressions on all four casters" },
                        },
                    },
                },
            },
            {
                title = "Projection puzzles", needed = {},
                steps = {
                    {
                        text = "Kill any wights in the room to obtain missing Masks (they will drop a Mask of Glee, Mask of Sorrow or Mask of Indifference)",
                        npcs = { "Mask of Glee", "Mask of Sorrow", "Mask of Indifference" },
                    },
                    {
                        text = "Click the Viewing panel to begin the projection mode",
                        npcs = {},
                    },
                    {
                        text = "If it says one of the projectors are damaged, repair them",
                        npcs = {},
                    },
                    {
                        text = "Rotate the Shadow casters till it forms the solution image shown on the right (a complete Sliske mask)",
                        npcs = {},
                    },
                },
            },
            {
                title = "Mask replacement puzzles", needed = {},
                steps = {
                    {
                        text = "Click the solution panel to view the Clue, then view the Solution from the table in the section above",
                        npcs = {},
                    },
                    {
                        text = "Kill any wights in the room to obtain missing Masks (they will drop a Mask of Glee, Mask of Sorrow or Mask of Indifference)",
                        npcs = { "Mask of Glee", "Mask of Sorrow", "Mask of Indifference" },
                    },
                    {
                        text = "Take the mask from all the casters that don't match the description, and re-attach the mask on another caster till it matches",
                        npcs = {},
                    },
                    {
                        text = "When all the casters are matching the solution, the puzzle will be solved",
                        npcs = {},
                    },
                },
            },
            {
                title = "Spotlight puzzles", needed = {},
                steps = {
                    {
                        text = "Stand in the spotlight",
                        npcs = {},
                    },
                },
            },
            {
                title = "Reaching the stone", needed = {},
                steps = {
                    {
                        text = "At the end of the maze, ascend the stairs",
                        npcs = {},
                    },
                    {
                        text = "Participate in the race and go through the dialogue and cutscenes",
                        chat = "Any",
                        npcs = {},
                    },
                },
            },
            {
                title = "The final battle", needed = {},
                steps = {
                    {
                        text = "Use the purple exit portal to leave, and prepare for a tough fight with the best combat gear you have.",
                        npcs = {},
                        subs = {
                            { text = "Tier 90 armour like masterwork equipment greatly helps." },
                            { text = "Bring a beast of burden with high healing foods." },
                        },
                    },
                    {
                        text = "Return to Relomia using The Heart teleports and resume the battle against Sliske",
                        npcs = { "The Heart teleport" },
                    },
                    {
                        text = "The fight is divided into 3 phases, at the end of each phase you can bank and return to resume from that checkpoint",
                        npcs = {},
                    },
                },
            },
            {
                title = "Phase 1", needed = {},
                steps = {
                    {
                        text = "Fight against wights of increasing difficulty, kill enough of them to increase the progress bar on top.",
                        npcs = {},
                        subs = {
                            { text = "Use Deflect Melee or Deflect Ranged depending on the types of wights you are fighting" },
                            { text = "Be aware that all remaining unstable wight footsoldiers will explode at the end of the wave, potentially causing death if the player is surrounded but you will continue onto the next wave when you return." },
                        },
                    },
                },
            },
            {
                title = "Phase 2", needed = {},
                steps = {
                    {
                        text = "Kill Nomad.",
                        npcs = {},
                        subs = {
                            { text = "Use Deflect Ranged while fighting him." },
                            { text = "Nomad plants mines and Gregorovic rains damage on the arena. Make sure to walk off of marked tiles." },
                        },
                    },
                    {
                        text = "Kill Linza the Disgraced.",
                        npcs = {},
                        subs = {
                            { text = "Use Deflect Melee while fighting her." },
                            { text = "Linza reflects damage which is less deadly after she's the only surviving boss." },
                            { text = "She also has a blue charged bar that appears above her head and does a very high damage move. She will also bind before she does this move so have surge or freedom ready. It is recommended to dodge this attack." },
                        },
                    },
                    {
                        text = "Kill Gregorovic.",
                        npcs = {},
                        subs = {
                            { text = "Use Deflect Ranged while fighting him." },
                            { text = "The spirits that spawn towards Gregorovic will heal him if they reach him. Kill them before they touch him." },
                        },
                    },
                },
            },
            {
                title = "Phase 3", needed = {},
                steps = {
                    {
                        text = "Kill Sliske. You cannot use deathtouched darts to kill Sliske.",
                        npcs = { "Sliske", "deathtouched dart" },
                        subs = {
                            { text = "Use Deflect Magic throughout the fight as the majority of the damage will be magic classed. Keep in mind that prayer points are drained faster than normal in this fight." },
                            { text = "If you are having trouble, wearing the Armour of Trials and wielding Vanquish can help greatly has it can provide a 25% defensive and offensive bonus during the fight if you die 5 times in a row." },
                            { text = "Beware of his special attack where several shadow pits will appear below your feet. Step away to avoid significant damage. He will summon 4 shadow pits in the first round, 5 in the second, and 4 in the subsequent two rounds. On rounds 3 and 4, Sliske's attacks will predict where you are walking towards on the 4th and final shadow pit." },
                            { text = "Attack Sliske until he reaches 10,000 health, he will teleport away." },
                            { text = "Destroy the Power Source in the centre of the room." },
                            { text = "Attack Sliske until he reaches 10,000 health again." },
                            { text = "Enter one of the rifts. Sliske will bring you back into the arena." },
                            { text = "Attack Sliske until he reaches 10,000 health again." },
                            { text = "Jump on the rock formation in front of Sliske." },
                            { text = "Attack Sliske until he reaches 10,000 health again." },
                            { text = "Defeat Sliske one final time. You have unlimited life points and adrenaline and all ability cooldowns are halved. (If you have Onslaught Ability you can kill him automatically)" },
                        },
                    },
                    {
                        text = "Talk to Jas. (Except insulting Jas - does not allow you to continue)",
                        chat = "Any / Any",
                        npcs = { "Jas" },
                    },
                    {
                        text = "Talk to the gods on the surface.",
                        chat = "Any / Any / Any",
                        npcs = {},
                    },
                    {
                        text = "Return to Relomia in Draynor.",
                        chat = "1 Sliske's Endgame. / Any",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "smoking_kills", name = "Smoking Kills", wiki = "Smoking Kills/Quick guide",
        required = { "Ranged/Magic/Necromancy weapons or spells (must kill skeletons without melee)", "Catspeak amulet", "Kitten, cat, overgrown cat, hellcat, wily cat, or lazy cat", "Ghostspeak amulet", "Earmuffs", "Face mask" },
        recommended = { "Level 60 Combat", "Level 40 Prayer", "Ranged/Magic/Necromancy equipment and food", "Desert heat protection (completing Crocodile Tears grants immunity)", "Player-owned house in Pollnivneach, Pollnivneach Teleport scroll or a few coins for Magic carpet rides", "Ring of slaying (for teleportation to Pollnivneach)", "Rope (if you haven't completed Dealing with Scabaras and have at least Level 40 Agility)" },
        sections = {
            {
                title = "Starting out", needed = { "Catspeak amulet" },
                steps = {
                    {
                        text = "Head to Pollnivneach. You can use the magic carpet network from Shantay Pass or Al Kharid lodestone to travel to Al Kharid and head south-east or Teleport to your player owned house and exit via Pollniveach.",
                        npcs = { "Pollnivneach", "magic carpet", "Shantay Pass", "Al Kharid lodestone", "Al Kharid" },
                    },
                    {
                        text = "Speak to Sumona in Pollnivneach (without a cat pet out).",
                        chat = "Accept",
                        npcs = { "Sumona", "Pollnivneach" },
                        tile = { x = 3358, y = 2993, plane = 0 },
                    },
                    {
                        text = "Equip your catspeak amulet.",
                        npcs = {},
                    },
                    {
                        text = "Run south to the well in the town centre.",
                        npcs = {},
                    },
                    {
                        text = "Attempt to climb down the well.",
                        npcs = {},
                    },
                    {
                        text = "Speak to the cat, finish all prompts.",
                        npcs = {},
                        subs = {
                            { text = "If you do not wear a catspeak amulet or skip the conversation, you will be unable to open the sealed tomb door later in the quest." },
                        },
                    },
                },
            },
            {
                title = "Finding the tomb", needed = { "Bring all items needed for the next section, including cat of any sort, catspeak amulet, ghostspeak amulet, combat gear (ranged, magic, or necromancy, or simply ignore three low damage ranged minions for a few seconds), earmuffs, facemask" },
                steps = {
                    {
                        text = "Travel to Sophanem by either one of the following methods.",
                        npcs = { "Sophanem" },
                        tile = { x = 3409, y = 2812, plane = 1 },
                        subs = {
                            { text = "Use the Magic carpet Network" },
                            { text = "Menaphos lodestone teleport, then run east across the bridge to Sophanem (requires completion of The Jack of Spades and Contact!)" },
                        },
                    },
                    {
                        text = "Head southeast towards the sea/swampland",
                        npcs = {},
                    },
                    {
                        text = "Enter the swamp using the entrance at the south end of the swamp, by the seashore.",
                        npcs = {},
                    },
                    {
                        text = "Make your way to the north-west part of the swamp, \"climb fallen pillar\", and go up the stairs.",
                        npcs = {},
                        subs = {
                            { text = "Optional: Go west, \"climb low wall\", use your rope on the \"rock\", jutting out over the edge - this will give you quicker access in the future." },
                        },
                    },
                    {
                        text = "Walk north past the archaeologist's fire, through the opening between the cliffs.",
                        npcs = {},
                    },
                    {
                        text = "Search the western wall for a sealed door to enter the dungeon.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Inside the tomb", needed = { "Cat of any sort, catspeak amulet, ghostspeak amulet, combat gear (ranged or magic recommended), earmuffs, facemask" },
                steps = {
                    {
                        text = "Drop your cat, search the western \"holey wall\". Agree, and your cat will enter, opening the wall.",
                        npcs = {},
                    },
                    {
                        text = "Go west, kill (or ignore) the 3 skeletons to the south with magic/range/necromancy.",
                        npcs = {},
                    },
                    {
                        text = "Destroy the broken door until you can walk through it.",
                        npcs = {},
                    },
                    {
                        text = "Search the west wall (not the odd markings on the east wall) twice to temporarily disable and pass two traps.",
                        npcs = {},
                    },
                    {
                        text = "Enter the door to the north.",
                        npcs = {},
                    },
                    {
                        text = "Kill the zombies and skeletons.",
                        npcs = { "Zombie (Smoking Kills)", "Skeleton (Smoking Kills)" },
                    },
                    {
                        text = "After about 10-20 seconds, a level 77 mummy warrior will spawn. Kill it and take the.",
                        npcs = {},
                    },
                    {
                        text = "Open the door to the east, pull the lever on the northern wall.",
                        npcs = {},
                    },
                    {
                        text = "Return to the starting room (traps on this side are now permanently disabled)",
                        npcs = {},
                    },
                    {
                        text = "Repeat steps on the other side.",
                        npcs = {},
                        subs = {
                            { text = "Go east, kill (or ignore) the 3 skeletons to the south with magic/range/necro." },
                            { text = "Destroy the broken door." },
                            { text = "Search the east wall (not odd markings on the west wall) twice to disable and pass two traps." },
                            { text = "Enter the door to the north." },
                            { text = "Kill the zombies and skeletons." },
                            { text = "After about 10-20 seconds, a level 77 mummy warrior will spawn. Kill it and take the." },
                            { text = "Use the key on the door to the west, pull the lever on the northern wall." },
                        },
                    },
                    {
                        text = "Return to the starting room (traps on this side are now permanently disabled).",
                        npcs = {},
                    },
                    {
                        text = "Walk north, all traps have been disabled and can be ignored.",
                        npcs = {},
                    },
                    {
                        text = "Equip your and talk to Catolax.",
                        npcs = { "Catolax" },
                    },
                    {
                        text = "Use your on your to create.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The final fight", needed = { "Masked earmuffs, combat gear, food" },
                steps = {
                    {
                        text = "Return to Pollnivneach.",
                        npcs = { "Pollnivneach" },
                    },
                    {
                        text = "Equip your masked earmuffs and combat gear.",
                        npcs = {},
                    },
                    {
                        text = "Enter the well in the town centre.",
                        npcs = {},
                    },
                    {
                        text = "Head north, kill a mighty banshee to get a. The drop must be manually picked up; it will not appear in the area loot interface.",
                        npcs = { "mighty banshee" },
                    },
                    {
                        text = "Ensure any follower is dismissed and auto-retaliate is turned off first, then run all the way north to the large blue/purple wavering mystic barrier and pass through it.",
                        npcs = { "wavering mystic barrier" },
                        subs = {
                            { text = "Do not click on anything else while the cutscene is in motion, or you will go back outside the barrier and will need to acquire another banshee voice." },
                        },
                    },
                    {
                        text = "After the cutscene, attack the Banshee mistress. She is weak to bolts, so using range is recommended if you're lower-levelled.",
                        npcs = { "Banshee mistress" },
                        subs = {
                            { text = "Enable the Protect from Ranged prayer after she gets to 50% health." },
                        },
                    },
                    {
                        text = "Finish the fight and watch the cutscene.",
                        npcs = {},
                        subs = {
                            { text = "If you click on anything else, you will go outside the barrier, but you will not have to fight again; you can easily go back inside the barrier to continue the last cutscene." },
                        },
                    },
                    {
                        text = "Return to Pollnivneach (you can climb out of the well).",
                        npcs = { "Pollnivneach" },
                    },
                    {
                        text = "Pick up your cat if you have not already done so.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Sumona again to complete the quest.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "Smoking Kills",
                        npcs = { "Smoking Kills (achievement)" },
                    },
                    {
                        text = "Desert achievements",
                        npcs = { "Desert achievements" },
                        subs = {
                            { text = "Hard" },
                            { text = "More Fletcher than Sumona" },
                            { text = "Drafty in Here" },
                            { text = "Elite" },
                            { text = "Staff on Stryke" },
                            { text = "Special Slayer Delivery" },
                        },
                    },
                    {
                        text = "Order of Slayers",
                        npcs = { "Order of Slayers" },
                    },
                },
            },
        },
