    {
        key = "some_like_it_cold", name = "Some Like It Cold", wiki = "Some Like It Cold/Quick guide",
        required = { "Clockwork suit (if not using the clockmaker's bench in player-owned house to make the costumes)", "At least 5 backpack spaces for the ransom letter and materials to make costumes for Ping and Pong", "You will be required to deposit all your items and worn items at some point during the quest." },
        recommended = { "Clockmaker's bench 3 in your player-owned house", "Teleport to house", "Enchanted Lyre for teleports to Rellekka" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to Chuck the polar bear in Ardougne Zoo.",
                        npcs = { "Chuck", "Ardougne Zoo" },
                    },
                    {
                        text = "Speak to him again.",
                        chat = "1 Some Like It Cold Quest / Accept",
                        npcs = {},
                    },
                    {
                        text = "Speak to him a final time to be teleported",
                        chat = "1 Some Like It Cold Quest / 1 Yes",
                        npcs = {},
                    },
                },
            },
            {
                title = "The seal", needed = {},
                steps = {
                    {
                        text = "After being teleported by Chuck, head west to the seals.",
                        npcs = {},
                    },
                    {
                        text = "Wake up the seal that can be interacted with.",
                        chat = "3 I'm looking for a polar bear. / 1 How can I entertain you?",
                        npcs = {},
                    },
                    {
                        text = "Perform the Dance or Jump For Joy emote.",
                        npcs = { "Dance", "Jump For Joy", "emote" },
                    },
                    {
                        text = "Talk to the seal.",
                        chat = "1 What's wrong with penguins? / 2 Where does your band live?",
                        npcs = {},
                    },
                    {
                        text = "Travel-Iceberg the smaller boat to the north-east.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Ping & Pong. You don't need to be in your tuxedo for this.",
                        npcs = { "Ping & Pong" },
                    },
                    {
                        text = "After receiving the items from them, do one of the following:",
                        npcs = {},
                        subs = {
                            { text = "Option one" },
                            { text = "Use a Clockmaker's bench 4 in a player-owned house to make their rock costume." },
                            { text = "To return, use the Fremennik Province lodestone and head north to board the ship to iceberg." },
                            { text = "Option two" },
                            { text = "Head to the north-east corner of the Iceberg and right-click Jim, a well disguised polar bear next to the stepping stones, and select 'tuxedo-time'." },
                            { text = "Head to the north-west and investigate the avalanche of snow. Follow the main hall to the end and talk to the KGP agent in the booth." },
                            { text = "After proceeding through the door, head east and then follow the western wall in the war-room to the western workbench. Craft Ping & Pong's costumes there." },
                            { text = "Head back outside. To get back in to the hallway, Push the big button west of the gate." },
                            { text = "Return to Jim, the polar bear, to get out of tuxedo." },
                        },
                    },
                    {
                        text = "Give Ping & Pong their costumes.",
                        npcs = {},
                    },
                    {
                        text = "Board the nearby boat to return to the seals.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Wake up the seal, bank any items, including your clockwork suit, and head to the camp. There is a deposit box option when talking to the seal.",
                        chat = "1 Yes.",
                        npcs = { "clockwork suit" },
                    },
                },
            },
            {
                title = "Prisoner of Walrus Camp", needed = {},
                steps = {
                    {
                        text = "Talk to Teddy, the polar bear in a clown costume, in the centre of the camp.",
                        npcs = { "Teddy" },
                    },
                    {
                        text = "Talk to Larry, north of Teddy",
                        npcs = { "Larry" },
                    },
                    {
                        text = "Talk to Teddy again.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Noodle outside the south-west building.",
                        npcs = { "Noodle" },
                    },
                    {
                        text = "Try to open the door to the southern building where the Walrus is in.",
                        npcs = { "Walrus" },
                    },
                    {
                        text = "Take bat-in-box the bat-in-box (slightly west of the door where the walrus is) from the front of the building.",
                        chat = "1 Yes.",
                        npcs = { "bat-in-box" },
                    },
                    {
                        text = "Encourage Teddy, Ping, Pong, and Bouncer to make noise by clicking on them repeatedly in turn. Click Ping, then Pong, then Bouncer, then Teddy until a cutscene starts. Their bars should all be blue, so it's a good idea to walk in circles.",
                        npcs = { "Bouncer (Some Like It Cold)" },
                    },
                    {
                        text = "When the Walrus is outside, enter his building and steal from the table to receive an egg.",
                        npcs = { "Egg (Some Like It Cold)" },
                    },
                    {
                        text = "Talk to Larry in the north with the egg.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Teddy.",
                        npcs = {},
                    },
                    {
                        text = "Talk to all six of the unnamed penguins. (Four in the courtyard, one between the north and north-west buildings and one, hard to see depending on camera angle, on the fishing hole in the north-east corner).",
                        npcs = { "fishing hole" },
                    },
                    {
                        text = "Talk to Teddy.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Plaza outside the easternmost building.",
                        npcs = { "Plaza" },
                    },
                    {
                        text = "Collect the following items:",
                        npcs = {},
                        subs = {
                            { text = "Fish the fishing hole in the north-east until you receive a shark tooth and squid." },
                            { text = "Take a board from the wood scrap pile north of the easternmost building." },
                            { text = "Search the shelves in the easternmost building for olive oil, popsicle tray, and a rock carving hammer." },
                            { text = "Right click Teddy and Tear off fabric." },
                            { text = "Search the shelves in the south-west building for lye and a cork screw." },
                        },
                    },
                    {
                        text = "Once all of the supplies are obtained:",
                        npcs = {},
                        subs = {
                            { text = "Use the lye on the olive oil." },
                            { text = "Use the unmoulded soap on the popsicle tray." },
                            { text = "Use the squid on the popsicle tray." },
                            { text = "Use the hammer on the soap." },
                            { text = "With a shark tooth in your backpack, use the ripped fabric on the board." },
                        },
                    },
                    {
                        text = "Talk to Plaza.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Teddy.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Astoria outside the easternmost building.",
                        chat = "1 Yes.",
                        npcs = { "Astoria" },
                        subs = {
                            { text = "If you are not prompted to start the game, talk to Teddy again." },
                        },
                    },
                },
            },
            {
                title = "Reparations", needed = {},
                steps = {
                    {
                        text = "Defeat Astoria in a game of Battlefish.",
                        npcs = {},
                        subs = {
                            { text = "Place your fish anywhere on the board." },
                            { text = "You can click on the \"HIT\" and \"MISS\" notifications to speed up this section considerably. But beware spam clicking may exit the game making you start over." },
                            { text = "Solution:" },
                        },
                    },
                    {
                        text = "In the small building just south-east, take from the circus prop crate on the northern wall.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Teddy.",
                        npcs = {},
                    },
                    {
                        text = "To repair the engine:",
                        npcs = {},
                        subs = {
                            { text = "Use Bowling pin -> lever opening" },
                            { text = "Use Hula hoop -> broken valve wheel" },
                            { text = "Use Circus plate -> pressure gauge" },
                            { text = "Use Foam finger -> pressure gauge" },
                            { text = "Use Balloon -> metal wire" },
                            { text = "Use Insulated wire -> wirebox" },
                            { text = "Use Cloth -> cracked pipe" },
                        },
                    },
                },
            },
            {
                title = "Escape", needed = {},
                steps = {
                    {
                        text = "Talk to Teddy.",
                        chat = "2 No, I know what needs to be done.",
                        npcs = {},
                    },
                    {
                        text = "Defeat the seals in Battlefish (if you accidentally exit, click on the periscope through the door to the left).",
                        npcs = {},
                        subs = {
                            { text = "Solution:" },
                        },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
