    {
        key = "spirit_of_summer", name = "Spirit of Summer", wiki = "Spirit of Summer/Quick guide",
        required = { "Ghostspeak amulet or cramulet (unless the player has claimed the reward for completing the hard Morytania achievements)", "1-3 Spirit wolf pouch", "1-3 Desert wyrm pouch", "1-3 Spirit scorpion pouch (more of each pouch if your reflexes are not relatively fast)", "At least 4 summoning points, but preferably full summoning points", "4 steel nails (obtainable during quest)", "2 planks (obtainable during quest)", "Bucket (obtainable during quest)", "Limpwurt seed (obtainable during quest, not guaranteed, not needed if you already have a limpwurt plant planted in the patch beforehand)", "1 skull (obtainable during quest)", "5 bones (obtainable during quest)" },
        recommended = { "One-click teleport (such as Ectophial or House Teleport which can prevent you from losing items from the death by poison)", "Weight-reducing and energy-restoring items highly recommended for prolonging run energy", "Supreme growth potion (leafy) to make the limpwurt plant grow much faster", "Food in case you accidentally get too close to the beast and take damage", "To get to the quest start quickly, players can use:", "Level 20 Archaeology to quickly reach the Infernal Source Dig Site through the dig site map in the Archaeology Guild", "Fort Forinthry lodestone, built after completing the quest New Foundations", "A Fort Forinthry Teleport" },
        sections = {
            {
                title = "The farm", needed = { "Ghostspeak amulet" },
                steps = {
                    {
                        text = "Talk to the spirit at the Wilderness wall north of Infernal Source Dig Site.",
                        npcs = { "Summer Bonde", "Infernal Source Dig Site" },
                    },
                    {
                        text = "Keep trying to catch the spirit until you see a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the father figure with a ghostspeak amulet equipped.",
                        npcs = {},
                    },
                    {
                        text = "Use the table below to respond to the man's emotes.",
                        npcs = {},
                        subs = {
                            { text = "Don't repeat yourself." },
                            { text = "Use the Think emote to see the emote again. Talk to him and your character will say the emote he is doing." },
                            { text = "The rings around the girl will disappear on successful emotes. When all the rings are gone, the girl is free." },
                        },
                    },
                    {
                        text = "Once the girl is free, talk to her.",
                        chat = "1 What's going on here? / 1 Okay, I will come with you to the village you're talking about.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Fixing the village", needed = { "none" },
                steps = {
                    {
                        text = "Once in the village, ask the girl to be taken back.",
                        chat = "3 Can you take me back, please?",
                        npcs = {},
                    },
                    {
                        text = "Search a crate for a limpwurt seed.",
                        npcs = { "limpwurt seed" },
                    },
                    {
                        text = "Rake the farming patch and plant the seed.",
                        npcs = {},
                        subs = {
                            { text = "Note: You can use a Supreme growth potion (leafy) on it, but do not harvest the roots yet." },
                            { text = "Wait limpwurt plant to grow (roughly 20 minutes), but do not harvest it. You cannot continue the quest until the plant grows." },
                        },
                    },
                    {
                        text = "Pick up 4 steel nails and a hammer in the anvil building (south east).",
                        npcs = { "steel nails", "hammer" },
                        subs = {
                            { text = "Note: Sometimes you will find only 3 nails there. More nails can be found in the sacks or the building west of the farming patch, near the bucket. You can also smith nails on the anvil." },
                        },
                    },
                    {
                        text = "Pick up 2 planks in the centre-most building.",
                        npcs = { "plank" },
                        subs = {
                            { text = "The north-western most building has more planks, if needed." },
                        },
                    },
                    {
                        text = "Use a plank on the wardrobe in the building south-east of the statue.",
                        npcs = {},
                    },
                    {
                        text = "With three free inventory slots, Pick from the Hollow log near the statue for button mushrooms.",
                        npcs = { "Hollow_log_(Spirit_of_Summer)", "button mushroom" },
                    },
                    {
                        text = "Grab a bucket from the building directly west of the farm patch.",
                        npcs = {},
                    },
                    {
                        text = "Use the bucket on the barrel of water south-east of the farming patch which is just outside the anvil building.",
                        npcs = {},
                    },
                    {
                        text = "After the limpwurt plant is grown, talk to the spirit for a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Talk to her again and agree to come along.",
                        chat = "1 Okay, I'll come along.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Back in the farm", needed = { "None" },
                steps = {
                    {
                        text = "Talk to Summer Bonde once more to be taken back.",
                        chat = "3 Can you take me back?",
                        npcs = {},
                    },
                    {
                        text = "Take a skull and 5 bones east of the farm.",
                        npcs = { "skull", "bones" },
                    },
                    {
                        text = "Stand in the portal which is the white circle.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Summer Bonde.",
                        chat = "2 What exactly is going on here? / 1 Of course, I will help you.",
                        npcs = {},
                    },
                    {
                        text = "Follow her and Climb-down the Trapdoor.",
                        npcs = {},
                    },
                    {
                        text = "Use the skull on the altar, then right-click each of the 5x bones to \"Use\" it on the altar. You do not need to move around the altar to use bones and skull.",
                        npcs = {},
                        subs = {
                            { text = "Note: Take care not to bury the bones." },
                        },
                    },
                    {
                        text = "If she is not right next to you, Climb-up the ladder and then in both situations, talk to Summer again.",
                        chat = "1 What should I do now? / 3 I better get to work, then.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Luring the beast", needed = { "Multiple Spirit wolf pouches, Desert wyrm pouches & Spirit scorpion pouches" },
                steps = {
                    {
                        text = "Optional: Customise your interface to allow you to dismiss familiars as fast as possible.",
                        npcs = {},
                    },
                    {
                        text = "Climb the ladder to go back outside.",
                        npcs = {},
                    },
                    {
                        text = "Run north to the wolf platform.",
                        npcs = {},
                    },
                    {
                        text = "Summon a spirit wolf so that it stands on the platform (it doesn't have to be in the centre).",
                        npcs = { "spirit wolf" },
                    },
                    {
                        text = "The Spirit Beast will only be lured to a platform with a familiar summoned.",
                        npcs = {},
                    },
                    {
                        text = "Dismiss the familiar as soon as the beast steps on the platform. (As the spirit beast foot is midair about to land.)",
                        npcs = {},
                        subs = {
                            { text = "There will be a cutscene that plays the very first time the beast approaches the platform. This is not the success cutscene." },
                            { text = "The beast does not need to fully be on the platform." },
                            { text = "Your familiar will be dismissed immediately without the \"are you sure\" warning; a lightning effect will show if successful." },
                        },
                    },
                    {
                        text = "Don't let the beast consume your familiar, and don't move your familiar off the platform. It is helpful to try to position yourself between the beast and your familiar.",
                        npcs = {},
                    },
                    {
                        text = "A cutscene in which the spirit beast is electrified, and the next summoning platform will appear will play if you have succeeded.",
                        npcs = {},
                    },
                    {
                        text = "If you have to teleport out for more pouches, you must talk to Summer by the quest start location to return to the spirit realm.",
                        npcs = {},
                    },
                    {
                        text = "Repeat this process with the desert wyrm, using the platform that appears during the cutscene. You can also push the Spirit Beast by walking at beast to position the creature, but it can give you some damage and may push you away sometimes.",
                        npcs = { "desert wyrm" },
                    },
                    {
                        text = "And again, for the spirit scorpion - the platform is far west.",
                        npcs = { "spirit scorpion" },
                    },
                    {
                        text = "Talk to any of the spirits by the Spirit Beast.",
                        npcs = { "Spirit Beast" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "spirits_of_the_elid", name = "Spirits of the Elid", wiki = "Spirits of the Elid/Quick guide",
        required = { "1 law rune and 1 air rune to cast the Telekinetic Grab spell", "A light source (such as a torch, mining helmet, bullseye lantern or Seer's headband)", "Rope", "One or two spools of thread", "A weapon for each melee attack style - stab (sword), crush (mace) and slash (scimitar) (other styles work but are extremely inefficient)", "For higher melee levelled players, all may not be needed", "A method of attacking with at least 4 range", "A Bow or crossbow with ammo unless using chargebow (a shortbow and bronze arrows can be found during the quest)", "A magic weapon and runes", "A necromancy weapon" },
        recommended = { "Enough coins and a ring of charos for 4 magic carpet rides (300 to 4,000)", "A traveller's necklace, enchanted broomstick, dominion medallion, ring of slaying, or the Al Kharid lodestone to quickly travel to the source of the River Elid", "At least 2 drinks from a waterskin—no more are needed if the magic carpets are used", "Low and medium-level players may bring prayer potions, rings of recoil and/or food to defeat the golems" },
        sections = {
            {
                title = "Getting started", needed = { "1 thread, 1 law rune and 1 air rune to cast the Telekinetic Grab spell" },
                steps = {
                    {
                        text = "Head to Nardah (south of fairy ring DLQ) and talk to Awusah the Mayor in the building east of the fountain.",
                        chat = "1 I am an adventurer in search of quests. / 2 Any idea how you got this curse? / Accept",
                        npcs = { "Nardah", "Awusah the Mayor" },
                    },
                    {
                        text = "Head to the house north-east of the fountain and talk to Ghaslor the Elder. You should receive a Ballad.",
                        chat = "1 I am trying to find out the cause of this town's curse. / 1 River spirits, what are they?",
                        npcs = { "Ghaslor the Elder", "Ballad" },
                    },
                    {
                        text = "Head to the building that has a statuette plinth just west of Ghaslor's house and north of the fountain.",
                        npcs = {},
                    },
                    {
                        text = "Telegrab the ancestral key from the table.",
                        npcs = { "Telegrab", "ancestral key" },
                        subs = {
                            { text = "You may attach the ancestral key to your steel key ring if you've completed the One Small Favour quest" },
                        },
                    },
                    {
                        text = "Go to the other side of the building and open the northernmost cupboard and search it for the robe top and bottom.",
                        npcs = {},
                    },
                    {
                        text = "Fix the top and bottom robes.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The Golems", needed = { "A weapon and ammo for a combat type other than melee, rope, thread" },
                steps = {
                    {
                        text = "Head north, past the Dominion Tower until a waterfall is seen.",
                        npcs = { "Dominion Tower" },
                        subs = {
                            { text = "You can teleport to there by using a traveller's necklace to south of the Uzer eagles' eyrie." },
                            { text = "There is a bronze arrow south-east of Dominion Tower and a shortbow north-east of it." },
                        },
                    },
                    {
                        text = "Climb the waterfall.",
                        npcs = {},
                    },
                    {
                        text = "Equip the Robes of Elidinis and open the door.",
                        npcs = { "Robes of Elidinis" },
                        subs = {
                            { text = "If the door will not open, make sure you repaired and are wearing both robe pieces, and make sure you have the Ancestral key you tele-grabbed earlier." },
                        },
                    },
                    {
                        text = "Head east to the three doors.",
                        npcs = {},
                    },
                    {
                        text = "Try to open any door, kill the golem that spawns, then enter the room and clear the water channel for each room.",
                        npcs = {},
                        subs = {
                            { text = "If you click the door before the golem's death animation has finished, it will respawn and you will have to fight it again." },
                        },
                    },
                    {
                        text = "Head through the door to the north and talk to one of the spirits in the large area.",
                        chat = "4 I come as an emissary from the people of Nardah. / 1 Is there anything they can do to get their fountain working again?",
                        npcs = {},
                    },
                    {
                        text = "Head back to Nardah.",
                        npcs = {},
                        subs = {
                            { text = "It is possible to be bugged when exiting the cave. To get out of the bug, simply use a Home Teleport spell." },
                            { text = "Amulet of glory teleport to Al Kharid and then taking the magic carpet to Nardah is a quick option." },
                        },
                    },
                },
            },
            {
                title = "The Genie", needed = {},
                steps = {
                    {
                        text = "Talk to Awusah the Mayor.",
                        npcs = {},
                    },
                    {
                        text = "Take shoes just south from the entrance door inside the Mayor's house.",
                        npcs = { "Shoes (Spirits of the Elid)" },
                    },
                    {
                        text = "Go outside the house, then remove-sole from the shoes to obtain a sole.",
                        npcs = { "sole" },
                        subs = {
                            { text = "Ensure you have a light source or you will not be able to talk to the next NPC without being interrupted." },
                        },
                    },
                    {
                        text = "Head west from the Nardah General Store, past a camp of trainee adventurers and climb-down the crevice.",
                        npcs = { "Nardah General Store", "trainee adventurer", "Elid Genie Cave" },
                    },
                    {
                        text = "Talk to the Genie, then talk again.",
                        chat = "1 I'm after a statue that was thrown down here. / 1 Maybe I can make a deal for it? / 3 Ok I agree to the deal.",
                        npcs = { "Genie (Spirits of the Elid)" },
                        subs = {
                            { text = "If your backpack was full, pick up the Statuette. - There will be room now as you gave the Genie a sole." },
                        },
                    },
                    {
                        text = "Head back to Nardah and use the statuette on the plinth in the shrine room, north of the fountain.",
                        npcs = { "Statuette (Spirits of the Elid)" },
                        subs = {
                            { text = "Optional: Pray at the statue for medium desert task achievement Heathen Idle." },
                        },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "Spirits of the Elid",
                        npcs = { "Spirits of the Elid (achievement)" },
                    },
                    {
                        text = "Desert achievements",
                        npcs = { "Desert achievements" },
                        subs = {
                            { text = "Medium" },
                            { text = "Heathen Idle" },
                            { text = "Goat Harralander?" },
                            { text = "Hard" },
                            { text = "Ug Thankee Kindly" },
                            { text = "Elite - Sun Shade" },
                            { text = "The bosses need to be killed in a special match in the Dominion Tower" },
                        },
                    },
                },
            },
        },
    },
    {
        key = "spiritual_enlightenment_miniquest", name = "Spiritual Enlightenment (miniquest)", wiki = "Spiritual Enlightenment (miniquest)/Quick guide",
        required = {},
        recommended = { "High level armour, weapons, and food. Enemies are weak to air spells" },
        sections = {
            {
                title = "Creatures of Aminishi", needed = {},
                steps = {
                    {
                        text = "Charter a ship to Aminishi and talk to Ling.",
                        chat = "Accept",
                        npcs = { "Aminishi", "The Assassin" },
                        subs = {
                            { text = "If you have just completed Impressing the Locals, you may need to relog for the chat option to show up." },
                        },
                    },
                    {
                        text = "Kill creatures on the island until you receive 3 books.",
                        npcs = {},
                        subs = {
                            { text = "Ordered from best drop rate to worst, kill Anagami, Sakadagami or Sotapanna." },
                            { text = "The 3 book names are:" },
                            { text = "The Path of the Dragon" },
                            { text = "The Path of the Monk" },
                            { text = "The Path of the Elemental" },
                            { text = "Pick up some spirit dragon charms because you will need 1-2 later. (Note: Ensure to have toggled off your spirit imp destroy option)" },
                        },
                    },
                    {
                        text = "Return to Ling.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Spirit realm", needed = {},
                steps = {
                    {
                        text = "Enter The Well of Spirits on the middle tier to travel to the spirit realm.",
                        npcs = { "The Well of Spirits" },
                    },
                    {
                        text = "Head south-west and talk to Yulong on the shore. He is exactly where you would find Ling outside the spirit realm.",
                        chat = "Any",
                        npcs = { "Yulong" },
                    },
                    {
                        text = "Return to Ling.",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "stellar_born", name = "Stellar Born", wiki = "Stellar Born/Quick guide",
        required = { "152 cosmic runes", "52 astral runes", "Wizard Blizzard or Premade Wizard Blizzard" },
        recommended = { "Stardust will teleport you directly to Wizard Rosalina", "Alternatively, wicked hood, fairy ring DIS, or other means of teleporting to the Wizards' Tower", "Memory strand, fairy ring AKQ, or other means of teleporting to Piscatoris", "'Chipped' Watchtower teleport or other means of teleporting to the Observatory", "Leela's favour will teleport you to Menaphos Merchant district near Desert goebie camp", "Shadow's Grace relic power or Mobile on an augmented armour piece (weapons will be unequipped for various parts of the quest)" },
        sections = {
            {
                title = "Mysterious star found", needed = {},
                steps = {
                    {
                        text = "Talk to the crashed star west of the Piscatoris Fishing Colony.",
                        chat = "Accept",
                        npcs = { "Crashed star (Stellar Born)", "Piscatoris Fishing Colony" },
                    },
                    {
                        text = "Mine the crashed star and finish the dialogue.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Sending Zoob back", needed = { "152 cosmic runes, 52 astral runes and a Wizard Blizzard (or its premade version)." },
                steps = {
                    {
                        text = "Go to the south side of the 3rd floor of the Wizard's Tower and talk to Wizard Rosalina.",
                        npcs = { "Wizard Rosalina" },
                    },
                    {
                        text = ": Players can quickly teleport to her with stardust.",
                        npcs = { "stardust" },
                    },
                    {
                        text = "Return to the crashed star west of Piscatoris.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Wizard Rosalina to hand her your cosmic and astral runes and the Wizard Blizzard drink. Finish the cutscene.",
                        npcs = { "Wizard Rosalina" },
                    },
                    {
                        text = "Head to the desert goebie camp, north-west of Menaphos.",
                        npcs = { "desert goebie camp" },
                    },
                    {
                        text = ": Players can use Leela's favour to get to the Merchant District (option 2) and exit through the north Menaphos gate.",
                        npcs = { "Leela's favour", "Menaphos Merchant district" },
                    },
                    {
                        text = "Talk to Wizard Chambers.",
                        npcs = { "Wizard Chambers" },
                    },
                    {
                        text = "Return to the Piscatoris crash site and talk to Wizard Chambers or Wizard Rosalina.",
                        npcs = {},
                    },
                    {
                        text = "Talk to them again.",
                        npcs = {},
                    },
                    {
                        text = "Shoo away fireflies to keep them away from the crashed star until the portal progress at the top of your screen reaches 50.",
                        npcs = {},
                    },
                    {
                        text = "Talk to them again.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Exploring the homeland of star sprites", needed = {},
                steps = {
                    {
                        text = "Teleport to Zolarea with the portal.",
                        npcs = { "Portal (Zolarea)" },
                    },
                    {
                        text = "Unequip any items in your main/off-hand slots and jump the rocky edge to the east.",
                        npcs = { "rocky edge" },
                    },
                    {
                        text = "Fly to the large island to the east and jump to the rocky edge to land.",
                        npcs = {},
                    },
                    {
                        text = ": Players can Surge and Dive during flight.",
                        npcs = { "Surge", "Dive" },
                    },
                    {
                        text = "Head south-east to the giant crystal towards the centre and talk to Wizard Rosalina.",
                        chat = "Any",
                        npcs = { "giant crystal (Zolarea)" },
                    },
                    {
                        text = "Jump the rocky edge on the northernmost side of the main island.",
                        npcs = {},
                    },
                    {
                        text = "Head to the north-easternmost island and inspect the mysterious decay.",
                        npcs = { "mysterious decay" },
                    },
                    {
                        text = "Return to the main island and then inspect the mysterious decay south of the rocky edge and west of the flower patch.",
                        npcs = {},
                    },
                    {
                        text = "Attempt to enter the cave entrance to the west of the giant crystal. (1/12)",
                        npcs = { "Cave entrance (Zolarea)", "giant crystal (Zolarea)" },
                    },
                    {
                        text = "Head to the south side of the main island and inspect the mysterious decay (2/12), then talk to Rox. (3/12)",
                        npcs = { "Rox" },
                    },
                    {
                        text = "Head west to the southernmost house and lift the woven rug, then talk to Nuub. (4/12)",
                        npcs = { "woven rug", "Nuub" },
                    },
                    {
                        text = "Talk to Blip near Wizard Rosalina. (5/12)",
                        npcs = { "Blip" },
                    },
                    {
                        text = "Talk to Wizard Rosalina.",
                        chat = "1 I found some information... / 2 Parts of the planet are dying. / 1 There is a cave in the center of the planet. / 3 The cave is where the elder star sprites go to die. / 1 The cave is where their power source can be found.",
                        npcs = {},
                    },
                    {
                        text = ": If the necessary chat options display \"???\", you missed a clue.",
                        npcs = {},
                    },
                    {
                        text = ": If done correctly, you receive a wrinkly scroll.",
                        npcs = { "wrinkly scroll" },
                    },
                },
            },
            {
                title = "Playing around dark star", needed = {},
                steps = {
                    {
                        text = "Head to the observatory west of Tree Gnome Village and north of Castle Wars.",
                        npcs = { "observatory", "Tree Gnome Village (location)", "Castle Wars" },
                    },
                    {
                        text = ": The fastest teleport is 'Chipped' Watchtower teleport made by Dave's spellbook.",
                        npcs = { "'Chipped' Watchtower teleport", "Dave's spellbook" },
                    },
                    {
                        text = ": See other ways of getting there.",
                        npcs = { "Observatory" },
                    },
                    {
                        text = "Climb the rope attached to the broken stairs north-east of the observatory, then go up the stairs inside the observatory.",
                        npcs = { "Rope (Observatory)" },
                    },
                    {
                        text = "Talk to the Observatory professor on the 2nd floor.",
                        npcs = { "Observatory professor" },
                    },
                    {
                        text = "After the cutscene, return to Zolarea via the portal at the crash site west of Piscatoris.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Wizard Rosalina in the centre of the island.",
                        npcs = {},
                    },
                    {
                        text = "Enter the cave entrance to the west.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Wizard Rosalina.",
                        npcs = {},
                    },
                    {
                        text = "Exit the cave.",
                        npcs = {},
                    },
                    {
                        text = "Gather the dark star wisps that have appeared. Wisps are visible on the minimap as a yellow dot:",
                        npcs = { "dark star wisp" },
                        subs = {
                            { text = "A bit north of the cave, west of the mysterious decay. (1/5)" },
                            { text = "Jump the rocky edge to the north and gather the wisp on the small, north-north-western island. (2/5)" },
                            { text = "Return to the east side of the main island and gather the wisp near the meteorites. (The mining symbol on your minimap) (3/5)" },
                            { text = "Go to the south side of the island and gather the wisp near the rocky edge. (4/5)" },
                            { text = "Jump the rocky edge to the south and gather the wisp on the south-easternmost island. (5/5)" },
                        },
                    },
                    {
                        text = "Return to the cave and talk to Wizard Rosalina.",
                        chat = "1 Could we sacrifice a star sprite? / 2 Could we sacrifice Blip? / 3 Could I sacrifice myself? / 4 Could we sacrifice you?",
                        npcs = {},
                    },
                    {
                        text = "Select the star sprites in the following order:",
                        npcs = {},
                        subs = {
                            { text = "Wave 1: Glorp, Bop, Rox" },
                            { text = "Wave 2: Zag, Fuz, Nuub, Zorb" },
                            { text = "Wave 3: Zig, Eetee, Bop, Eetee, Glorp" },
                        },
                    },
                    {
                        text = "Exit the cave and talk to Wizard Rosalina in the centre.",
                        chat = "1 Yes please!",
                        npcs = {},
                    },
                    {
                        text = "Talk to Wizard Rosalina back at the crash site.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "stolen_hearts", name = "Stolen Hearts", wiki = "Stolen Hearts/Quick guide",
        required = {},
        recommended = { "For lower levels, some food and iron armour or better is recommended." },
        sections = {
            {
                title = "The Skulls", needed = {},
                steps = {
                    {
                        text = "Talk to Ozan in the Draynor Village, just south of the potter, north of the water pump, west of the wheat field.",
                        chat = "Accept",
                        npcs = { "Ozan", "Draynor Village", "potter", "Wheat (scenery)" },
                    },
                    {
                        text = "In the house to the west, open the trapdoor.",
                        chat = "3 Let me in or I'll poke your eyes out!",
                        npcs = { "Trapdoor (The Skullery)" },
                    },
                    {
                        text = "Talk to Khnum.",
                        chat = "Any / Any / Any / Any / 1 Tell me what jobs you have in the works.",
                        npcs = { "Khnum" },
                    },
                    {
                        text = "If you have any followers, dismiss them now.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Ozan.",
                        chat = "1 How do we find the HQ? / 1 Yes.",
                        npcs = { "Ozan" },
                    },
                },
            },
            {
                title = "The headquarters and the jail", needed = {},
                steps = {
                    {
                        text = "Follow Khnum. Ozan will warn of getting too close or too far.",
                        npcs = {},
                    },
                    {
                        text = "Open the door Khnum went through.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Khnum.",
                        chat = "1 I'll beat the truth out of him! / 1 How about some sort of truth serum? / 2 I'll lock you up and throw away the key.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Lady Keli kidnapping Prince Ali", needed = {},
                steps = {
                    {
                        text = "Head south of the old jail, towards the shoreline, past the pale wisps.",
                        npcs = { "pale wisp" },
                    },
                    {
                        text = "Talk to a skulls mercenary or Mercenary Joe. Mercenaries will begin to attack you.",
                        npcs = { "skulls mercenary", "Mercenary Joe" },
                    },
                    {
                        text = "Kill the mercenaries and pick up the ransom note.",
                        npcs = { "ransom note" },
                    },
                    {
                        text = "Talk to Leela and remember the passphrase she gives you as this is needed later.",
                        npcs = {},
                    },
                    {
                        text = "Agree to travel with Ozan to Al Kharid.",
                        chat = "1 Yes.",
                        npcs = { "Ozan", "Al Kharid" },
                    },
                },
            },
            {
                title = "Getting into Al Kharid palace", needed = {},
                steps = {
                    {
                        text = "Home Teleport to Al Kharid lodestone.",
                        npcs = { "Home Teleport", "Al Kharid lodestone" },
                        subs = {
                            { text = "If you have the lodestone unlocked, you should Home Teleport so Ozan follows you." },
                        },
                    },
                    {
                        text = "Head south into the Al Kharid palace and talk to the palace guard.",
                        npcs = { "Al Kharid palace", "palace guard" },
                    },
                    {
                        text = "Head northeast of Al Kharid to Dommik's Crafting Store.",
                        npcs = { "Dommik's Crafting Store" },
                    },
                },
            },
            {
                title = "Parkour", needed = {},
                steps = {
                    {
                        text = "Climb up the steps inside.",
                        npcs = {},
                    },
                    {
                        text = "Climb the ladder.",
                        npcs = {},
                        subs = {
                            { text = "If there is no ladder you should need to talk to the guard in the palace again." },
                        },
                    },
                    {
                        text = "Walk across the plank to the south.",
                        npcs = {},
                    },
                    {
                        text = "Slide down the awning to the south.",
                        npcs = {},
                    },
                    {
                        text = "Head inside the room to the north",
                        npcs = {},
                    },
                    {
                        text = "Walk across the washing line to west.",
                        npcs = {},
                    },
                    {
                        text = "Climb the ladder to the west.",
                        npcs = {},
                    },
                    {
                        text = "Cross the planks to the west.",
                        npcs = {},
                    },
                    {
                        text = "Head west and climb the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Jump from the scaffold to the west.",
                        npcs = {},
                    },
                    {
                        text = "Climb down the rug to the south.",
                        npcs = {},
                    },
                    {
                        text = "Swing across the wooden frame to the west.",
                        npcs = {},
                    },
                    {
                        text = "Jump from the scaffold to the south.",
                        npcs = {},
                    },
                    {
                        text = "Bounce on the awning south.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the brickwork.",
                        npcs = {},
                    },
                    {
                        text = "\"Leave it to Ozan\" on the flagpole",
                        npcs = {},
                    },
                    {
                        text = "Shimmy across the rope.",
                        npcs = {},
                    },
                    {
                        text = "\"Climb up\" the brickwork to activate a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene, climb up the brickwork.",
                        npcs = {},
                    },
                    {
                        text = "Head south and \"break in\" through the skylight. Don't log out once inside, or you will respawn outside the palace.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Weight on Kharid-ib", needed = {},
                steps = {
                    {
                        text = "Inspect the Het scales.",
                        npcs = {},
                    },
                    {
                        text = "You have exactly two weighings to determine which is the heaviest weight.",
                        npcs = {},
                        subs = {
                            { text = "The heaviest weight will always be random." },
                            { text = "Drag two sets of three weights onto both sides of the scale and click the central green gem to weigh." },
                            { text = "If one of the sides is heavier, you know the heaviest weight is part of the 3 weights that went down. Put one of those weights on the left side and one weight on the right side of the scale, the last one in the bottom row and click the green gem again. If either side went down you know the heaviest weight. If they are equal you know it's the one you put back in the bottom row." },
                            { text = "If both sides were of equal weight, you know the remaining 3 weights in the bottom row are the heaviest. Put one of those weights on the left side and one weight on the right side of the scale, the last one in the bottom row and click the green gem again. If either side went down you know the heaviest weight. If they are equal you know it's the one you put back in the bottom row." },
                            { text = "Once you've determined the heaviest weight drag it onto the backpack icon to grab it." },
                        },
                    },
                    {
                        text = "\"Place weight\" on the Kharid-ib display.",
                        npcs = { "Kharid-ib display" },
                    },
                    {
                        text = "Tell Osman the passphrase that was obtained from Leela. If you don't remember it, try all options as if you get it wrong enough times Ozan will say the passphrase anyway.",
                        npcs = {},
                    },
                    {
                        text = "During the cutscene, choose either option.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "succession", name = "Succession", wiki = "Succession/Quick guide",
        required = {},
        recommended = { "Activated Falador lodestone or Falador Teleport to travel to White Knights' Castle", "Archaeology journal, Dig Site pendant, pontifex shadow ring or better to teleport to the Archaeology Guild, Varrock Dig Site, or Elder God Wars Dungeon", "Wilderness sword or Carrallangar Teleport to reach Ruins (east) quickly", "Slayer cape to teleport to Mandrith, activated Ardougne or Edgeville lodestone via Deserted Keep for the Mage Arena", "Imperial district teleport, Leela's favour, or activated Menaphos lodestone to travel to Grand Library of Menaphos directly", "Either activated Al Kharid lodestone or amulet of glory and coins to travel to the entrance of Menaphos via Shantay Pass", "Activated Fort Forinthry lodestone to travel quickly to argonlike rocks." },
        sections = {
            {
                title = "Investigation time", needed = {},
                steps = {
                    {
                        text = "Talk to Adrasteia in the throne room on the floor of the White Knights' Castle.",
                        chat = "Accept / 1 Yes. / 4 Let's continue our journey.",
                        npcs = { "Adrasteia", "White Knights' Castle" },
                    },
                },
            },
            {
                title = "Clues in the prison", needed = {},
                steps = {
                    {
                        text = "Head to the Varrock Dig Site and enter ancient door leading to Senntisten.",
                        chat = "1 Yes.",
                        npcs = { "Varrock Dig Site", "Ancient door (Senntisten)", "Senntisten" },
                    },
                    {
                        text = "Discover the large footprint downstairs. All discoverable entities in this quest should be marked by a red dot on your minimap. (1/5)",
