    {
        key = "tai_bwo_wannai_trio", name = "Tai Bwo Wannai Trio", wiki = "Tai Bwo Wannai Trio/Quick guide",
        required = { "One agility potion (4)", "You can combine lower dose potions to get to 4 doses; low-level Ironmen can do Temple Trekking to exchange yellow reward tokens for grimy toadflax", "Iron spear, steel spear, mithril spear, adamant spear, rune spear or dragon spear which will be consumed", "A rune spear can be bought from Scavvo's Rune Store, iron to rune spears can be bought from the Warriors' Guild Armoury", "22 karambwanji (can be obtained during quest by fishing near hobgoblins)", "Karamjan rum (cannot be taken off the island nor teleported with)", "Seaweed (can be obtained during quest on beach west of Tai Bwo Wannai)", "Sliced banana (can be obtained during quest)", "Jogre bones (can be obtained during quest)" },
        recommended = { "Level 65 Fishing (to catch karambwan in case it burns)", "Level 30 Firemaking (requires use of furnace to make burnt jogre bones without level 30 Firemaking)", "23 free inventory spaces recommended to minimise walking", "Activated Karamja lodestone", "2 raw karambwan (optional if you don't have level 65 Fishing - only required if you burn the karambwan given during the quest)", "Nature altar teleport", "Food and antipoison", "Any logs to make a fire", "Portable fairy ring" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to Timfraku located upstairs in the house northwest of Tai Bwo Wannai.",
                        chat = "Any / 3 Trufitus sent me. / 1 Your gratitude is all I deserve. / Accept",
                        npcs = { "Timfraku", "Tai Bwo Wannai" },
                        tile = { x = 2780, y = 3087, plane = 1 },
                    },
                },
            },
            {
                title = "Lubufu", needed = {},
                steps = {
                    {
                        text = "Go to the lake south of Tai Bwo Wannai and fish 23 raw karambwanji (just north of fairy ring code CKR).",
