                    {
                        text = "North of the Karamja lodestone, talk to Lubufu.",
                        chat = "1 I wasn't going anywhere...",
                        npcs = { "Lubufu" },
                    },
                    {
                        text = "Talk to him again.",
                        chat = "1 Talk about him... / 3 What do you do? / 3 What do you use for bait? / 1 Talk about him... / 3 What do you do? / 4 I could help collect the bait. / 1 You sound like you could do with the help.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Lubufu to give him 20 raw karambwanji.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Lubufu 3 more times as follows",
                        npcs = {},
                        subs = {
                            { text = "Talk to him again." },
                            { text = "Talk again.", chat = "3 What do you use to catch Karambwan?" },
                            { text = "Talk a third time.", chat = "4 What does Karambwan taste like? / 1 Yes!" },
                        },
                    },
                    {
                        text = "Drop the karambwan vessel and talk to him to get a second vessel, then pick up the first.",
                        chat = "3 Actually, I've lost my Karambwan vessel. / Any",
                        npcs = {},
                        subs = {
                            { text = "Optional: Use 1 raw karambwanji on a karambwan vessel, then fish at the spot next to Lubufu (requires ) to complete a Medium Karamja achievement." },
                        },
                    },
                    {
                        text = "Use another karambwanji on a vessel and keep it for the next step.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Tiadeche", needed = {},
                steps = {
                    {
                        text = "Head to the north-east coast of Karamja, across the river and talk to Tiadeche (fairy ring code DKP).",
                        chat = "3 Is there anything I can do to help?",
                        npcs = { "Tiadeche", "fairy ring" },
                        tile = { x = 2912, y = 3118, plane = 0 },
                    },
                    {
                        text = "Use the loaded vessel on him.",
                        chat = "1 Yes",
                        npcs = {},
                    },
                    {
                        text = "Head south, kill a jogre and take its bones.",
                        npcs = {},
                    },
                    {
                        text = "Go to Musa Point and buy one Karamjan rum from the pub. You can also buy rum from the Dead Man's Chest in Brimhaven. The rum will break if you teleport with it in your inventory. It will be stolen by a monkey if you ride the cart to Shilo Village with it in your inventory.",
                        npcs = { "Musa Point", "Karamjan rum", "Dead Man's Chest" },
                    },
                    {
                        text = "Pick a banana or buy one from the traders at the Brimhaven dock, cut it for slices.",
                        npcs = {},
                    },
                    {
                        text = "Use a banana slice on the Karamjan rum - you can now teleport without having the rum disappear from your inventory.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Tamayu and the Shaikahan", needed = { "Spear (iron or better), Agility potion (4), raw karambwan" },
                steps = {
                    {
                        text = "Take some seaweed near the shore of Cairn Isle (fairy ring code CKR).",
                        npcs = { "Cairn Isle", "fairy ring" },
                    },
                    {
                        text = "Chop nearby dead trees to get 2 logs to light (or go to the fire south of Tai Bwo Wannai).",
                        npcs = {},
                    },
                    {
                        text = "Use the Karambwan (not the Karambwanji) on the fire; select the option poison karambwan.",
                        npcs = { "poison karambwan" },
                    },
                    {
                        text = "Grind the poison karambwan to make Karambwan paste (poison).",
                        npcs = { "Karambwan paste (poison)" },
                    },
                    {
                        text = "Right-click use the paste on your spear to poison it.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Tamayu southeast of Tai Bwo Wannai, near the mining area.",
                        npcs = { "Tamayu" },
                        tile = { x = 2844, y = 3042, plane = 0 },
                    },
                    {
                        text = "Talk to him again.",
                        chat = "3 When will you succeed? / 1 Yes",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene, use the poisoned spear and agility potion (4) on him.",
                        npcs = {},
                    },
                    {
                        text = "Talk to him again.",
                        npcs = {},
                    },
                    {
                        text = "Kill a nearby monkey, take its corpse, then use it on Tamayu to skin it.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Tinsay", needed = { "Jogre bones, Karamjan rum with banana slices in it, logs, monkey skin, seaweed, raw karambwanji, karambwan vessel" },
                steps = {
                    {
                        text = "Go to Cairn Isle (fairy ring code CKR), climb the rocks and cross the bridge. The surge ability can be used to bypass the agility check for the bridge.",
                        npcs = { "fairy ring" },
                    },
                    {
                        text = "Talk to Tinsay.",
                        npcs = { "Tinsay" },
                        tile = { x = 2764, y = 2976, plane = 0 },
                    },
                    {
                        text = "Give him the Karamjan rum.",
                        chat = "1 Yes.",
                        npcs = {},
                        subs = {
                            { text = "Use banana slices on the Karamjan rum first if you did not in the previous section." },
                        },
                    },
                    {
                        text = "Use seaweed on the monkey skin, then give it to him.",
                        chat = "1 Yes.",
                        npcs = { "monkey skin" },
                    },
                    {
                        text = "Right-click light the jogre bones. (Use a furnace if not level 30 in Firemaking.)",
                        npcs = {},
                    },
                    {
                        text = "Grind your last raw karambwanji (the fish, not the octopus) into paste.",
                        npcs = { "raw karambwanji" },
                        subs = {
                            { text = "If there is no more raw karambwanji in your inventory, fish for more in the lake northeast of Cairn Isle." },
                        },
                    },
                    {
                        text = "Pick up the burnt jogre bones once the fire dies, then use the green paste on it.",
                        npcs = { "burnt jogre bones" },
                    },
                    {
                        text = "Light a log fire, then right-click use the pasty bones on the fire to cook it.",
                        npcs = {},
                    },
                    {
                        text = "Give him the marinated jogre bones.",
                        chat = "1 Yes.",
                        npcs = { "marinated jogre bones" },
                    },
                    {
                        text = "Use a karambwan vessel on Tinsay so that he gives you a crafting manual.",
                        npcs = {},
                        subs = {
                            { text = "If he will not take the Vessel go back to Tiadeche and use a loaded Vessel, one with a Karambwanji inside of it. After successfully catching a Karambwan, Tiadeche will ask you to take a Vessel to Tinsay to study. Tiadeche will keep the Vessel you give him so you will need to obtain a new one before returning to Tinsay." },
                        },
                    },
                },
            },
