    {
        key = "tales_of_nomad_miniquest", name = "Tales of Nomad (miniquest)", wiki = "Tales of Nomad (miniquest)/Quick guide",
        required = {},
        recommended = { "'Chipped' Watchtower teleport, Ring of duelling or teleport runes to Ourania Runecrafting Altar", "Wilderness sword for easy teleports to Edgeville", "Ring of respawn for easy teleports to Soul Wars lobby", "Archaeology journal for teleport to east Varrock" },
        sections = {
            {
                title = "Visiting the memories of Nomad", needed = {},
                steps = {
                    {
                        text = "Enter the River of Noumenon by passing through the door behind Death in Death's office.",
                        chat = "1 River Noumenon.",
                        npcs = { "Death's office" },
                    },
                    {
                        text = "Approach the Sinister figure on the west side at the bottom of the stairs, then sift through Nomad's memory.",
                        npcs = {},
                    },
                    {
                        text = "In each of the following locations, in order, \"Sift through\", \"End\" and then \"Witness\" the memory and receive the text saying where the next memory is.",
                        npcs = {},
                    },
                    {
                        text = "Once there is text overlaid on your screen, you can click away and move on to the next memory",
                        npcs = {},
                        subs = {
                            { text = "#1 — By the graves near the yew trees in Edgeville, south of the bank" },
                            { text = "#2 — West of Aubury's rune shop in Varrock, east of the Blue Moon Inn" },
                            { text = "#3 — At the Ourania altar, near the altar itself at the end of the tunnel" },
                            { text = "#4 — Nomad's throne room - use Edgeville portal to enter the Soul Wars lobby area. Enter tent to the east." },
                            { text = "#5 — In Dragith Nurn's chamber at the end of the Lumbridge Catacombs" },
                            { text = "#6 — Near the small guard house just outside of the east gate in to Varrock" },
                            { text = "#7 — Between the two graveyards in the Soul Wars lobby" },
                            { text = "#8 — Nomad's throne room (again) - enter the tent in the Soul Wars lobby area." },
                            { text = "#9 — Falador castle courtyard, southwest area" },
                            { text = "#10 — Just west of the entrance to the Black Knight's Fortress" },
                            { text = "#11 — Near the incandescent wisps south of the poison waste - north west of the crater, on the shore of the waste" },
                        },
                    },
                    {
                        text = "Return to the start point of the miniquest, and talk to the Sinister figure.",
                        npcs = {},
                    },
                    {
                        text = "Miniquest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
