    {
        key = "tales_of_the_god_wars_miniquest", name = "Tales of the God Wars (miniquest)", wiki = "Tales of the God Wars (miniquest)/Quick guide",
        required = {},
        recommended = { "Level 70 in all combat stats", "Desert amulet 2 or better to teleport to Nardah", "Remora's necklace to teleport to Mature Grotworms", "Portable fairy ring or other fast fairy ring access", "Drakan's medallion", "A God wars teleport or Trollheim tablet", "The Shard of Zaros or any Zamorak-aligned item", "War's Blessing 1 for faster access to the Barrows chest", "Combat equipment and food" },
        sections = {
            {
                title = "Curating the tales", needed = {},
                steps = {
                    {
                        text = "Talk to The Curator at the Heart of Gielinor, north of the Agility Pyramid (fairy code DLQ and run southwest). Make sure to have at least 4 open inventory spots.",
                        chat = "Accept / 2 [Continue...] / 4 [More...] / 3 Goodbye.",
                        npcs = { "The Curator", "Heart of Gielinor", "Agility Pyramid" },
                    },
                    {
                        text = "Be sure to bring the chapters with you to fill them.",
                        npcs = {},
                    },
                    {
                        text = "For chapter #1, collect 20 memory fragments (the green orbs) at the incandescent wisp Divination colony, south of the Poison Waste in Isafdar, west of Castle Wars (fairy code BKP and run west). This will grant 250 Divination XP each, 5,000 Divination XP in total.",
                        npcs = { "memory fragment", "incandescent wisp", "Poison Waste", "Isafdar", "Castle Wars" },
                    },
                    {
                        text = "For chapter #2, use the empty chapter on the Barrows reward chest. This step will grant you 5,000 Summoning XP.",
                        npcs = { "Barrows" },
                    },
                    {
                        text = "For chapter #3, kill 40 Zamorak creatures in the God Wars Dungeon to gain access to K'ril Tsutsaroth (killcount is not required if Totem of Intimidation is active on Anachronia, or if you have unlocked War's Blessing 2). Kill K'ril Tsutsaroth once at the God Wars Dungeon (practice or hard mode also count).",
                        npcs = { "God Wars Dungeon", "K'ril Tsutsaroth", "Totem of Intimidation", "Anachronia", "War's Blessing 2" },
                    },
                    {
                        text = "For chapter #4, kill 20 each of young grotworms, grotworms, and mature grotworms in any order at the Grotworm Lair, the entrance of which is at the White Knight Camp, west of Port Sarim. This step will grant you 5,000 Slayer XP.",
                        npcs = { "young grotworms", "grotworms", "mature grotworms", "Grotworm Lair", "White Knight Camp", "Port Sarim" },
                    },
                    {
                        text = "Return to the Heart of Gielinor.",
                        npcs = { "Heart of Gielinor" },
                    },
                    {
                        text = "Read the floating tome to deposit the chapters.",
                        npcs = { "Tome (Tales of the God Wars)" },
                    },
                    {
                        text = "Read the tome again and select the final memory; watch the cutscene. You do not have to watch the other memories to complete the miniquest, but you have to watch them if you want to unlock the music tracks for the Music Maestro achievement.",
                        chat = "1 Yes. / 4 [More...] / 2 Final memory.",
                        npcs = { "Music Maestro" },
                    },
                    {
                        text = "Talk to The Curator.",
                        npcs = {},
                    },
                    {
                        text = "Miniquest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "Tales of the God Wars (miniquest)",
                        npcs = { "Tales of the God Wars (miniquest) (achievement)" },
                    },
                },
            },
        },
    },
    {
        key = "tears_of_guthix_quest", name = "Tears of Guthix (quest)", wiki = "Tears of Guthix (quest)/Quick guide",
        required = { "An oil-filled bullseye lantern", "This can be obtained from the Lorehound with the 50 quest point upgrade", "A cut sapphire", "A rope, if it is your first time accessing Lumbridge Swamp Caves, and you are not accessing it through the Lumbridge Castle entrance.", "This can be obtained from the Lorehound with the 50 quest point upgrade" },
        recommended = { "Level 36 Thieving and Death to the Dorgeshuun for alternative lantern source", "Level 20 Smithing", "Level 49 Crafting, if you wish to make your own lantern. You don't need these levels to replace the lens by a sapphire in an existing bullseye lantern.", "Unlocking the swamp shortcut during The Lost Tribe for ease of getting to Juna.", "Starting The Lost Tribe to access the Lumbridge Swamp Caves through the Lumbridge's kitchen tunnel and having a lit sapphire lantern can be used to avoid the other items required.", "Either:", "Spiny helmet/Slayer helmet to negate damage from wall beasts.", "Food to heal damage." },
        sections = {
            {
                title = "Getting started", needed = { "Oil-filled bullseye lantern, cut sapphire, rope (if this is your first visit to Lumbridge Swamp Caves)" },
                steps = {
                    {
                        text = "Use a cut sapphire on an oil filled bullseye lantern.",
                        npcs = { "sapphire", "bullseye lantern (oil)" },
                    },
                    {
                        text = "Light the sapphire lantern.",
                        npcs = { "sapphire lantern" },
                    },
                    {
                        text = "Travel to the dark hole under tree slightly north west of the water altar in Lumbridge Swamp.",
                        npcs = { "dark hole under tree", "water altar", "Lumbridge Swamp" },
                    },
                    {
                        text = "Climb down the hole to access Lumbridge Swamp Caves.",
                        npcs = { "Lumbridge Swamp Caves" },
                        subs = {
                            { text = "If this is your first visit, Use the rope on the tree." },
                            { text = "Recommended: Equip a spiny helmet/slayer helmet to negate damage from wall beasts, or use a movement ability like Surge or Dive to prevent the wall beasts from attacking." },
                        },
                    },
                    {
                        text = "Run to the south east end of the cavern.",
                        npcs = {},
                    },
                    {
                        text = "Jump-across the stepping stone to the south",
                        npcs = {},
                    },
                    {
                        text = "Enter the tunnel.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Travelling with light creature", needed = {},
                steps = {
                    {
                        text = "Dismiss all followers and un-equip items held in hand.",
                        npcs = {},
                    },
                    {
                        text = "On the north side of the cavern near the entrance, Right-click travel across cavern on a light creature.",
                        npcs = { "light creature" },
                    },
                    {
                        text = "Mine one of the rocks.",
                        npcs = { "Rocks (Tears of Guthix)" },
                    },
                    {
                        text = "Jump the cliff to the east.",
                        npcs = {},
                    },
                    {
