    {
        key = "the_branches_of_darkmeyer", name = "The Branches of Darkmeyer", wiki = "The Branches of Darkmeyer/Quick guide",
        required = {},
        recommended = { "Gadderhammer (recommended if you want a higher vampyric title)", "Wolfbane dagger (recommended if you don't want to kill captured citizens)", "Combat equipment and food", "4 thread (obtainable during the quest by talking to Vanescula when entering Darkmeyer)" },
        sections = {
            {
                title = "Starting out", needed = {},
                steps = {
                    {
                        text = "Talk to Veliaf Hurtz in the Burgh de Rott pub's basement.",
                        chat = "1 What's wrong? / 1 Is there anything I can do to help? / Accept / 1 Okay, I'll go.",
                        npcs = { "Veliaf Hurtz" },
                    },
                    {
                        text = "South of the Burgh de Rott bank, enter the cave entrance.",
                        npcs = { "Burgh de Rott bank" },
                    },
                    {
                        text = "Read both pages of the decaying tome on the floor in the south-east corner of the room.",
                        npcs = { "decaying tome" },
                    },
                    {
                        text = "Take the letter on the floor south-west of the rope.",
                        npcs = { "Letter (The Branches of Darkmeyer)" },
                    },
                    {
                        text = "Search the coffin for a mysterious medallion (deals small amount of damage).",
                        chat = "1",
                        npcs = { "mysterious medallion" },
                    },
                    {
                        text = "Climb the rope to leave the cave and then return to Veliaf Hurtz.",
                        chat = "1 I found a medallion. / 1 Yes, please send me!",
                        npcs = {},
                    },
                },
            },
            {
                title = "An unexpected help", needed = {},
                steps = {
                    {
                        text = "Once teleported, head to the northernmost room. The medallion can also teleport you to the Meiyerditch laboratory.",
                        npcs = { "Meiyerditch laboratory" },
                    },
                    {
                        text = "Talk to Safalaan.",
                        chat = "2 What do you think of this medallion? / 2 What have the vampyres been doing? / 1 I've got a letter for you. / 1 What do you think? / 1 What do you think we should do? / 1 Of course.",
                        npcs = { "Safalaan" },
                    },
                },
            },
            {
                title = "Traversing Meiyerditch", needed = {},
                steps = {
                    {
                        text = "Exit the base, go through the wall to the north and climb up the stairs.",
                        npcs = {},
                        tile = { x = 3599, y = 3258, plane = 0 },
                    },
                    {
                        text = "Jump the floorboards to the west and go down the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Open the door, then go west a bit, then south to the building with the fireplace.",
                        npcs = {},
                    },
                    {
                        text = "Enter the building and climb up the ladder, where you will briefly be held up by two vyrewatch.",
                        npcs = {},
                    },
                    {
                        text = "Now jump over the wall to the building to the west and climb down the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Open the door, exit and close the door.",
                        npcs = {},
                    },
                    {
                        text = "Now go north and west around the next building. Enter it and go east, where Vertida will be standing and talk to him.",
                        npcs = {},
                    },
                    {
                        text = "Climb the wall and speak to Mekritus A'hara.",
                        npcs = { "Mekritus A'hara" },
                    },
                    {
                        text = "Stand on the lookout point for a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Drop-down the floorboards to the east.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Nessie who is in the courtyard south of the building.",
                        chat = "1 How do you know my name? / 1 What are you doing here?",
                        npcs = {},
                    },
                },
            },
            {
                title = "Entering Darkmeyer", needed = {},
                steps = {
                    {
                        text = "Attack Vanescula Drakan - she will knock you back (if she does not knock you back, dismiss any active conjured spirits, unequip any armour, and climb up and back down the wall to the east, then try talking to her again).",
                        npcs = { "Vanescula Drakan", "Conjuration" },
                    },
                    {
                        text = "Talk to her and exhaust all options, eventually learning about the tree and receiving an envelope.",
                        chat = "1 What are you doing here? / 1 How can you help? / 3 I'm not telling you anything, vampyre scum! / 2 How do you plan on freeing Meiyerditch? / 3 You won't get any information out of me. / 1 Why do you want to kill Drakan? / 3 Why should I trust you? / 1 I'll listen, for now. / 3 Tell me more about this tree. / 1 How do I know you are telling the truth?",
                        npcs = {},
                    },
                    {
                        text = "Teleport to Meiyerditch with the medallion and take the envelope to Safalaan.",
                        chat = "2 Meiyerditch",
                        npcs = { "Vanescula's offer" },
                    },
                    {
                        text = "In the same room, talk to Vertida Sefalatis.",
                        chat = "1 What do I need to go to Darkmeyer?",
                        npcs = { "Vertida Sefalatis" },
                    },
                    {
                        text = "Head to the most south-western point within the Meiyerditch hideout. Search the crate for 30 smoke bombs.",
                        npcs = { "Crate (Meiyerditch Myreque base, smoke bomb)", "smoke bomb" },
                    },
                    {
                        text = "With your medallion, teleport to the Meiyerditch laboratory.",
                        chat = "3 Meiyerditch Laboratories",
                        npcs = {},
                    },
                    {
                        text = "Go up the stairs, open the door, go through the slashed tapestry, and then out of the building.",
                        npcs = {},
                    },
                    {
                        text = "Run north and squeeze-through the grate on the north wall.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Vanescula on the other side of the grate. In Darkmeyer, the vyrewatch will attack you when you pass them as opposed to in Meiyerditch.",
                        chat = "1 What did you tell Safalaan? / 1 So, where's this tree? / 1 Yes / 2 I'll get on with it, then.",
                        npcs = { "vyrewatch", "Meiyerditch" },
                    },
                    {
                        text = "Use the smoke bombs to avoid being caught by vampyre juvinates. Do not go near vyrewatch.",
                        npcs = { "vampyre juvinate" },
                    },
                    {
                        text = "Search chests inside buildings to find clothing (four pieces in total). You can use another smoke bomb before the previous one dissipates. Enter a building before your smoke shroud vanishes. Once in a building, immediately close the door.",
                        npcs = {},
                    },
                    {
                        text = "Fix all four pieces and wear them. You no longer need to hide in smoke.",
                        npcs = {},
                    },
                    {
                        text = "Return to Vanescula.",
                        chat = "1 So can I go and get those logs now? / 1 No, of course not.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Gaining Status", needed = {},
                steps = {
                    {
                        text = "Walk up the ramp to the north-east to enter the 1st floor level of the city.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Sanguinus Varnis at the top of the ramp, telling him your vampyre name.",
                        npcs = { "Sanguinus Varnis" },
                    },
                    {
                        text = "Completing vampyric tasks below increases your rating. After completing enough tasks in the middle tier of the city, your rating bar will be half full, allowing progression into the next tier of the city.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Vyrewatch guard in the north-eastern jail.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Middle tier", needed = {},
                steps = {
                    {
                        text = "Complete any of the following tasks until you reach a half-full rating bar and access to the upper tier (proceed to next section).",
                        npcs = {},
                        subs = {
                            { text = "Terrorising Maria Gadderanks,,", chat = "1 Quiet, rat. / 1 What a shame. I'm going to be back later for a tithe. / 1 Enough, vermin! / 1 He's dead. / 1 Silence, wretch! / 1 Perhaps we need to 'dispose' of this one." },
                            { text = "Use the Angry or Laugh emotes several times next to Maria Gadderanks" },
                            { text = "Talk to Maria while wielding the Gadderhammer" },
                            { text = "Talk to Valentina Kaust, drink the vial of blood she gives you (if you are prepared to be damaged for half of your health), and then use either chat option." },
                            { text = "Vandalise the four posters (after getting the task by speaking with Sanguinus Varnis), shown as purple squares on the image, and then report back to Sanguinus Varnis again." },
                            { text = "Recapture six bloodveld younglings (after talking to Grigan Kaninus ). These vanish for long periods of time, so they can appear in places you've already checked. They are displayed as yellow dots on the minimap." },
                            { text = "Talking to Sentinel Draemus, Sentinel Gorthaur, or Sentinel Mortshade about citizens in Meiyerditch, the Myreque, and Burgh de Rott (three conversations)." },
                        },
                    },
                },
            },
            {
                title = "Upper tier", needed = {},
                steps = {
                    {
                        text = "Killing Captured Meiyerditch citizens for the Vyrewatch guards is the fastest way to fill the reputation bar, as each kill gives 2 reputation but there is a limit to how many you can kill in a short period of time. There are about a dozen locked in the jail and they respawn fairly quick. Start the task by talking to a Vyrewatch guard in the south-western jail.",
                        npcs = { "Captured Meiyerditch citizen", "Vyrewatch guard" },
                    },
                    {
                        text = "Entertaining Misdrievus Vakan then approach the nearby blood tither. Talk to Misdrievus Vakan again and then enter the building to the west for a cutscene.",
                        npcs = { "Misdrievus Vakan", "blood tither" },
                    },
                    {
                        text = "Speaking to Vanescula Drakan to pledge allegiance to the Drakan family.",
                        chat = "1 How do I do that? / 1 I pledge fealty to the Drakan family. / 1 I devote my service, land an power to the Drakan before me.",
                        npcs = {},
                    },
                    {
                        text = "Talking to Sentinel Bloodmortis, Sentinel Noctantine, or Sentinel Plaguemanst about Vanstrom Klause and Lord Drakan (two conversations).",
                        npcs = { "Sentinel Bloodmortis", "Sentinel Noctantine", "Sentinel Plaguemanst", "Lord Drakan" },
                    },
                },
            },
            {
                title = "The Arboretum", needed = {},
                steps = {
                    {
                        text = "After gaining enough status in the upper tier, talk to Vanescula about entering the Arboretum.",
                        npcs = { "Arboretum (location)" },
                    },
                    {
                        text = "Enter the Arboretum (Ranis will stop you).",
                        chat = "1 Of course not! / 1 I hereby pledge fealty to you, Ranis Drakan.",
                        npcs = {},
                        subs = {
                            { text = "Arboretum is a big temple-like building to the east" },
                        },
                    },
                    {
                        text = "Proceed to enter the Arboretum.",
                        npcs = {},
                    },
                    {
                        text = "Solve the four puzzles:",
                        npcs = {},
                        subs = {
                            { text = "Check the health of the tree for the orb pattern." },
                            { text = "Pull the lever (along the eastern edge) to start the first puzzle." },
                            { text = "Rotating the orbs by clicking the left-bottom orb of a group of four orbs." },
                            { text = "Match the orbs to the puzzle solution." },
                            { text = "When the puzzle is complete, pull the lever." },
                        },
                    },
                    {
                        text = "Check the health of the tree again. Repeat the process for all four puzzles.",
                        npcs = {},
                    },
                    {
                        text = "Chop the tree for three blisterwood logs and a cutscene will play.",
                        npcs = {},
                    },
                    {
                        text = "In the entrance room to the west, talk to Vanescula to be teleported to out of Darkmeyer.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Preparing for the fight", needed = {},
                steps = {
                    {
                        text = "Use the medallion to go to Meiyerditch.",
                        chat = "3 Meiyerditch",
                        npcs = {},
                    },
                    {
                        text = "Talk to Vertida Sefalatis.",
                        chat = "1 I managed to get some logs from the blisterwood tree. / 1 We may be able to trust her, yes. / 1 I'd be happy to dispatch one of the Myreque's most fearsome opponents.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Vertida again for a bottle of holy water.",
                        npcs = { "Vertida's bottle of holy water" },
                    },
                    {
                        text = "Talk to Kael Forshaw for two silver sickles.",
                        chat = "1 Do you have any sickles I could use? / 2 That's all, thanks.",
                        npcs = { "Kael Forshaw" },
                    },
                    {
                        text = "Use the medallion to teleport back to Darkmeyer.. This will complete the achievement On Wings Of Bling.",
                        chat = "4 Darkmeyer",
                        npcs = { "On Wings Of Bling" },
                    },
                    {
                        text = "Craft each of the logs into a staff, a polearm, and a set of stakes. Remember to set the quantity to 1 in the Build-X interface or you will lose the logs permanently. Fletching the blisterwood polearm leads to the achievement Raising The Stakes.",
                        npcs = { "Blisterwood staff", "Blisterwood polearm", "Blisterwood stake", "Raising The Stakes" },
                        subs = {
                            { text = "If you forgot to cut three logs, you can enter Arboretum without any issues and cut some more." },
                        },
                    },
                    {
                        text = "Bank at the Darkmeyer Treasury. The bottle of holy water is required for the fights with Vanstrom Klause and Harold.",
                        npcs = { "Vanstrom Klause", "Harold (monster)" },
                    },
                    {
                        text = "Enter the house with Harold in it (just north-east of the captured citizens) and kill him with any weapon. You must throw the bottle of holy water over him to be able to kill him.",
                        npcs = {},
                    },
                    {
                        text = "Go back to the bank and prepare for the final fight with Vanstrom Klause who is east of Harold.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The battle with Vanstrom", needed = { "Equip full Darkmeyer disguise, Vertida's bottle of holy water, and a blisterwood weapon of choice" },
                steps = {
                    {
                        text = "Only blisterwood weaponry can deal damage.",
                        npcs = {},
                    },
                    {
                        text = "If you're attacking at a distance use Deflect/Protect from Magic; otherwise, Deflect/Protect from Melee.",
                        npcs = { "Deflect Magic", "Protect from Magic", "Deflect Melee", "Protect from Melee" },
                    },
                    {
                        text = "If he shouts \"Stare into the darkness!\" run to the edge of the arena and rotate your camera away from him. Maximum 4000 damage.",
                        npcs = {},
                    },
                    {
                        text = "If he shouts \"Let the blood consume you!\" run away from the blood splodge on the floor. Maximum 6000 damage.",
                        npcs = {},
                    },
                    {
                        text = "If he shouts \"Come, fiends, and aid your master!\" kill the two easy minions that he spawns.",
                        npcs = {},
                    },
                    {
                        text = "If he throws blood bombs towards you, keep running around the room to avoid them. Maximum 4000 damage per bomb.",
                        npcs = {},
                    },
                    {
                        text = "Once he is very low health he turns into a cloud. Keep using holy water near him until he loses all health. Unequip your ring of life if you're wearing one.",
                        npcs = { "ring of life" },
                        subs = {
                            { text = "If you are saved by a ring of life after a group of bloodveld guardians spawn, heal up and return without a ring of life. You will be damaged, but in a safe way. You will not have to redo the fight." },
                        },
                    },
                    {
                        text = "Use Deflect/Protect from Magic for this last part as Vanstom can do rapid magic damage to you whilst he is dying.",
                        npcs = { "Deflect Magic", "Protect from Magic" },
                    },
                },
            },
            {
                title = "Finishing up in Darkmeyer", needed = {},
                steps = {
                    {
                        text = "Take control of Vanescula and kill the Bloodveld guardians. It is recommended to use the Shriek attack repeatedly as soon as it recharges.",
                        npcs = { "Bloodveld guardian" },
                    },
                    {
                        text = "When you awaken, speak with Vertida, and watch a short cutscene.",
                        chat = "1 What happened? / 1 Vanstrom believed that Safalaan may be the Icyene blood.",
                        npcs = {},
                    },
                    {
                        text = "Teleport to Burgh de Rott with the medallion and talk to Veliaf Hurtz.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "The Branches of Darkmeyer",
                        npcs = { "The Branches of Darkmeyer (achievement)" },
                    },
                    {
                        text = "Got a Vyre Reputation",
                        npcs = { "Got a Vyre Reputation" },
                    },
                    {
                        text = "Morytania achievements",
                        npcs = { "Morytania achievements" },
                        subs = {
                            { text = "Hard - Raising The Stakes" },
                            { text = "Elite - On Wings Of Bling" },
                        },
                    },
                    {
                        text = "Tirannwn achievements",
                        npcs = { "Tirannwn achievements" },
                        subs = {
                            { text = "Elite - Properly Metal" },
                        },
                    },
                },
            },
        },
    },
    {
