    {
        key = "the_chosen_commander", name = "The Chosen Commander", wiki = "The Chosen Commander/Quick guide",
        required = { "A light source", "Full H.A.M. robe outfit (obtained during quest - you are given a new set)", "5,000 coins (if player wrongly accuses an innocent merchant)" },
        recommended = { "Food, armour, and weapon (two different combat styles for fight with H.A.M. agents)", "Underneath Lumbridge Castle, unblock the wall to Lumbridge Swamp Caves south of Kazgar. It must be done from Kazgar's side. This saves a great deal of time later.", "Prayer potions", "Ardougne/Fishing Guild teleports", "Ancient mace", "Dorgesh-kaan sphere" },
        sections = {
            {
                title = "Food poisoning", needed = {},
                steps = {
                    {
                        text = "Talk to Captain Undak, east of the bank (by the eastern water fountain) in Dorgesh-Kaan. (You must dismiss any follower or pet you have or he will not go with you.)",
                        chat = "2 Can I help with anything? / 1 Yes. / 2 Okay. What's your point? / Accept",
                        npcs = { "Captain Undak", "Dorgesh-Kaan" },
                    },
                    {
                        text = "Climb the nearby stairs (slightly north of Undak) and talk to Torzek outside the nursery.",
                        chat = "4 Calm down. I'm here to help. / 1 Have the children eaten anything unusual lately? / 1 What did they have?",
                        npcs = { "Torzek" },
                    },
                    {
                        text = "Talk to any nearby child against the building wall about what they ate.",
                        npcs = {},
                        subs = {
                            { text = "Andil: The chat options may vary from person to person.", chat = "? What food did you eat yesterday?" },
                            { text = "Delgon:", chat = "1 What food did you have yesterday?" },
                            { text = "Gerdi:", chat = "1 What food did you eat yesterday?" },
                        },
                    },
                    {
                        text = "Talk to Captain Undak. (If you are unable to talk with Captain Undak, make sure you do not have \"Hide Familiar options\" checked under Settings>Combat & Action Bar>Choose Option Menu and log out and back in)",
                        chat = "3 I've worked out which foods are poisoned.",
                        npcs = {},
                    },
                    {
                        text = "Go down the stairs and head south to the market.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Markog, at the south-eastern-most stall of the market.",
                        chat = "1 Which merchants have you bought ingredients from?",
                        npcs = { "Markog" },
                    },
                    {
                        text = "Talk to Turgok, at the south-western-most stall of the market.",
                        chat = "1 Which merchants have you bought ingredients from?",
                        npcs = { "Turgok" },
                    },
                    {
                        text = "Talk to Merchant Walton, just outside of the market to the south-east.",
                        chat = "1 This is the one, Captain. / 1 Yes, I'm sure. / 3 [Attack the merchant] / 1 What's that behind you?",
                        npcs = {},
                    },
                    {
                        text = "Proceed to kill the merchant (Zanik will switch to melee if you use ranged).",
                        npcs = {},
                    },
                },
            },
            {
                title = "Zanik", needed = {},
                steps = {
                    {
                        text = "Talk to Zanik.",
                        chat = "Any / Any / 1 Yes! What happened?",
                        npcs = {},
