                    {
                        text = "Climb on the goblin south-west of the bowl statue.",
                        npcs = {},
                    },
                    {
                        text = "Jump on statues to reach the statue holding the bowl of water.",
                        npcs = {},
                        subs = {
                            { text = "If the jump-on option does not appear, try clicking on the head." },
