                    {
                        text = "Climb-down the ladder top and head all the way south.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Zanik.",
                        chat = "4 [Sit down next to Zanik.] / 4 [Say nothing.] / 4 [Say nothing.] / 4 [Say nothing.] / 2 Yes, but you should have respected the council. / Any / 4 What do you wish had happened? / 1 Someday, we'll build that world.",
                        npcs = {},
                    },
                    {
                        text = "Watch the cutscene.",
                        chat = "Any / 3 I have nothing else to say.",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene talk to Zanik.",
                        chat = "4 Goodbye, Zanik.",
                        npcs = {},
