            {
                title = "Beef with H.A.M.", needed = { "Full H.A.M. robe outfit" },
                steps = {
                    {
                        text = "Enter the H.A.M. Hideout in Lumbridge forest.",
                        npcs = { "H.A.M. Hideout", "Lumbridge forest" },
