                    },
                    {
                        text = "Talk to Milton in the windmill near the Fishing Guild, north of the Ardougne lodestone.",
                        chat = "2 How do I get into the H.A.M. base? / 1 Arrav.",
                        npcs = { "Milton", "Fishing Guild" },
                    },
                    {
                        text = "Climb down the ladder inside the windmill.",
                        npcs = {},
                    },
                    {
                        text = "Run directly east through the door, continuing east through stacks of crates.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the guard next to the prison.",
                        chat = "1 I need to see the prisoner. / 1 Letter? / 3 What day is it today? / 3 Never mind.",
                        npcs = {},
                    },
                    {
                        text = "Enter the main area (back through the doors to the west) and pickpocket Sam.",
                        npcs = {},
                    },
                    {
                        text = "Return to the prison guard.",
                        chat = "1 I have my letter here.",
                        npcs = {},
                    },
                    {
                        text = "Enter the prison and take the key, open the gate.",
                        npcs = {},
                    },
                    {
                        text = "Escape with Grubfoot:",
                        npcs = {},
                        subs = {
                            { text = "Talk to the prisoner, Grubfoot.", chat = "4 Wait there. I'll come back for you." },
                            { text = "Run into the kitchen, squeeze through the hole." },
                            { text = "Open 1 of the 2 doors." },
                            { text = "Go back through and open the other door as well." },
                            { text = "Return to Grubfoot.", chat = "1 Let's go / 3 I'll distract the guard so you can make a break for it." },
                            { text = "Stand north of the guard, talk to him to face you and have his back turned. After selecting the chat option, do not continue the conversation until Grubfoot walks past the guard into the next room.", chat = "Any" },
                            { text = "Talk to Grubfoot in the next room.", chat = "2 Wait at the west door; I'll distract the guard." },
                            { text = "Squeeze into the kitchen. Take the dirty plates from the sink, and wait for the H.A.M. guard to come talk to you.", chat = "1 Yes. / Any" },
                            { text = "Talk to Grubfoot in the bedroom.", chat = "1 Follow me." },
                            { text = "Exit the east door and run to the big doors north.", chat = "1 Let's get out of here." },
                        },
                    },
                    {
                        text = "Watch the cutscene and wait for Sigmund to confront you.",
                        npcs = {},
                    },
                    {
                        text = "Kill Sigmund.",
                        chat = "Any",
                        npcs = {},
                        subs = {
                            { text = "If Zanik doesn't attack Sigmund, climb up the ladder, then back down." },
                        },
                    },
                    {
                        text = "Kill Zanik repeatedly.",
                        chat = "1 I won't kill you, Zanik. / 3 Zanik! What's happened to you? / 3 Does our friendship mean nothing to you? / 1 But am I *your* enemy? / 2 Zanik, you're being controlled. Fight it! / 3 Zanik, it's the pendant. Take it off! / 2 You've got to do it, otherwise it will win!",
                        npcs = {},
                        subs = {
                            { text = "Turn off revolution in combat settings and avoid using bleeds and channelled abilities as they cancel the dialogue forcing you to repeat the phase." },
                            { text = "If revolution was left on and dialogue interrupted, run up and then down the ladder to the west to avoid having to fight again." },
                        },
                    },
                },
            },
            {
                title = "Lumbridge caves", needed = {},
                steps = {
