    {
        key = "the_curse_of_arrav", name = "The Curse of Arrav", wiki = "The Curse of Arrav/Quick guide",
        required = { "3 dwellberries", "Ring of life (will be consumed)", "Crossbow and mithril grapple (with rope) or enhanced grappling hook on toolbelt", "Insulated boots", "Familiar with remote view ability such as a macaw (level 41) or a ravenous locust (level 70)", "Combat equipment to survive against a level monster" },
        recommended = { "Desert amulet 2 or higher for unlimited teleports to Nardah", "Amulet of glory (to quickly get to the start point)", "Dramen or lunar staff if not done A Fairy Tale III - Battle at Ork's Rift; or another way of reaching Pollnivneach and Nardah", "Ring of charos (a) - reduced costs for magic carpet", "Desert survival gear", "Trollheim Teleport or climbing boots for mountain pathways", "Salve amulet (e) - bonus enhancement while fighting Arrav", "Varrock Teleport runes (3 air runes, 1 fire rune and 1 law rune) or a Varrock teleport tablet for quicker access to Captain Rovin" },
        sections = {
            {
                title = "Getting to the tunnels", needed = { "Trollheim Teleport or Trollheim tablet or God Wars Dungeon Teleport (or climbing boots if you cannot use the teleports), food and equipment for a level 91 monster, several Mining boosts (if required), 7 backpack spaces" },
                steps = {
                    {
                        text = "Talk to Ali the Wise in Nardah (north-most building).",
                        chat = "Accept / 3 Where is the tunnel entrance? / 3 Time for me to go to Trollweiss, then.",
                        npcs = { "Ali the Wise", "Nardah" },
                        subs = {
                            { text = "To get there: teleport to fairy ring and run south." },
                            { text = "Or teleport to Al Kharid and go south to Shantay Pass, then take a magic carpet to Nardah." },
                        },
                    },
                    {
                        text = "Head to the snowy area northwest of Trollheim, enter the troll tunnels and head north to go through the tunnels, and then head to the east to Ritual plateau tunnels.",
                        npcs = { "Trollheim", "troll tunnels", "Ritual plateau tunnels" },
                        subs = {
                            { text = "Follow the directions on the map below to get to the Ritual plateau tunnels, or use Trollheim Teleport if you have it. If you travel through Death Plateau or Troll Stronghold, you must bring the climbing boots." },
                            { text = "Prepare for combat before going through Trollheim as you don't have any access to bank in there." },
                        },
                    },
                },
            },
            {
                title = "The tunnels", needed = { "7 backpack spaces and equipment to fight Arrav" },
                steps = {
                    {
                        text = "Navigate through the caves by mining the rubble; some rubble must be mined from multiple sides to clear it.",
                        npcs = {},
                        subs = {
                            { text = "Optional: pick up the stone, granite, slate, and shale tablets." },
                            { text = "Optional: Search the small bookcase for notes (a-j) if you want to give all information to Ali the Wise after the quest is completed. There is no reward for doing so." },
                        },
                    },
                    {
                        text = "Enter the room east of the caves.",
                        npcs = {},
                    },
                    {
                        text = "Climb the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Arrav, who will attack you immediately.",
                        npcs = { "Arrav" },
                        subs = {
                            { text = "After he starts attacking you, if you do not auto-retaliate, right-click and attack him." },
                        },
                    },
                    {
                        text = "Fight until he teleports away. The fight will pause multiple times for dialogue.",
                        npcs = {},
                    },
                    {
                        text = "Enter the room to the south and search the tapestry on the west wall for base key and base plans.",
                        npcs = { "base key", "base plans" },
                    },
                    {
                        text = "Travel back to Nardah and speak to Ali the Wise.",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene, speak with Ali the Wise again.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Preparing the jar", needed = { "3 dwellberries, a ring of life and 1 backpack space" },
                steps = {
                    {
                        text = "Enter the nearby Uzer Mastaba pyramid.",
                        npcs = { "Uzer Mastaba" },
                        subs = {
                            { text = "To get there, either run north-east of Ali the Wise, use the nearby magic carpet network to get to Uzer and run south, or teleport to fairy ring DLQ and run east." },
                        },
                    },
                    {
                        text = "Enter the pyramid, head north-west through the imposing doors, then south, down the stairs and talk to Senliten for oil in a canopic jar.",
                        npcs = { "Senliten", "oil in a canopic jar" },
                        subs = {
                            { text = "Players who have completed certain quests can also choose to head directly to the Pharaoh Queen from the pyramid doors." },
                        },
                    },
                    {
                        text = "Use (do not eat) your dwellberries and ring of life on the oil in a canopic jar to obtain a full canopic jar.",
                        npcs = { "dwellberries", "ring of life", "full canopic jar" },
                    },
                    {
                        text = "Return to Ali the Wise and speak to him.",
                        npcs = {},
                        subs = {
                            { text = "If Leela is in the mummy's tomb, she can return you outside the Uzer Mastaba." },
                        },
                    },
                },
            },
            {
                title = "Saving Arrav's heart", needed = { "Insulated boots, either a macaw pouch or a ravenous locust pouch, a method of grappling (either any crossbow and a mithril grapple, or an enhanced grappling hook on your toolbelt), a full canopic jar, the base key, 4 backpack space, and enough summoning points to summon your familiar" },
                steps = {
                    {
                        text = "Go to the Varrock Palace and speak to Hartwin (northwest tower, 3rd floor) to travel to Chaos Temple Dungeon.",
                        npcs = { "Varrock Palace", "Hartwin", "Chaos Temple Dungeon" },
                    },
                    {
                        text = "Climb down the trapdoor.",
                        npcs = {},
                    },
                    {
                        text = "Follow the path, opening three doors along the way.",
                        npcs = {},
                    },
                    {
                        text = "Head east to the room with the range.",
                        npcs = {},
                    },
                    {
                        text = "Equip your insulated boots then enter the pipe on the south wall of the room.",
                        npcs = { "insulated boots" },
                    },
                    {
                        text = "Run through the sewers and attempt to enter the next pipe.",
                        npcs = {},
                    },
                    {
                        text = "Summon your familiar, interact with it and choose the remote view option.",
                        npcs = {},
                    },
                    {
                        text = "Run to the room south of you, search all the tables for decoder strips and notes (k-z).",
                        npcs = { "decoder strips", "notes (k-z)" },
                    },
                    {
                        text = "Right-click pick-lock on the chest to obtain the code key.",
                        npcs = { "code key" },
                    },
                    {
                        text = "Go north to the room east of the pipe and operate the keypad and solve the keypad puzzle:",
                        npcs = {},
                        subs = {
                            { text = "First read the code key and memorise or write down the letters." },
                            { text = "Drag-and-drop strip #1 over the line indicated by the first letter of the code key (A, B, C...)." },
                            { text = "The strip has a hole that reveals a specific number, this is the first digit of the passcode." },
                            { text = "Use the up and down arrows to enter that number, and press the right arrow to move to the next digit." },
                            { text = "Repeat this for the other three strips." },
                        },
                    },
                    {
                        text = "Enter the room, equip your crossbow and mithril grapple, then grapple the pipe above you.",
                        npcs = {},
                    },
                    {
                        text = "Take from the pedestal for a heart in a canopic jar, then teleport out.",
                        npcs = { "heart in a canopic jar" },
                    },
                    {
                        text = "Return to Ali the Wise and speak to him.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "the_darkness_of_hallowvale", name = "The Darkness of Hallowvale", wiki = "The Darkness of Hallowvale/Quick guide",
        required = { "8 nails (any type except rune nails)", "2 planks (regular, oak, teak, or mahogany)", "1 law rune and 1 air rune for Telekinetic Grab (obtainable during the quest)", "1 charcoal (given to you during quest)", "3 papyrus (given to you during quest)" },
        recommended = { "Energy potions and/or an explorer's ring (for a lot of walking and running)", "Garlic can be used to weaken the Vyrewatch so that they do less damage (can be obtained during the quest; inside a chest in the Myreque Hideout in Burgh de Rott.)", "2,000 coins (if you want to buy a set of vyrewatch clothing from Trader Sven)", "Fast travel to several locations", "Burgh de Rott (fairy ring BKR with Swamp Boat)", "Paterdomus (Skeletal horror Teleport, invitation box, fairy ring to CKS, Kharyrll Teleport, Canifis lodestone or Fort Forinthry lodestone)", "Varrock Palace (Varrock teleport, runes for this teleport are provided during the quest, Varrock lodestone, Ring of Wealth or other enchanted rings providing Grand Exchange teleportation)" },
        sections = {
            {
                title = "Starting out", needed = { "2 planks (regular, oak, teak, or mahogany), 8 nails (any type except rune nails)" },
                steps = {
                    {
                        text = "Go to Burgh de Rott, then enter in the inn where you will climb over the broken down wall and climb down trapdoor in the northwest of inn.",
                        npcs = { "Burgh de Rott", "broken down wall", "Trapdoor (Burgh de Rott cellar)" },
                    },
                    {
                        text = "Talk to Veliaf Hurtz in the Burgh de Rott pub basement.",
                        chat = "4 Is there something I can do to help you? / Accept / 1 What is the Sanguinesti region? / 2 How can I search for the Sanguinesti order of the Myreque? / 3 Can you tell me about the Sanguinesti Myreque? / 4 Tell me again how to get into the Sanguinesti region. / 5 Ok, thanks.",
                        npcs = { "Veliaf Hurtz", "Burgh de Rott" },
                        subs = {
                            { text = "Search the chest to the north for garlic if you do not have one." },
                        },
                    },
                    {
                        text = "Run directly south of the furnace until you find a boathouse.",
                        npcs = {},
                    },
                    {
                        text = "Search the boat, then use a plank on it to fix it.",
                        npcs = {},
                    },
                    {
                        text = "South of the boat, use plank on the boat chute to fix it.",
                        npcs = {},
                    },
                    {
                        text = "Push the boat down the chute, then go down to the docks and board the boat. If a Vyrewatch stops you at any point, just activate Freedom and walk away.",
                        npcs = { "Vyrewatch", "Freedom" },
                        subs = {
                            { text = "Keybind may not work, recommended to click the ability on your action bar or in the Defence abilities tab." },
                        },
                    },
                    {
                        text = "Exit the boat by jumping onto the nearby rock, and continue north-west a short distance.",
                        npcs = {},
                    },
                    {
                        text = "Just before the shore, kick down the floor, and climb down it.",
                        npcs = {},
                    },
                    {
                        text = "Climb the wall rubble to the north and talk to a Meiyerditch citizen.",
                        chat = "4 (whisper) Do you know about the Myreque? / 4 (whisper) I really need to meet the Myreque. / 4 How can Old Man Ral help me?",
                        npcs = { "Meiyerditch citizen" },
                    },
                    {
                        text = "North of the wall rubble, talk to Old Man Ral.",
                        chat = "4 Someone said you could help me. / 4 Old Man Ral, the sage of Sanguinesti.",
                        npcs = { "Old Man Ral", "Taskmasters" },
                        tile = { x = 3602, y = 3209, plane = 0 },
                        subs = {
                            { text = "(Optional) If you want to reduce detection chance by the Vyrewatch, you can buy a set of Vyrewatch clothing from Trader Sven just south of Old Man Ral before continuing." },
                        },
                    },
                },
            },
            {
                title = "Navigating Meiyerditch", needed = { "If you get snared by a vyre, you can still get away for free by using Freedom. Another option is to challenge them to a fight and then just running away without attacking. Below are the steps to navigating Meiyerditch from the ladder south-west of Old Man Ral. You can click each step to highlight it to keep track of completed steps. Changing \"Entity Highlight Mode\" in Settings->Accessibility->Visual Accessibility->High Contrast Mode to \"Proximity\" may help during the next steps." },
                steps = {
                },
            },
            {
                title = "Sector 1 directions", needed = {},
                steps = {
                    {
                        text = "Go to the house south-west of Old Man Ral with the door facing north (the western of the two houses with northern doors – it has a sickle next to it on the outside wall). Open the door and enter it.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the ladder there.",
