                    {
                        text = "Jump to the floorboards in the east.",
                        npcs = {},
                    },
                    {
                        text = "Go to the north-east corner of the room, push the wall and walk across the floor.",
                        npcs = {},
                    },
                    {
                        text = "Crawl under the wall to the north.",
                        npcs = {},
                    },
                    {
                        text = "Go north to the second room, look on the west side, push the wall and walk across the floor.",
                        npcs = {},
                    },
                    {
                        text = "Climb down the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Search the table next to the wall, open the trapdoor table, and go through the trapdoor tunnel.",
                        npcs = { "trapdoor tunnel" },
                    },
                    {
                        text = "Climb up the shelf next to the sickle logo in the north-west corner of the room.",
                        npcs = {},
                    },
                    {
                        text = "Crawl under the wall to the east side.",
                        npcs = {},
                    },
                    {
                        text = "Jump to the floorboards in the east.",
                        npcs = {},
                    },
                    {
                        text = "Climb down the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Search the pots near the eastern door to get a key and use it to open the door.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Sector 2 directions", needed = {},
                steps = {
                    {
                        text = "Climb up the ladder in the room to the east, by the sickle.",
                        npcs = {},
                    },
                    {
                        text = "Jump to the floorboards in the south.",
                        npcs = {},
                    },
                    {
                        text = "Go east, south, west then climb up the shelf to the south.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the ladder in the west.",
                        npcs = {},
                    },
                    {
                        text = "Jump to the floorboards in the south.",
                        npcs = {},
                    },
                    {
                        text = "Walk a little to the south-west and climb down the ladder once.",
                        npcs = {},
                    },
                    {
                        text = "Go east through the rooms and walk across the washing line.",
                        npcs = {},
                    },
                    {
                        text = "Climb down the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Push the wall to the north and walk across the floor.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the shelf to the north.",
                        npcs = {},
                    },
                    {
                        text = "Climb down the shelf in the north-eastern corner.",
                        npcs = {},
                    },
                    {
                        text = "Jump to the floorboards in the north.",
                        npcs = {},
                    },
                    {
                        text = "Jump to the floorboards in the north again.",
                        npcs = {},
                    },
                    {
                        text = "Go to the north end of the house and jump to the floorboards in the east.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the ladder to the east.",
                        npcs = {},
                    },
                    {
                        text = "Search the wall to the west to get the ladder top.",
                        npcs = { "ladder top" },
