                    },
                    {
                        text = "Search the portrait again to pick up a large ornate key.",
                        npcs = { "large ornate key" },
                    },
                    {
                        text = "Talk to Safalaan in the base and give him the message.",
                        chat = "2 I have a message for you Safalaan - it may be important.",
                        npcs = {},
                    },
                    {
                        text = "Leave the hideout, push the wall, climb the stairs, jump the gap, down the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Run north through three doors.",
                        npcs = {},
                    },
                    {
                        text = "Head to north-east in Meiyerditch (follow the eastern wall north). There is a bright red and yellow tapestry (with a door on the east side of the room).",
                        npcs = { "Tapestry (Meiyerditch)" },
                    },
                    {
                        text = "Look-at the tapestry and slash it with a knife.",
                        npcs = {},
                    },
                    {
                        text = "Walk-through the slashed tapestry.",
                        npcs = { "slashed tapestry" },
                    },
                    {
                        text = "Use the large ornate key on the vampyre statue.",
                        npcs = { "vampyre statue" },
