    {
        key = "the_dig_site", name = "The Dig Site", wiki = "The Dig Site/Quick guide",
        required = { "Charcoal (can be obtained during quest)", "Cup of tea (can be obtained during quest)", "Vial", "2 ropes (can be pick-pocketed from the Dig Site workmen)", "Uncut/cut opal (an uncut version can be acquired during the quest)" },
        recommended = { "An Archaeology journal from the Archaeology Guild to teleport to the Varrock Dig Site" },
        sections = {
            {
                title = "Starting out", needed = { "1 backpack space" },
                steps = {
                    {
                        text = "Speak to an examiner in the Exam Centre.",
                        npcs = { "examiner", "Exam Centre" },
                        subs = {
                            { text = "Teleport to the Archaeology Campus by using the archaeology journal and run south-east." },
                        },
                    },
                    {
                        text = "Talk to Seth Minas (site manager) in Archaeology Guild. Make sure you have the unstamped letter otherwise the dialogue with Seth does not progress.",
                        npcs = { "Seth Minas (site manager)", "Archaeology Guild", "unstamped letter" },
                        tile = { x = 3328, y = 3383, plane = 0 },
                    },
                    {
                        text = "Grab a cup of tea from the desk in the south side of the building. It is behind Acting Guildmaster Reiniger or Drew (depends on your progress). Not required if you have one.",
                        npcs = { "cup of tea", "Acting Guildmaster Reiniger", "Drew" },
                    },
                    {
                        text = "Talk to an examiner in the Exam Centre; you will fail the exam.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Lost and found", needed = { "Cup of tea" },
                steps = {
                    {
                        text = "Search the green bushes to the west of the Monolith in the middle of the Archaeology Campus (not the ones to the south, near the fences) until you find a teddy bear.",
                        npcs = {},
                    },
                    {
                        text = "Take the panning tray from the small building south of the screening station.",
                        npcs = { "panning tray" },
                    },
                    {
                        text = "Pan the water to the east of where you found the panning tray. Someone will try to stop you. Give him the cup of tea to pan the water.",
                        npcs = {},
                        subs = {
                            { text = "Pan until you find a special cup." },
                            { text = "Pan until you find an uncut opal if you have not already." },
                        },
                    },
                    {
                        text = "Pickpocket the Dig Site workman in the north-east corner of the dig site until you get an animal skull.",
                        npcs = { "Dig Site workman" },
                    },
                    {
                        text = "Talk to Katarina (student) in the central area of the dig site.",
                        npcs = { "Katarina (student)" },
                    },
                    {
                        text = "Talk to her again.",
                        npcs = {},
                    },
                    {
                        text = "Run south-east, talk to Dorian (student).",
                        npcs = { "Dorian (student)" },
                    },
                    {
                        text = "Talk to him again.",
                        npcs = {},
                    },
                    {
                        text = "Run west, talk to Eduardo (student) who can be found in the dig spot closest to the well.",
                        npcs = { "Eduardo (student)" },
                    },
                    {
                        text = "Talk to him again.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Exams", needed = { "Opal" },
                steps = {
                    {
                        text = "Return to an examiner.",
                        chat = "1 Yes, I certainly am. / 1 The study of the earth, its contents and history. / 3 All that have passed the appropriate Earth Sciences exam. / 2 Proper tools must be used.",
                        npcs = {},
                    },
                    {
                        text = "Talk to all 3 students again.",
                        npcs = {},
                    },
                    {
                        text = "Return to an examiner.",
                        chat = "1 I am ready for the next exam. / 3 Samples taken in rough form; kept only in sealed containers. / 1 Finds must be carefully handled. / 2 Always handle with care; strike cleanly on its cleaving point.",
                        npcs = {},
                    },
                    {
                        text = "Talk to all 3 students again.",
                        npcs = {},
                        subs = {
                            { text = "Katarina will demand an opal (talk to her again). You can obtain this by panning." },
                        },
                    },
                    {
                        text = "Return to an examiner.",
                        chat = "1 I am ready for the last exam... / 1 Samples cleaned, and carried only in specimen jars. / 1 Brush carefully and slowly using short strokes. / 3 Handle bones very carefully and keep them away from other samples.",
                        npcs = {},
                    },
                    {
                        text = "Optional: Give Seth Minas (site manager) the level 1, 2 and 3 certificates to receive a Fruit Blast or a chocolate cake. The Fruit Blast can be saved for the quest Recipe for Disaster: Another Cook's Quest.",
                        npcs = { "Seth Minas (site manager)", "Level 1 certificate", "Level 2 certificate", "Level 3 certificate", "Fruit Blast", "chocolate cake", "Recipe for Disaster: Another Cook's Quest" },
                    },
                },
            },
            {
                title = "Helping the expert", needed = { "2 ropes (or pickpocket Dig Site workman until you get enough), specimen jar, specimen brush" },
                steps = {
                    {
                        text = "Dig at the level 3 grid until you find an ancient talisman. It may take over 40 attempts to get it.",
                        npcs = { "level 3 grid", "ancient talisman" },
                    },
                    {
                        text = "Talk to Terry Balando back at the Exam Centre.",
                        npcs = { "Terry Balando" },
                    },
                    {
                        text = "Go to the north-eastern winch (a square hole in the ground with a rope going down it), at a dig site north from Dorian. You will also find Elissa wandering nearby and a training grid near the winch.",
                        npcs = { "Elissa", "training grid" },
                    },
                    {
                        text = "Operate the winch three times to hand in your invitation, attach a rope, and climb down.",
                        npcs = {},
                    },
                    {
                        text = "Search the brick east of the rope.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Climb back up, then climb down the winch near Katarina to the southwest.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Doug Deeping to receive a chest key.",
                        chat = "4 How could I move a large pile of rocks?",
                        npcs = { "Doug Deeping" },
                    },
                },
            },
            {
                title = "Explosives expert", needed = { "Chest key, vial, trowel" },
                steps = {
                    {
                        text = "Go back to the northeastern winch and climb down, use the key to unlock the chest in the north east room and search it for ammonium nitrate.",
                        npcs = { "ammonium nitrate" },
                    },
                    {
                        text = "Pick up the arcenia root next to the chest.",
                        npcs = { "arcenia root" },
                    },
                    {
                        text = "Use a trowel on the closed barrel directly east of the chest.",
                        npcs = {},
                    },
                    {
                        text = "Use a vial on the barrel.",
                        npcs = {},
                    },
                    {
                        text = "If needed, take a charcoal from the sack of charcoal north of the barrel.",
                        npcs = { "charcoal", "sack of charcoal" },
                    },
                    {
                        text = "Grind the charcoal.",
                        npcs = {},
                    },
                    {
                        text = "Mix the nitroglycerine and ammonium nitrate together, add ground charcoal, then finally add the arcenia root.",
                        npcs = {},
                    },
                    {
                        text = "Search the bricks to the south and select the compound on the brick.",
                        npcs = {},
                    },
                    {
                        text = "Search the brick again, select your tinderbox.",
                        npcs = {},
                    },
                    {
                        text = "Enter the large chamber, take the stone tablet.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing up", needed = { "Stone tablet" },
                steps = {
                    {
                        text = "Use the tablet on Terry Balando in the Exam Centre.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "the_elder_kiln", name = "The Elder Kiln", wiki = "The Elder Kiln/Quick guide",
        required = { "Adamant pickaxe (or better), or a melee weapon if the pickaxe is on the tool belt.", "Melee, magic or ranged armour, weapons, potions, and food.", "Necromancy does not work on TokTz-Ket-Dill.", "A dwarf multicannon is not allowed in all encounters.", "Summoning familiars are not allowed in last encounter." },
        recommended = {},
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to TzHaar-Mej-Jeh at the Birthing Pool in TzHaar City.",
                        npcs = { "TzHaar-Mej-Jeh", "Birthing Pool", "TzHaar City" },
                    },
                },
            },
            {
                title = "Hatching", needed = {},
                steps = {
                    {
                        text = "Keep the gauge within the two arrows using fire spells to heat it and water spells to cool it until the egg hatches.",
                        npcs = {},
                        subs = {
                            { text = "The two TzHaar will also fire occasionally. Keep an eye on them as both may shoot fire spells at the egg simultaneously which could result in overheating." },
                        },
                    },
                    {
                        text = "Talk to TzHaar-Mej-Jeh.",
                        chat = "1 What's a Ga'al? / 2 Why do you do this? / 1 Can't you teach them your ways?",
                        npcs = {},
                    },
                },
            },
            {
                title = "In the pits", needed = { "Combat equipment" },
                steps = {
                    {
                        text = "Go west to the main plaza and talk to TzHaar-Mej-Ak.",
                        chat = "1 I've come for that Ga'al. / 1 Yes.",
                        npcs = { "TzHaar-Mej-Ak" },
                    },
                    {
                        text = "Kill all enemies in the Fight Pits whilst protecting Ga'al-Jeh.",
                        npcs = { "Fight Pits", "Ga'al-Jeh" },
                    },
                    {
                        text = "After the cutscene, kill TzHaar-Ket-Yit'tal.",
                        npcs = { "TzHaar-Ket-Yit'tal" },
                    },
                },
            },
            {
                title = "Path to the kiln", needed = { "1 backpack space" },
                steps = {
                    {
                        text = "Talk to one of the TzHaar-Mejs.",
                        chat = "1 It's the remains of your dead that you use as currency. / 2 Of course I'll help the TzHaar. / 2 Okay. / 3 I had better be on my way.",
                        npcs = {},
                    },
                    {
                        text = "Head east of the plaza to the kiln.",
                        npcs = {},
                    },
                    {
                        text = "Enter the cave.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Room one", needed = { "Adamant pickaxe or better (tool belt only works when using a melee weapon), as well as melee, ranged, or magic weapon and armour" },
                steps = {
                    {
                        text = "Jump the chasm and kill all of the monsters.",
                        npcs = {},
                        subs = {
                            { text = "Do not use protection prayers until the TokTz-Ket-Dill's shell is broken as this will increase the frequency of making the rocks fall on you, dealing over 1,000 damage." },
                            { text = "You need a pickaxe to break the shell of TokTz-Ket-Dill, which is weak against water spell after its shell is broken. Necromancy will not work against him." },
                        },
                    },
                    {
                        text = "Investigate the skeleton at the end of the cavern to receive Journal of Perjour.",
                        npcs = { "Journal of Perjour" },
                    },
                    {
                        text = "Proceed to the next room.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Room two", needed = {},
                steps = {
                    {
                        text = "Take the TokKul on the ground and kill all of the monsters.",
                        npcs = { "TokKul" },
                    },
                    {
                        text = "Proceed to the next room.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Room three", needed = {},
                steps = {
                    {
                        text = "Kill all of the monsters and examine the note in the Journal of Perjour (the book which should be in your backpack).",
                        npcs = { "Journal of Perjour" },
                    },
                    {
                        text = "For the left scale, use the picture to find its resulting sum and put that much tokkul on it. Repeat for the right scale. A Tzhaar number symbol can be higher than 15 that is shown in the picture of this guide on the right.",
                        npcs = {},
                    },
                    {
                        text = "Proceed to the next room.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Room four", needed = {},
                steps = {
                    {
                        text = "Go through the room, jumping over chasms and killing the TokTz-Ket-Dill along the way.",
                        npcs = {},
                    },
                    {
                        text = "Proceed to the next room.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Room five", needed = {},
                steps = {
                    {
                        text = "Kill the monsters in this room.",
                        npcs = {},
                    },
                    {
                        text = "Proceed to the next room.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The elder kiln", needed = {},
                steps = {
                    {
                        text = "Complete all seven waves of the Kiln.",
                        npcs = {},
                    },
                    {
                        text = "Talk to TokHaar-Hok.",
                        chat = "2 Let's see what rock you're forged from, then. / 5 I need your help. / 2 I think he should, so the Ga'al can live good lives.",
                        npcs = { "TokHaar-Hok" },
                    },
                },
            },
            {
                title = "Finishing up", needed = { "2 backpack spaces" },
                steps = {
                    {
                        text = "Proceed back through the caves, ignoring monsters along the way.",
                        npcs = {},
                        subs = {
                            { text = "Teleporting away and attempting to avoid heading back through the caves will result in the player being forced to return where Ga'al Xox was left at the kiln, then head back through the caves as originally intended." },
                        },
                    },
                    {
                        text = "Return to the centre of the Main Plaza and talk to one of TzHaar-Mejs.",
                        chat = "1 Even after all we've done, you can't trust the Ga'al? / 2 [Let Ga'al-Xox fight] / 3 I'm only interested in the power of that Kiln.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "the_eyes_of_glouphrie", name = "The Eyes of Glouphrie", wiki = "The Eyes of Glouphrie/Quick guide",
        required = { "1 ground mud rune (made by clicking on a mud rune in your inventory)", "1 maple log", "1 oak log", "A bucket of sap (obtained by using an empty bucket on an evergreen or acadia tree with a knife on your tool belt)" },
        recommended = { "A long-range weapon (Chargebow, staff of air, halberd, etc.) to kill an evil creature that tends to get stuck behind some obstacles, unreachable by melee.", "Access to the fairy ring transportation system or Yanille lodestone activated", "Quick access to a Spirit Tree (i.e. Ring of duelling to South Feldip Hills Teleport or Teleport to Varrock by the Grand Exchange)" },
        sections = {
            {
                title = "Digression", needed = {},
                steps = {
                    {
                        text = "Talk to Brimstail in a cave west of the bank in the Gnome Stronghold. Look for dungeon link on minimap",
                        chat = "1 What's that cute creature wandering around? / 1 Yes, that sounds fascinating... / 1 Oh, yes I love a bit of History. / Accept",
                        npcs = { "Brimstail" },
                        tile = { x = 2406, y = 3420, plane = 0 },
                    },
                },
            },
            {
                title = "Elven Mystery", needed = {},
                steps = {
                    {
                        text = "Inspect the singing bowl in the western portion of the cave.",
                        npcs = {},
                    },
                    {
                        text = "To the north, attempt to unlock Oaknock's machine and use Oaknock's exchanger.",
                        npcs = { "Oaknock's machine", "Oaknock's exchanger" },
                    },
                    {
                        text = "Talk to Brimstail.",
                        chat = "1 I've had a look in the other room now. / 1 Of course, I'd love to!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Memories", needed = {},
                steps = {
                    {
                        text = "Talk to Hazelmere (island east of Yanille, fairy ring CLS) for several cutscenes. He provides you with a violet pentagon.",
                        npcs = { "Hazelmere" },
                    },
                    {
                        text = "Return and talk to Brimstail.",
                        chat = "1 I've visited Hazelmere, he told me all sorts of interesting things.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Incapacitated", needed = {},
                steps = {
                    {
                        text = "Grind mud rune and use on bucket of sap.",
                        npcs = { "mud rune", "bucket of sap" },
                    },
                    {
                        text = "Use the magic glue and a set of maple and oak logs on Oaknock's exchanger and repair it.",
                        npcs = { "magic glue" },
                    },
                    {
                        text = "Talk to Brimstail.",
                        chat = "1 I think I've fixed the machine now!",
                        npcs = {},
                    },
                    {
                        text = "Talk to him again three or more times to receive more discs. You will need to drop all of your discs and pick them back up after chatting to receive more discs. The more discs, the more streamlined the process in the next step becomes as you require little to no converting.",
                        chat = "1 I can't work out what to do with these discs!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Machinery", needed = {},
                steps = {
                    {
                        text = "Unlock machine to view the desired number.",
                        npcs = { "Oaknock's machine" },
                    },
                    {
                        text = "If necessary, use the exchanger to get a disc equal to your number (refer to conversion chart below, insert not more than 35 points at a time). If you have trouble converting, refer to the full guide here.",
                        npcs = { "Oaknock's exchanger", "The Eyes of Glouphrie" },
                    },
                    {
                        text = "Unlock the machine with the correct value disc. Click the small green square to submit the disc.",
                        npcs = {},
                    },
                    {
                        text = "Unlock the machine again to get 3 different numbers (the second unlock will require many more discs). Use the exchanger as necessary. The second number requires using 2 discs and the third requires 3 discs.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Brimstail.",
                        chat = "1 Phew! I've got that machine working now. What do I need to do now?",
                        npcs = {},
                    },
                },
            },
            {
                title = "Assassination", needed = {},
                steps = {
                    {
                        text = "Kill the evil creature by Brimstail and talk to him again. (1/6).",
                        npcs = { "evil creature" },
                    },
                    {
                        text = "Kill the 5 remaining evil creatures, which can be done in any order:",
                        npcs = {},
                        tile = { x = 2446, y = 3457, plane = 0 },
                        subs = {
                            { text = "(2/6) By the main gate to the stronghold (south-east from Brimstail's cave)" },
                            { text = "(3/6) South of the spirit tree by the gnome agility course entrance." },
                            { text = "(4/6) In the giant tortoise pen north-west of the Grand Tree and north of the swamp." },
                            { text = "(5/6) Top floor of the Grand Tree, next to the small prison/by the ladder (wait for the chat response saying you killed it before using the ladder. If it doesn't count it, an evil creature should respawn at one of the locations.)" },
                            { text = "(6/6) Near King Narnode (may need ranged, magic or necromancy as it can get stuck behind a trapdoor). Check your quest journal if your chat log does not display 6 creatures, if it says you need to talk to the king then you are finished." },
                        },
                    },
                    {
                        text = "Talk to King Narnode Shareen on the 1st floor of the Grand Tree.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "The Eyes of Glouphrie",
                        npcs = { "The Eyes of Glouphrie (achievement)" },
                    },
                },
            },
        },
    },
    {
        key = "the_feud", name = "The Feud", wiki = "The Feud/Quick guide",
        required = { "Desert disguise (buy Kharidian headpiece and fake beard from Ali's Discount Wares or the Pollnivneach General Store to make it)", "At least 1,000 coins (a ring of charos will reduce the cost of carpet rides)", "A pair of leather gloves (can be replaced by combat gloves)", "A bucket (there are two bucket spawns in Sami the Camel Man's shop)", "3 beer (can be purchased from Faisal the Barman)", "If you have already obtained red hot sauce from Isma'il the Kebab seller, he will not give you another one. Therefore, you need to bring the red hot sauce he already gave you." },
        recommended = { "Equipment to kill two champions. If the fights are worrisome, bring some food and/or a few prayer potions and/or a ring of life", "A few waterskins (if you plan to walk to Pollnivneach)", "Broomstick or amulet of glory (for faster teleports to Shantay Pass)", "The Pollnivneach General Store and Ali's Discount Wares at the quest start sells most of the items needed" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to Ali Morrisane in Al Kharid.",
                        chat = "1 If you are, then why are you still selling goods from a stall? / 2 I'd like to help you but.... / Accept / 1 No, I'm really too busy.",
                        npcs = { "Ali Morrisane", "Al Kharid" },
                        tile = { x = 3303, y = 3211, plane = 0 },
                        subs = {
                            { text = "If you do not have desert disguise, buy Kharidian headpiece and fake beard from the shop and then use these items on each other.", chat = "1 If you are, then why are you still selling goods from a stall? / 2 I'd like to help you but.... / Accept / 2 Okay." },
                        },
                    },
                },
            },
            {
                title = "In Pollnivneach", needed = { "3 beer (or 6 coins to buy them from Faisal the Barman)" },
                steps = {
                    {
                        text = "Travel to south Pollnivneach (talk to the rug merchant just outside Shantay Pass to get there using a magic carpet).",
                        npcs = { "Pollnivneach", "rug merchant", "Shantay Pass", "magic carpet" },
                    },
                    {
                        text = "Head to the local bar.",
                        npcs = {},
                        subs = {
                            { text = "If you do not have three glasses of beer, talk to Faisal the Barman to buy them.", chat = "1 Yes, I'd like a drink please." },
                        },
                    },
                    {
                        text = "Right-click to use three glasses of beer on Jalal the Drunk. Finish the dialogue with each beer.",
                        npcs = { "Jalal the Drunk" },
                    },
                    {
                        text = "Talk to a Menaphite Thug, who can be found inside the bar or outside the west side of the bar. Make sure to right-click to avoid attacking him.",
                        npcs = { "Menaphite Thug" },
                    },
                    {
                        text = "Talk to a brigand or bandit in the North Pollnivneach. Again, right-click to talk to him.",
                        npcs = { "brigand", "Bandit (Pollnivneach)" },
                    },
                },
            },
            {
                title = "Trading the camels", needed = { "500 coins, bucket (or pick 1 up in Sami the Camel Man's shop)" },
                steps = {
                    {
                        text = "Head to the kebab seller north-west of the well in the town centre. The map icon is.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Isma'il the Kebab seller to buy red hot sauce from him.",
                        chat = "3 Would you sell me that bottle of special kebab sauce? / 2 No thanks, I'm good.",
                        npcs = { "Isma'il the Kebab seller", "red hot sauce" },
                    },
                    {
                        text = "In the house immediately to the south-west, talk to Sami the Camel Man to ask for two camels. Offer 500 coins.",
                        chat = "4 Are those camels around the side for sale? / 2 What price do you want for both of them? / 3 Would 500 gold coins for the pair of them do?",
                        npcs = { "Sami the Camel Man" },
                    },
                    {
                        text = "Use the red hot sauce on a trough in the pen west of the camel shop.",
                        npcs = { "Trough (Pollnivneach)" },
                    },
                    {
                        text = "Pick up the dung with a bucket in the backpack if the dung is brown. If it is green, use more sauce on a trough until it is brown.",
                        npcs = { "Dung (camel)", "bucket" },
                        subs = {
                            { text = "2 empty buckets can be found in the camel shop." },
                            { text = "Obtain more buckets of dung if you plan to complete Dealing with Scabaras (1 bucket, does not consume) and My Arm's Big Adventure (3 buckets)." },
                        },
                    },
                    {
                        text = "Talk to a Menaphite Thug to the south to give them one of the camel receipts.",
                        npcs = { "Menaphite Thug", "receipt" },
                    },
                    {
                        text = "Talk to a brigand or bandit to the north to give them the other receipt.",
                        npcs = { "brigand", "Bandit (Pollnivneach)", "receipt" },
                    },
                },
            },
            {
                title = "Pickpocketing villagers", needed = { "10 coins" },
                steps = {
                    {
                        text = "Go south-west of Pollnivneach to a big purple tent and talk to Rashid the Operator to join his gang.",
                        chat = "1 Yes, of course, those bandits should be taught a lesson. / 2 No thanks.",
                        npcs = { "Rashid the Operator" },
                    },
                    {
                        text = "Attempt to pickpocket a villager. You will fail and take 20 damage.",
                        npcs = { "villager" },
                    },
                    {
                        text = "Talk to Rashid the Operator for advice.",
                        chat = "1 Yeah, I could do with a bit of advice. / 2 No thanks.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the street urchin near the well or the fountain. Pay him ten coins and then pickpocket the villager with an arrow over their head. You will fail again and take 20 damage.",
                        npcs = { "street urchin" },
                    },
                    {
                        text = "Talk to Rashid the Operator.",
                        chat = "1 Yeah, I could do with a bit of advice.",
                        npcs = {},
                    },
                    {
                        text = "Wield the oak-blackjack.",
                        npcs = { "oak-blackjack" },
                    },
                    {
                        text = "Lure a villager into a secluded area. Knock out the villager with the blackjack and pickpocket them.",
                        npcs = {},
                    },
