        required = { "A raw shark, raw manta ray or raw sea turtle (any of the three will work, and sharks are typically the cheapest)", "5,250 coins", ";Obtainable during quest:", "A beer", "Raw potato", "Cabbage", "Onion" },
        recommended = { "Activated Fremennik Province and Seers' Village lodestone", "Ring of recoil for lower-levelled players, in the fight against Koschei the deathless", "Spirit terrorbird, (Super) energy potions, explorer's ring or other method of restoring energy", "A player-owned house located at Rellekka, could save time (requires Level 30 Construction)" },
