                        npcs = { "swaying tree" },
                    },
                    {
                        text = "Chop off a branch and craft it into an unstrung lyre.",
                        npcs = { "branch", "unstrung lyre" },
                    },
                    {
                        text = "Head south-east and talk to Lalli.",
                        chat = "1 Other human?",
                        npcs = { "Lalli" },
                    },
                    {
                        text = "Talk to Askeladden south of the longhall.",
                        npcs = { "Askeladden" },
                    },
                    {
                        text = "Grab a raw potato, an onion, and cabbage from the farm in south-east Rellekka. It's recommended to pick an extra onion and cabbage in case you accidentally eat them.",
                        npcs = {},
                    },
                    {
                        text = "\"Use\" the potato, onion, cabbage, and pet rock on Lalli's Stew.",
                        npcs = { "Lalli's Stew" },
                    },
                    {
                        text = "Talk to Lalli to obtain a golden fleece.",
                        npcs = { "golden fleece" },
                        subs = {
                            { text = "Use the drop trick to obtain another if you plan on completing Kili's Knowledge VII." },
                        },
                    },
                    {
                        text = "\"Use\" the golden fleece on a spinning wheel to make golden wool. There's one in south-west Rellekka.",
                        npcs = { "golden fleece", "golden wool" },
                    },
                    {
                        text = "Use the wool on the unstrung lyre.",
                        npcs = {},
                    },
                    {
                        text = "Use your raw shark, manta ray or sea turtle on the strange altar south-west of Rellekka.",
                        npcs = { "strange altar" },
                    },
                    {
                        text = "Enter the backstage of the longhall through the north-east door. Play the enchanted lyre in front of the crowd. You will receive Olaf's vote.",
                        npcs = { "enchanted lyre" },
                    },
                },
            },
            {
                title = "Sigli the Huntsman", needed = { "Combat gear" },
                steps = {
                    {
                        text = "Talk to Sigli the Huntsman near Rellekka's southern entrance.",
                        chat = "1 What's a Draugen? / 1 Yes.",
                        npcs = { "Sigli the Huntsman" },
                    },
                    {
                        text = "Use the received hunters' talisman to locate and kill The Draugen. The Draugen is not visible until you get close to his location. Look for a tiny grey butterfly. There are only a few of these, one of which is the Draugen. Once in melee distance of the butterfly, use the 'Locate' function on the talisman once again, The Draugen will appear.",
                        npcs = { "hunters' talisman", "The Draugen", "Butterfly (Draugen)" },
                    },
                    {
                        text = "Return to Sigli to receive his vote.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Sigmund The Merchant", needed = { "5,000 coins" },
                steps = {
                    {
