            {
                title = "Swensen the Navigator", needed = {},
                steps = {
                    {
                        text = "Talk to Swensen the Navigator in his house south-west of the longhall.",
                        chat = "1 Yes",
                        npcs = {},
                    },
                    {
                        text = "Go down the ladder in the small room in his house. In each room, there are four portals. Enter them in the correct order to receive his vote. The first letter of each direction spells out the name SWENSEN. The correct order is as follows:",
                        npcs = {},
                        subs = {
                            { text = "South" },
                            { text = "West" },
                            { text = "East" },
                            { text = "North" },
                            { text = "South" },
                            { text = "East" },
                            { text = "North" },
                        },
                    },
                    {
                        text = "Climb up the ladder, then talk to Swensen to receive his vote.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Thorvald the Warrior", needed = { "A lot of food (such as sharks), rings of recoil, super attacks, super strengths, and super defences. Weapon poison also works. Make sure to store all armour and weapons prior to visiting Thorvald. You may speak to Peer the Seer and deposit your items; you cannot use the right click option." },
                steps = {
                    {
                        text = "Talk to Thorvald the Warrior in the helmet store north of the longhall. In order to receive his vote, you must kill a special warrior called Koschei the Deathless. However, the fight has three rules:",
                        chat = "1 Yes.",
                        npcs = { "Koschei the Deathless" },
                    },
                    {
                        text = ": You must defeat him at least three out of four times.",
                        npcs = {},
                    },
                    {
                        text = ": You must fight to the death.",
                        npcs = {},
                    },
                    {
                        text = ": You are not allowed to use weapons or armour or beasts of burden. This also means no runes, staves, etc (you can use food, prayer, rings of recoil, already summoned familiars, a pickaxe or hatchet removed from your tool belt, or even a dismantled godsword).",
                        npcs = {},
                    },
                    {
                        text = "Climb down the ladder and wait for him to appear to begin the fight.",
                        npcs = {},
                    },
                    {
                        text = "Defeat him three times and either kill him the fourth time or let yourself be defeated. (You will not die).",
                        npcs = {},
                    },
                    {
                        text = "Talk to Thorvald to receive his vote.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Peer the Seer", needed = {},
                steps = {
                    {
                        text = "Speak to Peer the Seer, who can be found south-west of the market in Rellekka. or if you've completed the easy Fremennik achievements",
                        chat = "1 Yes. / 2 The Fremennik Trials / 1 Yes",
                        npcs = {},
                    },
                    {
                        text = "To enter his house, you must solve a simple riddle. The riddle gives hints to letters in a four-letter word. Possible answers include: \"tree\", \"time\", \"life\", \"mage\", \"fire\", \"wind\", \"mind\" and \"disk\".",
                        npcs = {},
                    },
                    {
                        text = "Enter the building and climb the ladder.",
                        npcs = {},
                        subs = {
                            { text = "Study the unicorn's head for an old red disk." },
                            { text = "Study the bull's head for a wooden disk." },
                            { text = "Search the bookcase for a red herring." },
                            { text = "Open then search the eastern chest for an empty jug." },
                            { text = "Open then search the south-west cupboard for an empty bucket." },
                        },
                    },
                    {
                        text = "Use the red herring on the cooking range to get sticky red goop.",
                        npcs = { "sticky red goop" },
                    },
                    {
                        text = "Use the goop on the wooden disk to get a second red disk.",
                        npcs = { "red disk" },
                    },
                    {
                        text = "Go down the eastern trapdoor and use the two disks on the abstract mural for a vase lid.",
                        npcs = { "abstract mural", "vase lid" },
                    },
                    {
                        text = "Climb the ladder.",
                        npcs = {},
                        subs = {
                            { text = "Use the empty jug on the tap, then the full jug on the empty bucket." },
                            { text = "Use the empty jug on the tap again and fill the bucket. You'll have a full bucket and a 1/3rds full jug." },
                            { text = "Use the full bucket on the drain to get an empty bucket. Or search the cupboard again." },
                            { text = "Use the 1/3rds full jug on the empty bucket." },
                            { text = "Use the empty jug on the tap, then use the full jug on the 1/5ths full bucket to get a 4/5ths full bucket." },
                            { text = "Use the 4/5ths full bucket on the northwestern chest to receive a vase." },
                            { text = "Use the vase on the tap." },
                            { text = "Use the vase lid on the vase of water to get a sealed vase." },
                        },
                    },
                    {
                        text = "Use the sealed vase on the frozen table to receive a frozen key.",
                        npcs = { "Frozen key (The Fremennik Trials)" },
                    },
                    {
                        text = "Use the frozen key on the range, then go down the eastern trapdoor again and out the exit. You will receive Peer the Seer's vote.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing up", needed = { "10 free inventory slots" },
                steps = {
                    {
                        text = "Talk to Brundt the Chieftain in the longhall in Rellekka.",
                        npcs = { "Brundt the Chieftain", "Rellekka" },
                    },
                    {
                        text = "Congratulations, quest complete!",
                        npcs = {},
                    },
