        key = "the_general_s_shadow_miniquest", name = "The General's Shadow (miniquest)", wiki = "The General's Shadow (miniquest)/Quick guide",
        required = { "40 coins (70 coins if using boat to Karamja)", "Ghostspeak amulet or cramulet (not necessary with hard Morytania achievements completed)", "The full ghostly robe outfit", "A ring of visibility" },
        recommended = { "Fremennik Province lodestone unlocked", "Nature altar teleport", "Traveller's necklace to teleport to the Outpost south of the Grand Tree", "Amulet of glory for teleport to Shantay Pass (Al Kharid option)", "Draynor lodestone unlocked", "Skills necklace for teleport to the Fishing Guild", "Waterskins or an enchanted water tiara for the desert heat if you have not yet completed Crocodile Tears", "Armour", "A weapon", "Some food" },
        sections = {
            {
                title = "Ghosting", needed = {},
                steps = {
                    {
                        text = "Equip all ghostly robe outfit, the ring of visibility and a ghostspeak amulet or cramulet.",
                        npcs = { "ghostly robe outfit", "ring of visibility", "ghostspeak amulet", "cramulet" },
                    },
                    {
                        text = "South of the Fremennik Province lodestone and just south-west of the swaying tree, find and then talk to the ghost of General Khazard.",
                        chat = "1 Uh, well, you don't really have eyes, so how can you tell? / Accept",
                        npcs = { "Fremennik Province lodestone", "swaying tree" },
                        subs = {
                            { text = "Khazard, and all of the ghost scouts you'll locate next, cannot be seen on the minimap and have a fair-sized wander radius." },
                            { text = "It is recommended to use the skybox bloodstone if the player has completed The Lord of Vampyrium quest but can be done without, or use High Contrast Mode under Accessibility Options." },
                        },
                    },
                    {
                        text = "Talk to Sin Seer in Seers' Village. She is upstairs in the spinning wheel house.",
                        chat = "1 Bribe / 1 Here's the money.",
                        npcs = { "Sin Seer", "Seers' Village" },
                    },
                    {
                        text = "Return to General Khazard.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the ghost scout south-east of Tai Bwo Wannai (search between the hardwood grove and the drakolith mine).",
                        npcs = { "Scout (Tai Bwo Wannai)", "Tai Bwo Wannai", "hardwood grove" },
                    },
                    {
                        text = "Talk to the ghost scout south of the Tree Gnome Stronghold entrance (east of the Outpost).",
                        npcs = { "Scout (Tree Gnome Stronghold)", "Tree Gnome Stronghold", "Outpost" },
                    },
                    {
                        text = "Talk to the ghost scout in the area between Falador and Draynor Manor.",
                        npcs = { "Scout (Falador)", "Falador", "Draynor Manor" },
                    },
                    {
                        text = "Talk to the ghost scout south of the Shantay Pass.",
                        npcs = { "Scout (Shantay Pass)", "Shantay Pass" },
                    },
                    {
                        text = "Return to General Khazard.",
                        npcs = {},
                    },
                    {
                        text = "Prepare for battle before fighting against a level 91 enemy.",
                        npcs = {},
                    },
                    {
                        text = "Enter the goblin cave east of the Fishing Guild.",
                        npcs = { "Fishing Guild" },
                    },
                    {
                        text = "Run to the northeast \"room\" and enter the crack in the southern wall.",
                        chat = "1 Yes",
                        npcs = {},
                    },
                    {
                        text = "Kill the Bouncer. You'll throw the severed leg when its health reaches 0.",
                        npcs = { "severed leg" },
                        subs = {
                            { text = "If Bouncer's health is stuck at 0, the player should leave the room, dismiss any familiars, and reenter to try killing Bouncer again. Once at 0 health, continue clicking on him until your character automatically throws the severed leg." },
                        },
                    },
                    {
                        text = "Miniquest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "the_giant_dwarf", name = "The Giant Dwarf", wiki = "The Giant Dwarf/Quick guide",
        required = { "200 coins", "Any logs that you can set fire to", "1 coal", "1 iron bar", "Runes to cast Telekinetic Grab (1 law rune and 1 air rune)", "3 cut sapphires", "1 Redberry pie (not required if you have completed The Knight's Sword quest)", "About 10 of each of the following items in your bank or metal bank, which may or may not be necessary for the timed delivery tasks. There is the Keldagrim bank and a metal bank access in Keldagrim, so you don't have to carry everything there. Once you're there, take the items out for use in the quest.", "Clay (not soft clay)", "Copper ore", "Tin ore", "Iron ore", "Silver ore", "Gold ore", "Mithril ore", "Coal", "Bronze bar", "Iron bar", "Silver bar", "Gold bar", "Steel bar", "Mithril bar" },
        recommended = { "About 10,000 coins (may vary on the tasks you get during the quest)", "Level 21 Agility (for the underwall tunnel shortcut to the Grand Exchange)", "Activated Port Sarim and Fremennik Province lodestone", "Luck of the Dwarves or Hazelmere's signet ring teleport to Keldagrim (accessible after initial city entry in quest introduction)" },
        sections = {
            {
                title = "Under arrest", needed = {},
                steps = {
                    {
                        text = "Enter the tunnel between the two black statues, north-east of Rellekka, close to fairy ring DKS. (teleport to the Fremennik Province and run north-east)",
                        npcs = { "Rellekka", "Fremennik Province" },
                    },
                    {
                        text = "Go through cave entrance east to Keldagrim.",
                        npcs = { "Keldagrim" },
                    },
                    {
                        text = "Talk to the Dwarven Boatman inside the cave, not Dwarven Ferryman.",
                        chat = "1 Yes.",
                        npcs = { "Dwarven Boatman", "Dwarven Ferryman" },
                    },
                    {
                        text = "Go west to the Black Guard H.Q.. Enter the building and talk to Commander Veldaban. The chat instance should end with you accepting the quest.",
                        chat = "Accept",
                        npcs = { "Commander Veldaban" },
                    },
                    {
                        text = "Exit the house, go north-east across the bridge and talk to Blasidar the Sculptor just north-west of the brewery.",
                        chat = "2 Yes, I will do this.",
                        npcs = { "Blasidar the Sculptor" },
                    },
                },
            },
            {
                title = "King's clothes", needed = { "200 coins, 1 coal, 1 logs" },
                steps = {
                    {
                        text = "In the large building just west, talk to Vermundi at the silk icon.",
                        chat = "2 Yes, I'm looking for some special clothes.",
                        npcs = { "Vermundi" },
                        tile = { x = 71, y = 141, plane = 0 },
                    },
                    {
                        text = "In the building west of the northern bridge, talk to the Librarian.",
                        chat = "2 Do you know anything about King Alvis's clothes?",
                        npcs = {},
                        tile = { x = 42, y = 177, plane = 0 },
                    },
                    {
                        text = "While weighing less than 30kg, attempt to climb any bookcase (there's a bank south-west of the library if you're over the limit).",
                        npcs = {},
                    },
                    {
                        text = "With the book, return to Vermundi.",
                        chat = "2 Yes, about those special clothes again...",
                        npcs = {},
                    },
                    {
                        text = "Use coal and logs on her spinning machine.",
                        npcs = {},
                    },
                    {
                        text = "Try to light it until the engine starts. (This may take several attempts)",
                        npcs = {},
                    },
                    {
                        text = "Talk to Vermundi.",
                        chat = "2 Yes, about those special clothes again... / 1 I'll pay.",
                        npcs = {},
                    },
                },
            },
            {
                title = "King's boots", needed = { "Runes to cast Telekinetic Grab (1 air rune and 1 law rune)" },
                steps = {
                    {
                        text = "In the far west of the city, talk to Saro at the anvil icon.",
                        chat = "2 Yes, I'm looking for a pair of special boots.",
                        npcs = { "Saro" },
                        tile = { x = 11, y = 151, plane = 0 },
                    },
                    {
                        text = "North of the bank, talk to Dromund.",
                        npcs = { "Dromund" },
                    },
                    {
                        text = "Take the left boot, from the table near the door, while his back is turned.",
                        npcs = { "left boot" },
                    },
                    {
                        text = "Leave his house and run around to the north edge, stand next to the western window (adjacent to the right boot).",
                        npcs = { "right boot" },
                    },
                    {
                        text = "When his back is turned, cast Telekinetic Grab on the right boot through the window.",
                        npcs = { "Telekinetic Grab" },
                    },
                },
            },
            {
                title = "King's axe", needed = { "3 sapphires, 1 redberry pie (if you have not completed The Knight's Sword), 1 iron bar" },
                steps = {
                    {
                        text = "Go to the north-west corner and talk to Santiri.",
                        chat = "2 Yes, I'm looking for a particular battleaxe. / 2 Blasidar the sculptor needs it for his statue. / 2 Perhaps I can repair the axe?",
                        npcs = { "Santiri" },
                        tile = { x = 12, y = 181, plane = 0 },
                    },
                    {
                        text = "Use 3 sapphires on the battleaxe.",
                        npcs = {},
                    },
                    {
                        text = "If you have not completed The Knight's Sword:",
                        npcs = { "The Knight's Sword" },
                        subs = {
                            { text = "Take a redberry pie with you when you talk to Thurgo." },
                        },
                    },
                    {
                        text = "Talk to Thurgo in his small hut (fairy ring AIQ), south of Port Sarim, and north of Mudskipper Point.",
                        chat = "2 Something else. (3 if skillcape is owned) / 2 Would you like some redberry pie? / 3 Can you help me with this ancient axe? / 1 Return to Keldagrim immediately.",
                        npcs = { "Thurgo" },
                        tile = { x = 3001, y = 3144, plane = 0 },
                        subs = {
                            { text = "If The Knight's Sword is complete", chat = "2 Something else. (3 if skillcape is owned) / 2 Can you help me with this ancient axe? / 1 Return to Keldagrim immediately." },
                            { text = "Have an iron bar to give to Thurgo (or access your metal bank via the anvil next to Thurgo to obtain one which is stored in it)." },
                        },
                    },
                    {
                        text = "With the 4 items, talk to Riki the sculptor's model near Blasidar the sculptor.",
                        npcs = { "Riki the sculptor's model" },
                    },
                    {
                        text = "Talk to Blasidar for a cutscene.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Climbing the corporate ladder", needed = {},
                steps = {
                    {
                        text = "Run west to the marketplace building and up the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Talk to any secretary (yellow is closest to metal bank) - your character's gender may disqualify your eligibility to work for that colour of company, consequently try another colour.",
                        chat = "3 Is there anything I can help you with? / Any",
                        npcs = {},
                    },
                    {
                        text = "Fetch them the required ore (must be un-noted). Repeat with the same secretary for a total of 4 tasks.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the director.",
                        chat = "3 Do you have any more tasks for me? / Any",
                        npcs = {},
                    },
                    {
                        text = "Fetch them the required bars. You might need to repeat for a second task.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the director.",
                        chat = "2 I'd like to officially join your company. / 3 Blasidar the sculptor has sent me. / 1 I would support you. / 1 Yes! Long live the [company]!",
                        npcs = {},
                    },
                    {
                        text = "Return to Commander Veldaban in Black Guard headquarters, where you started the quest (west of the palace and west of the bank).",
                        chat = "1 I'm ready. / 2 I do NOT want to attend, I don't have time to waste. / 2 I just have a lot of smithing to do today, I can't attend.",
                        npcs = { "Commander Veldaban" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "the_golem", name = "The Golem", wiki = "The Golem/Quick guide",
        required = { "An empty vial", "4 soft clay", "A papyrus", "A phoenix feather from the Desert Phoenix (obtained during quest)", "A black mushroom (obtained during quest)" },
        recommended = { "Multiple waterskins (or an enchanted water tiara to save backpack space)", "Desert robes to reduce the usage of waterskins", "A charged amulet of glory or an enchanted broomstick for quick teleportation to Shantay Pass", "Dominion medallion for quick trips to Uzer and the Desert Phoenix", "A Dig Site pendant or Archaeology journal for faster access to the Varrock Dig Site", "Traveller's necklace for teleport to just south of eagles' eyrie, which is just north west of Uzer" },
        sections = {
            {
                title = "Incomplete Mission", needed = {},
                steps = {
                    {
                        text = "Head east of the Shantay Pass to Uzer (north-east of the fairy ring DLQ).",
                        npcs = { "Shantay Pass", "Uzer" },
                        subs = {
                            { text = "If running from the Shantay Pass, pick up the phoenix feather on the way." },
                        },
                    },
                    {
                        text = "Talk to the broken clay golem.",
                        chat = "Accept",
                        npcs = { "broken clay golem" },
                    },
                    {
                        text = "With four soft clay in your backpack, use one on the golem. All four will be used to repair the golem.",
                        npcs = { "soft clay" },
                    },
                    {
                        text = "Talk to the golem.",
                        chat = "1 How do I open the portal?",
                        npcs = {},
                    },
                    {
                        text = "Pick up and read the letter west of the clay golem.",
                        npcs = { "letter (The Golem)", "clay golem" },
                    },
                    {
                        text = "Pick a black mushroom, found on the south-east corner of the stairs leading into the ruins.",
                        npcs = { "black mushroom" },
                    },
                    {
                        text = "Climb down the stairs in the ruins east of the golem.",
                        npcs = {},
                    },
                    {
                        text = "Head to the north-western room and pick up the strange implement.",
                        npcs = { "strange implement" },
                    },
                },
            },
            {
                title = "Statuette", needed = {},
                steps = {
                    {
                        text = "Head to Varrock Dig Site by either:",
                        npcs = { "Varrock Dig Site" },
                        subs = {
                            { text = "Teleport to the Varrock Dig Site using the Archaeology journal." },
                            { text = "Teleport to Varrock lodestone and run east." },
                            { text = "Teleport to Fort Forinthry and run south." },
                            { text = "Alternatively, you can use the dig Site pendant's Senntisten Temple teleport option." },
                        },
                    },
                    {
                        text = "Use the letter on Elissa and talk to Elissa who is east of the winch in the north-east corner of the Varrock Dig Site (just north of The Stormbreaker ship).",
                        chat = "3 I found a letter in the desert with your name on.",
                        npcs = { "Elissa", "The Stormbreaker" },
                        tile = { x = 3380, y = 3442, plane = 0 },
                    },
                    {
                        text = "Head to the Exam Centre just south of the Dig Site.",
                        npcs = { "Exam Centre" },
                    },
                    {
                        text = "Search the bookshelf on the southern wall and read Varmen's notes.",
                        npcs = { "Varmen's notes" },
                    },
                    {
                        text = "Talk to Curator Haig Halen in the Varrock Museum about the statuette. (If The chat options are not coming up make sure you repaired the golem and have read Varmen's notes)",
                        chat = "3 I'm looking for a statuette recovered from the city of Uzer. / 1 I want to open a portal to the lair of an elder-demon.",
                        npcs = { "Curator Haig Halen", "Varrock Museum", "Statuette (The Golem)" },
                    },
                    {
                        text = "Pickpocket him for the display cabinet key.",
                        npcs = { "display cabinet key" },
                    },
                    {
                        text = "Head upstairs and use the display cabinet key on the northwestern most case to get the statuette.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The portal", needed = {},
                steps = {
                    {
                        text = "Return to Shantay Pass and cross into the desert.",
                        npcs = {},
                    },
                    {
                        text = "Go east to the Desert Phoenix, and grab a phoenix feather.",
                        npcs = { "Desert Phoenix", "phoenix feather" },
                        tile = { x = 3347, y = 3114, plane = 0 },
                        subs = {
                            { text = "Make sure you un-equip any item porters, as wearing an activated Porter or grace of the elves will teleport the feather to your bank." },
                            { text = "Make sure you un-equip the Thieving Cape or Thieving master cape, as they will cause the feather to be noted." },
                        },
                    },
                    {
                        text = "Go to the ruins of Uzer where you started the quest and go back down the stairs.",
                        npcs = {},
                    },
                    {
                        text = "In the centre of the room will be four alcoves. Place the statuette in the empty one.",
                        npcs = {},
                    },
                    {
                        text = "Turn the statuettes so they all point north towards the double doors. You may have to click \"turn\" more than once.",
                        npcs = {},
                    },
                    {
                        text = "Go north, through the double doors.",
                        npcs = {},
                        subs = {
                            { text = "Optional: Take the gems from the throne at the north side of the room to unlock the achievement Looting the Demon Throne and obtain two cut rubies, two cut emeralds, and two cut sapphires." },
                        },
                    },
                    {
                        text = "Go back through the south portal.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The golem", needed = {},
                steps = {
                    {
                        text = "Go back upstairs and talk to the golem.",
                        npcs = {},
                    },
                    {
                        text = "With an empty vial in your backpack, right click Grind the black mushroom (Don't left click \"Eat\" it).",
                        npcs = { "vial" },
                    },
                    {
                        text = "Use the phoenix feather on the black mushroom ink.",
                        npcs = { "black mushroom ink" },
                    },
                    {
                        text = "Use the phoenix quill pen on a piece of papyrus to get the golem program.",
                        npcs = { "phoenix quill pen", "papyrus", "golem program" },
                    },
                    {
                        text = "Use the Strange implement on the golem then quickly use the newly acquired golem program on the golem.",
                        npcs = { "Strange implement" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "The Golem",
                        npcs = { "The Golem (achievement)" },
                    },
                    {
                        text = "Looting the Demon Throne",
                        npcs = { "Looting the Demon Throne" },
                    },
                },
            },
        },
    },
    {
        key = "the_grand_tree", name = "The Grand Tree", wiki = "The Grand Tree/Quick guide",
        required = {},
        recommended = { "Completion of the Tree Gnome Village quest", "Active Eagles' Peak lodestone", "Grand seed pod, access to Spirit tree or Balloon transport system for quick transportation to Tree Gnome Stronghold", "Armour, weapon, food and/or prayer potions", "At least six free inventory slots", "Ring of duelling or amulet of glory" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Speak to King Narnode Shareen on the 1st floor of the Grand Tree.",
                        chat = "1 You seem worried, what's up? / Accept",
                        npcs = { "King Narnode Shareen", "Grand Tree" },
                    },
                },
            },
            {
                title = "The crisis", needed = {},
                steps = {
                    {
                        text = "Take the bark sample and book to Hazelmere; he lives east of Yanille.",
                        npcs = { "Hazelmere", "Yanille" },
                        tile = { x = 2678, y = 3087, plane = 1 },
                        subs = {
                            { text = "If you have A Fairy Tale II - Cure a Queen completed, you can use code CLS, otherwise teleport to the Yanille lodestone." },
                        },
                    },
                    {
                        text = "Up the ladder, talk to Hazelmere.",
                        npcs = {},
                    },
                    {
                        text = "Take Hazelmere's scroll back to the King.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the King.",
                        chat = "1 I think so! / 5 None of the above. / 5 None of the above. / 2 A man came to me with the King's seal. / 1 I gave the man Daconia rocks. / 4 And Daconia rocks will kill the tree!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Glough", needed = {},
                steps = {
                    {
                        text = "Climb up the ladder of the tree house south-east of the Grand Tree, north of the Agility course.",
                        npcs = { "Gnome Stronghold Agility Course" },
                    },
                    {
                        text = "Speak to Glough.",
                        npcs = { "Glough" },
                    },
                    {
                        text = "Speak to the King.",
                        npcs = {},
                    },
                    {
                        text = "Climb to the top floor of the Grand Tree.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Charlie the prisoner.",
                        npcs = { "Charlie (prisoner)" },
                    },
                    {
                        text = "Return to Glough's tree house.",
                        npcs = {},
                    },
                    {
                        text = "Search the cupboard north of the ladder to get Glough's journal.",
                        npcs = { "Glough's journal" },
                    },
                    {
                        text = "Speak to Glough.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Charlie and leave your prison cell.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Captain Errdo just north of the cells to get to Karamja.",
                        chat = "1 Take me to Karamja, please.",
                        npcs = { "Captain Errdo", "Karamja" },
                        subs = {
                            { text = "Beware if you are low level, there are multiple level 57 Jogres here so be ready." },
                        },
                    },
                    {
                        text = "Run east and attempt to open the gate.",
                        npcs = {},
                    },
                    {
                        text = "Tell him you work for Glough, Ka-Lu-Min is the password.",
                        chat = "2 Glough sent me. / 1 Ka. / 2 Lu. / 2 Min.",
                        npcs = {},
                    },
                    {
                        text = "Once inside, run east to the south dock.",
                        npcs = {},
                    },
                    {
                        text = "Either kill the foreman, or talk to him and answer his questions.",
                        chat = "3 Sadly his wife is no longer with us! / 2 He loves worm holes. / 1 Anita.",
                        npcs = {},
                    },
                    {
                        text = "Take the Lumber order.",
                        npcs = { "Lumber order" },
                    },
                    {
                        text = "Talk to Femi at the Gnome Stronghold gates to enter inside.",
                        npcs = { "Femi", "Gnome Stronghold" },
                        subs = {
                            { text = "You may offer help to get inside for free, or 1,000 coins if you do not." },
                            { text = "Alternatively teleport to the spirit tree if Tree Gnome Village quest is complete." },
                        },
                    },
                    {
                        text = "Talk to the King.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Charlie the prisoner.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Anita. She can be found in the northwesternmost tree house in the stronghold.",
                        npcs = { "Anita" },
                    },
                    {
                        text = "Use the key on the chest in Glough's house and search it to receive the invasion plans.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the king. Make sure you have 4 free inventory spaces before you do this step, as he will give you 4 twigs.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The fight", needed = {},
                steps = {
                    {
                        text = "Prepare to fight a level 98 black demon. Magic works well here, as the demon has a weakness to water spells. There is a safespot along the south wall, behind some rocks where Glough is standing. Using a halberd will allow lower levels to effectively melee the demon using the safespot.",
                        npcs = { "Black demon (The Grand Tree)", "Magic", "water spells", "safespot", "halberd" },
                    },
                    {
                        text = "Go to the top level of Glough's house.",
                        npcs = {},
                    },
                    {
                        text = "Use the twigs on the pillars to spell TUZO.",
                        npcs = {},
                    },
                    {
                        text = "Open the trapdoor.",
                        npcs = {},
                    },
                    {
                        text = "Kill the demon. (Can be safespotted by standing within the rocks to the south)",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Run to the middle of the cave and talk to the king. Don't click away yet, wait for the scripted dialogue to finish.",
                        npcs = {},
                        subs = {
                            { text = "The quest log should mention that you need to find a Daconia rock." },
                        },
                    },
                    {
                        text = "Search the nearby roots for a rock. If you don't find the rock try the other roots in the cave. Be sure to space-through or click through the text boxes, or else the Daconia rock may not appear in your inventory.",
                        npcs = { "Daconia rock" },
                    },
                    {
                        text = "Take the rock to the king.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "The Grand Tree",
                        npcs = { "The Grand Tree (achievement)" },
                    },
                    {
                        text = "Karamja achievements",
                        npcs = { "Karamja achievements" },
                        subs = {
                            { text = "Medium" },
                            { text = "Falling With Style" },
                            { text = "Shipping Out From the Shipyard" },
                        },
                    },
                },
            },
        },
    },
    {
        key = "the_great_brain_robbery", name = "The Great Brain Robbery", wiki = "The Great Brain Robbery/Quick guide",
        required = { "Fishbowl helmet and diving apparatus", "A holy symbol", "Ring of charos", "38+ nails of any kind over bronze (the nails have a chance to accidentally bend, so it is recommended to bring more)", "10 wooden cats", "Can be crafted with 10 bear fur and 10 planks (requires partial completion of quest, protean planks do not work)", "8 regular planks (cannot be used from within plank box)", "A hammer (tool belt does not work)", "A tinderbox (tool belt does not work, obtainable during quest)" },
        recommended = { "Access to a clockmaker's bench at a player-owned house (if not buying wooden cats from the Grand Exchange)", "An ectophial (only if not using fairy rings)", "4-6 ecto-tokens (if you haven't completed Ghosts Ahoy, not needed if using fairy rings)", "Activated Canifis and Edgeville lodestone", "Discovered the DIP fairy ring code (requires partial completion of A Fairy Tale III - Battle at Ork's Rift and fixing of the 2 bridges to use – see Fairy ring for more information)", "Not having any followers, or any summoning pouches or pets (this includes wooden cats) in the inventory", "A combat bracelet or wilderness sword 1 (to quick travel to the Edgeville Monastery)" },
        sections = {
            {
                title = "Disharmony", needed = { "4 regular planks, at least 10 nails, a holy symbol, fishbowl helmet, and diving apparatus" },
                steps = {
                    {
                        text = "Travel to Mos Le'Harmless (fairy ring DIP if you have repaired the bridge), walk a bit north off the dock and talk to Brother Tranquillity (if you arrived via the fairy ring, run into town and he is north of the docks).",
                        chat = "Accept",
                        npcs = { "Mos Le'Harmless", "fairy ring", "Brother Tranquillity" },
                    },
                    {
                        text = "Bank/dismiss any pets or familiars.",
                        npcs = {},
                    },
                    {
                        text = "Upon arrival on Harmony Island, go through the dialogue, or Brother Tranquillity will teleport you back to Mos Le'Harmless.",
                        npcs = { "Harmony Island" },
                    },
                    {
                        text = "Run outside and head slightly north to the statue. Pull the statue, then climb-down statue.",
                        npcs = {},
                    },
                    {
                        text = "Equip your diving gear and descend the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Run past the zombie pirates.",
                        npcs = {},
                    },
                    {
                        text = "Repair the stairs at the end of the tunnel, then climb them.",
                        npcs = {},
                        subs = {
                            { text = "If you happened to bring your planks in a plank box, be sure to remove them so you can repair the stairs." },
                        },
                    },
                    {
                        text = "Climb the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Peer-through the peephole on the wall.",
                        npcs = {},
                    },
                    {
                        text = "Make your way back to Brother Tranquillity on Harmony Island and speak with him.",
                        npcs = { "Harmony Island" },
                    },
                    {
                        text = "Travel to the Edgeville Monastery.",
                        npcs = { "Edgeville Monastery" },
                    },
                    {
                        text = "Search the southern bookcase on the 1st floor of the western wing to find a prayer book.",
                        npcs = { "prayer book" },
                    },
                    {
                        text = "Read the book.",
                        npcs = {},
                    },
                    {
                        text = "Head back to Brother Tranquillity who teleports you to Harmony Island.",
                        npcs = { "Harmony Island" },
                    },
                    {
                        text = "Wear your holy symbol and choose the option Recite-prayer on the prayer book.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Family doctor", needed = {},
                steps = {
                    {
                        text = "Talk to Brother Tranquillity.",
                        npcs = {},
                    },
                    {
                        text = "Travel to Fenkenstrain's Castle, which is directly north-east of the Canifis lodestone.",
                        npcs = { "Fenkenstrain's Castle", "Canifis lodestone" },
                    },
                    {
                        text = "Go up on the staircase in the north-western corner.",
                        npcs = {},
                    },
                    {
                        text = "Go up on the northern ladder behind the jail gate in the centre.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Dr Fenkenstrain.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Err... Meow?", needed = { "10 wooden cats (10 bear fur and 10 planks if making yourself), 28+ nails, 4 planks, ring of charos, and at least 2 backpack spaces" },
                steps = {
                    {
                        text = "Equip your ring of charos and talk to Rufus in the Canifis meat store.",
                        chat = "1 Talk about the meat shipment",
                        npcs = { "ring of charos", "Rufus" },
                        subs = {
                            { text = "Speak with Rufus again after the cutscene if you did not receive a wolf whistle and crate parts." },
                        },
                    },
                    {
                        text = "Start crafting on a clockmaker's bench in a player-owned house to make 10 wooden cats with 10 planks and 10 bear fur. You can also buy them off the Grand Exchange.",
                        npcs = { "Clockmaker's bench 1", "Grand Exchange" },
                    },
                    {
                        text = "Travel back to Dr Fenkenstrain with all of the required items.",
                        npcs = {},
                    },
                    {
                        text = "Build the crate on the hotspot, east of the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Add-bottom to the crate.",
                        npcs = {},
                    },
                    {
                        text = "Fill the crate with the wooden cats.",
                        npcs = {},
                    },
                    {
                        text = "Take off your fishbowl helmet and Blow the wolf whistle to call Rufus.",
                        npcs = {},
                    },
                    {
                        text = "Use the shipping order on the crate.",
                        npcs = { "shipping order" },
                    },
                },
            },
            {
                title = "Scrubs", needed = { "fishbowl helmet, diving apparatus, hammer (tool belt does not work), tinderbox (tool belt does not work, can be picked up on the pirate ship), combat gear, at least 6 backpack spaces" },
                steps = {
                    {
                        text = "Travel back to Mos Le'Harmless.",
                        npcs = {},
                        subs = {
                            { text = "You can buy a hammer and a tinderbox from the Trader Crewmember (located south-west on the dock)." },
                        },
                    },
                    {
                        text = "Speak with Brother Tranquillity to get back on Harmony Island. (Brother Tranquillity now also has a \"transport\" option available to players)",
                        chat = "1 Yes. please.",
                        npcs = { "Harmony Island" },
                    },
                    {
                        text = "Climb down the ladder and talk to Dr Fenkenstrain.",
                        npcs = {},
                        subs = {
                            { text = "If he is not there, exit to lobby and join the world again." },
                        },
                    },
                    {
                        text = "Return up the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Equip your diving suit and head north to the ship that has run aground.",
                        npcs = {},
                        subs = {
                            { text = "If you walk outside without diving suit, you will be teleported back." },
                            { text = "Equip your weapons in preparation for fighting enemies, otherwise you will have to return to the windmill to do so. Attempting to do so outside will give the message: \"You cannot wear that without the gas affecting you.\"" },
                        },
                    },
                    {
                        text = "Open and then search the locker on the west end of the 1st floor to get a fuse.",
                        npcs = { "Fuse (Gunpowder)" },
                    },
                    {
                        text = "Climb the ladder and take a keg of powder found next to a cannon.",
                        npcs = { "keg" },
                        subs = {
                            { text = "Grab the tinderbox from the front (east side) of the ship if you have not brought your own." },
                        },
                    },
                    {
                        text = "Go to the front door of the monastery (the main building on Harmony Island).",
                        npcs = {},
                    },
                    {
                        text = "Use the keg on the door.",
                        npcs = {},
                    },
                    {
                        text = "Use the fuse on the door.",
                        npcs = {},
                    },
                    {
                        text = "Use your tinderbox on the fuse.",
                        npcs = {},
                    },
                    {
                        text = "Pass the door to enter the monastery.",
                        npcs = {},
                    },
                    {
                        text = "Kill some sorebones until you get the following items (the items drop one at a time and the next item won't spawn until the current one is picked up):",
                        npcs = { "sorebones" },
                        subs = {
                            { text = "3 bell jars" },
                            { text = "A pair of brain tongs" },
                            { text = "A cranial clamp" },
                            { text = "30 skull staples" },
                        },
                    },
                    {
                        text = "Talk to Dr Fenkenstrain downstairs in the mill. Make sure to give him a hammer or you will be stuck.",
                        npcs = { "hammer" },
                    },
                    {
                        text = "After the cutscene, go upstairs and talk to Brother Tranquillity.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Barrelchest", needed = { "Combat equipment, fishbowl helmet, diving apparatus" },
                steps = {
                    {
                        text = "Pass the door of the monastery and confront Mi-Gor.",
                        npcs = { "Mi-Gor" },
                    },
                    {
                        text = "Kill Barrelchest.",
                        npcs = { "Barrelchest" },
                    },
                    {
                        text = "Take the Barrelchest anchor.",
                        npcs = { "Barrelchest anchor" },
                    },
                    {
                        text = "Return to Brother Tranquillity.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "the_hand_in_the_sand", name = "The Hand in the Sand", wiki = "The Hand in the Sand/Quick guide",
        required = { "A regular beer (or to buy one at the Dragon Inn in Yanille)", "A bucket of sand or bucket (can fill with sand during the quest)", "A lantern lens (the lens from an Emerald lantern won't work)", "Five earth runes", "An empty vial (bring two if you want to be teleported to Port Sarim to get the Truth serum).", "Redberries (1)", "White berries (1)" },
        recommended = { "It is also recommended not to bring anything that cannot be taken onto Entrana", "About for boat trips (or less with an activated Ring of charos)", "Activated Karamja, Port Sarim and Yanille lodestone", "House Teleport spell runes or teletabs to reach Brimhaven or Yanille", "Law altar teleport tablet" },
        sections = {
            {
                title = "A helping hand", needed = {},
                steps = {
                    {
                        text = "Talk to Bert in the building near Yanille's house portal.",
                        chat = "2 Eww a hand, in the sand! Why haven't you told the authorities? / Accept",
                        npcs = { "Bert" },
                        subs = {
                            { text = "If you need a bucket of sand, there is a sand pit directly north of the house portal that you may fill your bucket at for later in the quest." },
                        },
                    },
                    {
                        text = "Give the Guard Captain in the nearby pub a beer.",
                        npcs = { "Guard Captain" },
                    },
                    {
                        text = "Go east to the Wizards' Guild and ring the bell on the eastern side of the building.",
                        chat = "2 I have a rather sandy problem that I'd like to palm off on you.",
                        npcs = {},
                        subs = {
                            { text = "If you have at least 66 Magic, you can enter the guild and go upstairs to find Zavistic Rarve, rather than calling him to the front door." },
                        },
                    },
                    {
                        text = "Return to Bert and speak to him to receive Bert's rota.",
                        npcs = { "Bert's rota" },
                    },
                    {
                        text = "Go to Brimhaven and find Sandy in a small house directly south of the The Shrimp and Parrot.",
                        npcs = { "Brimhaven", "The Shrimp and Parrot" },
                    },
                    {
                        text = "Search his desk to receive Sandy's rota.",
                        npcs = { "Sandy's rota" },
                    },
                    {
                        text = "Pickpocket Sandy for some sand (may take several attempts, bucket of sand does not count).",
                        npcs = { "sand" },
                    },
                    {
                        text = "Return to Bert and talk to him.",
                        npcs = {},
                    },
                    {
                        text = "Ring the Wizards' Guild bell and talk to Zavistic Rarve again to receive a magical orb.",
                        chat = "2 I have a rather sandy problem that I'd like to palm off on you.",
                        npcs = { "magical orb" },
                        subs = {
                            { text = "If you have a second empty vial you can teleport to Port Sarim's magic shop by talking to Zavistic Rarve again and give him an empty vial.", chat = "2 I have a rather sandy problem that I'd like to palm off on you. / 4 Can you help me more?. / 1 Okay" },
                        },
                    },
                },
            },
            {
                title = "Truth serum", needed = { "an empty vial, redberries, white berries, lantern lens, magical orb, sand" },
                steps = {
                    {
                        text = "In Port Sarim's magic shop, talk to Betty.",
                        chat = "1 Talk to Betty about The Hand in the Sand.",
                        npcs = { "Port Sarim", "Betty's Magic Emporium" },
                    },
                    {
                        text = "Use your redberries on the bottled water Betty gave you, then the white berries.",
                        npcs = { "bottled water" },
                    },
                    {
                        text = "Use the pink dye on your lantern lens.",
                        npcs = { "pink dye", "lantern lens" },
                    },
                    {
                        text = "Talk to Betty again.",
                        chat = "1 Talk to Betty about The Hand in the Sand.",
                        npcs = {},
                    },
                    {
                        text = "Open the door to her shop and stand in the doorway, then use your rose-tinted lens on the counter. Successfully doing so grants you a truth serum potion.",
                        npcs = { "rose-tinted lens", "truth serum" },
                    },
                    {
                        text = "Talk to Betty a third time.",
                        chat = "1 Talk to Betty about The Hand in the Sand.",
                        npcs = {},
                    },
                    {
                        text = "Make your way back to Brimhaven.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Sandy to distract him. Try all three options until Sandy is distracted, this is random for each player. If this still doesn't work, lobby then log in again.",
                        chat = "Any",
                        npcs = {},
                    },
                    {
                        text = "Use the truth serum on the coffee mug on the table.",
                        npcs = {},
                    },
                    {
                        text = "Activate the magical orb in your backpack.",
                        npcs = { "magical orb" },
                    },
                    {
                        text = "Talk to Sandy again.",
                        chat = "1 Why is Bert's rota different from the original? / 1 Why doesn't Bert remember the change in his hours? / 1 What happened to the wizard?",
                        npcs = {},
                    },
                },
            },
            {
                title = "Retrieving the head", needed = { "5 earth runes, bucket of sand" },
                steps = {
                    {
                        text = "Head back to the Wizards Guild in Yanille and ring the bell once more.",
                        chat = "2 I have a rather sandy problem that I'd like to palm off on you.",
                        npcs = {},
                    },
                    {
                        text = "With your five earth runes and bucket of sand, ring the bell again for a cutscene.",
                        chat = "2 I have a rather sandy problem that I'd like to palm off on you.",
                        npcs = {},
                    },
                    {
                        text = "Go to the sand pit in south-west Entrana.",
                        npcs = { "Entrana" },
                    },
                    {
                        text = "Talk to Mazion to receive the wizard's head.",
                        npcs = { "Mazion", "wizard's head" },
                    },
                    {
                        text = "Return to Yanille and ring the bell at Wizards Guild a final time.",
                        chat = "2 I have a rather sandy problem that I'd like to palm off on you.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "The Hand in the Sand",
                        npcs = { "The Hand in the Sand (achievement)" },
                    },
                    {
                        text = "Falador achievements",
                        npcs = { "Falador achievements" },
                        subs = {
                            { text = "Hard - It Matches My Eyes" },
                        },
                    },
                    {
                        text = "Ardougne achievements",
                        npcs = { "Ardougne achievements" },
                        subs = {
                            { text = "Medium - By the Bucketload" },
                        },
                    },
                },
            },
        },
    },
    {
        key = "the_hunt_for_surok_miniquest", name = "The Hunt for Surok (miniquest)", wiki = "The Hunt for Surok (miniquest)/Quick guide",
        required = {},
        recommended = { "Combat equipment to fight a strong level 107 ork who is resistant to range attacks and survive taking multiple hits from different types of monsters.", "An Anti-dragon shield or antifire potion, super energy potions, and antipoisons are useful in the tunnels.", "A one-click teleport such as the ectophial or magic tablets.", "One of the following:", "A way to restore run energy, such as mint cakes or an Explorer's ring.", "The salt-water spring in Oo'glog if you've completed As a First Resort.", "The salt-water treatment at the spa pool if you have a tier 1 or higher Spa.", "A stamina potion if you have level 77 Herblore.", "Have the Endurance relic power activated at the mysterious monolith." },
        sections = {
            {
                title = "Tunnel chase", needed = {},
                steps = {
                    {
                        text = "Talk to Surok Magis outside the Tunnel of Chaos, at the Saradomin statue south of Jolly Boar Inn, south of Fort Forinthry. If he's not there, click dig on the statue, then enter and leave.",
                        npcs = { "Surok Magis", "Tunnel of Chaos", "Statue (Saradomin)", "Jolly Boar Inn", "Fort Forinthry" },
                    },
                    {
                        text = "After the cutscene, follow him into the tunnel.",
                        npcs = {},
                    },
                    {
                        text = "Follow him into the portal in the western room (where Dakh'thoulan Aegis is).",
                        npcs = { "Dakh'thoulan Aegis" },
                    },
                    {
                        text = "Follow Surok through the Chaos Tunnels portals in the route in the above map.",
                        npcs = {},
                        subs = {
                            { text = "Be aware that there are aggressive monsters, dragons, and prayer-draining monsters on the way. It is recommended to bring food and combat equipment." },
                            { text = "You may be randomly teleported by a portal - if so, locate yourself on the map and make your way back to the route." },
                        },
                    },
                    {
                        text = "You need to see three cutscenes along the route.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Boss battle", needed = {},
                steps = {
                    {
                        text = "Enter the final portal in the dagannoth room.",
                        npcs = {},
                    },
                    {
                        text = "Defeat Bork.",
                        npcs = { "Bork" },
                    },
                },
            },
        },
    },
    {
        key = "the_jack_of_spades", name = "The Jack of Spades", wiki = "The Jack of Spades/Quick guide",
        required = {},
        recommended = {},
        sections = {
            {
                title = "New trade deal", needed = {},
                steps = {
                    {
                        text = "Talk to Emir Ali Mirza in Al Kharid palace to begin the quest.",
                        chat = "1 Talk about Jack of Spades. / Accept / 1 Yes.",
                        npcs = { "Emir Ali Mirza", "Al Kharid palace" },
                    },
                    {
                        text = "Go upstairs. Talk to Osman.",
                        chat = "5 No more questions.",
                        npcs = { "Osman" },
                    },
                    {
                        text = "From the same floor, climb the central north or northwest staircase to the roof and talk to Grand Vizier Hassan. The steps are built into the wall and may be difficult to notice at a glance. Look south west of the fountain.",
                        chat = "1 I know all I need - let's go!",
                        npcs = { "Grand Vizier Hassan" },
                    },
                    {
                        text = "Dismiss any follower and unequip the item in your main and off-hand slots. Talk to Grand Vizier Hassan.",
                        chat = "1 Yes, let's go!",
                        npcs = { "Grand Vizier Hassan" },
                    },
                    {
                        text = "Talk to Hassan while on the carpet to teleport to Menaphos.",
                        npcs = { "Menaphos" },
                    },
                    {
                        text = "Follow Hassan into the city.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The streets of Menaphos", needed = {},
                steps = {
                    {
                        text = "Talk to Hassan. Make sure you finish all dialogue. There are (brief) pauses between dialogue after talking to each person below.",
                        chat = "1 Talk about Jack of Spades.",
                        npcs = {},
                    },
                    {
                        text = "Head north east to the shifting tombs entrance in the centre of the market square.",
                        npcs = { "Shifting tombs (scenery)" },
                    },
                    {
                        text = "Choose the Travel Ports District option on the tombs to go to the Port district.",
                        npcs = { "Menaphos Port district" },
                    },
                    {
                        text = "Talk to 'Admiral' Wadud (Ports) in The Golden Scarab Inn just north.",
                        npcs = { "'Admiral' Wadud (Ports)", "The Golden Scarab Inn" },
                    },
                    {
                        text = "Choose the Travel Imperial District option on the tombs to the Imperial district. (This is a good time to activate the Menaphos Lodestone just East of you.)",
                        npcs = { "Menaphos Imperial district" },
                    },
                    {
                        text = "Speak to Commander Akhomet (Imperial) in front of the entrance to the Great Pyramid just west. Make sure you finish the dialogue, as there is a pause as the Jack of Spades appears.",
                        npcs = { "Commander Akhomet (Imperial)" },
                    },
                    {
                        text = "Choose the Travel Worker District option on the tombs to the Worker district.",
                        npcs = { "Menaphos Worker district" },
                    },
                    {
                        text = "Talk to Batal (Worker) next to the fire pit. Make sure you finish the dialogue, as there is a pause as the Jack of Spades appears.",
                        npcs = { "Batal (Worker)" },
                    },
                },
            },
            {
                title = "Shifty", needed = {},
                steps = {
                    {
                        text = "Enter the shifting tombs to go inside.",
                        npcs = {},
                    },
                    {
                        text = "Ensure you have 4 backpack spaces.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Jack of Spades.",
                        chat = "3 Why steal from people? / 4 I've heard enough.",
                        npcs = { "Ozan" },
                    },
                    {
                        text = "Exit the shifting tombs to any district.",
                        npcs = {},
                    },
                    {
                        text = "Referencing above locations, return the four stolen items to their respective districts. It is recommended to do the Merchant district last as Hassan is there.",
                        npcs = {},
                    },
                    {
                        text = "Return to Hassan in the Merchant district.",
                        chat = "1 Talk about Jack of Spades.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                    {
                        text = "Before leaving the city, feel free to activate the Menaphos lodestone if you didn't do it in the previous steps.",
                        npcs = { "Menaphos lodestone" },
                    },
                },
            },
        },
    },
    {
        key = "the_knight_s_sword", name = "The Knight's Sword", wiki = "The Knight's Sword/Quick guide",
        required = { "Redberry pie", "2 Iron bars", "Blurite ore (obtainable during quest)" },
        recommended = { "Activated Falador, Port Sarim, and Varrock lodestones", "20 Mining and a steel pickaxe or better" },
        sections = {
            {
                title = "Getting started", needed = { "Redberry pie" },
                steps = {
                    {
                        text = "Talk to Squire Asrol in the White Knights' Castle courtyard in Falador.",
                        chat = "1 Chat / 1 And how is life as a squire? / 2 I can make a new sword if you like... / 1 So would these dwarves make another one? / Accept",
                        npcs = { "Squire Asrol", "White Knights' Castle", "Falador" },
                    },
                    {
                        text = "Talk to Reldo in Varrock Palace library about the Imcando dwarf tribe.",
                        chat = "3 What do you know about the Imcando dwarves?",
                        npcs = { "Reldo", "Varrock Palace" },
                        subs = {
                            { text = "If The Giant Dwarf quest is complete, skip this step." },
                            { text = "If wielding ring of charos remove that, otherwise option does not appear." },
                        },
                    },
                    {
                        text = "Talk to Thurgo south of Port Sarim (north of fairy ring AIQ) with a Redberry pie in the inventory.",
                        chat = "2 Something else. / 2 Would you like some redberry pie?",
                        npcs = { "Thurgo", "Port Sarim", "Redberry pie" },
                        tile = { x = 3001, y = 3144, plane = 0 },
                        subs = {
                            { text = "If Smithing cape is obtained", chat = "3 Something else. / 2 Would you like some redberry pie?" },
                        },
                    },
                    {
                        text = "Talk to him again.",
                        chat = "2 Something else.",
                        npcs = {},
                        subs = {
                            { text = "If Smithing cape is obtained", chat = "3 Something else." },
                        },
                    },
                },
            },
            {
                title = "The portrait", needed = {},
                steps = {
                    {
                        text = "Talk to Squire Asrol.",
                        chat = "1 Chat",
                        npcs = { "Squire Asrol" },
                    },
                    {
                        text = "Climb the ladder to the east, then the first staircase to the west.",
                        npcs = {},
                    },
                    {
                        text = "Enter Sir Vyvin's room directly south.",
                        npcs = { "Sir Vyvin" },
                    },
                    {
                        text = "Look for a cupboard and open it then search it.",
                        npcs = {},
                        subs = {
                            { text = "If Sir Vyvin keeps noticing, four methods can be used to distract him." },
                            { text = "Have a friend talk to Sir Vyvin while you open and search the cupboard." },
                            { text = "Open the door to his room and wait for him to walk out. However, this will take a very long time, so keep hopping worlds until you arrive at one where he's already outside, or alternatively just shut the door when he leaves and then search the cupboard." },
                            { text = "Wait until he is behind the door, then quickly search the cupboard." },
                            { text = "Wait until Sir Vyvin looks at a wall, then quickly search the cupboard." },
                        },
                    },
                },
            },
            {
                title = "The sword", needed = {},
                steps = {
                    {
                        text = "Give Thurgo the portrait.",
                        chat = "2 Something else.",
                        npcs = {},
                        subs = {
                            { text = "If Skillcape in Smithing is obtained", chat = "3 Something else." },
                        },
                    },
                    {
