    {
        key = "the_path_of_glouphrie", name = "The Path of Glouphrie", wiki = "The Path of Glouphrie/Quick guide",
        required = { "Small crystal seed or crystal saw (tools made from crystal tool seeds will not work)", "A crossbow and mithril grapple (tool belt works)", "A key (from the Waterfall Quest; can be re-obtained during the quest)" },
        recommended = { "Good food and armour", "Super energy potions, unlimited run from the Oo'glog salt-water pool, or an explorer's ring for run recharge", "Prayer or super restore potions", "A cooked tangled toad legs (optional for a mint cake reward; does not have to be cooked during the quest)", "Earmuffs, masked earmuffs, or a slayer helmet to reduce the strength of the terrorbirds' ranged attacks", "Any remaining crystalline discs from The Eyes of Glouphrie" },
        sections = {
            {
                title = "Evil dumplings", needed = { "Crystal saw or small crystal seed, drop or bring all crystalline discs if you have some of them" },
                steps = {
