                        subs = {
                            { text = "People with sensitivity to light, seizures, or other ailments concerning flashing lights should be cautious during the escape scene (about 3–4 minutes). Recommended to hold spacebar and look away. You must watch the cutscene. In the event you cancel it, simply re-enter the room." },
                        },
                    },
                    {
                        text = "Speak to Hazelmere.",
                        npcs = { "Hazelmere" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "The Path of Glouphrie",
                        npcs = { "The Path of Glouphrie (achievement)" },
