                    {
                        text = "Culinary Exchange",
                        npcs = { "Culinary Exchange" },
                    },
                    {
                        text = "Tirannwn achievements",
                        npcs = { "Tirannwn achievements" },
                        subs = {
                            { text = "Easy - Sick and Twisted" },
                        },
                    },
                },
            },
        },
