    {
        key = "the_prisoner_of_glouphrie", name = "The Prisoner of Glouphrie", wiki = "The Prisoner of Glouphrie/Quick guide",
        required = {},
        recommended = { "Runes for Ourania teleport (optional, if you have Level 71 Magic and are using Lunar spells, 1 law rune, 2 astral runes, 6 earth runes or Ardougne easy tasks for Kandarin monastery Teleport)", "A ring of duelling or an activated Yanille lodestone for quick access to the observatory", "Rope", "Chipped Watchtower teleport" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Speak to Golrie in the Gnome Village Dungeon. (Note: If you run into a bug where you can't click the X to close the letter without it moving your character, right-click on the X and click \"Close\" or press \"Esc\" on your keyboard to close the note.)",
                        chat = "2 [Look at the letter] / Accept / 4 What should we do next?",
                        npcs = { "Golrie", "Gnome Village Dungeon" },
                    },
                    {
                        text = "After asking what is next, you will be transported to the surface for a conversation with Golrana.",
                        npcs = { "Golrana" },
                    },
                    {
                        text = "Talk with Golrana inside the Gnome Village.",
                        npcs = { "Golrana", "Gnome Village" },
                    },
                    {
                        text = "Teleport to Castle Wars (or follow Elkoy out of the maze) and head to the highlighted area north of the Observatory and south of the Ourania altar (just north-east of the crystal tree). Make sure to pass the Observatory on its eastern side, alternatively use a 'Chipped' Watchtower teleport to teleport directly there.",
                        npcs = { "Castle Wars", "Observatory", "'Chipped' Watchtower teleport" },
                    },
                    {
                        text = "Make sure to dismiss your pet/follower. Talk to Golrana.",
                        npcs = { "Golrana" },
                    },
                    {
                        text = "Walk up the path north-west until you reach a large dead tree. Search it, then climb-through it.",
                        npcs = {},
                    },
                    {
                        text = "Investigate the ledge on the south end of the chasm (the wall near the rocks at the south of the room), continue the conversation with Golrana, she then will cross the chasm and throw a rope for you to cross.",
                        npcs = {},
                        subs = {
                            { text = "If you encounter a bug in which Golrana disappears, simply re-log and continue from two steps prior." },
                        },
                    },
                    {
                        text = "Move south and continue through the cave by jumping across gaps.",
                        npcs = {},
                    },
                    {
                        text = "Travel north-west until reaching a water stream with stepping stones, but do not cross yet.",
                        npcs = {},
                    },
                    {
                        text = "Before crossing the set of stepping stones, investigate the small crevice in the south wall to your immediate east.",
                        npcs = {},
                    },
                    {
                        text = "Golrana will enter the crevice and emerge on the other side, she then will move a stone for you to complete the jumping part.",
                        npcs = {},
                    },
                    {
                        text = "Cross the stepping stones, head southwest until you reach a crevice, then climb-through and out of the cave.",
                        npcs = {},
                    },
                    {
                        text = "Go west to the ledge overlooking Lletya and investigate the sturdy tree, then climb-down it.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Bolrie's Lab", needed = {},
                steps = {
                    {
                        text = "After a cutscene, take the handwritten book on the crate next to you and read it.",
                        npcs = { "A handwritten book (The Prisoner of Glouphrie)" },
                    },
                    {
                        text = "Search all crates, lamps, shelves and the picture in the room. You will be notified when you have gathered everything in the room.",
                        npcs = {},
                    },
                    {
                        text = "Build the crate at the desk north of the ladder, then calibrate it.",
                        npcs = {},
                    },
                    {
                        text = "Note down the number and colour value for all three.",
                        npcs = {},
                    },
                    {
                        text = "Use the calculator below to get a working pair of shapes for each of the three value pairs. Note down the pair of shapes for each.",
                        npcs = {},
                        subs = {
                            { text = "Please wait for the form to load." },
                            { text = "Please submit the form." },
                        },
                    },
                    {
                        text = "Clear any Skyboxes and filters to see the plain colours for this next part.",
                        npcs = { "Skyboxes and filters" },
                    },
                    {
                        text = "To change the colour, rotate the prism near the singing bowl until it reaches the desired colour.",
                        npcs = {},
                    },
                    {
                        text = "To change the shape, right-click fill or empty the singing bowl. Every time you fill or empty the bowl, the crystal will respectively gain or lose a side.",
                        npcs = {},
                    },
                    {
                        text = "To finalise the crystal into the shape, sing-glass on the singing bowl.",
                        npcs = {},
                    },
                    {
                        text = "To obtain more minute crystal seeds, search the crate just next to the bowl.",
                        npcs = { "minute crystal seed" },
                    },
                    {
                        text = "Once you sing all 6 desired shapes, calibrate the device then insert the correct shapes into their corresponding slots.",
                        npcs = {},
                    },
                    {
                        text = "Click the green tick mark at the bottom to complete the puzzle.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Arposandra", needed = {},
                steps = {
                    {
                        text = "Climb up the ladder and talk to Golrana underneath the steps just to the east of Lletya centre. (If you teleport to Lletya instead of leaving via the ladder, she will not appear. You can return to the lab from a trapdoor in the sheep pen in the northwest Lletya.)",
                        npcs = {},
                    },
                    {
                        text = "Once back up on the ledge, walk past the large boulder to the east, and Golrana should spot an air vent.",
                        npcs = {},
                    },
                    {
                        text = "Open the air vent on the rock wall just south of the boulder, then climb-down it.",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene Climb-up the stairs just next to you.",
                        npcs = {},
                    },
                    {
                        text = "Head east to the prison and rotate the watcher once.",
                        npcs = {},
                    },
                    {
                        text = "Enter the prison through the metal doors. Talk to the guard.",
                        npcs = {},
                    },
                    {
                        text = "Pick-lock on the northwest cell door. Talk to Bolrie.",
                        chat = "1 I fell down the shaft and we got separated. / 2 Ilfeen. / 3 Gena. / 3 42. / 1 The Grand Tree.",
                        npcs = {},
                    },
                    {
                        text = "Lead Bolrie out of the jail and west to the corridor behind the stairs you just came up.",
                        npcs = {},
                    },
                    {
                        text = "Continue through the door in the end and watch the cutscene.",
                        npcs = {},
                    },
                    {
                        text = "After the cutscene, stand north of the big boulder and push it southward to block the air vent.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the gnomes for a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Talk to them again to watch a second cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "The Prisoner of Glouphrie",
                        npcs = { "The Prisoner of Glouphrie (achievement)" },
                    },
                    {
                        text = "Power of Three Spirits",
                        npcs = { "Power of Three Spirits" },
                    },
                    {
                        text = "Tirannwn achievements",
                        npcs = { "Tirannwn achievements" },
                        subs = {
                            { text = "Medium - Gnome Roaming" },
                        },
                    },
                },
            },
        },
    },
    {
        key = "the_restless_ghost", name = "The Restless Ghost", wiki = "The Restless Ghost/Quick guide",
        required = {},
        recommended = {},
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to Father Aereck in Lumbridge Church.",
                        chat = "3 I'm looking for a quest! / Accept",
                        npcs = { "Father Aereck", "Lumbridge Church" },
                    },
                    {
                        text = "Go through the graveyard's southern exit and follow the shore to a mining site. Head west to a hut in the swamp.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Ghostspeak amulet", needed = {},
                steps = {
                    {
                        text = "Talk to Father Urhney inside the hut.",
                        chat = "2 Father Aereck sent me to talk to you. / 1 A ghost is haunting his graveyard.",
                        npcs = { "Father Urhney" },
                    },
                    {
                        text = "Go back to the graveyard and open a coffin located south of the catacombs.",
                        npcs = {},
                    },
                    {
                        text = "Equip the Ghostspeak amulet and talk to the ghost.",
                        chat = "1 Yep. Now, tell me what the problem is.",
                        npcs = { "Ghostspeak amulet" },
                    },
                },
            },
            {
                title = "The skull", needed = {},
                steps = {
                    {
                        text = "Head back through the southern gate of the graveyard, keep walking until you reach the mining site once again.",
                        npcs = {},
                    },
                    {
                        text = "Look south-east of the mining site, there are some rocks. Search the rocks, you will receive a muddy skull.",
                        npcs = { "Rocks (The Restless Ghost)" },
                    },
                    {
                        text = "Kill the skeleton or run away.",
                        npcs = {},
                    },
                    {
                        text = "Go back to the graveyard, reopen the coffin and use the skull on the open coffin.",
                        chat = "1 Put the skull in the coffin.",
                        npcs = {},
                    },
                    {
                        text = "Quest completed!",
                        npcs = {},
                    },
                },
            },
        },
