    {
        key = "the_slug_menace", name = "The Slug Menace", wiki = "The Slug Menace/Quick guide",
        required = { "Swamp paste", "At least 5 rune essence or pure essence (the essence can break during the quest, so to be safe, bring 10-15)", "Tools to access air, earth, water, fire, and mind altar by any means:", "An air, an earth, a water, a fire and a mind talisman", "An elemental and a mind talisman", "An omni-talisman", "Their corresponding tiaras", "A wicked hood charged with any of above combinations will also work", "Access to the Abyss", "Commorb (can be obtained during quest)" },
        recommended = { "An amulet of glory with at least one charge", "Melee equipment to kill a level 51 monster", "Activated Ardougne and Falador lodestone", "Runecrafting pouches can carry rune essence or pure essence for you if you have completed the Enter the Abyss (miniquest)", "A traveller's necklace", "The Cape of legends for quick teleport to Legends' Guild, just north of Witchaven." },
        sections = {
            {
                title = "Witchaven weirdness", needed = {},
                steps = {
                    {
                        text = "Talk to Sir Tiffy Cashien in Falador park.",
                        npcs = { "Sir Tiffy Cashien", "Falador park" },
                    },
                    {
                        text = "Talk to Col. O'Niall on the pier in Witchaven (fairy ring BLR or Cape of Legends and run south).",
                        chat = "3 Who are the important people in Witchaven? / 4 That's enough for now.",
                        npcs = { "Col. O'Niall", "Witchaven", "fairy ring", "Cape of Legends" },
                    },
                    {
                        text = "Talk to Mayor Hobb in the western building just south of Caroline.",
                        chat = "Any / 2 What improvements are you making to the shrine? / 4 Nothing at the moment thanks.",
                        npcs = { "Mayor Hobb" },
                    },
                    {
                        text = "When you try to exit the building, Savant will contact you and request that you scan nearby the Mayor using the Commorb v2",
                        npcs = { "Savant", "Commorb v2" },
                    },
                    {
                        text = "Go back into the mayor's building, stand beside him and begin scanning.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Brother Maledict in the church.",
                        chat = "4 That's enough for now.",
                        npcs = { "Brother Maledict" },
                    },
                    {
                        text = "Talk to Holgart to the north.",
                        npcs = { "Holgart" },
                    },
                    {
                        text = "Report back to Col. O'Niall.",
                        chat = "4 That's enough for now.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Imposing door", needed = { "Commorb v2, 2 backpack space" },
                steps = {
                    {
                        text = "Climb-down the old ruin entrance west of Witchaven.",
                        npcs = { "old ruin entrance" },
                    },
                    {
                        text = "Push the wall to your immediate east.",
                        npcs = { "Wall (Witchaven Dungeon)" },
                    },
                    {
                        text = "Enter the Wall Opening",
                        npcs = {},
                    },
                    {
                        text = "Run through the cave until you reach a set of imposing doors.",
                        npcs = { "Imposing doors (Witchaven Dungeon)" },
                        subs = {
                            { text = "Take the Agility shortcut (requires level 30)." },
                        },
                    },
                    {
                        text = "Savant will contact you.",
                        npcs = {},
                    },
                    {
                        text = "Scan with the commorb to obtain a door transcription.",
                        npcs = { "door transcription" },
                    },
                    {
                        text = "Pick up the dead sea slug on the ground nearby. You only need one.",
                        npcs = { "dead sea slug" },
                    },
                    {
                        text = "Talk to Jorral in the small Outpost, north-west of West Ardougne.",
                        chat = "2 Translations",
                        npcs = { "Jorral", "Outpost", "West Ardougne" },
                        subs = {
                            { text = "Traveller's necklace to the Outpost." },
                        },
                    },
                    {
                        text = "Savant will contact you while talking to Jorral and after.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Col. O'Niall in Witchaven (fairy ring BLR or cape of legends and run south).",
                        npcs = { "fairy ring", "cape of legends" },
                    },
                    {
                        text = "Go near the church (a cutscene will begin).",
                        npcs = {},
                    },
                    {
                        text = "Talk to Brother Maledict in the church.",
                        chat = "2 Talk about something else",
                        npcs = {},
                    },
                },
            },
            {
                title = "Page pieces", needed = { "Commorb v2, 1 swamp paste, 5 backpack spaces, 1 Dead sea slug" },
                steps = {
                    {
                        text = "Search the Mayor's study desk. You may fail, so repeat until you receive Page 1.",
                        npcs = { "Study desk (The Slug Menace)", "Page 1" },
                    },
                    {
                        text = "Talk to Ezekial Lovecraft in the fishing shop.",
                        npcs = { "Ezekial Lovecraft" },
                    },
                    {
                        text = "Talk to Col. O'Niall. This step requires 3 backpack spaces.",
                        npcs = {},
                    },
                    {
                        text = "Try to use the swamp paste on the fragments.",
                        npcs = {},
                        subs = {
                            { text = "Savant will contact you." },
                        },
                    },
                    {
                        text = "Talk to Jeb to reach the fishing platform.",
                        npcs = { "Jeb" },
                    },
                    {
                        text = "Talk to Bailey to the west.",
                        npcs = {},
                    },
                    {
                        text = "Use the Sea slug glue on the fragments.",
                        npcs = { "Sea slug glue" },
