                        subs = {
                            { text = "If you asked Ali for help getting there, he gave you a Dig Site pendant (or Ali's pendant if you have not unlocked the ability to create Dig Site pendants) to teleport directly there." },
                            { text = "Alternatively, teleporting to Varrock Dig Site with either pendant for the first time will grant you the Return to Senntisten achievement." },
                        },
                    },
                    {
                        text = "Talk to Dr. Nabanik outside of the Exam Centre south of the Digsite.",
                        chat = "1 (Whisper) Why are we speaking so quietly? / 1 Azzanadra? You are quite the master of disguise. / 1 Why are you here, away from the pyramid? / 2 What's Ali's part in this? / 3 Why all the secrecy? / 4 Just tell me what you want.",
                        npcs = { "Dr. Nabanik", "Exam Centre" },
                    },
                    {
                        text = "Talk to Terry Balando inside the exam centre for a restoration certificate.",
                        chat = "1 I'm here about a close friend of mine: Dr Nabanik. / 1 He was in the pyramid for a very long time. / 1 I've seen those beetles and they're huge. / 1 He studies pyramids, particularly their interiors. / 1 He has an aged benefactor.",
                        npcs = { "Terry Balando", "restoration certificate" },
