        required = { "Ancient timepiece (if Time Served is not completed)", "Pontifex signet ring (can be on the tool belt)", "500 Divination memories, vibrant or better (collected after shadow engrammeter (depleted) has been obtained)" },
        recommended = { "Ring of visibility or Sliske's gift (post-mystery completion for extra rewards)", "'Animate Dead' spell scroll (alternatively players can use an 'Animate Dead' spell scroll (loaned) given by Dr Nabanik)", "'Exsanguinate' spell scroll (alternatively players can use an 'Exsanguinate' spell scroll (loaned) given by Dr Nabanik)", "'Incite Fear' spell scroll (alternatively players can use an 'Incite Fear' spell scroll (loaned) given by Dr Nabanik)", "'Smoke Cloud' spell scroll (alternatively players can use a 'Smoke Cloud' spell scroll (loaned) given by Dr Nabanik)" },
        sections = {
            {
                title = "Getting started", needed = {},
