    {
        key = "the_void_stares_back", name = "The Void Stares Back", wiki = "The Void Stares Back/Quick guide",
        required = { "Hard leather (obtainable during quest)", "Limestone brick (obtainable during quest)", "Logs (obtainable during quest)", "8 backpack spaces" },
        recommended = { "Level 100 Combat", "High level food", "Armour and a weapon (for killing the pests) (either melee, necromancy, or both magic and ranged for fighting the torcher pest)", "Prayer potions" },
        sections = {
            {
                title = "Getting started", needed = { "3 free inventory spaces" },
                steps = {
                    {
                        text = "Talk to Korasi in Falador Park.",
                        chat = "Accept",
                        npcs = { "Korasi", "Falador Park" },
                    },
                },
            },
            {
                title = "Infiltration", needed = { "5 backpack spaces, limestone brick, hard leather, black full helm (bugged), black platebody (bugged), and black platelegs (bugged)" },
                steps = {
                    {
                        text = "Go to the entrance of the Black Knights' Fortress north-west of the Edgeville Monastery.",
                        npcs = { "Black Knights' Fortress", "Edgeville Monastery" },
                    },
                    {
                        text = "Equip the black full helm (bugged), black platebody (bugged), and black platelegs (bugged). Open the portcullis. Commander Colby will yell at you and teleport you.",
                        npcs = { "Portcullis (Black Knights' Fortress)" },
                        subs = {
                            { text = "Once you finally get to the storage room, your helmet will be taken." },
                        },
                    },
                    {
                        text = "If you leave the room at any point (including disconnect), or once your helmet is taken, you will no longer be able to use the Black Knights' Fortress to return to the storage area.",
                        npcs = {},
                        subs = {
                            { text = "Instead, enter via the Black Knights' Base inside the Taverley Dungeon." },
                            { text = "Inside the Black Knights' Base, enter the door south from the conquest map table, which is found in the middle of the floor." },
                        },
                    },
                },
            },
            {
                title = "Room 1", needed = {},
                steps = {
                    {
                        text = "Talk to Captain Gilroy.",
                        npcs = { "Captain Gilroy" },
                    },
                    {
                        text = "Attempt to take an item from any crate.",
                        npcs = {},
                    },
                    {
                        text = "Speak to Gilroy. (correct order of blocks is 4, 2, 6, 3, 5)",
                        chat = "3 I think I've got it, sir.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Gilroy again..",
                        chat = "3 actually weigh 4 / 1 are of weight 2 / 5 should be labelled 6 / 2 really weigh 3 / 4 need to be marked 5",
                        npcs = {},
                    },
                    {
                        text = "Balance the scale on the wall to the south, arrange the weights to make 15 on each side. (Top: 3-5-3-4 and Bottom: 2-2-5-6)",
                        npcs = {},
                    },
                    {
                        text = "Proceed to the next room.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Room 2", needed = {},
                steps = {
                    {
                        text = "Kill the enemies in the room and pick up the security blocks that are dropped.",
                        npcs = { "security block" },
                    },
                    {
                        text = "Talk to Gilroy.",
                        chat = "2 What do we do now?",
                        npcs = {},
                    },
                    {
                        text = "Exit the room and head to the jail, northeast of the storage room, and search the crate for a piece of hard leather.",
                        npcs = { "hard leather" },
                    },
                    {
                        text = "Search a crate in the kitchen for some logs, just north of the jail.",
                        npcs = { "logs" },
                    },
                    {
                        text = "Head to the tiny forge on the west side of the base (icon on minimap).",
                        npcs = { "tiny forge" },
                    },
                    {
                        text = "Search the crate in the south-west corner of the forge room for a limestone brick.",
                        npcs = { "limestone brick" },
                    },
                    {
                        text = "Return to the forge and repair it.",
                        npcs = {},
                    },
                    {
                        text = "Use the logs on the forge to fuel it.",
                        npcs = {},
                    },
                    {
                        text = "Light the forge.",
                        npcs = {},
                    },
                    {
                        text = "Use the broken security block on the forge to repair it.",
                        npcs = {},
                    },
                    {
                        text = "Go back into the room with Gilroy and place all the blocks within the western wall.",
                        npcs = {},
                    },
                    {
                        text = "Proceed to the next room.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Room 3", needed = {},
                steps = {
                    {
                        text = "Click on the panel on the western wall.",
                        chat = "2 Search the panels for magical traps.",
                        npcs = {},
                    },
                    {
                        text = "Open the panel.",
                        npcs = {},
                    },
                    {
                        text = "Drag the tiles into the panels so that a horizontal line is going across all three panels, while filling the empty spaces. Press confirm once completed.",
                        npcs = {},
                    },
                    {
                        text = "Proceed to the next room.",
                        npcs = {},
                    },
                },
            },
            {
                title = "A little game", needed = {},
                steps = {
                    {
                        text = "Reveal yourself and explain the danger to Lord Daquarius. Accept the allegiance.",
                        chat = "1 Yes, sir. / 3 Explain the danger in calm, logical terms. / 1 Okay, I'll do it.",
                        npcs = { "Lord Daquarius" },
                    },
                    {
                        text = "Talk to Korasi.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Commodore Tyr.",
                        chat = "1 I'm ready.",
                        npcs = { "Commodore Tyr" },
                        subs = {
                            { text = "At this point you can equip your own armour again instead of the Black Knight (bugged) armour." },
                        },
                    },
                    {
                        text = "Enter the portal and watch the cutscene.",
                        chat = "1 You bet!",
                        npcs = {},
                    },
                    {
                        text = ": Make sure you go through each dialogue box, otherwise it will kick you out of the portal and you will have to start the cutscene from the start.",
                        npcs = {},
                    },
                    {
                        text = "A game of modified conquest must be played and won.",
                        npcs = {},
                        subs = {
                            { text = "Spinners are very powerful but do not heal like in Pest Control." },
                            { text = "Ravagers have the movement range of Scouts and the damage rate of a Knight." },
                            { text = "Shifters are less of a threat than other units and can be tanked if need be." },
                            { text = "Torchers are similar to Mages." },
                            { text = "Defilers are similar to Archers." },
                            { text = "Splatters will explode and deal 100 life points of damage to any adjacent unit that is within 1 square." },
                        },
                    },
                    {
                        text = "Win the game and proceed to the next room.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The Pest Queen", needed = {},
                steps = {
                    {
                        text = "Sacrifice either Korasi or Jessika.",
                        npcs = { "Jessika" },
                    },
                    {
                        text = "Speak to Valluta before stocking for the fight or Sir Tiffy won't teleport you back.",
                        npcs = { "Valluta" },
                    },
                    {
                        text = "Make all necessary preparations to fight the Pest Queen. Korasi's sword will be the primary weapon during the fight and its Special attacks will be used a lot.",
                        npcs = { "Pest Queen", "Korasi's sword", "Special attack" },
                        subs = {
                            { text = "It may be helpful to use manual attack abilities rather than Revolution." },
                            { text = "You can use necromancy to trivialise the encounter. Summon conjures prior to equipping Korasi's sword, and keep your necromancy offhand equipped. Ghost will provide full sustain without food, and skeleton will do the majority of the damage." },
                        },
                    },
                    {
                        text = "Kill the Pest Queen.",
                        npcs = {},
                        subs = {
                            { text = "The Weapon Special attack is located under Constitution abilities." },
                            { text = "If you die, talk to Sir Tiffy in Falador park and he will teleport you back to the portal. You will lose the weapon if you die. Reclaim this from Jessika/Korasi before you attack the Pest Queen again.", chat = "3" },
                            { text = "Build your adrenaline up more than 60% then use the special attack \"Disrupt\" to stun the Pest Queen when she raises her head and starts shaking for several seconds." },
                            { text = "Hurt but don't kill the spawning Elite defilers to defend Void Knight archers. They need to be focussed on you so more don't respawn and so they don't hurt your archers." },
                            { text = "More in-depth strategies can be found here." },
                        },
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Talk to Korasi or Jessika. Decide who to let deal with Wizard Grayzag.",
                        chat = "Any",
                        npcs = { "Wizard Grayzag" },
                    },
                    {
                        text = "Talk to Commodore Tyr.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "the_world_wakes", name = "The World Wakes", wiki = "The World Wakes/Quick guide",
        required = {},
        recommended = { "Level 100 Combat, it is recommended that you have balanced combat stats at around level 70 each.", "Food (Monkfish or a higher tier food is recommended), weapons and armour", "Yew logs or better for a bonfire boost", "Combat boosting potions (e.g. super ranging potion or super magic potion)", "Prayer-restoring potions (e.g. prayer potion or super restore)" },
        sections = {
            {
                title = "Helping Orlando", needed = { "Gear and food for fights." },
                steps = {
                    {
                        text = "Talk to Orlando Smith, West of the Legends' Guild (fairy code BLR, or use the Ardougne lodestone).",
                        chat = "1 Can I help at all? / 1 So you just need me to open the doors? / Accept",
                        npcs = { "Legends' Guild", "Ardougne lodestone" },
                        tile = { x = 2701, y = 3372, plane = 0 },
                    },
                    {
                        text = "Open the door.",
                        npcs = {},
                    },
                    {
                        text = "Investigate the following 6 artefacts:",
                        npcs = {},
                        subs = {
                            { text = "Inactive obelisk (north-west)" },
                            { text = "Stone carvings (north)" },
                            { text = "The other stone carvings (north-east)" },
                            { text = "Clouded vials (north-east)" },
                            { text = "Dusty parchment (south-east)" },
                            { text = "Shattered blade (south)" },
                        },
                    },
                    {
                        text = "Investigate the Guthixian statue to the east.",
                        npcs = { "Guthixian statue" },
                    },
                    {
                        text = "Enter the next room to the east and kill the 3 automatons.",
                        npcs = { "Automaton (monster)" },
                        subs = {
                            { text = "You must finish the entire dialogue with the Automatons before clicking to attack them (there's a small break in the dialogue) or you will have to redo the cutscene again." },
                            { text = "Warning: Automatons can deal high damage to players standing within their special attack range. Lower-level players should use ranged, magic, or necromancy to attack them." },
                        },
                    },
                    {
                        text = "Talk to Sliske.",
                        chat = "3 I, [Player], stand before you! Do your worst! / 1 What does this mean? / 1 What do you mean, trouble? / 1 Okay then.",
                        npcs = { "Sliske" },
                    },
                    {
                        text = "Continue talking to Sliske after the cutscene.",
                        chat = "1 What do you gain from telling me this? / 2 So how do I come into this? / 1 I already know my decision. / Any",
                        npcs = {},
                    },
                    {
                        text = "If Kree'arra and Commander Zilyana don't spawn, talk to Sliske again.",
                        npcs = { "Kree'arra", "Commander Zilyana" },
                    },
                },
            },
            {
                title = "Defeating Kree'arra", needed = {},
                steps = {
                    {
                        text = "After the cutscenes, talk to Kree'arra.",
                        chat = "3 Why are you following Zilyana, then? / 3 If you want to get rid of me, you'll have to do it the hard way.",
                        npcs = { "Kree'arra" },
                    },
                    {
                        text = "Defeat Kree'arra. Avoid standing on the tornadoes.",
                        npcs = {},
                    },
                    {
                        text = "Pass through the door (east).",
                        npcs = {},
                    },
                },
            },
            {
                title = "Lock mechanism", needed = {},
                steps = {
                    {
                        text = "Run to the other side of the room and activate the control panel.",
                        chat = "1 Guthix is in trouble. I'm here to protect him.",
                        npcs = {},
                    },
                    {
                        text = "While using the control panel you can release a boulder by clicking on the dispenser in the corner of the screen. The goal is to get the boulder from the dispenser to the receptacle tile (circular cavity with a green dot).",
                        npcs = {},
                    },
                    {
                        text = "To solve the puzzle:",
                        npcs = {},
                        subs = {
                            { text = "Rotate the tracks to create a path from the dispenser to the green hole, matching the solutions below (NOTE: puzzle can crash based on camera settings try classic)" },
                            { text = "Click the appropriate dispenser to release the boulder" },
                            { text = "When the boulder halts at a gate, wait for the next tile to auto-rotate such that the path continues, and click the gates to release the boulder at the right time" },
                        },
                    },
                },
            },
            {
                title = "Leading the guardians", needed = {},
                steps = {
                    {
                        text = "After the cutscenes (skippable), view the strange map to the east.",
                        npcs = {},
                    },
                    {
                        text = "Answer four randomised questions to balance the pillars (Chaos, Order, Good, and Evil must all be exactly 50%). Refer to the below table and pick the appropriate answers:",
                        npcs = {},
                    },
                    {
                        text = "Give the group a motivational speech",
                        chat = "1 Enthuse the group. / 1 Reinforce the importance of protecting the edicts. / 1 Highlight the strengths of the group.",
                        npcs = {},
                    },
                    {
                        text = "Drag the guardian icons to the correct threat based on the hover text in the top row:",
                        npcs = {},
                        subs = {
                            { text = "Chaeldar and Thaerisk — Whoever is coming through this wing is very big and slow. It sounds like they are using their immense strength to force their way through the rock. Perhaps they don't have the intelligence to try any other way." },
                            { text = "Cres and automatons — It sounds like there are a lot of enemies breaking through here, and the foul stench of the undead can be smelled. Whoever is leading these troops must have an immense talent to undermine death itself." },
                            { text = "Death — This enemy sounds large, slow and heavy, but they are using more than their strength to break through. The impact of magic can be heard alongside demonic chanting, so they must have some intelligence." },
                            { text = "Valluta and Fiara — Whoever is coming through here sounds small and nimble. They seem to be using only magic, so it could be assumed they'll have a high resistance to magic used against them. Their attacks sound extremely aggressive, as if they're beyond determined." },
                        },
                    },
                    {
                        text = "Talk to Juna.",
                        chat = "1 I've finished setting up. / 1 I'm happy with the formation for now.",
                        npcs = { "Juna" },
                    },
                    {
                        text = "Finish the dialogue after the cutscene (including a pause in dialogue) or you will be forced to watch it again.",
                        npcs = {},
                    },
                    {
                        text = "Drink from the elixirs if you need to restore your health or prayer.",
                        npcs = {},
                    },
                    {
                        text = "Note: you can bank if you talk to Druidess. Look for the bank icon on the minimap.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Defeating Graardor", needed = {},
                steps = {
                    {
                        text = "Enter the north-west storage wing guarded by Chaeldar and Thaerisk Cemphier.",
                        chat = "1 Yes, I'm sure. Let's go.",
                        npcs = { "Chaeldar", "Thaerisk Cemphier" },
                    },
                    {
                        text = "Defeat General Graardor. Protect from Melee is preferred.",
                        npcs = { "General Graardor", "Protect from Melee" },
                    },
                    {
                        text = "Be aware of his special attacks:",
                        npcs = {},
                        subs = {
                            { text = "He reflects your damage when he shouts \"Graardor protect!\"." },
                            { text = "Move away from his charging path when he shouts \"Graardor mad!\"." },
                            { text = "Avoid the falling debris by looking at the shadows when he shouts \"Graardor smash!\"." },
                        },
                    },
                    {
                        text = "Enter the exit.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Defeating Zemouregal", needed = {},
                steps = {
                    {
                        text = "Enter the north storage wing guarded by Cres.",
                        chat = "1 Yes, I'm sure. Let's go.",
                        npcs = { "Cres" },
                    },
                    {
                        text = "Defeat Zemouregal. Bringing Antipoison is recommended.",
                        npcs = { "Zemouregal" },
                    },
                    {
                        text = "Protect from magic works best here.",
                        npcs = {},
                    },
                    {
                        text = "Start by killing the two dark portals.",
                        npcs = {},
                    },
                    {
                        text = "Stay away from Decaying portals or kill them quickly.",
                        npcs = { "Decaying portal" },
                    },
                    {
                        text = "Attack Zemouregal to about 70%.",
                        npcs = {},
                    },
                    {
                        text = "Kill 4 more dark portals.",
                        npcs = {},
                    },
                    {
                        text = "Kill the decaying portals to lower his defence, if necessary.",
                        npcs = {},
                    },
                    {
                        text = "Finish Zemouregal.",
                        npcs = {},
                    },
                    {
                        text = "Enter the exit.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Defeating K'ril Tsutsaroth", needed = {},
                steps = {
                    {
                        text = "Enter the south-west storage wing guarded by Death.",
                        chat = "1 Yes, I'm sure. Let's go.",
                        npcs = { "Death" },
                    },
                    {
                        text = "Defeat K'ril Tsutsaroth. Be aware of his special attacks.",
                        npcs = { "K'ril Tsutsaroth" },
                    },
                    {
                        text = "When he shouts \"You cannot stand against Zamorakian might!\" avoid the spikes that appear under you.",
                        npcs = {},
                    },
                    {
                        text = "When he shouts \"Run, coward!\" he will charge forwards, simply move out the way.",
                        npcs = {},
                    },
                    {
                        text = "When he shouts \"Guthix will die in the name of Zamorak!\" you will need to constantly run from K'ril otherwise he will hit you very rapidly.",
                        npcs = {},
                    },
                    {
                        text = "Enter the exit.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Defeating Enakhra", needed = {},
                steps = {
                    {
                        text = "Enter the south storage wing guarded by Fiara and Valluta.",
                        npcs = { "Fiara", "Valluta" },
                    },
                    {
                        text = "Defeat Enakhra.",
                        npcs = { "Enakhra" },
                    },
                    {
                        text = "Protect from Magic is preferred.",
                        npcs = { "Protect from Magic" },
                    },
                    {
                        text = "She will sometimes start to steal from your health. Hide behind any obstacle to stop her. It may help to disable auto-retaliate since her ranged attacks can unintentionally draw you out of hiding.",
                        npcs = {},
                    },
                    {
                        text = "The lower your health, the less she heals. Low-healing food like cakes, pizzas, or a bunyip can keep you alive for a long time.",
                        npcs = { "bunyip" },
                    },
                    {
                        text = "She will occasionally stun you. Activating Freedom will free you.",
                        npcs = { "Freedom" },
                    },
                    {
                        text = "Enter the exit.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Protecting Juna", needed = {},
                steps = {
                    {
                        text = "Talk to Cres in the center.",
                        npcs = { "Cres" },
                    },
                    {
                        text = "Talk to Juna in the east.",
                        npcs = { "Juna" },
                    },
                    {
                        text = "Defend Juna from the spiritual enemies for 2 minutes.",
                        npcs = { "Juna" },
                    },
                    {
                        text = "Jump over a barrier to safety near Juna and simply repair barriers as they slowly become half-broken.",
                        npcs = {},
                    },
                    {
                        text = "Alternatively, kill the enemies, which are fairly weak. Attacks that hit multiple enemies simultaneously are effective, such as Ancient Magicks.",
                        npcs = { "Ancient Magicks" },
                    },
                    {
                        text = "Talk to Azzanadra after the skippable cutscene.",
                        chat = "Any / Any",
                        npcs = { "Azzanadra" },
                    },
                },
            },
            {
                title = "Guthix", needed = {},
                steps = {
                    {
                        text = "Note: The next area does not require combat, but contains environmental hazards that can easily lead to unsafe death, and does not allow teleporting out. You may wish to bank now.",
                        npcs = {},
                        subs = {
                            { text = "Teleport out to bank all gear and items; bring high-healing food. Fireballs do 20% of your max life points rapidly while running under them. Do not bring life points boosting gear as it will be harder to out-eat them." },
                            { text = "Return via the Ardougne lodestone and run east to the entrance of the chamber." },
                        },
                    },
                    {
                        text = "Enter the shattered wall.",
                        npcs = {},
                    },
                    {
                        text = "Run down the path, avoiding the boulders and flames. If you get trapped between ice spikes, click them to break free.",
                        npcs = {},
                    },
                    {
                        text = "After the skippable cutscene, walk east down to the pedestal in front of Guthix. He will teleport you.",
                        npcs = { "Guthix" },
                    },
                    {
                        text = "Walk between the islands, talking to Guthix along the way.",
                        chat = "Any",
                        npcs = { "Guthix" },
                    },
                    {
                        text = "On your return, talk to one of the guardians.",
                        chat = "Any / Any",
                        npcs = {},
                    },
                    {
                        text = "After a skippable cutscene, Saradomin will appear in front of you. Talk to him.",
                        chat = "Any / Any",
                        npcs = { "Saradomin" },
                    },
                    {
                        text = "Talk to Juna (10 free inventory slots are required).",
                        npcs = { "Juna" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "there_s_no_place_like_home", name = "There's No Place Like Home...", wiki = "There's No Place Like Home.../Quick guide",
        required = { "Two regular logs (obtainable once during quest)" },
        recommended = {},
