    {
        key = "thok_it_to_em_saga", name = "Thok It To 'Em (saga)", wiki = "Thok It To 'Em (saga)/Quick guide",
        required = { "Ring of kinship to find scribbled notes" },
        recommended = { "To play the unabridged version:", "Level 70 Strength" },
        sections = {
            {
                title = "Beginning of the story", needed = {},
                steps = {
                    {
                        text = "Find the scribbled note while raiding the 30-35 Abandoned 2 floors of Daemonheim, and recover memory of it.",
                        npcs = { "scribbled note", "Daemonheim" },
                    },
                    {
                        text = "Talk to Skaldrun and ask him to tell you a story.",
                        chat = "1 Forgot what he says here / 1 Tell me a story",
                        npcs = { "Skaldrun" },
                        subs = {
                            { text = "You need to bank everything, including the ring of kinship." },
                            { text = "If the option to start this saga is not available, that means you haven't found the scribbled note on the floor inside Daemonheim." },
                        },
                    },
                },
            },
            {
                title = "Starting room", needed = {},
                steps = {
                    {
                        text = "Kill Stomp like you would in a normal dungeon.",
                        npcs = { "Stomp" },
                    },
                },
            },
            {
                title = "Thok", needed = {},
                steps = {
                    {
                        text = "As Thok, continue down the ladder and kill The Thing with eyes.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Big rock room", needed = {},
                steps = {
                    {
                        text = "Continue east and exorcise dark spirit to the east.",
                        npcs = {},
                    },
                    {
                        text = "Kill the 2 enemies in the next room and continue south.",
                        npcs = {},
                    },
                    {
                        text = "Kill the 3 enemies in the next room and continue east.",
                        npcs = {},
                    },
                    {
                        text = "Pick up the silver curvy thing to the southeast and return back to the starting room to unlock the silver wibbly thing.",
                        npcs = {},
                    },
                    {
                        text = "Activate the big rock and kill all the squishy ghosts until the monolith is fully charged then continue north.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Coward with a bow", needed = {},
                steps = {
                    {
                        text = "Head west and kill the coward with a bow.",
                        npcs = {},
                    },
                    {
                        text = "Once he has been killed, run back to the room where the Silver curvy thing was found (marked by the summoning icon on the minimap).",
                        npcs = {},
                    },
                    {
                        text = "Next, continue through the rooms to the east, north and east again.",
                        npcs = {},
                    },
                    {
                        text = "Take the Red block from the floor.",
                        npcs = {},
                        subs = {
                            { text = "If additional food is required, Crunchy rune rocks can be acquired from the supply table." },
                        },
                    },
                },
            },
            {
                title = "Bulky warrior", needed = {},
                steps = {
                    {
                        text = "Run back through the rooms: west, south, and 2 more rooms west.",
                        npcs = {},
                    },
                    {
                        text = "Enter the southern door, then go west by unlocking the red wibbly thing.",
                        npcs = {},
                    },
                    {
                        text = "Attempt to imbue the tiles 3 times. On the third try, Thok will manage to imbue all the tiles correctly.",
                        npcs = {},
                    },
                    {
                        text = "Take the blue pointed thing in the northwestern corner of the room.",
                        npcs = {},
                    },
                    {
                        text = "Go into the next room with the bulky warrior. Kill him and move out of the direction he is facing if he prepares to charge.",
                        npcs = {},
                    },
                    {
                        text = "Once the bulky warrior has been defeated, return to the room with the summoning icon indicated on the minimap.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Armoured cow thing", needed = {},
                steps = {
                    {
                        text = "Unlock the Blue wibbly thing.",
                        npcs = {},
                    },
                    {
                        text = "Upon entering the room, take a pickaxe from the rock and equip it.",
                        npcs = {},
                    },
                    {
                        text = "Attack the Armoured cow thing until its armour is destroyed.",
                        npcs = {},
                    },
                    {
                        text = "Continue the fight with Thok's sword.",
                        npcs = {},
                    },
                    {
                        text = "After the fight, go back to the room with the supply table (North-East side).",
                        npcs = {},
                    },
                },
            },
            {
                title = "Gobby demon", needed = {},
                steps = {
                    {
                        text = "In the room to the north, kill the Ramokee skinweaver first, then move on to killing the other ramokees.",
                        npcs = {},
                    },
                    {
                        text = "Moving to the next room, talk to Thok-blocker until it allows you to enter the room.",
                        npcs = {},
                    },
                    {
                        text = "Pick up the Orange stick thing in the southeast corner of the room, and return to the room to the east.",
                        npcs = {},
                    },
                    {
                        text = "Unlock the Orange wibbly thing to face Gobby demon.",
                        npcs = {},
                    },
                    {
                        text = "Thok should be able to kill the demon before any of its attacks are used. However, if portals appear on the ground, move away from them and continue attacking.",
                        npcs = {},
                    },
                    {
                        text = "Go back through the door and take the door to the west.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "Kill Warped Gulega. Avoid the 1 lifepoint attack by moving 1 square away when tentacles appear on the ground.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Pretty Lass.",
                        chat = "1 [Tell her about Marmaros] / 2 [Take her to Marmaros]",
                        npcs = {},
                    },
                    {
                        text = "Kill the Walking ice cube.",
                        npcs = {},
                        subs = {
                            { text = "Every 33% damage dealt it will encase itself in ice and running around the dungeon will avoid the player from being hit." },
                        },
                    },
                },
            },
        },
    },
    {
        key = "thok_your_block_off_saga", name = "Thok Your Block Off (saga)", wiki = "Thok Your Block Off (saga)/Quick guide",
        required = { "Ring of kinship to find the rock and twine bundle. Players cannot bring it into the saga itself." },
        recommended = { "Full:Thok Your Block Off (saga)", "To play the unabridged version:", "Level 75 Strength" },
        sections = {
            {
                title = "Beginning of the story", needed = {},
                steps = {
                    {
                        text = "Find the rock and twine bundle while raiding the 36-40 occult floors of Daemonheim, and recover memory of it.",
                        npcs = { "rock and twine bundle", "Daemonheim" },
                    },
                    {
                        text = "Talk to Skaldrun and ask him to tell you a story.",
                        chat = "1 Forgot what he says here / 1 Tell me a story",
                        npcs = { "Skaldrun" },
                        subs = {
                            { text = "You need to bank everything, including the ring of kinship." },
                        },
                    },
                },
            },
            {
                title = "Starting room", needed = {},
                steps = {
                    {
                        text = "Kill all the enemies in the first room and finish dialogue with Marmaros.",
                        npcs = {},
                    },
                    {
                        text = "Enter the boss door to the west.",
                        npcs = {},
                    },
                    {
                        text = "Watch the cutscene and climb down the ladder to the west.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Venturing through the dungeon", needed = {},
                steps = {
                    {
                        text = "Head north and clear more enemies than Marmaros by clearing out the rooms as fast as possible, you are required to have at least 4 more kills than Marmaros at the end of the dungeon for unabridged tome. Continue this throughout the entire dungeon (legacy mode greatly increases hits). Auto-retaliate helps too.",
                        npcs = {},
                    },
                    {
                        text = "Head west, then west (reinforcement room) and pick up the Orange thing, west and enter the Orange shield door.",
                        npcs = {},
                    },
                    {
                        text = "Pick Frilly plants to the north of the room and mine Crumbly stuff just west of that. Make stuff on the Spinny stuff-maker south-east of the room to make the Best Thing Ever.",
                        npcs = {},
                    },
                    {
                        text = "Head east, north, east (reinforcement room) and pick up the Blue brick, unlock and proceed through the Blue rectangle room.",
                        npcs = {},
                    },
                    {
                        text = "Enter the Blue rectangle room again to give Pretty Lass the Best thing ever.",
                        npcs = {},
                    },
                    {
                        text = "Continue north then west and fish the bubbling water to find Mini-marm and Mrs mini-marm. This equips them as weapons which increases damage dealt.",
                        npcs = {},
                    },
                    {
                        text = "Continue north, then east (reinforcement room), then east again, and then south.",
                        chat = "1 Let's go!",
                        npcs = {},
                        subs = {
                            { text = "DO NOT pick up the Red pointy stone." },
                        },
                    },
                    {
                        text = "Attack and kill the Gluttonous behemoth",
                        npcs = {},
                        subs = {
                            { text = "Allow the gluttonous behemoth to access the other bosses as it will heal it and kill them. Once all other bosses are dead, the 1hp behemonth can be killed." },
                            { text = "If Derek becomes bugged and the Gluttonous Behemoth does not attack him, use the Cease ability (Defence, Utility Abilities) and wait until you leave combat (Thok will put his arms down to his sides) and trap the Behemoth behind the middle pillar. Exit to lobby, log back in, start the saga from your checkpoint and this should allow the Behemoth to attack Derek to heal itself." },
                        },
                    },
                    {
                        text = "Head west and watch the cutscene.",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "three_s_company_saga", name = "Three's Company (saga)", wiki = "Three's Company (saga)/Quick guide",
        required = { "Ring of kinship to find the bear pelt" },
        recommended = { "Persistent Rage relic power, for quick and unlimited healing with Regenerate", "To play the unabridged version:", "Level 30 Attack", "Level 30 Magic", "Level 30 Ranged" },
        sections = {
            {
                title = "Starting room", needed = {},
                steps = {
                    {
                        text = "Head to Daemonheim and bank everything, including your ring of kinship.",
                        npcs = { "Daemonheim", "ring of kinship" },
                    },
                    {
                        text = "Right-click choose start saga on Skaldrun, choose the first option then Play Saga. (Note: If you found the bear skin a long time ago and forgot about it, there is a chance this is bugged.. You are best off talking to Skaldrun manually and asking about the bearskin and to tell you the story. This is how you know you've found it already and can start the saga)",
                        npcs = { "Skaldrun" },
                    },
                    {
                        text = "Control Ariane, pick up the dusk eels from the tables.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Guardian room #1", needed = {},
                steps = {
                    {
                        text = "As Ariane, enter the south door, kill all the enemies and pick up the dusk eels.",
                        npcs = {},
                    },
                    {
                        text = "Pick up the gold charm and heim crabs but do not eat them.",
                        npcs = {},
                    },
                    {
                        text = "Control Sir Owen and check the rocky debris for a novite ore.",
                        npcs = {},
                    },
                    {
                        text = "Enter the south door.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Ice puzzle room", needed = {},
                steps = {
                    {
                        text = "Control Ozan and unlock the door by stepping on each of the 4 pressure plates.",
                        npcs = {},
                        subs = {
                            { text = "The puzzle is different for everyone and every time." },
                            { text = "You can slide diagonally." },
                        },
                    },
                    {
                        text = "Open the east door.",
                        npcs = {},
                    },
                    {
                        text = "Quickly switch to Ariane once in the next room.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Bridge room", needed = {},
                steps = {
                    {
                        text = "As Ariane, kill all the enemies. (Make sure you select earth strike in your magic book, it won't show properly but Ariane is lower level despite the spells that show up probably due to your character being higher level.)",
                        npcs = {},
                    },
                    {
                        text = "As Ariane, make a cub skinweaver by using the gold charm on the summoning obelisk.",
                        npcs = {},
                    },
                    {
                        text = "As Ariane, talk to the cub skinweaver.",
                        npcs = {},
                    },
                    {
                        text = "Enter the east door.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Tile flip room", needed = {},
                steps = {
                    {
                        text = "As Ariane, flip all tiles until all yellow or green.",
                        npcs = {},
                        subs = {
                            { text = "You can right click \"force\" to flip individual tiles." },
                        },
                    },
                },
            },
            {
                title = "Mysterious shade room", needed = {},
                steps = {
                    {
                        text = "As Ariane, enter the north door, quickly pick up the green rectangle key, and exit the room.",
                        npcs = {},
                    },
                    {
                        text = "Switch to Ozan and return to the starting room without teleporting (west, west, north, north).",
                        npcs = {},
                        subs = {
                            { text = "There is currently a bug where if you use Home Teleport, it will turn the character you are currently controlling into your player character and you'll no longer be able to switch to other characters or continue on. You'll be forced to restart the Saga from last checkpoint." },
                        },
                    },
                },
            },
            {
                title = "Magical imbue room", needed = {},
                steps = {
                    {
                        text = "Switch to Ariane.",
                        npcs = {},
                    },
                    {
                        text = "Unlock the green rectangle door and enter.",
                        npcs = {},
                    },
                    {
                        text = "\"Wait\" on each of the pressure pads for Owen and Ozan.",
                        npcs = {},
                    },
                    {
                        text = "Enter the south door.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Strange crystal room", needed = {},
                steps = {
                    {
                        text = "Take the crimson triangle key.",
                        npcs = {},
                    },
                    {
                        text = "Right-click \"Get-premonition\" on any strange crystal.",
                        npcs = {},
                    },
                    {
                        text = "Touch the following crystals in order:",
                        npcs = {},
                    },
                    {
                        text = "Enter the north door.",
                        npcs = {},
                    },
                    {
                        text = "Right-click call Owen and Ozan to walk them off the pressure plates.",
                        npcs = {},
                    },
                    {
                        text = "Enter the west door.",
                        npcs = {},
                    },
                    {
                        text = "As Ariane, unlock the crimson triangle door and enter it.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Guardian room #2", needed = {},
                steps = {
                    {
                        text = "As Ariane, kill all the enemies and pick up the dusk eels.",
                        npcs = {},
                    },
                    {
                        text = "Control Ozan, and enter the east door.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Door guard room", needed = {},
                steps = {
                    {
                        text = "As Ozan, talk to the guard.",
                        chat = "1 [Charm] What are you guarding? / 2 Isn't guarding a door in these dungeons a little...redundant? / 1 Who put you up to guarding the door? / 2 Why are you bothering to guard it?",
                        npcs = {},
                    },
                    {
                        text = "Enter the east door.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Statue puzzle room", needed = {},
                steps = {
                    {
                        text = "Control Owen and push the statues into place.",
                        npcs = {},
                        subs = {
                            { text = "The four southern statues should match the position of the statues in the north." },
                        },
                    },
                },
            },
            {
                title = "Pickaxe room", needed = {},
                steps = {
                    {
                        text = "Enter the east door and pick up the fractite pickaxe.",
                        npcs = {},
                    },
                    {
                        text = "Return west to the guard room and mine the zephyrium rock hidden behind the northwest pillar.",
                        npcs = {},
                    },
                    {
                        text = "Return east to the statue room.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Agility room", needed = {},
                steps = {
                    {
                        text = "Control Ozan and enter the northern door.",
                        npcs = {},
                    },
                    {
                        text = "Proceed through the traps and investigate the broken longsword.",
                        npcs = {},
                    },
                    {
                        text = "Control Ariane and return to the previous room.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Guardian room #3", needed = {},
                steps = {
                    {
                        text = "Enter the southern door, kill the enemies and pick up the dusk eel.",
                        npcs = {},
                    },
                    {
                        text = "Enter the east door and pick up the gold crescent key.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Pikkupstix (in the northwest corner of the room).",
                        chat = "3 Can you walk? / 1 You should head to the surface now. / 4 Leave",
                        npcs = {},
                    },
                    {
                        text = "Return to the room north of the starting room without teleporting (west, north, west, west).",
                        npcs = {},
                    },
                    {
                        text = "Unlock the gold crescent door north of the starting room.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Confronting Carn", needed = {},
                steps = {
                    {
                        text = "Enter the room and continue through the dialogue.",
                        chat = "1 Sir Owen / 2 Ozan / 3 Ariane",
                        npcs = {},
                    },
                    {
                        text = "Kill the two arctic bears and then kill Carn.",
                        npcs = {},
                    },
                    {
                        text = "Once he is killed, choose any chat option.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Required for completing", needed = { "100% completion of Three's Company is required for the achievement 300, an Area Task in the Medium Daemonheim subcategory." },
                steps = {
                },
            },
        },
    },
    {
        key = "throne_of_miscellania", name = "Throne of Miscellania", wiki = "Throne of Miscellania/Quick guide",
        required = { "Iron bar", "Log of any kind (excluding Eternal magic logs) (may be harvested when needed)", "Flowers (can be bought from the Flower Girl for 15 coins)", "Cake (if the player is wooing Prince Brand)", "Any bow (if the player is wooing Princess Astrid), excluding the training bow, composite bows, ogre bow, crystal bow, dark bow, chargebow, Kayle's chargebow, boogie bow, and masterwork bow; it will be lost during the quest", "Any tradeable, metal ring (some rings, like the opal ring, lapis lazuli ring, jade ring, topaz ring, Ring of Wealth (4), moonstone ring, onyx ring, hydrix ring, and luck of the dwarves, do not work. The gold ring, sapphire ring, emerald ring, ruby ring, diamond ring, dragonstone ring, ring of life, are confirmed to work)" },
        recommended = { "Weight-reducing clothing or a means to restore energy, due to the amount of running involved - Mint cakes are a cheap option, or the Endurance relic if you have 81 Archaeology.", "A good hatchet or pickaxe, to assist in gathering resources to gain approval from the population.", "Multiple Miscellania Teleports greatly reduces the walking times." },
        sections = {
            {
                title = "Starting out", needed = {},
                steps = {
                    {
                        text = "Talk to King Vargas, 2nd floor in the castle on the western island of Miscellania. You'll first need to open the throne room door and click through the dialogue with the guard.",
                        chat = "Accept",
                        npcs = { "King Vargas", "Miscellania" },
                    },
                },
            },
            {
                title = "Being the messenger", needed = { "1 iron bar, 1 logs" },
                steps = {
                    {
                        text = "Run to the eastern island. On the 2nd floor of the castle, talk to Queen Sigrid.",
                        npcs = { "Queen Sigrid" },
                    },
                    {
                        text = "Go back and talk to King Vargas.",
                        npcs = {},
                    },
                    {
                        text = "Go back and talk to Queen Sigrid.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Prince Brand in the bedroom south of King Vargas's room. He will give you an awful anthem.",
                        npcs = { "Prince Brand", "awful anthem" },
                    },
                    {
                        text = "Talk to Advisor Ghrim in King Vargas's room. He adjusts the anthem, and the awful anthem will convert into a good anthem.",
                        chat = "2 How do I make peace with Etceteria?",
                        npcs = { "Advisor Ghrim", "good anthem" },
                    },
                    {
                        text = "Take the good anthem to Queen Sigrid.",
                        npcs = {},
                    },
                    {
                        text = "Talk to King Vargas.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Derrik at the anvil on the north of the island, and give him an iron bar.",
                        chat = "2 I have a slightly strange request...",
                        npcs = { "Derrik" },
                    },
                    {
                        text = "Use the giant nib on your logs.",
                        npcs = { "giant nib" },
                    },
                    {
                        text = "Talk to King Vargas.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Advisor Ghrim about marriage.",
                        chat = "2 How am I supposed to get the Prince or Princess to marry me?",
                        npcs = {},
                    },
                },
            },
            {
                title = "Getting married", needed = { "The player must complete either of the following:" },
                steps = {
                },
            },
            {
                title = "To marry the princess", needed = { "1 flowers (can be bought from the Flower Girl for 15 coins), any bow (it will be lost during the quest), and any tradeable non-enchanted metal ring" },
                steps = {
                    {
                        text = "Go to the room to the north and talk to Princess Astrid.",
                        chat = "1 Yes.",
                        npcs = { "Princess Astrid" },
                    },
                    {
                        text = "Talk to Princess Astrid again, read carefully what she says. You must agree with her.",
                        npcs = {},
                    },
                    {
                        text = "Repeat this about 3 times until the chat options stop appearing.",
                        npcs = {},
                        subs = {
                            { text = "Hahahaha!" },
                            { text = "He's been very helpful." },
                            { text = "Archery is a noble art!" },
                        },
                    },
                    {
                        text = "Use the flowers on her.",
                        chat = "1 Yes",
                        npcs = {},
                    },
                    {
                        text = "Perform the Dance emote in her room.",
                        npcs = { "Dance" },
                    },
                    {
                        text = "Talk to Princess Astrid to tell her your name.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Princess Astrid again and agree with her again 3 times.",
                        npcs = {},
                        subs = {
                            { text = "What happened next?" },
                            { text = "That sounds like a good idea." },
                            { text = "I'm quite fond of it myself." },
                        },
                    },
                    {
                        text = "Give her a bow by using it on her.",
                        chat = "1 Yes",
                        npcs = {},
                    },
                    {
                        text = "Talk to Princess Astrid.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Princess Astrid again and agree with her again 3 times.",
                        npcs = {},
                        subs = {
                            { text = "I suppose you don't have much opportunity to." },
                            { text = "It's a lovely little country." },
                            { text = "And what a great bard he makes!" },
                        },
                    },
                    {
                        text = "Blow a kiss at Princess Astrid.",
                        npcs = { "Blow Kiss" },
                    },
                    {
                        text = "Use the ring on her.",
                        chat = "1 Yes",
                        npcs = {},
                    },
                    {
                        text = "Talk to King Vargas.",
                        npcs = {},
                    },
                },
            },
            {
                title = "To marry the prince", needed = { "1 flowers (can be bought from the Flower Girl for 15 coins), cake, any tradeable, non-enchanted metal ring" },
                steps = {
                    {
                        text = "Go to the room to the south and talk to Prince Brand.",
                        chat = "1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Prince Brand about 3 more times, trying to impress and/or agree with him.",
                        npcs = {},
                    },
                    {
                        text = "Use the clap or cheer emote.",
                        npcs = {},
                    },
                    {
                        text = "Use the flowers on him.",
                        chat = "1 Yes",
                        npcs = {},
                    },
                    {
                        text = "Talk to Prince Brand and agree with him again 3 times.",
                        npcs = {},
                    },
                    {
                        text = "Listen to his saga.",
                        npcs = {},
                    },
                    {
                        text = "Use the cake on him.",
                        chat = "1 Yes",
                        npcs = {},
                    },
                    {
                        text = "Talk to Prince Brand and agree with him again 3 times.",
                        npcs = {},
                    },
                    {
                        text = "When he calls you 'Dear', blow a kiss at him.",
                        npcs = {},
                    },
                    {
                        text = "Use the ring on Prince Brand.",
                        chat = "1 Yes",
                        npcs = {},
                    },
                    {
                        text = "Talk to King Vargas.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Helping the population", needed = {},
                steps = {
                    {
                        text = "Talk to Advisor Ghrim about support.",
                        chat = "2 How do I gain the support of the population?",
                        npcs = {},
                    },
                    {
                        text = "You need to make the population like you. You can check your approval percentage by talking to the people you're helping. To do this, perform any of the following tasks on the island:",
                        npcs = {},
                        subs = {
                            { text = "Raking weeds" },
                            { text = "Chopping trees (logs will not be obtained)" },
                            { text = "Mining coal (ore will not be obtained but it is the most AFK method here)" },
                            { text = "Fishing at the docks to the south (fish will not be obtained)" },
                            { text = "Purchase Flowers (mixed) from the Flower Girl (50% chance of +1% per flower)" },
                        },
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
