    {
        key = "toktz_ket_dill", name = "TokTz-Ket-Dill", wiki = "TokTz-Ket-Dill/Quick guide",
        required = { "Adamant pickaxe or better (tool belt will work for the mines, but will only work for the fight if you already have a melee weapon equipped. Otherwise, bring a separate pickaxe for the fight)", "14 oak planks", "A main-hand magic weapon and runes for water spells, or a necromancy weapon", "A ranged weapon (the final lava monster can only be damaged with ranged)", "A melee weapon (for faster breaking of the TokTz-Ket-Dill armour)", "A necromancy weapon can be used to kill the fire and lava monsters. Cannot use necromancy for the last lava monster and the TokTz-Ket-Dill", "17 stone slabs (obtained during quest)" },
        recommended = { "Food for the final fight (portent of restoration does not work)", "Varrock armour for mining the obsidian", "Transportation to Varrock for quick access to the Varrock Palace library", "TokKul-Zo for quick teleportation around TzHaar City", "There are several banks in the city, so you do not need to bring all the items in the backpack.", "A plank box can be used to carry the oak planks before being treated" },
        sections = {
            {
                title = "The TzHaar tourist guide", needed = { "2 empty inventory slots" },
                steps = {
                    {
                        text = "After entering the TzHaar City, go east as far as possible along the southern wall, then directly north (just west of Fight Cauldron teleport). Speak to one of the three guards.",
                        chat = "1 What has happened here? / Accept",
                        npcs = { "TzHaar City" },
                    },
                    {
                        text = "Talk to TzHaar-Ket-Grol south-west, at the crack in the wall (with at least one empty inventory slot).",
                        chat = "1 I was told to talk to you",
                        npcs = { "TzHaar-Ket-Grol" },
                    },
                    {
                        text = "Enter the tunnel to the library north-west of the Main Plaza.",
                        npcs = {},
                    },
                    {
                        text = "Speak to TzHaar-Mej-Lor.",
                        chat = "1 I need help with the TzHaar language.",
                        npcs = { "TzHaar-Mej-Lor" },
                    },
                    {
                        text = "Talk to Reldo in the Varrock library about TzHaar language.",
                        npcs = { "Reldo" },
                    },
                    {
                        text = "Along the west wall, in the cluster of 3 bookcases, search the middle one for the TzHaar Tourist Guide.",
                        npcs = { "TzHaar Tourist Guide" },
                    },
                    {
                        text = "Read the TzHaar Tourist Guide along with the note inside.",
                        npcs = {},
                    },
                    {
                        text = "Return to TzHaar-Ket-Grol.",
                        chat = "1 I know what to bring now. / 5 A pickaxe. / 5 Oak planks. / 4 Blocks of stone.",
                        npcs = {},
                    },
                    {
                        text = "Go east and pass the cave entrance.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The TzHaar theatre", needed = {},
                steps = {
                    {
                        text = "Enter the mine directly east and speak with TzHaar-Hur-Brekt on the east side, then talk again.",
                        chat = "2 Can you teach me magma mining? / 1 But it's very important! / 2 We should change the plot. / 3 The humans started it.",
                        npcs = {},
                    },
                    {
                        text = "Speak to TzHaar-Hur-Klag on the west wall.",
                        chat = "3 How can I make the story better? / 2 TzHaar who gets assaulted in its home is TzHaar-Hur. / 4 That was it.",
                        npcs = {},
                    },
                    {
                        text = "Speak to TzHaar-Mej-Kol, just north.",
                        chat = "3 How can I make the story better? / 2 One is a TzHaar-Mej who is aware of the situation. / 4 That was it.",
                        npcs = {},
                    },
                    {
                        text = "Speak to TzHaar-Xil-Mor, south-east in the mine.",
                        chat = "3 How can I make the story better? / 1 The criminal could be a TzHaar-Xil.",
                        npcs = {},
                    },
                    {
                        text = "Speak to TzHaar-Hur-Brekt.",
                        chat = "1 We should decide an ending. / 1 The criminal's plans are foiled.",
                        npcs = {},
                    },
                    {
                        text = "Speak to TzHaar-Xil-Mor.",
                        chat = "3 How can I make the story better? / 2 The plans aren't always foiled.",
                        npcs = {},
                    },
                    {
                        text = "Speak to TzHaar-Hur-Brekt.",
                        chat = "3 They are all happy with the plot.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The TzHaar plot", needed = {},
                steps = {
                    {
                        text = "Speak with TzHaar-Ket-Jok, south-west in the mine.",
                        chat = "1 You will play the role... / 3 ...JalYt-Jenny / 2 What do you think of your current role? / 3 We should modify your current role. / 2 No, we can't have that. / 4 That was it.",
                        npcs = { "TzHaar-Ket-Jok" },
                    },
                    {
                        text = "Speak with TzHaar-Xil-Mor.",
                        chat = "1 You will play the role... / 1 ...TokTz-Ket-Ek-Mack. / 2 What do you think of your current role? / 4 That was it.",
                        npcs = {},
                    },
                    {
                        text = "Speak with TzHaar-Hur-Klag.",
                        chat = "1 You will play the role... / 4 ...TzHaar-Hur. / 2 What do you think of your current role? / 3 We should modify your current role. / 1 Eh, I guess so. / 4 That was it.",
                        npcs = {},
                    },
                    {
                        text = "Speak with TzHaar-Mej-Kol.",
                        chat = "1 You will play the role... / 2 ...KetKul-Schmul. / 3 We should modify your current role. / 4 That was it.",
                        npcs = {},
                    },
                    {
                        text = "Finally speak to TzHaar-Hur-Brekt.",
                        chat = "2 Yes, all roles have been given out.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Obsidian pillars", needed = {},
                steps = {
                    {
                        text = "Mine the Stone slab vein and craft 4 pillars for the first cave section (you can easily return for more).",
                        npcs = { "Stone slab vein" },
                    },
                },
            },
            {
                title = "Treating the planks", needed = { "14 oak planks (bank at Fight Cauldron or the Main Plaza if needed, or store them in a plank box)" },
                steps = {
                    {
                        text = "Go to the quest start location and have your planks treated by the small TzHaar-Hur-Frok..",
                        chat = "1 Can you treat these oak planks for me? / 1 Here you go.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Repairing the tunnels", needed = { "Magic weapon with runes for water spells, ranged weapon with more distance than just darts, enough pillars and planks for a cave section (there are checkpoints.)" },
                steps = {
                    {
                        text = "Enter the crack in the south wall by TzHaar-Ket-Grol.",
                        npcs = {},
                    },
                    {
                        text = "If the examine info for a cave-in says \"The damage in this location is bad / isn't too badly damaged\", use a plank on it.",
                        npcs = {},
                    },
                    {
                        text = "If the examine info for a cave-in says \"The damage in this location is very bad/badly damaged/very badly damaged\", use a pillar on it. You cannot walk through these, and must place them from 1 tile away. Don't accidentally block yourself off with them, or you will need to push them over and get more pillars. If you run out of pillars, you can simply lobby and you'll end up outside of the cave, near the mine. You can then return to where you left off.",
                        npcs = {},
                    },
                    {
                        text = "Using the wrong item on a cave-in can cause a few hundred damage.",
                        npcs = {},
                    },
                    {
                        text = "The first cave requires 6 treated planks and 4 pillars. After fixing the cave-ins, mine the blocked tunnel and proceed to the next checkpoint.",
                        npcs = {},
                    },
                    {
                        text = "The second cave requires 6 treated planks and 6 pillars. The fire monster can only be harmed by magic with water spells or necromancy.",
                        npcs = {},
                    },
                    {
                        text = "The third cave requires 2 treated planks and 7 pillars. The first two lava monsters can only be harmed by ranged weapons with an attack range of 5 spaces or higher or by using necromancy. You will need to use magic with water spells or necromancy on the final fire monster. You cannot cross the stones before killing all three lava monsters.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Battling the TokTz-Ket-Dill", needed = { "Adamant pickaxe or better in your inventory or tool belt, full melee or hybrid armour" },
                steps = {
                    {
                        text = "Once you are ready to fight the TokTz-Ket-Dill, enter the tunnel to the north.",
                        chat = "1 Yes.",
                        npcs = { "TokTz-Ket-Dill (monster)" },
                        subs = {
                            { text = "If you die, your gravestone will appear in the chamber with the trapped TzHaar-Hurs, outside the tunnel to the TokTz-Ket-Dill." },
                        },
                    },
                    {
                        text = "Kill the TokTz-Ket-Dill by breaking its armour with a pickaxe equipped, then using only melee attack. Do not use prayers until the shell is broken.",
                        npcs = {},
                    },
                    {
                        text = "After killing the TokTz-Ket-Dill, exit to the north, head south out of the caves, and then talk to any of the three starting TzHaar to finish the quest.",
                        npcs = {},
                    },
                },
            },
        },
    },
