        recommended = { "Reducing ranged attacks from Thrower Trolls", "Level 47 Agility to traverse the shortcuts", "Level 40 Prayer for Protect from Ranged", "Fremennik round shield", "Good food", "Ranged/Magic/Necromancy equipment to safespot Dad" },
        sections = {
            {
                title = "Mountain climbing", needed = { "1 backpack space, climbing boots" },
                steps = {
