                        npcs = { "Freda" },
                    },
                    {
                        text = "Enter Sabbot's cave from Death Plateau and cross all the obstacles to reach the exit of the tunnel (recommended for low Defence and Constitution levels).",
                        npcs = { "Sabbot's cave", "Death Plateau (location)", "Tunnel (Death Plateau)", "Defence", "Constitution" },
                        subs = {
                            { text = "Alternatively, take the shortcut by running through the Death Plateau on the surface, clockwise around it, and climbing the rocks to the northwest, then climb the cliffside while wearing climbing boots. Beware of level 67 thrower trolls - Protect from Ranged, Dive, and Fremennik round shield are advised when taking this route." },
                        },
                    },
                    {
                        text = "Exit the cavern, climb the rocks to the immediate west of the exit and follow the path east over the rocks until you reach the arena entrance.",
