            {
                title = "Infiltrating the Infernal Source", needed = {},
                steps = {
                    {
                        text = "Talk to the four white knights at the Jolly Boar Inn.",
                        npcs = { "Jolly Boar Inn" },
                        tile = { x = 3281, y = 3497, plane = 0 },
                        subs = {
                            { text = "Sir Cull" },
                            { text = "Sir Berus" },
                            { text = "Sir Dated" },
                            { text = "Sir Plus" },
                        },
                    },
                    {
                        text = "Just west of the inn, descend the lift to enter the Infernal Source Dig Site.",
                        chat = "1 Yes.",
                        npcs = { "Infernal Source Dig Site" },
                    },
                    {
                        text = "Talk to Blythe.",
                        chat = "1 Growth through chaos. / 3 Philippa Wharton. / 2 Dagon.",
                        npcs = { "Blythe" },
                    },
                    {
                        text = "Wear the cultist attire and climb down the secret passage to the north.",
                        npcs = { "secret passage" },
