                    {
                        text = "Pickpocket cultists until you obtain a cast iron key (pickpocketing the same one works).",
                        npcs = { "cast iron key" },
                    },
                    {
                        text = "Collect information about the cult:",
                        npcs = {},
                        subs = {
                            { text = "Head north and talk to Wilona.", chat = "1 Yes. / 2 Domine fortis chaos / 2 In sanguine et in morte / 3 Honoramus tibi hoc sacrificium" },
                            { text = "Talk to Audrey (near the east pillar)." },
                            { text = "Talk to Ridley (in the east hallway)." },
                            { text = "Talk to Edda (in the southeast room)." },
                            { text = "Search the crate against the southern wall for spare cultist robes." },
                            { text = "Talk to Tyne in the jail cell west." },
