            {
                title = "Guardians of Guthix", needed = {},
                steps = {
                    {
                        text = "Return and talk to Saradomin.",
                        chat = "1 Yes.",
                        npcs = { "Saradomin" },
                        tile = { x = 3318, y = 3340, plane = 0 },
                    },
                    {
                        text = "Talk to Saradomin again.",
                        npcs = {},
                    },
                    {
                        text = "Talk to him a third time.",
                        chat = "Any / 1 Can you assault Zamorak directly? / 2 Can the summoning portal at the Infernal Source be disrupted? / 3 Why don't we just kill the attacking demons?",
                        npcs = {},
                        subs = {
                            { text = "After finishing the last dialogue, your quest journal should mention \"re-establishing the Edicts of Guthix\" as the current step." },
                        },
                    },
                    {
                        text = "Go downstairs and talk to Adrasteia in the room to the west.",
                        npcs = { "Adrasteia" },
                        subs = {
                            { text = "If she is not there, you may lobby and log back in." },
                        },
                    },
                    {
                        text = "Talk to the Tree of Balance south-west of the Archaeology Campus.",
                        chat = "1 Continue Twilight of the Gods.",
                        npcs = { "Tree of Balance", "Archaeology Campus" },
                    },
                    {
                        text = "Talk to any of the guardians of Guthix for a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Return and talk to Saradomin to obtain an.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Preparing for the spell", needed = {},
                steps = {
                    {
                        text = "Scan with the energy scanner, then go to the Memorial to Guthix",
                        npcs = { "energy scanner", "Memorial to Guthix" },
                        subs = {
                            { text = "You can teleport directly to the Memorial using either Sixth-Age circuit or by using memory strand from the currency pouch" },
                        },
                    },
                    {
                        text = "Stand in front of the pool and talk to the Archivist if he is visible near the pool.",
                        npcs = { "the Archivist" },
                    },
                    {
                        text = "Scan with the energy scanner, then go to the gleaming wisp divination site south-east of the Karamja lodestone and interact with the green mystical wisp.",
                        npcs = { "gleaming wisp", "Karamja lodestone", "mystical wisp" },
                        tile = { x = 2887, y = 3052, plane = 0 },
                        subs = {
                            { text = "You can use the elder divination outfit for a direct teleport to the gleaming wisp colony, or Karamja gloves 3 or higher to teleport nearby to the Shilo Village mine." },
                        },
                    },
                    {
                        text = "Talk to the confused automaton and complete all the dialogue.",
                        npcs = { "Confused automaton (Twilight of the Gods)" },
                    },
                    {
                        text = "Exit the cache and scan with the energy scanner, then talk to Merethiel at the Lost Grove.",
                        chat = "1 Yes / 1 Yes - please send me in.",
                        npcs = { "Merethiel", "the Lost Grove" },
                        subs = {
                            { text = "You can use the Boss portal to Solak, fairy ring BJS if repaired (Take 5 Bittercap mushroom to repair it if you have not) and then interact with the magical mushrooms, the elder divination outfit to the incandescent wisp colony, or BKP and then run west to the standstone to get to the Lost Grove." },
                        },
                    },
                    {
                        text = "Talk to the Guardians of Guthix once inside.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Isaura at the Black Knights' Base (northeastern corner of the base, next to the kitchen) in the Taverley Dungeon for a.",
                        chat = "1 Yes",
                        npcs = { "Isaura", "Black Knights' Base", "Taverley Dungeon" },
                        subs = {
                            { text = "You can quickly get to her using the Archaeology teleport or the master archaeologist's outfit teleport to Collectors, then Isaura. (→)" },
                        },
                    },
                },
            },
            {
                title = "Casting the spell", needed = {},
                steps = {
                    {
                        text = "Return to The Lost Grove, then talk to Merethiel.",
                        chat = "1 Yes / 1 Yes - please send me in.",
                        npcs = { "The Lost Grove", "Merethiel" },
                    },
                    {
                        text = "Speak to Juna once inside.",
                        npcs = { "Juna" },
                    },
                    {
                        text = "Place effigy on the stone circle in the middle of the arena.",
                        npcs = {},
                    },
                    {
                        text = "Harvest from the energy spring until you have 52 Guthixian energy.",
                        npcs = { "energy spring", "Guthixian energy" },
                    },
                    {
                        text = "Make all of the letters at the offering cradle (the large orb in the middle of the area).",
                        npcs = { "offering cradle" },
                    },
                    {
                        text = "Collect four stone circle building kits from the material cart slightly north-east of Juna and construct four empty stone circles starting from the west.",
                        npcs = { "stone circle building kit", "material cart", "Stone circle (Twilight of the Gods)" },
                    },
                    {
                        text = "The spelling of 3 words is required for each of the 3 rituals (9 total).",
                        npcs = {},
                        subs = {
                            { text = "For each ritual phase, the order of words is random per player." },
                            { text = "To spell words, add a rune (letter) on each of the stone circles you've just constructed." },
                            { text = "Words are spelled in clockwise orientation on the stone circles along the perimeter of the arena." },
                            { text = "To attempt the word you spelled, place effigy on stone circle, followed by \"start ritual\"." },
                            { text = "Each successful ritual phase will yield the chat message:" },
                        },
                    },
                },
            },
            {
                title = "Completing the rituals", needed = {},
                steps = {
                    {
                        text = "In the first ritual, the words are; in no certain order:",
                        npcs = {},
                        subs = {
                            { text = "H A L T" },
                            { text = "W A R D" },
                            { text = "G O D S" },
                        },
                    },
                    {
                        text = "Talk to Juna.",
                        npcs = { "Juna" },
                    },
                    {
                        text = "Collect from the material cart again and build the 5th stone circle.",
                        npcs = {},
                    },
                    {
                        text = "In the second ritual, the words are; in no certain order:",
                        npcs = {},
                        subs = {
                            { text = "L E A V E" },
                            { text = "A N I M A" },
                            { text = "A E G I S" },
                        },
                    },
                    {
                        text = "Talk to Juna.",
                        npcs = { "Juna" },
                    },
                    {
                        text = "Collect from the material cart again and build the 6th stone circle.",
                        npcs = {},
                    },
                    {
                        text = "In the third ritual, the words are; in no certain order:",
                        npcs = {},
                        subs = {
                            { text = "B A N I S H" },
                            { text = "S H I E L D" },
                            { text = "D I V I N E" },
                        },
                    },
                    {
                        text = "Talk to Juna.",
                        npcs = { "Juna" },
                    },
                    {
                        text = "Return to Saradomin's throne at the White Knights' Castle at Falador and speak to Adrasteia.",
                        chat = "1 Yes.",
                        npcs = { "Saradomin", "White Knights' Castle", "Falador", "Adrasteia" },
                    },
                    {
                        text = "Talk to Adrasteia again.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Finishing", needed = {},
                steps = {
                    {
                        text = "Go to the Empyrean Citadel (Adrasteia offers to teleport you).",
                        chat = "1 Yes please.",
                        npcs = { "Empyrean Citadel", "Adrasteia" },
                        subs = {
                            { text = "Alternatively use the invitation box.", chat = "1 Yes / 1 Yes" },
                        },
                    },
                    {
                        text = "Talk to the gods.",
                        npcs = {},
                    },
                    {
                        text = "Interact with the fake quest completion certificate and talk to the voices in your head.",
                        npcs = {},
                    },
                    {
                        text = "Quest Complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "underground_pass", name = "Underground Pass", wiki = "Underground Pass/Quick guide",
        required = { "A rope (2 recommended)", "A shortbow or longbow (chargebow will not work)", "A few of bronze, iron, steel, mithril, adamant, rune, dragon, or dark arrows (bring a few extras should you do so; no advantage in type)", "Bucket (obtainable during quest)", "Enough backpack space to hold all your armour and at least six spaces for the items that you receive during the quest" },
        recommended = { "Level 50 Agility", "Level 50 Thieving (otherwise, bring a little extra food to heal from the trap damage)", "Weapons. Ranged, magic or necromancy recommended, most enemies can be killed from safe spots. Using the bow is recommended if you need to save backpack space.", "Level 43 Prayer for Protect from Melee, or armour to reduce damage from the monsters. Minimising weight may be beneficial for some agility obstacles.", "Food to survive traps and monsters. Alternatively, Saradomin brews or super restores to reduce weight.", "Coins to buy food from Kamen (75 coins each time for food that heals a total of 1,325 life points).", "Agility potions, or summer pies, if you have a low Agility level", "Toadflax incense sticks may be used to considerably lower your chances of failing obstacles inside the dungeon regardless of Agility level", "An emergency teleport", "A plank (helps in avoiding damage; can be obtained during the quest)", "The catspeak amulet for amusing dialogue later in the quest", "Dave's spellbook with 'Chipped' Ardougne teleport to teleport to West Ardougne (requires the completion of Evil Dave's Big Day Out)" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Go to 2nd floor of Ardougne Castle in East Ardougne.",
                        npcs = { "Ardougne Castle", "East Ardougne" },
                    },
                    {
                        text = "Talk to King Lathas.",
                        chat = "Accept",
                        npcs = { "King Lathas" },
                    },
                },
            },
            {
                title = "Getting in and across the bridge", needed = { "a shortbow, some arrows, 1–2 ropes" },
                steps = {
                    {
                        text = "Talk to Koftik in the western most part of West Ardougne.",
                        chat = "1 I'll take my chances.",
                        npcs = { "Koftik", "West Ardougne" },
                    },
                    {
                        text = "Enter the cave entrance and go on either the north or south passages with rockslides to bypass the middle swamp.",
                        npcs = { "Cave entrance (Underground path)", "Rockslide (Underground path)", "Swamp (Underground path)" },
                    },
                    {
                        text = "Talk to Koftik for a damp cloth. Use it on an arrow and then light the arrow.",
                        npcs = { "damp cloth" },
                    },
                    {
                        text = "Make sure you are standing around the bend to the north. Equip your bow and the lit arrow. Fire at the guide rope attached to the bridge.",
                        npcs = { "guide rope", "Bridge (Underground path)" },
                    },
                    {
                        text = "You may pick up the plank for passing through some traps further in the cave. It is located just after the bridge to the north. Only one is needed.",
                        npcs = { "plank" },
                    },
                    {
                        text = "Continue through the cave to the south-east until you reach a gap north of the rope swing.",
                        npcs = { "Rope swing (Underground Pass)" },
                    },
                    {
                        text = "Use a rope on the old spike near the northern edge of the gap on your side.",
                        npcs = { "old spike" },
                        subs = {
                            { text = "You may need to hover at the tip of the spike as its hitbox is so small. Be sure to select your rope first, then use it on the space adjacent to the northern edge. You will lose your rope in the process." },
                            { text = "If you fail the obstacle, you can climb out of the pit via the pile of rocks on the north western wall past some rockslides." },
                        },
                    },
                    {
                        text = "Continue through the cave over the two rockslides until you reach a large grid (5x5) next to Koftik.",
                        npcs = { "Koftik" },
                    },
                },
            },
            {
                title = "Grid puzzle", needed = {},
                steps = {
                    {
                        text = "Find your path across the grid. Keep a record of the path over the grid for Regicide quest. You will fall through some of the tiles.",
                        npcs = { "Regicide/Quick guide" },
                        subs = {
                            { text = "You can use the table below to save your path: click a cell to highlight it, and click again to de-highlight it (your browser will remember the path saved in the table as long as you don't clean browser cache for the wiki)." },
                        },
                    },
                    {
                        text = "Pull the lever to the south at the end to continue.",
                        npcs = { "Lever (Underground path, portcullis)" },
                    },
                },
            },
            {
                title = "Lights in the night", needed = { "4 free backpack space" },
                steps = {
                    {
                        text = "Run past the zombie camp, there will be odd markings along the walls of the corridor. These are traps. Search these walls to disarm them.",
                        npcs = { "Odd markings (Underground path)" },
                        subs = {
                            { text = "You can skip disarming by standing right next to the trapped tile and then running to the other side of the tile. This can also be done on the next step." },
                            { text = "You can also simply run past the traps, take damage, and then eat to replenish the lost life points." },
                        },
                    },
                    {
                        text = "You will reach a chaos altar, take the north path using a plank on the flat rocks. Take the orb of light. Return back to the altar.",
                        npcs = { "Chaos altar (Prayer)", "Flat rock (Underground path, stalagmites)", "orb of light" },
                    },
                    {
                        text = "Take the north-west path towards the ogres. Take the orb. Return back to the altar.",
                        npcs = { "Ogre" },
                    },
                    {
                        text = "Take the middle west path, traversing the flat rocks as before using the plank. Take the orb.",
                        npcs = {},
                    },
                    {
                        text = "Take the final path and do not pick up the orb right away. Search the flat rock underneath the orb to disarm the trap first and then take the orb. If successful your character will automatically pick up the orb. If not, continue trying to search the rock.",
                        npcs = { "Flat rock (Underground path, hanging log)" },
                    },
                    {
                        text = "Return to the zombie camp (don't forget about disarming the traps).",
                        npcs = {},
                    },
                    {
                        text = "Use the 4 orbs on the furnace.",
                        npcs = { "Furnace (Underground path)" },
                    },
                    {
                        text = "Return to the altar (again, don't forget about the traps).",
                        npcs = {},
                    },
                    {
                        text = "Climb down the well. You can search the two stacked crates for 2 salmon and 2 meat pies.",
                        npcs = { "Crate (Underground Pass)", "salmon", "meat pie" },
                    },
                    {
                        text = "Follow the path until you reach the cages.",
                        npcs = { "Cage (Underground path, slave)" },
                    },
                    {
                        text = "Pick the lock and dig the mud in the south-easternmost cell.",
                        npcs = { "Mud (Underground path)" },
                    },
                    {
                        text = "Walk west and cross the ledge.",
                        npcs = { "Ledge (Underground path)" },
                    },
                    {
                        text = "Reaching the eastern side of the wooden bridge maze.",
                        npcs = { "wooden bridge" },
                        subs = {
                            { text = "If you have level 50 Thieving, you can bypass the wooden bridge maze:" },
                            { text = "Enter the room to the south" },
                            { text = "Pick-lock on the cage" },
                            { text = "Head east and avoid the bubbles. If you step on a bubble, you will have to start from the beginning, without a rope. Avoid standing in the same place for too long, as this can also set you back." },
                            { text = "If you lack level 50 Thieving, cross the wooden bridge maze to get to the other side. If you fall, try again." },
                            { text = "At the first intersection, go south" },
                            { text = "At the second intersection, go north" },
                            { text = "At the third intersection, go north" },
                        },
                    },
                    {
                        text = "Head south and enter the obstacle pipe.",
                        npcs = { "Obstacle pipe (Underground path, two-way)" },
                    },
                },
            },
            {
                title = "Cold blooded killing", needed = {},
                steps = {
                    {
                        text = "Search the unicorn cage to find a piece of railing.",
                        npcs = { "Cage (Underground Pass, unicorn)", "piece of railing" },
                    },
                    {
                        text = "Use the railing on the boulder south of the unicorn.",
                        npcs = { "Boulder (Underground Pass)" },
                    },
                    {
                        text = "Search the smashed cage to get a unicorn horn.",
                        npcs = { "smashed cage", "unicorn horn (Underground Pass)" },
                        subs = {
                            { text = "The piece of railing can be dropped." },
                        },
                    },
                    {
                        text = "Pass through the tunnel north of the cage, until you reach 3 paladins.",
                        npcs = {},
                        subs = {
                            { text = "If you are low on health, talk to Sir Jerro for some free food and potions. You will need 7 backpack space." },
                        },
                    },
                    {
                        text = "Kill them and take their badges. Requires 3 backpack space.",
                        npcs = { "Paladin's badge" },
                    },
                    {
                        text = "Continue forward, using your plank on the flat rocks, until you see a well.",
                        npcs = { "Well (Underground path, door)" },
                    },
                    {
                        text = "Use the badges and unicorn horn on the well.",
                        npcs = {},
                    },
                    {
                        text = "Open the door.",
                        npcs = { "Door (Underground path)" },
                    },
                },
            },
            {
                title = "Meeting the dwarves", needed = { "6 free backpack space" },
                steps = {
                    {
                        text = "Reach the dwarf camp in the cavern below by following one of the below methods.",
                        npcs = {},
                        subs = {
                            { text = "Head south along the wall to the south-east corner then head west along the south wall to find the cave stairs there. Take the stairs down." },
                            { text = "There are also stairs in the north-west corner that may be easier to find but will require players to make their way through the herd of hostile soulless in the centre of the cavern below on the way to the dwarf camp." },
                            { text = "Fail a bridge jump." },
                        },
                    },
                    {
                        text = "Koftik will appear with some brief dialogue.",
                        npcs = {},
                    },
                    {
                        text = "After the dialogue is finished, go to the dwarf camp in the cavern's south-western corner.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Niloof the dwarf.",
                        npcs = { "Niloof" },
                    },
                    {
                        text = "Go back up the stairs to the east.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Black cat in the dark", needed = {},
                steps = {
                    {
                        text = "Head to the central part of the map by crossing the wooden bridges to pick up the witch's cat, the cat should be wandering out on the bridges and platforms north-west of her house (marked by a yellow dot on the minimap). The witch's house is the most south-eastern platform.",
                        npcs = { "Bridge (Iban's lair)", "witch's cat" },
                    },
                    {
                        text = "Use the cat on the door to the witch's house.",
                        npcs = { "Door (Kardia's house)" },
                    },
                    {
                        text = "Open the door to the house.",
                        npcs = {},
                    },
                    {
                        text = "Search the chest in her house for a few items and the History of Iban book.",
                        npcs = { "Chest (Iban's lair, doll)", "History of Iban" },
                        subs = {
                            { text = "Click the chest once to trigger a dialogue. Prematurely ending the dialogue will require you to wait for the chest to close, or logout." },
                            { text = "The History of Iban can be dropped." },
                        },
                    },
                },
            },
            {
                title = "Ashes to ashes", needed = {},
                steps = {
                    {
                        text = "Kill Doomion, Othainian, and Holthion west of the witch and take their amulets.",
                        npcs = { "Doomion", "Othainian", "Holthion" },
                    },
                    {
                        text = "Open and search the chest north of the middle demon.",
                        npcs = { "Chest (Iban's lair, shadow)" },
                    },
                    {
                        text = "Pour Iban's shadow on the doll of Iban.",
                        npcs = { "Iban's shadow", "doll of Iban" },
                    },
                    {
                        text = "Return downstairs and talk to Klank the dwarf, taking his gauntlets.",
                        npcs = { "Klank", "Klank's gauntlets" },
                    },
                    {
                        text = "Take the bucket in the large house. Use it on the barrel in the smaller house to receive a dwarf brew.",
                        npcs = { "bucket", "Barrel (Underground Pass)", "dwarf brew" },
                    },
                    {
                        text = "Run east to a tomb in the south-east corner of the cave",
                        npcs = { "Tomb (Beneath Iban's lair)" },
                    },
                    {
                        text = "Use the dwarf brew on the tomb.",
                        npcs = {},
                        subs = {
                            { text = "You will not need a bucket for the rest of the quest." },
                        },
                    },
                    {
                        text = "Light the tomb to obtain Iban's ashes.",
                        npcs = { "Iban's ashes" },
                    },
                    {
                        text = "Use Iban's ashes on the doll of Iban.",
                        npcs = {},
                    },
                    {
                        text = "Run to the furthest north-east corner, kill Kalrag the spider.",
                        npcs = { "Kalrag" },
                        subs = {
                            { text = "*IMPORTANT* Upon killing Kalrag, the blessed spiders will begin attacking with range, so quickly enable Deflect/Protect from Ranged and run away from the spiders." },
                        },
                    },
                },
            },
            {
                title = "Caging his dove", needed = {},
                steps = {
                    {
                        text = "Go to the north-western corner and ascend the stairs to the half-soulless area.",
                        npcs = { "half-soulless" },
                        tile = { x = 2134, y = 4702, plane = 0 },
                    },
                    {
                        text = "Walk south to the third walkway and cross the bridge.",
                        npcs = {},
                    },
                    {
                        text = "Walk north to the first cage, then walk east to the next cage.",
                        npcs = {},
                    },
                    {
                        text = "Walk a little north then west from here to the cage containing Iban's dove (lowest platform in the centre of several others).",
                        npcs = {},
                    },
                    {
                        text = "Equip Klank's gauntlets to prevent taking damage.",
                        npcs = { "Klank's gauntlets" },
                    },
                    {
                        text = "Search the cage to find Iban's dove.",
                        npcs = { "Iban's dove" },
                    },
                    {
                        text = "Use the Iban's dove on the doll of Iban.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Ultimate demise", needed = { "enough backpack space to unequip the gear and 3 extra spaces" },
                steps = {
                    {
                        text = "Head back towards the most recent bridge you crossed BUT...",
                        npcs = {},
                    },
                    {
                        text = "Instead, follow the bridge to east, then south-east towards the Disciple of Iban.",
                        npcs = { "Disciple of Iban" },
                    },
                    {
                        text = "Kill a Disciple of Iban, grab both the Zamorak robe top and Zamorak robe bottom.",
                        npcs = { "Zamorak robe (top)", "Zamorak robe (bottom)" },
                    },
                    {
                        text = "Un-equip everything and equip the robes. You don't need planks or rope anymore.",
                        npcs = {},
                        subs = {
                            { text = "If you don't have 3 free backpack spaces you will miss out on 15 death runes and 30 fire runes because you will instantly be teleported away after Iban is destroyed." },
                        },
                    },
