                            { text = "Leave the island and head to south-east to the passage between Gu'Tanoth and the island south of Yanille, then head to south-west to the cave entrance." },
                            { text = "You can use fairy ring AKS and head north-west to reach there." },
                            { text = "If A Fairy Tale III - Battle at Ork's Rift is completed, you can use fairy ring ALP, head north to exit the tunnel, and head south-east for quicker access." },
                            { text = "If The Grand Tree quest is completed and partially completed the quest One Small Favour, you can use gnome glider to fly to the Feldip Hills and head north-west for quicker access.", chat = "6 Lemantolly Undri" },
                        },
                    },
                    {
                        text = "Enter the cave entrance.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Toban twice, he will take the dragon bones and give you relic part 3.",
                        chat = "1 I seek entrance to the city of ogres. / 1 I could do something for you…",
                        npcs = { "Toban", "relic part 3" },
                        subs = {
                            { text = "If you didn't bring a second rope, take one now from the island." },
                        },
                    },
                    {
                        text = "Talk to Gorad and tell him that you have come to knock out his teeth",
                        npcs = { "Gorad" },
                        subs = {
                            { text = "Kill Gorad and take the ogre tooth." },
                        },
                    },
                    {
                        text = "Open the Chest and take the gold.",
                        npcs = { "toban's gold" },
                    },
                    {
                        text = "Go back and talk to Grew, giving him the tooth and consuming the second rope.",
                        npcs = {},
                    },
                    {
                        text = "If you didn't get the yellow crystal, talk to Grew again and ask for it.",
                        npcs = { "crystal (yellow)" },
                    },
                    {
                        text = "Talk to Og, north of Grew's island to receive the relic part 1.",
                        npcs = { "relic part 1" },
                    },
                },
            },
            {
                title = "Gu'Tanoth", needed = { "light source, 20 coins, ogre relic, death rune" },
                steps = {
                    {
                        text = "Talk to the Watchtower Wizard until you receive an Ogre relic (there is a break in the conversation).",
                        npcs = {},
                        subs = {
                            { text = "If you didn't bring a light source, take the lit candle from the 1st floor of Watchtower." },
                        },
                    },
                    {
                        text = "Enter Gu'Tanoth from the north-eastern corner and go west along the northern path.",
                        npcs = {},
                    },
                    {
                        text = "Use the Ogre relic on one of the guards at the west gate. Do not talk to them or you will be hit for some damage and sent back near Copernicus.",
                        npcs = {},
                    },
                    {
                        text = "Head south-east to the Ogre trader marked with on the map but don't talk to him.",
                        npcs = { "Ogre trader" },
                    },
                    {
                        text = "Steal a rock cake from the counter.",
                        npcs = { "rock cake" },
                    },
                    {
                        text = "Return to the path and continue south.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the guards, then give (but do not eat) a rock cake to be able to climb over the battlement.",
                        chat = "1 But I am a friend to ogres...",
                        npcs = {},
                    },
                    {
                        text = "Continue up the path and jump over the gap, paying 20 coins to the guards.",
                        chat = "1 Okay, I'll pay it.",
                        npcs = {},
                    },
                    {
                        text = "Talk to one of the City guard. Make sure to use the \"Talk-to\" option on the guard., then talk to them again and give them a death rune.",
                        chat = "2 I seek passage into the skavid caves.",
                        npcs = { "City guard" },
                    },
                },
            },
            {
                title = "The skavids", needed = { "Skavid map, gold bar, light source, armoured gloves" },
                steps = {
