                        npcs = {},
                        subs = {
                            { text = "Talk to the skavid (respond with \"Ig\")." },
                            { text = "While in this cave, pick two cave nightshades." },
                            { text = "Attempting to pick a cave nightshade without gloves results in a dialogue \"You have been poisoned by the plant!\", causing minor damage." },
                            { text = "Attempting to pick a cave nightshade with regular, non-armoured gloves results in the same dialogue as above and another suggesting to wear armoured gloves." },
