                    {
                        text = "Enter the north cave, marked 2.",
                        npcs = {},
                        subs = {
                            { text = "Talk to the skavid (respond with \"Ar\")." },
                        },
                    },
                    {
                        text = "Enter the northeast cave, marked 3.",
                        npcs = {},
                        subs = {
                            { text = "Talk to the skavid (respond with \"Cur\")." },
                        },
                    },
                    {
                        text = "Enter the east cave, marked 5.",
                        npcs = {},
                        subs = {
                            { text = "Talk to the skavid (respond with \"Nod\")." },
                        },
                    },
                    {
                        text = "Return to the east cave, marked 4.",
                        npcs = {},
                        subs = {
                            { text = "Talk to the Scared skavid." },
                        },
                    },
                    {
                        text = "Go to a gate south of the 4 cave entrance.",
                        npcs = {},
                    },
                    {
                        text = "Talk to one of the ogre guards and he will take the gold bar and let you in.",
                        npcs = {},
                    },
                    {
                        text = "Enter the south cave, marked 6.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the Mad skavid to obtain the pink crystal.",
                        npcs = {},
                        subs = {
                            { text = "If he says \"Ar cur,\" the correct response is \"Gor.\"" },
                            { text = "If he says \"Bidith ig,\" the correct response is \"Cur.\"" },
                            { text = "If he says \"Gor nod,\" the correct response is \"Tanath.\"" },
                            { text = "If he says \"Cur tanath,\" the correct response is \"Bidith.\"" },
