    {
        key = "waterfall_quest", name = "Waterfall Quest", wiki = "Waterfall Quest/Quick guide",
        required = { "6 air runes", "6 earth runes", "6 water runes", "1 rope (can be obtained during the quest if you've created a rope rack, which requires 24 Construction, 5 coils of rope, and 3 oak planks, by the quest's start point)" },
        recommended = { "Games necklace is very useful for its teleport to Barbarian Outpost", "Ardougne Teleport (if Plague City completed) or access to Ardougne or Yanille lodestone for convenience.", "Completion of Tree Gnome Village to access the Spirit tree network and reach Gnome Village faster." },
        sections = {
            {
                title = "The Treasure", needed = {},
                steps = {
                    {
                        text = "Talk to Almera inside her house, south of the Barbarian Outpost.",
                        chat = "Accept",
                        npcs = { "Almera", "Barbarian Outpost" },
                    },
                    {
                        text = "Board the raft to the west.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Hudon north of where you land.",
                        npcs = { "Hudon" },
                        subs = {
                            { text = "If you do not talk to Hudon you will not be able to find the Book on Baxtorian in the later step." },
                        },
                    },
                    {
                        text = "Click swim on the river to the south to end up back on shore.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Glarial's Pebble", needed = {},
                steps = {
                    {
                        text = "Once back on shore, head into the house to your north-west right next to where you arrived on shore and climb either the inside staircase, or the outside staircase on the south side of the larger building.",
                        npcs = {},
                    },
                    {
                        text = "Search the southern bookcase on the east wall to find the Book on Baxtorian.",
                        npcs = { "Book on Baxtorian" },
                    },
                    {
                        text = "Read the book.",
                        npcs = {},
                    },
                    {
                        text = "Head to the Tree Gnome Village, located north-west of Yanille.",
                        npcs = { "Tree Gnome Village (location)", "Yanille" },
                    },
                    {
                        text = "Once there, follow the path through the maze, heading towards the dungeon",
                        npcs = {},
                        subs = {
                            { text = "If the quest Tree Gnome Village is at least partially completed, follow Elkoy, who is at the beginning and end of the maze." },
                            { text = "If the quest is not partially completed, it is recommended to squeeze through the loose railing and speak to King Bolren while nearby." },
                            { text = "Go east and enter the dungeon." },
                        },
                    },
                    {
                        text = "Inside the dungeon, go to the eastern room.",
                        npcs = {},
                    },
                    {
                        text = "Search the south-east stack of crates which is a different colour than the others, to find a key (must read book in order to find key).",
                        npcs = { "A key (Waterfall Dungeon)" },
                    },
                    {
                        text = "Head to the westernmost room and use the key on the gate to unlock it.",
                        npcs = {},
                    },
                    {
                        text = "Enter and speak to Golrie to find Glarial's pebble.",
                        npcs = { "Golrie", "Glarial's pebble" },
                    },
                },
            },
            {
                title = "Tomb Raiding", needed = {},
                steps = {
                    {
                        text = "Bank everything except Glarial's pebble and your rope (you may bring food and allowed items).",
                        npcs = { "Glarial's Tomb" },
                        subs = {
                            { text = "To enter the tomb, you cannot bring combat-related items such as weapons, armour, or runes." },
                            { text = "You may drop 6 air runes, 6 water runes and 6 earth runes outside the tomb and retrieve them upon exiting, in order to skip banking for the final part." },
                        },
                    },
                    {
                        text = "Teleport to Ardougne lodestone and go north-west of the Fishing Guild to find Glarial's tombstone.",
                        npcs = { "Fishing Guild", "Glarial's tombstone" },
                    },
                    {
                        text = "Use Glarial's pebble on the tombstone.",
                        npcs = { "Glarial's pebble" },
                        subs = {
                            { text = "If it says, it's because you are wearing disallowed items or carrying runes" },
                        },
                    },
                    {
                        text = "Go west and search the chest to obtain Glarial's amulet.",
                        npcs = { "Glarial's amulet" },
                        subs = {
                            { text = "Optional: Drop the amulet and search the chest for a second one, preventing having to obtain a second one after the quest for dungeon access." },
                        },
                    },
                    {
                        text = "Go south and search Glarial's Tomb to obtain Glarial's urn.",
                        npcs = { "Glarial's Tomb", "Glarial's urn" },
                    },
                    {
                        text = "Head north-east back up the ladder you came down.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Baxtorian Treasures", needed = { "6 air runes, 6 water runes, 6 earth runes, a rope, Glarial's urn, and Glarial's amulet." },
                steps = {
                    {
                        text = "Go north-west to the quest start point (Almera's house) and board the raft once more.",
                        npcs = {},
                    },
                    {
                        text = "Use your rope on the rock situated on the bank to the south (do not click 'swim to rock').",
                        npcs = {},
                    },
                    {
                        text = "Use your rope on the dead tree next to you (do not click 'climb tree').",
                        npcs = {},
                    },
                    {
                        text = "With Glarial's amulet in your inventory, enter the cave door north.",
                        npcs = {},
                    },
                    {
                        text = "Go north-east, open the door, and search the light-colored crates on the northern wall for another key.",
                        npcs = {},
                    },
                    {
                        text = "Return to the centre room and go down the western passage, past the fire giants, through the doors north.",
                        npcs = {},
                    },
                    {
                        text = "Use the key on the last door.",
                        npcs = {},
                    },
                    {
                        text = "Make sure you follow these three steps carefully or you will be washed up down stream.",
                        npcs = {},
                        subs = {
                            { text = "Use an air rune, a water rune, and an earth rune on each of the six pillars." },
                            { text = "Use Glarial's amulet on the statue of Glarial, the western statue." },
                            { text = "Use Glarial's urn on the Chalice of Eternity, in the centre of the room." },
                            { text = "If you attempt to take the Chalice you will be washed up down stream and will have to get the amulet back from the chest under Glarial's tombstone before being able to return to the cave." },
                        },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "what_lies_below", name = "What Lies Below", wiki = "What Lies Below/Quick guide",
        required = { "Bowl", "15 chaos runes or 15 pure essence (unnoted, so it's recommended to bring the stackable chaos runes, or store the essence in some pouches)", "Access to the chaos altar (requiring any item that acts as the chaos talisman, for example a wicked hood having consumed the talisman, or travelling through the Abyss)" },
        recommended = { "Level 42 Mining and Enter the Abyss (miniquest) (only if you use the Tunnel of Chaos to get to the chaos altar)", "Varrock Teleports would be useful. Teleport tablets may also be used.", "Varrock lodestone is very useful as it is just north of Rat Burgiss." },
        sections = {
            {
                title = "Starting out", needed = {},
                steps = {
                    {
                        text = "Talk to Rat Burgiss, south-east of the Varrock lodestone by the crossroads to Lumbridge.",
                        chat = "2 Hello there! / 3 Shall I get them back for you? / Accept",
                        npcs = { "Rat Burgiss", "Varrock", "Lumbridge" },
                    },
                },
            },
            {
                title = "Helping Rat", needed = {},
                steps = {
                    {
                        text = "Immediately west of the Grand Exchange is a camp. Kill 5 outlaws there.",
                        npcs = { "Grand Exchange", "outlaws" },
                    },
                    {
                        text = "Take all 5 Rat's papers that they drop.",
                        npcs = { "Rat's paper" },
                    },
                    {
                        text = "Use the 5 papers on an empty folder.",
                        npcs = { "an empty folder" },
                    },
                    {
                        text = "Talk to Rat Burgiss.",
                        chat = "2 Hello there!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Surok Magis", needed = { "Bowl, 15 chaos runes or pure essence to craft them, at least 1 empty inventory slot (2 recommended)" },
                steps = {
                    {
                        text = "Go to the Varrock palace library, and talk to Surok Magis in the most northern room.",
                        chat = "1 Go on, then!",
                        npcs = { "Surok Magis" },
                        subs = {
                            { text = "Optional: search the bookcase south of the telescope in the north-east section of the room for the Dagon'hai History; it can be turned in to Historian Minas after the quest for 5 kudos." },
                        },
                    },
                    {
                        text = "Use any method to enter the chaos altar.",
                        npcs = { "chaos altar" },
                    },
                    {
                        text = "With 15 chaos runes, use the wand on the altar.",
                        npcs = {},
                        subs = {
                            { text = "If you brought essence instead, craft the runes now." },
                        },
                    },
                    {
                        text = "Give Surok Magis a bowl and the infused wand.",
                        chat = "1 I have the things you wanted!",
                        npcs = { "Surok Magis" },
                    },
                    {
                        text = "Talk to Rat Burgiss.",
                        chat = "2 Hello there! / 1 Yes! I have a letter for you.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Zaff, in his shop north-west of Varrock Square.",
                        chat = "4 Rat Burgiss sent me.",
                        npcs = { "Zaff" },
                    },
                    {
                        text = "Talk to Surok Magis.",
                        chat = "1 Bring it on!",
                        npcs = {},
                    },
                    {
                        text = "Attack King Roald, and right-click summon with the beacon ring when he has 1 life point remaining.",
                        npcs = { "King Roald", "beacon ring" },
                    },
                },
            },
            {
                title = "Finishing up", needed = {},
                steps = {
                    {
                        text = "After the cutscene, return to Rat Burgiss.",
                        chat = "2 Hello there!",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "what_s_mine_is_yours", name = "What's Mine is Yours", wiki = "What's Mine is Yours/Quick guide",
        required = {},
        recommended = { "Activated Falador, Port Sarim, and Varrock lodestones", "A weapon and armour for low-level players" },
        sections = {
            {
                title = "Getting started", needed = { "3 backpack space" },
                steps = {
                    {
                        text = "Talk to Doric in his hut, north of the Falador lodestone, until you get an ore bag and mining sites map.",
                        chat = "1 Don't worry, I'll help you. / Accept",
                        npcs = { "Doric", "Doric's hut", "Falador lodestone", "ore bag", "mining sites map" },
                        tile = { x = 2959, y = 3439, plane = 0 },
                    },
                    {
                        text = "Mine any rock in each of the following locations until a living rock brawler appears, kill it, and take the ore it drops:",
                        npcs = { "living rock brawler" },
                        subs = {
                            { text = "Dwarven mines, to the east up the hill" },
                            { text = "Rimmington mine, west of Port Sarim" },
                            { text = "Watch the cutscene." },
                            { text = "Varrock south-west mine" },
                            { text = "Varrock south-east mine" },
                        },
                    },
                    {
                        text = "Talk to Doric.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The weapons", needed = { "2 backpack space" },
                steps = {
                    {
                        text = "Withdraw the ores from the ore bag.",
                        chat = "1 Ore.",
                        npcs = { "ore bag" },
                    },
                    {
                        text = "Smelt two high-quality bronze bars using the furnace.",
                        chat = "1 Yes",
                        npcs = { "high-quality bronze bar" },
                    },
                    {
                        text = "Smith a high-quality bronze sword and a high-quality bronze dagger on Doric's anvil.",
                        npcs = { "high-quality bronze sword", "high-quality bronze dagger", "Anvil (Doric's hut)" },
                    },
                    {
                        text = "Talk to Doric.",
                        chat = "3 I'll leave right away.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Aksel in the Artisans' Workshop in south-east Falador.",
                        chat = "1 Doric sent me here with these weapons.",
                        npcs = { "Aksel", "Artisans' Workshop", "Falador" },
                    },
                },
            },
            {
                title = "Doric and Boric", needed = { "3 backpack space" },
                steps = {
                    {
                        text = "Head to the White Knights' Castle and talk to Squire Cerlyn in the west tower on the 1st floor.",
                        npcs = { "White Knights' Castle", "Squire Cerlyn" },
                    },
                    {
                        text = "After the cutscene, help Doric and Boric reconcile. Use the following responses:",
                        npcs = { "Boric" },
                        subs = {
                            { text = "Boric, tell Doric about your graduation." },
                            { text = "Boric, tell Doric what you thought when Doric sent you away." },
                            { text = "Boric, tell Doric about your education." },
                            { text = "Boric, tell Doric why you wanted to stay here." },
                            { text = "Boric, tell Doric what you thought of Keldagrim" },
                            { text = "Doric, tell Boric what you thought when Boric was born." },
                            { text = "Doric, tell Boric why you sent him to Keldagrim." },
                            { text = "Doric, tell Boric how you felt bringing Boric up alone." },
                            { text = "Doric, tell Boric what you want Boric's future to be." },
                            { text = "Doric, tell Boric what you hoped sending him away would teach him." },
                        },
                    },
                    {
                        text = "Talk to Doric and agree to take the bars.",
                        chat = "1 I'd love to. / 1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Smith the items that were asked for on Doric's anvil.",
                        npcs = {},
                        subs = {
                            { text = "Ornamental platebody" },
                            { text = "Ornamental chainbody" },
                            { text = "Shop sign" },
                        },
                    },
                    {
                        text = "Head down the stairs into Doric's cave (if the \"climb down\" option on the northern doorway does not appear, try switching textures off temporarily, this is a known bug).",
                        npcs = { "Doric's cave" },
                    },
                    {
                        text = "Mine the rocks blocking the way.",
                        npcs = {},
                    },
                    {
                        text = "Head back upstairs and talk to Doric to give him the items and trigger a cutscene.",
                        chat = "1 Yes, I have them here.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "while_guthix_sleeps", name = "While Guthix Sleeps", wiki = "While Guthix Sleeps/Quick guide",
        required = { "A lit sapphire lantern", "Three air runes, an earth rune, a fire rune, a water rune, a mind rune, a law rune, and a death rune", "Any logs (except acadia or eternal magic)", "A charcoal and a papyrus (both may easily be obtained during the quest)", "Lantern lens", "Mort myre fungus (can be obtained during the quest)", "Unpowered orb", "Ring of charos (a)", "or 5,000 coins", "Equipment to enter the Black Knights' Fortress", "Runes to cast the NPC Contact spell four times (8 air runes, 4 astral runes, and 4 cosmic runes)", "Runes for any charge orb spell (30 runes of a chosen element and three cosmic runes)", "Equipment for two different attack styles or Necromancy equipment", "Either a snapdragon seed or 100 coins to buy one from Thaerisk" },
        recommended = { "Completion of Nature Spirit for access to druid pouch or ouroboros pouch; alternatively, bring the #Required ingredients for the statue|required ingredients for the statue", "Activated Burthorpe, Canifis, Edgeville, Falador, Karamja, Oo'glog, Port Sarim, Seers' Village, Taverley, Varrock, Ardougne and Yanille lodestone", "A dramen or lunar staff, unless you have completed A Fairy Tale III - Battle at Ork's Rift", "And/or Portable fairy ring", "A cape of legends for instant teleport to the Legends' Guild", "Multiple Falador teletabs or ring of respawn for continual return to Falador", "Games necklace", "Ardougne Teleport or Ardougne cloak", "Watchtower Teleport", "Runes to cast the NPC Contact spell three additional times (6 air runes, 3 astral runes, and 3 cosmic runes)", "Some super energy potions", "A set of elite black armour or Black Knight captain's armour to save time", "Otherwise, obtainable during the quest requiring you to kill guards until you collect each piece", "Black Knight captain's armour is obtained early into the The Death of Chivalry quest by searching a suit of armour shortly after accepting the quest (a cosmetic override of the armour can be unlocked using the Skull of Remembrance after the quest)", "Ring of life", "Ingredients for a Guthix balance potion (clean harralander, red spiders' eggs, garlic, and silver dust) may be needed for the statue." },
        sections = {
            {
                title = "Starting out", needed = { "Varrock teleport, any boosts you wish to use to start the quest, and equipment to kill two Assassins" },
                steps = {
                    {
                        text = "Talk to Radimus Erkle in the Legends' Guild (fairy ring BLR).",
                        chat = "4 Yes, I'm interested, where do I report? / Accept",
                        npcs = { "Radimus Erkle", "Legends' Guild" },
                    },
                    {
                        text = "In Taverley, talk to Ivy Sophista in the house west of the summoning obelisk.",
                        chat = "1 Ask about 'While Guthix Sleeps'. / 4 Our friend in common places great faith in totems.",
                        npcs = { "Ivy Sophista" },
                    },
                    {
                        text = "Go upstairs and talk to Thaerisk Cemphier. Kill both assassins that appear.",
                        npcs = { "Thaerisk Cemphier", "Assassin (While Guthix Sleeps)" },
                    },
                    {
                        text = "Talk to Thaerisk again.",
                        chat = "1 What efforts are you making against Lucien? / 2 What are our options? / 2 I know about the 'Fist of Guthix'. / 3 What do you need me to do? / 4 Okay, thanks.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Reldo in Varrock Palace library and \"Talk about Lucien and Movario\"",
                        chat = "? Talk about Lucien and Movario. / 1 What can you tell me about Movario? / 2 What does Movario do? / 3 Where does Movario live? / 4 Okay, thanks.",
                        npcs = { "Reldo", "Varrock Palace" },
                        subs = {
                            { text = "If Desperate Times is completed, you need to choose one more chat option before proceed the aforementioned quest dialogue.", chat = "2 [Talk to Reldo.]" },
                        },
                    },
                },
            },
            {
                title = "Finding Movario's base", needed = { "Logs of any type, ring of charos (a) or 5,000 coins, one of each of the following runes: air, mind, water, earth, fire (bring more in case of failure), mort myre fungus (can be obtained during quest), at least 6 free backpack spaces, but more is preferable" },
                steps = {
                },
            },
            {
                title = "Feldip Hunter area", needed = {},
                steps = {
                    {
                        text = "Talk to the Hunting expert in Feldip Hunter area and ask about tracking down a person. She is north of Oo'glog lodestone, or south-west of fairy ring AKS. After the conversation she will give you a mort myre fungus.",
                        chat = "? A creature to help track down a person. / 2 How can I catch a wild broav? / 3 What do I do once I've caught a broav? / 4 Okay, thanks.",
                        npcs = { "Hunting expert", "Feldip Hunter area", "Oo'glog lodestone" },
                    },
                    {
                        text = "Go west and trap pit (which builds a pitfall trap) at the square trap pit (uses one set of logs), then use your mort myre fungus on the built trap.",
                        npcs = {},
                    },
                    {
                        text = "Dismantle the collapsed trap to obtain an unconscious broav.",
                        npcs = { "unconscious broav" },
                    },
                    {
                        text = "Talk to the Hunting expert again about tracking a person.",
                        chat = "? A creature to help track down a person.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Khazard", needed = {},
                steps = {
                    {
                        text = "Head to the west of Fight Arena and into the laundry room two houses north of the pub. (Kandarin monastery Teleport then run south, or Watchtower Teleport and run north, or use the Fairy ring code DJP and run south are quick ways to get there.)",
                        npcs = { "Fight Arena (location)", "Fight Arena Bar", "Kandarin monastery Teleport", "Watchtower Teleport" },
                    },
                    {
                        text = "With your ring of charos (a) equipped, talk to the Khazard launderer to obtain dirty laundry.",
                        chat = "2 Do you know someone called Movario? / 2 (Charm) Tell me all you know about Movario.",
                        npcs = { "ring of charos (a)", "Khazard launderer", "dirty laundry" },
                        tile = { x = 2564, y = 3172, plane = 0 },
                        subs = {
                            { text = "If you brought coins instead, take them out of your coin pouch and use them on the launderer.", chat = "2 No, I need information. Do you know someone called Movario? / 1 Offer five thousand coins for information on Movario." },
                        },
                    },
                    {
                        text = "Go to the Khazard Battleground north-west (north of Tree Gnome Village and across the bridges).",
                        npcs = { "Battlefield" },
                    },
                    {
                        text = "Climb-over the crumbled wall inside the north-westernmost building.",
                        npcs = {},
                    },
                    {
                        text = "Drop your Broav in the room with the broken table then use the dirty laundry on him.",
                        npcs = {},
                    },
                    {
                        text = "Search the broken table to reveal a trapdoor, then go down.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Old battered door", needed = {},
                steps = {
                    {
                        text = "Pick-up your Broav.",
                        npcs = {},
                    },
                    {
                        text = "Go through the door, and follow the path to the north, then climb-down the stairs.",
                        npcs = {},
                    },
                    {
                        text = "Search the old battered door and find the correct rune to use on it. After you enter the correct rune, you'll hear a click.",
                        npcs = {},
                    },
                    {
                        text = "Search the door again (boost your Thieving level if needed), and you will find a trap to disarm.",
                        chat = "1 Yes, I'm an awesome thief, I'll disable it easily!",
                        npcs = {},
                    },
                    {
                        text = "Go through the old battered door.",
                        npcs = {},
                        subs = {
                            { text = "| (O)" },
                            { text = "| (H)" },
                            { text = "| (E)" },
                            { text = "| (E)" },
                            { text = "| (D)" },
                        },
                    },
                },
            },
            {
                title = "Inside Movario's base", needed = {},
                steps = {
                    {
                        text = "Search the painting on the east wall.",
                        npcs = {},
                    },
                    {
                        text = "Choose the Search option on the bookcases until you receive the chat response.",
                        npcs = {},
                    },
                    {
                        text = "Follow the wire that faintly glows to the next bookshelf. (for those with colourblindness, zoom the camera in to see the wire slightly pulsate)",
                        npcs = {},
                        subs = {
                            { text = "Search that bookshelf." },
                            { text = "Repeat, searching each bookshelf until the electricity on the gate disappears." },
                        },
                    },
                    {
                        text = "Open the gate and search the spiral staircase to disarm the trap, then climb-up.",
                        npcs = {},
                    },
                    {
                        text = "Search the desk to obtain Movario's notes (volume 1)",
                        npcs = { "Desk (Movario's base)", "Movario's notes (volume 1)" },
                        subs = {
                            { text = "Read the notes." },
                        },
                    },
                    {
                        text = "Pick-up the waste-paper basket.",
                        npcs = { "waste-paper basket" },
                        subs = {
                            { text = "With Movario's notes in your backpack, search the basket." },
                        },
                    },
                    {
                        text = "Search the bookcase to the west of the waste-paper basket.",
                        npcs = {},
                        subs = {
                            { text = "Use the ruby key on the bookcase." },
                            { text = "Climb-up the stairs just north of you." },
                        },
                    },
                    {
                        text = "Search the bed.",
                        npcs = {},
                        subs = {
                            { text = "Use the ruby key on the bed chest." },
                            { text = "Search the bed chest to disarm the traps You may need to attempt again until you disarm the trap." },
                            { text = "Use the ruby key on the chest. Open and search the chest to obtain a strange key loop, strange key teeth, and Movario's notes (volume 2). Read these notes too." },
                        },
                    },
                    {
                        text = "Climb back down twice to the wire room and cross-over the broken wall, then search the drawers.",
                        npcs = {},
                    },
                    {
                        text = "Look-at the thermometer. Note down the number it says. Check your current character's weight in your equipment interface. You must equalise both numbers. If you weigh more than the number: subtract the number from the thermometer from your character's weight to get the result number. For example: if the thermometer says 20 and you weigh 30, you would need 10. If you weigh less than the number: subtract your character's weight from the number from to get the result number.",
                        npcs = {},
                        subs = {
                            { text = "Pick up your Broav if you haven't already, otherwise it will mess with the numbers." },
                        },
                    },
                    {
                        text = "On the floor of this room is a Pile of weights. Take weights equalling the result number you got. If you have been following the guide, you will need to take two 2kg weights, as Movario's notes and the key parts weigh 4kg collectively. CAUTION: You will not be able to recover any items dropped in this room.",
                        npcs = {},
                    },
                    {
                        text = "Climb back up the spiral staircase. If you weigh more than the number: use all the weights on the statue just north of you, then open the door just east. If you weigh less than the number: keep the weights in your inventory and open the door east of the statue.",
                        npcs = {},
                    },
                    {
                        text = "Head east through the door and up the ladder to leave the hideout.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Catching Lucien's spy", needed = { "Strange key loop, Strange key teeth, Movario's notes (volume 1) and Movario's notes (volume 2), equipment to kill two mercenary axemen and a mercenary mage" },
                steps = {
                    {
                        text = "Return to Thaerisk Cemphier in Taverley with the items obtained in Movario's base.",
                        chat = "2 What should I do now? / 5 Sorry, I have to go.",
                        npcs = { "Thaerisk Cemphier", "Taverley" },
                    },
                    {
                        text = "Head to the building in McGrubor's Wood (Seers' Village lodestone or fairy ring ALS), and a cutscene will start. Kill all the mercenaries.",
                        npcs = { "McGrubor's Wood", "Seers' Village lodestone" },
                    },
                    {
                        text = "Search the dead mercenaries and talk to the wounded Guardian of Armadyl.",
                        npcs = {},
                    },
                    {
                        text = "Go upstairs in the Seers' Village pub and talk to Idria.",
                        chat = "1 Do you know where Lucien is? / 3 How can I get to Lucien?",
                        npcs = { "Idria" },
                    },
                    {
                        text = "Talk to Sir Tiffy Cashien in the Falador Park. or if the Slug Menace hasn't been completed.",
                        chat = "1 While Guthix Sleeps. / 2",
                        npcs = { "Sir Tiffy Cashien", "Falador Park", "the Slug Menace" },
                    },
                    {
                        text = "Go to the White Knights' Castle.",
                        npcs = { "White Knights' Castle" },
                    },
                    {
                        text = "In the eastern room on the 1st floor, talk to Akrisae.",
                        chat = "3 How can I get to Draynor? / 1 Yes, please!",
                        npcs = { "Akrisae" },
                    },
                    {
                        text = "At Draynor Village, use the teleorb on the shady stranger wearing white robes and near the shore. This may take several attempts.",
                        npcs = { "Teleorb (While Guthix Sleeps)", "shady stranger" },
                    },
                    {
                        text = "Talk to Akrisae in the White Knight's Castle. Cutscene plays.",
                        npcs = {},
                    },
                    {
                        text = "If you don't have a snapdragon seed for the next step, buy one from Thaerisk.",
                        chat = "2 Could you help me get a snapdragon seed? / 1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Thaerisk to teleport to Port Sarim.",
                        chat = "3 Can you teleport me to Port Sarim, please?",
                        npcs = {},
                    },
                },
            },
            {
                title = "Super truth serum and recruiting the Heroes", needed = { "Lantern lens, snapdragon seed, 20 coins, 6 air runes, 3 cosmic runes, 3 astral runes, lunar spellbook" },
                steps = {
                    {
                        text = "Talk to Betty in the Port Sarim magic shop for truth serum and pink dye. (If The Hand In The Sand quest is completed )",
                        chat = "1 Talk to Betty about While Guthix Sleeps. / 1 Yes, please can I have a standard truth serum? / 1 Yes, please! / 2 Talk to Betty about While Guthix Sleeps. / 1 Yes, please can I have a standard truth serum? / 1 Yes, please!",
                        npcs = { "Betty", "truth serum" },
                    },
                    {
                        text = "If the snapdragon seed isn't already on the counter, talk to her again until she places the seed on the counter.",
                        npcs = {},
                    },
                    {
                        text = "Use the pink dye on your lantern lens.",
                        npcs = { "pink dye" },
                    },
                    {
                        text = "Stand just inside the doorway, use the lens with the counter and take the enriched snapdragon seed by searching the counter.",
                        npcs = {},
                    },
                    {
                        text = "If not already, switch to the Lunar spellbook.",
                        npcs = {},
                    },
                    {
                        text = "Using the most western staircase in White Knight Castle, head to the top of the castle and plant the seed in the herb patch.",
                        npcs = {},
                    },
                    {
                        text = "Go back downstairs and talk to Thaerisk on the ground floor of the eastern part of the castle.",
                        chat = "1 I've planted the enriched snapdragon seed.",
                        npcs = {},
                    },
                    {
                        text = "Cast NPC Contact to talk to the following people:",
                        npcs = { "NPC Contact" },
                        subs = {
                            { text = "Turael", chat = "1 I need to talk to you about Lucien." },
                            { text = "Duradel", chat = "1 I need to talk to you about Lucien." },
                            { text = "Mazchna", chat = "1 I need to talk to you about Lucien." },
                        },
                    },
                    {
                        text = "Talk to Hazelmere upstairs in the hut east of Yanille near fairy ring CLS.",
                        npcs = { "Hazelmere" },
                    },
                },
            },
            {
                title = "Questioning the spy", needed = { "Truth serum, 1 astral rune, 1 cosmic rune, and 2 air runes" },
                steps = {
                    {
                        text = "Pick the enriched snapdragon (top of west tower at White Knights' Castle) and mix it into your truth serum for a super truth serum.",
                        npcs = { "super truth serum" },
                    },
                    {
                        text = "Head back to the room with Thaerisk and the others.",
                        npcs = {},
                    },
                    {
                        text = "Open and search the drawers to find charcoal and papyrus.",
                        npcs = { "Drawers (charcoal and papyrus)", "charcoal", "papyrus" },
                    },
                    {
                        text = "Go into the cell and use the serum on the shady stranger. The correct chat option varies from player to player. Exhaust chat options until you reach the correct one so that the stranger drinks the serum.",
                        chat = "~",
                        npcs = { "shady stranger" },
                    },
                    {
                        text = "Talk to Idria (she is now in this same room).",
                        npcs = {},
                    },
                    {
                        text = "Cast NPC Contact to talk to Cyrisus.",
                        npcs = { "NPC Contact", "Cyrisus" },
                    },
                    {
                        text = "Head to the Warriors' Guild and talk to the following:",
                        npcs = { "Warriors' Guild" },
                        subs = {
                            { text = "Ghommal just outside" },
                            { text = "Harrallak Menarous in the main lobby" },
                            { text = "Sloane upstairs" },
                        },
                    },
                    {
                        text = "Return to the White Knights' Castle and speak to Idria, then Akrisae.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Into the Black Knights' Fortress", needed = { "Unpowered orb, runes for any charge Orb spell (3 cosmics and 30 runes of any element or any elemental staff), items to enter Black Knights' Fortress (Skull of Remembrance, bronze med helm/iron chainbody, black armour set or Black Knight captain's armour), equipment for two combat styles or Necromancy (Necromancy recommended)." },
                steps = {
                    {
                        text = "WARNING, BEFORE KILLING ANY ELITE BLACK KNIGHTS DISABLE AOE SPELLS, If you are doing this on a ironman killing two at once will cause a duplicate piece to drop. The only way around this is farm elite black knights to get the piece you will be missing.",
                        npcs = {},
                    },
                    {
                        text = "Switch back to the standard spellbook.",
                        npcs = {},
                    },
                    {
                        text = "You will need 11 free inventory slots to proceed.",
                        npcs = {},
                    },
                    {
                        text = "Equip your disguise and head inside Black Knights' Fortress with all the items above or use the skull of remembrance to teleport to the ritual chamber, and make your way down to the 1st floor.",
                        npcs = { "Black Knights' Fortress" },
                    },
                    {
                        text = "Climb down the ladder in the south-west corner.",
                        npcs = {},
                    },
                    {
                        text = "Along the east wall, right-click search the floor tile. Cast your charge orb spell on the floor tile.",
                        npcs = { "Tile (While Guthix Sleeps)" },
                    },
                    {
                        text = "Climb-down the trapdoor.",
                        npcs = {},
                    },
                    {
                        text = "Kill Elite Black Knights to obtain a helmet, platebody and platelegs if you don't have a set already. The three pieces of armour are guaranteed to drop until 3 pieces are received. Do not use multi-target abilities as killing two Elite Black Knights at once will cause them both to drop the same piece, with both counting toward the first 3 pieces received. Equip the full set to remove their aggression.",
                        npcs = { "Elite Black Knight" },
                    },
                    {
                        text = "Head north by jumping across the broken bridge, go east, and climb up the wall.",
                        npcs = {},
                    },
                    {
                        text = "Jump over the barricade and walk north-west until you reach a fork in the path, then head east.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Silif in the northmost cell.",
                        chat = "1 Silif, it's me, [Name]. Are you okay? / 2 I want to get you out of here. Any suggestions? / 3 I'll be back to try to get you out.",
                        npcs = {},
                    },
                    {
                        text = "Go back west and enter the northern centre Solid black door.",
                        npcs = {},
                    },
                    {
                        text = "Search all desks and wardrobes in the room for:",
                        npcs = {},
                        subs = {
                            { text = "Another set of elite black armour" },
                            { text = "Full set of Dagon'hai robes" },
                            { text = "Restore potion (4) (Do not drink the restore potion)" },
                            { text = "Strange teleorb" },
                            { text = "Lobster (Do not eat the lobster)" },
                            { text = "If you accidentally eat the lobster, any kind of cooked food will work as well." },
                        },
                    },
                    {
                        text = "Right-click search the key rack on the northern wall (a few tiles east of the wardrobe) for a Cell key.",
                        npcs = { "Cell key" },
                    },
                    {
                        text = "Enter Silif's cell. Use the piece of food on Silif, then the potion.",
                        chat = "2 Do you have a plan?",
                        npcs = {},
                    },
                    {
                        text = "Give Silif a set of elite black armour (dismiss your familiar if you have one).",
                        npcs = {},
                    },
                    {
                        text = "Return to the northern room. Walk to the map board on the southern wall then talk to Silif.",
                        npcs = {},
                    },
                    {
                        text = "Plant the teleorb on Dark Squall, who is located in the east of the room, then escape back to Falador.",
                        npcs = { "Dark Squall" },
                    },
                },
            },
            {
                title = "Lucien's Army", needed = { "Strange teleorb, Dagon'hai robe armour, one law rune, one death rune" },
                steps = {
                    {
                        text = "Talk to Akrisae.",
                        chat = "1 What would this orb look like? / 2 How will I be able to get to Lucien's base? / 3 Okay, thanks.",
                        npcs = { "Akrisae" },
                    },
                    {
                        text = "Wear your Dagon'hai robes and enter the nearby jail cell.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the ladder in the north-eastern corner, stand in the stone circle in the middle of the room, and right-click activate the strange teleorb. (Note: Activation will fail if the required runes are in a pouch.)",
                        npcs = {},
                    },
                    {
                        text = "Follow the north-eastern path towards the chapel and climb-up the ice wall. There is a stick in the ice wall to indicate where to climb.",
                        npcs = { "Chaos Temple (hut)", "ice wall" },
                    },
                    {
                        text = "Jump-to the ledge on the chapel into the Wilderness.",
                        npcs = { "Ledge (Chaos Temple (hut))" },
                    },
                    {
                        text = "Walk east to activate a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Return to Falador after the cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Idria.",
                        npcs = {},
                        subs = {
                            { text = "If she won't talk about Movario and instead keeps saying to investigate Lucien's camp, then unfortunately the game glitched and you must go back and rewatch the cutscene. Remember to bring the strange teleorb, a law rune, and a death rune. A good indicator that the cutscene registered is to check for the \"You have unlocked a new music track: The Evil Within\" game message." },
                        },
                    },
                },
            },
            {
                title = "Into the chasm", needed = { "Sapphire lantern, Dagon'hai robe armour, equipment for two combat styles (or Necromancy) and some food (You can go back to get these at a later step), prayer points to use the Bloom ability (a sickle and pouch are provided) OR two druid pouch charges (neither needed if you have an ouroboros pouch). You also need enough free inventory space to unequip anything in your main hand and off hand, plus 6 additional free inventory slots" },
                steps = {
                    {
                        text = "Go to the Tears of Guthix cavern.",
                        npcs = { "Tears of Guthix cavern" },
                    },
                    {
                        text = "Equip your Dagon'hai robes and talk to Movario North.",
                        chat = "3 I am Surok, Lucien has sent me to check on your progress. / 1 I could go down to the bottom first, to make sure it's safe! / 3 I shall return.",
                        npcs = { "Movario" },
                    },
                    {
                        text = "With a sapphire lantern lit, right-click travel into cavern with a light creature.",
                        npcs = { "Sapphire lantern (lit)" },
                    },
                    {
                        text = "Search the northernmost skeleton for a silver sickle (b) and 6 druid pouch charges.",
                        npcs = { "silver sickle (b)", "druid pouch" },
                        subs = {
                            { text = "If you have an Ouroboros pouch or brought two druid pouch charges of your own, you can drop the silver sickle to save inventory space." },
                        },
                    },
                    {
                        text = "Search the rocks in the north-eastern corner. Then search on the brazier that appears, choosing the chisel option to receive a fire orb.",
                        chat = "1 Yes",
                        npcs = { "fire orb" },
                    },
                    {
                        text = "Repeat on the north-west rock for the earth orb.",
                        npcs = { "earth orb" },
                    },
                    {
                        text = "Repeat for the standing lit braziers for air and water orbs in the south-western and south-eastern corners.",
                        npcs = { "air orb", "water orb" },
                    },
                    {
                        text = "Head further south to reach three skull cavities on the southern wall. Examine each recessed block and use the respective orb on the block.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the wall twice and use the water orb on the recessed block.",
                        npcs = {},
                    },
                    {
                        text = "Jump down the same way you came up. For each of the three lower skulls, enter its nose cavity.",
                        npcs = {},
                        subs = {
                            { text = "Dismiss any followers and empty both your main and off-hand slots before entering the cavities." },
                        },
                    },
                    {
                        text = "Crawl along the tunnel in each cavity to its end. Examine the door there and insert the respective element key into the door lock. Crawl back through the tunnel and exit the skull.",
                        npcs = {},
                    },
                    {
                        text = "Climb up the walls to the upper skull. Use the fire key on the skull's recessed block, then search the stone cube in front of the skull.",
                        npcs = {},
                    },
                    {
                        text = "Climb-through the cave opening to enter the Guthixian temple.",
                        npcs = { "Guthixian temple" },
                    },
                },
            },
            {
                title = "Intended method", needed = {},
                steps = {
                    {
                        text = "You will now need at least two free backpack spaces, though more can make it quicker to proceed. Ensure that you have also deactivated any sign of the porter effects.",
                        npcs = {},
                    },
                    {
                        text = "There are eight statues in this temple. Each, when examined, will reveal what type of potion must be \"made\" at that statue.",
                        npcs = {},
                    },
                    {
                        text = "Use your druid pouches on the druid spirits. Each will drop required ingredients for the statues once - if these are lost (e.g. by dropping and letting them timeout), you will have to get replacements yourself. Grace of the elves will send items to the bank so unequip it or disable its porter functionality.",
                        npcs = { "druid spirit", "Grace of the elves" },
                    },
                    {
                        text = "Do not let your druid pouch empty completely or it disappears! You need 3 open inventory slots to add 3 flowers into the druid pouch.",
                        npcs = {},
                        subs = {
                            { text = "Use the Bloom spell on your silver sickle (b) while standing on or close to the dead vine to grow some vine flower to recharge your druid pouch." },
                        },
                    },
                    {
                        text = "Use the herbs and the secondary ingredients on the various statues referencing the table below. Not all keywords will be on statues.",
                        npcs = {},
                        subs = {
                            { text = "If you have an ouroboros pouch, you do not need to worry about the druid pouch losing charges. However, you must carry a druid pouch in the backpack to \"use\" it on the spirits, though it will never deplete." },
                            { text = "If you need to refill your druid pouch, right-click bloom with your silver sickle near dead vines to get flowers. These can be used to refill the druid pouch. If you received a mort myre fungus from the druids, use it with the correct statue or drop it for a moment before filling the druid pouch else you will lose it!" },
                        },
                    },
                    {
                        text = "Use the dolmens you receive from the statues on the Stone Table in the middle of the temple. It will open the huge door in front of it.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Required ingredients for the statue", needed = { "An alternative to using druid spirit drops to solve this puzzle is to make a list of all potions that need to be made (either by simply looking at or Examine-ing each statue), and teleport out to obtain the needed ingredients based on the table below. You do not need to save the druid spirits to continue. Using a Herb bag can help in finishing it with one trip." },
                steps = {
                },
            },
            {
                title = "The Stone of Jas", needed = {},
                steps = {
                    {
                        text = "Make whatever arrangements necessary to battle the level 117 Balance Elemental that can use all three combat styles, and lowers your combat stats (except for Necromancy). You can leave the area to get supplies, but always bring your lit sapphire lantern. Don't forget to bring at least two combat styles for the tormented demon fight, unless using Necromancy. The Balance Elemental drains combat stats during the fight, so be sure to bring at least one full super restore.",
                        npcs = {},
                    },
                    {
                        text = "Proceed down the corridor and enter a large chamber.",
                        npcs = {},
                    },
                    {
                        text = "Once ready, search the mysterious stone and kill the Balance Elemental that appears. See the strategy guide here.",
                        chat = "1 Yes, I need to investigate this, even if it kills me!",
                        npcs = { "Balance Elemental" },
                    },
                    {
                        text = "Search the mysterious stone again for a cutscene. Doing so boosts all your combat stats to level 255 except Prayer.",
                        npcs = {},
                    },
                    {
                        text = "Continue dialogue with Movario, then with Lucien.",
                        chat = "1 What are you going to do with the Stone of Jas? / 2 What is the Stone of Jas? / 3 You can't let Lucien get the Stone of Jas! / 4 What if someone should stand in your way? / 1 What are you going to do with the Stone of Jas? / 2 Why is the Stone of Jas so important to you? / 3 Do you really hope to follow in the footsteps of Zamorak?",
                        npcs = {},
                    },
                    {
                        text = "Kill the two Tormented demons, switching between your two combat styles.",
                        npcs = { "Tormented demon" },
                    },
                    {
                        text = "Talk to Idria to have her teleport you to Falador.",
                        chat = "1 Yes, a teleport out of here would be good.",
                        npcs = {},
                    },
                    {
                        text = "Continue dialogue with Idria in Falador.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                    {
                        text = "Optional: after using of all four of Idria's 100,000 exp boosts, talk to her again to view the \"Elsewhere...\" epilogue.",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "witch_s_house", name = "Witch's House", wiki = "Witch's House/Quick guide",
        required = { "Leather gloves (Can be obtained during the quest)", "Cheese (Can be obtained during the quest)" },
        recommended = { "Combat gear (Magic equipment and water spells work best) and food for low level players" },
        sections = {
            {
                title = "Getting started", needed = {},
                steps = {
                    {
                        text = "Talk to Harvey standing by the long garden just west of Falador, just west of the crumbling wall which requires level 5 Agility to cross.",
