                        npcs = { "Harvey" },
                        tile = { x = 2925, y = 3355, plane = 0 },
                    },
                },
            },
            {
                title = "Entering the house", needed = {},
                steps = {
                    {
                        text = "Go to the front door of the house.",
                        npcs = {},
