                    {
                        text = "Look under the northern potted plant for the house key and enter.",
                        npcs = { "Potted plant (Witch's House)", "house key" },
                    },
                    {
                        text = "Climb down the stairs into the basement.",
                        npcs = {},
                    },
                    {
                        text = "If you didn't bring leather gloves, search the nearby crates for a pair. You may have to search several times.",
                        npcs = {},
                    },
                    {
                        text = "While wearing leather gloves, enter the gate.",
                        npcs = {},
                    },
                    {
                        text = "Open and search the cupboard, straight ahead on the western wall for a magnet.",
                        npcs = { "Cupboard (Witch's House)", "Magnet (Witch's House)" },
                    },
                    {
                        text = "Go back up the stairs and grab the cheese off of the table.",
                        npcs = { "cheese" },
                    },
                    {
                        text = "Go to the room located on the south end of the house.",
                        npcs = {},
                    },
                    {
                        text = "Right-Click Use cheese on the mouse hole on the eastern wall. (If you accidentally eat it, it will respawn on the table.)",
                        npcs = {},
                    },
                    {
                        text = "Use the magnet on the mouse.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Retrieving the ball", needed = {},
                steps = {
                    {
                        text = "Exit the door and make your way to the fountain, being careful not to be seen by the witch.",
                        npcs = { "Fountain (Witch's House)" },
                        subs = {
                            { text = "Strategically walk behind the shrubs to hide, being sure to stand in the middle space of each shrub. Surge can be used; timing is key." },
