                    },
                    {
                        text = "Check fountain for a shed key.",
                        npcs = { "Shed key (Witch's House)" },
                    },
                    {
                        text = "Return east down the shrubs to the shed, being careful not to be caught by the witch, and open the door.",
                        npcs = {},
