                    },
                    {
                        text = "Return and talk to Harvey (getting caught teleports you outside, you'll keep the ball)",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Achievements", needed = {},
                steps = {
                    {
                        text = "Witch's House",
                        npcs = { "Witch's House (achievement)" },
                    },
                },
            },
        },
