    {
        key = "within_the_light", name = "Within the Light", wiki = "Within the Light/Quick guide",
        required = { "Two sets of mourner outfit (including the gas mask) – you will lose one set during the quest. The second set is easy to obtain during the quest.", "To enter the death altar, you will also need:", "A death talisman, death talisman staff, death tiara, omni-talisman, omni-talisman staff, omni-tiara or a properly fed wicked hood (a death talisman can be obtained during the quest)", "These items can also be obtained during the quest, but it's possible you already have them in the bank. If so, you will need to bring them with you:", "New key (may be stored on a steel key ring)", "Tarnished key", "Colour wheel", "Notes", "Crystal trinket" },
        recommended = { "Food and prayer potions", "Crystal teleport seed or Tirannwn quiver 1 to teleport to Lletya", "Dave's spellbook to quickly teleport to West Ardougne", "Weapon to defend against level 95 Shadows (100 life points)", "Some toad crunchies for the gnome" },
        sections = {
            {
                title = "Trouble in the temple", needed = { "Two sets of mourner outfit, new key, tarnished key, one backpack space" },
                steps = {
                    {
                        text = "Talk to Arianwyn in Lletya in the large building to the east.",
                        npcs = { "Arianwyn", "Lletya" },
                        subs = {
                            { text = "To get to Lletya easily, use a crystal teleport seed, a Tirannwn quiver 1, or pass through the forest from Tirannwn lodestone." },
                        },
                    },
                    {
                        text = "With your mourner gear equipped, enter the Mourner Headquarters in the north-east of West Ardougne and climb down the trapdoor.",
                        npcs = { "Mourner Headquarters", "West Ardougne", "Trapdoor (Mourner Tunnels)" },
                    },
                    {
                        text = "If you need the keys, search the Head Mourner's desk in the basement's south-east room for the tarnished key and new key.",
                        npcs = { "Desk (Head Mourner)", "tarnished key", "new key" },
                    },
                    {
                        text = "Enter the tunnels with the new key and run to the west to approach the Temple of Light.",
                        npcs = { "new key", "Temple of Light" },
                    },
                    {
                        text = "Remove your gas mask and chant-to the blank teleport crystal in your backpack, whilst standing east of the first slave on the square directly between the north and south crates.",
                        npcs = { "blank teleport crystal" },
                    },
                    {
                        text = "After the cutscene, return to the room next to the Head Mourner's office.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the gnome.",
                        chat = "1 Talk about Within the Light. / 2 Stay undercover.",
                        npcs = { "Gnome (Mourner Headquarters)" },
                        subs = {
                            { text = "Ensure the tarnished key is in your backpack or you will not be able to open the door to the gnome." },
                            { text = "Talk to Head Mourner if you want to honour your deal." },
                        },
                    },
                    {
                        text = "Optionally for the second set of mourner outfit, you can kill a mourner nearby.",
                        npcs = { "Mourner (Mourner Tunnels)" },
                    },
                    {
                        text = "Return to Lletya.",
                        npcs = {},
                    },
                    {
                        text = "Use a piece of mourner's outfit on Arianwyn.",
                        npcs = {},
                    },
                    {
                        text = "Use the enchanted crystal on Arianwyn.",
                        npcs = {},
                    },
                    {
                        text = "Bank for food to fend against shadows.",
                        npcs = { "Shadow (Temple of Light)" },
                    },
                    {
                        text = "Talk to Arianwyn and accept the teleport. Dismiss your pet or familiar if you have any.",
                        chat = "1 About those tasks I need to do... / 1 I'm ready, let's go.",
                        npcs = {},
                        subs = {
                            { text = "Make sure to have a second set of mourner gear to hand in, if not done earlier, talk to him again once he is dressed." },
                        },
                    },
                },
            },
            {
                title = "The death altar", needed = { "Crystal trinket, Death talisman" },
                steps = {
                    {
                        text = "Proceed to Thorgel in the temple. Do not teleport out of the room to the death altar until rotating the red beam back the way it started, or else the light door will be locked on return.",
                        npcs = { "Thorgel" },
                        subs = {
                            { text = "Go up the stairs to the west, up the stairs to the south, down the stairs in the centre, down again, and through the light door. Rotate the red beam west and go through another light door." },
                            { text = "Do not use death altar teleport at this point unless you are absolutely certain the light beam is situated to let you out of the altar room." },
                        },
                    },
                    {
                        text = "Talk to Thorgel near the death ruins.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Arianwyn.",
                        npcs = {},
                    },
                    {
                        text = "Investigate the energised pillar (east multi-coloured 4-beam pillar).",
                        npcs = {},
                    },
                    {
                        text = "Talk to Arianwyn.",
                        npcs = {},
                    },
                    {
                        text = "(Epilepsy warning about 2s duration) Use the crystal trinket on the energised pillar.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Arianwyn.",
                        npcs = {},
                        subs = {
                            { text = "Speak to Arianwyn again if you need a death talisman." },
                        },
                    },
                    {
                        text = "Enter the death ruins.",
                        npcs = {},
                    },
                    {
                        text = "Remember the following steps and do them quickly, or you'll have to try again:",
                        npcs = {},
                        subs = {
                            { text = "Talk to Thorgel to become energised.", chat = "1 Within the Light. / 2 Okay, let's do this." },
                            { text = "He is south of the altar, and does not appear as a yellow dot on the minimap." },
                            { text = "Exit the altar." },
                            { text = "Pass the door of light." },
                            { text = "Rotate the first pillar of light mirror by the stairs." },
                            { text = "Go up the first stairs and immediately take the stairs to your left (north)." },
                            { text = "Run all the way east then south to the large crystal and investigate it. (If it speaks, you were not fast enough and have to go back to Thorgel.)" },
                            { text = "Run back down the stairs and touch the energised pillar. (If you don't get transported, you were not fast enough.)" },
                        },
                    },
                },
            },
            {
                title = "Within the light itself", needed = {},
                steps = {
                    {
                        text = "Once inside, search the dead slave on the ground.",
                        npcs = { "dead slave" },
                    },
                    {
                        text = "Chop, then fix the eastern crystal tree with the blue light beam.",
                        npcs = { "Crystal tree (Within the Light)" },
                    },
                    {
                        text = "Solve the puzzles by reflecting the light beams to the opposite coloured receivers. You only have one receiver available at a time.",
                        npcs = {},
                    },
                    {
                        text = ": For example: if the receiver in the end is yellow and since the opposite of yellow is blue (refer to the colour wheel), you need to direct the blue light beam to the yellow receiver. Due to how mirrors reflect, you often have to reroute, just keep trying different paths for the quickest solution.",
                        npcs = {},
                    },
                    {
                        text = ": Refer to the in-depth guide if you cannot figure it out.",
                        npcs = { "Within the Light" },
                        subs = {
                            { text = "Redirect the blue light to the yellow receiver. This enables the red light." },
                            { text = "Redirect a combination of red and blue light to the green receiver. This enables the green light." },
                            { text = "Redirect a combination of blue and green light to the red receiver." },
                            { text = "Redirect all three colours to the colourless receiver. When done all receivers on the western wall will be white. See below for example solutions." },
                        },
                    },
                    {
                        text = "Exit using the ladder in the south-east (not the portal).",
                        npcs = {},
                        subs = {
                            { text = "Yellow receiver" },
                            { text = "Green receiver" },
                            { text = "Red receiver" },
                            { text = "Colourless receiver" },
                        },
                    },
                },
            },
            {
                title = "Sharpshooter", needed = {},
                steps = {
                    {
                        text = "Reach the platform with the ballista by jumping between the platform and trying to avoid the spikes in the floor.",
                        npcs = {},
                    },
                    {
                        text = "Shoot it at the right time to hit the target.",
                        npcs = {},
                    },
                },
            },
            {
                title = "The passage to Prifddinas", needed = {},
                steps = {
                    {
                        text = "Go back the way you came and jump to the ladder.",
                        npcs = {},
                    },
                    {
                        text = "Go-through the large stone door on the west wall.",
                        npcs = {},
                    },
                    {
                        text = "Search the Elf messenger.",
                        npcs = {},
                    },
                    {
                        text = "Read the report.",
                        npcs = {},
                    },
                    {
                        text = "Important: Before you leave the temple, rotate the mirror of the red beam back to the east, so that when you return to the Temple again, you will be able to access the Death Altar room.",
                        npcs = {},
                    },
                    {
                        text = "Now is your last chance to inquire about saving the Gnome, if you intend to (it's completely optional).",
                        npcs = {},
                    },
                    {
                        text = "Return to Arianwyn in Lletya and give him the report.",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
            {
                title = "Required for completing", needed = { "pt:Luz Interior/Guia rápido" },
                steps = {
                },
            },
        },
    },
