    {
        key = "you_are_it", name = "You Are It", wiki = "You Are It/Quick guide",
        required = { "Rope" },
        recommended = { "Activated Draynor, Lumbridge, Port Sarim, Seer's Village and Varrock lodestone, or teleport runes" },
        sections = {
            {
                title = "Starting out", needed = {},
                steps = {
                    {
                        text = "Teleport to Seers' Village and run north-west to McGrubor's Wood (fairy ring ).",
                        npcs = { "Seers' Village", "McGrubor's Wood" },
                    },
                    {
                        text = "Enter the woods through the Loose railing.",
                        npcs = { "Loose Railing (McGrubor's Wood)" },
                    },
                    {
                        text = "Attempt to chop the tree 14 paces west and 6 paces south of the crate. (Slightly different colour, and near the quest marker on the minimap)",
                        npcs = {},
                    },
                    {
                        text = "Read the mysterious clue scroll.",
                        chat = "Accept",
                        npcs = { "Mysterious clue scroll (You Are It)" },
                    },
                    {
                        text = "Talk to Reldo in the library of Varrock Palace.",
                        npcs = { "Reldo", "Varrock Palace" },
                    },
                    {
                        text = "Read the mysterious clue scroll again.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Treasure trail", needed = {},
                steps = {
                    {
                        text = "Stand in the room with Duke Horacio on the 2nd floor of Lumbridge Castle.",
                        npcs = { "Duke Horacio", "Lumbridge Castle" },
                    },
                    {
                        text = "Remove all worn items, then perform the Cry and Panic emotes (in that order). You should see a cutscene if it works.",
                        npcs = { "Cry", "Panic" },
                    },
                    {
                        text = "Go to Lumbridge cemetery. Using the mysterious clue's dig option, dig one square to the north of the largest tombstone along the southern fence. You will get a locked casket. You must complete the cutscene in order to continue.",
                        npcs = { "Lumbridge cemetery", "locked casket" },
                    },
                    {
                        text = "Enter the POH portal in Rimmington to trigger a cutscene.",
                        npcs = { "Portal (player-owned house)", "Rimmington" },
                    },
                    {
                        text = "Teleport to Draynor, run into the Draynor Manor, and head into the first door to the west after entering the building.",
                        npcs = { "Draynor", "Draynor Manor" },
                    },
                    {
                        text = "Search the bookcase in the north-western part of the room to find the casket key.",
                        npcs = { "casket key" },
                    },
                    {
                        text = "Open the locked casket to obtain an old necklace.",
                        npcs = { "locked casket", "old necklace" },
                    },
                },
            },
            {
                title = "Mysterious hole", needed = {},
                steps = {
                    {
                        text = "Take a rope, and go back into McGrubor's Wood. Enter the railing shortcut and stand two squares south of the crate (which is south of the building).",
                        npcs = {},
                    },
                    {
                        text = "Dig via the old necklace.",
                        npcs = {},
                    },
                    {
                        text = "Inspect and then descend into the Mysterious Hole.",
                        npcs = { "Mysterious Hole" },
                    },
                    {
                        text = "Follow the path to the end and investigate the coffin for a cutscene.",
                        npcs = {},
                    },
                    {
                        text = "Talk to the double agent.",
                        chat = "3 What happens next? / 4 I'm going to look around.",
                        npcs = {},
                    },
                    {
                        text = "Investigate the mantle to the east for a cutscene.",
                        chat = "6 The Stone / 1 Yes.",
                        npcs = {},
                    },
                    {
                        text = "Talk to Uri.",
                        npcs = { "Uri" },
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
    {
        key = "zogre_flesh_eaters", name = "Zogre Flesh Eaters", wiki = "Zogre Flesh Eaters/Quick guide",
        required = {},
        recommended = { "Level 40 Prayer for Protect from Ranged, preferably level 43 for Protect from Melee", "Level 20 Crafting for a better chance on making the correct portrait, the higher your crafting the better your chances.", "Level 8 Herblore for creation of Relicym's balm to unlock Uglug Nar's store", "A comp ogre bow (or can be learned how to create during the quest)", "Activated Yanille lodestone, ring of duelling with at least 4 charges, dramen/lunar staff for fairy ring access (if A Fairy Tale III - Battle at Ork's Rift hasn't been completed).", "Food and combat gear", "If killing Slash Bash with ranged, comp ogre bow and at least 50 mithril brutal arrows (or better)" },
        sections = {
            {
                title = "Starting out", needed = { "Around 10 free inventory spaces, combat equipment" },
                steps = {
                    {
                        text = "Talk to Grish in Jiggig, located a short run south of the Castle Wars.",
                        chat = "3 What are Zogres? / 4 Can I help in any way? / Accept",
                        npcs = { "Grish", "Jiggig" },
                    },
                    {
                        text = "Talk to the ogre guard (without the combat level, east).",
                        npcs = { "ogre guard" },
                    },
                    {
                        text = "Climb over the crushed barricade.",
                        npcs = { "crushed barricade" },
                    },
                    {
                        text = "Run east and down the stairs.",
                        npcs = { "Stairs (Jiggig Dungeon)" },
                    },
                    {
                        text = "Run as far north-west as you can, and search the skeleton, kill the zombie, and take his ruined backpack.",
                        npcs = { "Skeleton (Zogre Flesh Eaters)", "Zombie (Zogre Flesh Eaters)" },
                        subs = {
                            { text = "If you're in combat when trying to search the skeleton, the zombie will not spawn." },
                        },
                    },
                    {
                        text = "Open the ruined backpack. You will get a dragon inn tankard, a knife, and rotten food. Drop all except the dragon inn tankard.",
                        npcs = { "dragon inn tankard", "knife", "rotten food" },
                    },
                    {
                        text = "Search the broken lectern behind the skeleton.",
                        npcs = { "Broken Lecturn" },
                    },
                    {
                        text = "Read the torn page.",
                        npcs = { "torn page" },
                    },
                    {
                        text = "Search the nearby ogre coffin until you find a black prism.",
                        npcs = { "ogre coffin", "black prism" },
                    },
                },
            },
            {
                title = "Yanille", needed = {},
                steps = {
                    {
                        text = "Enter the Dragon Inn pub in Yanille.",
                        npcs = { "Dragon Inn", "Yanille" },
                    },
                    {
                        text = "Use the dragon inn tankard on the bartender.",
                        npcs = { "dragon inn tankard" },
                    },
                    {
                        text = "Talk to Zavistic Rarve on the 2nd floor of the Wizards' Guild. Ring the bell outside if you lack the requirements.",
                        chat = "1 What did you say I should do?",
                        npcs = { "Zavistic Rarve", "Wizards' Guild" },
                    },
                    {
                        text = "Enter the house just north of the guild, 2nd floor, talk to Sithik in bed.",
                        npcs = {},
                    },
                    {
                        text = "Search the drawers, the cupboard, and the wardrobe.",
                        npcs = {},
                    },
                    {
                        text = "Read the 3 books, use the papyrus on Sithik to make a portrait, then use the portrait on Sithik.",
                        npcs = {},
                    },
                    {
                        text = "Make sure that Sithik says that he appreciates \"honesty\" of the portrait or you will have to make another. If he says 'truth' you will have to try again. There is more papyrus in the drawers.",
                        npcs = {},
                    },
                    {
                        text = "Use the portrait on the bartender. He will return it as a Signed portrait.",
                        npcs = {},
                        subs = {
                            { text = "If he just says that he recognises Sithik without signing the portrait, it means that you forgot to show him the dragon inn tankard." },
                        },
                    },
                    {
                        text = "Talk to Zavistic Rarve. He will give you a strange potion.",
                        chat = "1 I'm here about the sicks...err Zogres. / 3 I have some items that I'd like you to look at.",
                        npcs = { "Zavistic Rarve", "strange potion" },
                        subs = {
                            { text = "You must have the three books, signed portrait, dragon inn tankard, torn page and black prism with you otherwise he will say you do not have enough evidence" },
                        },
                    },
                    {
                        text = "Use the strange potion on the cup of tea beside Sithik.",
                        npcs = { "strange potion" },
                    },
                    {
                        text = "Climb down the ladder, climb up the ladder, ask Sithik all the possible questions.",
                        chat = "1 How do I remove the effects of the spell from the area? / 2 How do I get rid of the undead ogres? / 3 How do I get rid of the disease? / 4 Sorry, I have to go.",
                        npcs = {},
                    },
                },
            },
            {
                title = "Final Battle", needed = {},
                steps = {
                    {
                        text = "Return to Grish at the quest start, he will give you a key.",
                        chat = "1 I found who's responsible for the Zogres being here.",
                        npcs = {},
                    },
                    {
                        text = "Talk to him again to be able to create a comp ogre bow and brutal arrows, which can be used to fight the upcoming boss.",
                        chat = "2 There must be an easier way to kill these zogres!",
                        npcs = { "comp ogre bow", "brutal arrows" },
                        subs = {
                            { text = "(Optional) Use a clean rogue's purse on a vial of water, and then add a clean snakeweed to create a relicym's balm. Use this on Uglug Nar next to Grish, and you unlock his shop Uglug's Stuffsies which sells the comp ogre bow. This will also complete the Brutal Stuffsies achievement." },
                            { text = "(Optional) Either buy brutal arrows from the Grand Exchange, or fletch them at this point; there are achey trees to the west of Grish, chop them down and fletch their logs into shafts, then attach feathers, and tip them with nails of your choosing." },
                        },
                    },
                    {
                        text = "Cross the barricade to the east and go down the stairs again.",
                        npcs = {},
                    },
                    {
                        text = "Once inside, run directly west, through the double doors and down more stairs.",
                        npcs = {},
                    },
                    {
                        text = "Go north-east and search the stand in front of the pile of skulls. Prepare for battle.",
                        npcs = {},
                    },
                    {
                        text = "Kill Slash Bash, pick up the Ogre artefact he drops.",
                        npcs = { "Slash Bash" },
                    },
                    {
                        text = "Return to Grish at quest start.",
                        chat = "1 Yeah, I have them here!",
                        npcs = {},
                    },
                    {
                        text = "Quest complete!",
                        npcs = {},
                    },
                },
            },
        },
    },
